if not r.ImGui_GetBuiltinPath then
    r.ShowMessageBox("ReaImGui extension is not installed.\nPlease install it via ReaPack.", "ReaImGui Error", 0)
    return
end

package.path = r.ImGui_GetBuiltinPath() .. '/?.lua'
local ok, imgui_module = pcall(require, 'imgui')
if not ok then return end
local ok2, imgui = pcall(imgui_module, '0.9')
if not ok2 then return end

local function GetImGuiEnum(name, default)
    local success, val = pcall(function() return imgui[name] end)
    if success and val ~= nil then return val end
    return default
end

