function CanonicalUserDataQueueCount(user_data)
    if not user_data then return 0 end
    local queue = user_data.queue or {}
    local head = user_data.queue_head or 1
    local tail = user_data.queue_tail or #queue
    return math.max(0, tail - head + 1)
end

