-- ============================================================
-- UTILITIES
-- ============================================================
function FileExists(path)
    if not path or path == "" then return false end
    if r.file_exists then return r.file_exists(path) == true end
    local f = io.open(path, "r")
    if f then f:close() return true end
    return false
end

RB_AUDIO_FILE_EXTENSIONS = {
    wav=true, wave=true, bwf=true, w64=true, rf64=true,
    aif=true, aiff=true, aifc=true, flac=true, mp3=true,
    ogg=true, oga=true, opus=true, wv=true, ape=true, tta=true,
    m4a=true, aac=true, ac3=true, dts=true, amr=true, caf=true,
    dsf=true, dff=true, rex=true, rx2=true,
    mp4=true, m4v=true, mov=true, avi=true, mkv=true, webm=true,
    mpg=true, mpeg=true, m2ts=true, mts=true, ["3gp"]=true,
}
RB_MEDIA_EXTENSION_SUPPORT_CACHE = {}
MAX_LIBRARY_SCAN_DEPTH = 64
MAX_MIDI_PREVIEW_FILE_BYTES = 64 * 1024 * 1024
MAX_MIDI_PREVIEW_TRACKS = 4096
MAX_MIDI_PREVIEW_EVENTS = 500000
MAX_MIDI_PARSE_CACHE_ENTRIES = 32
MAX_MIDI_PARSE_CACHE_BYTES = 24 * 1024 * 1024
MIDI_PARSE_CACHE_TTL_SECONDS = 30

function IsMacOSMetadataPath(path)
    local normalized = tostring(path or ""):gsub("\\", "/")
    local name = normalized:match("([^/]+)$") or normalized
    if name:sub(1, 2) == "._" then return true end
    for component in normalized:gmatch("[^/]+") do
        if component:lower() == "__macosx" then return true end
    end
    return false
end

function IsAudioFile(path)
    local ext = path:match("%.([^./\\]+)$")
    if not ext then return false end
    ext = ext:lower()
    if ext == "mid" or ext == "midi" then return false end
    local cached = RB_MEDIA_EXTENSION_SUPPORT_CACHE[ext]
    if cached ~= nil then return cached end
    local supported = RB_AUDIO_FILE_EXTENSIONS[ext] == true
    if type(r.IsMediaExtension) == "function" then
        -- Match Media Explorer's installed decoder set. Cache by extension so
        -- a ten-million-file scan crosses the Lua/API boundary only once per
        -- distinct suffix, not once per file.
        supported = r.IsMediaExtension(ext, false) and true or false
    end
    RB_MEDIA_EXTENSION_SUPPORT_CACHE[ext] = supported
    return supported
end

function IsBrowserMediaFile(path)
    return not IsMacOSMetadataPath(path)
        and (IsMidiFile(path) or IsAudioFile(path))
end

function GetFileSizeBytes(path)
    local file = io.open(path or "", "rb")
    if not file then return nil end
    local size = file:seek("end")
    file:close()
    return tonumber(size)
end

function IsMidiFile(path)
    local lower = tostring(path or ""):lower()
    return lower:sub(-4) == ".mid" or lower:sub(-5) == ".midi"
end
function GetFileName(path) 
    local clean_path = path:gsub("[/\\]+$", "")
    return clean_path:match("([^/\\]+)$") or clean_path 
end

function NormalizeFavoritePath(path)
    local normalized = (path or ""):gsub("\\", "/"):gsub("/+$", "")
    if REABROWSE_IS_WINDOWS then normalized = normalized:lower() end
    return normalized
end

local function AddRootFolderIfMissing(path)
    path = (path or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if path == "" then return false end
    local os_name = r.GetOS() or ""
    local valid_shape = os_name:match("^Win")
        and (path:match("^%a:[/\\]") ~= nil
            or path:match("^[/\\][/\\]") ~= nil)
        or (not os_name:match("^Win") and path:sub(1, 1) == "/")
    if not valid_shape or path:find("[\r\n]") then return false end
    local key = NormalizeFavoritePath(path)
    for _, existing in ipairs(state.root_folders) do
        if NormalizeFavoritePath(existing) == key then return false end
    end
    state.root_folders[#state.root_folders + 1] = path
    return true
end

function RemoveConfiguredRootValue(path)
    local key = NormalizeFavoritePath(path)
    local removed = false
    for index = #state.root_folders, 1, -1 do
        if NormalizeFavoritePath(state.root_folders[index]) == key then
            table.remove(state.root_folders, index)
            removed = true
        end
    end
    return removed
end

local function NormalizeTag(tag)
    return (tag or ""):lower()
        :gsub("[\t\r\n]", " ")
        :gsub("^%s+", "")
        :gsub("%s+$", "")
        :gsub("%s+", " ")
end

function NormalizeBrowserSearchTokens(value)
    return (tostring(value or ""):lower()
        :gsub("[%p%s]+", " "):match("^%s*(.-)%s*$"))
end

function BrowserSearchTokensMatch(normalized_text, normalized_query)
    if normalized_query == "" then return true end
    for term in normalized_query:gmatch("%S+") do
        if not normalized_text:find(term, 1, true) then return false end
    end
    return true
end

