    "soft", "clean", "dry", "wet", "cinematic",
}

-- These are broad navigation concepts, not permanent tags. They receive a
-- predictable leading position only when their count is non-zero in the
-- current result scope; all other available tags follow by usefulness.
TAG_BROAD_PRIORITY = {
    bass = 1, chord = 2, drums = 3, guitar = 4, keys = 5,
    melody = 6, percussion = 7, rhythm = 8, ["sound effect"] = 9,
    stem = 10, synth = 11, vocal = 12,
}
MEDIA_PRIORITY_TAGS = {
    ["drum loops"] = 1,
    ["melody loops"] = 2,
}
MEDIA_PRIORITY_TAG_LABELS = {
    ["drum loops"] = "Drum Loops",
    ["melody loops"] = "Melody Loops",
}
MEDIA_PRIORITY_TAG_STAR = utf8.char(0x2605)
MEDIA_PRIORITY_TAG_STAR_COLOR = 0xF2C94CFF
MEDIA_TAG_CATALOG_LIMIT = 256
-- Facets are navigation hints, not an exhaustive analytics report. Restrictive
-- scopes remain exact; broad scopes sample a bounded prefix so selecting
-- a common tag cannot make work grow linearly toward ten million files.
MEDIA_TAG_RELEVANCE_SAMPLE_LIMIT = 50000

local AutoTagSearchText, AutoTagTextMatches

function SortMediaTagCatalog(tags, selected_tags)
    selected_tags = selected_tags or {}
    table.sort(tags, function(a, b)
        local app = MEDIA_PRIORITY_TAGS[a.name]
        local bpp = MEDIA_PRIORITY_TAGS[b.name]
        if app or bpp then
            if not app then return false end
            if not bpp then return true end
            return app < bpp
        end
        local as = selected_tags[a.name] == true
        local bs = selected_tags[b.name] == true
        if as ~= bs then return as end
        local ap = TAG_BROAD_PRIORITY[a.name]
        local bp = TAG_BROAD_PRIORITY[b.name]
        if ap or bp then
            if not ap then return false end
            if not bp then return true end
            return ap < bp
        end
        local ac, bc = tonumber(a.count) or 0, tonumber(b.count) or 0
        if state.tag_sort_mode ~= "az" and ac ~= bc then return ac > bc end
        return a.name < b.name
    end)
    return tags
end

local function CollectPriorityLoopTags(
    entry, add_tag, generated_tags)
    if not entry or IsMidiFile(entry.path or entry.name) then return end
    local classification = entry.automatic_classification
    if not classification and type(ClassifyAutomaticMedia) == "function" then
        classification = select(1,
            ClassifyAutomaticMedia(entry.path, nil, true))
    end
    if classification ~= "loop" then return end
    local raw_path = tostring(entry.path or ""):lower():gsub("\\", "/")
    local filename = AutoTagSearchText(
        (entry.name or ""):gsub("%.[^%.]+$", ""))
    local detected_key_pc = entry.detected_key_pc
    if detected_key_pc == nil and type(DetectFileKeyPitchClass) == "function" then
        detected_key_pc = DetectFileKeyPitchClass(entry.path, nil)
    end
    local has_explicit_tempo = filename:match(" %d%d?%d? bpm ") ~= nil

    local drum_context = AutoTagTextMatches(filename, "drum loop")
        or raw_path:find("/drum loops/", 1, true)
        or raw_path:find("/drum_loops/", 1, true)
        or raw_path:find("/drumloops/", 1, true)
    local non_full_drum = raw_path:find("/stems/", 1, true)
        or raw_path:find("/stem/", 1, true)
        or raw_path:find("/loop stems/", 1, true)
        or raw_path:find("/loop_stems/", 1, true)
        or raw_path:find("/top loops/", 1, true)
        or raw_path:find("/top_loops/", 1, true)
        or raw_path:find("/drum loops no kick/", 1, true)
        or raw_path:find("/drum_loops_no_kick/", 1, true)
        or raw_path:find("/perc loops/", 1, true)
        or raw_path:find("/perc_loops/", 1, true)
        or raw_path:find("/percussion loops/", 1, true)
        or raw_path:find("/hi hat loops/", 1, true)
        or raw_path:find("/hi_hat_loops/", 1, true)
        or AutoTagTextMatches(filename, "no kick")
        or AutoTagTextMatches(filename, "top loop")
        or AutoTagTextMatches(filename, "percussion loop")
        or AutoTagTextMatches(filename, "perc loop")
        or AutoTagTextMatches(filename, "hi hat loop")
        or AutoTagTextMatches(filename, "hihat loop")
    if drum_context and not non_full_drum then
        add_tag("drum loops", "folder", 0.95)
    end

    local instrumental_context =
        AutoTagTextMatches(filename, "melody loop")
        or AutoTagTextMatches(filename, "song starter")
        or AutoTagTextMatches(filename, "composition")
        or AutoTagTextMatches(filename, "instrumental")
        or raw_path:find("/melody loops/", 1, true)
        or raw_path:find("/melody_loops/", 1, true)
        or raw_path:find("/compositions/", 1, true)
        or raw_path:find("/composition/", 1, true)
        or raw_path:find("/song starters/", 1, true)
        or raw_path:find("/song_starters/", 1, true)
        or raw_path:find("/instrumentals/", 1, true)
    local component_names = {
        "bass", "bassline", "guitar", "electric guitar", "acoustic guitar",
        "bass guitar", "piano", "keys", "organ", "synth", "vocal", "choir",
        "strings", "brass", "woodwind", "stem",
    }
    local component_lookup = {}
    for _, name in ipairs(component_names) do component_lookup[name] = true end
    local explicit_component_tag, explicit_drum_tag = false, false
    for _, tag in ipairs(generated_tags or {}) do
        if tag.source == "filename" then
            if component_lookup[tag.name] then explicit_component_tag = true end
            if tag.name == "drums" then explicit_drum_tag = true end
        end
    end
    local component_path = raw_path:find("/stems/", 1, true)
        or raw_path:find("/stem/", 1, true)
        or raw_path:find("/bass loops/", 1, true)
        or raw_path:find("/bass_loops/", 1, true)
        or raw_path:find("/guitar loops/", 1, true)
        or raw_path:find("/guitar_loops/", 1, true)
        or raw_path:find("/keys loops/", 1, true)
        or raw_path:find("/keys_loops/", 1, true)
        or raw_path:find("/piano loops/", 1, true)
        or raw_path:find("/piano_loops/", 1, true)
        or raw_path:find("/vocal loops/", 1, true)
        or raw_path:find("/vocal_loops/", 1, true)
    local unlabeled_musical_loop = has_explicit_tempo
        and detected_key_pc ~= nil
        and not explicit_component_tag
        and not explicit_drum_tag
    local explicit_vocal_phrase =
        AutoTagTextMatches(filename, "ad lib")
        or AutoTagTextMatches(filename, "ad libs")
        or AutoTagTextMatches(filename, "adlib")
        or AutoTagTextMatches(filename, "adlibs")
        or AutoTagTextMatches(filename, "sung phrase")
        or AutoTagTextMatches(filename, "sung phrases")
        or AutoTagTextMatches(filename, "vocal phrase")
        or AutoTagTextMatches(filename, "vocal phrases")
    if (instrumental_context or unlabeled_musical_loop)
        and not component_path and not drum_context
        and not explicit_component_tag and not explicit_vocal_phrase then
        add_tag("melody loops",
            instrumental_context and "folder" or "filename", 0.9)
    end
end

AutoTagSearchText = function(value)
    return " " .. (value or "")
        :gsub("([%l%d])([%u])", "%1 %2")
        :lower()
        :gsub("[^%w]+", " ")
        :gsub("%s+", " ")
        :gsub("^%s+", "")
        :gsub("%s+$", "") .. " "
end

local AUTO_TAG_ALIAS_CACHE = {}
AutoTagTextMatches = function(search_text, alias)
    -- Alias normalization is invariant. Cache it instead of rebuilding it for
    -- every rule, for every file, during every scan.
    local normalized = AUTO_TAG_ALIAS_CACHE[alias]
    if not normalized then
        normalized = AutoTagSearchText(alias)
        AUTO_TAG_ALIAS_CACHE[alias] = normalized
    end
    return search_text:find(normalized, 1, true) ~= nil
end

function GeneratedTagContextAllowed(tag, search_text)
    search_text = tostring(search_text or "")
    local padded_tag = " " .. tostring(tag or "") .. " "
    -- Explicit negative filenames such as "no_bass" must not generate the
    -- very tag they negate.
    if search_text:find(" no" .. padded_tag, 1, true)
        or search_text:find(" without" .. padded_tag, 1, true) then
        return false
    end
    if tag == "bass" then
        -- These phrases describe genres or a different drum instrument. They
        -- previously leaked an instrument-level bass tag onto every kick,
        -- riser and hat stored below the pack folder.
        if search_text:find(" future bass ", 1, true)
            or search_text:find(" drum and bass ", 1, true)
            or search_text:find(" drum bass ", 1, true)
            or search_text:find(" bass drum ", 1, true) then
            return false
        end
    end
    if tag == "drums" then
        -- Drum & bass is a genre label, not evidence that the file is a drum
        -- kit component. Keep the explicit genre tag without manufacturing a
        -- drum-family tag from the phrase itself.
        if search_text:find(" drum and bass ", 1, true)
            or search_text:find(" drum bass ", 1, true) then
            return false
        end
    end
    return true
end

local function CollectGeneratedTags(entry)
    local filename_text = AutoTagSearchText(
        (entry.name or ""):gsub("%.[^%.]+$", ""))
    local folder_parts = {}
    local parent = entry.parent
    -- Nearby folders are useful categories; distant pack/vendor ancestors
    -- tend to leak unrelated genre and instrument words onto every file.
    for _ = 1, 3 do
        if not parent then break end
        folder_parts[#folder_parts + 1] = parent.name or ""
        parent = parent.parent
    end
    local folder_text = AutoTagSearchText(table.concat(folder_parts, " "))
    local generated, seen = {}, {}

    local function AddGeneratedTag(name, source, confidence)
        name = NormalizeTag(name)
        if name == "" or seen[name] then return false end
        generated[#generated + 1] = {
            name = name,
            source = source,
            confidence = confidence or (source == "filename" and 0.9 or 0.75),
        }
        seen[name] = true
        return true
    end

    local function AddMatches(search_text, source, limit)
        for _, rule in ipairs(AUTO_TAG_RULES) do
            if #generated >= limit then return end
            local tag, aliases = rule[1], rule[2]
            -- Loop/one-shot/MIDI are database classifications, not tags.
            -- Keeping them out of generated tags prevents a second category
            -- system from competing with files.classification.
            if tag ~= "loop" and tag ~= "one-shot" and tag ~= "midi"
                and GeneratedTagContextAllowed(tag, search_text)
                and not seen[tag] then
                for _, alias in ipairs(aliases) do
                    if AutoTagTextMatches(search_text, alias) then
                        AddGeneratedTag(tag, source)
                        break
                    end
                end
            end
        end
    end

    AddMatches(filename_text, "filename", 8)
    AddMatches(folder_text, "folder", 12)
    CollectPriorityLoopTags(entry, AddGeneratedTag, generated)

    -- Add only semantic parents that are unambiguous enough to be useful as
    -- filters. The child tag's evidence source is retained so the existing
    -- filename/folder automatic-tag lifecycle replaces these entries during
    -- a glossary migration without touching user tags.
    local source_by_tag = {}
    for _, tag in ipairs(generated) do
        source_by_tag[tag.name] = tag.source
    end
    local index = 1
    while index <= #generated do
        local child = generated[index]
        local parents = AUTO_TAG_IMPLIED_PARENTS[child.name]
        if parents then
            for _, parent_name in ipairs(parents) do
                local parent_source = child.source
                    or source_by_tag[child.name] or "filename"
                if AddGeneratedTag(parent_name, parent_source) then
                    source_by_tag[parent_name] = parent_source
                end
            end
        end
        index = index + 1
    end

    -- In sample-library organization an unqualified 808 belongs with drums,
    -- while an explicitly labelled "808 bass" remains bass. Specific filename
    -- evidence outranks a generic nearby Bass or Drumkit folder.
    if seen["808"] then
        local drum_context_aliases = {
            "kick", "kicks", "snare", "snares", "hi hat", "hihat",
            "hh", "open hat", "open hihat", "closed hat", "closed hihat",
            "cymbal", "cymbals", "crash", "ride", "tom", "toms",
            "rimshot", "rim shot", "drum", "drums", "drum kit",
            "drumkit", "drum sample", "drum samples",
        }
        local filename_has_drum_context = false
        local folder_has_drum_context = false
        for _, alias in ipairs(drum_context_aliases) do
            filename_has_drum_context = filename_has_drum_context
                or AutoTagTextMatches(filename_text, alias)
            folder_has_drum_context = folder_has_drum_context
                or AutoTagTextMatches(folder_text, alias)
        end
        local filename_has_bass_context =
            AutoTagTextMatches(filename_text, "bass")
        local folder_has_bass_context =
            AutoTagTextMatches(folder_text, "bass")
        local classify_as_drums
        if filename_has_bass_context and not filename_has_drum_context then
            classify_as_drums = false
        elseif filename_has_drum_context then
            classify_as_drums = true
        elseif folder_has_bass_context and not folder_has_drum_context then
            classify_as_drums = false
        else
            classify_as_drums = true
        end
        if classify_as_drums then
            AddGeneratedTag("drums", source_by_tag["808"] or "filename")
        end
    end

    -- Drums and auxiliary percussion are sibling browsing groups. Specific
    -- piece evidence outranks a generic nearby kit/folder label so a cowbell
    -- inside a folder named Drumkit does not inherit Drums, and a kick inside
    -- a broadly named Percussion folder does not inherit Percussion. When
    -- equally specific evidence for both families exists, retain both.
    local drum_piece_strength = 0
    for _, name in ipairs({
        "kick", "snare", "clap", "snap", "hi-hat", "cymbal", "tom",
        "rimshot",
    }) do
        if seen[name] then
            drum_piece_strength = math.max(drum_piece_strength,
                source_by_tag[name] == "filename" and 2 or 1)
        end
    end
    if seen["808"] and seen["drums"] then
        drum_piece_strength = math.max(drum_piece_strength,
            source_by_tag["808"] == "filename" and 2 or 1)
    end
    local percussion_piece_strength = 0
    for _, name in ipairs({
        "cowbell", "shaker", "tambourine", "conga", "bongo",
    }) do
        if seen[name] then
            percussion_piece_strength = math.max(
                percussion_piece_strength,
                source_by_tag[name] == "filename" and 2 or 1)
        end
    end
    local remove_family
    if drum_piece_strength > percussion_piece_strength
        and drum_piece_strength > 0 then
        remove_family = "percussion"
    elseif percussion_piece_strength > drum_piece_strength
        and percussion_piece_strength > 0 then
        remove_family = "drums"
    end
    if remove_family and seen[remove_family] then
        for tag_index = #generated, 1, -1 do
            if generated[tag_index].name == remove_family then
                table.remove(generated, tag_index)
            end
        end
        seen[remove_family] = nil
    end
    return generated
end

local function EnsureGeneratedTags(entry)
    if entry and entry.generated_tags == nil then
        entry.generated_tags = CollectGeneratedTags(entry)
    end
    if not entry then return {} end
    local excluded = GetMediaExcludedTags and GetMediaExcludedTags(entry.path) or nil
    if not excluded or #excluded == 0 then return entry.generated_tags or {} end
    local blocked, visible = {}, {}
    for _, tag in ipairs(excluded) do blocked[tag] = true end
    for _, generated in ipairs(entry.generated_tags or {}) do
        if not blocked[generated.name] then
            visible[#visible + 1] = generated
        end
    end
    return visible
end

function LoadMediaUserTags()
    state.media_user_tags = {}
    state.media_tags_file_present = false
    state.media_tag_generation = state.media_tag_generation + 1
    return true
end

function SaveMediaUserTags()
    -- Manual tags are stored in file_tags/file_tag_exclusions.  Keep this
    -- compatibility entry point so older call sites do not recreate a TSV.
    return true
end

function LoadCanonicalMediaUserTagsForPath(path)
    local key = NormalizeFavoritePath(path)
    if key == "" or not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath()) then
        return nil
    end
    local cached = state.media_user_tags[key]
    if cached then return cached end
    local sql = "SELECT COALESCE((SELECT group_concat(hex(tags.name),'|') FROM "
        .. "file_tags JOIN tags ON tags.id=file_tags.tag_id JOIN files ON files.id="
        .. "file_tags.file_id WHERE files.canonical_path_norm=" .. SQLQuote(key)
        .. " AND file_tags.source='user'),'')||char(9)||COALESCE((SELECT "
        .. "group_concat(hex(file_tag_exclusions.tag_norm),'|') FROM "
        .. "file_tag_exclusions JOIN files ON files.id=file_tag_exclusions.file_id "
        .. "WHERE files.canonical_path_norm=" .. SQLQuote(key) .. "),'');"
    local output = QueryDatabaseScalarAtPath(GetCanonicalDatabasePath(), sql)
    local tags_text, excluded_text = tostring(output or ""):match("^([^\t]*)\t(.*)$")
    local tags, excluded = {}, {}
    for value in (tags_text or ""):gmatch("[^|]+") do
        local tag = NormalizeTag(DecodeSQLHex(value))
        if tag ~= "" then tags[#tags + 1] = tag end
    end
    for value in (excluded_text or ""):gmatch("[^|]+") do
        local tag = NormalizeTag(DecodeSQLHex(value))
        if tag ~= "" then excluded[#excluded + 1] = tag end
    end
    cached = {path = path, tags = tags, excluded = excluded, _sql_loaded = true}
    state.media_user_tags[key] = cached
    return cached
end

function GetMediaUserTags(path)
    local key = NormalizeFavoritePath(path)
    local entry = state.media_user_tags[key]
        or LoadCanonicalMediaUserTagsForPath(path)
    return entry and entry.tags or nil
end

function GetMediaExcludedTags(path)
    local key = NormalizeFavoritePath(path)
    local entry = state.media_user_tags[key]
        or LoadCanonicalMediaUserTagsForPath(path)
    return entry and entry.excluded or nil
end

function LoadCanonicalDetectedTagsForPath(path)
    if not path or path == "" or not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath()) then
        return nil
    end
    local path_norm = NormalizeFavoritePath(path)
    local sql = "SELECT hex(tags.name) FROM files JOIN file_tags ON "
        .. "file_tags.file_id=files.id JOIN tags ON tags.id=file_tags.tag_id "
        .. "WHERE files.canonical_path_norm=" .. SQLQuote(path_norm)
        .. " AND file_tags.source IN('filename','folder') AND NOT EXISTS("
        .. "SELECT 1 FROM file_tag_exclusions WHERE "
        .. "file_tag_exclusions.file_id=files.id AND "
        .. "file_tag_exclusions.tag_norm=tags.name_norm) "
        .. "GROUP BY tags.id ORDER BY tags.name_norm;"
    local output = QueryDatabaseScalarAtPath(GetCanonicalDatabasePath(), sql)
    if output == nil then return nil end
    local detected, seen = {}, {}
    for value in tostring(output):gmatch("[^\r\n]+") do
        local name = NormalizeTag(DecodeSQLHex(value))
        if name ~= "" and not TAG_BAR_EXCLUDED[name] and not seen[name] then
            seen[name] = true
            detected[#detected + 1] = name
        end
    end
    return detected
end

-- Load all tag-editor state for a bounded multi-selection in one SQLite read.
-- Opening the editor previously issued several synchronous queries per file,
-- which could stall REAPER for seconds near the 600-row selection ceiling.
function BuildCanonicalTagEditorSQL(paths)
    local values, seen = {}, {}
    for _, path in ipairs(paths or {}) do
        local path_norm = NormalizeFavoritePath(path)
        if path_norm ~= "" and not seen[path_norm] then
            seen[path_norm] = true
            values[#values + 1] = "(" .. SQLQuote(path_norm) .. ")"
        end
    end
    if #values == 0 then return nil end
    local selected = "WITH selected(path_norm) AS (VALUES "
        .. table.concat(values, ",") .. ") "
    local row_expr = "hex(files.canonical_path_norm)||char(9)||"
    return selected
        .. "SELECT " .. row_expr .. "'U'||char(9)||hex(tags.name) "
        .. "FROM selected CROSS JOIN files ON files.canonical_path_norm="
        .. "selected.path_norm CROSS JOIN file_tags ON file_tags.file_id=files.id "
        .. "CROSS JOIN tags ON tags.id=file_tags.tag_id "
        .. "WHERE file_tags.source='user' UNION ALL "
        .. "SELECT " .. row_expr .. "'D'||char(9)||hex(tags.name) "
        .. "FROM selected CROSS JOIN files ON files.canonical_path_norm="
        .. "selected.path_norm CROSS JOIN file_tags ON file_tags.file_id=files.id "
        .. "CROSS JOIN tags ON tags.id=file_tags.tag_id "
        .. "WHERE file_tags.source IN('filename','folder') AND NOT EXISTS("
        .. "SELECT 1 FROM file_tag_exclusions excluded WHERE "
        .. "excluded.file_id=files.id AND excluded.tag_norm=tags.name_norm) "
        .. "UNION ALL SELECT " .. row_expr
        .. "'X'||char(9)||hex(exclusions.tag_norm) "
        .. "FROM selected CROSS JOIN files ON files.canonical_path_norm="
        .. "selected.path_norm CROSS JOIN file_tag_exclusions exclusions ON "
        .. "exclusions.file_id=files.id;"
end

function ParseCanonicalTagEditorData(paths, output)
    local data = {}
    for _, path in ipairs(paths or {}) do
        local path_norm = NormalizeFavoritePath(path)
        data[path_norm] = data[path_norm]
            or {user = {}, detected = {}, excluded = {}}
    end
    for line in tostring(output or ""):gmatch("[^\r\n]+") do
        local path_hex, kind, tag_hex =
            line:match("^([^\t]*)\t([^\t]*)\t(.*)$")
        local path_norm = NormalizeFavoritePath(
            DecodeSQLHex(path_hex or ""))
        local tag = NormalizeTag(DecodeSQLHex(tag_hex or ""))
        local entry = data[path_norm]
        if entry and tag ~= "" then
            local target = kind == "U" and entry.user
                or (kind == "D" and entry.detected)
                or (kind == "X" and entry.excluded) or nil
            if target then target[#target + 1] = tag end
        end
    end
    return data
end

function SetMediaTagData(path, tags, excluded, defer_refresh, defer_journal)
    local normalized_path = NormalizeFavoritePath(path)
    state.media_class_by_path[normalized_path] = nil
    local cleaned, clean_excluded, seen = {}, {}, {}
    for _, raw_tag in ipairs(tags or {}) do
        local tag = NormalizeTag(raw_tag)
        if tag ~= "" and not seen[tag] then
            cleaned[#cleaned + 1] = tag
            seen[tag] = true
        end
    end
    for _, raw_tag in ipairs(excluded or {}) do
        local tag = NormalizeTag(raw_tag)
        if tag ~= "" and not seen[tag] then
            clean_excluded[#clean_excluded + 1] = tag
            seen[tag] = true
        end
    end
    if #cleaned > 0 or #clean_excluded > 0 then
        state.media_user_tags[normalized_path] = {
            path = path,
            tags = cleaned,
            excluded = clean_excluded,
        }
    else
        state.media_user_tags[normalized_path] = nil
    end
    local saved = true
    if not defer_refresh then
        state.media_tag_generation = state.media_tag_generation + 1
        state.force_search_update = true
        state.needs_visible_update = true
        if StartMediaFilterIndexBuild then StartMediaFilterIndexBuild() end
        saved = true
    end
    if PersistMediaTagsToDatabase then
        local persisted = {}
        for _, tag in ipairs(cleaned) do persisted[#persisted + 1] = tag end
        for _, tag in ipairs(clean_excluded) do
            persisted[#persisted + 1] = "!" .. tag
        end
        PersistMediaTagsToDatabase(path, persisted)
    end
    if QueueCanonicalTags then
        QueueCanonicalTags(path, cleaned, clean_excluded, defer_journal)
    end
    return saved
end

local function GetManualCategoryKey(path)
    local normalized_path = NormalizeFavoritePath(path)
    local function Effective(value)
        if value == "uncategorized" then return "other" end
        if value == "loop" or value == "one-shot" or value == "other" then
            return value
        end
        return nil
    end
    local exact = state.classification_overrides
        and state.classification_overrides["file|" .. normalized_path]
    if exact then return Effective(exact) end

    -- A nearest folder override outranks a root override, regardless of the
    -- order in which Lua happens to iterate the override table.
    local folder_best, folder_length = nil, -1
    local root_best, root_length = nil, -1
    for key, classification in pairs(state.classification_overrides or {}) do
        local scope, override_path = key:match("^(%a+)|(.+)$")
        if (scope == "folder" or scope == "root") and override_path then
            local matches = normalized_path == override_path
                or (normalized_path:sub(1, #override_path) == override_path
                    and normalized_path:sub(#override_path + 1, #override_path + 1) == "/")
            if matches and scope == "folder" and #override_path > folder_length then
                folder_best = classification
                folder_length = #override_path
            elseif matches and scope == "root" and #override_path > root_length then
                root_best = classification
                root_length = #override_path
            end
        end
    end
    if folder_best then return Effective(folder_best) end
    if root_best then return Effective(root_best) end
    return nil
end

-- Return the winning manual override and its scope without confusing it with
-- the automatic scan result. The effective browser category may come from
-- this value, but the UI must label it as an override.
local function GetManualOverrideInfo(path)
    local normalized_path = NormalizeFavoritePath(path)
    local function Effective(value)
        if value == "uncategorized" then return "other" end
        if value == "loop" or value == "one-shot" or value == "other" then
            return value
        end
        return nil
    end
    local exact = state.classification_overrides
        and state.classification_overrides["file|" .. normalized_path]
    if exact then return Effective(exact), "file" end

    local folder_best, folder_length = nil, -1
    local root_best, root_length = nil, -1
    for key, classification in pairs(state.classification_overrides or {}) do
        local scope, override_path = key:match("^(%a+)|(.+)$")
        if (scope == "folder" or scope == "root") and override_path then
            local matches = normalized_path == override_path
                or (normalized_path:sub(1, #override_path) == override_path
                    and normalized_path:sub(#override_path + 1,
                        #override_path + 1) == "/")
            if matches and scope == "folder" and #override_path > folder_length then
                folder_best = classification
                folder_length = #override_path
            elseif matches and scope == "root" and #override_path > root_length then
                root_best = classification
                root_length = #override_path
            end
        end
    end
    if folder_best then return Effective(folder_best), "subfolder" end
    if root_best then return Effective(root_best), "root" end
    return nil, nil
end

local function ClassificationLabel(category)
    if category == "one-shot" then return "One-shot" end
    if category == "loop" then return "Loop" end
    if category == "midi" then return "MIDI" end
    return "Other"
end

local function SummarizeClassification(values)
    local seen, labels = {}, {}
    for _, value in ipairs(values or {}) do
        local label = ClassificationLabel(value)
        if not seen[label] then
            seen[label] = true
            labels[#labels + 1] = label
        end
    end
    table.sort(labels)
    return #labels == 1 and labels[1]
        or (#labels > 1 and "Mixed: " .. table.concat(labels, " + ")
            or "Unknown")
end

local function MediaHasMatchingTag(node, query)
    for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
        if tag:find(query, 1, true) then return true end
    end
    for _, tag in ipairs(EnsureGeneratedTags(node)) do
        if tag.name:find(query, 1, true) then return true end
    end
    return false
end

function MediaHasMatchingSearchTokens(node, normalized_query)
    for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
        if BrowserSearchTokensMatch(
            NormalizeBrowserSearchTokens(tag), normalized_query) then
            return true
        end
    end
    for _, tag in ipairs(EnsureGeneratedTags(node)) do
        if BrowserSearchTokensMatch(
            NormalizeBrowserSearchTokens(tag.name), normalized_query) then
            return true
        end
    end
    return false
end

local function MediaHasExactTag(node, wanted)
    wanted = NormalizeTag(wanted)
    for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
        if NormalizeTag(tag) == wanted then return true end
    end
    for _, tag in ipairs(EnsureGeneratedTags(node)) do
        if NormalizeTag(tag.name) == wanted then return true end
    end
    return false
end

local function QuickTypeSelectionKey()
    local names = {}
    for kind, enabled in pairs(state.media_filters.quick_types or {}) do
        if enabled then names[#names + 1] = kind end
    end
    table.sort(names)
    return table.concat(names, ",")
end

-- Classification is deliberately conservative and cheap. It uses bounded
-- path structure during the explicit scan; it never opens or analyzes audio.
-- Direct evidence wins, local structure can support a decision, and a distant
-- Loop/One-shot ancestor by itself is not allowed to label every descendant.
local function AutomaticCategoryMarker(value, allow_bare_break)
    local text = AutoTagSearchText(value or "")
    local has_one = AutoTagTextMatches(text, "one shot")
        or AutoTagTextMatches(text, "oneshot")
        or AutoTagTextMatches(text, "one shots")
        or AutoTagTextMatches(text, "oneshots")
    local has_loop = AutoTagTextMatches(text, "loop")
        or AutoTagTextMatches(text, "loops")
        or AutoTagTextMatches(text, "drum break")
        or AutoTagTextMatches(text, "breakbeat")
        or (allow_bare_break and (AutoTagTextMatches(text, "break")
            or AutoTagTextMatches(text, "breaks")))
    if has_one and has_loop then return "conflict" end
    if has_one then return "one-shot" end
    if has_loop then return "loop" end
    return nil
end

-- A library root can provide a broad default without overriding more
-- specific child folders. Keep this intentionally narrow: generic roots
-- such as Samples remain neutral.
local function RootDefaultCategory(value)
    local explicit = AutomaticCategoryMarker(value, true)
    if explicit then return explicit end
    local text = AutoTagSearchText(value or "")
    local function HasRootAlias(alias)
        return AutoTagTextMatches(text, alias)
    end
    if HasRootAlias("drums")
        or HasRootAlias("drum kit")
        or HasRootAlias("drum kits")
        or HasRootAlias("drumkit")
        or HasRootAlias("drum samples")
        or HasRootAlias("fx")
        or HasRootAlias("sfx")
        or HasRootAlias("sound effects") then
        return "one-shot"
    end
    return nil
end

local function FindClassificationRoot(path)
    local normalized = NormalizeFavoritePath(path)
    local best, best_length = nil, -1
    for _, root_path in ipairs(state.root_folders or {}) do
        local root = NormalizeFavoritePath(root_path)
        local inside = normalized == root
            or (normalized:sub(1, #root) == root
                and normalized:sub(#root + 1, #root + 1) == "/")
        if inside and #root > best_length then
            best, best_length = root, #root
        end
    end
    return best
end

local function ClassifyAutomaticMedia(filepath, supplied_key_pc, key_already_checked)
    local path = NormalizeFavoritePath(filepath or "")
    local extension = (path:match("%.([^./]+)$") or ""):lower()
    if extension == "mid" or extension == "midi" then
        return "midi", "media type", 1.0
    end
    local filename = path:match("([^/]+)$") or path
    local filename_class = AutomaticCategoryMarker(
        filename:gsub("%.[^%.]+$", ""), false)
    if filename_class == "conflict" then
        return "other", "conflicting filename category", 0.0
    elseif filename_class then
        return filename_class, "explicit filename", 0.98
    end

    local root = FindClassificationRoot(path)
    local parent_path = path:match("^(.*)/[^/]+$") or ""
    local relative = root and parent_path:sub(#root + 1) or parent_path
    local folders = {}
    if root then folders[#folders + 1] = root:match("([^/]+)$") or root end
    for folder_name in relative:gmatch("[^/]+") do folders[#folders + 1] = folder_name end
    local root_category = root and RootDefaultCategory(
        root:match("([^/]+)$") or root) or nil

    local nearest_category, nearest_distance = nil, nil
    -- The configured root has its own deliberately weak fallback below. Do not
    -- also treat its name as a nearby category folder: a root such as Guitar
    -- Loops must not force a nested Guitar FX or drum-hit folder to Loop.
    local first_category_folder = root and 2 or 1
    for index = #folders, first_category_folder, -1 do
        local folder_class = AutomaticCategoryMarker(folders[index], true)
        if folder_class == "conflict" then
            return "other", "conflicting folder category", 0.0
        elseif folder_class then
            nearest_category = folder_class
            nearest_distance = #folders - index
            break
        end
    end

    local filename_stem = filename:gsub("%.[^%.]+$", "")
    local immediate_folder = folders[#folders] or ""
    local local_text = AutoTagSearchText(
        filename_stem .. " " .. immediate_folder)
    local ancestor_parts = {}
    local first_ancestor = math.max(root and 2 or 1, #folders - 2)
    for index = first_ancestor, math.max(0, #folders - 1) do
        if folders[index] then
            ancestor_parts[#ancestor_parts + 1] = folders[index]
        end
    end
    local ancestor_text = AutoTagSearchText(table.concat(ancestor_parts, " "))

    local function HasAny(search_text, aliases)
        for _, alias in ipairs(aliases) do
            if AutoTagTextMatches(search_text, alias) then return true end
        end
        return false
    end

    local drum_aliases = {
        "kick", "kicks", "snare", "snares", "clap", "claps",
        "hat", "hats", "hi hat", "hihat", "hh", "oh", "ch",
        "open hat", "open hats", "open hihat", "closed hat",
        "closed hats", "closed hihat", "tom", "toms", "808",
        "cymbal", "cymbals", "rim", "rimshot", "percussion", "perc",
    }
    local drum_piece = HasAny(local_text, drum_aliases)
    local drum_context = HasAny(ancestor_text, {
        "drums", "drum kit", "drum kits", "drumkit", "drumkits",
        "drum samples", "drum one shots", "drum oneshots",
    })
    local kit_context = HasAny(local_text, {
        "kit", "kits", "drum kit", "drum kits", "drumkit", "drumkits",
    })
    local broader_instrument = HasAny(local_text, {
        "bass", "sub", "synth", "stab", "pluck", "chord", "vocal",
        "guitar", "piano", "keys", "brass", "strings",
    })
    local local_one_shot = drum_piece
        or (kit_context and drum_context)
        or nearest_category == "one-shot"
            and (drum_piece or broader_instrument)

    -- Terminal FX are one-shots unless they carry a validated BPM value.
    -- BPM-labelled risers, impacts, sweeps, transitions, and fills need loop
    -- behavior so preview and insertion preserve their rhythm.
    local terminal_one_shot = HasAny(local_text, {
        "fx", "sfx", "sound effect", "sound effects",
        "riser", "risers", "uplifter", "uplifters",
        "downlifter", "downlifters", "impact", "impacts",
        "sweep", "sweeps", "whoosh", "woosh",
        "transition", "transitions", "fill", "fills",
    })
    -- These terminal effects are commonly authored to a musical duration.
    -- Unlike the broad word "FX" (or an impact), a nearby BPM/bar declaration
    -- is meaningful evidence that they can be tempo matched.
    local rhythmic_fx_candidate = HasAny(local_text, {
        "riser", "risers", "uplifter", "uplifters",
        "downlifter", "downlifters", "sweep", "sweeps",
        "transition", "transitions", "fill", "fills",
    })

    -- Musical-fragment words describe content that may be useful with native
    -- tempo matching, but they do not prove that the file is an intentional
    -- loop. Keep these files in Other unless explicit loop/BPM evidence or a
    -- manual override says otherwise.
    local musical_fragment = HasAny(local_text, {
        "chop", "chops", "lick", "licks",
        "groove", "grooves", "pattern", "patterns", "phrase", "phrases",
        "sequence", "sequences", "seq", "melody", "melodies", "riff", "riffs",
        "arpeggio", "arpeggios", "arp", "beat", "beats", "roll", "rolls",
    })
    local local_musical_context = musical_fragment or broader_instrument
    local bare_timing = false
    for number in local_text:gmatch(" (%d%d?%d?) ") do
        local value = tonumber(number)
        if value and value >= 40 and value <= 300 then
            bare_timing = true
            break
        end
    end
    local local_explicit_bpm = DetectExplicitFilenameBPM
        and DetectExplicitFilenameBPM(filepath) or nil
    local filename_has_bpm_label = filename:lower():find("bpm", 1, true) ~= nil
    if local_explicit_bpm and not filename_has_bpm_label
        and nearest_category == "one-shot" then
        -- Vendor-position tempo fields remain available to playback, but a
        -- bare positional number must not overturn an explicit One-Shots tree.
        local_explicit_bpm = nil
    end
    local filename_text = AutoTagSearchText(filename_stem)
    local local_explicit_tempo = (local_explicit_bpm ~= nil
            and local_explicit_bpm >= 30 and local_explicit_bpm <= 400)
        or HasAny(filename_text, {"tempo"})
    local local_explicit_bar_length = filename_text:match(
        " %d+ bars? ") ~= nil
    local local_key_evidence = key_already_checked
        and supplied_key_pc ~= nil
        or (not key_already_checked and DetectFileKeyPitchClass
            and DetectFileKeyPitchClass(filepath, nil) ~= nil)
    local ancestor_explicit_bpm_text = ancestor_text:match(
        " (%d%d?%d?)%s*bpm ")
    local ancestor_explicit_bpm = tonumber(ancestor_explicit_bpm_text)
    local ancestor_explicit_tempo = (ancestor_explicit_bpm ~= nil
            and ancestor_explicit_bpm >= 30
            and ancestor_explicit_bpm <= 400)
        or HasAny(ancestor_text, {"tempo"})
        or HasAny(ancestor_text, {"loop", "loops"})
    local ancestor_explicit_bar_length = ancestor_text:match(
        " %d+ bars? ") ~= nil
    local immediate_folder_text = AutoTagSearchText(immediate_folder)
    local immediate_folder_bpm_text = immediate_folder_text:match(
        " (%d%d?%d?)%s*bpm ")
    local immediate_folder_bpm = tonumber(immediate_folder_bpm_text)
    local immediate_folder_tempo = (immediate_folder_bpm ~= nil
            and immediate_folder_bpm >= 30 and immediate_folder_bpm <= 400)
        or HasAny(immediate_folder_text, {"tempo"})
    local immediate_folder_bar_length = immediate_folder_text:match(
        " %d+%s*%-%s*%d+ bars? ") ~= nil
        or immediate_folder_text:match(" %d+ bars? ") ~= nil
    local nearby_folder_timing = immediate_folder_tempo
        or immediate_folder_bar_length
        or ancestor_explicit_tempo
        or ancestor_explicit_bar_length
    local explicit_tempo = local_explicit_tempo
        or ((local_musical_context or local_key_evidence)
            and nearby_folder_timing)
    local explicit_bar_length = local_explicit_bar_length
        or ((local_musical_context or local_key_evidence)
            and (immediate_folder_bar_length
                or ancestor_explicit_bar_length))

    -- A bare number is only timing support and must not turn Kick 120, Snare
    -- 95, or Riser 120 into loops without an explicit BPM suffix.
    if local_explicit_tempo or local_explicit_bar_length then
        -- File-level timing is the strongest automatic playback evidence. It
        -- must win over content words such as FX, downlifter, slide or guitar.
        return "loop", "explicit file BPM/bar structure", 0.95
    elseif terminal_one_shot and rhythmic_fx_candidate
        and nearby_folder_timing then
        return "loop", "folder-timed rhythmic FX", 0.92
    elseif terminal_one_shot and nearest_category == "loop" then
        -- FX, fills and transitions can be authored rhythmic phrases. An
        -- explicit nearby Loops folder is stronger evidence than the generic
        -- terminal-content word in the filename.
        local source = nearest_distance == 0
            and "direct category folder" or "ancestor category folder"
        return "loop", source, nearest_distance == 0 and 0.94 or 0.88
    elseif terminal_one_shot then
        return "one-shot", "local terminal/FX structure", 0.90
    elseif nearest_category then
        -- The nearest explicit category folder supplies the default within
        -- its subtree. A child Loop/One-shot folder therefore overrides a
        -- broad parent, while hard file evidence above can still differ.
        local source = nearest_distance == 0
            and "direct category folder" or "ancestor category folder"
        return nearest_category, source, nearest_distance == 0 and 0.94 or 0.88
    elseif explicit_tempo or explicit_bar_length then
        return "loop", "explicit BPM/bar structure", 0.93
    elseif local_one_shot then
        -- Without an explicit category folder, local drum/instrument naming
        -- can provide the fallback. It must not overturn a trusted folder
        -- default: a Kick.wav inside a Loop folder remains a Loop.
        return "one-shot", "local drum/instrument structure", 0.86
    elseif bare_timing then
        local has_key = local_key_evidence
        if has_key or nearest_category == "loop"
            or root_category == "loop" then
            return "loop", "contextual bare-tempo structure", 0.78
        elseif drum_piece or nearest_category == "one-shot"
            or root_category == "one-shot" then
            return "one-shot", "local instrument/ordinal structure", 0.82
        end
        return "other", "ambiguous bare number", 0.0
    elseif musical_fragment then
        return "other", "musical fragment descriptor", 0.0
    elseif root_category then
        -- A semantically named root supplies the default only after more
        -- specific local and ancestor evidence has had a chance to decide.
        return root_category, "configured root category", 0.80
    elseif nearest_category then
        return "other", "distant category folder only", 0.0
    end
    return "other", "uncategorized", 0.0
end

local function GetMediaClass(node)
    local normalized_path = NormalizeFavoritePath(node.path)
    local function Classified(kind)
        state.media_class_by_path[normalized_path] = kind
        return kind
    end
    local ext = (node.path:match("%.([^./\\]+)$") or ""):lower()
    if ext == "mid" or ext == "midi" then return Classified("midi") end
    local manual_override = GetManualCategoryKey(node.path)
    if manual_override then return Classified(manual_override) end
    local row_class = node.classification or node._classification
    if row_class == "loop" or row_class == "one-shot"
        or row_class == "other" then
        return Classified(row_class)
    end
    local cached = state.media_class_by_path[normalized_path]
    if cached then return cached end
    if not IsAudioFile(node.path) then return Classified("other") end
    local automatic = ClassifyAutomaticMedia(node.path)
    return Classified(automatic)
end

local function ResolveEffectiveMediaClass(filepath, supplied_class)
    if IsMidiFile(filepath) then return "midi" end
    local manual = GetManualCategoryKey(filepath)
    if manual then return manual end
    if supplied_class == "loop" or supplied_class == "one-shot"
        or supplied_class == "other" then
        return supplied_class
    end
    local normalized = NormalizeFavoritePath(filepath)
    local cached = state.media_class_by_path[normalized]
    if cached == "loop" or cached == "one-shot" or cached == "other" then
        return cached
    end
    return ClassifyAutomaticMedia(filepath)
end

function StartMediaFilterIndexBuild()
    local index = state.media_filter_index
    if state.database.canonical then
        -- Canonical SQLite pages and tag catalogs already provide this data.
        -- Building the complete legacy Lua index after a scan competes with
        -- the first interactive folder query and duplicates every file/tag in
        -- memory. Retain this index only for TSV compatibility mode.
        index.ready = false
        index.building = false
        index.requested = false
        index.stack = {}
        index.files = {}
        index.by_tag = {}
        index.by_class = {
            ["loop"] = {}, ["one-shot"] = {},
            ["midi"] = {}, ["other"] = {},
        }
        index.seen_paths = {}
        index.indexed_count = 0
        index.session_count = 0
        return
    end
    index.ready = false
    index.building = true
    index.stack = {}
    index.files = {}
    index.by_tag = {}
    index.by_class = {
        ["loop"] = {}, ["one-shot"] = {},
        ["midi"] = {}, ["other"] = {},
    }
    index.seen_paths = {}
    index.duplicate_count = 0
    index.build_mode = "full"
    index.session_count = 0
    index.indexed_count = 0
    index.requested = true
    for tree_index = #state.folder_tree, 1, -1 do
        index.stack[#index.stack + 1] = {
            kind = "node", value = state.folder_tree[tree_index]
        }
    end
end

local function AppendMediaFilterIndexRoots(roots)
    local index = state.media_filter_index
    if state.database_startup_test.enabled then
        StartMediaFilterIndexBuild()
        return
    end
    -- Appending is safe only onto a complete index. If startup optimization
    -- is still underway, rebuild once from the authoritative combined tree.
    if not index.ready or index.building then
        StartMediaFilterIndexBuild()
        return
    end
    -- Keep the completed existing index usable while the new root is merged.
    index.ready = true
    index.building = true
    index.build_mode = "append"
    index.session_count = 0
    index.stack = {}
    for tree_index = #(roots or {}), 1, -1 do
        index.stack[#index.stack + 1] = {
            kind = "node", value = roots[tree_index]
        }
    end
end

function ProcessMediaFilterIndexBuild()
    local index = state.media_filter_index
    if state.database.canonical then
        if index.building or index.ready or #(index.files or {}) > 0 then
            StartMediaFilterIndexBuild()
        end
        return
    end
    if not index.building then return end
    local budget = 750
    local deadline = r.time_precise() + 0.003
    while budget > 0 and r.time_precise() < deadline do
        local work = table.remove(index.stack)
        if not work then
            index.building = false
            index.ready = true
            index.requested = false
            state.force_search_update = true
            state.media_tag_bar.cache_key = nil
            return
        end
        if work.kind == "node" then
            local node = work.value
            for file_index = #node.files, 1, -1 do
                index.stack[#index.stack + 1] = {
                    kind = "file", value = node.files[file_index]
                }
            end
            for child_index = #node.children, 1, -1 do
                index.stack[#index.stack + 1] = {
                    kind = "node", value = node.children[child_index]
                }
            end
        else
            local node = work.value
            local path_key = NormalizeFavoritePath(node.path)
            if index.seen_paths[path_key] then
                index.duplicate_count = (index.duplicate_count or 0) + 1
            else
                index.seen_paths[path_key] = true
                index.files[#index.files + 1] = node
                local class = GetMediaClass(node)
                local class_entries = index.by_class[class]
                if class_entries then
                    class_entries[#class_entries + 1] = node
                end
                local seen = {}
                for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
                    local name = NormalizeTag(tag)
                    if name ~= "" and not seen[name] then
                        local entries = index.by_tag[name]
                        if not entries then
                            entries = {}
                            index.by_tag[name] = entries
                        end
                        entries[#entries + 1] = node
                        seen[name] = true
                    end
                end
                for _, generated in ipairs(EnsureGeneratedTags(node)) do
                    local name = NormalizeTag(generated.name)
                    if name ~= "" and not seen[name] then
                        local entries = index.by_tag[name]
                        if not entries then
                            entries = {}
                            index.by_tag[name] = entries
                        end
                        entries[#entries + 1] = node
                        seen[name] = true
                    end
                end
                index.indexed_count = index.indexed_count + 1
                index.session_count = (index.session_count or 0) + 1
            end
        end
        budget = budget - 1
    end
end

local function GetIndexedFilterCandidates()
    local index = state.media_filter_index
    local facet = state.media_tag_facets
    -- Do not optimize the entire library at startup. The index is only
    -- needed when a filter is actually active; ordinary browsing and search
    -- can use the loaded cache directly.
    if MediaFiltersActive()
        and not index.ready and not index.building
        and not index.requested then
        StartMediaFilterIndexBuild()
    end
    if state.selected_folder_scope
        and not facet.building
        and facet.scope == state.selected_folder_scope then
        local smallest = nil
        for tag, enabled in pairs(
            state.media_filters.selected_tags or {}) do
            if enabled then
                local entries = facet.by_tag[NormalizeTag(tag)] or {}
                if not smallest or #entries < #smallest then
                    smallest = entries
                end
            end
        end
        if smallest then return smallest end
        local quick_types = state.media_filters.quick_types or {}
        if next(quick_types) ~= nil then
            local combined = {}
            for _, kind in ipairs(
                {"loop", "one-shot", "midi", "other"}) do
                if quick_types[kind] then
                    for _, node in ipairs(facet.by_class[kind] or {}) do
                        combined[#combined + 1] = node
                    end
                end
            end
            return combined
        end
    end
    if state.favorites_mode
        or (not index.ready and not index.building) then return nil end
    -- Never publish an incomplete full-library result set. Selected filters
    -- become active atomically when startup optimization completes instead of
    -- making matching files visibly trickle into the browser.
    if index.building and index.build_mode == "full" then return {} end
    local smallest = nil
    for tag, enabled in pairs(state.media_filters.selected_tags or {}) do
        if enabled then
            local entries = index.by_tag[NormalizeTag(tag)] or {}
            if not smallest or #entries < #smallest then smallest = entries end
        end
    end
    if smallest then return smallest end

    local quick_types = state.media_filters.quick_types or {}
    if next(quick_types) ~= nil then
        local combined = {}
        for _, kind in ipairs({"loop", "one-shot", "midi", "other"}) do
            if quick_types[kind] then
                for _, node in ipairs(index.by_class[kind] or {}) do
                    combined[#combined + 1] = node
                end
            end
        end
        return combined
    end
    return nil
end

local function GetNormalizedMediaTagQuery()
    local source = state.media_filters.tag_text or ""
    if state._media_tag_query_source ~= source then
        state._media_tag_query_source = source
        state._normalized_media_tag_query = NormalizeTag(source)
    end
    return state._normalized_media_tag_query or ""
end

local function GetNormalizedMediaSearchQuery()
    local source = state.search_text or ""
    if state._media_search_query_source ~= source then
        state._media_search_query_source = source
        state._normalized_media_search_query =
            NormalizeBrowserSearchTokens(source)
    end
    return state._normalized_media_search_query or ""
end

local function MediaMatchesFilters(node)
    local filters = state.media_filters
    for tag, enabled in pairs(filters.selected_tags or {}) do
        if enabled and not MediaHasExactTag(node, tag) then return false end
    end
    if (filters.key_pc or -1) >= 0 then
        if node.filter_key_override_generation
            ~= (state.key_override_generation or 0) then
            node.filter_key_pc = ResolveEffectiveKeyPitchClass(
                node.path, DetectFileKeyPitchClass(node.path, nil)) or false
            node.filter_key_override_generation =
                state.key_override_generation or 0
        end
        if node.filter_key_pc ~= filters.key_pc then return false end
    end
    local quick_types = filters.quick_types or {}
    if next(quick_types) ~= nil
        and not quick_types[GetMediaClass(node)] then return false end
    local tag_query = GetNormalizedMediaTagQuery()
    if tag_query ~= "" and not MediaHasMatchingTag(node, tag_query) then
        return false
    end
    return true
end

local function MediaMatchesSearch(node)
    if state.search_text == "" then return true end
    local query = GetNormalizedMediaSearchQuery()
    node.normalized_search_name = node.normalized_search_name
        or NormalizeBrowserSearchTokens(node.name_lower)
    if BrowserSearchTokensMatch(node.normalized_search_name, query) then
        return true
    end
    return MediaHasMatchingSearchTokens(node, query)
end

function MediaFiltersActive()
    if GetNormalizedMediaTagQuery() ~= "" then return true end
    for _, enabled in pairs(state.media_filters.selected_tags or {}) do
        if enabled then return true end
    end
    return (state.media_filters.key_pc or -1) >= 0
        or next(state.media_filters.quick_types or {}) ~= nil
end

-- ============================================================
-- LOCALIZATION BOUNDARY
-- ============================================================
-- UI strings migrate through T() progressively. REAPER's active language
-- pack selects a matching ReaBrowse table when one is available; missing
-- translations always fall back to English.
local REABROWSE_STRINGS = {
    en = {
        check_folder_changes = "Update Folder",
        add_new_files_folder = "Add new files from this folder",
        remove_folder = "Remove folder from ReaBrowse",
        checking_folder = "Checking folder for changes...",
    },
}

local function DetectREAPERLanguage()
    local filename = ""
    if r.get_config_var_string then
        local ok, first, second =
            pcall(r.get_config_var_string, "__langpack_filename")
        local value = type(first) == "string" and first or second
        if ok and type(value) == "string" then filename = value end
    end
    if filename == "" and r.SNM_GetStringConfigVar then
        local ok, first, second = pcall(
            r.SNM_GetStringConfigVar, "__langpack_filename", "")
        local value = type(first) == "string" and first or second
        if ok and type(value) == "string" then filename = value end
    end
    local lower = filename:lower()
    if lower:find("german", 1, true) or lower:find("deutsch", 1, true) then
        return "de"
    elseif lower:find("french", 1, true) or lower:find("fran", 1, true) then
        return "fr"
    elseif lower:find("spanish", 1, true) or lower:find("espa", 1, true) then
        return "es"
    elseif lower:find("japanese", 1, true) then
        return "ja"
    end
    return "en"
end

local REABROWSE_LANGUAGE = DetectREAPERLanguage()

local function T(key)
    local active = REABROWSE_STRINGS[REABROWSE_LANGUAGE]
    return active and active[key]
        or REABROWSE_STRINGS.en[key]
        or tostring(key)
end

-- ============================================================
-- DATABASE STORAGE ADAPTER
-- ============================================================
local DATABASE_SCHEMA_VERSION = 5
DATABASE_WORKER_PROTOCOL_VERSION = 4
-- Schema v5 removes the structural hot paths, while these runtime rails remain
-- as last-resort protection against unexpectedly pathological predicates.
-- Exact totals are cosmetic and optional reads never outrank foreground work.
local LARGE_LIBRARY_FILE_COUNT = 1000000
local SMALL_MATERIALIZED_FOLDER_SCOPE = 50000
local SLOW_CANONICAL_QUERY_MS = 750
local OPTIONAL_READ_COOLDOWN_SECONDS = 2.0
-- Keep both smart usage views bounded while allowing enough history for
-- meaningful Recent and Most Used results in long-running installations.
local USAGE_RECENT_RETENTION_LIMIT = 5000
local USAGE_MOST_USED_RETENTION_LIMIT = 5000
local USAGE_RETENTION_PRUNE_THRESHOLD = 12000
-- Result views use a small rolling window. The page cache remains the
-- authority for nearby history, while Lua never retains millions of decoded
-- row tables. Keeping only a handful of pages visible also makes the earlier
-- results boundary appear during ordinary browsing instead of only after
-- thousands of rows have accumulated.
RB_MAX_CANONICAL_RESULT_ROWS = 600
RB_MAX_CANONICAL_ACCORDION_ROWS = 600
RB_FAVORITES_ROOT_MEMBERSHIP = "\1root"
-- Custom Favorites are virtual collections, not physical folders.  Their
-- facet cache mirrors folder_tag_counts so reopening a large Favorites folder
-- remains an indexed read instead of repeatedly combining its memberships.
function GetMediaDatabasePath()
    -- ReaBrowse has one active database. The legacy database path is no
    -- longer part of the runtime contract.
    return GetCanonicalDatabasePath()
end

function GetReaBrowseDataDirectory()
    return r.GetResourcePath():gsub("[/\\]+$", "") .. "/Data/ReaBrowse"
end

function EnsureReaBrowseDataLayout()
    local root = GetReaBrowseDataDirectory()
    if not r.RecursiveCreateDirectory then return false end
    local paths = {
        root,
        root .. "/cache",
        root .. "/sidecar",
        root .. "/backups",
    }
    for _, path in ipairs(paths) do
        if r.RecursiveCreateDirectory(path, 0) == false then
            return false
        end
    end
    local marker = root .. "/layout.version"
    local marker_file = io.open(marker, "r")
    if marker_file then
        marker_file:close()
    else
        marker_file = io.open(marker, "w")
        if not marker_file then return false end
        marker_file:write("1\n")
        marker_file:close()
    end
    return FileExists(marker)
end

local function CleanupStaleScanManifests()
    local data_dir = GetReaBrowseDataDirectory():gsub("[/\\]+$", "")
    local index = 0
    while r.EnumerateFiles do
        local name = r.EnumerateFiles(data_dir, index)
        if not name then break end
        index = index + 1
        if name:match("^Pending_Scan_.+%.tsv$")
            or name:match("^Discovery_.+%.tsv$")
            or name:match("^Discovery_.+%.tsv%.writing$")
            or name:match("^Discovery_.+%.tsv%.progress$") then
            pcall(os.remove, data_dir .. "/" .. name)
        end
    end
end

function GetCanonicalDatabasePath()
    return GetReaBrowseDataDirectory() .. "/ReaBrowse.sqlite3"
end

local function GetScriptDirectory()
    local source = debug.getinfo(1, "S").source or ""
    if source:sub(1, 1) == "@" then source = source:sub(2) end
    return source:match("^(.*)[/\\][^/\\]+$") or "."
end

local function LoadReaBrowseSchemaSQL()
    local path = GetScriptDirectory():gsub("[/\\]+$", "")
        .. "/ReaBrowse_Canonical_Schema_v5.sql"
    local file = io.open(path, "rb")
    if not file then return nil, "Canonical ReaBrowse schema was not found." end
    local sql = file:read("*a") or ""
    file:close()
    if sql == "" then return nil, "Canonical ReaBrowse schema is empty." end
    return sql
end

local DATABASE_BATCH_SIZE = 250

-- Worker discovery removes filesystem latency from REAPER's GUI thread. These
-- budgets now govern sequential manifest ingestion/finalization, plus the Lua
-- enumeration fallback when the packaged worker is unavailable.
local LIBRARY_SCAN_SPEEDS = {
    gentle = {
        label = "Background",
        detail = "128 entries / 1 ms per frame",
        budget = 128, time_slice = 0.001,
        finalize_budget = 192, finalize_slice = 0.001,
    },
    balanced = {
        label = "Normal",
        detail = "512 entries / 2 ms per frame",
        budget = 512, time_slice = 0.002,
        finalize_budget = 768, finalize_slice = 0.002,
    },
    fast = {
        label = "Fast",
        detail = "1,536 entries / 4 ms per frame",
        budget = 1536, time_slice = 0.004,
        finalize_budget = 2048, finalize_slice = 0.004,
    },
    maximum = {
        label = "Maximum",
        detail = "3,072 entries / 6 ms per frame",
        budget = 3072, time_slice = 0.006,
        finalize_budget = 4096, finalize_slice = 0.006,
    },
    turbo = {
        label = "Dedicated",
        detail = "73,728 entries / 60 ms per frame; unthrottled worker",
        -- Dedicated is explicitly throughput-first. The former 20 ms slice
        -- processed a version migration at ~440 files/s, about one third of
        -- the established scan rate, while still yielding every UI frame.
        budget = 73728, time_slice = 0.060,
        finalize_budget = 98304, finalize_slice = 0.060,
    },
}

local function GetLibraryScanSpeedProfile()
    return LIBRARY_SCAN_SPEEDS[state.scan_speed]
        or LIBRARY_SCAN_SPEEDS.balanced
end

local function BeginBlockingLibraryOperation(kind, phase, label, detail)
    local scan = state.library_scan
    scan.scanning = true
    scan.browser_blocked = true
    scan.progressive = false
    scan.operation_kind = kind
    scan.phase = phase
    scan.started_at = r.time_precise()
    scan.phase_started_at = scan.started_at
    scan.phase_label = label
    scan.phase_detail = detail
    scan.phase_done = 0
    scan.phase_total = 1
end

local function EndBlockingLibraryOperation(status, error_message)
    local scan = state.library_scan
    scan.scanning = false
    scan.browser_blocked = false
    scan.progressive = false
    scan.operation_kind = nil
    scan.phase = nil
    scan.phase_detail = nil
    scan.phase_done = 0
    scan.phase_total = 0
    if status then state.database.status = status end
    state.database.error = error_message and tostring(error_message) or nil
end

local function FormatLibraryProgressCaption(done, total, fraction)
    done = tonumber(done)
    total = tonumber(total)
    if done and total and total > 0
        and done == math.floor(done) and total == math.floor(total) then
        return string.format("%d / %d", done, total)
    end
    return string.format("%.0f%%", math.max(0, math.min(1,
        tonumber(fraction) or 0)) * 100)
end

local function ProcessQuote(value)
    value = tostring(value or "")
    if value ~= "" and not value:find('[%s"]') then return value end
    local result, slashes = {'"'}, 0
    for index = 1, #value do
        local character = value:sub(index, index)
        if character == "\\" then
            slashes = slashes + 1
        elseif character == '"' then
            result[#result + 1] = string.rep("\\", slashes * 2 + 1)
            result[#result + 1] = '"'
            slashes = 0
        else
            if slashes > 0 then
                result[#result + 1] = string.rep("\\", slashes)
                slashes = 0
            end
            result[#result + 1] = character
        end
    end
    if slashes > 0 then result[#result + 1] = string.rep("\\", slashes * 2) end
    result[#result + 1] = '"'
    return table.concat(result)
end

local function BrowseForRootFolder()
    if r.JS_Dialog_BrowseForFolder then
        local ok, path =
            r.JS_Dialog_BrowseForFolder("Select Root Folder", "")
        return ok and path ~= "" and path or nil, true
    end
    return nil, false
end

local function RemoveEmptySidecarDirectory(path)
    if not path or path == "" then return false end
    local call_ok, removed = pcall(os.remove, path)
    if call_ok and removed then return true end
    if not r.ExecProcess then return false end

    -- Lua's os.remove() does not remove directories on Windows. Use the
    -- platform's non-recursive rmdir command so cleanup can reclaim a queue
    -- only after every transport file and process lock has disappeared.
    local os_name = (r.GetOS() or ""):lower()
    local is_windows = os_name:find("win", 1, true) ~= nil
    -- REAPER paths normally use forward slashes. cmd.exe treats a quoted
    -- absolute path such as C:/Users/... as command switches beginning at
    -- /Users, so rmdir fails after the queue files have already been removed.
    local command_path = is_windows and path:gsub("/", "\\") or path
    local command = is_windows
        and ("cmd.exe /D /Q /C rmdir " .. ProcessQuote(command_path))
        or ("rmdir " .. ProcessQuote(command_path))
    local response = r.ExecProcess(command, 5000)
    local exit_code = response and tonumber(
        tostring(response):match("^%s*(-?%d+)")) or nil
    return exit_code == 0
end

local function CleanupStaleSidecarFiles(data_dir)
    -- Session sidecars are short-lived transport files. A one-hour grace
    -- period allowed every script reload to leave another full copy behind.
    -- Keep a small safety window for a second live instance, while reclaiming
    -- abandoned session files promptly on the next launch.
    local file_cutoff = os.time() - 60
    local owner_cutoff = os.time() - 45
    local sidecar_dir = data_dir:gsub("[/\\]+$", "") .. "/sidecar"
    local index = 0
    while true do
        local name = r.EnumerateFiles(sidecar_dir, index)
        if not name then break end
        index = index + 1
        local timestamp = name:match("^ReaBrowse_Sidecar_[^_]+_(%d+)_")
            or name:match("^ReaBrowse_Worker_(%d+)_")
        if timestamp and tonumber(timestamp) < file_cutoff then
            local call_ok, removed = pcall(os.remove,
                sidecar_dir .. "/" .. name)
            if call_ok and removed then index = index - 1 end
        end
    end

    -- Worker queues are session-specific directories. A normal shutdown
    -- removes their process, but an unexpected REAPER close can leave the
    -- queue behind. Use the worker heartbeat rather than directory age so an
    -- active long-running session is never mistaken for stale state.
    local queue_names = {}
    local queue_index = 0
    while true do
        local name = r.EnumerateSubdirectories(sidecar_dir, queue_index)
        if not name then break end
        queue_index = queue_index + 1
        if name:match("^worker_queue_") then
            queue_names[#queue_names + 1] = name
        end
    end
    for _, queue_name in ipairs(queue_names) do
        local queue_path = sidecar_dir .. "/" .. queue_name
        local queue_created_at = tonumber(
            queue_name:match("^worker_queue_(%d+)_"))
        local owner_file = io.open(queue_path .. "/owner.ready", "rb")
        local owner_heartbeat
        if owner_file then
            owner_heartbeat = tonumber((owner_file:read("*a") or "")
                :match("%d+"))
            owner_file:close()
        end
        local stale = (owner_heartbeat and owner_heartbeat < owner_cutoff)
            or (not owner_heartbeat and queue_created_at
                and queue_created_at < file_cutoff)
        if stale then
            -- Ask a lingering worker to release its lock before removing the
            -- queue. Locked files are harmlessly retried on the next launch.
            local shutdown = io.open(queue_path .. "/shutdown.req", "wb")
            if shutdown then shutdown:write("shutdown\n"); shutdown:close() end
            local file_index = 0
            while true do
                local file_name = r.EnumerateFiles(queue_path, file_index)
                if not file_name then break end
                local call_ok, removed = pcall(os.remove,
                    queue_path .. "/" .. file_name)
                if not (call_ok and removed) then file_index = file_index + 1 end
            end
            RemoveEmptySidecarDirectory(queue_path)
        end
    end
end

local function CleanupWorkerQueuePath(queue_path)
    if not queue_path or queue_path == "" then return end
    local file_index = 0
    while true do
        local file_name = r.EnumerateFiles(queue_path, file_index)
        if not file_name then break end
        local call_ok, removed = pcall(os.remove, queue_path .. "/" .. file_name)
        if not (call_ok and removed) then file_index = file_index + 1 end
    end
    RemoveEmptySidecarDirectory(queue_path)
end

local function PublishWorkerOwnerHeartbeat()
    local database = state.database
    if not database or not database.worker_started
        or not database.worker_owner_path then return end
    local now = r.time_precise()
    if database.worker_owner_last_write
        and now - database.worker_owner_last_write < 1.0 then return end
    local file = io.open(database.worker_owner_path, "wb")
    if file then
        file:write(tostring(os.time()), "\n")
        file:close()
        database.worker_owner_last_write = now
    end
end

SQLQuote = function(value)
    if value == nil then return "NULL" end
    return "'" .. tostring(value):gsub("'", "''") .. "'"
end

local function WriteDatabaseBatch(sql, batch_path, target_path)
    local database = state.database
    batch_path = batch_path or database.batch_path
    target_path = target_path or GetMediaDatabasePath()
    local file, open_error = io.open(batch_path, "wb")
    if not file then return false, "Could not prepare database update: " .. tostring(open_error) end
    local batch_sql = "PRAGMA foreign_keys=ON;\nPRAGMA busy_timeout=5000;\n"
        .. tostring(sql or "")
    local wrote, write_error = file:write(batch_sql)
    file:close()
    if not wrote then return false, "Could not write database update: " .. tostring(write_error) end
    local command = ProcessQuote(database.helper_path)
        .. " -batch -bail -init " .. ProcessQuote(batch_path)
        .. " " .. ProcessQuote(target_path) .. " .quit"
    local response = r.ExecProcess(command, 30000)
    if response == nil then return false, "REAPER could not start the database helper." end
    response = tostring(response)
    local first_line, output = response:match("^([^\r\n]*)\r?\n?(.*)$")
    if tonumber(first_line) ~= 0 then
        return false, "Database helper failed (" .. tostring(first_line) .. "): "
            .. tostring(output or "")
    end
    return true, output or ""
end

local function WindowsBatchQuote(value)
    return '"' .. tostring(value or ""):gsub('"', '""') .. '"'
end

local function StartDatabaseCliBatchAsync(sql, count, kind, target_path)
    local database = state.database
    if database.write_active then return false, "Database update already active." end
    local file, open_error = io.open(database.batch_path, "wb")
    if not file then
        return false, "Could not prepare database update: " .. tostring(open_error)
    end
    local batch_sql = "PRAGMA foreign_keys=ON;\nPRAGMA busy_timeout=5000;\n"
        .. tostring(sql or "")
    local wrote, write_error = file:write(batch_sql)
    file:close()
    if not wrote then
        return false, "Could not write database update: " .. tostring(write_error)
    end

    pcall(os.remove, database.done_path)
    pcall(os.remove, database.result_path)
    local runner, runner_error = io.open(database.runner_path, "wb")
    if not runner then
        return false, "Could not prepare background database update: "
            .. tostring(runner_error)
    end
    runner:write(
        "@echo off\r\n",
        WindowsBatchQuote(database.helper_path),
        " -batch -bail -init ", WindowsBatchQuote(database.batch_path),
        " ", WindowsBatchQuote(target_path or GetMediaDatabasePath()),
        " .quit > ",
        WindowsBatchQuote(database.result_path), " 2>&1\r\n",
        "> ", WindowsBatchQuote(database.done_path), " echo %errorlevel%\r\n"
    )
    runner:close()

    local launcher, launcher_error = io.open(database.launcher_path, "wb")
    if not launcher then
        return false, "Could not prepare hidden database update: "
            .. tostring(launcher_error)
    end
    local escaped_runner = database.runner_path:gsub('"', '""')
    launcher:write(
        "Set shell = CreateObject(\"WScript.Shell\")\r\n",
        "shell.Run Chr(34) & \"", escaped_runner,
        "\" & Chr(34), 0, False\r\n"
    )
    launcher:close()

    local launched = r.ExecProcess(
        "wscript.exe //B //NoLogo " .. ProcessQuote(database.launcher_path), -1)
    if launched == nil then
        return false, "REAPER could not start the background database helper."
    end
    database.write_active = true
    database.write_pending_count = count or 0
    database.write_pending_kind = kind or "batch"
    database.write_target_path = target_path or GetMediaDatabasePath()
    database.write_started_at = r.time_precise()
    database.write_progress_stage = nil
    database.write_progress_label = nil
    database.write_progress_done = 0
    database.write_progress_total = 0
    database.write_progress_stage_started_at = 0
    return true
end

local function StartDatabaseBatchAsync(sql, count, kind, target_path)
    local database = state.database
    if database.write_active then return false, "Database update already active." end
    local discovery_owns_worker = state.library_scan
        and state.library_scan.scanning
        and state.library_scan.phase == "worker_discovery"
    if (kind == "canonical_page" or kind == "canonical_membership"
        or kind == "canonical_favorite_mutation"
        or kind == "canonical_tag_editor")
        and not discovery_owns_worker then
        local worker_result = StartDatabaseWorkerAsync(
            sql, target_path, kind)
        if worker_result ~= nil then
            if worker_result then
                database.worker_fallback_sql = sql
                database.worker_fallback_count = count or 0
                database.worker_fallback_kind = kind
                database.worker_fallback_target =
                    target_path or GetMediaDatabasePath()
            end
            return worker_result
        end
    end
    return StartDatabaseCliBatchAsync(sql, count, kind, target_path)
end

local function DecodeWorkerPayload(value)
    return tostring(value or ""):gsub("%%09", "\t")
        :gsub("%%0A", "\n"):gsub("%%0D", "\r")
        :gsub("%%25", "%%")
end

function PublishDatabaseWorkerRequest(request_path, contents)
    local writing_path = request_path .. ".writing"
    pcall(os.remove, writing_path)
    local file, open_error = io.open(writing_path, "wb")
    if not file then return false, open_error end
    local wrote, write_error = file:write(contents or "")
    local closed, close_error = file:close()
    if not wrote or closed == nil then
        pcall(os.remove, writing_path)
        return false, write_error or close_error or "request write failed"
    end
    pcall(os.remove, request_path)
    local renamed, rename_error = os.rename(writing_path, request_path)
    if not renamed then
        pcall(os.remove, writing_path)
        return false, rename_error or "request publish failed"
    end
    return true
end

-- Launch the persistent reader without attaching it to a UI request.  This
-- lets the first visible frame stay responsive while the worker's one-time
-- .NET/SQLite startup happens in the background.
local function EnsureDatabaseWorkerStarted(target_path)
    local database = state.database
    local worker_path = database.worker_path
    if not worker_path or not FileExists(worker_path) then
        database.worker_status = "worker file missing: " .. tostring(worker_path)
        return false
    end
    local queue = database.worker_queue
    if not queue then
        database.worker_status = "worker queue missing"
        return false
    end
    if r.RecursiveCreateDirectory then r.RecursiveCreateDirectory(queue, 0) end
    -- The on-disk protocol heartbeat is authoritative. A completed CLI read or
    -- cancellation can clear Lua's launch bookkeeping while the persistent
    -- worker remains healthy. Re-adopt that worker instead of deleting its
    -- readiness file and launching a duplicate that can only lose worker.lock.
    if database.worker_ready_path then
        local ready = io.open(database.worker_ready_path, "rb")
        local ready_text = ready and (ready:read("*a") or "") or ""
        if ready then ready:close() end
        local heartbeat, protocol = ready_text:match("^(%d+)|(%d+)|")
        if tonumber(protocol) == DATABASE_WORKER_PROTOCOL_VERSION
            and tonumber(heartbeat)
            and os.time() - tonumber(heartbeat) <= 5 then
            database.worker_started = true
            database.worker_unready_since = nil
            database.worker_status = "adopted live worker heartbeat"
            return true
        end
    end
    if database.worker_started then return true end
    -- Publish ownership before launching. A fast worker can reach its first
    -- heartbeat check before the next deferred Lua frame.
    if database.worker_owner_path then
        local owner = io.open(database.worker_owner_path, "wb")
        if owner then
            owner:write(tostring(os.time()), "\n")
            owner:close()
            database.worker_owner_last_write = r.time_precise()
        end
    end
    if database.worker_ready_path then
        pcall(os.remove, database.worker_ready_path)
    end
    local launcher_path = database.worker_launcher_path
    local launcher, launcher_error = io.open(launcher_path, "wb")
    if not launcher then
        database.worker_status = "could not create worker launcher: "
            .. tostring(launcher_error)
        return false
    end
    local escaped_worker = worker_path:gsub('"', '""')
    local escaped_queue = queue:gsub('"', '""')
    local escaped_database = (target_path or GetMediaDatabasePath())
        :gsub('"', '""')
    local escaped_owner = (database.worker_owner_path or ""):gsub('"', '""')
    launcher:write(
        "Set shell = CreateObject(\"WScript.Shell\")\r\n",
        "shell.Run Chr(34) & \"", escaped_worker,
        "\" & Chr(34) & \" --queue \" & Chr(34) & \"",
        escaped_queue,
        "\" & Chr(34) & \" --database \" & Chr(34) & \"",
        escaped_database,
        '" & Chr(34) & " --owner-heartbeat " & Chr(34) & "',
        escaped_owner, '" & Chr(34), 0, False\r\n')
    launcher:close()
    local launched = r.ExecProcess(
        "wscript.exe //B //NoLogo " .. ProcessQuote(launcher_path), -1)
    if launched == nil then
        database.worker_status = "wscript launch failed"
        return false
    end
    database.worker_started = true
    database.worker_started_at = r.time_precise()
    database.worker_unready_since = nil
    database.worker_status = "worker warm"
    return true
end

local function IsDatabaseWorkerReady()
    local database = state.database
    if not database.worker_ready_path then
        return false
    end
    local ready = io.open(database.worker_ready_path, "rb")
    if not ready then return false end
    local text = ready:read("*a") or ""
    ready:close()
    local heartbeat, protocol, sqlite_version = text:match(
        "^(%d+)|(%d+)|([^|%s]+)")
    heartbeat = tonumber(heartbeat)
    protocol = tonumber(protocol)
    database.worker_protocol_version = protocol
    database.worker_sqlite_version = sqlite_version
    if heartbeat and protocol ~= DATABASE_WORKER_PROTOCOL_VERSION then
        database.worker_status = string.format(
            "worker protocol mismatch (found %s, need %d)",
            tostring(protocol or "legacy"), DATABASE_WORKER_PROTOCOL_VERSION)
        return false
    end
    local healthy = heartbeat ~= nil and os.time() - heartbeat <= 5
    if healthy then
        database.worker_started = true
        database.worker_unready_since = nil
    end
    return healthy
end

function StartDatabaseWorkerAsync(sql, target_path, request_kind)
    local database = state.database
    if database.worker_active then
        return false, "Database worker request already active."
    end
    local queue = database.worker_queue
    if not queue then return nil end
    -- A prior worker can reclaim its session queue after owner loss. Recreate
    -- it before publishing the next request so the reader path can recover.
    if r.RecursiveCreateDirectory then
        r.RecursiveCreateDirectory(queue, 0)
    end
    local token = tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999))
    local request_path = queue .. "/" .. token .. ".req"
    local result_path = queue .. "/" .. token .. ".res"
    local published = PublishDatabaseWorkerRequest(
        request_path, token .. "\n@sql:"
            .. tostring(DATABASE_WORKER_PROTOCOL_VERSION) .. "\n" .. tostring(sql or ""))
    if not published then return nil end
    if not EnsureDatabaseWorkerStarted(target_path) then
        pcall(os.remove, request_path)
        return nil
    end
    database.worker_active = true
    database.worker_cancelled = false
    database.worker_request_path = request_path
    database.worker_result_path = result_path
    database.worker_started_at = r.time_precise()
    database.write_active = true
    database.write_pending_count = 0
    database.write_pending_kind = request_kind or "canonical_page"
    database.write_target_path = target_path or GetMediaDatabasePath()
    return true
end

local function CancelActiveCanonicalRead(reason)
    local database = state.database
    local paging = state.canonical_paging
    local request = paging and paging.browser_request
    local membership_read =
        database.write_pending_kind == "canonical_membership"
    if not database.worker_active or not database.worker_request_path
        or (not request and not membership_read) then
        return false
    end
    local cancel = io.open(database.worker_request_path .. ".cancel", "wb")
    if not cancel then return false end
    cancel:write(tostring(reason or "foreground request"), "\n")
    cancel:close()
    database.worker_status = "cancelling stale browser request"
    database.worker_cancel_requested = true
    database.worker_cancel_requested_at = r.time_precise()
    return true
end

-- A foreground view change invalidates every queued page/tag operation from
-- the previous view. Keeping the old request alive used to let a Favorites
-- or Random result replace the Library after the user had already navigated
-- away, and left selection row keys pointing into the old result set.
local function ResetCanonicalForegroundView(reason, clear_rows)
    local browser = state.canonical_browser
    local paging = state.canonical_paging
    if paging and paging.browser_request then
        CancelActiveCanonicalRead(reason or "browser view changed")
    end
    browser.view_generation = (browser.view_generation or 0) + 1
    browser.deferred_request = nil
    browser.pending_prefetch = nil
    browser.pending_tag_folder_id = nil
    browser.pending_tag_time = nil
    state.canonical_reveal = nil
    browser.next_cursor = nil
    if paging then
        paging.deferred_queued_at = nil
        paging.accordion_requested_at = nil
        paging.tag_requested_at = nil
    end
    browser.loading = false
    browser.clipper = nil
    browser._visible_rows_source = nil
    browser._visible_rows_scope = nil
    browser._visible_items = nil
    browser._visible_index = nil
    browser._visible_index_by_row_key = nil
    if clear_rows then
        browser.rows = {}
        browser.has_more = false
        browser.total_count = nil
        browser.loaded_file_count = nil
        browser.loaded_file_last_page_offset = nil
    end
end

-- The canonical scan is committed by a separate SQLite process while the
-- persistent reader stays open.  Recycle that reader after a commit so its
-- SQLite page/schema state is as clean as it is after a normal relaunch.
local function RequestDatabaseWorkerRefreshAfterLibraryCommit()
    local database = state.database
    if not database.worker_queue then
        return false
    end
    if database.worker_active then
        -- A page request owns the reader connection. Let it finish, then
        -- recycle the reader before any subsequent folder request is served.
        database.worker_refresh_requested = true
        database.worker_status = "Database worker refresh queued..."
        return true
    end
    if not database.worker_started then
        -- There is no live reader to recycle. Start a fresh one instead of
        -- leaving the first folder click to pay the process startup cost.
        database.worker_refresh_requested = false
        database.worker_prewarm_requested = true
        database.worker_status = "Warming database worker..."
        return true
    end
    local shutdown = io.open(database.worker_queue .. "/shutdown.req", "wb")
    if not shutdown then return false end
    shutdown:write("refresh after library commit\n")
    shutdown:close()
    database.worker_refresh_requested = false
    database.worker_restart_pending = true
    database.worker_restart_requested_at = r.time_precise()
    database.worker_started = false
    database.worker_status = "Refreshing database worker..."
    return true
end

local function CancelActiveBrowserReadForForegroundRequest()
    local paging = state.canonical_paging
    local request = paging and paging.browser_request
    if not request then return false end
    -- The worker owns a single read lane. A new foreground search/filter/random
    -- action supersedes whatever browser page or facet is currently using it;
    -- cancelling here keeps fast UI changes from queueing behind a slow query.
    -- The completion path already discards the interrupted result and starts
    -- browser.deferred_request immediately.
    return CancelActiveCanonicalRead("newer foreground browser request")
end

local function CanonicalOptionalReadsAllowed()
    return r.time_precise()
        >= (state.canonical_browser.optional_reads_suppressed_until or 0)
end

local function SuppressSlowCanonicalOptionalReads(elapsed_ms, request)
    if (tonumber(elapsed_ms) or 0) < SLOW_CANONICAL_QUERY_MS
        or not request then
        return false
    end
    local browser = state.canonical_browser
    browser.optional_reads_suppressed_until = math.max(
        browser.optional_reads_suppressed_until or 0,
        r.time_precise() + OPTIONAL_READ_COOLDOWN_SECONDS)
    browser.pending_prefetch = nil
    browser.pending_tag_folder_id = nil
    browser.pending_tag_time = nil
    return true
end

local function ShouldRequestExactCanonicalCount(mode, offset)
    if (tonumber(offset) or 0) ~= 0 then return false end
    -- Search/filter totals are cosmetic and inherently require completing the
    -- entire match. V5 returns page one immediately and reports the existing
    -- loaded-count-plus indicator instead.
    if mode == "browser_search" or mode == "browser_filter" then return false end
    local count = tonumber(state.database.library_file_count)
    if count and count >= LARGE_LIBRARY_FILE_COUNT then return false end
    return mode == "smart_favorites" or mode == "smart_collection"
end

local function PollDatabaseWorker()
    local database = state.database
    local result_path = database.worker_result_path
    if not result_path then return nil end
    local file = io.open(result_path, "rb")
    if not file then
        local started_at = database.worker_started_at or r.time_precise()
        local elapsed = math.max(0, r.time_precise() - started_at)
        local cancel_elapsed = database.worker_cancel_requested
            and math.max(0, r.time_precise()
                - (database.worker_cancel_requested_at or r.time_precise()))
            or 0
        if database.worker_cancel_requested and cancel_elapsed > 2 then
            -- Cancellation can race with the worker moving the request file.
            -- If no result is published, release the read lane so a library
            -- refresh cannot remain queued forever behind a dead request.
            if database.worker_request_path then
                pcall(os.remove, database.worker_request_path)
                pcall(os.remove, database.worker_request_path .. ".cancel")
            end
            pcall(os.remove, result_path)
            database.worker_active = false
            database.worker_cancelled = true
            database.worker_cancel_requested = false
            database.worker_cancel_requested_at = 0
            database.worker_request_path = nil
            database.worker_result_path = nil
            database.worker_started_at = nil
            database.write_active = false
            database.worker_fallback_sql = nil
            database.worker_fallback_count = nil
            database.worker_fallback_kind = nil
            database.worker_fallback_target = nil
            database.worker_status =
                "Cancelled stale browser request; refreshing worker."
            return false, "cancelled"
        end
        local heartbeat
        if database.worker_ready_path then
            local ready = io.open(database.worker_ready_path, "rb")
            if ready then
                heartbeat = tonumber((ready:read("*a") or ""):match("%d+"))
                ready:close()
            end
        end
        local startup_failed = elapsed > 2 and not heartbeat
        local worker_stale = heartbeat and os.time() - heartbeat > 5
        if not startup_failed and not worker_stale then return nil end

        -- A helper that failed before opening SQLite must never retain the
        -- only browser request lane indefinitely. Re-run the same read through
        -- the bundled SQLite CLI; the visible request and target stay intact.
        if database.worker_request_path then
            local cancel = io.open(database.worker_request_path .. ".cancel", "wb")
            if cancel then cancel:write("worker unavailable\n"); cancel:close() end
            pcall(os.remove, database.worker_request_path)
        end
        local sql = database.worker_fallback_sql
        local count = database.worker_fallback_count or 0
        local kind = database.worker_fallback_kind or "canonical_page"
        local target = database.worker_fallback_target
        database.worker_active = false
        database.worker_started = false
        database.worker_request_path = nil
        database.worker_result_path = nil
        database.worker_started_at = nil
        database.write_active = false
        database.worker_status = startup_failed
            and "worker startup failed; SQLite fallback"
            or "worker heartbeat lost; SQLite fallback"
        database.worker_fallback_sql = nil
        database.worker_fallback_count = nil
        database.worker_fallback_kind = nil
        database.worker_fallback_target = nil
        if sql then
            local fallback_ok, fallback_error = StartDatabaseCliBatchAsync(
                sql, count, kind, target)
            if fallback_ok then return nil end
            return false, fallback_error
        end
        return false, "Database worker stopped before returning a page."
    end
    local response = file:read("*a") or ""
    file:close()
    pcall(os.remove, result_path)
    if database.worker_request_path then
        pcall(os.remove, database.worker_request_path)
        pcall(os.remove, database.worker_request_path .. ".cancel")
    end
    database.worker_active = false
    database.worker_request_path = nil
    database.worker_result_path = nil
    database.write_active = false
    local _, status, elapsed, payload =
        response:match("^([^\t]*)\t([^\t]*)\t([^\t]*)\t?(.*)$")
    database.worker_cancelled = status == "cancelled"
    database.worker_cancel_requested = false
    database.worker_cancel_requested_at = 0
    database.worker_last_sql_ms = tonumber(elapsed) or 0
    database.worker_last_wait_ms = math.floor(
        math.max(0, r.time_precise() - (database.worker_started_at or 0))
            * 1000 + 0.5)
    local page_request = state.canonical_paging
        and state.canonical_paging.browser_request
    database.worker_started_at = nil
    database.worker_fallback_sql = nil
    database.worker_fallback_count = nil
    database.worker_fallback_kind = nil
    database.worker_fallback_target = nil
    if status ~= "ok" then
        return false, DecodeWorkerPayload(payload or response)
    end
    return true, nil, DecodeWorkerPayload(payload)
end

local function ClearDatabaseWriteProgress()
    local database = state.database
    if database.write_progress_path then
        pcall(os.remove, database.write_progress_path)
    end
    database.write_progress_path = nil
    database.write_progress_stage = nil
    database.write_progress_label = nil
    database.write_progress_done = 0
    database.write_progress_total = 0
    database.write_progress_stage_started_at = 0
    database.write_started_at = 0
end

local function PollDatabaseWriteProgress()
    local database = state.database
    local path = database.write_progress_path
    if not path then return end
    local file = io.open(path, "rb")
    if not file then return end
    local text = file:read("*a") or ""
    file:close()
    local stage, done, total, label
    for next_stage, next_done, next_total, next_label in text:gmatch(
        "RB_PROGRESS|([^|]*)|(%d+)|(%d+)|([^\r\n]*)") do
        stage, done, total, label =
            next_stage, next_done, next_total, next_label
    end
    if stage then
        if database.write_progress_stage ~= stage
            or database.write_progress_label ~= label then
            database.write_progress_stage_started_at = r.time_precise()
        end
        database.write_progress_stage = stage
        database.write_progress_label = label ~= "" and label or nil
        database.write_progress_done = tonumber(done) or 0
        database.write_progress_total = tonumber(total) or 0
    end
end

local function PollDatabaseBatchAsync()
    local database = state.database
    if database.write_active then PollDatabaseWriteProgress() end
    if database.worker_active or database.worker_result_path then
        return PollDatabaseWorker()
    end
    if not database.write_active then return nil end
    local done = io.open(database.done_path, "rb")
    if not done then return nil end
    local exit_code = tonumber((done:read("*a") or ""):match("-?%d+"))
    done:close()
    local output = ""
    local result = io.open(database.result_path, "rb")
    if result then output = result:read("*a") or ""; result:close() end
    pcall(os.remove, database.done_path)
    pcall(os.remove, database.result_path)
    database.write_active = false
    database.worker_active = false
    -- CLI writes run beside the persistent reader. Do not forget that reader
    -- exists here: doing so spawned a duplicate worker after every root scan
    -- and left the original reader carrying stale post-scan state.
    database.worker_request_path = nil
    database.worker_result_path = nil
    database.worker_started_at = nil
    if exit_code ~= 0 then
        ClearDatabaseWriteProgress()
        return false, "Database helper failed (" .. tostring(exit_code)
            .. "): " .. output
    end
    ClearDatabaseWriteProgress()
    return true, nil, output
end

local function QueryDatabaseScalar(sql)
    local database = state.database
    local command = ProcessQuote(database.helper_path)
        .. " -batch -bail -noheader " .. ProcessQuote(GetMediaDatabasePath())
        .. " " .. ProcessQuote(sql)
    local response = r.ExecProcess(command, 15000)
    if response == nil then return nil, "REAPER could not start the database helper." end
    response = tostring(response)
    local first_line, output = response:match("^([^\r\n]*)\r?\n?(.*)$")
    if tonumber(first_line) ~= 0 then
        return nil, "Database query failed (" .. tostring(first_line) .. "): "
            .. tostring(output or "")
    end
    return (output or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function QueryDatabaseScalarAtPath(path, sql, timeout_ms)
    local database = state.database
    local command = ProcessQuote(database.helper_path)
        .. " -batch -bail -noheader " .. ProcessQuote(path)
        .. " " .. ProcessQuote(sql)
    local response = r.ExecProcess(command, timeout_ms or 15000)
    if response == nil then return nil, "REAPER could not start the database helper." end
    response = tostring(response)
    local first_line, output = response:match("^([^\r\n]*)\r?\n?(.*)$")
    if tonumber(first_line) ~= 0 then
        return nil, "Database query failed (" .. tostring(first_line)
            .. "): " .. tostring(output or "")
    end
    return (output or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function GetCanonicalUserDataBackupPath()
    return GetReaBrowseDataDirectory() .. "/ReaBrowse_User_Data_Backup.sqlite3"
end

function PreserveCanonicalUserDataForReset(database_path)
    local backup_path = GetCanonicalUserDataBackupPath()
    pcall(os.remove, backup_path)
    local backup_sql = table.concat({
        "ATTACH DATABASE ", SQLQuote(backup_path), " AS preserved;",
        "CREATE TABLE preserved.saved_collections(external_key TEXT PRIMARY KEY,",
        "parent_external_key TEXT,name TEXT,created_at INTEGER,sort_order INTEGER);",
        "INSERT INTO preserved.saved_collections SELECT keys.external_key,",
        "parent_keys.external_key,c.name,c.created_at,c.sort_order FROM collections c ",
        "JOIN collection_external_keys keys ON keys.collection_id=c.id ",
        "LEFT JOIN collections parent ON parent.id=c.parent_id LEFT JOIN ",
        "collection_external_keys parent_keys ON parent_keys.collection_id=parent.id;",
        "CREATE TABLE preserved.saved_user_file_data(path_norm TEXT PRIMARY KEY,",
        "favorite INTEGER,notes TEXT,play_count INTEGER,last_used_at INTEGER,",
        "updated_at INTEGER);",
        "INSERT INTO preserved.saved_user_file_data SELECT files.canonical_path_norm,",
        "data.favorite,data.notes,data.play_count,data.last_used_at,data.updated_at ",
        "FROM user_file_data data JOIN files ON files.id=data.file_id;",
        "CREATE TABLE preserved.saved_collection_items(collection_key TEXT,",
        "kind TEXT,path_norm TEXT,added_at INTEGER,",
        "PRIMARY KEY(collection_key,kind,path_norm));",
        "INSERT OR IGNORE INTO preserved.saved_collection_items SELECT ",
        "CASE WHEN items.collection_id=-1 THEN '' ELSE keys.external_key END,",
        "'file',files.canonical_path_norm,items.added_at FROM collection_items items ",
        "JOIN files ON files.id=items.file_id LEFT JOIN collection_external_keys keys ",
        "ON keys.collection_id=items.collection_id WHERE items.collection_id=-1 ",
        "OR keys.external_key IS NOT NULL;",
        "INSERT OR IGNORE INTO preserved.saved_collection_items SELECT ",
        "CASE WHEN items.collection_id=-1 THEN '' ELSE keys.external_key END,",
        "'folder',roots.path_norm||CASE WHEN folders.relative_path_norm='' THEN '' ",
        "ELSE '/'||folders.relative_path_norm END,items.added_at FROM ",
        "collection_items items JOIN folders ON folders.id=items.folder_id JOIN roots ",
        "ON roots.id=folders.root_id LEFT JOIN collection_external_keys keys ON ",
        "keys.collection_id=items.collection_id WHERE items.collection_id=-1 ",
        "OR keys.external_key IS NOT NULL;",
        "CREATE TABLE preserved.saved_user_tags(path_norm TEXT,name TEXT,",
        "name_norm TEXT,confidence REAL,PRIMARY KEY(path_norm,name_norm));",
        "INSERT OR IGNORE INTO preserved.saved_user_tags SELECT ",
        "files.canonical_path_norm,tags.name,tags.name_norm,file_tags.confidence ",
        "FROM file_tags JOIN files ON files.id=file_tags.file_id JOIN tags ON ",
        "tags.id=file_tags.tag_id WHERE file_tags.source='user';",
        "CREATE TABLE preserved.saved_exclusions(path_norm TEXT,tag_norm TEXT,",
        "updated_at INTEGER,PRIMARY KEY(path_norm,tag_norm));",
        "INSERT INTO preserved.saved_exclusions SELECT files.canonical_path_norm,",
        "excluded.tag_norm,excluded.updated_at FROM file_tag_exclusions excluded ",
        "JOIN files ON files.id=excluded.file_id;",
        "CREATE TABLE preserved.saved_overrides(scope_type TEXT,path_norm TEXT,",
        "classification TEXT,created_at INTEGER,updated_at INTEGER,",
        "PRIMARY KEY(scope_type,path_norm));",
        "INSERT INTO preserved.saved_overrides SELECT scope_type,path_norm,",
        "classification,created_at,updated_at FROM classification_overrides;",
        "CREATE TABLE preserved.saved_key_overrides(path_norm TEXT PRIMARY KEY,",
        "key_pc INTEGER,detected_key_pc INTEGER,created_at INTEGER,",
        "updated_at INTEGER);",
        "INSERT INTO preserved.saved_key_overrides SELECT path_norm,key_pc,",
        "detected_key_pc,created_at,updated_at FROM key_overrides;",
        "DETACH DATABASE preserved;",
    })
    -- This is a multi-statement write, not a scalar query. Passing the whole
    -- preservation program on the Windows process command line is fragile
    -- (and can fail before SQLite sees it). Use the established batch-file
    -- writer so quoting and command length are independent of user-data size.
    local preserved, err = WriteDatabaseBatch(
        backup_sql, nil, database_path)
    if not preserved then
        pcall(os.remove, backup_path)
        return false, err
    end
    return true
end

-- Read the preserved scan result for diagnostics. This is cached and only
-- queried when a user opens classification UI; normal browsing remains on
-- the existing indexed effective classification path.
local function GetAutomaticCategoryKey(filepath, node)
    if IsMidiFile(filepath) then return "midi" end
    local normalized = NormalizeFavoritePath(filepath)
    local cached = state.automatic_class_by_path[normalized]
    if cached then return cached end

    local from_node = node and (node.automatic_classification
        or node._automatic_classification)
    if from_node == "loop" or from_node == "one-shot"
        or from_node == "other" then
        state.automatic_class_by_path[normalized] = from_node
        return from_node
    end

    if state.database_startup_test.enabled
        and state.database.backend == "sqlite"
        and FileExists(GetCanonicalDatabasePath()) then
        local output = QueryDatabaseScalarAtPath(
            GetCanonicalDatabasePath(),
            "SELECT CASE WHEN media_type='midi' THEN 'midi' ELSE "
                .. "COALESCE(automatic_classification,'other') END FROM files "
                .. "WHERE canonical_path_norm=" .. SQLQuote(normalized)
                .. " LIMIT 1;")
        if output == "loop" or output == "one-shot"
            or output == "midi" or output == "other" then
            state.automatic_class_by_path[normalized] = output
            return output
        end
    end

    local automatic = ClassifyAutomaticMedia(filepath)
    state.automatic_class_by_path[normalized] = automatic
    return automatic
end

local function GetClassificationDisplaySummary(paths, node)
    local detected, effective, overrides = {}, {}, {}
    local detected_unavailable = false
    local visible_by_path = {}
    for _, visible in ipairs(state.visible_items or {}) do
        if visible.type == "file" and visible.path then
            visible_by_path[NormalizeFavoritePath(visible.path)] = visible
        end
    end
    for _, path in ipairs(paths or {}) do
        -- Multi-selection is limited to loaded visible rows. Use those rows'
        -- scan classifications instead of launching one synchronous SQLite
        -- process per selected file while drawing the Category submenu.
        local row_node = (#paths == 1 and node)
            or visible_by_path[NormalizeFavoritePath(path)]
        local normalized = NormalizeFavoritePath(path)
        local override = GetManualOverrideInfo(path)
        local automatic = state.automatic_class_by_path[normalized]
            or (row_node and (row_node.automatic_classification
                or row_node._automatic_classification))
        -- Without an override, the loaded effective class is necessarily the
        -- automatic class. With an override, do not synchronously query SQLite
        -- merely to decorate a context submenu.
        if not automatic and not override and row_node then
            automatic = row_node.classification
        end
        if automatic then
            detected[#detected + 1] = automatic
        else
            detected_unavailable = true
        end
        effective[#effective + 1] = ResolveEffectiveMediaClass(
            path, row_node and row_node.classification)
        if override then overrides[#overrides + 1] = override end
    end
    local detected_summary = #detected > 0
        and SummarizeClassification(detected) or "Unavailable"
    if detected_unavailable and #detected > 0 then
        detected_summary = detected_summary .. ", unavailable"
    end
    return detected_summary,
        #overrides > 0 and SummarizeClassification(overrides) or "None",
        SummarizeClassification(effective)
end

function SetMediaDatabaseUnavailable(status, message)
    local database = state.database
    local detail = message and tostring(message) or nil
    database.backend = "unavailable"
    database.canonical = false
    database.capabilities = {
        canonical_queries = false,
        paged_browser = false,
        database_random = false,
        background_scan_commit = false,
    }
    database.status = status or "SQLite database unavailable"
    database.error = detail
    database.pending_init = false
    database.queue = {}
    database.queue_head = 1
    database.queued_index = {}
    database.scan_active = false
    database.finalize_pending = false
    database.write_active = false
    database.cancel_after_write = false
    state.folder_tree = {}
    state.canonical_browser.rows = {}
    state.canonical_browser.loading = false
    state.canonical_browser.accordion_error = detail
        or database.status
    state.canonical_browser.error = nil
    state.pending_scan_root = nil
    state.pending_scan_root_is_new = false
    state.needs_refresh = false
    state.library_scan.scanning = false
    state.library_scan.operation_kind = nil
    state.library_scan.phase = nil
    state.library_scan.queue = {}
    state.library_scan.roots = {}
    state.canonical_scan_sync.importing = false
end

function InitializeMediaDatabase()
    local database = state.database
    if not EnsureReaBrowseDataLayout() then
        SetMediaDatabaseUnavailable(
            "ReaBrowse database unavailable",
            "Could not create the ReaBrowse data directory.")
        return false
    end
    SetMediaDatabaseUnavailable("Preparing SQLite database", nil)
    database.rebuild_required = false
    database.schema_version = 0

    local os_name = (r.GetOS() or ""):lower()
    local app_version = (r.GetAppVersion() or ""):lower()
    if not os_name:find("win", 1, true) or app_version:find("arm64", 1, true) then
        SetMediaDatabaseUnavailable(
            "SQLite database unavailable",
            "This package currently requires the Windows x64 database helper.")
        return false
    end

    database.helper_path = GetScriptDirectory():gsub("[/\\]+$", "") .. "/sqlite3.exe"
    if not FileExists(database.helper_path) then
        SetMediaDatabaseUnavailable(
            "SQLite database unavailable",
            "The bundled SQLite database helper was not found. Reinstall ReaBrowse and restart REAPER.")
        return false
    end
    local data_dir = GetReaBrowseDataDirectory()
    if r.RecursiveCreateDirectory then
        r.RecursiveCreateDirectory(data_dir, 0)
        r.RecursiveCreateDirectory(data_dir .. "/sidecar", 0)
    end
    CleanupStaleSidecarFiles(data_dir)
    local sidecar_dir = data_dir .. "/sidecar"
    database.batch_path = sidecar_dir .. "/ReaBrowse_Sidecar_Batch_"
        .. tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999)) .. ".sql"
    local sidecar_token = tostring(os.time()) .. "_"
        .. tostring(math.random(100000, 999999))
    database.runner_path = sidecar_dir
        .. "/ReaBrowse_Sidecar_Run_" .. sidecar_token .. ".cmd"
    database.launcher_path = sidecar_dir
        .. "/ReaBrowse_Sidecar_Launch_" .. sidecar_token .. ".vbs"
    database.result_path = sidecar_dir
        .. "/ReaBrowse_Sidecar_Result_" .. sidecar_token .. ".txt"
    database.done_path = sidecar_dir
        .. "/ReaBrowse_Sidecar_Done_" .. sidecar_token .. ".txt"
    local script_dir = GetScriptDirectory():gsub("[/\\]+$", "")
    local worker_candidates = {
        script_dir .. "/worker/publish/win-x64/ReaBrowseWorker.exe",
        script_dir .. "/worker/bin/Release/net10.0/win-x64/ReaBrowseWorker.exe",
        script_dir .. "/worker/bin/Debug/net10.0/win-x64/ReaBrowseWorker.exe",
    }
    -- Release packages use the published self-contained worker. The other
    -- locations keep the source-tree build runnable during development and
    -- prevent a missing publish artifact from leaving scans waiting forever.
    database.worker_path = worker_candidates[1]
    for _, candidate in ipairs(worker_candidates) do
        if FileExists(candidate) then
            database.worker_path = candidate
            break
        end
    end
    -- Use a session-specific queue so a stale worker from a prior script
    -- reload can never consume requests for the current worker protocol.
    -- A healthy protocol-compatible queue is safe to adopt, however: request
    -- tokens are unique and the worker serializes them. Reusing it avoids a
    -- new session waiting behind the previous worker's database-wide lock.
    local reusable_worker_queue = nil
    local queue_index = 0
    while true do
        local queue_name = r.EnumerateSubdirectories(sidecar_dir, queue_index)
        if not queue_name then break end
        queue_index = queue_index + 1
        if queue_name:match("^worker_queue_") then
            local candidate = sidecar_dir .. "/" .. queue_name
            local ready = io.open(candidate .. "/worker.ready", "rb")
            local ready_text = ready and (ready:read("*a") or "") or ""
            if ready then ready:close() end
            local heartbeat, protocol = ready_text:match("^(%d+)|(%d+)|")
            if tonumber(protocol) == DATABASE_WORKER_PROTOCOL_VERSION
                and tonumber(heartbeat)
                and os.time() - tonumber(heartbeat) <= 5 then
                reusable_worker_queue = candidate
                break
            end
        end
    end
    database.worker_queue = reusable_worker_queue
        or (sidecar_dir .. "/worker_queue_" .. sidecar_token)
    database.worker_ready_path = database.worker_queue .. "/worker.ready"
    database.worker_owner_path = database.worker_queue .. "/owner.ready"
    database.worker_launcher_path = sidecar_dir .. "/ReaBrowse_Worker_"
        .. sidecar_token .. ".vbs"
    database.worker_started = reusable_worker_queue ~= nil
    database.worker_active = false
    database.worker_restart_pending = false
    database.worker_restart_requested_at = 0
    database.worker_refresh_requested = false
    database.compact_requested = false
    database.worker_request_path = nil
    database.worker_result_path = nil
    database.worker_owner_last_write = nil
    -- Defer the cold launch until after the first window exists. The process
    -- is then ready before the user opens their first folder.
    database.worker_prewarm_requested = reusable_worker_queue == nil
    if reusable_worker_queue then
        local owner = io.open(database.worker_owner_path, "wb")
        if owner then
            owner:write(tostring(os.time()), "\n")
            owner:close()
            database.worker_owner_last_write = r.time_precise()
        end
        database.worker_status = "adopted warm worker"
    end
    database.pending_init = true
    database.status = "Database init deferred (will complete after window opens)"
    return true
end

function CloseMediaDatabase()
    local database = state.database
    database.worker_refresh_requested = false
    database.compact_requested = false
    -- The Lua state can already have marked the worker unavailable after a
    -- timeout even though the process is still draining its queue. Signal
    -- shutdown from the queue/ready files as well as worker_started so that
    -- closing ReaBrowse never leaves an orphaned sidecar worker behind.
    local worker_present = database.worker_queue
        and (database.worker_started
            or (database.worker_ready_path
                and FileExists(database.worker_ready_path)))
    if worker_present then
        local shutdown = io.open(database.worker_queue .. "/shutdown.req", "wb")
        if shutdown then shutdown:write("shutdown\n"); shutdown:close() end
        database.worker_started = false
    end
    -- The worker also watches this heartbeat. Removing it makes shutdown
    -- deterministic even if shutdown.req cannot be opened or consumed.
    if database.worker_owner_path then
        pcall(os.remove, database.worker_owner_path)
    end
    -- A no-wait SQLite commit may still be consuming these files during
    -- script shutdown. Leave that tiny set in place rather than risking an
    -- interrupted committed batch; a later maintenance pass can remove it.
    if database and database.write_active then return end
    if database and database.batch_path then
        pcall(os.remove, database.batch_path)
    end
    if database then
        if database.runner_path then pcall(os.remove, database.runner_path) end
        if database.launcher_path then pcall(os.remove, database.launcher_path) end
        if database.worker_launcher_path then
            pcall(os.remove, database.worker_launcher_path)
        end
        if database.result_path then pcall(os.remove, database.result_path) end
        if database.done_path then pcall(os.remove, database.done_path) end
    end
    -- If the worker had already published that it was gone, reclaim the
    -- session queue immediately. Otherwise the worker owns its queue until it
    -- consumes shutdown.req (or observes the removed owner heartbeat) and
    -- will delete it itself after releasing SQLite locks.
    if database and database.worker_queue
        and not FileExists(database.worker_ready_path or "") then
        CleanupWorkerQueuePath(database.worker_queue)
    end
end

local function ClearReaBrowseSettings()
    if not r.DeleteExtState then return end
    local root_count = tonumber(r.GetExtState(EXT_SECTION, "root_count")) or 0
    for index = 1, math.max(0, math.floor(root_count)) do
        r.DeleteExtState(EXT_SECTION, "root_" .. tostring(index), true)
    end
    for _, key in ipairs({
        "root_paths", "root_count", "auto_play",
        "preview_transport_mode",
        "loop_preview", "tempo_match_enabled", "one_shot_mode",
        "scan_speed",
        "audio_auto_one_shot", "one_shot_bypass_sync",
        "external_drag_default_native", "one_shot_native_drag",
        "one_shot_bypass_loop", "one_shot_bypass_tempo_match",
        "one_shot_bypass_key_sync", "one_shot_bypass_playrate",
        "randomize_on", "playrate", "pitch_shift", "audio_volume_db",
        "audio_route_mode", "audio_route_output_channel",
        "audio_route_output_mono", "media_tag_bar_open", "tag_sort_mode",
        "piano_open", "media_tag_height",
        "favorite_sort", "show_favorite_column",
        "theme_use_custom", "theme_window_bg",
        "theme_panel_bg", "theme_text", "theme_selected_text", "theme_accent",
        "theme_header_icon", "theme_border", "theme_folder_text",
        "theme_midi_note", "theme_preview_bg", "theme_preview_grid",
        "theme_font_name", "theme_font_size", "key_sync_enabled",
        "key_sync_target_pc", "FXFavoriteFolders", "FXFavorites", "FXUsage",
        "FXTypeFilter", "FXViewMode", "FXSortMode", "FXFormatFilters",
        "ActionFavoriteFolders", "ActionFavorites", "ActionUsage",
        "ActionViewMode", "ActionSortMode", "ActionSectionFilter",
    }) do
        r.DeleteExtState(EXT_SECTION, key, true)
    end
    for _, key in ipairs(THEME_COLOR_KEYS or {}) do
        r.DeleteExtState(EXT_SECTION, "theme_suggestions_" .. key, true)
    end
    -- Factory reset changes ExtState outside SaveSettings' incremental writer.
    -- Discard its comparison cache so any later save in this process reads the
    -- newly empty durable state instead of assuming deleted values still exist.
    state.settings_persisted_values = {}
    state.settings_persisted_loaded = {}
end

local function DeleteCanonicalLibraryDatabase(factory_reset)
    local database = state.database
    if database.write_active or database.worker_active
        or state.canonical_paging.active or database.scan_active
        or state.library_scan.scanning then
        database.status = "Finish the current library task first."
        return false
    end
    if database.worker_started then
        CloseMediaDatabase()
        database.status =
            "Worker stopping - click Delete Database again."
        return false
    end
    if database.worker_queue
        and FileExists(database.worker_queue .. "/worker.ready") then
        database.status =
            "Worker still stopping - try again shortly."
        return false
    end
    CloseMediaDatabase()
    local target = GetCanonicalDatabasePath()
    if not factory_reset and FileExists(target) then
        local preserved, preserve_error =
            PreserveCanonicalUserDataForReset(target)
        if not preserved then
            database.status = "Library database was not deleted"
            database.error = "Favorites and user tags could not be backed up: "
                .. tostring(preserve_error or "unknown error")
            return false
        end
    end
    local worker_queue = database.worker_queue
    CleanupWorkerQueuePath(worker_queue)
    local removed = false
    local delete_paths = {
        target, target .. "-wal", target .. "-shm",
        target .. ".worker.lock",
        GetReaBrowseDataDirectory() .. "/ReaBrowse_Library_Cache.tsv",
    }
    if factory_reset then
        delete_paths[#delete_paths + 1] = GetReaBrowseDataDirectory()
            .. "/ReaBrowse_Library_Cache.tsv.writing"
        delete_paths[#delete_paths + 1] = GetReaBrowseDataDirectory()
            .. "/ReaBrowse_Library_Cache.tsv.previous"
        delete_paths[#delete_paths + 1] = GetFXInventoryCachePath()
        delete_paths[#delete_paths + 1] = GetReaBrowseDataDirectory()
            .. "/ReaBrowse_Actions_Inventory.tsv"
        -- Remove the obsolete file if an older ReaBrowse build created it.
        delete_paths[#delete_paths + 1] = GetReaBrowseDataDirectory()
            .. "/ReaBrowse_Ratings.tsv"
        delete_paths[#delete_paths + 1] = GetReaBrowseDataDirectory()
            .. "/layout.version"
        delete_paths[#delete_paths + 1] = GetCanonicalUserDataBackupPath()
    end
    for _, path in ipairs(delete_paths) do
        if FileExists(path) then
            local call_ok, remove_result = pcall(os.remove, path)
            if call_ok and remove_result then removed = true end
        end
    end
    if FileExists(target) then
        database.status = "Library database could not be deleted"
        database.error = "The database file is still in use or not writable."
        return false
    end
    for _, path in ipairs(delete_paths) do
        if FileExists(path) then
            database.status = factory_reset
                and "Factory reset could not remove all ReaBrowse data"
                or "Library database could not be deleted"
            database.error = "A ReaBrowse data file is still in use or not writable."
            return false
        end
    end
    -- Treat database deletion as a clean-install reset. Retaining configured
    -- roots would cause a scan on the next launch before the user adds a
    -- folder again.
    state.root_folders = {}
    state.pending_root_removal = nil
    SaveSettings()
    state.canonical_browser.rows = {}
    state.canonical_browser.cache = {}
    state.canonical_browser.cache_order = {}
    state.canonical_browser.tag_catalog_cache = {}
    state.canonical_browser.tag_catalog_cache_order = {}
    state.canonical_browser.folder_scope_counts = {}
    state.canonical_browser.favorite_scope_counts = {}
    state.canonical_browser.favorite_scope_upper_bounds = {}
    state.canonical_browser.available_tags = {}
    state.canonical_browser.error = nil
    state.canonical_browser.status = factory_reset
        and "Factory reset complete; restart ReaBrowse."
        or "Library reset; preparing an empty database..."
    state.canonical_browser.loading = false
    state.canonical_browser.smart_mode = nil
    state.canonical_browser.collection_key = nil
    state.canonical_browser.collection_scope_key = nil
    state.canonical_browser.deferred_request = nil
    state.canonical_browser.pending_prefetch = nil
    state.canonical_browser.pending_tag_folder_id = nil
    state.canonical_browser.pending_tag_time = nil
    state.canonical_browser.optional_reads_suppressed_until = 0
    state.canonical_browser.accordion_loading = false
    state.canonical_browser.accordion_error = nil
    database.library_file_count = nil
      state.folder_tree = {}
      state.favorite_tree = {}
      state.favorite_folder_id_cache = {}
    if factory_reset then
        state.favorites = {}
        state.favorite_index = {}
        state.favorite_index_dirty = false
        state.favorite_lookup_miss = {}
        state.favorite_membership_cache = {}
        state.favorite_membership_pending_paths = {}
        state.favorite_membership_inflight_paths = {}
        state.favorite_membership_next_at = 0
        state.favorite_membership_query_pending = false
        state.favorite_mutation_pending = {}
        state.favorite_mutation_inflight = {}
        state.favorite_mutation_versions = {}
        state.favorite_mutation_next_frame = 0
        state.favorite_pending_overrides = {}
        state.favorite_collections = {}
        state.media_user_tags = {}
        state.media_tags_file_present = false
        ClearReaBrowseSettings()
    end
    state.open_folders = {}
    state.favorite_open_folders = {}
    state.selected_path = nil
    state.selected_folder_scope = nil
    state.pending_scan_root = nil
    state.pending_scan_root_is_new = false
    state.needs_refresh = false
    state.search_active = false
    state.search_text = ""
    state.cached_search_results = {}
    state.media_filters.selected_tags = {}
    state.media_filters.quick_types = {}
    state.media_filters.key_pc = -1
    state.media_filters.tag_text = ""
    state.force_search_update = true
    state.needs_visible_update = true
    -- A database reset must also invalidate every derived in-memory view.
    -- Otherwise a same-session reset can briefly expose rows from the old
    -- database even though the authoritative tree has been cleared.
    state.search_index_by_path = {}
    state.visible_index_by_path = {}
    state.media_filter_index = {
        ready = false,
        building = false,
        stack = {},
        files = {},
        by_tag = {},
        by_class = {
            ["loop"] = {}, ["one-shot"] = {},
            ["midi"] = {}, ["other"] = {},
        },
        seen_paths = {},
        duplicate_count = 0,
        build_mode = "full",
        session_count = 0,
        indexed_count = 0,
        requested = false,
    }
    state.media_tag_facets = {
        building = false,
        scope = nil,
        stack = {},
        counts = {},
        files = {},
        by_tag = {},
        by_class = {},
        processed = 0,
    }
    state.media_tag_bar.cache_key = nil
    state.media_tag_bar.tags = {}
    state.media_tag_bar.tags = {}
    state.media_tag_bar.stable_key = nil
    state.media_tag_bar.stable_order = {}
    state.media_tag_bar.stable_tags = {}
    state.media_tag_bar.catalog_complete = false
    state.canonical_paging.active = false
    state.canonical_paging.browser_request = nil
    state.canonical_paging.rows = {}
    state.canonical_paging.has_more = false
    state.canonical_paging.step = nil
    state.canonical_paging.error = nil
    state.classification_overrides = {}
    state.key_overrides = {}
    state.key_override_generation =
        (state.key_override_generation or 0) + 1
    state.media_class_by_path = {}
    state.automatic_class_by_path = {}
    state.favorite_smart_mode = nil
    state.favorites_mode = false
    local sync = state.canonical_scan_sync
    if sync.manifest_file then
        pcall(function() sync.manifest_file:close() end)
        sync.manifest_file = nil
    end
    if sync.manifest_path then pcall(os.remove, sync.manifest_path) end
    sync.manifest_path = nil
    sync.ready = false
    sync.validated = false
    sync.apply_requested = false
    sync.importing = false
    sync.newly_added_root = nil
    sync.error = nil
    sync.status = "No completed scan delta"
    state.canonical_user_data.queue = {}
    state.canonical_user_data.queue_head = 1
    state.canonical_user_data.queue_tail = 0
    state.canonical_user_data.queue_key_index = {}
    if state.canonical_user_data.journal_file then
        pcall(state.canonical_user_data.journal_file.close,
            state.canonical_user_data.journal_file)
        state.canonical_user_data.journal_file = nil
    end
    state.canonical_user_data.inflight = {}
    state.canonical_user_data.journal_loaded = true
    pcall(os.remove, GetCanonicalUserDataJournalPath())
    pcall(os.remove, GetCanonicalUserDataJournalPath() .. ".writing")
    pcall(os.remove, GetCanonicalUserDataJournalPath() .. ".previous")
    database.backend = "none"
    database.canonical = false
    database.rebuild_required = false
    database.pending_init = false
    database.worker_active = false
    database.worker_restart_pending = false
    database.worker_restart_requested_at = 0
    database.worker_result_path = nil
    state.database_startup_test.enabled = false
    database.status = factory_reset
        and "Factory reset complete; restart ReaBrowse."
        or "Library reset; preparing an empty database..."
    if not factory_reset then
        -- Reuse the normal deferred startup path to recreate schema v5,
        -- restore the preserved user-data backup, and launch a fresh worker.
        -- Root controls remain disabled only for these initialization frames
        -- and no ReaBrowse/REAPER relaunch is required.
        state.lazy_init_frame = 0
        state.lazy_init_pending = true
    end
    return removed or not FileExists(target)
end

local function DisableMediaDatabase(message)
    SetMediaDatabaseUnavailable(
        "SQLite database unavailable; restart ReaBrowse after correcting the error",
        message or "Unknown database error")
end

local function StartCanonicalDatabaseCompactionNow()
    local database = state.database
    local scan = state.library_scan
    local progress_path = GetReaBrowseDataDirectory() .. "/Compact_Progress_"
        .. tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999))
        .. ".txt"
    pcall(os.remove, progress_path)
    database.write_progress_path = progress_path
    local progress_file = progress_path:gsub("\\", "/"):gsub('"', '""')
    local function progress(stage, done, total, label)
        return ".output \"" .. progress_file .. "\"\n"
            .. ".print RB_PROGRESS|" .. tostring(stage) .. "|"
            .. tostring(done or 0) .. "|" .. tostring(total or 0) .. "|"
            .. tostring(label or "") .. "\n.output stdout\n"
    end
    local sql = table.concat({
        progress("checkpoint", 0, 1, "Preparing database"),
        "PRAGMA wal_checkpoint(TRUNCATE);\n",
        progress("checkpoint", 1, 1, "Database prepared"),
        progress("vacuum", 0, 1, "Reclaiming unused space"),
        "VACUUM;\n",
        progress("vacuum", 1, 1, "Unused space reclaimed"),
        progress("optimize", 0, 1, "Optimizing indexes"),
        "PRAGMA optimize;\n",
        progress("optimize", 1, 1, "Indexes optimized"),
    })
    local ok, err = StartDatabaseBatchAsync(
        sql, 0, "canonical_compact", GetCanonicalDatabasePath())
    if not ok then
        ClearDatabaseWriteProgress()
        EndBlockingLibraryOperation(
            "Database compaction could not start.", err)
        return false
    end
    scan.phase = "compact"
    scan.phase_started_at = r.time_precise()
    scan.phase_label = "Compacting database"
    scan.phase_detail = "Preparing database"
    database.status = "Compacting database; this may take a while..."
    database.error = nil
    return true
end

function CompactCanonicalLibraryDatabase()
    local database = state.database
    if database.backend ~= "sqlite"
        or not state.database_startup_test.enabled
        or not FileExists(GetCanonicalDatabasePath()) then
        database.status = "The SQLite library database is not available."
        return false
    end
    if RootLibraryActionsBlocked()
        or database.write_active
        or state.canonical_paging.active
        or CanonicalUserDataQueueCount(state.canonical_user_data) > 0
        or #(state.canonical_user_data.inflight or {}) > 0 then
        database.status = "Finish the current library task before compacting."
        return false
    end
    BeginBlockingLibraryOperation(
        "compact", "compact_prepare", "Preparing database compaction",
        "Closing the database reader")
    database.compact_requested = true
    database.worker_prewarm_requested = false
    if database.worker_started then
        if not RequestDatabaseWorkerRefreshAfterLibraryCommit() then
            database.compact_requested = false
            EndBlockingLibraryOperation(
                "Database compaction could not prepare the database reader.",
                database.worker_status)
            return false
        end
        return true
    end
    database.compact_requested = false
    return StartCanonicalDatabaseCompactionNow()
end

local function BeginMediaDatabaseScan(incremental)
    local database = state.database
    -- The legacy media_files writer is retired. Canonical scans own all
    -- database writes through roots/folders/files/folder_files.
    database.scan_active = false
    database.finalize_pending = false
end

local function QueueMediaDatabaseFile(entry)
    -- Retained as a call-site no-op while the scan pipeline is being
    -- consolidated on the canonical schema.
    return
end

local function MakeMediaDatabaseUpsert(entry, generation)
    local sql = "INSERT INTO media_files(path,path_norm,name,extension,media_type,"
        .. "last_seen_generation,missing) VALUES("
        .. table.concat({
            SQLQuote(entry.path), SQLQuote(entry.path_norm), SQLQuote(entry.name),
            SQLQuote(entry.extension), SQLQuote(entry.media_type),
            tostring(generation), "0"
        }, ",") .. ") ON CONFLICT(path_norm) DO UPDATE SET "
        .. "path=excluded.path,name=excluded.name,extension=excluded.extension,"
        .. "media_type=excluded.media_type,"
        .. "last_seen_generation=excluded.last_seen_generation,missing=0;\n"
    local tags = GetMediaUserTags(entry.path) or {}
    sql = sql .. "DELETE FROM file_tags WHERE source='user' AND file_id="
        .. "(SELECT id FROM media_files WHERE path_norm=" .. SQLQuote(entry.path_norm) .. ");\n"
    for _, tag in ipairs(tags) do
        sql = sql .. "INSERT INTO tags(name) VALUES(" .. SQLQuote(tag)
            .. ") ON CONFLICT(name) DO NOTHING;\n"
            .. "INSERT INTO file_tags(file_id,tag_id,source,confidence) "
            .. "SELECT media_files.id,tags.id,'user',1.0 FROM media_files,tags "
            .. "WHERE media_files.path_norm=" .. SQLQuote(entry.path_norm)
            .. " AND tags.name=" .. SQLQuote(tag)
            .. " ON CONFLICT(file_id,tag_id,source) DO NOTHING;\n"
    end
    local generated_names = {}
    for _, tag in ipairs(entry.generated_tags or {}) do
        generated_names[#generated_names + 1] =
            tag.source .. ":" .. tag.name
    end
    sql = sql .. "INSERT INTO generated_media_tags(file_id,tags_text,tag_version) "
        .. "SELECT id," .. SQLQuote(table.concat(generated_names, "|"))
        .. ",2 FROM media_files WHERE path_norm=" .. SQLQuote(entry.path_norm)
        .. " ON CONFLICT(file_id) DO UPDATE SET "
        .. "tags_text=excluded.tags_text,tag_version=excluded.tag_version;\n"
    return sql
end

local function ParseCanonicalPageRows(output, page_size)
    local function decode_hex(value)
        if not value or value == "" then return "" end
        return (value:gsub("%x%x", function(pair)
            return string.char(tonumber(pair, 16))
        end))
    end
    local rows = {}
    local total_count = nil
    for line in tostring(output or ""):gmatch("[^\r\n]+") do
        local count_value = line:match("^N\t(%d+)$")
        if count_value then total_count = tonumber(count_value) end
        local favorite_upper_bound = line:match("^S\t(%d+)$")
        if favorite_upper_bound then
            local browser = state.canonical_browser
            browser.favorite_scope_upper_bounds =
                browser.favorite_scope_upper_bounds or {}
            browser.favorite_scope_upper_bounds["__all_favorites__"] =
                tonumber(favorite_upper_bound)
        end
        local fields = {}
        for field in (line .. "\t"):gmatch("(.-)\t") do
            fields[#fields + 1] = field
        end
        if fields[1] ~= "N" and fields[1] ~= "S" and #fields >= 6 then
            local row = {
                kind = fields[1],
                id = tonumber(fields[2]) or 0,
                name = decode_hex(fields[3]),
                path = decode_hex(fields[4]),
                media_type = fields[5] or "",
                folder_id = tonumber(fields[6]) or 0,
                classification = fields[7] or "",
                subtree_file_count = tonumber(fields[8]),
                -- Keep the 63-bit SQLite key as text. Lua numbers cannot
                -- represent every INTEGER value exactly enough for a cursor.
                random_key = fields[8] ~= "" and fields[8] or nil,
                -- Loose Favorites-root pages append the file's custom-folder
                -- ownership. Hydrating that bounded page prevents removing
                -- root ownership from temporarily clearing the global heart.
                favorite_collection_keys = fields[9] or "",
            }
            if row.kind == "F" and (row.classification == "loop"
                or row.classification == "one-shot"
                or row.classification == "midi" or row.classification == "other") then
                state.media_class_by_path[NormalizeFavoritePath(row.path)] =
                    row.classification
            end
            if row.kind == "R" then row.name = GetFileName(row.path) end
            rows[#rows + 1] = row
        end
    end
    local has_more = #rows > page_size
    while #rows > page_size do table.remove(rows) end
    return rows, has_more, total_count
end


local function GetCanonicalBrowserSelectedTags()
    local selected = {}
    for name, enabled in pairs(
        state.canonical_browser.selected_tags or {}) do
        if enabled then selected[#selected + 1] = NormalizeTag(name) end
    end
    table.sort(selected)
    return selected
end

-- Return the cached/indexed Favorites scope count used by the navigation
-- label.  The count is informational; result views still use bounded pages
-- and never hydrate the complete Favorites result set into Lua.
function GetFavoritesUniqueFileCount(extra_entries, force_refresh)
    local count = nil
    -- Never run a shell-backed aggregate synchronously from the draw loop.
    -- A large database can make that read monopolize Reaper's UI thread after
    -- a favorite mutation invalidates the cached value. Use the last indexed
    -- value when available; the bounded Favorites pages remain authoritative.
    if state.database.canonical then
        local cached = state.canonical_browser.favorite_scope_counts
            and state.canonical_browser.favorite_scope_counts[
                "__all_favorites__"]
        count = cached
    end
    if count == nil then
        count = #state.favorites
    end
    return math.max(0, math.floor(tonumber(count) or 0)), false, true
end

function GetCanonicalFavoriteScopeCount(collection_key)
    local browser = state.canonical_browser
    browser.favorite_scope_counts = browser.favorite_scope_counts or {}
    local cache_key = collection_key or "__all_favorites__"
    local cached = browser.favorite_scope_counts[cache_key]
    -- Exact counts remain informational. Query planning may also use the cheap
    -- startup upper bound; an overestimate can only select the more conservative
    -- streaming plan and can never omit a favorite.
    if cached ~= nil then return cached end
    return browser.favorite_scope_upper_bounds
        and browser.favorite_scope_upper_bounds[cache_key] or nil
end

local function BuildCanonicalUnifiedMatchCTE(
    folder_id, exclude_ids, minimum_random_key_sql, force_random_index,
    smart_mode_override, minimum_file_id, prefer_tag_source,
    collection_key_override, minimum_random_id)
    local browser = state.canonical_browser
    local smart_mode = smart_mode_override or browser.smart_mode
    local ctes = {}
    local joins = {}
    local where = {
        "files.missing=0 AND (files.file_size IS NULL OR files.file_size>0)"}
    -- Smart user-data views are sparse. Drive them from user_file_data so an
    -- empty or tiny Favorites/Recent/Used view never walks the whole library.
    local files_source = "files "
    if smart_mode == "smart_recent" then
        files_source = "user_file_data AS matched_user INDEXED BY "
            .. "idx_user_file_recent JOIN files ON files.id="
            .. "matched_user.file_id "
        where[#where + 1] = "matched_user.last_used_at IS NOT NULL"
    elseif smart_mode == "smart_used" then
        files_source = "user_file_data AS matched_user INDEXED BY "
            .. "idx_user_file_used JOIN files ON files.id="
            .. "matched_user.file_id "
        where[#where + 1] = "matched_user.play_count>0"
    end

    local scoped_collection_key = smart_mode == "smart_collection"
        and (collection_key_override or browser.collection_key)
        or (state.favorites_mode and browser.collection_scope_key)
    if scoped_collection_key then
        local collection_correlated =
            "(EXISTS(SELECT 1 FROM collection_items "
            .. "JOIN collection_external_keys ON "
            .. "collection_external_keys.collection_id="
            .. "collection_items.collection_id WHERE "
            .. "collection_external_keys.external_key="
            .. SQLQuote(scoped_collection_key)
            .. " AND collection_items.file_id=files.id) OR "
            .. "EXISTS(SELECT 1 FROM folder_files AS collection_location "
            .. "INDEXED BY idx_folder_files_file JOIN folder_closure AS "
            .. "collection_closure INDEXED BY idx_folder_closure_descendant "
            .. "ON collection_closure.descendant_id="
            .. "collection_location.folder_id JOIN collection_items AS "
            .. "collection_folder_item INDEXED BY idx_collection_items_folder "
            .. "ON collection_folder_item.folder_id="
            .. "collection_closure.ancestor_id JOIN collection_external_keys AS "
            .. "collection_folder_key ON collection_folder_key.collection_id="
            .. "collection_folder_item.collection_id WHERE "
            .. "collection_location.file_id=files.id AND "
            .. "collection_location.missing=0 AND "
            .. "collection_folder_key.external_key="
            .. SQLQuote(scoped_collection_key) .. "))"
        local scope_count = GetCanonicalFavoriteScopeCount(
            scoped_collection_key)
        if minimum_random_key_sql
            or (scope_count
                and scope_count <= SMALL_MATERIALIZED_FOLDER_SCOPE) then
            -- Organizational Favorites folders are normally sparse compared
            -- with the Library. Walking the global random-key index and running
            -- two membership probes for every file made a five-item collection
            -- scan hundreds of thousands of unrelated rows. Random requests
            -- materialize the selected collection first, then sort only that
            -- bounded membership by random_key.
            ctes[#ctes + 1] =
                "collection_files(file_id) AS MATERIALIZED (SELECT "
                .. "collection_items.file_id FROM collection_items JOIN "
                .. "collection_external_keys ON "
                .. "collection_external_keys.collection_id="
                .. "collection_items.collection_id WHERE "
                .. "collection_external_keys.external_key="
                .. SQLQuote(scoped_collection_key)
                .. " AND collection_items.file_id IS NOT NULL UNION SELECT "
                .. "collection_location.file_id FROM collection_items JOIN "
                .. "collection_external_keys ON "
                .. "collection_external_keys.collection_id="
                .. "collection_items.collection_id JOIN folder_closure ON "
                .. "folder_closure.ancestor_id=collection_items.folder_id JOIN "
                .. "folder_files AS collection_location INDEXED BY "
                .. "idx_folder_files_folder_active ON "
                .. "collection_location.folder_id=folder_closure.descendant_id "
                .. "WHERE collection_external_keys.external_key="
                .. SQLQuote(scoped_collection_key)
                .. " AND collection_items.folder_id IS NOT NULL AND "
                .. "collection_location.missing=0)"
            where[#where + 1] =
                "files.id IN(SELECT file_id FROM collection_files)"
            force_random_index = false
        else
            where[#where + 1] = collection_correlated
        end
    end

    if folder_id then
        folder_id = math.max(0, math.floor(tonumber(folder_id) or 0))
        local materialized_scope =
            "scope_files(file_id) AS MATERIALIZED (SELECT folder_files.file_id FROM "
            .. "folder_closure JOIN folder_files ON folder_files.folder_id="
            .. "folder_closure.descendant_id WHERE folder_closure.ancestor_id="
            .. tostring(folder_id) .. " AND folder_files.missing=0"
        local correlated_scope =
            "EXISTS(SELECT 1 FROM folder_files AS scoped_location "
            .. "INDEXED BY idx_folder_files_file JOIN folder_closure AS "
            .. "scoped_closure INDEXED BY idx_folder_closure_descendant ON "
            .. "scoped_closure.descendant_id=scoped_location.folder_id "
            .. "WHERE scoped_location.file_id=files.id AND "
            .. "scoped_location.missing=0 AND scoped_closure.ancestor_id="
            .. tostring(folder_id) .. ")"
        local known_scope_count = tonumber(
            browser.folder_scope_counts
                and browser.folder_scope_counts[folder_id])
        if known_scope_count
            and known_scope_count <= SMALL_MATERIALIZED_FOLDER_SCOPE then
            ctes[#ctes + 1] = materialized_scope .. ")"
            where[#where + 1] = "files.id IN(SELECT file_id FROM scope_files)"
        elseif known_scope_count then
            where[#where + 1] = correlated_scope
        else
            ctes[#ctes + 1] =
                "scope_size(n) AS (SELECT COALESCE((SELECT file_count FROM "
                .. "folder_subtree_stats WHERE folder_id=" .. tostring(folder_id)
                .. "),0))," .. materialized_scope .. " AND (SELECT n FROM "
                .. "scope_size)<=" .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. ")"
            where[#where + 1] =
                "(((SELECT n FROM scope_size)<="
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " AND files.id IN(SELECT file_id FROM scope_files)) OR "
                .. "((SELECT n FROM scope_size)>"
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " AND " .. correlated_scope .. "))"
        end
    end

    local search_text = NormalizeBrowserSearchTokens(browser.search_text)
    local has_fts_search = false
    local search_match_query = nil
    -- A random request with an active FTS query must be driven by the FTS
    -- index. Forcing idx_files_random_key first makes SQLite walk a large
    -- fraction of the entire library before it can discover 256 matches.
    local random_fts_mode = force_random_index == true
        and minimum_random_key_sql ~= nil
    if search_text ~= "" then
        local terms = {}
        for token in search_text:gmatch("%S+") do
            token = token:gsub('"', '""')
            if token ~= "" then
                terms[#terms + 1] = '"' .. token .. '"*'
            end
        end
        if #terms > 0 then
            has_fts_search = true
            search_match_query = table.concat(terms, " ")
            if not random_fts_mode then
                joins[#joins + 1] =
                    "JOIN file_search ON file_search.rowid=files.id"
                where[#where + 1] =
                    "file_search MATCH " .. SQLQuote(search_match_query)
            end
            if (tonumber(minimum_file_id) or 0) > 0 then
                where[#where + 1] = (random_fts_mode
                    and "files.id>" or "file_search.rowid>")
                    .. tostring(math.floor(tonumber(minimum_file_id)))
            end
        end
    end
    if not has_fts_search and (tonumber(minimum_file_id) or 0) > 0 then
        where[#where + 1] = "files.id>"
            .. tostring(math.floor(tonumber(minimum_file_id)))
    end

    local selected_tags = GetCanonicalBrowserSelectedTags()
    if #selected_tags > 0 then
        -- Prefer the narrowest known tag as the seed for intersections. The
        -- catalog is only a performance hint; when counts are unavailable,
        -- the stable alphabetical order remains the fallback.
        local tag_counts = {}
        for _, tag in ipairs(browser.available_tags or {}) do
            local tag_name = NormalizeTag(tag.name)
            if tag_name ~= "" then
                local scope_hint = browser.tag_cardinality_hints
                    and browser.tag_cardinality_hints[
                        tostring(folder_id or 0) .. "\31" .. tag_name]
                tag_counts[tag_name] = tonumber(scope_hint)
                    or tonumber(tag.count) or math.huge
            end
        end
        table.sort(selected_tags, function(left, right)
            local left_count = tag_counts[left] or math.huge
            local right_count = tag_counts[right] or math.huge
            if left_count == right_count then return left < right end
            return left_count < right_count
        end)
        local quoted = {}
        for _, name in ipairs(selected_tags) do
            quoted[#quoted + 1] = SQLQuote(name)
        end
        local seed_count = tag_counts[selected_tags[1]]
        local library_count = tonumber(state.database.library_file_count) or 0
        local folder_count = folder_id and tonumber(
            browser.folder_scope_counts
                and browser.folder_scope_counts[folder_id]) or nil
        local random_scope_count = folder_count or library_count
        local random_tag_stream = force_random_index and not has_fts_search
            and (#selected_tags > 1 or (seed_count
                and seed_count < math.huge
                and seed_count < math.max(2000, random_scope_count / 20)))
        -- Result pages need only their first small page, where probing a broad
        -- tag against the ordered file stream can win. A filtered tag catalog
        -- must enumerate up to 50,000 matches before aggregating co-occurring
        -- tags, so that same plan degenerates into a large library scan. Force
        -- catalogs to seed from idx_file_tags_tag whenever a tag is selected.
        local rowid_tag_stream = not prefer_tag_source
            and not force_random_index
            and smart_mode == nil and not has_fts_search
            and seed_count and seed_count < math.huge
            and seed_count >= math.max(1000, library_count / 1000)
            and (not folder_id or (folder_count
                and folder_count > SMALL_MATERIALIZED_FOLDER_SCOPE))
        if has_fts_search
            or (force_random_index and not random_tag_stream)
            or rowid_tag_stream then
            -- Common single tags are fastest as indexed probes against the
            -- random stream. Ordinary filtered pages use the same existence
            -- form when a broad tag would be slower as a materialized source.
            -- FTS searches must stay driven by file_search: materializing the
            -- complete selected-tag stream before intersecting it with FTS
            -- made root + vendor search + tag changes take seconds on large
            -- libraries, even when the final scoped result was small.
            if rowid_tag_stream then files_source = "files NOT INDEXED " end
            for _, tag_name in ipairs(quoted) do
                where[#where + 1] =
                    "EXISTS(SELECT 1 FROM file_tags JOIN tags ON "
                    .. "tags.id=file_tags.tag_id WHERE file_tags.file_id="
                    .. "files.id AND tags.name_norm=" .. tag_name
                    .. " AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions "
                    .. "WHERE file_tag_exclusions.file_id=file_tags.file_id "
                    .. "AND file_tag_exclusions.tag_norm=tags.name_norm))"
            end
        elseif #selected_tags == 1 then
            -- Drive paging directly from the ordered (tag_id,file_id) index.
            -- GROUP BY collapses duplicate sources as the co-routine streams;
            -- unlike IN(SELECT DISTINCT ...), page one does not materialize
            -- every file carrying a very common tag.
            files_source = "(SELECT file_tags.file_id FROM tags JOIN "
                .. "file_tags INDEXED BY idx_file_tags_tag ON "
                .. "file_tags.tag_id=tags.id WHERE tags.name_norm="
                .. quoted[1] .. " AND NOT EXISTS(SELECT 1 FROM "
                .. "file_tag_exclusions WHERE file_tag_exclusions.file_id="
                .. "file_tags.file_id AND file_tag_exclusions.tag_norm="
                .. "tags.name_norm) GROUP BY file_tags.file_id) AS "
                .. "selected_tag_files JOIN files ON files.id="
                .. "selected_tag_files.file_id "
        else
            -- Seed the intersection from one indexed tag relation, then
            -- check the remaining tags only against those candidates. This
            -- avoids the old full file_tag GROUP BY/HAVING pass while also
            -- avoiding a correlated existence test for every library file.
            files_source = "(SELECT file_tags.file_id FROM tags JOIN "
                .. "file_tags INDEXED BY idx_file_tags_tag ON "
                .. "file_tags.tag_id=tags.id WHERE tags.name_norm="
                .. quoted[1] .. " AND NOT EXISTS(SELECT 1 FROM "
                .. "file_tag_exclusions WHERE file_tag_exclusions.file_id="
                .. "file_tags.file_id AND file_tag_exclusions.tag_norm="
                .. "tags.name_norm) GROUP BY file_tags.file_id) AS "
                .. "selected_tag_files JOIN files ON files.id="
                .. "selected_tag_files.file_id "
            local intersection = {}
            for index = 2, #quoted do
                local tag_name = quoted[index]
                intersection[#intersection + 1] =
                    "EXISTS(SELECT 1 FROM file_tags JOIN tags "
                    .. "ON tags.id=file_tags.tag_id WHERE "
                    .. "file_tags.file_id=files.id AND tags.name_norm="
                    .. tag_name .. " AND NOT EXISTS(SELECT 1 FROM "
                    .. "file_tag_exclusions WHERE file_tag_exclusions.file_id="
                    .. "file_tags.file_id AND file_tag_exclusions.tag_norm="
                    .. "tags.name_norm))"
            end
            where[#where + 1] = "(" .. table.concat(intersection, " AND ") .. ")"
        end
        if random_tag_stream then
            -- Sparse or intersected tags are much faster when the tag index
            -- supplies candidates before random-key ordering. This also keeps
            -- Random on exactly the same tag predicates as the visible page.
            force_random_index = false
        end
    end

    -- A tag-driven source replaces the earlier sparse smart-view source.
    -- Reattach the same sparse relation so its predicates remain valid and
    -- Recent/Used still scale with user rows, not library rows. Favorites has
    -- a broader indexed membership predicate below (direct, custom, and
    -- inherited folder descendants), so narrowing it back to user_file_data
    -- here would silently hide custom-only Favorites whenever tags are active.
    if #selected_tags > 0 then
        if smart_mode == "smart_recent" then
            files_source = files_source
                .. "JOIN user_file_data AS matched_user INDEXED BY "
                .. "idx_user_file_recent ON matched_user.file_id=files.id "
        elseif smart_mode == "smart_used" then
            files_source = files_source
                .. "JOIN user_file_data AS matched_user INDEXED BY "
                .. "idx_user_file_used ON matched_user.file_id=files.id "
        end
    end

    local classes = {}
    for name, enabled in pairs(browser.selected_classes or {}) do
        if enabled and (name == "loop" or name == "one-shot"
            or name == "midi" or name == "other") then
            classes[#classes + 1] = name
        end
    end
    table.sort(classes)
    if #classes > 0 then
        local predicates = {}
        -- The indexed effective database classification is the sole filter
        -- authority. User tags are ordinary tags and never compete here.
        for _, name in ipairs(classes) do
            if name == "loop" then
                predicates[#predicates + 1] =
                    "(files.media_type='audio' AND files.classification='loop')"
            elseif name == "one-shot" then
                predicates[#predicates + 1] =
                    "(files.media_type='audio' AND files.classification='one-shot')"
            elseif name == "midi" then
                predicates[#predicates + 1] =
                    "(files.media_type='midi' OR files.classification='midi')"
            else
                predicates[#predicates + 1] =
                    "(files.media_type='audio' AND "
                    .. "COALESCE(files.classification,'other')='other')"
            end
        end
        where[#where + 1] =
            "(" .. table.concat(predicates, " OR ") .. ")"
    end

    local key_pc = math.floor(tonumber(browser.key_pc) or -1)
    if key_pc >= 0 and key_pc <= 11 then
        where[#where + 1] = "files.key_pc=" .. tostring(key_pc)
    end

    -- A Favorites-wide search must operate on favorite files and descendants
    -- of favorite folders, not silently fall back to the entire Library.
    -- Build that membership through indexed locations and closure rows. Facet
    -- queries do not take this path; they require a physical folder ID.
    -- A physical folder reached from Favorites is already an authoritative
    -- favorite scope, so its indexed subtree predicate above is sufficient.
    -- Only root/search scopes need the broader Favorites membership test.
    if state.favorites_mode
        and (not smart_mode or smart_mode == "smart_favorites")
        and not folder_id
        and not scoped_collection_key then
        local favorite_correlated =
            "(EXISTS(SELECT 1 FROM user_file_data WHERE "
            .. "user_file_data.file_id=files.id AND "
            .. "user_file_data.favorite=1) OR EXISTS(SELECT 1 FROM "
            .. "collection_items WHERE collection_items.file_id=files.id) "
            .. "OR EXISTS(SELECT 1 FROM "
            .. "folder_files AS favorite_location INDEXED BY "
            .. "idx_folder_files_file JOIN folder_closure AS favorite_closure "
            .. "INDEXED BY idx_folder_closure_descendant ON "
            .. "favorite_closure.descendant_id=favorite_location.folder_id "
            .. "JOIN collection_items AS favorite_folder_item INDEXED BY "
            .. "idx_collection_items_folder ON favorite_folder_item.folder_id="
            .. "favorite_closure.ancestor_id WHERE favorite_location.file_id="
            .. "files.id AND favorite_location.missing=0))"
        local scope_count = GetCanonicalFavoriteScopeCount(nil)
        if scope_count and scope_count <= SMALL_MATERIALIZED_FOLDER_SCOPE then
            ctes[#ctes + 1] =
                "favorite_files(file_id) AS MATERIALIZED (SELECT "
                .. "favorite_location.file_id FROM collection_items JOIN "
                .. "folder_closure ON folder_closure.ancestor_id="
                .. "collection_items.folder_id JOIN folder_files AS "
                .. "favorite_location INDEXED BY idx_folder_files_folder_active "
                .. "ON favorite_location.folder_id=folder_closure.descendant_id "
                .. "WHERE collection_items.folder_id IS NOT NULL AND "
                .. "favorite_location.missing=0 UNION SELECT "
                .. "collection_items.file_id FROM collection_items WHERE "
                .. "collection_items.file_id IS NOT NULL UNION SELECT "
                .. "user_file_data.file_id FROM user_file_data WHERE "
                .. "user_file_data.favorite=1)"
            where[#where + 1] =
                "files.id IN(SELECT file_id FROM favorite_files)"
            force_random_index = false
        elseif scope_count then
            where[#where + 1] = favorite_correlated
        else
            -- Cold startup intentionally does not hydrate every favorite into
            -- Lua. Compute a cheap upper bound from indexed direct favorites
            -- plus scan-maintained folder subtree sizes. If that bound is
            -- small, materialize only the bounded Favorites membership; if it
            -- is large, keep the streaming correlated plan. Duplicate or
            -- overlapping favorite folders can only overestimate this bound.
            ctes[#ctes + 1] =
                "favorite_scope_size(n) AS (SELECT (SELECT count(*) FROM "
                .. "user_file_data WHERE favorite=1)+(SELECT count(*) FROM "
                .. "collection_items WHERE file_id IS NOT NULL)+COALESCE((SELECT sum("
                .. "folder_subtree_stats.file_count) FROM collection_items "
                .. "JOIN folder_subtree_stats ON folder_subtree_stats.folder_id="
                .. "collection_items.folder_id WHERE collection_items.folder_id "
                .. "IS NOT NULL),0)),favorite_files(file_id) AS MATERIALIZED ("
                .. "SELECT favorite_location.file_id FROM collection_items JOIN "
                .. "folder_closure ON folder_closure.ancestor_id="
                .. "collection_items.folder_id JOIN folder_files AS "
                .. "favorite_location INDEXED BY idx_folder_files_folder_active "
                .. "ON favorite_location.folder_id=folder_closure.descendant_id "
                .. "WHERE collection_items.folder_id IS NOT NULL AND "
                .. "favorite_location.missing=0 AND (SELECT n FROM "
                .. "favorite_scope_size)<="
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " UNION SELECT collection_items.file_id FROM "
                .. "collection_items WHERE collection_items.file_id IS NOT NULL "
                .. "AND (SELECT n FROM favorite_scope_size)<="
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " UNION SELECT user_file_data.file_id FROM user_file_data "
                .. "WHERE favorite=1 AND (SELECT n FROM favorite_scope_size)<="
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE) .. ")"
            where[#where + 1] =
                "(((SELECT n FROM favorite_scope_size)<="
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " AND files.id IN(SELECT file_id FROM favorite_files)) OR "
                .. "((SELECT n FROM favorite_scope_size)>"
                .. tostring(SMALL_MATERIALIZED_FOLDER_SCOPE)
                .. " AND " .. favorite_correlated .. "))"
        end
    end

    if exclude_ids and #exclude_ids > 0 then
        local ids = {}
        for _, id in ipairs(exclude_ids) do
            ids[#ids + 1] = tostring(math.max(
                0, math.floor(tonumber(id) or 0)))
        end
        where[#where + 1] =
            "files.id NOT IN(" .. table.concat(ids, ",") .. ")"
    end

    if minimum_random_key_sql then
        if minimum_random_id ~= nil then
            where[#where + 1] = "(files.random_key>("
                .. minimum_random_key_sql .. ") OR (files.random_key=("
                .. minimum_random_key_sql .. ") AND files.id>"
                .. tostring(math.max(0, math.floor(
                    tonumber(minimum_random_id) or 0))) .. "))"
        else
            where[#where + 1] = "files.random_key>=("
                .. minimum_random_key_sql .. ")"
        end
    end

    if random_fts_mode and has_fts_search and search_match_query then
        -- Let FTS produce the candidates and only then apply the random-key
        -- threshold. The bounded CTE below prevents a broad search from
        -- materializing the complete match set.
        files_source = "(SELECT file_search.rowid AS file_id FROM "
            .. "file_search WHERE file_search MATCH "
            .. SQLQuote(search_match_query) .. ") AS search_matches JOIN files "
            .. "ON files.id=search_matches.file_id "
        force_random_index = false
    elseif not force_random_index and smart_mode == nil
        and not has_fts_search and #selected_tags == 0
        and (#classes > 0 or (key_pc >= 0 and key_pc <= 11)) then
        -- Filter pages are ordered by canonical file ID. Driving the primary
        -- row stream lets SQLite stop after one page instead of selecting a
        -- classification/key index and sorting every match into a temp B-tree.
        files_source = "files NOT INDEXED "
    elseif force_random_index
        and (smart_mode == nil or smart_mode == "smart_favorites") then
        files_source = "files INDEXED BY idx_files_random_key "
    end
    local random_pool_limit = minimum_random_key_sql
        and (random_fts_mode and has_fts_search and " LIMIT 256"
            or " ORDER BY files.random_key,files.id LIMIT 256") or ""
    ctes[#ctes + 1] =
        "matched(file_id) AS (SELECT files.id FROM " .. files_source
        .. table.concat(joins, " ") .. " WHERE "
        .. table.concat(where, " AND ") .. ")"
    if random_pool_limit ~= "" then
        ctes[#ctes] = ctes[#ctes]:sub(1, -2) .. random_pool_limit .. ")"
    end
    return table.concat(ctes, ",")
end

local function StartCanonicalPageQuery(
    mode, folder_id, offset, page_size_override, collection_key_override)
    local paging = state.canonical_paging
    if state.database.write_active then
        return false, "Another library task is still running."
    end
    local page_size = page_size_override or paging.page_size or 100
    local limit = page_size + 1
    offset = math.max(0, math.floor(tonumber(offset) or 0))
    local cursor = offset > 0 and paging.browser_request
        and paging.browser_request.cursor or nil
    local cursor_id = cursor
        and math.max(0, math.floor(tonumber(cursor.id) or 0)) or 0
    local offset_sql = cursor and "" or " OFFSET " .. tostring(offset)
    local sql = {".headers off\n.mode tabs\n"}
    if mode == "roots" then
        sql[#sql + 1] =
            "SELECT 'R',folders.id,hex(roots.display_path),"
            .. "hex(roots.display_path),'',"
            .. "folders.id,'',COALESCE(folder_subtree_stats.file_count,0) "
            .. "FROM roots JOIN folders "
             .. "ON folders.root_id=roots.id "
             .. "AND folders.relative_path_norm='' "
             .. "LEFT JOIN folder_subtree_stats ON "
             .. "folder_subtree_stats.folder_id=folders.id "
             .. "WHERE roots.enabled=1 AND folders.missing=0 "
             .. "ORDER BY roots.display_path COLLATE NOCASE,roots.id LIMIT "
             .. tostring(limit) .. " OFFSET " .. tostring(offset) .. ";\n"
        if offset == 0 then
            -- This is an inexpensive upper bound, not a Favorites tag scan.
            -- It lets later filters choose a bounded membership plan without
            -- hydrating Favorites into Lua or counting distinct descendants.
            sql[#sql + 1] =
                "SELECT 'S',(SELECT count(*) FROM user_file_data WHERE "
                .. "favorite=1)+(SELECT count(*) FROM collection_items WHERE "
                .. "file_id IS NOT NULL)+COALESCE((SELECT sum("
                .. "folder_subtree_stats.file_count) FROM collection_items "
                .. "JOIN folder_subtree_stats ON folder_subtree_stats.folder_id="
                .. "collection_items.folder_id WHERE collection_items.folder_id "
                .. "IS NOT NULL),0);\n"
        end
    elseif mode == "favorite_scope_count" then
        -- Resolve the small/materialized versus large/streaming plan before
        -- Root Random starts. Embedding both paths behind a SQL OR prevents
        -- SQLite from optimizing either path and makes even a tiny uncached
        -- Favorites set walk the global random stream.
        sql[#sql + 1] =
            "SELECT 'S',(SELECT count(*) FROM user_file_data WHERE "
            .. "favorite=1)+(SELECT count(*) FROM collection_items WHERE "
            .. "file_id IS NOT NULL)+COALESCE((SELECT sum("
            .. "folder_subtree_stats.file_count) FROM collection_items "
            .. "JOIN folder_subtree_stats ON folder_subtree_stats.folder_id="
            .. "collection_items.folder_id WHERE collection_items.folder_id "
            .. "IS NOT NULL),0);\n"
    elseif mode == "smart_favorites" then
        local browser = state.canonical_browser
        local favorite_sort = state.favorite_sort or "added"
        local favorite_order
        if favorite_sort == "az" then
            favorite_order = "name COLLATE NOCASE ASC,item_id ASC"
        elseif favorite_sort == "za" then
            favorite_order = "name COLLATE NOCASE DESC,item_id DESC"
        elseif favorite_sort == "newest" then
            favorite_order = "sort_time DESC,name COLLATE NOCASE,item_id"
        else
            favorite_order = "sort_time ASC,name COLLATE NOCASE,item_id"
        end
        local unfiltered_favorites =
            NormalizeTag(browser.search_text or "") == ""
            and next(browser.selected_tags or {}) == nil
            and next(browser.selected_classes or {}) == nil
            and (tonumber(browser.key_pc) or -1) < 0
        local matched
        if unfiltered_favorites then
            -- This legacy aggregate query is retained for compatibility, but
            -- the current Favorites UI opens the Favorites Library hierarchy.
            -- Unfiltered, show only files with their own
            -- root/custom membership. Descendants inherited from a favorited
            -- folder remain available inside that folder and to search/filter/
            -- random, but do not flood this list as standalone rows.
            matched = "explicit_favorite_files(file_id) AS MATERIALIZED ("
                .. "SELECT file_id FROM user_file_data WHERE favorite=1 UNION "
                .. "SELECT file_id FROM collection_items WHERE file_id IS NOT NULL),"
                .. "matched(file_id) AS (SELECT files.id FROM "
                .. "explicit_favorite_files JOIN files ON files.id="
                .. "explicit_favorite_files.file_id WHERE files.missing=0 AND "
                .. "(files.file_size IS NULL OR files.file_size>0))"
        else
            matched = BuildCanonicalUnifiedMatchCTE(
                folder_id, nil, nil, nil, mode)
        end
        sql[#sql + 1] = "WITH RECURSIVE " .. matched
            .. ",favorite_items(kind,item_id,name,path,media_type,classification,"
            .. "folder_id,sort_time) AS ("
            .. "SELECT 'F',files.id,files.name,files.canonical_path,"
            .. "files.media_type,files.classification,0,COALESCE((SELECT "
            .. "MIN(collection_items.added_at) FROM collection_items WHERE "
            .. "collection_items.file_id=files.id),"
            .. "user_file_data.updated_at,0) "
            .. "FROM matched JOIN files ON files.id=matched.file_id "
            .. "LEFT JOIN user_file_data ON user_file_data.file_id=files.id"
            .. ") SELECT kind,item_id,hex(name),hex(path),media_type,"
            .. "folder_id,classification FROM favorite_items ORDER BY "
            .. "CASE WHEN kind='D' THEN 0 ELSE 1 END,"
            .. favorite_order .. " LIMIT " .. tostring(limit)
            .. " OFFSET " .. tostring(offset) .. ";\n"
    elseif mode == "favorite_collection_items" then
        local collection_id = "(SELECT collection_id FROM "
            .. "collection_external_keys WHERE external_key="
            .. SQLQuote(tostring(collection_key_override or "")) .. ")"
        local favorite_sort = state.favorite_sort or "added"
        local item_order
        if favorite_sort == "az" then
            item_order = "name COLLATE NOCASE ASC,item_id ASC"
        elseif favorite_sort == "za" then
            item_order = "name COLLATE NOCASE DESC,item_id DESC"
        elseif favorite_sort == "newest" then
            item_order = "sort_time DESC,name COLLATE NOCASE,item_id"
        else
            item_order = "sort_time ASC,name COLLATE NOCASE,item_id"
        end
        sql[#sql + 1] = "WITH collection_entries(kind,item_id,name,path,"
            .. "media_type,classification,folder_id,sort_time) AS ("
            .. "SELECT 'D',folders.id,folders.name,roots.display_path||"
            .. "CASE WHEN folders.relative_path='' THEN '' ELSE '/'||"
            .. "folders.relative_path END,'','',folders.id,"
            .. "collection_items.added_at FROM collection_items JOIN folders "
            .. "ON folders.id=collection_items.folder_id JOIN roots ON "
            .. "roots.id=folders.root_id WHERE collection_items.collection_id="
            .. collection_id .. " AND folders.missing=0 AND roots.enabled=1 "
            .. "UNION ALL SELECT 'F',files.id,files.name,files.canonical_path,"
            .. "files.media_type,files.classification,0,collection_items.added_at "
            .. "FROM collection_items JOIN files ON files.id="
            .. "collection_items.file_id WHERE collection_items.collection_id="
            .. collection_id .. " AND files.missing=0) SELECT kind,item_id,"
            .. "hex(name),hex(path),media_type,folder_id,classification FROM "
            .. "collection_entries ORDER BY CASE WHEN kind='D' THEN 0 ELSE 1 END,"
            .. item_order .. " LIMIT " .. tostring(limit)
            .. " OFFSET " .. tostring(offset) .. ";\n"
    elseif mode == "favorite_root_items" then
        local favorite_sort = state.favorite_sort or "added"
        local item_order
        if favorite_sort == "az" then
            item_order = "files.name COLLATE NOCASE ASC,files.id ASC"
        elseif favorite_sort == "za" then
            item_order = "files.name COLLATE NOCASE DESC,files.id DESC"
        elseif favorite_sort == "newest" then
            item_order = "sort_time DESC,files.name COLLATE NOCASE,files.id"
        else
            item_order = "sort_time ASC,files.name COLLATE NOCASE,files.id"
        end
        sql[#sql + 1] = "WITH direct_file_ids(file_id) AS (SELECT file_id "
            .. "FROM user_file_data WHERE favorite=1 UNION SELECT file_id FROM "
            .. "collection_items WHERE collection_id=-1 AND file_id IS NOT NULL),"
            .. "direct_files(file_id,sort_time) AS (SELECT direct_file_ids.file_id,"
            .. "COALESCE((SELECT collection_items.added_at FROM collection_items "
            .. "WHERE collection_items.collection_id=-1 AND collection_items.file_id="
            .. "direct_file_ids.file_id LIMIT 1),(SELECT user_file_data.updated_at "
            .. "FROM user_file_data WHERE user_file_data.file_id="
            .. "direct_file_ids.file_id),0) FROM direct_file_ids) SELECT 'F',"
            .. "files.id,hex(files.name),hex(files.canonical_path),files.media_type,0,"
            .. "files.classification,0 AS reserved,'M'||COALESCE((SELECT "
            .. "group_concat(hex(collection_external_keys.external_key),',') "
            .. "FROM collection_items JOIN collection_external_keys ON "
            .. "collection_external_keys.collection_id="
            .. "collection_items.collection_id WHERE collection_items.file_id="
            .. "files.id),'') FROM direct_files JOIN files ON files.id="
            .. "direct_files.file_id WHERE files.missing=0 ORDER BY "
            .. item_order .. " LIMIT " .. tostring(limit)
            .. " OFFSET " .. tostring(offset) .. ";\n"
    elseif mode == "smart_recent" or mode == "smart_used"
        or mode == "smart_collection" then
        local matched = BuildCanonicalUnifiedMatchCTE(
            folder_id, nil, nil, nil, mode, nil, nil,
            collection_key_override)
        local ordering = mode == "smart_recent"
            and "user_file_data.last_used_at DESC,user_file_data.file_id"
            or mode == "smart_used"
            and "user_file_data.play_count DESC,"
                .. "user_file_data.last_used_at DESC,user_file_data.file_id"
            or "files.name COLLATE NOCASE,files.id"
        local result_limit = mode == "smart_recent"
            and USAGE_RECENT_RETENTION_LIMIT or mode == "smart_used"
            and USAGE_MOST_USED_RETENTION_LIMIT or limit
        local cursor_where = ""
        if cursor then
            if mode == "smart_recent" then
                local last_time = "(SELECT last_used_at FROM user_file_data WHERE file_id="
                    .. tostring(cursor_id) .. ")"
                cursor_where = "WHERE (user_file_data.last_used_at<" .. last_time
                    .. " OR (user_file_data.last_used_at=" .. last_time
                    .. " AND user_file_data.file_id>" .. tostring(cursor_id)
                    .. ")) "
            elseif mode == "smart_used" then
                local last_play = "(SELECT play_count FROM user_file_data WHERE file_id="
                    .. tostring(cursor_id) .. ")"
                local last_time = "(SELECT last_used_at FROM user_file_data WHERE file_id="
                    .. tostring(cursor_id) .. ")"
                cursor_where = "WHERE (user_file_data.play_count<" .. last_play
                    .. " OR (user_file_data.play_count=" .. last_play
                    .. " AND (user_file_data.last_used_at<" .. last_time
                    .. " OR (user_file_data.last_used_at=" .. last_time
                    .. " AND user_file_data.file_id>" .. tostring(cursor_id)
                    .. ")))) "
            else
                local name_tail = "(files.name COLLATE NOCASE>"
                    .. SQLQuote(cursor.name or "") .. " OR (files.name="
                    .. SQLQuote(cursor.name or "")
                    .. " COLLATE NOCASE AND files.id>" .. tostring(cursor_id) .. "))"
                cursor_where = "WHERE " .. name_tail .. " "
            end
        end
        local usage_join = ""
        if mode == "smart_recent" then
            usage_join = "JOIN user_file_data INDEXED BY idx_user_file_recent "
                .. "ON user_file_data.file_id=files.id "
        elseif mode == "smart_used" then
            usage_join = "JOIN user_file_data INDEXED BY idx_user_file_used "
                .. "ON user_file_data.file_id=files.id "
        end
        sql[#sql + 1] = "WITH RECURSIVE " .. matched
            .. " SELECT 'F',files.id,hex(files.name),"
            .. "hex(files.canonical_path),files.media_type,0,files.classification "
            .. "FROM matched JOIN files ON files.id=matched.file_id "
            .. usage_join
            .. cursor_where
            .. "ORDER BY " .. ordering .. " LIMIT "
            .. tostring(result_limit) .. (cursor and "" or " OFFSET "
                .. tostring(offset)) .. ";\n"
    elseif mode == "tag_catalog" then
        local browser = state.canonical_browser
        local collection_scope_key = state.favorites_mode
            and not browser.smart_mode and browser.collection_scope_key
        if state.favorites_mode and (folder_id == nil
            or browser.smart_mode or collection_scope_key) then
            -- Favorites home, smart views, and organizational collections do
            -- not aggregate tags. Only selected physical folders use their
            -- scan-maintained subtree tag counts.
            sql[#sql + 1] =
                "SELECT 'T',0,'','','',0 WHERE 0;\n"
        elseif next(browser.selected_tags or {}) ~= nil
            or next(browser.selected_classes or {}) ~= nil
            or (tonumber(browser.key_pc) or -1) >= 0
            or NormalizeTag(browser.search_text or "") ~= "" then
            -- Active filters need a co-occurrence catalog. Unfiltered physical
            -- folders use their precomputed subtree counts below.
            local selected_tag_names = GetCanonicalBrowserSelectedTags()
            local selected_tag_keep_sql = ""
            if #selected_tag_names > 0 then
                local quoted_selected_tags = {}
                for _, selected_name in ipairs(selected_tag_names) do
                    quoted_selected_tags[#quoted_selected_tags + 1] =
                        SQLQuote(selected_name)
                end
                selected_tag_keep_sql = " OR tags.name_norm IN("
                    .. table.concat(quoted_selected_tags, ",") .. ")"
            end
            local matched = BuildCanonicalUnifiedMatchCTE(
                folder_id, nil, nil, nil, browser.smart_mode, nil, true)
            sql[#sql + 1] = "WITH RECURSIVE " .. matched
                .. ",facet_files(file_id) AS MATERIALIZED (SELECT file_id "
                .. "FROM matched ORDER BY file_id LIMIT "
                .. tostring(MEDIA_TAG_RELEVANCE_SAMPLE_LIMIT) .. "),"
                .. "facet_size(n) AS (SELECT count(*) FROM facet_files),"
                .. "popular AS (SELECT file_tags.tag_id,"
                .. "count(DISTINCT facet_files.file_id) AS file_count FROM "
                .. "facet_files JOIN file_tags ON file_tags.file_id="
                .. "facet_files.file_id "
                .. "JOIN tags ON tags.id=file_tags.tag_id WHERE NOT EXISTS("
                .. "SELECT 1 FROM file_tag_exclusions WHERE "
                .. "file_tag_exclusions.file_id=file_tags.file_id AND "
                .. "file_tag_exclusions.tag_norm=tags.name_norm) GROUP BY "
                .. "file_tags.tag_id ORDER BY file_count DESC,file_tags.tag_id "
                .. "LIMIT " .. tostring(MEDIA_TAG_CATALOG_LIMIT + 5)
                .. "),relevant_tags AS (SELECT tags.id,tags.name,"
                .. "popular.file_count FROM popular JOIN tags ON tags.id="
                .. "popular.tag_id CROSS JOIN facet_size WHERE "
                .. "tags.name_norm NOT IN "
                .. "('loop','one-shot','oneshot','midi','audio') AND ("
                .. "popular.file_count>=CASE WHEN facet_size.n<100 THEN 1 "
                .. "ELSE max(2,(facet_size.n+99)/100) END"
                .. selected_tag_keep_sql .. ") ORDER BY popular.file_count "
                .. "DESC,popular.tag_id LIMIT "
                .. tostring(MEDIA_TAG_CATALOG_LIMIT) .. ") SELECT 'T',id,"
                .. "hex(name),hex(CAST(file_count AS TEXT)),'',0 FROM "
                .. "relevant_tags ORDER BY name COLLATE NOCASE;\n"
        elseif folder_id ~= nil then
            folder_id = math.max(0, math.floor(tonumber(folder_id) or 0))
            sql[#sql + 1] =
                "WITH popular AS (SELECT tag_id,file_count FROM "
                .. "folder_subtree_tag_counts WHERE folder_id="
                .. tostring(folder_id)
                .. " ORDER BY file_count DESC,tag_id LIMIT "
                .. tostring(MEDIA_TAG_CATALOG_LIMIT + 5) .. "),"
                .. "relevant_tags AS (SELECT tags.id,tags.name,popular.file_count "
                .. "FROM popular JOIN tags ON tags.id=popular.tag_id WHERE "
                .. "tags.name_norm NOT IN "
                .. "('loop','one-shot','oneshot','midi','audio') LIMIT "
                .. tostring(MEDIA_TAG_CATALOG_LIMIT) .. ") "
                .. "SELECT 'T',id,hex(name),"
                .. "hex(CAST(file_count AS TEXT)),'',0 FROM relevant_tags "
                .. "ORDER BY name COLLATE NOCASE;\n"
        else
            sql[#sql + 1] =
                "WITH popular AS (SELECT tag_id,file_count FROM "
                .. "library_tag_counts ORDER BY file_count DESC,tag_id LIMIT "
                .. tostring(MEDIA_TAG_CATALOG_LIMIT + 5) .. "),"
                .. "relevant_tags AS (SELECT tags.id,tags.name,popular.file_count "
                .. "FROM popular JOIN tags ON tags.id=popular.tag_id WHERE "
                .. "tags.name_norm NOT IN "
                .. "('loop','one-shot','oneshot','midi','audio') LIMIT "
                .. tostring(MEDIA_TAG_CATALOG_LIMIT) .. ") "
                .. "SELECT 'T',id,hex(name),"
                .. "hex(CAST(file_count AS TEXT)),'',0 FROM relevant_tags "
                .. "ORDER BY name COLLATE NOCASE;\n"
        end
    elseif mode == "resolve_favorite_folder" then
        local lookup_target = paging.browser_request
            and paging.browser_request.accordion_target or nil
        local path_norm = NormalizeFavoritePath(
            type(lookup_target) == "table" and lookup_target.path or "")
        sql[#sql + 1] = "SELECT 'D',folders.id,hex(folders.name),hex("
            .. "roots.display_path||CASE WHEN folders.relative_path='' THEN '' "
            .. "ELSE '/'||folders.relative_path END),'',folders.id,'',0 FROM "
            .. "folders JOIN roots ON roots.id=folders.root_id WHERE "
            .. CanonicalFolderPathPredicate(path_norm)
            .. " AND folders.missing=0 LIMIT 1;\n"
    elseif mode == "browser_search" then
        local search_text = NormalizeBrowserSearchTokens(
            state.canonical_browser.search_text)
        local terms = {}
        for token in search_text:gmatch("%S+") do
            token = token:gsub('"', '""')
            if token ~= "" then
                terms[#terms + 1] = '"' .. token .. '"*'
            end
        end
        local match_query = table.concat(terms, " ")
        if match_query == "" then
            sql[#sql + 1] =
                "SELECT 'F',id,hex(name),hex(canonical_path),media_type,0,classification "
                .. "FROM files WHERE 0;\n"
        elseif not state.database.file_search_ready then
            sql[#sql + 1] =
                "SELECT 'F',id,hex(name),hex(canonical_path),media_type,0,classification "
                .. "FROM files WHERE 0;\n"
        else
            local browser = state.canonical_browser
            local simple_fts = folder_id == nil and not state.favorites_mode
                and not browser.smart_mode
                and next(browser.selected_tags or {}) == nil
                and next(browser.selected_classes or {}) == nil
                and (tonumber(browser.key_pc) or -1) < 0
            if simple_fts then
                -- FTS5 consumes both the row-id lower bound and ORDER BY. This
                -- is stable seek paging without sorting the complete match.
                sql[#sql + 1] = "SELECT 'F',files.id,hex(files.name),"
                    .. "hex(files.canonical_path),files.media_type,0,"
                    .. "files.classification FROM file_search JOIN files ON "
                    .. "files.id=file_search.rowid WHERE files.missing=0 AND "
                    .. "(files.file_size IS NULL OR files.file_size>0) AND "
                    .. "file_search MATCH " .. SQLQuote(match_query)
                    .. (cursor and (" AND file_search.rowid>"
                        .. tostring(cursor_id)) or "")
                    .. " ORDER BY file_search.rowid LIMIT "
                    .. tostring(limit) .. offset_sql .. ";\n"
            else
                local matched = BuildCanonicalUnifiedMatchCTE(
                    folder_id, nil, nil, nil, nil,
                    cursor and cursor_id or nil)
                sql[#sql + 1] = "WITH RECURSIVE " .. matched
                    .. ",page(file_id) AS MATERIALIZED (SELECT file_id FROM "
                    .. "matched ORDER BY file_id LIMIT " .. tostring(limit)
                    .. offset_sql .. ") SELECT 'F',files.id,hex(files.name),"
                    .. "hex(files.canonical_path),files.media_type,0,"
                    .. "files.classification FROM page JOIN files ON "
                    .. "files.id=page.file_id ORDER BY page.file_id;\n"
            end
        end
    elseif mode == "browser_filter" then
        local matched = BuildCanonicalUnifiedMatchCTE(
            folder_id, nil, nil, nil, nil, cursor and cursor_id or nil)
        sql[#sql + 1] = "WITH RECURSIVE " .. matched
            .. ",page(file_id) AS MATERIALIZED (SELECT file_id FROM matched "
            .. "ORDER BY file_id LIMIT " .. tostring(limit) .. offset_sql
            .. ") SELECT 'F',files.id,hex(files.name),"
            .. "hex(files.canonical_path),files.media_type,0,files.classification "
            .. "FROM page JOIN files ON files.id=page.file_id "
            -- Category and key filters can match millions of rows. Ordering
            -- by indexed file ID returns page one without sorting the entire
            -- match set by filename.
            .. "ORDER BY page.file_id;\n"
    elseif mode == "browser_random" then
        local browser = state.canonical_browser
        local wrapped = browser.random_force_start == true
        browser.random_force_start = false
        local continuing = not wrapped and browser.random_cursor_key ~= nil
        local minimum_key = wrapped and "0"
            or continuing and tostring(browser.random_cursor_key)
            or "(random() & 0x7fffffffffffffff)"
        local minimum_id = continuing and browser.random_cursor_id or nil
        local smart_random_mode = browser.smart_mode
        local matched
        if smart_random_mode == "smart_recent"
            or smart_random_mode == "smart_used" then
            -- Recent and Most Used retain a shared maintenance margin, but Dice
            -- must roll only within the current view's ranked top 5,000.
            matched = BuildCanonicalUnifiedMatchCTE(
                folder_id, nil, nil, nil, smart_random_mode)
        else
            matched = BuildCanonicalUnifiedMatchCTE(
                folder_id, nil, minimum_key, true, nil, nil, nil, nil,
                minimum_id)
        end
        if paging.browser_request then
            paging.browser_request.random_wrapped = wrapped
            paging.browser_request.random_start_key = minimum_key
            paging.browser_request.random_start_id = minimum_id
        end
        if smart_random_mode == "smart_recent"
            or smart_random_mode == "smart_used" then
            local ranking = smart_random_mode == "smart_recent"
                and "user_file_data.last_used_at DESC,user_file_data.file_id"
                or "user_file_data.play_count DESC,"
                    .. "user_file_data.last_used_at DESC,user_file_data.file_id"
            local ranked_limit = smart_random_mode == "smart_recent"
                and USAGE_RECENT_RETENTION_LIMIT
                or USAGE_MOST_USED_RETENTION_LIMIT
            local cursor_predicate = "files.random_key>=(" .. minimum_key .. ")"
            if minimum_id ~= nil then
                cursor_predicate = "(files.random_key>(" .. minimum_key
                    .. ") OR (files.random_key=(" .. minimum_key
                    .. ") AND files.id>" .. tostring(math.max(
                        0, math.floor(tonumber(minimum_id) or 0))) .. "))"
            end
            sql[#sql + 1] = "WITH RECURSIVE " .. matched
                .. ",ranked_smart_random(file_id) AS MATERIALIZED (SELECT "
                .. "matched.file_id FROM matched JOIN user_file_data ON "
                .. "user_file_data.file_id=matched.file_id ORDER BY "
                .. ranking .. " LIMIT " .. tostring(ranked_limit) .. ") "
                .. "SELECT 'F',files.id,hex(files.name),"
                .. "hex(files.canonical_path),files.media_type,0,"
                .. "files.classification,files.random_key FROM "
                .. "ranked_smart_random JOIN files "
                .. "ON files.id=ranked_smart_random.file_id WHERE "
                .. cursor_predicate
                .. " ORDER BY files.random_key,files.id LIMIT 256;\n"
        else
            sql[#sql + 1] = "WITH RECURSIVE " .. matched
                .. " SELECT 'F',files.id,hex(files.name),"
                .. "hex(files.canonical_path),files.media_type,0,"
                .. "files.classification,files.random_key "
                .. "FROM matched JOIN files ON files.id=matched.file_id "
                -- V5 always walks the indexed random stream and tests the active
                -- predicates until the bounded pool is full. Restrictive scopes
                -- may inspect more candidates, but never sort/materialize the
                -- complete match set.
                .. "ORDER BY files.random_key,files.id LIMIT 256;\n"
        end
    elseif mode == "filter_multi_tag" then
        sql[#sql + 1] =
            "WITH chosen(file_id) AS (SELECT file_tags.file_id "
            .. "FROM file_tags JOIN files ON files.id=file_tags.file_id "
            .. "WHERE files.missing=0 GROUP BY file_tags.file_id "
            .. "HAVING count(DISTINCT file_tags.tag_id)>=2 "
            .. "ORDER BY count(DISTINCT file_tags.tag_id) DESC LIMIT 1),"
            .. "wanted(tag_id) AS (SELECT tag_id FROM file_tags "
            .. "WHERE file_id=(SELECT file_id FROM chosen) "
            .. "ORDER BY tag_id LIMIT 2),"
            .. "matched(file_id) AS (SELECT file_tags.file_id "
            .. "FROM file_tags JOIN wanted ON wanted.tag_id=file_tags.tag_id "
            .. "GROUP BY file_tags.file_id "
            .. "HAVING count(DISTINCT file_tags.tag_id)="
            .. "(SELECT count(*) FROM wanted)) "
            .. "SELECT 'F',files.id,hex(files.name),"
            .. "hex(files.canonical_path),files.media_type,0,files.classification "
            .. "FROM matched JOIN files ON files.id=matched.file_id "
            .. "WHERE files.missing=0 "
            .. "ORDER BY files.name COLLATE NOCASE,files.id LIMIT "
            .. tostring(limit) .. " OFFSET " .. tostring(offset) .. ";\n"
    elseif mode == "filter_class" then
        sql[#sql + 1] =
            "WITH chosen(tag_id) AS (SELECT tags.id FROM tags "
            .. "JOIN file_tags ON file_tags.tag_id=tags.id "
            .. "JOIN files ON files.id=file_tags.file_id "
            .. "WHERE files.missing=0 "
            .. "AND tags.name_norm IN ('loop','one-shot') "
            .. "GROUP BY tags.id ORDER BY count(*) DESC LIMIT 1) "
            .. "SELECT 'F',files.id,hex(files.name),"
            .. "hex(files.canonical_path),files.media_type,0,files.classification FROM file_tags "
            .. "JOIN files ON files.id=file_tags.file_id "
            .. "WHERE files.missing=0 AND file_tags.tag_id="
            .. "(SELECT tag_id FROM chosen) "
            .. "GROUP BY files.id "
            .. "ORDER BY files.name COLLATE NOCASE,files.id LIMIT "
            .. tostring(limit) .. " OFFSET " .. tostring(offset) .. ";\n"
    elseif mode == "filter_key" then
        sql[#sql + 1] =
            "WITH chosen(key_pc,key_mode) AS (SELECT key_pc,key_mode "
            .. "FROM files WHERE missing=0 AND key_pc IS NOT NULL "
            .. "GROUP BY key_pc,key_mode ORDER BY count(*) DESC LIMIT 1) "
            .. "SELECT 'F',files.id,hex(files.name),"
            .. "hex(files.canonical_path),files.media_type,0,files.classification FROM files "
            .. "WHERE files.missing=0 AND files.key_pc="
            .. "(SELECT key_pc FROM chosen) AND "
            .. "COALESCE(files.key_mode,'')="
            .. "COALESCE((SELECT key_mode FROM chosen),'') "
            .. "ORDER BY files.name COLLATE NOCASE,files.id LIMIT "
            .. tostring(limit) .. " OFFSET " .. tostring(offset) .. ";\n"
    else
        folder_id = math.max(0, math.floor(tonumber(folder_id) or 0))
        -- Folders always sort before files, so issue two independently indexed
        -- streams. The parser concatenates them and trims the combined page.
        -- This avoids a million-row UNION sort for unusually flat folders.
        if not cursor or cursor.kind == "D" then
            sql[#sql + 1] =
                "SELECT 'D',child.id,hex(child.name),hex(roots.display_path||"
                .. "CASE WHEN child.relative_path='' THEN '' ELSE '/'||"
                .. "child.relative_path END),'',child.id,'',"
                .. "COALESCE(folder_subtree_stats.file_count,0) "
                .. "FROM folders AS child JOIN roots ON roots.id=child.root_id "
                .. "LEFT JOIN folder_subtree_stats ON "
                .. "folder_subtree_stats.folder_id=child.id WHERE child.missing=0 "
                .. "AND roots.enabled=1 AND child.parent_id=" .. tostring(folder_id)
                .. (cursor and (" AND (child.name COLLATE NOCASE>"
                    .. SQLQuote(cursor.name or "") .. " OR (child.name="
                    .. SQLQuote(cursor.name or "") .. " COLLATE NOCASE AND child.id>"
                    .. tostring(cursor_id) .. "))") or "")
                .. " ORDER BY child.name COLLATE NOCASE,child.id LIMIT "
                .. tostring(limit) .. ";\n"
        end
        sql[#sql + 1] =
            "SELECT 'F',files.id,hex(files.name),hex(files.canonical_path),"
            .. "files.media_type,locations.folder_id,files.classification,0 "
            .. "FROM folder_files AS locations INDEXED BY "
            .. "idx_folder_files_folder_name JOIN files ON files.id=locations.file_id "
            .. "WHERE locations.folder_id=" .. tostring(folder_id)
            .. " AND locations.missing=0 AND files.missing=0 AND "
            .. "(files.file_size IS NULL OR files.file_size>0) "
            .. (cursor and cursor.kind == "F" and ("AND (locations.name_sort>"
                .. SQLQuote((cursor.name or ""):lower())
                .. " OR (locations.name_sort="
                .. SQLQuote((cursor.name or ""):lower())
                .. " AND locations.file_id>" .. tostring(cursor_id) .. ")) ") or "")
            .. "ORDER BY locations.name_sort,locations.file_id LIMIT "
            .. tostring(limit) .. ";\n"
    end
    if ShouldRequestExactCanonicalCount(mode, offset) then
        local count_smart_mode = mode:match("^smart_") and mode or nil
        local count_match = BuildCanonicalUnifiedMatchCTE(
            folder_id, nil, nil, nil, count_smart_mode)
        sql[#sql + 1] = "WITH RECURSIVE " .. count_match
            .. " SELECT 'N',count(DISTINCT file_id) FROM matched;\n"
    end
    paging.pending_mode = mode
    paging.pending_folder_id = folder_id
    paging.pending_offset = offset
    paging.started_at = r.time_precise()
    return StartDatabaseBatchAsync(
        table.concat(sql), 0, "canonical_page", GetCanonicalDatabasePath())
end

local function CanonicalBrowserCacheKey(
    mode, folder_id, offset, collection_key_override)
    local browser = state.canonical_browser
    local classes = {}
    for name, enabled in pairs(browser.selected_classes or {}) do
        if enabled then classes[#classes + 1] = name end
    end
    table.sort(classes)
    local suffix = ":" .. NormalizeTag(browser.search_text or "")
        .. ":t=" .. table.concat(GetCanonicalBrowserSelectedTags(), "|")
        .. ":c=" .. table.concat(classes, "|")
        .. ":k=" .. tostring(math.floor(tonumber(browser.key_pc) or -1))
        .. ":s=" .. tostring(browser.smart_mode or "")
        .. ":collection=" .. tostring(
            collection_key_override or browser.collection_key or "")
        .. ":collection_scope="
            .. tostring(browser.collection_scope_key or "")
        .. ":favorite_sort=" .. tostring(state.favorite_sort or "added")
        .. ":favorites=" .. tostring(state.favorites_mode == true)
    return tostring(mode) .. ":" .. tostring(folder_id or 0)
        .. ":" .. tostring(offset or 0) .. suffix
end

local function PutCanonicalBrowserCache(
    key, rows, has_more, elapsed_ms, prefetched, total_count, next_cursor,
    offset)
    local browser = state.canonical_browser
    browser.cache[key] = {
        rows = rows, has_more = has_more, elapsed_ms = elapsed_ms or 0,
        prefetched = prefetched == true,
        total_count = total_count,
        next_cursor = next_cursor,
        offset = math.max(0, math.floor(tonumber(offset) or 0)),
    }
    for index = #browser.cache_order, 1, -1 do
        if browser.cache_order[index] == key then
            table.remove(browser.cache_order, index)
        end
    end
    browser.cache_order[#browser.cache_order + 1] = key
    while #browser.cache_order > (browser.cache_limit or 12) do
        local expired = table.remove(browser.cache_order, 1)
        browser.cache[expired] = nil
    end
end

local function BuildCanonicalPageCursor(rows)
    local row = rows and rows[#rows]
    if not row then return nil end
    return {
        id = math.max(0, math.floor(tonumber(row.id) or 0)),
        name = tostring(row.name or ""),
        kind = tostring(row.kind or "F"),
    }
end

local function ClearCanonicalResultPages()
    local browser = state.canonical_browser
    for index = #browser.cache_order, 1, -1 do
        local key = browser.cache_order[index]
        if key:match("^browser_search:")
            or key:match("^browser_filter:") then
            browser.cache[key] = nil
            table.remove(browser.cache_order, index)
        end
    end
end

local function ClearCanonicalTagCatalogCache()
    local browser = state.canonical_browser
    browser.tag_catalog_cache = {}
    browser.tag_catalog_cache_order = {}
    browser.tag_cardinality_hints = {}
    browser.available_tags = {}
    state.media_tag_bar.canonical_scope_key = nil
end

local function InvalidateCanonicalFavoriteViews()
    local browser = state.canonical_browser
    local deferred_accordion = browser.deferred_request
        and browser.deferred_request.accordion_target
        and browser.deferred_request or nil
    browser.favorite_scope_counts = {}
    browser.favorite_scope_upper_bounds = {}
    for index = #browser.cache_order, 1, -1 do
        local key = browser.cache_order[index]
        if key:match("^smart_favorites:")
            or key:match("^smart_collection:")
            or key:match("^favorite_collection_items:")
            or key:match("^favorite_root_items:") then
            browser.cache[key] = nil
            table.remove(browser.cache_order, index)
        end
    end
    -- Library tag catalogs do not change when a heart is toggled. Only the
    -- active Favorites surface needs its dynamic catalog discarded.
    if state.favorites_mode then
        ClearCanonicalTagCatalogCache()
        ResetCanonicalForegroundView("Favorites changed", false)
        -- The visible rows may be retained while the refreshed page is
        -- pending, but its old aggregate count must not survive a favorite
        -- removal and keep the navigation badge stale.
        browser.total_count = nil
        browser.loaded_file_count = nil
        browser.loaded_file_last_page_offset = nil
        -- A newly favorited folder may be opened before its write commits.
        -- That folder page is deliberately deferred behind the writer and is
        -- still valid after membership cache invalidation; do not discard it
        -- with result-view requests from the previous Favorites generation.
        if deferred_accordion then
            browser.deferred_request = deferred_accordion
            state.canonical_paging.deferred_queued_at = r.time_precise()
        end
        -- Smart Favorites pages are canonical result pages. Reissue the
        -- current page after invalidating it so membership changes become
        -- visible without another navigation action.
        if browser.smart_mode then
            browser.offset = 0
            RequestCanonicalBrowserPage(
                browser.smart_mode, browser.current_folder_id,
                0, false, false)
        end
    end
end

-- A root scan changes every folder/page relationship.  Drop queued work from
-- the previous library generation as well as the visible caches; otherwise a
-- stale page or tag request can run ahead of the user's first folder request
-- after the scan commits.
local function ResetCanonicalNavigationAfterLibraryChange()
    local browser = state.canonical_browser
    local paging = state.canonical_paging
    browser.deferred_request = nil
    browser.pending_prefetch = nil
    browser.pending_tag_folder_id = nil
    browser.pending_tag_time = nil
    browser.folder_scope_counts = {}
    browser.favorite_scope_counts = {}
    browser.favorite_scope_upper_bounds = {}
    paging.deferred_queued_at = nil
    paging.accordion_requested_at = nil
    paging.tag_requested_at = nil
end

local function PutCanonicalTagCatalogCache(key, tags)
    local browser = state.canonical_browser
    local copy = {}
    for index, tag in ipairs(tags or {}) do
        copy[index] = {name = tag.name, count = tag.count}
    end
    browser.tag_catalog_cache[key] = copy
    for index = #browser.tag_catalog_cache_order, 1, -1 do
        if browser.tag_catalog_cache_order[index] == key then
            table.remove(browser.tag_catalog_cache_order, index)
        end
    end
    browser.tag_catalog_cache_order[#browser.tag_catalog_cache_order + 1] = key
    while #browser.tag_catalog_cache_order
        > (browser.tag_catalog_cache_limit or 24) do
        local expired = table.remove(browser.tag_catalog_cache_order, 1)
        browser.tag_catalog_cache[expired] = nil
    end
end

local function ShuffleCanonicalFileRows(rows, first_index)
    local positions, files = {}, {}
    for index = math.max(1, first_index or 1), #rows do
        if rows[index].kind == "F" then
            positions[#positions + 1] = index
            files[#files + 1] = rows[index]
        end
    end
    for index = #files, 2, -1 do
        local swap = math.random(index)
        files[index], files[swap] = files[swap], files[index]
    end
    for index, position in ipairs(positions) do
        rows[position] = files[index]
    end
end

local function CanonicalAccordionNode(row, parent)
    local is_folder = row.kind == "R" or row.kind == "D"
    local media_kind = row.media_type
    if not is_folder and IsMidiFile(row.path) then media_kind = "midi" end
    if is_folder and row.folder_id and row.subtree_file_count ~= nil then
        state.canonical_browser.folder_scope_counts[row.folder_id] =
            tonumber(row.subtree_file_count)
    end
    return {
        name = row.name,
        name_lower = (row.name or ""):lower(),
        path = row.path,
        is_folder = is_folder,
        children = is_folder and {} or nil,
        files = is_folder and {} or nil,
        parent = parent,
        depth = parent and ((parent.depth or 0) + 1) or 0,
        media_kind = media_kind,
        classification = row.classification,
        -- Canonical root pages identify true Library roots with kind "R".
        -- Keep that authoritative identity on the node so the Favorites
        -- gutter cannot make a root look like an indented regular folder
        -- when configured-path text and database display paths differ.
        _canonical_is_library_root = row.kind == "R",
        _canonical_folder_id = is_folder and row.folder_id or nil,
        _canonical_loaded = false,
        _canonical_loading = false,
        _canonical_offset = 0,
        _canonical_has_more = false,
        _canonical_loaded_file_count = nil,
        _canonical_file_last_page_offset = nil,
        _canonical_subtree_file_count = tonumber(row.subtree_file_count),
    }
end

local function CountCanonicalPageFiles(rows)
    local count = 0
    for _, row in ipairs(rows or {}) do
        if row.kind ~= "R" and row.kind ~= "D" and row.kind ~= "T" then
            count = count + 1
        end
    end
    return count
end

local function ApplyCanonicalAccordionPage(page, append, target)
    local apply_started = r.time_precise()
    local browser = state.canonical_browser
    -- Files inside a favorited physical folder inherit that folder's status,
    -- but may also be direct favorites. Prime the bounded membership cache so
    -- their hearts can distinguish inherited from direct state after reload.
    -- Custom collection pages are already membership-qualified by their SQL.
    if not state.favorites_mode
        or (type(target) == "table" and not target.is_collection
            and not target.is_favorite_root_files) then
        PrimeCanonicalFavoriteMembershipCache(page.rows)
    end
    if target == "__roots__" then
        local roots = append and state.folder_tree or {}
        for _, row in ipairs(page.rows or {}) do
            if row.kind == "R" then
                roots[#roots + 1] = CanonicalAccordionNode(row, nil)
            end
        end
        state.folder_tree = roots
        state.open_folders = {}
        browser.loading = false
        browser.accordion_loading = false
        browser.accordion_error = nil
        -- A relaunched browser warmed a folder query during startup validation,
        -- but a freshly committed root previously stopped after loading roots.
        -- Queue the new root's first page now so its first expansion is a cache
        -- hit and does not pay SQLite/index cold-start cost.
        local warm_path = state.library_scan.newly_added_root
        if warm_path then
            local warm_key = NormalizeFavoritePath(warm_path)
            for _, root in ipairs(roots) do
                if NormalizeFavoritePath(root.path) == warm_key
                    and root._canonical_folder_id then
                    browser.pending_prefetch = {
                        mode = "folder",
                        folder_id = root._canonical_folder_id,
                        offset = 0,
                    }
                    break
                end
            end
        end
        state.needs_visible_update = true
        return
    end
    if type(target) ~= "table" then return end
    -- A scan commit can rebuild either tree while a child-page request is in
    -- flight. The request then points at the old Lua node object. Resolve the
    -- current node by persistent path before applying rows; otherwise the
    -- arrow opens against an orphan node and the visible row remains empty.
    if target.path then
        local active_tree = state.favorites_mode
            and state.favorite_tree or state.folder_tree
        local target_instance_key = state.favorites_mode
            and GetFavoriteNodeInstanceKey(target) or nil
        local function FindCurrent(nodes)
            for _, candidate in ipairs(nodes or {}) do
                local same_target = candidate.path == target.path
                    and (not state.favorites_mode
                        or GetFavoriteNodeInstanceKey(candidate)
                            == target_instance_key)
                if same_target then return candidate end
                local found = FindCurrent(candidate.children)
                if found then return found end
            end
        end
        local current = FindCurrent(active_tree)
        if current then target = current end
    end
    local page_offset = math.max(0, math.floor(
        tonumber(page.offset) or 0))
    local page_file_count = CountCanonicalPageFiles(page.rows)
    if append then
        if target._canonical_file_last_page_offset ~= page_offset then
            target._canonical_loaded_file_count =
                (target._canonical_loaded_file_count or 0) + page_file_count
            target._canonical_file_last_page_offset = page_offset
        end
    else
        target._canonical_loaded_file_count = page_file_count
        target._canonical_file_last_page_offset = page_offset
    end
    if not append then
        if target.is_collection then
            local collection_children = {}
            for _, child in ipairs(target.children or {}) do
                if child.is_collection then
                    collection_children[#collection_children + 1] = child
                end
            end
            target.children = collection_children
        else
            target.children = {}
        end
        target.files = {}
    end
    local existing_rows = {}
    if append then
        for _, child in ipairs(target.children or {}) do
            if not child.is_collection then
                existing_rows["D\31" .. NormalizeFavoritePath(child.path)] = true
            end
        end
        for _, file in ipairs(target.files or {}) do
            existing_rows["F\31" .. NormalizeFavoritePath(file.path)] = true
        end
    end
    for _, row in ipairs(page.rows or {}) do
        local node = CanonicalAccordionNode(row, target)
        local row_key = (node.is_folder and "D\31" or "F\31")
            .. NormalizeFavoritePath(node.path)
        if not existing_rows[row_key] then
            existing_rows[row_key] = true
            if target.is_collection then
                node._favorite_collection_id = target.collection_id
                node._canonical_favorite = true
            elseif target.is_favorite_root_files then
                node._canonical_favorite = true
                node._favorite_root_membership = true
                -- Direct loose files are intentionally absent from the startup
                -- cache for scalability. The root page is bounded, so hydrate
                -- the complete ownership of each visible row here. A later
                -- root-only removal can then preserve custom-folder ownership
                -- (and the Library heart) without a synchronous database read.
                EnsureFavoriteIndex()
                local favorite_key = NormalizeFavoritePath(node.path or "")
                local favorite_index = state.favorite_index[favorite_key]
                local favorite_entry = favorite_index
                    and state.favorites[favorite_index] or nil
                if not favorite_entry then
                    favorite_entry = {
                        kind = "file", path = node.path,
                        added = 0, collection_ids = {},
                        _direct_favorite = true,
                    }
                    AddCanonicalFavoriteCacheEntry(favorite_entry)
                else
                    favorite_entry._direct_favorite = true
                    favorite_entry.collection_ids =
                        favorite_entry.collection_ids or {}
                end
                local encoded_memberships = tostring(
                    row.favorite_collection_keys or "")
                if encoded_memberships:sub(1, 1) == "M" then
                    encoded_memberships = encoded_memberships:sub(2)
                else
                    encoded_memberships = ""
                end
                for encoded_key in encoded_memberships:gmatch("[^,]+") do
                    local collection_key = DecodeSQLHex(encoded_key)
                    if collection_key ~= "" then
                        favorite_entry.collection_ids[collection_key] = true
                    end
                end
                state.favorite_membership_cache[favorite_key] = true
            end
            if node.is_folder then
                target.children[#target.children + 1] = node
            else
                target.files[#target.files + 1] = node
            end
        end
    end
    local reveal = state.canonical_reveal
    local reveal_matches = reveal and not append
        and ((reveal.folder_id
                and target._canonical_folder_id == reveal.folder_id)
            or (reveal.folder_path
                and NormalizeFavoritePath(target.path or "")
                    == NormalizeFavoritePath(reveal.folder_path)))
    if reveal_matches then
        local already_present = false
        for _, file in ipairs(target.files or {}) do
            if NormalizeFavoritePath(file.path) == reveal.path then
                already_present = true
                break
            end
        end
        if not already_present and reveal.node then
            reveal.node.parent = target
            target.files[#target.files + 1] = reveal.node
        end
        state.scroll_to_cursor = true
        state.canonical_reveal = nil
    end
    local paged_child_count = 0
    for _, child in ipairs(target.children or {}) do
        if not child.is_collection then
            paged_child_count = paged_child_count + 1
        end
    end
    local retained_count = paged_child_count + #target.files
    local overflow = math.max(
        0, retained_count - RB_MAX_CANONICAL_ACCORDION_ROWS)
    if overflow > 0 then
        local trim_children = math.min(overflow, paged_child_count)
        if trim_children > 0 then
            local kept = {}
            local trimmed = 0
            for _, child in ipairs(target.children) do
                if child.is_collection or trimmed >= trim_children then
                    kept[#kept + 1] = child
                else
                    trimmed = trimmed + 1
                end
            end
            target.children = kept
        end
        local trim_files = overflow - trim_children
        if trim_files > 0 then
            local protected_path = append
                and state.cursor_type == "file" and state.cursor_path or nil
            local protected_file = nil
            if protected_path then
                for index = 1, math.min(trim_files, #target.files) do
                    local candidate = target.files[index]
                    if candidate.path == protected_path then
                        protected_file = candidate
                        break
                    end
                end
            end
            local kept = {}
            for index = trim_files + 1, #target.files do
                kept[#kept + 1] = target.files[index]
            end
            if protected_file then
                -- Keep the active row visible even if a page response that
                -- started before the click finishes afterward. Replace one
                -- other retained row so the 600-row memory ceiling remains
                -- unchanged; the pinned row is released on the next page
                -- replacement or when selection moves elsewhere.
                local drop_index = #kept
                while drop_index > 0
                    and kept[drop_index].path == protected_path do
                    drop_index = drop_index - 1
                end
                if drop_index > 0 then table.remove(kept, drop_index) end
                kept[#kept + 1] = protected_file
                state.scroll_to_cursor = true
            end
            target.files = kept
        end
        target._canonical_window_start_offset =
            (target._canonical_window_start_offset or 0) + overflow
        -- The retained row count stays fixed once the 600-row window is full,
        -- so ImGui cannot infer that a new page arrived from content height.
        -- Rebase the shared accordion viewport after mouse release instead of
        -- leaving its scrollbar thumb stranded at the bottom.
        if r.time_precise() - (state.keyboard_navigation_at or 0) < 0.4 then
            -- Keyboard paging follows the selected row, not the scrollbar.
            -- The clipper will include it and SetScrollHereY will preserve the
            -- navigation anchor on the next draw.
            state.accordion_scroll_rebase_pending = false
            state.scroll_to_cursor = true
        else
            state.accordion_scroll_rebase_pending = true
        end
    elseif not append then
        target._canonical_window_start_offset = page_offset
    end
    target._canonical_offset = page_offset + #(page.rows or {})
    target._canonical_has_more = page.has_more == true
    target._canonical_cursor = page.next_cursor
    target._canonical_loading = false
    target._canonical_loaded = not target._canonical_has_more
    browser.loading = false
    -- Tag catalog work follows the child-page application as an explicit
    -- pipeline step. It no longer depends on a wall-clock delay.
    if state.media_tag_bar.open and target._canonical_folder_id
        and (not state.favorites_mode
            or browser.current_folder_id == target._canonical_folder_id) then
        browser.pending_tag_folder_id = target._canonical_folder_id
        browser.pending_tag_time = 0
    end
    state.needs_visible_update = true
end

local function ApplyCanonicalBrowserPage(page, append, accordion_target)
    if accordion_target then
        ApplyCanonicalAccordionPage(page, append, accordion_target)
        return
    end
    local browser = state.canonical_browser
    -- Smart Favorites/collection pages are already membership-qualified by
    -- their SQL predicate. Avoid another synchronous shell-backed probe for
    -- every row when a mutation refreshes those pages.
    local membership_qualified = state.favorites_mode
        and (browser.smart_mode == "smart_favorites"
            or browser.smart_mode == "smart_collection")
    local favorites_scope_qualified = state.favorites_mode
        and (membership_qualified
            or (browser.smart_mode == nil
                and (browser.current_folder_id ~= nil
                    or browser.collection_scope_key ~= nil)))
    if not favorites_scope_qualified then
        PrimeCanonicalFavoriteMembershipCache(page.rows)
    end
    local page_offset = math.max(0, math.floor(
        tonumber(page.offset) or 0))
    local page_file_count = CountCanonicalPageFiles(page.rows)
    if append then
        if browser.loaded_file_last_page_offset ~= page_offset then
            browser.loaded_file_count =
                (browser.loaded_file_count or 0) + page_file_count
            browser.loaded_file_last_page_offset = page_offset
        end
    else
        browser.loaded_file_last_page_offset = page_offset
        if page_offset == 0 then
            browser.loaded_file_count = page_file_count
        else
            browser.loaded_file_count = math.max(
                browser.loaded_file_count or 0, page_file_count)
        end
    end
    local shuffle_from = 1
    if append then
        local combined = {}
        for _, row in ipairs(browser.rows) do combined[#combined + 1] = row end
        shuffle_from = #combined + 1
        for _, row in ipairs(page.rows) do combined[#combined + 1] = row end
        local overflow = math.max(0, #combined - RB_MAX_CANONICAL_RESULT_ROWS)
        if overflow > 0 then
            local bounded = {}
            for index = overflow + 1, #combined do
                bounded[#bounded + 1] = combined[index]
            end
            browser.rows = bounded
            browser.window_start_offset =
                (browser.window_start_offset or 0) + overflow
            browser.rows_trimmed = true
            if r.time_precise() - (state.keyboard_navigation_at or 0) < 0.4 then
                browser.scroll_rebase_pending = false
                state.scroll_to_cursor = true
            else
                browser.scroll_rebase_pending = true
            end
            shuffle_from = math.max(1, shuffle_from - overflow)
        else
            browser.rows = combined
        end
    else
        browser.rows = {}
        for _, row in ipairs(page.rows) do
            browser.rows[#browser.rows + 1] = row
        end
        browser.window_start_offset = page_offset
        browser.rows_trimmed = browser.window_start_offset > 0
    end
    browser.has_more = page.has_more
    browser.next_cursor = page.next_cursor
    if page.total_count ~= nil then
        browser.total_count = page.total_count
    end
    browser.last_ms = page.elapsed_ms or 0
    browser.loading = false
    browser.error = nil
    browser.status = string.format(
        "%d items · %d ms%s",
        #browser.rows, browser.last_ms,
        browser.has_more and " · more available" or "")
end

local function CanonicalAccordionTargetsMatch(left, right)
    if left == right then return true end
    if type(left) ~= "table" or type(right) ~= "table" then return false end
    if state.favorites_mode then
        return GetFavoriteNodeInstanceKey(left)
            == GetFavoriteNodeInstanceKey(right)
    end
    return left.path ~= nil and right.path ~= nil and left.path == right.path
end

local function ReleaseReplacedCanonicalAccordionRequest(next_target)
    local browser = state.canonical_browser
    local previous = browser.deferred_request
        and browser.deferred_request.accordion_target
    if type(previous) == "table"
        and not CanonicalAccordionTargetsMatch(previous, next_target) then
        -- Only one deferred request is retained. If a newer folder replaces
        -- it, the old node no longer owns any work and must not remain stuck
        -- in the loading state forever.
        previous._canonical_loading = false
        previous._canonical_started = false
    end
end

local HasPendingCanonicalTagWrites

function RequestCanonicalBrowserPage(
    mode, folder_id, offset, append, prefetch, accordion_target)
    local browser = state.canonical_browser
    local paging = state.canonical_paging
    -- Tag catalogs run after the foreground page, but they are not optional.
    -- Treating an unfiltered catalog as disposable made its visibility depend
    -- on whether an unrelated earlier query had tripped slow-read suppression.
    -- Folder/global catalogs use precomputed counts; filtered catalogs remain
    -- required because they are the user's active refinement surface.
    local filtered_tag_catalog = mode == "tag_catalog"
        and (next(browser.selected_tags or {}) ~= nil
            or next(browser.selected_classes or {}) ~= nil
            or (tonumber(browser.key_pc) or -1) >= 0
            or NormalizeTag(browser.search_text or "") ~= "")
    local required_tag_catalog = mode == "tag_catalog"
    if prefetch and not CanonicalOptionalReadsAllowed()
        and not required_tag_catalog then
        browser.pending_prefetch = nil
        if mode == "tag_catalog" then
            browser.pending_tag_folder_id = nil
            browser.pending_tag_time = nil
            browser.tag_catalog_refreshing = false
            paging.tag_requested_at = nil
        end
        return true
    end
    if mode ~= "browser_random" and mode ~= "tag_catalog"
        and not prefetch then
        browser.discovery_active = false
    end
    offset = math.max(0, math.floor(tonumber(offset) or 0))
    if not append and not prefetch and not accordion_target and offset == 0
        and mode ~= "tag_catalog" and mode ~= "resolve_favorite_folder" then
        browser.total_count = nil
        browser.loaded_file_count = nil
        browser.loaded_file_last_page_offset = nil
    end
    if state.database.worker_restart_pending
        or state.database.worker_refresh_requested then
        if prefetch then
            browser.pending_prefetch = {
                mode = mode, folder_id = folder_id, offset = offset,
            }
        else
            ReleaseReplacedCanonicalAccordionRequest(accordion_target)
            if not paging.deferred_queued_at then
                paging.deferred_queued_at = r.time_precise()
            end
            browser.deferred_request = {
                mode = mode, folder_id = folder_id, offset = offset,
                append = append == true,
                accordion_target = accordion_target,
            }
            if not accordion_target and not append then
                browser.loading = true
            end
            browser.error = nil
            browser.status = "Refreshing database worker..."
        end
        return true
    end
    local accordion_collection_key = type(accordion_target) == "table"
        and accordion_target.is_collection
        and tostring(accordion_target.collection_id or "") or nil
    local key = CanonicalBrowserCacheKey(
        mode, folder_id, offset, accordion_collection_key)
    local request_cursor = nil
    if offset > 0 and mode ~= "tag_catalog" and mode ~= "browser_random" then
        local previous_offset = math.max(
            0, offset - (paging.page_size or 100))
        local previous = browser.cache[
            CanonicalBrowserCacheKey(
                mode, folder_id, previous_offset,
                accordion_collection_key)]
        request_cursor = previous and previous.next_cursor
            or (type(accordion_target) == "table"
                and accordion_target._canonical_cursor or nil)
            or (not accordion_target and browser.next_cursor or nil)
    end
    if not prefetch and offset == 0
        and (mode == "browser_search" or mode == "browser_filter") then
        -- A new foreground query supersedes any queued page from the prior
        -- query. Keep folder/accordion pages cached, but do not spend the
        -- worker lane or Lua memory on obsolete result pages.
        browser.pending_prefetch = nil
        ClearCanonicalResultPages()
    end
    -- Accordion folders must become usable after one normal page. Loading
    -- 1,000 rows and then recursively draining every remaining page made the
    -- first click scale with the total size of the folder.
    -- A tag catalog is one bounded response, not a normal file page. Parsing
    -- it with the 100-row browser page size silently discarded alphabetically
    -- later tags after SQL had already selected them by relevance.
    local request_page_size = mode == "tag_catalog"
        and MEDIA_TAG_CATALOG_LIMIT or (paging.page_size or 100)
    local cacheable = mode ~= "browser_random" and mode ~= "tag_catalog"
        and mode ~= "resolve_favorite_folder"
        and mode ~= "favorite_scope_count"

    -- Custom tags are reflected in Lua immediately but persisted to SQLite
    -- through the user-data queue. Filter/search/random requests must wait for
    -- that index update; ordinary folder pages do not depend on it and should
    -- remain responsive while a tag write is pending.
    local tag_write_sensitive = mode == "browser_filter"
        or mode == "browser_search" or mode == "browser_random"
    if not prefetch and tag_write_sensitive
        and HasPendingCanonicalTagWrites() then
        ReleaseReplacedCanonicalAccordionRequest(accordion_target)
        browser.deferred_request = {
            mode = mode, folder_id = folder_id, offset = offset,
            append = append == true,
            accordion_target = accordion_target,
        }
        if not accordion_target and not append then
            browser.loading = true
        end
        browser.error = nil
        browser.status = "Saving custom tags before filtering..."
        return true
    end
    local cached = cacheable and browser.cache[key] or nil
    if mode == "tag_catalog" then
        browser.tag_catalog_refreshing = true
        local cached_tags = browser.tag_catalog_cache[key]
        if cached_tags then
            local current_key = CanonicalBrowserCacheKey(
                "tag_catalog", browser.current_folder_id, 0)
            if key == current_key then
                browser.available_tags = cached_tags
                browser.tag_catalog_refreshing = false
                browser.tag_catalog_refresh_started_at = nil
            end
            paging.tag_requested_at = nil
            return true
        end
    end
    if cached then
        if accordion_target then paging.accordion_requested_at = nil end
        if not prefetch then
            browser.error = nil
            if cached.prefetched then
                cached.prefetched = false
            end
            ApplyCanonicalBrowserPage(cached, append, accordion_target)
            if accordion_target then
                if accordion_target == "__roots__" then
                    if cached.has_more then
                        RequestCanonicalBrowserPage(
                            mode, folder_id,
                            offset + request_page_size,
                            true, false, accordion_target)
                    end
                elseif not append
                    and not (type(accordion_target) == "table"
                        and (accordion_target.is_collection
                            or accordion_target.is_favorite_root_files))
                    and (not state.favorites_mode
                        or browser.current_folder_id == folder_id) then
                    -- false is the queued root/dynamic-scope sentinel; nil
                    -- continues to mean that no catalog request is pending.
                    browser.pending_tag_folder_id = folder_id or false
                    browser.pending_tag_time = r.time_precise() + 0.4
                end
                return true
            end
            local next_offset = offset + (paging.page_size or 100)
            local next_key =
                CanonicalBrowserCacheKey(mode, folder_id, next_offset)
            if cached.has_more and not browser.cache[next_key]
                and not state.database.write_active then
                browser.pending_prefetch = {
                    mode = mode,
                    folder_id = folder_id,
                    offset = next_offset,
                }
            else
                browser.pending_prefetch = nil
            end
            if (not state.favorites_mode
                or CanonicalFavoriteFacetScopeActive())
                and (mode == "roots" or mode == "folder"
                or mode == "browser_search"
                or mode == "browser_filter"
                or mode == "smart_favorites" or mode == "smart_recent"
                or mode == "smart_used" or mode == "smart_collection") then
                RequestCanonicalBrowserPage(
                    "tag_catalog", folder_id, 0, false, true)
            end
        end
        return true
    end
    if paging.active then
        if prefetch then
            browser.pending_prefetch = {
                mode = mode, folder_id = folder_id, offset = offset,
            }
        else
            ReleaseReplacedCanonicalAccordionRequest(accordion_target)
            if not paging.deferred_queued_at then
                paging.deferred_queued_at = r.time_precise()
            end
            browser.deferred_request = {
                mode = mode, folder_id = folder_id, offset = offset,
                append = append == true,
                accordion_target = accordion_target,
            }
            if mode ~= "tag_catalog" then
                CancelActiveBrowserReadForForegroundRequest()
            end
            if not accordion_target and not append then
                browser.loading = true
            end
            browser.error = nil
            browser.status = "Waiting for the current library request..."
        end
        return true
    end
    if state.database.write_active then
        if not prefetch then
            ReleaseReplacedCanonicalAccordionRequest(accordion_target)
            if not paging.deferred_queued_at then
                paging.deferred_queued_at = r.time_precise()
            end
            browser.deferred_request = {
                mode = mode, folder_id = folder_id, offset = offset,
                append = append == true,
                accordion_target = accordion_target,
            }
            local pending_kind = state.database.write_pending_kind
                or "database write"
            if pending_kind == "canonical_membership" then
                CancelActiveCanonicalRead(
                    "foreground folder before favorite membership hydration")
            end
            if not accordion_target and not append then
                browser.loading = true
            end
            browser.status = "Waiting for the current library request..."
        end
        return true
    end
    paging.consumer = "browser"
    paging.active = true
    paging.browser_request = {
        mode = mode,
        folder_id = folder_id,
        offset = offset,
        append = append == true,
        prefetch = prefetch == true,
        cache_key = key,
        cacheable = cacheable,
        accordion_target = accordion_target,
        page_size = request_page_size,
        cursor = request_cursor,
        view_generation = browser.view_generation or 0,
        filtered_tag_catalog = filtered_tag_catalog == true,
    }
    if not prefetch and not accordion_target and not append then
        browser.loading = true
        browser.error = nil
        browser.status = "Loading..."
    end
    local request_wait_ms
    if paging.deferred_queued_at then
        request_wait_ms = math.floor(
            math.max(0, r.time_precise() - paging.deferred_queued_at)
                * 1000 + 0.5)
        paging.deferred_queued_at = nil
    else
        request_wait_ms = (mode == "tag_catalog" and paging.tag_requested_at
            or paging.accordion_requested_at)
            and math.floor(math.max(0, r.time_precise()
                - (mode == "tag_catalog" and paging.tag_requested_at
                    or paging.accordion_requested_at)) * 1000 + 0.5) or 0
    end
    if mode == "tag_catalog" then
        paging.last_tag_wait_ms = request_wait_ms or 0
        paging.tag_requested_at = nil
    else
        paging.queue_wait_ms = request_wait_ms or 0
        paging.accordion_requested_at = nil
    end
    local ok, err = StartCanonicalPageQuery(
        mode, folder_id, offset, request_page_size,
        accordion_collection_key)
    if not ok then
        paging.active = false
        if mode == "tag_catalog" then
            browser.tag_catalog_refreshing = false
        end
        if type(accordion_target) == "table" then
            accordion_target._canonical_loading = false
        elseif accordion_target == "__roots__" then
            browser.accordion_loading = false
        end
        browser.loading = false
        browser.status = "Database page could not be loaded."
        browser.error = tostring(err)
    end
    return ok
end

function LoadCanonicalAccordionRoots()
    local browser = state.canonical_browser
    browser.accordion_loading = true
    browser.accordion_error = nil
    -- Keep the current tree visible while the replacement root page is
    -- loading. Clearing it here caused a brief empty browser after the final
    -- scan commit, even though the new roots were already being requested.
    state.needs_visible_update = true
    state.canonical_paging.accordion_requested_at = r.time_precise()
    local requested = RequestCanonicalBrowserPage(
        "roots", nil, 0, false, false, "__roots__")
    return requested
end

function LoadCanonicalAccordionFolder(node)
    if not node or (not node.is_collection
        and not node.is_favorite_root_files
        and not node._canonical_folder_id) then
        return false
    end
    if node._canonical_loading then
        local paging = state.canonical_paging
        local active_target = paging.browser_request
            and paging.browser_request.accordion_target
        local deferred_target = state.canonical_browser.deferred_request
            and state.canonical_browser.deferred_request.accordion_target
        local still_owned = CanonicalAccordionTargetsMatch(node, active_target)
            or CanonicalAccordionTargetsMatch(node, deferred_target)
        if still_owned then return false end
        -- Recover nodes stranded by an older replaced/cancelled request.
        node._canonical_loading = false
    end
    if node._canonical_loaded then return false end
    node._canonical_loading = true
    node._canonical_started = true
    node._canonical_offset = 0
    node._canonical_window_start_offset = 0
    node._canonical_has_more = false
    state.canonical_browser.accordion_error = nil
    state.canonical_paging.accordion_requested_at = r.time_precise()
    local mode = node.is_collection and "favorite_collection_items"
        or node.is_favorite_root_files and "favorite_root_items"
        or "folder"
    local requested = RequestCanonicalBrowserPage(
        mode, (node.is_collection or node.is_favorite_root_files)
            and nil or node._canonical_folder_id,
        0, false, false, node)
    if not requested then
        -- A freshly favorited folder can be clicked while its SQLite write
        -- still owns the worker. Do not strand the new UI instance in a
        -- permanent loading state; the normal draw/click path can retry it as
        -- soon as the writer releases the lane.
        node._canonical_started = false
        node._canonical_loading = false
    end
    return requested
end

function LoadNextCanonicalAccordionPage(node)
    if not node or (not node.is_collection
        and not node.is_favorite_root_files and not node._canonical_folder_id)
        or node._canonical_loading or not node._canonical_has_more then
        return false
    end
    node._canonical_loading = true
    local mode = node.is_collection and "favorite_collection_items"
        or node.is_favorite_root_files and "favorite_root_items"
        or "folder"
    return RequestCanonicalBrowserPage(
        mode, (node.is_collection or node.is_favorite_root_files)
            and nil or node._canonical_folder_id,
        node._canonical_offset or 0, true, false, node)
end

function LoadPreviousCanonicalAccordionPage(node)
    if not node or (not node.is_collection
        and not node.is_favorite_root_files and not node._canonical_folder_id)
        or node._canonical_loading
        or (node._canonical_window_start_offset or 0) <= 0 then
        return false
    end
    local previous_offset = math.max(0,
        (node._canonical_window_start_offset or 0)
            - (state.canonical_paging.page_size or 100))
    node._canonical_loading = true
    local mode = node.is_collection and "favorite_collection_items"
        or node.is_favorite_root_files and "favorite_root_items"
        or "folder"
    return RequestCanonicalBrowserPage(
        mode, (node.is_collection or node.is_favorite_root_files)
            and nil or node._canonical_folder_id,
        previous_offset, false, false, node)
end

local CanonicalBrowserCurrentMode
local CanonicalBrowserFiltersActive
local CanonicalBrowserHasStructuredFilters
local CaptureCanonicalAccordionReturnState
local RestoreCanonicalAccordionReturnState

function OpenFavoriteSmartFolder(mode, name)
    if mode ~= "smart_favorites"
        and mode ~= "smart_recent" and mode ~= "smart_used"
        and mode ~= "smart_collection" then
        return
    end
    local browser = state.canonical_browser
    if state.favorites_mode and ClearCanonicalFavoriteFolderFacetScope then
        ClearCanonicalFavoriteFolderFacetScope(false)
    end
    ResetCanonicalForegroundView("Favorite smart view changed", true)
    state.favorite_smart_mode = mode
    browser.smart_mode = mode
    browser.collection_scope_key = nil
    if mode ~= "smart_collection" then browser.collection_key = nil end
    browser.history = {}
    browser.current_folder_id = nil
    browser.current_name = name or "Favorites"
    browser.current_path = nil
    browser.offset = 0
    browser.selected_path = nil
    browser.discovery_active = false
    browser.pending_prefetch = nil
    browser.random_history = {}
    browser.random_rows = {}
    browser.random_pool = {}
    browser.random_index = 0
    browser.random_force_start = false
    browser.random_wrap_rows = nil
    browser.random_cursor_key = nil
    browser.random_cursor_id = nil
    state.randomize_on = false
    state.multi_selected = {}
    state.selected_file_row_keys = {}
    state.selected_folder_scope = nil
    RequestCanonicalBrowserPage(mode, nil, 0, false, false)
end

function CloseFavoriteSmartFolder()
    local browser = state.canonical_browser
    if state.favorites_mode and ClearCanonicalFavoriteFolderFacetScope then
        ClearCanonicalFavoriteFolderFacetScope(false)
    end
    ResetCanonicalForegroundView("Favorite smart view closed", true)
    state.favorite_smart_mode = nil
    browser.smart_mode = nil
    browser.collection_key = nil
    browser.collection_scope_key = nil
    browser.history = {}
    browser.current_folder_id = nil
    browser.current_name = "Favorites"
    browser.current_path = nil
    browser.selected_path = nil
    browser.discovery_active = false
    browser.loading = false
    browser.rows = {}
    browser.has_more = false
    browser.total_count = nil
    browser.pending_prefetch = nil
    state.multi_selected = {}
    state.selected_file_row_keys = {}
    state.cursor_path = nil
    state.cursor_type = nil
    state.selected_folder_scope = nil
    if NormalizeTag(browser.search_text or "") ~= ""
        or CanonicalBrowserHasStructuredFilters() then
        RequestCanonicalBrowserPage(
            CanonicalBrowserCurrentMode(), nil, 0, false, false)
    else
        state.needs_visible_update = true
    end
end

function EnterCanonicalBrowserFolder(row)
    local browser = state.canonical_browser
    state.canonical_reveal = nil
    browser.history[#browser.history + 1] = {
        folder_id = browser.current_folder_id,
        name = browser.current_name,
        path = browser.current_path,
        smart_mode = browser.smart_mode,
    }
    -- Folder rows use ordinary folder browsing. When one is entered from an
    -- aggregate view, Back restores that view from the saved history entry.
    browser.smart_mode = nil
    browser.current_folder_id = row.folder_id
    browser.current_name = row.name
    browser.current_path = row.path
    state.selected_folder_scope = row.path
    browser.offset = 0
    browser.selected_path = nil
    RequestCanonicalBrowserPage(
        CanonicalBrowserCurrentMode(),
        browser.current_folder_id, 0, false, false)
end

function BackCanonicalBrowserFolder()
    local browser = state.canonical_browser
    state.canonical_reveal = nil
    local previous = table.remove(browser.history)
    if not previous then return end
    if state.favorites_mode and (previous.folder_id == nil
        or previous.smart_mode ~= nil) then
        ClearCanonicalFavoriteFolderFacetScope(false)
    end
    browser.current_folder_id = previous.folder_id
    browser.current_name = previous.name
    browser.current_path = previous.path
    browser.smart_mode = previous.smart_mode
    state.selected_folder_scope = previous.path
    browser.offset = 0
    browser.selected_path = nil
    RequestCanonicalBrowserPage(
        CanonicalBrowserCurrentMode(),
        browser.current_folder_id, 0, false, false)
end

function ExitCanonicalLuckyDraw()
    local browser = state.canonical_browser
    if not browser.discovery_active then return false end
    browser.discovery_active = false
    browser.clipper = nil
    browser.offset = 0
    browser.selected_path = nil
    state.multi_selected = {}
    if browser.smart_mode or CanonicalBrowserFiltersActive() then
        RequestCanonicalBrowserPage(
            CanonicalBrowserCurrentMode(),
            browser.current_folder_id, 0, false, false)
    else
        browser.loading = false
        browser.rows = {}
        RestoreCanonicalAccordionReturnState()
        state.needs_visible_update = true
    end
    return true
end

function CancelPendingMediaRowActivation()
    state.pending_single_node = nil
    state.pending_single_row_key = nil
    state.pending_ctrl_file = nil
    state.favorite_drag_pending_path = nil
    state.favorite_drag_pending_copy = false
end

function PreviewPaneOwnsMouseInput()
    local bounds = state.preview_pane_bounds
    if not bounds then return false end
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    if mouse_x < bounds.x1 or mouse_x > bounds.x2
        or mouse_y < bounds.y1 or mouse_y > bounds.y2 then
        return false
    end
    return imgui.IsMouseDown(ctx, 0)
        or imgui.IsMouseClicked(ctx, 0)
        or (imgui.IsMouseReleased and imgui.IsMouseReleased(ctx, 0))
end

function HomeCanonicalBrowser()
    CancelPendingMediaRowActivation()
    local browser = state.canonical_browser
    ResetCanonicalForegroundView("Library home opened", true)
    state.favorites_mode = false
    state.favorite_smart_mode = nil
    state.selected_folder_scope = nil
    state.search_input = ""
    state.search_text = ""
    state.force_search_update = true
    state.media_filters.selected_tags = {}
    state.media_filters.tag_text = ""
    state.media_filters.quick_types = {}
    state.media_filters.key_pc = -1
    state.media_tag_bar.cache_key = nil
    browser.smart_mode = nil
    browser.collection_key = nil
    browser.collection_scope_key = nil
    browser.history = {}
    browser.current_folder_id = nil
    browser.current_name = "Library"
    browser.current_path = nil
    browser.search_text = ""
    browser.selected_tags = {}
    browser.selected_classes = {}
    browser.key_pc = -1
    browser.available_tags = {}
    browser.pending_tag_folder_id = nil
    browser.tag_catalog_cache = {}
    browser.discovery_active = false
    browser.offset = 0
    browser.selected_path = nil
    browser.random_history = {}
    browser.random_rows = {}
    browser.random_pool = {}
    browser.random_index = 0
    browser.random_result = nil
    browser.random_force_start = false
    browser.random_wrap_rows = nil
    browser.random_cursor_key = nil
    browser.random_cursor_id = nil
    browser.error = nil
    browser.accordion_return_state = nil
    state.randomize_on = false
    state.multi_selected = {}
    state.cursor_path = nil
    state.cursor_type = nil
    state.open_folders = {}
    state.needs_visible_update = true
    browser.loading = false
    browser.rows = {}
    if #state.folder_tree == 0 then LoadCanonicalAccordionRoots() end
end

CanonicalBrowserHasStructuredFilters = function()
    local browser = state.canonical_browser
    local has_tags = next(browser.selected_tags or {}) ~= nil
    if state.favorites_mode
        and CanonicalFavoriteFacetScopeActive
        and not CanonicalFavoriteFacetScopeActive() then
        has_tags = false
    end
    return has_tags
        or next(browser.selected_classes or {}) ~= nil
        or (tonumber(browser.key_pc) or -1) >= 0
end

CanonicalBrowserCurrentMode = function()
    local browser = state.canonical_browser
    if browser.smart_mode then return browser.smart_mode end
    if browser.search_text ~= "" then return "browser_search" end
    if CanonicalBrowserHasStructuredFilters() then return "browser_filter" end
    return browser.current_folder_id and "folder" or "roots"
end

CanonicalBrowserFiltersActive = function()
    local browser = state.canonical_browser
    return NormalizeTag(state.search_input or "") ~= ""
        or NormalizeTag(browser.search_text or "") ~= ""
        or CanonicalBrowserHasStructuredFilters()
end

-- Favorites tags are intentionally scoped to a selected physical folder. Its
-- subtree counts are maintained during indexing, so opening the tag bar does
-- not scale with the total size of an ever-growing Favorites collection.
function CanonicalFavoriteFacetScopeActive()
    if not state.favorites_mode then return true end
    local browser = state.canonical_browser
    return browser.current_folder_id ~= nil
        and browser.smart_mode == nil
        and browser.collection_scope_key == nil
end

function CanonicalFavoriteRandomScopeAvailable()
    -- Every Favorites surface has an indexed canonical membership scope:
    -- direct/custom items plus descendants of favorited physical folders.
    -- Randomize therefore queries the complete scope instead of depending on
    -- which accordion rows happen to be loaded.
    return true
end

function ClearCanonicalFavoriteFolderFacetScope(clear_rows)
    if not state.favorites_mode then return false end
    local browser = state.canonical_browser
    local had_tags = next(browser.selected_tags or {}) ~= nil
    local had_scope_filters = had_tags
        or next(browser.selected_classes or {}) ~= nil
        or (tonumber(browser.key_pc) or -1) >= 0
        or NormalizeTag(browser.search_text or "") ~= ""
    if clear_rows and had_scope_filters then
        ResetCanonicalForegroundView("Favorites tag scope cleared", true)
    end
    browser.selected_tags = {}
    browser.available_tags = {}
    browser.pending_tag_folder_id = nil
    browser.pending_tag_time = nil
    browser.random_history = {}
    browser.random_rows = {}
    browser.random_pool = {}
    browser.random_index = 0
    browser.random_result = nil
    browser.random_force_start = false
    browser.random_wrap_rows = nil
    browser.random_cursor_key = nil
    browser.random_cursor_id = nil
    browser.accordion_return_state = nil
    state.media_filters.selected_tags = {}
    state.randomize_on = false
    state.media_tag_bar.canonical_scope_key = nil
    return had_tags
end

local function CanonicalResultViewActive()
    return state.database_startup_test.enabled
        and (state.favorite_smart_mode ~= nil
            or state.canonical_browser.discovery_active
            or CanonicalBrowserFiltersActive())
end

local function CopyBooleanMap(source)
    local copy = {}
    for key, value in pairs(source or {}) do
        if value then copy[key] = true end
    end
    return copy
end

CaptureCanonicalAccordionReturnState = function()
    local browser = state.canonical_browser
    if browser.accordion_return_state then return end
    browser.accordion_return_state = {
        open_folders = CopyBooleanMap(state.open_folders),
        cursor_path = state.cursor_path,
        cursor_type = state.cursor_type,
        selected_folder_scope = state.selected_folder_scope,
        multi_selected = CopyBooleanMap(state.multi_selected),
        selection_anchor = state.selection_anchor,
        selection_anchor_row_key = state.selection_anchor_row_key,
    }
end

RestoreCanonicalAccordionReturnState = function()
    local browser = state.canonical_browser
    local saved = browser.accordion_return_state
    browser.accordion_return_state = nil
    if not saved then return false end
    state.open_folders = saved.open_folders or {}
    state.cursor_path = saved.cursor_path
    state.cursor_type = saved.cursor_type
    state.selected_folder_scope = saved.selected_folder_scope
    state.multi_selected = saved.multi_selected or {}
    state.selection_anchor = saved.selection_anchor
    state.selection_anchor_row_key = saved.selection_anchor_row_key
    state.scroll_to_cursor = state.cursor_path ~= nil
    -- Returning from search/random restores the highlighted accordion row.
    -- It must also restore that row's tag catalog, otherwise the tag bar
    -- keeps showing the previous result-view scope until the user clicks.
    local selected_folder = state.cursor_type == "folder"
        and state.cursor_path or state.selected_folder_scope
    if selected_folder and state.media_tag_bar.open then
        local function FindFolder(nodes)
            for _, node in ipairs(nodes or {}) do
                if node.path == selected_folder then return node end
                local found = FindFolder(node.children)
                if found then return found end
            end
        end
        local node = FindFolder(state.folder_tree)
        if node and node._canonical_folder_id then
            browser.pending_tag_folder_id = node._canonical_folder_id
            browser.pending_tag_time = 0
        end
    end
    if state.favorites_mode and state.media_tag_bar.open
        and CanonicalFavoriteFacetScopeActive() then
        state.media_tag_bar.canonical_scope_key = nil
        browser.pending_tag_folder_id = browser.current_folder_id or false
        browser.pending_tag_time = 0
    end
    state.needs_visible_update = true
    return true
end

function ResetCanonicalRandomState()
    local browser = state.canonical_browser
    browser.random_history = {}
    browser.random_rows = {}
    browser.random_pool = {}
    browser.random_index = 0
    browser.random_result = nil
    browser.random_force_start = false
    browser.random_wrap_rows = nil
    browser.random_cursor_key = nil
    browser.random_cursor_id = nil
    state.randomize_on = false
    state.random_history = {}
    state.random_history_index = 0
end

function PrepareCanonicalTagCatalogRefresh()
    local browser = state.canonical_browser
    -- Keep the last complete catalog on screen while its filtered replacement
    -- is calculated. Clearing down to only the selected chips made the first
    -- selection look permanently broken on a cold worker; repeating the same
    -- sequence merely hid that race by hitting a warm result. The completed
    -- catalog is still swapped in atomically, so incompatible tags disappear
    -- together instead of the bar collapsing and repopulating in stages.
    local catalog = {}
    local catalog_names = {}
    for _, tag in ipairs(browser.available_tags or {}) do
        local name = NormalizeTag(tag.name)
        if name ~= "" and not catalog_names[name] then
            catalog[#catalog + 1] = {
                name = name,
                count = tonumber(tag.count) or 0,
            }
            catalog_names[name] = true
        end
    end
    for name, enabled in pairs(browser.selected_tags or {}) do
        name = NormalizeTag(name)
        if enabled and name ~= "" and not catalog_names[name] then
            catalog[#catalog + 1] = {
                name = name,
                count = 0,
            }
            catalog_names[name] = true
        end
    end
    SortMediaTagCatalog(catalog, browser.selected_tags)
    browser.available_tags = catalog
    local tag_scope_available = not state.favorites_mode
        or CanonicalFavoriteFacetScopeActive()
    browser.tag_catalog_refreshing = tag_scope_available and (
        next(browser.selected_tags or {}) ~= nil
        or next(browser.selected_classes or {}) ~= nil
        or (tonumber(browser.key_pc) or -1) >= 0
        or NormalizeTag(browser.search_text or "") ~= "")
    browser.tag_catalog_refresh_started_at =
        browser.tag_catalog_refreshing and r.time_precise() or nil
    state.media_tag_bar.layout_source = nil
end

function ApplyCanonicalStructuredFilterChange()
    local browser = state.canonical_browser
    ResetCanonicalRandomState()
    -- A structured filter replaces the accordion with a canonical result
    -- page. Invalidate any folder/tag request that was already in flight so
    -- its completion cannot overwrite the new result view. The accordion
    -- selection itself has already been saved by the filter controls and is
    -- restored when the final structured filter is cleared.
    ResetCanonicalForegroundView("Structured filter changed", true)
    PrepareCanonicalTagCatalogRefresh()
    browser.offset = 0
    browser.selected_path = nil
    if not CanonicalBrowserHasStructuredFilters()
        and NormalizeTag(browser.search_text or "") == ""
        and not browser.smart_mode then
        browser.loading = false
        browser.rows = {}
        browser.has_more = false
        browser.total_count = nil
        RestoreCanonicalAccordionReturnState()
        state.needs_visible_update = true
        return true
    end
    -- Do not carry a live folder/file cursor into a flat result page. Apart
    -- from highlighting an unrelated row, a stale ensure-visible request can
    -- scroll the replacement page to a path from the previous folder. The
    -- saved accordion_return_state remains authoritative for returning home.
    state.cursor_path = nil
    state.cursor_type = nil
    state.multi_selected = {}
    state.selected_file_row_keys = {}
    state.selection_anchor = nil
    state.selection_anchor_row_key = nil
    state.pending_single_node = nil
    state.pending_single_row_key = nil
    state.pending_ctrl_file = nil
    state.scroll_to_cursor = false
    RequestCanonicalBrowserPage(
        CanonicalBrowserCurrentMode(),
        browser.current_folder_id, 0, false, false)
    return true
end

function ClearCanonicalBrowserFilters()
    local browser = state.canonical_browser
    state.search_input = ""
    state.search_text = ""
    state.force_search_update = true
    state.media_filters.selected_tags = {}
    state.media_filters.tag_text = ""
    state.media_filters.quick_types = {}
    state.media_filters.key_pc = -1
    state.media_tag_bar.cache_key = nil
    browser.search_text = ""
    browser.selected_tags = {}
    browser.selected_classes = {}
    browser.key_pc = -1
    ResetCanonicalRandomState()
    browser.offset = 0
    browser.selected_path = nil
    browser.error = nil
    state.multi_selected = {}
    state.selected_file_row_keys = {}
    state.selection_anchor = nil
    state.selection_anchor_row_key = nil
    state.pending_single_node = nil
    state.pending_single_row_key = nil
    state.pending_ctrl_file = nil
    if browser.smart_mode then
        RequestCanonicalBrowserPage(
            browser.smart_mode, browser.current_folder_id,
            0, false, false)
    else
        browser.loading = false
        browser.rows = {}
        RestoreCanonicalAccordionReturnState()
        state.needs_visible_update = true
    end
end

function ToggleCanonicalBrowserTag(name)
    local browser = state.canonical_browser
    if state.favorites_mode
        and not CanonicalFavoriteFacetScopeActive() then
        return false
    end
    CaptureCanonicalAccordionReturnState()
    name = NormalizeTag(name)
    browser.selected_tags[name] = not browser.selected_tags[name]
    if not browser.selected_tags[name] then browser.selected_tags[name] = nil end
    ApplyCanonicalStructuredFilterChange()
    return true
end

function ClearCanonicalBrowserTags()
    local browser = state.canonical_browser
    browser.selected_tags = {}
    browser.available_tags = {}
    browser.tag_catalog_refreshing = false
    ApplyCanonicalStructuredFilterChange()
end

function SelectCanonicalRandomResult(picked, add_to_history)
    if not picked or not picked.path then return false end
    local browser = state.canonical_browser
    browser.selected_path = picked.path
    browser.random_result = picked
    if add_to_history then
        browser.random_history[#browser.random_history + 1] = picked.id
        browser.random_rows[#browser.random_rows + 1] = picked
        while #browser.random_history > 20 do
            table.remove(browser.random_history, 1)
            table.remove(browser.random_rows, 1)
        end
        browser.random_index = #browser.random_rows
    end

    local found = false
    for _, row in ipairs(browser.rows or {}) do
        if row.path == picked.path then
            found = true
            break
        end
    end
    if not found then
        for index = #(browser.rows or {}), 1, -1 do
            if browser.rows[index]._random_injected then
                table.remove(browser.rows, index)
            end
        end
        picked._random_injected = true
        table.insert(browser.rows, 1, picked)
    end

    local node = picked._main_node or {
        path = picked.path,
        name = picked.name,
        is_folder = false,
    }
    picked._main_node = node
    SetCursorToFileNode(node, true)
    return true
end

local function LoadNextCanonicalBrowserPage()
    local browser = state.canonical_browser
    if not browser.has_more or browser.loading then return end
    -- An append request is still a foreground page load. Mark it immediately
    -- so repeated clipper/scroll callbacks cannot queue duplicate offsets
    -- while the tag catalog or worker lane is finishing another request.
    browser.loading = true
    browser.pending_prefetch = nil
    local next_offset =
        (browser.offset or 0) + (state.canonical_paging.page_size or 100)
    browser.offset = next_offset
    RequestCanonicalBrowserPage(
        CanonicalBrowserCurrentMode(),
        browser.current_folder_id, next_offset, true, false)
end

function GetCanonicalUserDataJournalPath()
    return GetReaBrowseDataDirectory() .. "/Pending_User_Data_v1.tsv"
end

function EncodeCanonicalUserDataJournalField(value)
    return tostring(value or ""):gsub("%%", "%%25")
        :gsub("\r", "%%0D"):gsub("\n", "%%0A"):gsub("\t", "%%09")
end

function DecodeCanonicalUserDataJournalField(value)
    return tostring(value or ""):gsub("%%09", "\t")
        :gsub("%%0A", "\n"):gsub("%%0D", "\r"):gsub("%%25", "%%")
end

function IsDurableReplaySafeFavoriteEntry(entry)
    local key = tostring(entry and entry.key or "")
    -- These mutations only set/delete direct Favorites membership and can be
    -- replayed after an uncertain handoff without double-counting anything.
    return key:match("^favorite:") ~= nil
        or key:match("^favorite_entry:") ~= nil
        or key:match("^favorites_batch:") ~= nil
end

function AppendCanonicalFavoriteJournalEntry(entry)
    if not IsDurableReplaySafeFavoriteEntry(entry) then return true end
    local user_data = state.canonical_user_data
    if user_data and user_data.journal_file then
        local ok = user_data.journal_file:write(
            EncodeCanonicalUserDataJournalField(entry.key), "\t",
            tostring(math.max(0, math.floor(tonumber(entry.attempts) or 0))), "\t",
            EncodeCanonicalUserDataJournalField(entry.sql), "\n")
        return ok ~= nil
    end
    local path = GetCanonicalUserDataJournalPath()
    local has_header = false
    local existing = io.open(path, "rb")
    if existing then
        has_header = existing:read("*l")
            == "REABROWSE_USER_DATA_QUEUE\t1"
        existing:close()
    end
    local file = io.open(path, has_header and "ab" or "wb")
    if not file then return false end
    local wrote = true
    if not has_header then
        wrote = file:write("REABROWSE_USER_DATA_QUEUE\t1\n") ~= nil
    end
    if not wrote then
        file:close()
        return false
    end
    pcall(function() file:setvbuf("full", 32768) end)
    wrote = file:write(
        EncodeCanonicalUserDataJournalField(entry.key), "\t",
        tostring(math.max(0, math.floor(tonumber(entry.attempts) or 0))), "\t",
        EncodeCanonicalUserDataJournalField(entry.sql), "\n") ~= nil
    if wrote then
        user_data.journal_file = file
        return true
    end
    file:close()
    return false
end

function FlushCanonicalFavoriteJournal()
    local user_data = state.canonical_user_data
    if not user_data or not user_data.journal_file then return true end
    return user_data.journal_file:flush() ~= nil
end

function CloseCanonicalFavoriteJournal()
    local user_data = state.canonical_user_data
    if not user_data or not user_data.journal_file then return true end
    local file = user_data.journal_file
    user_data.journal_file = nil
    return file:close() ~= nil
end

function PersistCanonicalUserDataJournal()
    local user_data = state.canonical_user_data
    if not user_data then return false end
    CloseCanonicalFavoriteJournal()
    -- A launched SQLite process is not the same as an acknowledged commit.
    -- Keep replay-safe Favorite mutations durable until the .done result has
    -- been consumed. Inflight entries precede newly queued changes so an add
    -- followed by a remove retains its original order after recovery.
    local entries = {}
    for _, entry in ipairs(user_data.inflight or {}) do
        if IsDurableReplaySafeFavoriteEntry(entry) then
            entries[#entries + 1] = entry
        end
    end
    local queue = user_data.queue or {}
    local queue_head = user_data.queue_head or 1
    local queue_tail = user_data.queue_tail or #queue
    for index = queue_head, queue_tail do
        local entry = queue[index]
        if entry then
            entries[#entries + 1] = entry
        end
    end
    local path = GetCanonicalUserDataJournalPath()
    local writing_path = path .. ".writing"
    local backup_path = path .. ".previous"
    if #entries == 0 then
        pcall(os.remove, writing_path)
        pcall(os.remove, backup_path)
        pcall(os.remove, path)
        return true
    end
    local file = io.open(writing_path, "wb")
    if not file then return false end
    local wrote = file:write("REABROWSE_USER_DATA_QUEUE\t1\n")
    for _, entry in ipairs(entries) do
        if wrote then
            wrote = file:write(
                EncodeCanonicalUserDataJournalField(entry.key), "\t",
                tostring(math.max(0, math.floor(tonumber(entry.attempts) or 0))), "\t",
                EncodeCanonicalUserDataJournalField(entry.sql), "\n")
        end
    end
    local closed = file:close()
    if not wrote or closed == nil then
        pcall(os.remove, writing_path)
        return false
    end
    pcall(os.remove, backup_path)
    os.rename(path, backup_path)
    local renamed = os.rename(writing_path, path)
    if renamed then
        pcall(os.remove, backup_path)
        return true
    end
    os.rename(backup_path, path)
    pcall(os.remove, writing_path)
    return false
end

function LoadCanonicalUserDataJournal()
    local user_data = state.canonical_user_data
    if not user_data or user_data.journal_loaded then return 0 end
    user_data.journal_loaded = true
    user_data.queue = user_data.queue or {}
    user_data.queue_head = 1
    user_data.queue_tail = 0
    user_data.queue_key_index = {}
    local file = io.open(GetCanonicalUserDataJournalPath(), "rb")
    if not file then return 0 end
    local header = file:read("*l")
    if header ~= "REABROWSE_USER_DATA_QUEUE\t1" then
        file:close()
        return 0
    end
    local loaded = 0
    for line in file:lines() do
        local key, attempts, sql = line:match("^([^\t]*)\t(%d+)\t(.*)$")
        sql = DecodeCanonicalUserDataJournalField(sql)
        if sql ~= "" then
            key = DecodeCanonicalUserDataJournalField(key)
            local entry = {
                key = key ~= "" and key or nil,
                attempts = tonumber(attempts) or 0,
                sql = sql,
            }
            user_data.queue_tail = user_data.queue_tail + 1
            user_data.queue[user_data.queue_tail] = entry
            if entry.key then
                user_data.queue_key_index[entry.key] = entry
            end
            loaded = loaded + 1
        end
    end
    file:close()
    if loaded > 0 then
        user_data.status = "Recovering " .. tostring(loaded) .. " saved user change(s)..."
    else
        PersistCanonicalUserDataJournal()
    end
    return loaded
end

function ReplayRecoveredFavoritesBeforeLoad()
    local user_data = state.canonical_user_data
    if not user_data or CanonicalUserDataQueueCount(user_data) == 0
        or not FileExists(GetCanonicalDatabasePath()) then
        return 0
    end
    local recovered, remaining = {}, {}
    local queue = user_data.queue or {}
    local queue_head = user_data.queue_head or 1
    local queue_tail = user_data.queue_tail or #queue
    for index = queue_head, queue_tail do
        local entry = queue[index]
        if not entry then goto continue end
        if IsDurableReplaySafeFavoriteEntry(entry) then
            recovered[#recovered + 1] = entry
        else
            remaining[#remaining + 1] = entry
        end
        ::continue::
    end
    if #recovered == 0 then return 0 end

    local statements = {"BEGIN IMMEDIATE;\n"}
    for _, entry in ipairs(recovered) do
        statements[#statements + 1] = entry.sql
        if entry.sql:sub(-1) ~= "\n" then
            statements[#statements + 1] = "\n"
        end
    end
    statements[#statements + 1] = "COMMIT;\n"
    -- Use a launch-unique init file. A detached writer from the closing
    -- ReaBrowse instance may still have the normal batch file open.
    local recovery_path = state.database.batch_path .. ".favorites_recovery_"
        .. tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999))
    local ok, err = WriteDatabaseBatch(
        table.concat(statements), recovery_path, GetCanonicalDatabasePath())
    pcall(os.remove, recovery_path)
    if not ok then
        user_data.status = "Saved Favorites are waiting to be recovered: "
            .. tostring(err or "database unavailable")
        return 0
    end
    user_data.queue = remaining
    user_data.queue_head = 1
    user_data.queue_tail = #remaining
    user_data.queue_key_index = {}
    for _, entry in ipairs(remaining) do
        if entry.key then user_data.queue_key_index[entry.key] = entry end
    end
    user_data.saved = user_data.saved + #recovered
    user_data.status = #remaining > 0
        and "Recovering remaining user changes..." or "Favorites recovered"
    PersistCanonicalUserDataJournal()
    return #recovered
end

function QueueCanonicalUserDataSQL(sql, dedupe_key, defer_journal)
    if not sql or sql == "" or not FileExists(GetCanonicalDatabasePath()) then
        return false
    end
    local user_data = state.canonical_user_data
    user_data.queue_key_index = user_data.queue_key_index or {}
    if dedupe_key then
        local existing = user_data.queue_key_index[dedupe_key]
        if existing then
            existing.sql = sql
            if not defer_journal then
                if IsDurableReplaySafeFavoriteEntry(existing) then
                    AppendCanonicalFavoriteJournalEntry(existing)
                else
                    PersistCanonicalUserDataJournal()
                end
            end
            return true
        end
    end
    local entry = {
        sql = sql,
        key = dedupe_key,
        attempts = 0,
    }
    user_data.queue_tail = user_data.queue_tail or #user_data.queue
    user_data.queue_tail = user_data.queue_tail + 1
    user_data.queue[user_data.queue_tail] = entry
    if dedupe_key then user_data.queue_key_index[dedupe_key] = entry end
    if not defer_journal then
        if IsDurableReplaySafeFavoriteEntry(entry) then
            AppendCanonicalFavoriteJournalEntry(entry)
        else
            PersistCanonicalUserDataJournal()
        end
    end
    return true
end

-- Compatibility stub: previewing must never mutate library classification.
-- Classification changes only during an explicit scan or an explicit user
-- override, which keeps browsing, playback, and insertion deterministic.
function RefreshClassificationViews()
    -- The non-smart Favorites accordion still evaluates its visible tree
    -- locally. Drop cached classifications so file/folder override changes
    -- are reflected there immediately as well as in canonical SQL results.
    state.media_class_by_path = {}
    state.automatic_class_by_path = {}
    state.force_search_update = true
    state.canonical_browser.cache = {}
    state.canonical_browser.cache_order = {}
    ClearCanonicalTagCatalogCache()
    state.needs_visible_update = true
    if CanonicalBrowserFiltersActive and CanonicalBrowserFiltersActive()
        and RequestCanonicalBrowserPage then
        state.canonical_browser.offset = 0
        RequestCanonicalBrowserPage(
            CanonicalBrowserCurrentMode(),
            state.canonical_browser.current_folder_id, 0, false, false)
    end
end

function QueueClassificationOverride(
    scope_type, path, classification, defer_finalize)
    -- Folder/root choices are defaults. More-specific folder evidence and
    -- clear local file evidence remain exceptions inside that subtree; use a
    -- file-scope override when the user wants to force that file too.
    local allowed = {
        loop = true, ["one-shot"] = true,
        uncategorized = true,
    }
    if not allowed[classification] then return false end
    if scope_type ~= "file" and scope_type ~= "folder"
        and scope_type ~= "root" then return false end
    local normalized = NormalizeFavoritePath(path)
    if normalized == "" then return false end
    if scope_type == "file" and IsMidiFile(path) then return false end
    local stored_classification = classification == "uncategorized"
        and "other" or classification
    state.classification_overrides[scope_type .. "|" .. normalized] = classification
    local now = os.time()
    local sql = "INSERT INTO classification_overrides(scope_type,path_norm,"
        .. "classification,created_at,updated_at) VALUES("
        .. SQLQuote(scope_type) .. "," .. SQLQuote(normalized) .. ","
        .. SQLQuote(classification) .. "," .. tostring(now) .. ","
        .. tostring(now) .. ") ON CONFLICT(scope_type,path_norm) DO UPDATE SET "
        .. "classification=excluded.classification,updated_at=excluded.updated_at;\n"
    if scope_type == "file" then
        sql = sql .. "UPDATE files SET classification="
            .. SQLQuote(stored_classification) .. " WHERE canonical_path_norm="
            .. SQLQuote(normalized) .. " AND media_type='audio';\n"
    else
        sql = sql .. "UPDATE files SET classification="
            .. SQLQuote(stored_classification) .. " WHERE (canonical_path_norm="
            .. SQLQuote(normalized) .. " OR (substr(canonical_path_norm,1,"
            .. tostring(#normalized) .. ")=" .. SQLQuote(normalized)
            .. " AND substr(canonical_path_norm," .. tostring(#normalized + 1)
            .. ",1)='/')) AND media_type='audio'"
            .. " AND classification_source NOT IN('explicit filename',"
            .. "'explicit file BPM/bar structure','explicit BPM/bar structure',"
            .. "'BPM-labeled rhythmic FX','local terminal/FX structure',"
            .. "'local drum/instrument structure','musical fragment descriptor',"
            .. "'contextual bare-tempo structure','local instrument/ordinal structure',"
            .. "'conflicting filename category','direct category folder',"
            .. "'ancestor category folder');\n"
    end
    local queued = QueueCanonicalUserDataSQL(sql,
        "classification:" .. scope_type .. ":" .. normalized,
        defer_finalize)
    if not defer_finalize then RefreshClassificationViews() end
    return queued
end

function ClearClassificationOverride(
    scope_type, path, subtree, include_files, defer_finalize)
    if scope_type ~= "file" and scope_type ~= "folder"
        and scope_type ~= "root" then return false end
    local normalized = NormalizeFavoritePath(path)
    if normalized == "" then return false end
    -- On a root row, folder-and-subfolder clearing includes the root
    -- override and folder-scope overrides below it, but not file overrides.
    local clear_root_folder_scopes = subtree and not include_files
        and scope_type == "root"
    for key in pairs(state.classification_overrides or {}) do
        local key_scope, key_path = key:match("^(%a+)|(.+)$")
        local scope_matches = include_files
            or key_scope == scope_type
            or (clear_root_folder_scopes
                and (key_scope == "root" or key_scope == "folder"))
        local path_matches = key_path == normalized
            or (subtree and key_path
                and key_path:sub(1, #normalized + 1)
                    == normalized .. "/")
        if scope_matches and path_matches then
            state.classification_overrides[key] = nil
        end
    end
    local predicate = "path_norm=" .. SQLQuote(normalized)
    if subtree then
        predicate = "(path_norm=" .. SQLQuote(normalized)
            .. " OR (substr(path_norm,1," .. tostring(#normalized) .. ")="
            .. SQLQuote(normalized) .. " AND substr(path_norm,"
            .. tostring(#normalized + 1) .. ",1)='/'))"
    end
    local scope_sql
    if include_files then
        scope_sql = "scope_type IN('file','folder','root')"
    elseif clear_root_folder_scopes then
        scope_sql = "scope_type IN('root','folder')"
    else
        scope_sql = "scope_type=" .. SQLQuote(scope_type)
    end
    local affected = "(files.canonical_path_norm=" .. SQLQuote(normalized)
        .. (subtree and " OR (substr(files.canonical_path_norm,1,"
            .. tostring(#normalized) .. ")=" .. SQLQuote(normalized)
            .. " AND substr(files.canonical_path_norm," .. tostring(#normalized + 1)
            .. ",1)='/')" or "") .. ")"
    local effective = "CASE WHEN files.media_type='midi' THEN 'midi' ELSE COALESCE("
        .. "(SELECT CASE WHEN classification='uncategorized' THEN 'other' ELSE classification END "
        .. "FROM classification_overrides WHERE scope_type='file' AND path_norm=files.canonical_path_norm LIMIT 1),"
        .. "(SELECT CASE WHEN overrides.classification='uncategorized' THEN 'other' ELSE overrides.classification END "
        .. "FROM classification_overrides AS overrides WHERE overrides.scope_type='folder' AND "
        .. "(files.canonical_path_norm=overrides.path_norm OR (substr(files.canonical_path_norm,1,length(overrides.path_norm))=overrides.path_norm "
        .. "AND substr(files.canonical_path_norm,length(overrides.path_norm)+1,1)='/')) "
        .. "ORDER BY length(overrides.path_norm) DESC LIMIT 1),"
        .. "(SELECT CASE WHEN overrides.classification='uncategorized' THEN 'other' ELSE overrides.classification END "
        .. "FROM classification_overrides AS overrides WHERE overrides.scope_type='root' AND "
        .. "(files.canonical_path_norm=overrides.path_norm OR (substr(files.canonical_path_norm,1,length(overrides.path_norm))=overrides.path_norm "
        .. "AND substr(files.canonical_path_norm,length(overrides.path_norm)+1,1)='/')) LIMIT 1),"
        .. "files.automatic_classification) END"
    local sql = "DELETE FROM classification_overrides WHERE "
        .. scope_sql .. " AND " .. predicate .. ";\n"
        .. "UPDATE files SET classification=" .. effective
        .. " WHERE " .. affected .. ";\n"
    state.media_class_by_path[normalized] = nil
    local queued = QueueCanonicalUserDataSQL(sql,
        "classification_clear:" .. scope_type .. ":" .. normalized,
        defer_finalize)
    if not defer_finalize then RefreshClassificationViews() end
    return queued
end

function SetClassificationOverrides(paths, classification)
    local queued_any = false
    for _, path in ipairs(paths or {}) do
        if not IsMidiFile(path) then
            queued_any = QueueClassificationOverride(
                "file", path, classification, true) or queued_any
        end
    end
    if queued_any then
        PersistCanonicalUserDataJournal()
        RefreshClassificationViews()
        for _, path in ipairs(paths or {}) do
            if not IsMidiFile(path) then
                state.media_class_by_path[NormalizeFavoritePath(path)] =
                    classification == "uncategorized"
                        and "other" or classification
            end
        end
    end
    state.needs_visible_update = true
end

function GetManualKeyOverrideEntry(path)
    return state.key_overrides[
        NormalizeFavoritePath(path or "")]
end

function ResolveEffectiveKeyPitchClass(path, detected_pc)
    local entry = GetManualKeyOverrideEntry(path)
    if not entry then return detected_pc end
    if entry.key_pc == false then return nil end
    return tonumber(entry.key_pc)
end

function KeyPitchClassLabel(pc, unknown_label)
    pc = tonumber(pc)
    if pc and pc >= 0 and pc <= 11 then
        return PITCH_CLASS_NAMES and PITCH_CLASS_NAMES[pc + 1]
            or ({"C", "C#", "D", "D#", "E", "F",
                "F#", "G", "G#", "A", "A#", "B"})[pc + 1]
    end
    return unknown_label or "Unkeyed"
end

function RefreshKeyOverrideViews(path)
    state.key_override_generation =
        (state.key_override_generation or 0) + 1
    state.force_search_update = true
    state.needs_visible_update = true
    state.canonical_browser.cache = {}
    state.canonical_browser.cache_order = {}
    ClearCanonicalTagCatalogCache()

    local normalized = NormalizeFavoritePath(path or "")
    if normalized ~= ""
        and NormalizeFavoritePath(state.source_file or "") == normalized then
        local entry = GetManualKeyOverrideEntry(path)
        if state.media_kind == "audio" then
            local automatic = state.audio_detected_key_automatic_pc
            state.audio_detected_key_pc = ResolveEffectiveKeyPitchClass(
                path, automatic)
            if entry then
                state.audio_detection_method = entry.key_pc == false
                    and "manual unkeyed" or "manual override"
            else
                state.audio_detection_method =
                    state.audio_detection_automatic_method or "undetected"
            end
        elseif state.loaded_midi then
            state.loaded_midi.detected_key_pc =
                ResolveEffectiveKeyPitchClass(
                    path, state.loaded_midi.automatic_key_pc)
        end
        if ApplyPlaybackSettings then ApplyPlaybackSettings() end
    end

    if CanonicalBrowserFiltersActive and CanonicalBrowserFiltersActive()
        and RequestCanonicalBrowserPage then
        state.canonical_browser.offset = 0
        RequestCanonicalBrowserPage(
            CanonicalBrowserCurrentMode(),
            state.canonical_browser.current_folder_id, 0, false, false)
    end
end

function QueueKeyOverride(path, key_pc, defer_finalize)
    local normalized = NormalizeFavoritePath(path or "")
    if normalized == "" then return false end
    if key_pc ~= nil then
        key_pc = math.floor(tonumber(key_pc) or -1)
        if key_pc < 0 or key_pc > 11 then return false end
    end
    local existing = state.key_overrides[normalized]
    local detected = existing and existing.detected_key_pc
        or DetectFileKeyPitchClass(path, nil)
    state.key_overrides[normalized] = {
        key_pc = key_pc == nil and false or key_pc,
        detected_key_pc = detected == nil and false or detected,
    }
    local now = os.time()
    local key_sql = key_pc == nil and "NULL" or tostring(key_pc)
    local sql = "INSERT INTO key_overrides(path_norm,key_pc,detected_key_pc,"
        .. "created_at,updated_at) SELECT " .. SQLQuote(normalized) .. ","
        .. key_sql .. ",key_pc," .. tostring(now) .. "," .. tostring(now)
        .. " FROM files WHERE canonical_path_norm=" .. SQLQuote(normalized)
        .. " ON CONFLICT(path_norm) DO UPDATE SET key_pc=excluded.key_pc,"
        .. "updated_at=excluded.updated_at;\n"
        .. "UPDATE files SET key_pc=" .. key_sql
        .. " WHERE canonical_path_norm=" .. SQLQuote(normalized) .. ";\n"
    local queued = QueueCanonicalUserDataSQL(
        sql, "keys:" .. normalized, defer_finalize)
    if not defer_finalize then RefreshKeyOverrideViews(path) end
    return queued
end

function ClearKeyOverride(path, defer_finalize)
    local normalized = NormalizeFavoritePath(path or "")
    local existing = state.key_overrides[normalized]
    if normalized == "" or not existing then return false end
    state.key_overrides[normalized] = nil
    local detected_sql = existing.detected_key_pc == false
        and "NULL" or tostring(tonumber(existing.detected_key_pc) or "NULL")
    local sql = "UPDATE files SET key_pc=" .. detected_sql
        .. " WHERE canonical_path_norm=" .. SQLQuote(normalized) .. ";\n"
        .. "DELETE FROM key_overrides WHERE path_norm="
        .. SQLQuote(normalized) .. ";\n"
    local queued = QueueCanonicalUserDataSQL(
        sql, "keys:" .. normalized, defer_finalize)
    if not defer_finalize then RefreshKeyOverrideViews(path) end
    return queued
end

function SetKeyOverrides(paths, key_pc)
    local queued_any = false
    local refresh_path = nil
    for _, path in ipairs(paths or {}) do
        queued_any = QueueKeyOverride(path, key_pc, true) or queued_any
        if NormalizeFavoritePath(path)
            == NormalizeFavoritePath(state.source_file or "") then
            refresh_path = path
        end
    end
    if queued_any then
        PersistCanonicalUserDataJournal()
        RefreshKeyOverrideViews(refresh_path)
    end
end

HasPendingCanonicalTagWrites = function()
    local user_data = state.canonical_user_data
    local queue = user_data.queue or {}
    local queue_head = user_data.queue_head or 1
    local queue_tail = user_data.queue_tail or #queue
    for index = queue_head, queue_tail do
        local entry = queue[index]
        if not entry then goto continue end
        local prefix = tostring(entry.key or ""):sub(1, 5)
        if prefix == "tags:" or prefix == "keys:" then
            return true
        end
        ::continue::
    end
    return false
end

local function StartCanonicalUserDataWrite()
    local database = state.database
    local user_data = state.canonical_user_data
    local queue = user_data.queue or {}
    local queue_head = user_data.queue_head or 1
    local queue_count = CanonicalUserDataQueueCount(user_data)
    if database.write_active or queue_count == 0
        or not FileExists(GetCanonicalDatabasePath()) then
        return false
    end
    if not FlushCanonicalFavoriteJournal() then
        user_data.status = "User changes are waiting to be saved."
        return false
    end
    local count = math.min(50, queue_count)
    local batch = {}
    for index = 1, count do
        batch[index] = queue[queue_head]
        queue[queue_head] = nil
        queue_head = queue_head + 1
        local entry = batch[index]
        if entry and entry.key and user_data.queue_key_index[entry.key] == entry then
            user_data.queue_key_index[entry.key] = nil
        end
    end
    user_data.queue_head = queue_head
    -- Foreign keys must be enabled before the transaction begins. Enabling
    -- them from inside a queued entry is ignored by SQLite and previously
    -- allowed orphaned Favorites collection keys.
    local statements = {
        "PRAGMA foreign_keys=ON;\n",
        "BEGIN IMMEDIATE;\n",
    }
    for _, entry in ipairs(batch) do
        statements[#statements + 1] = entry.sql
        if entry.sql:sub(-1) ~= "\n" then
            statements[#statements + 1] = "\n"
        end
    end
    statements[#statements + 1] = "COMMIT;\n"
    user_data.inflight = batch
    local ok, err = StartDatabaseBatchAsync(
        table.concat(statements), count,
        "canonical_user_data", GetCanonicalDatabasePath())
    if not ok then
        local restore_head = user_data.queue_head or 1
        for index = #batch, 1, -1 do
            restore_head = restore_head - 1
            user_data.queue[restore_head] = batch[index]
            local entry = batch[index]
            if entry.key then
                user_data.queue_key_index[entry.key] = entry
            end
        end
        user_data.queue_head = restore_head
        user_data.inflight = {}
        PersistCanonicalUserDataJournal()
        user_data.status = "User changes are waiting to be saved."
        return false, err
    end
    user_data.status = "Saving user changes..."
    return true
end

local StartCanonicalScanImport

function ProcessMediaDatabase()
    local database = state.database
    if database.backend ~= "sqlite" then return end
    local browser = state.canonical_browser

    if database.worker_refresh_requested
        and not database.worker_active
        and not database.write_active then
        RequestDatabaseWorkerRefreshAfterLibraryCommit()
    end

    if database.worker_restart_pending then
        -- Wait for the old reader to release its database lock before
        -- starting a clean connection.  Requests made during this short
        -- handoff are retained by RequestCanonicalBrowserPage.
        local restart_elapsed = math.max(0, r.time_precise()
            - (database.worker_restart_requested_at or r.time_precise()))
        local worker_still_live = false
        if database.worker_ready_path
            and FileExists(database.worker_ready_path) then
            local ready = io.open(database.worker_ready_path, "rb")
            local heartbeat = ready and tonumber(
                (ready:read("*a") or ""):match("%d+")) or nil
            if ready then ready:close() end
            worker_still_live = heartbeat ~= nil
                and os.time() - heartbeat <= 5
            -- A malformed/half-written heartbeat gets a short grace period,
            -- but can no longer hold every library operation forever.
            if (worker_still_live and restart_elapsed < 10)
                or (not heartbeat and restart_elapsed < 2) then return end
        end
        if database.worker_ready_path then
            pcall(os.remove, database.worker_ready_path)
        end
        database.worker_restart_pending = false
        database.worker_restart_requested_at = 0
        if database.compact_requested then
            database.compact_requested = false
            StartCanonicalDatabaseCompactionNow()
            return
        end
        database.worker_prewarm_requested = true
        return
    end

    if database.worker_prewarm_requested
        and database.worker_started then
        -- Another request may have started the worker before the deferred
        -- prewarm was serviced. The request has already been fulfilled.
        database.worker_prewarm_requested = false
    end

    if database.worker_prewarm_requested
        and not database.worker_started
        and not database.worker_active then
        database.worker_prewarm_requested = false
        EnsureDatabaseWorkerStarted(GetCanonicalDatabasePath())
    end

    if not database.write_active then
        local sync = state.canonical_scan_sync
        if sync.validated and sync.apply_requested and not sync.importing
            and not database.scan_active and StartCanonicalScanImport then
            StartCanonicalScanImport()
        elseif StartPendingCanonicalFavoriteMutationLookup() then
        elseif browser.deferred_request
            and not (HasPendingCanonicalTagWrites()
                and (browser.deferred_request.mode == "browser_filter"
                    or browser.deferred_request.mode == "browser_search"
                    or browser.deferred_request.mode == "browser_random"))
            and not state.canonical_paging.active then
            -- Foreground navigation owns the next free read lane. Favorites
            -- writes are durable queue entries and can safely wait one page;
            -- making them first repeatedly left an opened folder with no
            -- content until the user clicked it again.
            local deferred = browser.deferred_request
            browser.deferred_request = nil
            local started = RequestCanonicalBrowserPage(
                deferred.mode, deferred.folder_id, deferred.offset,
                deferred.append, false, deferred.accordion_target)
            if not started then browser.deferred_request = deferred end
        else
            StartCanonicalUserDataWrite()
        end
    end

    if not database.write_active
        and not state.canonical_paging.active
        and state.media_tag_bar.open
        and browser.pending_tag_folder_id ~= nil
        and (not browser.pending_tag_time
            or r.time_precise() >= browser.pending_tag_time)
        -- Folder tag counts are rebuilt as part of the canonical scan
        -- commit. Do not start a tag-catalog read against the old counts or
        -- compete with the import; the pending folder ID will be picked up
        -- on the next pass once the commit is complete.
        and not state.library_scan.scanning
        and not state.canonical_scan_sync.importing
        and not HasPendingCanonicalTagWrites()
        then
        local pending_scope = browser.pending_tag_folder_id
        local folder_id = pending_scope == false and nil or pending_scope
        browser.pending_tag_folder_id = nil
        browser.pending_tag_time = nil
        state.canonical_paging.tag_requested_at = r.time_precise()
        RequestCanonicalBrowserPage(
            "tag_catalog", folder_id, 0, false, true)
    end

    -- Favorite-heart hydration is deliberately last in the read priority
    -- order. Its 250 ms quiet period lets successive first-time folder opens
    -- run back-to-back without waiting behind a cold membership probe.
    if not database.write_active
        and not state.canonical_paging.active
        and not browser.deferred_request
        and StartPendingCanonicalFavoriteMembershipQuery then
        StartPendingCanonicalFavoriteMembershipQuery()
    end

    if database.write_active then
        local pending_count = database.write_pending_count or 0
        local pending_kind = database.write_pending_kind
        local finished, finish_error, finish_output = PollDatabaseBatchAsync()
        if finished == nil then return end
        if not finished then
            if pending_kind == "canonical_tag_editor" then
                local editor = state.tag_editor
                editor.loading = false
                editor.loading_request_started = false
                if not editor.loading_cancelled then
                    editor.loading_error = tostring(
                        finish_error or "Unable to load tags.")
                end
                editor.loading_cancelled = false
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                return
            elseif pending_kind == "canonical_favorite_mutation" then
                RequeueCanonicalFavoriteMutations()
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                return
            elseif pending_kind == "canonical_membership" then
                for key in pairs(
                    state.favorite_membership_inflight_paths or {}) do
                    state.favorite_membership_pending_paths[key] = true
                end
                state.favorite_membership_inflight_paths = {}
                state.favorite_membership_next_at = r.time_precise() + 0.25
                state.favorite_membership_query_pending = false
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                local deferred = state.canonical_browser.deferred_request
                state.canonical_browser.deferred_request = nil
                if deferred then
                    RequestCanonicalBrowserPage(
                        deferred.mode, deferred.folder_id, deferred.offset,
                        deferred.append, false, deferred.accordion_target)
                end
                return
            elseif pending_kind == "canonical_scan_sync" then
                local sync = state.canonical_scan_sync
                local newly_added_root = sync.newly_added_root
                sync.importing = false
                sync.apply_requested = false
                sync.ready = false
                sync.validated = false
                sync.newly_added_root = nil
                sync.scanned_root_keys = {}
                sync.scanned_folder_keys = {}
                sync.favorite_file_candidates = {}
                sync.scanned_favorite_file_keys = {}
                sync.progress_path = nil
                if sync.manifest_path then
                    pcall(os.remove, sync.manifest_path)
                    sync.manifest_path = nil
                end
                sync.status =
                    "Scan changes could not be applied; current database unchanged."
                sync.error = tostring(finish_error)
                state.library_scan.scanning = false
                state.library_scan.phase = nil
                state.library_scan.browser_blocked = false
                state.library_scan.operation_kind = nil
                state.library_scan.queue = {}
                state.library_scan.roots = {}
                state.library_scan.current = nil
                state.library_scan.retain_file_nodes = nil
                -- The scan tree may already have been published progressively.
                -- Re-read the authoritative roots so a failed import cannot
                -- leave Lua showing folders that SQLite rejected.
                state.folder_tree = {}
                state.open_folders = {}
                state.canonical_browser.cache = {}
                state.canonical_browser.cache_order = {}
                ClearCanonicalTagCatalogCache()
                state.canonical_browser.pending_prefetch = nil
                state.canonical_browser.pending_tag_folder_id = nil
                state.canonical_browser.pending_tag_time = nil
                state.canonical_browser.deferred_request = nil
                state.canonical_browser.error = nil
                state.canonical_browser.accordion_error = nil
                state.canonical_browser.status =
                    "Scan import failed; showing the last saved library."
                state.canonical_browser.current_folder_id = nil
                state.canonical_browser.current_path = nil
                state.canonical_browser.current_name = "Library"
                state.canonical_browser.rows = {}
                state.canonical_browser.offset = 0
                state.selected_folder_scope = nil
                state.force_search_update = true
                state.needs_visible_update = true
                if newly_added_root
                    and RemoveConfiguredRootValue(newly_added_root) then
                    SaveSettings()
                end
                local facet_ready = QueryDatabaseScalarAtPath(
                    GetCanonicalDatabasePath(),
                    "SELECT COALESCE(MAX(CASE WHEN key='folder_tag_counts_ready' "
                        .. "THEN value END),'0') FROM app_meta;")
                database.folder_tag_counts_ready = tostring(facet_ready or "") == "1"
                LoadCanonicalAccordionRoots()
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                return
            elseif pending_kind == "canonical_user_data" then
                local user_data = state.canonical_user_data
                local root_removal_failed = false
                for index = #user_data.inflight, 1, -1 do
                    local entry = user_data.inflight[index]
                    entry.attempts = (entry.attempts or 0) + 1
                    if entry.attempts < 3 then
                        local restore_head = user_data.queue_head or 1
                        restore_head = restore_head - 1
                        user_data.queue[restore_head] = entry
                        user_data.queue_head = restore_head
                        if entry.key then
                            user_data.queue_key_index[entry.key] = entry
                        end
                    else
                        user_data.failed = user_data.failed + 1
                        if entry.key
                            and entry.key:sub(1, 12) == "remove_root:" then
                            root_removal_failed = true
                        end
                    end
                end
                user_data.inflight = {}
                PersistCanonicalUserDataJournal()
                user_data.status = user_data.failed > 0
                    and "Some user changes could not be saved."
                    or "User changes will be retried."
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                if root_removal_failed
                    and state.library_scan.operation_kind == "remove" then
                    EndBlockingLibraryOperation(
                        "Root was removed from Settings, but database cleanup failed.",
                        finish_error)
                end
                return
            elseif pending_kind == "canonical_compact" then
                database.compact_requested = false
                EndBlockingLibraryOperation(
                    "Database compaction failed; existing data was kept.",
                    finish_error)
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                return
            elseif pending_kind == "canonical_page" then
                local paging = state.canonical_paging
                local request = paging.browser_request or {}
                if database.worker_cancelled then
                    -- A newer foreground browser action interrupted an obsolete
                    -- page or facet. Drop it quietly and give the queued action
                    -- the worker lane immediately.
                    paging.active = false
                    paging.browser_request = nil
                    database.worker_cancelled = false
                    database.worker_cancel_requested = false
                    database.write_pending_count = 0
                    database.write_pending_kind = nil
                    database.write_target_path = nil
                    if type(request.accordion_target) == "table" then
                        request.accordion_target._canonical_loading = false
                        request.accordion_target._canonical_started = false
                    end
                    local deferred = state.canonical_browser.deferred_request
                    state.canonical_browser.deferred_request = nil
                    if deferred then
                        RequestCanonicalBrowserPage(
                            deferred.mode, deferred.folder_id,
                            deferred.offset, deferred.append, false,
                            deferred.accordion_target)
                    end
                    return
                end
                paging.active = false
                if paging.consumer == "browser"
                    and not (request and request.mode == "tag_catalog") then
                    if request.accordion_target == "__roots__" then
                        state.canonical_browser.accordion_loading = false
                    elseif type(request.accordion_target) == "table" then
                        request.accordion_target._canonical_loading = false
                        if request.mode == "resolve_favorite_folder" then
                            request.accordion_target._canonical_resolution_pending = false
                            request.accordion_target._canonical_resolution_error =
                                tostring(finish_error)
                        end
                    end
                    state.canonical_browser.loading = false
                    state.canonical_browser.status =
                        "Database page could not be loaded."
                    state.canonical_browser.accordion_error =
                        tostring(finish_error)
                    -- An accordion child-page failure must not invalidate a
                    -- previously valid search/Favorites result page. Keep the
                    -- global page error reserved for the main result surface.
                    if not request.accordion_target
                        or request.accordion_target == "__roots__" then
                        state.canonical_browser.error = tostring(finish_error)
                    end
                elseif paging.consumer == "browser"
                    and request and request.mode == "tag_catalog" then
                    -- A background tag catalog is optional. It must never
                    -- replace a valid Favorites/search page with a global
                    -- "page could not be loaded" error.
                    state.canonical_browser.accordion_error =
                        tostring(finish_error)
                else
                    paging.status =
                        "Paged browsing test failed; current library unchanged."
                    paging.error = tostring(finish_error)
                end
                local browser = state.canonical_browser
                local retry_key = tostring(request.mode or "") .. ":"
                    .. tostring(request.folder_id or 0) .. ":"
                    .. tostring(request.offset or 0) .. ":"
                    .. tostring(request.accordion_target or "")
                local retryable = request.mode == "tag_catalog"
                    or request.mode == "browser_filter"
                    or request.mode == "browser_search"
                    or request.mode == "folder"
                    or request.mode == "roots"
                if retryable and browser.page_retry_key ~= retry_key then
                    -- A scan commit can briefly race the persistent reader
                    -- while SQLite refreshes its schema/cache. Retry once;
                    -- never spin forever on a genuinely invalid query.
                    browser.page_retry_key = retry_key
                    if request.mode == "tag_catalog" then
                        browser.pending_tag_folder_id = request.folder_id or false
                        browser.pending_tag_time = r.time_precise() + 0.15
                    else
                        browser.deferred_request = {
                            mode = request.mode,
                            folder_id = request.folder_id,
                            offset = request.offset or 0,
                            append = request.append == true,
                            accordion_target = request.accordion_target,
                        }
                    end
                    browser.error = nil
                    browser.status = "Retrying the current library request..."
                else
                    browser.page_retry_key = nil
                end
                database.write_pending_count = 0
                database.write_pending_kind = nil
                database.write_target_path = nil
                return
            end
            DisableMediaDatabase(finish_error)
            return
        end

        database.write_pending_count = 0
        database.write_pending_kind = nil
        if pending_kind == "canonical_tag_editor" then
            local editor = state.tag_editor
            editor.loading = false
            editor.loading_request_started = false
            if not editor.loading_cancelled then
                ApplyLoadedMediaTagEditorData(editor,
                    ParseCanonicalTagEditorData(
                        editor.paths, finish_output))
            end
            editor.loading_cancelled = false
        elseif pending_kind == "canonical_favorite_mutation" then
            ApplyCanonicalFavoriteMutationLookup(finish_output)
        elseif pending_kind == "canonical_scan_sync" then
            local sync = state.canonical_scan_sync
            local metrics = state.library_scan.scan_metrics or {}
            metrics.commit_seconds = math.max(0, r.time_precise()
                - (metrics.commit_started_at or r.time_precise()))
            metrics.sql_ms = tonumber(database.worker_last_sql_ms) or 0
            metrics.total_seconds = math.max(0, r.time_precise()
                - (metrics.started_at or r.time_precise()))
            local metric_text = string.format(
                "mode=%s;files=%d;discovery=%.3f;ingest=%.3f;prepare=%.3f;commit=%.3f;sql_ms=%d;total=%.3f",
                tostring(metrics.mode or "unknown"),
                tonumber(state.canonical_scan_sync.files) or 0,
                tonumber(metrics.discovery_seconds) or 0,
                tonumber(metrics.ingest_seconds) or 0,
                tonumber(metrics.prepare_seconds) or 0,
                tonumber(metrics.commit_seconds) or 0,
                tonumber(metrics.sql_ms) or 0,
                tonumber(metrics.total_seconds) or 0)
            r.SetExtState(EXT_SECTION, "last_scan_profile", metric_text, true)
            -- Classification evidence may have changed during the import;
            -- never let pre-scan Lua cache entries mask the new inheritance.
            state.media_class_by_path = {}
            state.automatic_class_by_path = {}
            -- Removed files also retire their sparse key decisions. Reloading
            -- this normally tiny table keeps the in-memory override resolver
            -- identical to the committed database without a library rescan.
            LoadKeyOverrides()
            state.key_override_generation =
                (state.key_override_generation or 0) + 1
            sync.importing = false
            sync.newly_added_root = nil
            sync.validated = false
            sync.apply_requested = false
            sync.ready = false
            sync.error = nil
            local pruned_favorites = select(1,
                PruneMissingFavoritesAfterScan())
            sync.scanned_root_keys = {}
            sync.scanned_folder_keys = {}
            sync.favorite_file_candidates = {}
            sync.scanned_favorite_file_keys = {}
            sync.progress_path = nil
            local folders, files, active_locations, added, removed,
                library_file_count =
                tostring(finish_output or ""):match(
                    "SYNC[\t|](%d+)[\t|](%d+)[\t|](%d+)"
                        .. "[\t|](%d+)[\t|](%d+)[\t|](%d+)")
            database.library_file_count =
                tonumber(library_file_count) or database.library_file_count
            sync.status = folders and string.format(
                "Update complete: %d added, %d removed (%d files total)",
                tonumber(added) or 0, tonumber(removed) or 0,
                tonumber(active_locations) or tonumber(files) or 0)
                or "Library update committed."
            if pruned_favorites > 0 then
                sync.status = sync.status .. string.format(
                    "; %d missing favorite%s removed",
                    pruned_favorites,
                    pruned_favorites == 1 and "" or "s")
            end
            database.folder_tag_counts_ready = true
            database.file_search_ready = true
            if sync.manifest_path then pcall(os.remove, sync.manifest_path) end
            sync.manifest_path = nil
            state.canonical_browser.cache = {}
            state.canonical_browser.cache_order = {}
            ClearCanonicalTagCatalogCache()
            ResetCanonicalNavigationAfterLibraryChange()
            -- A completed commit starts a new database generation. Slow-query
            -- suppression from the previous generation must not discard the
            -- new root's one-time folder warmup.
            state.canonical_browser.optional_reads_suppressed_until = 0
            RequestDatabaseWorkerRefreshAfterLibraryCommit()
            local browser = state.canonical_browser
            -- Keep a foreground request queued while the refreshed root page
            -- is being installed. ApplyCanonicalAccordionPage resolves its
            -- target by path, so the request can safely attach to the new
            -- Library node instead of being lost during the scan handoff.
            browser.accordion_error = nil
            browser.offset = 0
            browser.selected_path = nil
            BuildFavoriteTree(true, true)
            sync.metadata_root = nil
            -- Metadata analysis is separate from folder synchronization. A
            -- normal add or update must finish here and remain immediately usable.
            if state.favorite_smart_mode
                or browser.discovery_active
                or CanonicalBrowserFiltersActive() then
                RequestCanonicalBrowserPage(
                    CanonicalBrowserCurrentMode(),
                    browser.current_folder_id, 0, false, false)
            else
                LoadCanonicalAccordionRoots()
            end
            local scan = state.library_scan
            scan.phase = "finalize_db"
            scan.phase_started_at = r.time_precise()
            scan.phase_label = "Finalizing browser"
            scan.phase_done = 0
            scan.phase_total = 1
            scan.phase_detail = "Refreshing database worker and navigation"
        elseif pending_kind == "canonical_user_data" then
            local user_data = state.canonical_user_data
            local roots_changed = false
            local favorites_changed = false
            local broad_cache_change = false
            for _, entry in ipairs(user_data.inflight or {}) do
                if entry.key and entry.key:sub(1, 16) == "favorites_batch:"
                    or (entry.key and entry.key:sub(1, 9) == "favorite:")
                    or (entry.key and entry.key:sub(1, 15)
                        == "favorite_entry:") then
                    favorites_changed = true
                elseif entry.key
                    and entry.key:sub(1, 12) == "remove_root:" then
                    roots_changed = true
                    broad_cache_change = true
                else
                    broad_cache_change = true
                end
            end
            user_data.saved = user_data.saved + #user_data.inflight
            user_data.inflight = {}
            -- Favorite journal entries are append-only while writes are
            -- draining. Compact the journal once the queue is empty instead
            -- of rewriting an ever-growing pending queue every batch.
            if CanonicalUserDataQueueCount(user_data) == 0 then
                user_data.queue = {}
                user_data.queue_head = 1
                user_data.queue_tail = 0
                PersistCanonicalUserDataJournal()
            end
            user_data.status = CanonicalUserDataQueueCount(user_data) > 0
                and "Saving user changes..." or "User changes saved"
            if broad_cache_change then
                state.canonical_browser.cache = {}
                state.canonical_browser.cache_order = {}
                ClearCanonicalTagCatalogCache()
            elseif favorites_changed then
                InvalidateCanonicalFavoriteViews()
            end
            if roots_changed then
                database.status =
                    "Root removed; database records cleaned. Compact Database to reclaim file space."
                state.canonical_browser.rows = {}
                state.canonical_browser.selected_path = nil
                state.open_folders = {}
                RequestDatabaseWorkerRefreshAfterLibraryCommit()
                LoadCanonicalAccordionRoots()
                if state.library_scan.operation_kind == "remove" then
                    local scan = state.library_scan
                    scan.phase = "finalize_db"
                    scan.phase_started_at = r.time_precise()
                    scan.phase_label = "Finalizing folder removal"
                    scan.phase_detail =
                        "Refreshing database worker and navigation"
                    scan.phase_done = 0
                    scan.phase_total = 1
                end
            elseif state.favorite_smart_mode then
                local browser = state.canonical_browser
                browser.offset = 0
                browser.selected_path = nil
                RequestCanonicalBrowserPage(
                    CanonicalBrowserCurrentMode(),
                    browser.current_folder_id, 0, false, false)
            elseif favorites_changed and state.favorites_mode then
                local browser = state.canonical_browser
                browser.available_tags = {}
            end
        elseif pending_kind == "canonical_compact" then
            database.status = "Database compacted; unused file space reclaimed."
            database.error = nil
            RequestDatabaseWorkerRefreshAfterLibraryCommit()
            local scan = state.library_scan
            if scan.operation_kind == "compact" then
                scan.phase = "finalize_db"
                scan.phase_started_at = r.time_precise()
                scan.phase_label = "Finalizing database maintenance"
                scan.phase_detail = "Restarting database worker"
                scan.phase_done = 0
                scan.phase_total = 1
            end
        elseif pending_kind == "batch" then
            database.queue_head =
                math.min(#database.queue + 1,
                    (database.queue_head or 1) + pending_count)
            if database.queue_head > 4096
                and database.queue_head > (#database.queue * 0.5) then
                local compacted = {}
                for index = database.queue_head, #database.queue do
                    compacted[#compacted + 1] = database.queue[index]
                end
                database.queue = compacted
                database.queue_head = 1
            end
            database.indexed_count = database.indexed_count + pending_count
            database.batch_count = database.batch_count + 1
            database.status = "Database update: "
                .. tostring(database.indexed_count) .. " files saved"
        elseif pending_kind == "finalize" then
            database.scan_active = false
            database.finalize_pending = false
            database.status = "Database up to date: "
                .. tostring(database.indexed_count) .. " files"
        elseif pending_kind == "canonical_membership" then
            for line in tostring(finish_output or ""):gmatch(
                "[^\r\n]+") do
                local key, value = line:match("^([^\t]+)\t([01])$")
                if key then
                    state.favorite_membership_cache[key] = value == "1"
                end
            end
            state.favorite_membership_query_pending = false
            state.favorite_membership_inflight_paths = {}
            state.favorite_membership_next_at = r.time_precise() + 0.10
            state.media_favorite_generation =
                (state.media_favorite_generation or 0) + 1
            database.write_pending_count = 0
            database.write_pending_kind = nil
            database.write_target_path = nil
            local deferred = state.canonical_browser.deferred_request
            state.canonical_browser.deferred_request = nil
            if deferred then
                RequestCanonicalBrowserPage(
                    deferred.mode, deferred.folder_id, deferred.offset,
                    deferred.append, false, deferred.accordion_target)
            end
        elseif pending_kind == "canonical_page" then
            local paging = state.canonical_paging
            paging.elapsed_ms = math.floor(
                math.max(0, r.time_precise() - (paging.started_at or 0))
                    * 1000 + 0.5)
            local request = paging.browser_request or {}
            local result_limit = request.mode == "browser_random"
                and 1000 or (request.page_size
                    or paging.page_size or 100)
            local rows, has_more, total_count = ParseCanonicalPageRows(
                finish_output, result_limit)
            local browser = state.canonical_browser
            if request.view_generation ~= (browser.view_generation or 0) then
                -- Home/Back may leave a smart result while its SQL is still
                -- running. The completed page is obsolete and must not reopen
                -- that view after navigation has already returned home.
                request.prefetch = true
                request.cacheable = false
                request.stale = true
            elseif browser.deferred_request
                and (request.mode == "browser_search"
                    or request.mode == "browser_filter"
                    or request.mode == "browser_random"
                    or request.mode == "smart_favorites"
                    or request.mode == "smart_recent"
                    or request.mode == "smart_used"
                    or request.mode == "smart_collection") then
                -- A newer foreground action is already queued. Do not let
                -- the older result replace the visible page or schedule a
                -- prefetch before the newer request gets the lane.
                request.prefetch = true
                request.cacheable = false
                request.stale = true
            end
            SuppressSlowCanonicalOptionalReads(paging.elapsed_ms, request)
            state.canonical_browser.page_retry_key = nil
            paging.last_row_count = #rows
            paging.last_target_path = type(request.accordion_target) == "table"
                and request.accordion_target.path
                or tostring(request.accordion_target or request.mode or "")
            if paging.consumer == "browser" then
                if request.mode == "resolve_favorite_folder" then
                    local target = request.accordion_target
                    paging.browser_request = nil
                    paging.active = false
                    if type(target) == "table" then
                        target._canonical_loading = false
                        target._canonical_resolution_pending = false
                        local match = rows[1]
                        local folder_id = match
                            and tonumber(match.folder_id or match.id) or nil
                        if folder_id then
                            target._canonical_folder_id = folder_id
                            target._canonical_resolution_error = nil
                            state.favorite_folder_id_cache =
                                state.favorite_folder_id_cache or {}
                            state.favorite_folder_id_cache[
                                NormalizeFavoritePath(target.path)] = folder_id
                            state.canonical_browser.accordion_error = nil
                            -- The user may have left Media Favorites while
                            -- the worker lookup was in flight. Cache the ID,
                            -- but only mutate/open the Favorites tree while
                            -- that surface is still active.
                            local browser = state.canonical_browser
                            local is_current_selection = state.favorites_mode
                                and state.cursor_type == "folder"
                                and state.cursor_path == target.path
                            if is_current_selection then
                                -- Selection happened before the asynchronous
                                -- folder-ID lookup completed. Complete the
                                -- browser scope handoff now; without this the
                                -- folder looks selected but tag_catalog never
                                -- receives its physical folder ID.
                                browser.current_folder_id = folder_id
                                browser.current_name = target.name
                                browser.current_path = target.path
                                browser.collection_scope_key = nil
                                state.selected_folder_scope = target.path
                                browser.available_tags = {}
                            end
                            if state.favorites_mode then
                                OpenFolderAccordion(target)
                            end
                        else
                            target._canonical_resolution_error =
                                "Favorite folder is no longer in the library."
                            if state.favorites_mode then
                                state.canonical_browser.accordion_error =
                                    target._canonical_resolution_error
                            end
                            state.needs_visible_update = true
                        end
                    end
                    return
                end
                if request.mode == "tag_catalog" then
                    local browser = state.canonical_browser
                    local current_tag_key = CanonicalBrowserCacheKey(
                        "tag_catalog", browser.current_folder_id, 0)
                    local catalog = {}
                    local catalog_names = {}
                    for _, row in ipairs(rows) do
                        local normalized_name = NormalizeTag(row.name)
                        catalog[#catalog + 1] = {
                            name = normalized_name,
                            count = tonumber(row.path) or 0,
                        }
                        catalog_names[normalized_name] = true
                    end
                    -- A selected chip is also the escape hatch for removing
                    -- that refinement. Never let an empty or thresholded
                    -- co-occurrence result make the active choice disappear.
                    for selected_name, enabled in pairs(
                        browser.selected_tags or {}) do
                        selected_name = NormalizeTag(selected_name)
                        if enabled and selected_name ~= ""
                            and not catalog_names[selected_name] then
                            catalog[#catalog + 1] = {
                                name = selected_name,
                                count = 0,
                            }
                            catalog_names[selected_name] = true
                        end
                    end
                    if not request.stale
                        and request.cache_key == current_tag_key then
                        SortMediaTagCatalog(catalog, browser.selected_tags)
                        PutCanonicalTagCatalogCache(request.cache_key, catalog)
                        if not request.filtered_tag_catalog then
                            browser.tag_cardinality_hints =
                                browser.tag_cardinality_hints or {}
                            local scope_prefix =
                                tostring(request.folder_id or 0) .. "\31"
                            for _, tag in ipairs(catalog) do
                                local name = NormalizeTag(tag.name)
                                if name ~= "" then
                                    browser.tag_cardinality_hints[
                                        scope_prefix .. name] =
                                        tonumber(tag.count) or 0
                                end
                            end
                        end
                        browser.available_tags = catalog
                        browser.tag_catalog_refreshing = false
                        browser.tag_catalog_refresh_started_at = nil
                    else
                        -- A filter can change while an older catalog is in
                        -- flight without changing the foreground navigation
                        -- generation. Do not cache or display those rows under
                        -- either filter identity: explicitly request the
                        -- current scope. This closes the gap where the old
                        -- result failed the key check but no replacement was
                        -- left queued.
                        browser.pending_tag_folder_id =
                            browser.current_folder_id or false
                        browser.pending_tag_time = 0
                        browser.tag_catalog_refreshing = true
                        browser.tag_catalog_refresh_started_at =
                            browser.tag_catalog_refresh_started_at
                            or r.time_precise()
                    end
                    paging.browser_request = nil
                    paging.active = false
                    local deferred = browser.deferred_request
                    browser.deferred_request = nil
                    if deferred and not state.database.write_active then
                        browser.pending_prefetch = nil
                        RequestCanonicalBrowserPage(
                            deferred.mode, deferred.folder_id,
                            deferred.offset, deferred.append, false,
                            deferred.accordion_target)
                        return
                    end
                    local pending_prefetch = browser.pending_prefetch
                    browser.pending_prefetch = nil
                    if pending_prefetch
                        and not state.database.write_active then
                        RequestCanonicalBrowserPage(
                            pending_prefetch.mode,
                            pending_prefetch.folder_id,
                            pending_prefetch.offset,
                            false, true)
                    end
                    return
                end
                local page = {
                    rows = rows,
                    has_more = has_more,
                    elapsed_ms = paging.elapsed_ms,
                    total_count = total_count,
                    next_cursor = BuildCanonicalPageCursor(rows),
                    offset = math.max(0,
                        math.floor(tonumber(request.offset) or 0)),
                }
                if request.mode == "favorite_scope_count" then
                    paging.browser_request = nil
                    paging.active = false
                    local root_scope_still_active = not request.stale
                        and state.favorites_mode
                        and browser.current_folder_id == nil
                        and browser.collection_scope_key == nil
                        and browser.smart_mode == nil
                        and browser.deferred_request == nil
                    if root_scope_still_active then
                        RequestCanonicalBrowserPage(
                            "browser_random", nil, 0, false, false)
                    else
                        browser.loading = false
                        local deferred = browser.deferred_request
                        if deferred and not state.database.write_active then
                            browser.deferred_request = nil
                            RequestCanonicalBrowserPage(
                                deferred.mode, deferred.folder_id,
                                deferred.offset, deferred.append, false,
                                deferred.accordion_target)
                        end
                    end
                    return
                end
                if request.cacheable ~= false then
                    PutCanonicalBrowserCache(
                        request.cache_key or CanonicalBrowserCacheKey(
                            request.mode, request.folder_id, request.offset),
                        rows, has_more, paging.elapsed_ms,
                        request.prefetch, total_count, page.next_cursor,
                        request.offset)
                end
                paging.browser_request = nil
                paging.active = false
                if request.stale then
                    browser.loading = false
                    if type(request.accordion_target) == "table" then
                        request.accordion_target._canonical_loading = false
                        request.accordion_target._canonical_started = false
                    end
                elseif request.accordion_target then
                    ApplyCanonicalBrowserPage(
                        page, request.append, request.accordion_target)
                    if request.accordion_target == "__roots__"
                        and has_more then
                        RequestCanonicalBrowserPage(
                            request.mode, request.folder_id,
                            (request.offset or 0)
                                + (request.page_size
                                    or paging.page_size or 100),
                            true, false, request.accordion_target)
                    elseif request.accordion_target ~= "__roots__"
                        and not (type(request.accordion_target) == "table"
                            and (request.accordion_target.is_collection
                                or request.accordion_target.is_favorite_root_files))
                        and not request.append
                        and (not state.favorites_mode
                            or browser.current_folder_id == request.folder_id) then
                        state.canonical_browser.pending_tag_folder_id =
                            request.folder_id or false
                        state.canonical_browser.pending_tag_time =
                            r.time_precise() + 0.4
                    end
                elseif request.mode == "browser_random" then
                    local browser = state.canonical_browser
                    if not request.random_wrapped and #rows < 256 then
                        -- The indexed random-key walk may begin near the end of
                        -- the eligible range. Wrap once and merge the prefix so
                        -- small result sets are shuffled whole instead of being
                        -- replaced by only the tail after the random pivot.
                        browser.random_wrap_rows = rows
                        browser.random_force_start = true
                        RequestCanonicalBrowserPage(
                            "browser_random", request.folder_id,
                            0, false, false)
                        return
                    elseif request.random_wrapped
                        and browser.random_wrap_rows then
                        local merged, seen = {}, {}
                        for _, row in ipairs(browser.random_wrap_rows) do
                            local key = tonumber(row.id) or row.path
                            if not seen[key] then
                                seen[key] = true
                                merged[#merged + 1] = row
                            end
                        end
                        for _, row in ipairs(rows) do
                            if #merged >= 256 then break end
                            local key = tonumber(row.id) or row.path
                            if not seen[key] then
                                seen[key] = true
                                merged[#merged + 1] = row
                            end
                        end
                        rows = merged
                        browser.random_wrap_rows = nil
                    end
                    local cursor_row = rows[#rows]
                    if cursor_row and cursor_row.random_key ~= nil then
                        browser.random_cursor_key = cursor_row.random_key
                        browser.random_cursor_id = cursor_row.id
                    end
                    ShuffleCanonicalFileRows(rows, 1)
                    local picked = rows[1]
                    browser.random_pool = {}
                    for index = 2, #rows do
                        browser.random_pool[#browser.random_pool + 1] = rows[index]
                    end
                    browser.loading = false
                    browser.discovery_active = true
                    browser.clipper = nil
                    browser.rows = rows
                    -- Random owns a self-contained candidate window. Do not
                    -- inherit paging offsets from the Library/Favorites view
                    -- it replaced, or the generic "Load earlier results"
                    -- control will appear and navigate to the root page.
                    browser.window_start_offset = 0
                    browser.rows_trimmed = false
                    browser.has_more = false
                    browser.loaded_file_count = CountCanonicalPageFiles(rows)
                    browser.loaded_file_last_page_offset = nil
                    browser.offset = 0
                    browser.last_ms = paging.elapsed_ms
                    if picked then
                        browser.selected_path = picked.path
                        browser.random_result = picked
                        local node = picked._main_node or {
                            path = picked.path,
                            name = picked.name,
                            is_folder = false,
                        }
                        picked._main_node = node
                        SetCursorToFileNode(node, true)
                        browser.status = string.format(
                            "%d lucky matches - %d ms",
                            #rows, paging.elapsed_ms)
                    else
                        browser.status = "No files match the selected filters."
                    end
                elseif not request.prefetch then
                    if request.mode == "browser_filter" then
                    end
                    ApplyCanonicalBrowserPage(page, request.append)
                    -- Unfiltered catalogs use stable scan-time read models;
                    -- filtered pages schedule a bounded co-occurrence catalog
                    -- so incompatible tag chips disappear without blocking the
                    -- foreground result page.
                    local next_offset =
                        (request.offset or 0) + (paging.page_size or 100)
                    if has_more then
                        state.canonical_browser.pending_prefetch = {
                            mode = request.mode,
                            folder_id = request.folder_id,
                            offset = next_offset,
                        }
                    else
                        state.canonical_browser.pending_prefetch = nil
                    end
                    if (not state.favorites_mode
                        or CanonicalFavoriteFacetScopeActive())
                        and (request.mode == "roots"
                        or request.mode == "folder"
                        or request.mode == "browser_search"
                        or request.mode == "browser_filter"
                        or request.mode == "smart_favorites"
                        or request.mode == "smart_recent"
                        or request.mode == "smart_used"
                        or request.mode == "smart_collection") then
                        RequestCanonicalBrowserPage(
                            "tag_catalog", request.folder_id,
                            0, false, true)
                    end
                end
                local deferred = state.canonical_browser.deferred_request
                if deferred and not state.database.write_active then
                    state.canonical_browser.deferred_request = nil
                    RequestCanonicalBrowserPage(
                        deferred.mode, deferred.folder_id, deferred.offset,
                        deferred.append, false,
                        deferred.accordion_target)
                elseif browser.pending_prefetch
                    and not state.database.write_active then
                    local pending_prefetch = browser.pending_prefetch
                    browser.pending_prefetch = nil
                    RequestCanonicalBrowserPage(
                        pending_prefetch.mode, pending_prefetch.folder_id,
                        pending_prefetch.offset, false, true)
                end
                return
            end
            paging.rows = rows
            paging.has_more = has_more
            paging.total_ms =
                (paging.total_ms or 0) + paging.elapsed_ms
            paging.validation_counts[paging.step or "unknown"] = #rows
            if paging.step == "roots" then
                local first_root = rows[1]
                if not first_root then
                    paging.active = false
                    paging.status = "Paged browsing returned no library folders."
                    paging.error = "The validated database has no enabled roots."
                else
                    paging.step = "folder"
                    paging.status = "Checking the first folder page..."
                    local ok, err = StartCanonicalPageQuery(
                        "folder", first_root.folder_id, 0)
                    if not ok then
                        paging.active = false
                        paging.status = "Paged browsing test could not continue."
                        paging.error = tostring(err)
                    end
                end
            elseif paging.step == "folder" then
                paging.step = "multi_tag"
                paging.status = "Checking combined tags..."
                local ok, err = StartCanonicalPageQuery(
                    "filter_multi_tag", nil, 0)
                if not ok then
                    paging.active = false
                    paging.status = "Combined-tag test could not continue."
                    paging.error = tostring(err)
                end
            elseif paging.step == "multi_tag" then
                paging.step = "classification"
                paging.status = "Checking media categories..."
                local ok, err = StartCanonicalPageQuery(
                    "filter_class", nil, 0)
                if not ok then
                    paging.active = false
                    paging.status = "Media-category test could not continue."
                    paging.error = tostring(err)
                end
            elseif paging.step == "classification" then
                paging.step = "key"
                paging.status = "Checking detected keys..."
                local ok, err = StartCanonicalPageQuery(
                    "filter_key", nil, 0)
                if not ok then
                    paging.active = false
                    paging.status = "Key-filter test could not continue."
                    paging.error = tostring(err)
                end
            else
                paging.active = false
                paging.step = "complete"
                local key_count = paging.validation_counts.key or 0
                paging.status = key_count > 0
                    and string.format(
                        "Paged filters validated: tags %d, media %d, key %d"
                            .. " (%d ms total)",
                        paging.validation_counts.multi_tag or 0,
                        paging.validation_counts.classification or 0,
                        key_count, paging.total_ms or 0)
                    or string.format(
                        "Tag/media paging validated; key metadata pending"
                            .. " (%d ms total)",
                        paging.total_ms or 0)
            end
        end
        if database.cancel_after_write then
            database.cancel_after_write = false
            database.scan_active = false
            database.finalize_pending = false
            database.status =
                "Database update cancelled; committed batches were kept"
            return
        end
    end

    if not database.scan_active then return end
    local queued_count =
        math.max(0, #database.queue - (database.queue_head or 1) + 1)
    if queued_count >= DATABASE_BATCH_SIZE
        or (database.finalize_pending and queued_count > 0) then
        local count = math.min(DATABASE_BATCH_SIZE, queued_count)
        local sql = {"BEGIN IMMEDIATE;\n"}
        for index = 1, count do
            sql[#sql + 1] = MakeMediaDatabaseUpsert(
                database.queue[(database.queue_head or 1) + index - 1],
                database.generation)
        end
        sql[#sql + 1] = "COMMIT;\n"
        local ok, err = StartDatabaseBatchAsync(
            table.concat(sql), count, "batch")
        if not ok then DisableMediaDatabase(err); return end
        database.status = "Saving database in background..."
        return
    end
    if database.finalize_pending and queued_count == 0 then
        local completed_at = os.time()
        local sql = "BEGIN IMMEDIATE;\n"
        if not database.incremental_scan then
            sql = sql
                .. "UPDATE media_files SET missing=1 WHERE last_seen_generation<>"
                .. tostring(database.generation) .. ";\n"
                .. "DELETE FROM generated_media_tags WHERE file_id IN "
                .. "(SELECT id FROM media_files WHERE missing=1);\n"
                .. "DELETE FROM tags WHERE NOT EXISTS "
                .. "(SELECT 1 FROM file_tags WHERE file_tags.tag_id=tags.id);\n"
                .. "INSERT INTO app_meta(key,value) VALUES"
                .. "('completed_scan_generation'," .. SQLQuote(database.generation) .. "),"
                .. "('completed_scan_at'," .. SQLQuote(completed_at) .. ") "
                .. "ON CONFLICT(key) DO UPDATE SET value=excluded.value;\n"
        end
        sql = sql .. "COMMIT;\n"
        local ok, err = StartDatabaseBatchAsync(sql, 0, "finalize")
        if not ok then DisableMediaDatabase(err); return end
        database.status = "Finishing database update in background..."
    end
end

function ConsumeReadyCanonicalPageBeforeDraw()
    local database = state.database
    -- The worker publishes .res atomically, so existence means the complete
    -- response can be consumed without waiting. Only foreground/page reads
    -- move ahead of drawing; scans, writes, discovery and maintenance retain
    -- their post-input scheduling below.
    if database.backend ~= "sqlite"
        or database.write_pending_kind ~= "canonical_page"
        or not database.worker_active
        or not database.worker_result_path
        or not FileExists(database.worker_result_path) then
        return false
    end
    database.worker_pre_draw_completions =
        (database.worker_pre_draw_completions or 0) + 1
    ProcessMediaDatabase()
    return true
end

local function CompleteMediaDatabaseScan()
    local database = state.database
    if database.backend == "sqlite" and database.scan_active then
        database.finalize_pending = true
    end
end

local function CancelMediaDatabaseScan()
    local database = state.database
    if database.backend ~= "sqlite" then return end
    database.queue = {}
    database.queue_head = 1
    database.queued_index = {}
    database.scan_cancelled = true
    database.finalize_pending = false
    if database.write_active then
        database.cancel_after_write = true
        database.status = "Cancelling after the current database batch..."
    else
        database.scan_active = false
        database.status =
            "Database update cancelled; committed batches were kept"
    end
end

function PersistMediaTagsToDatabase(path, tags)
    local database = state.database
    if database.backend ~= "sqlite" or database.canonical then return false end
    local path_norm = NormalizeFavoritePath(path)
    local sql = {"BEGIN IMMEDIATE;\nDELETE FROM file_tags WHERE source='user' AND file_id="
        .. "(SELECT id FROM media_files WHERE path_norm=" .. SQLQuote(path_norm) .. ");\n"}
    for _, tag in ipairs(tags or {}) do
        sql[#sql + 1] = "INSERT INTO tags(name) VALUES(" .. SQLQuote(tag)
            .. ") ON CONFLICT(name) DO NOTHING;\n"
        sql[#sql + 1] = "INSERT INTO file_tags(file_id,tag_id,source,confidence) "
            .. "SELECT media_files.id,tags.id,'user',1.0 FROM media_files,tags "
            .. "WHERE media_files.path_norm=" .. SQLQuote(path_norm)
            .. " AND tags.name=" .. SQLQuote(tag)
            .. " ON CONFLICT(file_id,tag_id,source) DO NOTHING;\n"
    end
    sql[#sql + 1] = "COMMIT;\n"
    local ok, err = WriteDatabaseBatch(table.concat(sql))
    if not ok then DisableMediaDatabase(err) end
    return ok
end

function DecodeSQLHex(value)
    return (value or ""):gsub("%x%x", function(pair)
        return string.char(tonumber(pair, 16))
    end)
end

function LoadMediaMetadataFromDatabase()
    if state.database.backend ~= "sqlite" or state.database.canonical then return false end
    local imported_tags = false
    if not state.media_tags_file_present then
        local tag_rows, tags_error = QueryDatabaseScalar(
            "SELECT hex(mf.path)||'|'||group_concat(hex(t.name),',') "
            .. "FROM media_files mf JOIN file_tags ft ON ft.file_id=mf.id "
            .. "JOIN tags t ON t.id=ft.tag_id WHERE ft.source='user' GROUP BY mf.id;")
        if tag_rows == nil then
            state.database.error = tostring(tags_error)
            return false
        end
        imported_tags = true
        for line in (tag_rows or ""):gmatch("[^\r\n]+") do
            local path_hex, tag_hexes = line:match("^([%x]+)|([%x,]+)$")
            local path = DecodeSQLHex(path_hex)
            local key = NormalizeFavoritePath(path)
            if path ~= "" and not state.media_user_tags[key] then
                local tags = {}
                for tag_hex in (tag_hexes or ""):gmatch("[^,]+") do
                    local tag = NormalizeTag(DecodeSQLHex(tag_hex))
                    if tag ~= "" then tags[#tags + 1] = tag end
                end
                if #tags > 0 then state.media_user_tags[key] = {path = path, tags = tags} end
            end
        end
    end
    if imported_tags then SaveMediaUserTags() end
    return true
end

function CacheFavoriteEntryIdentity(entry)
    if not entry then return "", "", "" end
    local path = entry.path or ""
    if entry._favorite_identity_path ~= path then
        entry._favorite_identity_path = path
        entry._favorite_path_key = NormalizeFavoritePath(path)
        entry._favorite_name = GetFileName(path)
        entry._favorite_name_lower = entry._favorite_name:lower()
    end
    return entry._favorite_path_key,
        entry._favorite_name, entry._favorite_name_lower
end

-- Appends update favorite_index directly. Only array removals shift later
-- numeric indices, so defer the one unavoidable rebuild until a lookup or
-- view refresh actually needs it. This keeps repeated heart clicks from
-- becoming O(total favorites) work on every add.
EnsureFavoriteIndex = function()
    if not state.favorite_index_dirty then return end
    local rebuilt = {}
    for index, entry in ipairs(state.favorites or {}) do
        entry.collection_ids = entry.collection_ids or {}
        rebuilt[CacheFavoriteEntryIdentity(entry)] = index
    end
    state.favorite_index = rebuilt
    state.favorite_index_dirty = false
end

-- Mutations must never hydrate SQLite from the ImGui frame. The database
-- write is path-targeted and authoritative; this helper reads only the Lua
-- cache that is already available for immediate UI feedback.
function FindCachedFavoriteIndex(path)
    EnsureFavoriteIndex()
    return state.favorite_index[NormalizeFavoritePath(path)]
end

function AddCanonicalFavoriteCacheEntry(entry)
    if not entry or not entry.path or entry.path == "" then return nil end
    EnsureFavoriteIndex()
    local key = NormalizeFavoritePath(entry.path)
    local existing = state.favorite_index[key]
    if existing then return existing end
    entry.kind = entry.kind == "folder" and "folder" or "file"
    entry.added = tonumber(entry.added) or 0
    entry.collection_ids = entry.collection_ids or {}
    CacheFavoriteEntryIdentity(entry)
    state.favorites[#state.favorites + 1] = entry
    local index = #state.favorites
    state.favorite_index[key] = index
    state.favorite_lookup_miss[key] = nil
    return index
end

function LoadCanonicalFavoriteEntry(path)
    if not path or path == "" or not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath()) then
        return nil
    end
    local path_norm = NormalizeFavoritePath(path)
    local database_path = GetCanonicalDatabasePath()
    local file_sql = "SELECT hex(files.canonical_path)||char(9)||"
        .. "COALESCE(MAX(collection_items.added_at),"
        .. "MAX(user_file_data.updated_at),0)||char(9)||"
        .. "COALESCE(MAX(user_file_data.favorite),0)||char(9)||COALESCE("
        .. "group_concat(hex(collection_external_keys.external_key),','),'') "
        .. "FROM files LEFT JOIN user_file_data ON user_file_data.file_id=files.id "
        .. "LEFT JOIN collection_items ON collection_items.file_id=files.id "
        .. "LEFT JOIN collection_external_keys ON collection_external_keys.collection_id="
        .. "collection_items.collection_id WHERE files.canonical_path_norm="
        .. SQLQuote(path_norm) .. " AND (COALESCE(user_file_data.favorite,0)=1 OR "
        .. "collection_items.collection_id IS NOT NULL) GROUP BY files.id;"
    local output = QueryDatabaseScalarAtPath(database_path, file_sql)
    local line = tostring(output or ""):match("[^\r\n]+")
    if line then
        -- Scalar queries trim trailing whitespace, so a direct Favorite with
        -- no custom-collection memberships arrives without its final tab.
        -- Append a sentinel delimiter before parsing to retain the empty field.
        local path_hex, added, direct, memberships = (line .. "\t"):match(
            "^([^\t]+)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t?$")
        if path_hex then
            local entry = {
                kind = "file", path = DecodeSQLHex(path_hex),
                added = tonumber(added) or 0, collection_ids = {},
                _direct_favorite = direct == "1",
            }
            for value in (memberships or ""):gmatch("[^,]+") do
                local id = DecodeSQLHex(value)
                if id ~= "" then entry.collection_ids[id] = true end
            end
            AddCanonicalFavoriteCacheEntry(entry)
            return entry
        end
    end

    local folder_predicate = CanonicalFolderPathPredicate(path_norm)
    local folder_sql = "SELECT folders.id||char(9)||hex(roots.display_path||CASE WHEN "
        .. "folders.relative_path='' THEN '' ELSE '/'||folders.relative_path END)"
        .. "||char(9)||COALESCE(MAX(collection_items.added_at),0)||char(9)||"
        .. "MAX(CASE WHEN collection_items.collection_id=-1 THEN 1 ELSE 0 END)"
        .. "||char(9)||"
        .. "COALESCE(group_concat(hex(collection_external_keys.external_key),','),'') "
        .. "FROM folders JOIN roots ON roots.id=folders.root_id JOIN collection_items "
        .. "ON collection_items.folder_id=folders.id LEFT JOIN collection_external_keys "
        .. "ON collection_external_keys.collection_id=collection_items.collection_id "
        .. "WHERE " .. folder_predicate .. " AND folders.missing=0 GROUP BY folders.id;"
    output = QueryDatabaseScalarAtPath(database_path, folder_sql)
    line = tostring(output or ""):match("[^\r\n]+")
    if line then
        local folder_id, path_hex, added, direct, memberships =
            (line .. "\t"):match(
                "^(%d+)\t([^\t]+)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t?$")
        if folder_id and path_hex then
            local entry = {
                kind = "folder", path = DecodeSQLHex(path_hex),
                added = tonumber(added) or 0, collection_ids = {},
                _canonical_folder_id = tonumber(folder_id),
                _direct_favorite = direct == "1",
            }
            for value in (memberships or ""):gmatch("[^,]+") do
                local id = DecodeSQLHex(value)
                if id ~= "" then entry.collection_ids[id] = true end
            end
            AddCanonicalFavoriteCacheEntry(entry)
            return entry
        end
    end
    state.favorite_lookup_miss[path_norm] = true
    return nil
end

function LoadCanonicalFavoritesFromDatabase()
    if not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath()) then
        return false
    end
    local database_path = GetCanonicalDatabasePath()
    local collection_sql = "SELECT hex(keys.external_key)||char(9)||hex(c.name)||"
        .. "char(9)||c.created_at||char(9)||COALESCE(hex(parent_keys.external_key),'') "
        .. "FROM collections c JOIN collection_external_keys keys ON keys.collection_id=c.id "
        .. "LEFT JOIN collections parents ON parents.id=c.parent_id LEFT JOIN "
        .. "collection_external_keys parent_keys ON parent_keys.collection_id=parents.id "
        .. "WHERE c.id<>-1 ORDER BY c.sort_order,c.id;"
    local collection_rows, collection_error =
        QueryDatabaseScalarAtPath(database_path, collection_sql)
    if collection_rows == nil then
        state.database.error = tostring(collection_error)
        return false
    end
    for line in tostring(collection_rows or ""):gmatch("[^\r\n]+") do
        local fields = {}
        for field in (line .. "\t"):gmatch("(.-)\t") do
            fields[#fields + 1] = field
        end
        local id = DecodeSQLHex(fields[1] or "")
        if id ~= "" then
            local decoded_name = DecodeSQLHex(fields[2] or "")
            state.favorite_collections[#state.favorite_collections + 1] = {
                id = id,
                name = decoded_name ~= "" and decoded_name or "Favorites Folder",
                added = tonumber(fields[3]) or 0,
                parent_id = DecodeSQLHex(fields[4] or "")
            }
            if state.favorite_collections[#state.favorite_collections].parent_id == "" then
                state.favorite_collections[#state.favorite_collections].parent_id = nil
            end
        end
    end
    local collections_by_id = {}
    local valid_collections = {}
    for _, folder in ipairs(state.favorite_collections) do
        local id = tostring(folder.id or "")
        if id ~= "" and not collections_by_id[id] then
            folder.id = id
            folder.parent_id = folder.parent_id
                and tostring(folder.parent_id) or nil
            collections_by_id[id] = folder
            valid_collections[#valid_collections + 1] = folder
        end
    end
    state.favorite_collections = valid_collections
    for _, folder in ipairs(state.favorite_collections) do
        if folder.parent_id == folder.id
            or (folder.parent_id
                and not collections_by_id[folder.parent_id]) then
            folder.parent_id = nil
        end
    end
    for _, folder in ipairs(state.favorite_collections) do
        local seen_parents = {[folder.id] = true}
        local parent_id = folder.parent_id
        while parent_id do
            if seen_parents[parent_id] then
                folder.parent_id = nil
                break
            end
            seen_parents[parent_id] = true
            local parent = collections_by_id[parent_id]
            parent_id = parent and parent.parent_id or nil
        end
    end

    -- Direct files stay database-backed and load through the bounded loose-root
    -- pager. Favorite physical folders are hydrated as navigation nodes; their
    -- descendant files continue to load in bounded canonical pages.
    local folder_sql = "SELECT folders.id||char(9)||hex(roots.display_path||CASE WHEN "
        .. "folders.relative_path='' THEN '' ELSE '/'||folders.relative_path END)||"
        .. "char(9)||MAX(CASE WHEN collection_items.collection_id=-1 THEN 1 "
        .. "ELSE 0 END)||char(9)||MAX(collection_items.added_at)||char(9)||COALESCE("
        .. "group_concat(CASE WHEN collection_items.collection_id=-1 THEN NULL ELSE "
        .. "hex(collection_external_keys.external_key) END,','),'')||char(9)||COALESCE("
        .. "MAX(folder_subtree_stats.file_count),0) FROM collection_items "
        .. "JOIN folders ON folders.id=collection_items.folder_id JOIN roots ON roots.id="
        .. "folders.root_id LEFT JOIN collection_external_keys ON collection_external_keys.collection_id="
        .. "collection_items.collection_id LEFT JOIN folder_subtree_stats ON "
        .. "folder_subtree_stats.folder_id=folders.id WHERE folders.missing=0 AND roots.enabled=1 "
        .. "GROUP BY folders.id ORDER BY collection_items.added_at,folders.id;"
    local folder_rows, folder_error =
        QueryDatabaseScalarAtPath(database_path, folder_sql)
    if folder_rows == nil then
        state.database.error = tostring(folder_error)
        return false
    end
    for line in tostring(folder_rows or ""):gmatch("[^\r\n]+") do
        local folder_id, path_hex, direct, added, memberships, subtree_count =
            (line .. "\t"):match(
                "^(%d+)\t([^\t]+)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t?$")
        if folder_id and path_hex then
            local canonical_folder_id = tonumber(folder_id)
            local entry = {
                kind = "folder", path = DecodeSQLHex(path_hex),
                added = tonumber(added) or 0, collection_ids = {},
                _canonical_folder_id = canonical_folder_id,
                _direct_favorite = direct == "1",
            }
            if canonical_folder_id then
                state.canonical_browser.folder_scope_counts[
                    canonical_folder_id] = tonumber(subtree_count) or 0
            end
            for value in (memberships or ""):gmatch("[^,]+") do
                local id = DecodeSQLHex(value)
                if id ~= "" and collections_by_id[id] then
                    entry.collection_ids[id] = true
                end
            end
            AddCanonicalFavoriteCacheEntry(entry)
        end
    end
    return true
end

function CancelCanonicalFavoriteMutations(paths)
    local pending = state.favorite_mutation_pending or {}
    local versions = state.favorite_mutation_versions or {}
    state.favorite_mutation_versions = versions
    for _, path in ipairs(paths or {}) do
        local key = NormalizeFavoritePath(path)
        if key ~= "" then
            versions[key] = (versions[key] or 0) + 1
            pending[key] = nil
        end
    end
end

function CancelCanonicalFavoriteCollectionMutations(collection_id)
    local collection_key = collection_id and tostring(collection_id) or nil
    if not collection_key then return end
    local pending = state.favorite_mutation_pending or {}
    local versions = state.favorite_mutation_versions or {}
    state.favorite_mutation_versions = versions
    for key, mutation in pairs(pending) do
        if tostring(mutation.collection_id or "") == collection_key then
            local path_key = NormalizeFavoritePath(mutation.path)
            if path_key ~= "" then
                versions[path_key] = (versions[path_key] or 0) + 1
            end
            pending[key] = nil
        end
    end
    for _, mutation in ipairs(state.favorite_mutation_inflight or {}) do
        if tostring(mutation.collection_id or "") == collection_key then
            local path_key = NormalizeFavoritePath(mutation.path)
            if path_key ~= "" then
                versions[path_key] = (versions[path_key] or 0) + 1
            end
        end
    end
end

function QueueCanonicalFavoriteMutation(
    path, kind, canonical_folder_id, collection_id)
    kind = kind == "folder" and "folder" or "file"
    if not path or path == ""
        or not state.database.canonical then
        return false
    end
    local key = NormalizeFavoritePath(path)
    if key == "" then return false end
    local versions = state.favorite_mutation_versions or {}
    state.favorite_mutation_versions = versions
    versions[key] = (versions[key] or 0) + 1
    state.favorite_mutation_pending[key] = {
        path = path, kind = kind,
        collection_id = collection_id,
        canonical_folder_id = canonical_folder_id,
        version = versions[key],
    }
    state.favorite_mutation_next_frame = math.max(
        state.favorite_mutation_next_frame or 0,
        (state.ui_frame_index or 0) + 1)
    return true
end

function QueueCanonicalFavoriteCollectionMemberships(
    paths, collection_id, kind, canonical_folder_id)
    if not state.database.canonical or not collection_id then return 0 end
    local queued = 0
    for _, path in ipairs(paths or {}) do
        if QueueCanonicalFavoriteMutation(
            path, kind, canonical_folder_id, collection_id) then
            state.favorite_pending_overrides[
                NormalizeFavoritePath(path)] = true
            queued = queued + 1
        end
    end
    if queued > 0 then
        -- The context menu has no row node handle to invalidate directly.
        -- Advance the shared decoration generation so Library hearts read
        -- the pending custom-membership state on the next frame.
        state.media_favorite_generation =
            (state.media_favorite_generation or 0) + 1
        state.needs_visible_update = true
    end
    return queued
end

function BuildCanonicalFavoriteMutationLookupSQL(entries)
    local values = {}
    for _, entry in ipairs(entries or {}) do
        values[#values + 1] = "(" .. SQLQuote(
            NormalizeFavoritePath(entry.path)) .. ")"
    end
    if #values == 0 then return nil end
    local kind = entries[1].kind == "folder" and "folder" or "file"
    if kind == "folder" then
        -- Resolve only the requested folder paths. This keeps folder heart
        -- clicks off the synchronous scalar lookup without enumerating the
        -- folder's descendants.
        return "WITH requested(path_norm) AS (VALUES "
            .. table.concat(values, ",") .. "), resolved AS (SELECT "
            .. "requested.path_norm,roots.id AS root_id,CASE WHEN "
            .. "requested.path_norm=roots.path_norm THEN '' ELSE substr("
            .. "requested.path_norm,length(roots.path_norm)+2) END "
            .. "AS relative_path_norm FROM requested JOIN roots ON ("
            .. "requested.path_norm=roots.path_norm OR substr("
            .. "requested.path_norm,1,length(roots.path_norm)+1)="
            .. "roots.path_norm||'/') AND roots.enabled=1) SELECT "
            .. "hex(resolved.path_norm)||char(9)||'D'||char(9)||folders.id"
            .. "||char(9)||hex(roots.display_path||CASE WHEN folders."
            .. "relative_path='' THEN '' ELSE '/'||folders.relative_path END)"
            .. "||char(9)||COALESCE(MAX(collection_items.added_at),0)"
            .. "||char(9)||COALESCE(MAX(CASE WHEN collection_items."
            .. "collection_id=-1 THEN 1 ELSE 0 END),0)||char(9)||COALESCE("
            .. "group_concat(CASE WHEN collection_items.collection_id=-1"
            .. " THEN NULL ELSE hex(collection_external_keys.external_key)"
            .. " END,','),'') FROM resolved JOIN roots ON roots.id="
            .. "resolved.root_id JOIN folders ON folders.root_id=resolved."
            .. "root_id AND folders.relative_path_norm=resolved."
            .. "relative_path_norm LEFT JOIN collection_items ON "
            .. "collection_items.folder_id=folders.id LEFT JOIN "
            .. "collection_external_keys ON collection_external_keys."
            .. "collection_id=collection_items.collection_id WHERE folders."
            .. "missing=0 GROUP BY resolved.path_norm,folders.id;"
    end
    -- Return one bounded row per requested path. This preserves existing
    -- collection memberships without issuing one helper process per file.
    return "WITH requested(path_norm) AS (VALUES "
        .. table.concat(values, ",") .. ") SELECT hex(requested.path_norm)"
        .. "||char(9)||'F'||char(9)||COALESCE(MAX(hex(files.canonical_path)),'')"
        .. "||char(9)||COALESCE(MAX(collection_items.added_at),"
        .. "MAX(user_file_data.updated_at),0)||char(9)||COALESCE(MAX("
        .. "user_file_data.favorite),0)||char(9)||COALESCE(group_concat("
        .. "hex(collection_external_keys.external_key),','),'') FROM requested "
        .. "LEFT JOIN files ON files.canonical_path_norm=requested.path_norm "
        .. "LEFT JOIN user_file_data ON user_file_data.file_id=files.id "
        .. "LEFT JOIN collection_items ON collection_items.file_id=files.id "
        .. "LEFT JOIN collection_external_keys ON collection_external_keys."
        .. "collection_id=collection_items.collection_id GROUP BY requested.path_norm;"
end

function StartPendingCanonicalFavoriteMutationLookup()
    local database = state.database
    if database.write_active
        or CanonicalUserDataQueueCount(state.canonical_user_data) > 0
        or state.canonical_paging.active
        or state.database.worker_restart_pending
        or not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath())
        or (state.ui_frame_index or 0)
            < (state.favorite_mutation_next_frame or 0) then
        return false
    end
    local pending = state.favorite_mutation_pending or {}
    local selected, values = {}, {}
    local selected_kind
    for key, entry in pairs(pending) do
        local entry_kind = entry.kind == "folder" and "folder" or "file"
        if not selected_kind then selected_kind = entry_kind end
        if entry_kind == selected_kind then
            selected[#selected + 1] = entry
            values[#values + 1] = key
        end
        if #selected >= 100 then break end
    end
    if #selected == 0 then return false end
    local sql = BuildCanonicalFavoriteMutationLookupSQL(selected)
    if not sql then return false end
    local ok = StartDatabaseBatchAsync(
        sql, #selected, "canonical_favorite_mutation",
        GetCanonicalDatabasePath())
    if not ok then
        state.favorite_mutation_next_frame =
            (state.ui_frame_index or 0) + 1
        return false
    end
    for _, key in ipairs(values) do
        pending[key] = nil
    end
    state.favorite_mutation_inflight = selected
    state.favorite_mutation_next_frame = 0
    return true
end

function RequeueCanonicalFavoriteMutations()
    local versions = state.favorite_mutation_versions or {}
    for _, entry in ipairs(state.favorite_mutation_inflight or {}) do
        local key = NormalizeFavoritePath(entry.path)
        if versions[key] == entry.version then
            state.favorite_mutation_pending[key] = entry
        end
    end
    state.favorite_mutation_inflight = {}
    state.favorite_mutation_next_frame =
        (state.ui_frame_index or 0) + 1
end

function ApplyCanonicalFavoriteMutationLookup(output)
    local versions = state.favorite_mutation_versions or {}
    local active = {}
    for _, mutation in ipairs(state.favorite_mutation_inflight or {}) do
        local key = NormalizeFavoritePath(mutation.path)
        if versions[key] == mutation.version then
            active[key] = true
        end
    end
    local seen = {}
    for line in tostring(output or ""):gmatch("[^\r\n]+") do
        local path_hex, row_kind, field1, field2, field3, field4, field5 =
            (line .. "\t"):match("^([^\t]+)\t([FD])\t"
                .. "([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t?"
                .. "([^\t]*)\t?$")
        local folder_id, actual_hex, added, direct, memberships
        if row_kind == "D" then
            folder_id, actual_hex, added, direct, memberships =
                field1, field2, field3, field4, field5
        else
            actual_hex, added, direct, memberships =
                field1, field2, field3, field4
        end
        local path_norm = path_hex and DecodeSQLHex(path_hex) or ""
        local path_key = NormalizeFavoritePath(path_norm)
        if path_norm ~= "" and active[path_key] then
            local key = path_key
            seen[key] = true
            if actual_hex ~= "" and (direct == "1" or memberships ~= "") then
                local entry = {
                    kind = row_kind == "D" and "folder" or "file",
                    path = DecodeSQLHex(actual_hex),
                    added = tonumber(added) or 0, collection_ids = {},
                    _direct_favorite = direct == "1",
                }
                if row_kind == "D" then
                    entry._canonical_folder_id = tonumber(folder_id)
                end
                for value in tostring(memberships or ""):gmatch("[^,]+") do
                    local collection_key = DecodeSQLHex(value)
                    if collection_key ~= "" then
                        entry.collection_ids[collection_key] = true
                    end
                end
                AddCanonicalFavoriteCacheEntry(entry)
            else
                state.favorite_lookup_miss[key] = true
            end
        end
    end
    local groups = {}
    local group_order = {}
    for _, mutation in ipairs(state.favorite_mutation_inflight or {}) do
        local key = NormalizeFavoritePath(mutation.path)
        if active[key] then
            if not seen[key] then state.favorite_lookup_miss[key] = true end
            local mutation_kind = mutation.kind == "folder" and "folder" or "file"
            local collection_key = mutation.collection_id
                and tostring(mutation.collection_id) or ""
            local group_key = mutation_kind .. "\31" .. collection_key
            if not groups[group_key] then
                groups[group_key] = {
                    kind = mutation_kind,
                    collection_id = mutation.collection_id,
                    paths = {},
                }
                group_order[#group_order + 1] = group_key
            end
            groups[group_key].paths[#groups[group_key].paths + 1] = mutation.path
        end
    end
    state.favorite_mutation_inflight = {}
    for _, group_key in ipairs(group_order) do
        local group = groups[group_key]
        if #group.paths > 0 then
            -- Keep each custom collection's membership mutation separate so
            -- one mixed batch cannot accidentally add every path to the same
            -- collection.
            SetFavoritePaths(
                group.paths, true, group.kind,
                group.collection_id, nil)
        end
    end
end

function PrimeCanonicalFavoriteMembershipCache(rows)
    if not state.database.canonical or not rows
        or #rows == 0 or not FileExists(GetCanonicalDatabasePath()) then
        return
    end
    -- Membership is needed for hearts in ordinary Library pages, but it is
    -- decoration rather than navigation. Queue and debounce it instead of
    -- taking the persistent reader directly from a folder-page apply frame.
    local pending = state.favorite_membership_pending_paths
    local inflight = state.favorite_membership_inflight_paths
    for _, row in ipairs(rows) do
        local key = NormalizeFavoritePath(row.path or "")
        if key ~= "" and state.favorite_membership_cache[key] == nil
            and not pending[key] and not inflight[key] then
            pending[key] = true
        end
    end
    state.favorite_membership_next_at = math.max(
        state.favorite_membership_next_at or 0,
        r.time_precise() + 0.25)
end

function StartPendingCanonicalFavoriteMembershipQuery()
    if state.favorite_membership_query_pending
        or state.file_context_menu_open_frame == state.ui_frame_index
        or state.database.write_active
        or state.canonical_paging.active
        or state.canonical_browser.deferred_request
        or state.canonical_browser.pending_prefetch
        or state.canonical_browser.pending_tag_folder_id ~= nil
        or state.database.worker_restart_pending
        or state.database.worker_refresh_requested
        or r.time_precise() < (state.favorite_membership_next_at or 0)
        or not state.database.canonical
        or not FileExists(GetCanonicalDatabasePath()) then
        return false
    end
    local pending = state.favorite_membership_pending_paths
    local selected, values = {}, {}
    for key in pairs(pending) do
        selected[#selected + 1] = key
        values[#values + 1] = "(" .. SQLQuote(key) .. ")"
        if #selected >= 100 then break end
    end
    if #values == 0 then return false end
    local sql = "WITH requested(path_norm) AS (VALUES "
        .. table.concat(values, ",") .. ") SELECT requested.path_norm||char(9)||CASE WHEN "
        .. "EXISTS(SELECT 1 FROM files JOIN user_file_data ON user_file_data.file_id=files.id "
        .. "WHERE files.canonical_path_norm=requested.path_norm AND user_file_data.favorite=1) "
        .. "OR EXISTS(SELECT 1 FROM files JOIN collection_items ON collection_items.file_id=files.id "
        .. "WHERE files.canonical_path_norm=requested.path_norm AND collection_items.collection_id=-1) "
        .. "OR EXISTS(SELECT 1 FROM files JOIN collection_items ON collection_items.file_id=files.id "
        .. "WHERE files.canonical_path_norm=requested.path_norm AND collection_items.collection_id<>-1) "
        .. "OR EXISTS(SELECT 1 FROM roots JOIN folders ON folders.root_id=roots.id "
        .. "JOIN collection_items ON collection_items.folder_id=folders.id "
        .. "WHERE collection_items.collection_id=-1 AND (requested.path_norm=roots.path_norm "
        .. "OR substr(requested.path_norm,1,length(roots.path_norm)+1)=roots.path_norm||'/') "
        .. "AND folders.relative_path_norm=CASE WHEN requested.path_norm=roots.path_norm "
        .. "THEN '' ELSE substr(requested.path_norm,length(roots.path_norm)+2) END) "
        .. "OR EXISTS(SELECT 1 FROM roots JOIN folders ON folders.root_id=roots.id "
        .. "JOIN collection_items ON collection_items.folder_id=folders.id "
        .. "WHERE collection_items.collection_id<>-1 AND (requested.path_norm=roots.path_norm "
        .. "OR substr(requested.path_norm,1,length(roots.path_norm)+1)=roots.path_norm||'/') "
        .. "AND folders.relative_path_norm=CASE WHEN requested.path_norm=roots.path_norm "
        .. "THEN '' ELSE substr(requested.path_norm,length(roots.path_norm)+2) END) "
        .. "THEN '1' ELSE '0' END FROM requested;"
    local ok = StartDatabaseBatchAsync(
        sql, 0, "canonical_membership", GetCanonicalDatabasePath())
    if ok then
        state.favorite_membership_query_pending = true
        local inflight = state.favorite_membership_inflight_paths
        for _, key in ipairs(selected) do
            pending[key] = nil
            inflight[key] = true
        end
    else
        state.favorite_membership_next_at = r.time_precise() + 0.25
    end
    return ok == true
end

function LoadFavorites()
    state.favorites = {}
    state.favorite_index = {}
    state.favorite_index_dirty = false
    state.favorite_lookup_miss = {}
    state.favorite_membership_cache = {}
    state.favorite_membership_pending_paths = {}
    state.favorite_membership_inflight_paths = {}
    state.favorite_membership_next_at = 0
    state.favorite_membership_query_pending = false
    state.favorite_mutation_pending = {}
    state.favorite_mutation_inflight = {}
    state.favorite_mutation_versions = {}
    state.favorite_mutation_next_frame = 0
    state.favorite_pending_overrides = {}
    state.favorite_collections = {}
    if state.database.canonical then
        LoadCanonicalFavoritesFromDatabase()
    end
end

function FavoriteEntryHasCollection(entry, collection_id)
    return entry and entry.collection_ids
        and entry.collection_ids[tostring(collection_id)] == true
end

function FavoriteEntryHasAnyMembership(entry)
    return entry ~= nil and (entry._direct_favorite == true
        or next(entry.collection_ids or {}) ~= nil)
end

function FavoritePathHasMembership(path, collection_id)
    local normalized = NormalizeFavoritePath(path)
    local index = FindCachedFavoriteIndex(path)
    local entry = index and state.favorites[index] or nil
    if collection_id then
        return FavoriteEntryHasCollection(entry, collection_id)
    end
    local pending = state.favorite_pending_overrides[normalized]
    if pending ~= nil then return pending == true end
    if FavoriteEntryHasAnyMembership(entry) then
        return true
    end
    return state.favorite_membership_cache[normalized] == true
end

local function RemoveFavoriteEntryIfUnowned(path)
    local key = NormalizeFavoritePath(path)
    for index = #state.favorites, 1, -1 do
        local entry = state.favorites[index]
        if NormalizeFavoritePath(entry.path) == key
            and entry._direct_favorite ~= true
            and next(entry.collection_ids or {}) == nil then
            -- Keep an explicit false until visible canonical rows have observed
            -- the mutation; clearing this lets an old row decoration win.
            state.favorite_pending_overrides[key] = false
            table.remove(state.favorites, index)
            state.favorite_index_dirty = true
            return true
        end
    end
    return false
end

local function SyncFavoritePendingOverride(path)
    local key = NormalizeFavoritePath(path)
    EnsureFavoriteIndex()
    local index = state.favorite_index[key]
    local entry = index and state.favorites[index] or nil
    state.favorite_pending_overrides[key] =
        FavoriteEntryHasAnyMembership(entry)
end

function AddFavoriteCollectionMembership(path, collection_id, kind)
    if not path or not collection_id then return false end
    return SetFavoriteCollectionMemberships(
        {path}, collection_id, true, kind or "file")
end

function RemoveFavoriteCollectionMembership(path, collection_id)
    local index = FindCachedFavoriteIndex(path)
    local entry = index and state.favorites[index]
    local entry_kind = entry and entry.kind or "file"
    local canonical_folder_id = entry and entry._canonical_folder_id or nil
    return SetFavoriteCollectionMemberships(
        {path}, collection_id, false, entry_kind, canonical_folder_id)
end

function SetFavoriteCollectionMemberships(
    paths, collection_id, enabled, kind, canonical_folder_id)
    if not paths or not collection_id then return false end
    CancelCanonicalFavoriteMutations(paths)
    local changed = false
    local key = tostring(collection_id)
    local touched = {}
    local intent_sql = {}
    for _, path in ipairs(paths) do
        if state.database.canonical then
            local membership_sql =
                BuildCanonicalFavoriteCollectionMembershipSQL(
                    path, kind or "file", collection_id, enabled,
                    canonical_folder_id)
            if membership_sql then intent_sql[#intent_sql + 1] = membership_sql end
        end
        local index = FindCachedFavoriteIndex(path)
        local created = false
        if enabled and not index then
            created = AddFavorite(
                path, kind or "file", collection_id, true, true,
                canonical_folder_id) == true
            index = FindCachedFavoriteIndex(path)
        end
        local entry = index and state.favorites[index]
        if entry then
            entry.collection_ids = entry.collection_ids or {}
            if created then
                changed = true
                touched[NormalizeFavoritePath(entry.path)] = {
                    path = entry.path, kind = entry.kind or kind or "file"}
            elseif enabled and not entry.collection_ids[key] then
                entry.collection_ids[key] = true
                changed = true
                touched[NormalizeFavoritePath(entry.path)] = {
                    path = entry.path, kind = entry.kind or kind or "file"}
            elseif not enabled and entry.collection_ids[key] then
                entry.collection_ids[key] = nil
                changed = true
                touched[NormalizeFavoritePath(entry.path)] = {
                    path = entry.path, kind = entry.kind or kind or "file"}
            end
        end
    end
    for _, path in ipairs(paths) do
        local path_key = NormalizeFavoritePath(path)
        if path_key ~= "" then
            state.favorite_pending_overrides[path_key] = enabled == true
        end
    end
    if not enabled then
        for _, path in ipairs(paths) do
            SyncFavoritePendingOverride(path)
        end
    end
    local queued = QueueCanonicalFavoriteIntentSQL(intent_sql)
    if changed or queued then
        SaveFavorites(false)
        if not state.database.canonical then
            for _, target in pairs(touched) do
                QueueCanonicalFavoriteEntrySnapshot(
                    target.path, target.kind)
            end
        end
        for _, target in pairs(touched) do
            RemoveFavoriteEntryIfUnowned(target.path)
        end
        for _, target in pairs(touched) do
            SyncFavoritePendingOverride(target.path)
        end
        RefreshFavoriteMembershipRows(
            paths, {[key] = true}, kind or "file")
        InvalidateCanonicalFavoriteViews()
    end
    return changed or queued == true
end

function ClearFavoriteCollectionMembershipsForPaths(paths)
    local changed = false
    local touched = {}
    local affected_collections = {}
    CancelCanonicalFavoriteMutations(paths)
    for _, path in ipairs(paths or {}) do
        local index = FindCachedFavoriteIndex(path)
        local entry = index and state.favorites[index]
        if entry and next(entry.collection_ids or {}) ~= nil then
            for collection_id in pairs(entry.collection_ids) do
                affected_collections[tostring(collection_id)] = true
            end
            entry.collection_ids = {}
            changed = true
            touched[#touched + 1] = {
                path = entry.path, kind = entry.kind or "file"}
        end
    end
    if changed then
        SaveFavorites(false)
        local all_files = true
        local touched_paths = {}
        for _, target in ipairs(touched) do
            QueueCanonicalFavoriteEntrySnapshot(target.path, target.kind)
            touched_paths[#touched_paths + 1] = target.path
            if target.kind ~= "file" then all_files = false end
        end
        for _, target in ipairs(touched) do
            RemoveFavoriteEntryIfUnowned(target.path)
        end
        for _, target in ipairs(touched) do
            SyncFavoritePendingOverride(target.path)
        end
        if all_files then
            RefreshFavoriteMembershipRows(
                touched_paths, affected_collections, "file")
        else
            RefreshFavoritesView()
        end
        InvalidateCanonicalFavoriteViews()
    end
    return changed
end

function MoveFavoritePathsToCollection(
    paths, source_collection_id, target_collection_id, kind)
    if not target_collection_id then return false end
    -- A move is authoritative for the whole item. Invalidate an older lazy
    -- membership lookup before its completion can restore the source state.
    CancelCanonicalFavoriteMutations(paths)
    local source_is_root = source_collection_id == RB_FAVORITES_ROOT_MEMBERSHIP
    local source_key = not source_is_root and source_collection_id
        and tostring(source_collection_id) or nil
    local target_key = tostring(target_collection_id)
    local changed = false
    local touched = {}
    for _, path in ipairs(paths or {}) do
        local index = FindCachedFavoriteIndex(path)
        if not index then
            local created = AddFavorite(
                path, kind or "file", target_collection_id, true, true)
            index = FindCachedFavoriteIndex(path)
            if created and index then
                local created_entry = state.favorites[index]
                changed = true
                touched[NormalizeFavoritePath(created_entry.path)] = {
                    path = created_entry.path,
                    kind = created_entry.kind or kind or "file"}
            end
        end
        local entry = index and state.favorites[index]
        if entry then
            local entry_changed = false
            entry.collection_ids = entry.collection_ids or {}
            if source_is_root and entry._direct_favorite == true then
                entry._direct_favorite = false
                changed = true
                entry_changed = true
            end
            if source_key and source_key ~= target_key
                and entry.collection_ids[source_key] then
                entry.collection_ids[source_key] = nil
                changed = true
                entry_changed = true
            end
            if not entry.collection_ids[target_key] then
                entry.collection_ids[target_key] = true
                changed = true
                entry_changed = true
            end
            if entry_changed then
                local entry_key = NormalizeFavoritePath(entry.path)
                -- Moving out of the loose Favorites root does not unfavorite
                -- the item: the target collection now owns its membership.
                -- Keep Library hearts filled while the database write commits.
                state.favorite_pending_overrides[entry_key] = true
                touched[entry_key] = {
                    path = entry.path, kind = entry.kind or kind or "file"}
            end
        end
    end
    if changed then
        SaveFavorites(false)
        local all_files = true
        local touched_paths = {}
        for _, target in pairs(touched) do
            QueueCanonicalFavoriteEntrySnapshot(target.path, target.kind)
            touched_paths[#touched_paths + 1] = target.path
            if target.kind ~= "file" then all_files = false end
        end
        if all_files then
            local affected = {[target_key] = true}
            if source_key then affected[source_key] = true end
            RefreshFavoriteMembershipRows(
                touched_paths, affected, kind or "file")
        else
            RefreshFavoritesView()
        end
        InvalidateCanonicalFavoriteViews()
    end
    return changed
end

function MoveFavoritePathsToRoot(paths, source_collection_id, kind)
    -- Keep a delayed membership lookup from replaying the pre-move snapshot.
    CancelCanonicalFavoriteMutations(paths)
    local source_key = source_collection_id
        and tostring(source_collection_id) or nil
    local changed = false
    local touched = {}
    for _, path in ipairs(paths or {}) do
        local index = FindCachedFavoriteIndex(path)
        if not index then
            AddFavorite(path, kind or "file", nil, true, true)
            index = FindCachedFavoriteIndex(path)
        end
        local entry = index and state.favorites[index]
        if entry then
            local entry_changed = false
            entry.collection_ids = entry.collection_ids or {}
            if entry._direct_favorite ~= true then
                entry._direct_favorite = true
                entry_changed = true
            end
            if source_key and entry.collection_ids[source_key] then
                entry.collection_ids[source_key] = nil
                entry_changed = true
            end
            if entry_changed then
                state.favorite_pending_overrides[
                    NormalizeFavoritePath(entry.path)] = true
                touched[NormalizeFavoritePath(entry.path)] = {
                    path = entry.path, kind = entry.kind or kind or "file"}
                changed = true
            end
        end
    end
    if changed then
        local all_files = true
        local touched_paths = {}
        for _, target in pairs(touched) do
            QueueCanonicalFavoriteEntrySnapshot(target.path, target.kind)
            touched_paths[#touched_paths + 1] = target.path
            if target.kind ~= "file" then all_files = false end
        end
        SaveFavorites(false)
        if all_files then
            local affected = {}
            if source_key then affected[source_key] = true end
            RefreshFavoriteMembershipRows(
                touched_paths, affected, kind or "file")
        else
            RefreshFavoritesView()
        end
        InvalidateCanonicalFavoriteViews()
    end
    return changed
end

function ApplyFavoritePathsToCollection(
    paths, target_collection_id, kind, source_kind,
    source_collection_id, copy_drop)
    if not target_collection_id then return false end
    if source_kind == "inherited" or source_kind == "library"
        or copy_drop then
        return SetFavoriteCollectionMemberships(
            paths, target_collection_id, true, kind)
    end
    if source_kind == "root" then
        return MoveFavoritePathsToCollection(
            paths, RB_FAVORITES_ROOT_MEMBERSHIP,
            target_collection_id, kind)
    end
    return MoveFavoritePathsToCollection(
        paths, source_collection_id, target_collection_id, kind)
end

function ApplyFavoritePathsToRoot(
    paths, kind, source_kind, source_collection_id, copy_drop)
    if source_kind == "root" then return false end
    if source_kind == "collection" and not copy_drop then
        return MoveFavoritePathsToRoot(
            paths, source_collection_id, kind)
    end
    return SetFavoritePaths(paths, true, kind) > 0
end

function GetFavoriteEntryTargets(entry, collection_nodes)
    local targets = {}
    local memberships = entry and entry.collection_ids or {}
    local ids = {}
    for collection_id in pairs(memberships) do ids[#ids + 1] = tostring(collection_id) end
    table.sort(ids)
    if entry and entry._direct_favorite == true then
        targets[#targets + 1] = {id = nil, node = nil}
    end
    for _, id in ipairs(ids) do
        targets[#targets + 1] = {
            id = id, node = collection_nodes and collection_nodes[id] or nil
        }
    end
    return targets
end

function GetFavoritePersistenceCollectionIds(entry)
    local ids = {"-1"}
    for collection_id in pairs(entry and entry.collection_ids or {}) do
        ids[#ids + 1] = tostring(collection_id)
    end
    table.sort(ids, function(a, b)
        if a == "-1" then return true end
        if b == "-1" then return false end
        return a < b
    end)
    return ids
end


local function LoadClassificationOverrides()
    if not FileExists(GetCanonicalDatabasePath()) then return false end
    local output = QueryDatabaseScalarAtPath(
        GetCanonicalDatabasePath(),
        "SELECT scope_type||'|'||hex(path_norm)||'|'||classification "
            .. "FROM classification_overrides ORDER BY scope_type,path_norm;")
    local loaded = false
    for line in tostring(output or ""):gmatch("[^\r\n]+") do
        local scope, path_hex, classification =
            line:match("^(%a+)|([%x]+)|([%w%-]+)$")
        local path = DecodeSQLHex(path_hex)
        if scope and path ~= "" and classification then
            state.classification_overrides[
                scope .. "|" .. NormalizeFavoritePath(path)] = classification
            loaded = true
        end
    end
    return loaded
end

function LoadKeyOverrides()
    state.key_overrides = {}
    if not FileExists(GetCanonicalDatabasePath()) then return false end
    local output = QueryDatabaseScalarAtPath(
        GetCanonicalDatabasePath(),
        "SELECT hex(path_norm)||'|'||COALESCE(CAST(key_pc AS TEXT),'U')||"
            .. "'|'||COALESCE(CAST(detected_key_pc AS TEXT),'U') "
            .. "FROM key_overrides ORDER BY path_norm;")
    local loaded = false
    for line in tostring(output or ""):gmatch("[^\r\n]+") do
        local path_hex, key_text, detected_text =
            line:match("^([%x]+)|([U%d]+)|([U%d]+)$")
        local path = DecodeSQLHex(path_hex)
        if path ~= "" and key_text then
            state.key_overrides[NormalizeFavoritePath(path)] = {
                key_pc = key_text == "U" and false or tonumber(key_text),
                detected_key_pc = detected_text == "U"
                    and false or tonumber(detected_text),
            }
            loaded = true
        end
    end
    return loaded
end

function SaveFavorites(queue_snapshot)
    -- Favorites are SQLite-authoritative.  This compatibility entry point is
    -- intentionally a no-op so legacy callers cannot recreate a TSV mirror.
    -- Individual mutations queue their bounded SQL transaction directly.
    return true
end

function PruneMissingFavoritesAfterScan()
    local sync = state.canonical_scan_sync
    local scanned_roots = sync.scanned_root_keys or {}
    local scanned_folders = sync.scanned_folder_keys or {}
    local scanned_files = sync.scanned_favorite_file_keys or {}
    if next(scanned_roots) == nil then return 0, false end

    local protected_roots = {}
    for _, configured_path in ipairs(state.root_folders or {}) do
        local configured_key = NormalizeFavoritePath(configured_path)
        if not scanned_roots[configured_key] then
            for scanned_key in pairs(scanned_roots) do
                if configured_key:sub(1, #scanned_key + 1)
                    == scanned_key .. "/" then
                    protected_roots[#protected_roots + 1] = configured_key
                    break
                end
            end
        end
    end

    local function IsInUpdatedScope(path_key)
        for scanned_key in pairs(scanned_roots) do
            if path_key == scanned_key
                or path_key:sub(1, #scanned_key + 1) == scanned_key .. "/" then
                for _, protected_key in ipairs(protected_roots) do
                    if path_key == protected_key
                        or path_key:sub(1, #protected_key + 1)
                            == protected_key .. "/" then
                        return false
                    end
                end
                return true
            end
        end
        return false
    end

    local original_favorites = state.favorites
    local kept = {}
    local removed = 0
    for _, entry in ipairs(original_favorites) do
        local missing = false
        if entry and (entry.kind == "folder" or entry.kind == "file") then
            local path_key = NormalizeFavoritePath(entry.path)
            local exists = entry.kind == "folder"
                and scanned_folders[path_key]
                or scanned_files[path_key]
            if IsInUpdatedScope(path_key) and not exists then
                missing = true
            end
        end
        if missing then
            removed = removed + 1
        else
            kept[#kept + 1] = entry
        end
    end
    if removed == 0 then return 0, false end
    state.favorites = kept
    state.favorite_index_dirty = true
    if (not state.database_startup_test.enabled
        or QueueCanonicalPruneMissingFavorites()) then
        RefreshFavoritesView()
        InvalidateCanonicalFavoriteViews()
        return removed, true
    end
    state.favorites = original_favorites
    return 0, false
end

function FindFavoriteIndex(path)
    EnsureFavoriteIndex()
    local key = NormalizeFavoritePath(path)
    local index = state.favorite_index[key]
    if index then return index end
    if state.database_startup_test.enabled
        and not state.favorite_lookup_miss[key] then
        local entry = LoadCanonicalFavoriteEntry(path)
        if entry then return state.favorite_index[key] end
    end
    return nil
end

function IsFavorite(path)
    return FindFavoriteIndex(path) ~= nil
end

function BuildFavoriteTree(collections_only, defer_folder_lookup)
    -- A canonical database is the authoritative source for Favorites. Never
    -- fall back to the legacy recursive ScanFolder path here: opening or
    -- refreshing a large favorited folder would otherwise walk every file on
    -- the UI thread before the paged SQL browser gets a chance to render.
    if state.database.canonical then
        collections_only = true
        defer_folder_lookup = true
    end
    state.favorite_tree_dirty = false
    state.favorite_tree = {}
    local collection_nodes = {}
    for _, folder in ipairs(state.favorite_collections) do
        collection_nodes[folder.id] = {
            name = folder.name, name_lower = folder.name:lower(),
            path = "__fav_collection__" .. folder.id, collection_id = folder.id,
            is_collection = true, is_folder = true, children = {}, files = {},
            depth = 0, parent = nil,
            _canonical_loaded = false,
            _canonical_loading = false,
            _canonical_has_more = false,
            _canonical_offset = 0,
        }
    end
    for _, folder in ipairs(state.favorite_collections) do
        local node = collection_nodes[folder.id]
        local parent = folder.parent_id and collection_nodes[folder.parent_id] or nil
        if parent then
            node.parent = parent
            parent.children[#parent.children + 1] = node
        else
            state.favorite_tree[#state.favorite_tree + 1] = node
        end
    end
    local function AssignFavoriteCollectionDepth(nodes, depth, parent)
        for _, node in ipairs(nodes or {}) do
            node.depth = depth
            node.parent = parent
            AssignFavoriteCollectionDepth(node.children, depth + 1, node)
        end
    end
    AssignFavoriteCollectionDepth(state.favorite_tree, 0, nil)
    local function SortFavoriteFolderNodes(nodes)
        table.sort(nodes, function(a, b)
            return (a.name_lower or a.name:lower())
                < (b.name_lower or b.name:lower())
        end)
        for _, node in ipairs(nodes) do
            SortFavoriteFolderNodes(node.children or {})
        end
    end
    if collections_only then
        -- Loose root favorites are kept in a hidden container so the renderer
        -- can show them directly after custom and favorited media folders in
        -- the current Favorites Library hierarchy.
        local favorite_files = {
            name = "Root Favorites", name_lower = "root favorites",
            path = "__favorite_files__", is_folder = true,
            children = {}, files = {}, depth = 0, parent = nil,
            is_favorite_root_files = true,
            _canonical_started = false,
            _canonical_loaded = false,
            _canonical_loading = false,
            _canonical_has_more = false,
            _canonical_offset = 0,
        }
        local favorite_folder_ids = {}
        local folder_paths = {}
        for _, entry in ipairs(state.favorites or {}) do
            if (entry.kind or "file") == "folder" then
                local path_key = CacheFavoriteEntryIdentity(entry)
                folder_paths[#folder_paths + 1] =
                    SQLQuote(path_key)
            end
        end
        if not defer_folder_lookup and #folder_paths > 0
            and FileExists(GetCanonicalDatabasePath()) then
            local rows = QueryDatabaseScalarAtPath(
                GetCanonicalDatabasePath(),
                "WITH requested(path_norm) AS (VALUES ("
                    .. table.concat(folder_paths, "),(")
                    .. ")),resolved(path_norm,root_id) AS MATERIALIZED (SELECT "
                    .. "requested.path_norm,(SELECT roots.id FROM roots WHERE "
                    .. "requested.path_norm=roots.path_norm OR substr("
                    .. "requested.path_norm,1,length(roots.path_norm)+1)="
                    .. "roots.path_norm||'/' ORDER BY length(roots.path_norm) "
                    .. "DESC LIMIT 1) FROM requested) SELECT "
                    .. "folders.id||char(9)||hex("
                    .. "roots.display_path||CASE WHEN "
                    .. "folders.relative_path='' THEN '' ELSE '/'||"
                    .. "folders.relative_path END) FROM resolved "
                    .. "JOIN roots ON roots.id=resolved.root_id JOIN folders ON "
                    .. "folders.root_id=resolved.root_id AND "
                    .. "folders.relative_path_norm=CASE WHEN "
                    .. "resolved.path_norm=roots.path_norm THEN '' ELSE substr("
                    .. "resolved.path_norm,length(roots.path_norm)+2) END "
                    .. "AND folders.missing=0;")
            for line in tostring(rows or ""):gmatch("[^\r\n]+") do
                local folder_id, path_hex = line:match("^(%d+)\t(%x+)$")
                if folder_id and path_hex then
                    local decoded = path_hex:gsub("%x%x", function(pair)
                        return string.char(tonumber(pair, 16))
                    end)
                    favorite_folder_ids[NormalizeFavoritePath(decoded)] =
                        tonumber(folder_id)
                end
            end
        end
        local loaded_folders_by_path = {}
        local function IndexLoadedFolders(nodes)
            for _, candidate in ipairs(nodes or {}) do
                loaded_folders_by_path[
                    NormalizeFavoritePath(candidate.path)] = candidate
                IndexLoadedFolders(candidate.children)
            end
        end
        IndexLoadedFolders(state.folder_tree)
        local favorite_entries = {}
        for index, entry in ipairs(state.favorites or {}) do
            favorite_entries[index] = entry
        end
        if state.favorite_sort == "az" then
            table.sort(favorite_entries, function(a, b)
                return select(3, CacheFavoriteEntryIdentity(a))
                    < select(3, CacheFavoriteEntryIdentity(b))
            end)
        elseif state.favorite_sort == "za" then
            table.sort(favorite_entries, function(a, b)
                return select(3, CacheFavoriteEntryIdentity(a))
                    > select(3, CacheFavoriteEntryIdentity(b))
            end)
        elseif state.favorite_sort == "newest" then
            table.sort(favorite_entries, function(a, b)
                return (a.added or 0) > (b.added or 0)
            end)
        end
        for _, entry in ipairs(favorite_entries) do
            local entry_path_key, entry_name, entry_name_lower =
                CacheFavoriteEntryIdentity(entry)
            if (entry.kind or "file") ~= "folder"
                and entry._direct_favorite == true then
                favorite_files.files[#favorite_files.files + 1] = {
                    name = entry_name,
                    name_lower = entry_name_lower,
                    path = entry.path,
                    is_folder = false,
                    parent = favorite_files,
                }
            end
            local targets = GetFavoriteEntryTargets(entry, collection_nodes)
            for _, target_info in ipairs(targets) do
                -- Canonical custom collections are populated only when opened,
                -- through the same 100-row/600-retained paging path as physical
                -- folders. Hydrating their explicit rows here would briefly
                -- render the entire collection and defeat clipping at scale.
                if not (state.database_startup_test.enabled
                    and target_info.id ~= nil) then
                    local target = target_info.node
                    if (entry.kind or "file") == "folder" then
                        local loaded = loaded_folders_by_path[entry_path_key]
                        -- The persisted folder ID identifies the exact instance
                        -- selected under overlapping roots. A path lookup can
                        -- resolve the same text to the configured top-level root
                        -- and must never replace that saved instance.
                        local folder_id = entry._canonical_folder_id
                            or favorite_folder_ids[entry_path_key]
                            or (loaded and loaded._canonical_folder_id)
                        local node = {
                            name = entry_name,
                            name_lower = entry_name_lower,
                            path = entry.path,
                            is_folder = true,
                            children = {},
                            files = {},
                            depth = target and ((target.depth or 0) + 1) or 0,
                            parent = target,
                            collection_id = target_info.id,
                            -- A folder shown in Favorites is a favoriteable media
                            -- folder even when its path is also configured as a
                            -- Library root. Only Library rows can be root rows.
                            _canonical_is_library_root = false,
                            _favorite_root_membership = target_info.id == nil,
                            _canonical_folder_id = folder_id,
                            _canonical_loaded = folder_id == nil
                                and not state.database_startup_test.enabled,
                            _canonical_loading = false,
                        }
                        if target then
                            target.children[#target.children + 1] = node
                        else
                            state.favorite_tree[#state.favorite_tree + 1] = node
                        end
                    else
                        if target then
                            target.files[#target.files + 1] = {
                                name = entry_name,
                                name_lower = entry_name_lower,
                                path = entry.path,
                                is_folder = false,
                                parent = target,
                                collection_id = target_info.id,
                            }
                        end
                    end
                end
            end
        end
        SortFavoriteFolderNodes(state.favorite_tree)
        state.favorite_tree[#state.favorite_tree + 1] = favorite_files
        return
    end
    local loose_files = {
        name = "Root Favorites", name_lower = "root favorites",
        path = "__favorite_files__", is_folder = true,
        children = {}, files = {}, depth = 0, parent = nil
    }
    local entries = {}
    for i, entry in ipairs(state.favorites) do
        entries[i] = entry
    end
    if state.favorite_sort == "az" then
        table.sort(entries, function(a, b)
            return select(3, CacheFavoriteEntryIdentity(a))
                < select(3, CacheFavoriteEntryIdentity(b))
        end)
    elseif state.favorite_sort == "za" then
        table.sort(entries, function(a, b)
            return select(3, CacheFavoriteEntryIdentity(a))
                > select(3, CacheFavoriteEntryIdentity(b))
        end)
    elseif state.favorite_sort == "newest" then
        table.sort(entries, function(a, b) return (a.added or 0) > (b.added or 0) end)
    end
    for _, entry in ipairs(entries) do
        local _, entry_name, entry_name_lower =
            CacheFavoriteEntryIdentity(entry)
        local targets = GetFavoriteEntryTargets(entry, collection_nodes)
        for _, target_info in ipairs(targets) do
            local target = target_info.node
            if entry.kind == "folder" then
                local tree = ScanFolder(entry.path, 0, nil)
                if tree then
                    tree.collection_id = target_info.id
                    if target then
                        tree.parent = target
                        target.children[#target.children + 1] = tree
                    else
                        state.favorite_tree[#state.favorite_tree + 1] = tree
                    end
                end
            else
                local parent = target or loose_files
                parent.files[#parent.files + 1] = {
                    name = entry_name, name_lower = entry_name_lower,
                    path = entry.path,
                    is_folder = false, parent = parent,
                    collection_id = target_info.id
                }
            end
        end
    end
    SortFavoriteFolderNodes(state.favorite_tree)
    if #loose_files.files > 0 then
        state.favorite_tree[#state.favorite_tree + 1] = loose_files
    end
end

local function RefreshFavoriteRootFilesInPlace(paths)
    if not state.favorites_mode then return end
    local tree = state.favorite_tree or {}
    local root_files
    for _, node in ipairs(tree) do
        if node.path == "__favorite_files__" then
            root_files = node
            break
        end
    end
    if not root_files then
        root_files = {
            name = "Root Favorites", name_lower = "root favorites",
            path = "__favorite_files__", is_folder = true,
            children = {}, files = {}, depth = 0, parent = nil,
            is_favorite_root_files = true,
            _canonical_started = false,
            _canonical_loaded = false,
            _canonical_loading = false,
            _canonical_has_more = false,
            _canonical_offset = 0,
        }
        tree[#tree + 1] = root_files
    end
    local affected = {}
    for _, path in ipairs(paths or {}) do
        affected[NormalizeFavoritePath(path)] = true
    end
    local kept = {}
    for _, file in ipairs(root_files.files or {}) do
        if not affected[NormalizeFavoritePath(file.path)] then
            kept[#kept + 1] = file
        end
    end
    root_files.files = kept
    local kept_roots = {}
    for _, node in ipairs(tree) do
        local remove_root_folder = node ~= root_files
            and not node.parent and not node.is_collection
            and not node.is_favorite_root_files
            and affected[NormalizeFavoritePath(node.path or "")]
        if not remove_root_folder then kept_roots[#kept_roots + 1] = node end
    end
    tree = kept_roots
    for key in pairs(affected) do
        local index = state.favorite_index[key]
        local entry = index and state.favorites[index] or nil
        if entry and (entry.kind or "file") == "file"
            and entry._direct_favorite == true then
            local _, name, name_lower = CacheFavoriteEntryIdentity(entry)
            local row = {
                name = name, name_lower = name_lower,
                path = entry.path, is_folder = false,
                parent = root_files, _canonical_favorite = true,
                _favorite_added = entry.added or 0,
            }
            if state.favorite_sort == "newest" then
                table.insert(root_files.files, 1, row)
            else
                root_files.files[#root_files.files + 1] = row
            end
        elseif entry and entry.kind == "folder"
            and entry._direct_favorite == true then
            local _, name, name_lower = CacheFavoriteEntryIdentity(entry)
            tree[#tree + 1] = {
                name = name, name_lower = name_lower,
                path = entry.path, is_folder = true,
                children = {}, files = {}, depth = 0, parent = nil,
                _canonical_folder_id = entry._canonical_folder_id,
                _canonical_loaded = false,
                _canonical_loading = false,
                _canonical_started = false,
                _canonical_has_more = false,
                _canonical_offset = 0,
            }
        end
    end
    if state.favorite_sort == "az" or state.favorite_sort == "za" then
        table.sort(root_files.files, function(left, right)
            local left_name = left.name_lower or (left.name or ""):lower()
            local right_name = right.name_lower or (right.name or ""):lower()
            return state.favorite_sort == "za"
                and left_name > right_name or left_name < right_name
        end)
    end
    while #root_files.files > RB_MAX_CANONICAL_ACCORDION_ROWS do
        if (root_files._canonical_window_start_offset or 0) > 0 then
            table.remove(root_files.files, 1)
            root_files._canonical_window_start_offset =
                (root_files._canonical_window_start_offset or 0) + 1
        else
            table.remove(root_files.files)
        end
    end
    -- Keep the navigation badge synchronized with the in-place root update;
    -- otherwise it can continue using the old paged count after a removal.
    root_files._canonical_loaded_file_count = #root_files.files
    root_files._canonical_file_last_page_offset =
        root_files._canonical_window_start_offset or 0
    local loose_root
    local sortable_roots = {}
    for _, node in ipairs(tree) do
        if node.is_favorite_root_files then
            loose_root = node
        else
            sortable_roots[#sortable_roots + 1] = node
        end
    end
    table.sort(sortable_roots, function(left, right)
        return (left.name_lower or (left.name or ""):lower())
            < (right.name_lower or (right.name or ""):lower())
    end)
    tree = sortable_roots
    if loose_root then tree[#tree + 1] = loose_root end
    state.favorite_tree = tree
    state.folder_clippers.__favorite_root_files = nil
    state.favorite_tree_dirty = false
    state.needs_visible_update = true
end

function RefreshFavoriteMembershipRows(paths, collection_ids, fallback_kind)
    state.media_favorite_generation =
        (state.media_favorite_generation or 0) + 1
    state.favorite_lookup_miss = {}
    EnsureFavoriteIndex()
    for _, path in ipairs(paths or {}) do
        local key = NormalizeFavoritePath(path)
        local index = state.favorite_index[key]
        local entry = index and state.favorites[index] or nil
        state.favorite_membership_cache[key] =
            FavoriteEntryHasAnyMembership(entry)
    end

    local affected_paths = {}
    for _, path in ipairs(paths or {}) do
        affected_paths[NormalizeFavoritePath(path)] = path
    end
    local affected_collections = {}
    for collection_id in pairs(collection_ids or {}) do
        affected_collections[tostring(collection_id)] = true
    end

    local function SortCollectionRows(node)
        table.sort(node.children or {}, function(left, right)
            local left_name = (left.name_lower or left.name or ""):lower()
            local right_name = (right.name_lower or right.name or ""):lower()
            if left_name == right_name then
                return tostring(left.path or "") < tostring(right.path or "")
            end
            return left_name < right_name
        end)
        table.sort(node.files or {}, function(left, right)
            if state.favorite_sort == "za" then
                return (left.name_lower or left.name:lower())
                    > (right.name_lower or right.name:lower())
            elseif state.favorite_sort == "newest" then
                return (left._favorite_added or 0)
                    > (right._favorite_added or 0)
            elseif state.favorite_sort == "added" then
                return (left._favorite_added or 0)
                    < (right._favorite_added or 0)
            end
            return (left.name_lower or left.name:lower())
                < (right.name_lower or right.name:lower())
        end)
        local physical_children = 0
        for _, child in ipairs(node.children or {}) do
            if not child.is_collection then
                physical_children = physical_children + 1
            end
        end
        while physical_children + #(node.files or {})
            > RB_MAX_CANONICAL_ACCORDION_ROWS do
            if #node.files > 0 then
                table.remove(node.files)
            else
                for index = #node.children, 1, -1 do
                    if not node.children[index].is_collection then
                        table.remove(node.children, index)
                        physical_children = physical_children - 1
                        break
                    end
                end
            end
        end
    end

    local function PatchCollectionNodes(nodes)
        for _, node in ipairs(nodes or {}) do
            if node.is_collection
                and affected_collections[tostring(node.collection_id)] then
                local kept_files = {}
                for _, file in ipairs(node.files or {}) do
                    if not affected_paths[NormalizeFavoritePath(file.path)] then
                        kept_files[#kept_files + 1] = file
                    end
                end
                node.files = kept_files
                local kept_children = {}
                for _, child in ipairs(node.children or {}) do
                    if child.is_collection
                        or not affected_paths[
                            NormalizeFavoritePath(child.path)] then
                        kept_children[#kept_children + 1] = child
                    end
                end
                node.children = kept_children
                for key, path in pairs(affected_paths) do
                    local index = state.favorite_index[key]
                    local entry = index and state.favorites[index] or nil
                    if entry and FavoriteEntryHasCollection(
                        entry, node.collection_id) then
                        local _, name, name_lower =
                            CacheFavoriteEntryIdentity(entry)
                        if (entry.kind or fallback_kind or "file") == "folder" then
                            node.children[#node.children + 1] = {
                                name = name, name_lower = name_lower,
                                path = entry.path, is_folder = true,
                                children = {}, files = {}, parent = node,
                                depth = (node.depth or 0) + 1,
                                collection_id = node.collection_id,
                                _favorite_collection_id = node.collection_id,
                                _canonical_folder_id = entry._canonical_folder_id,
                                _canonical_loaded = false,
                                _canonical_loading = false,
                            }
                        else
                            node.files[#node.files + 1] = {
                                name = name, name_lower = name_lower,
                                path = entry.path, is_folder = false,
                                parent = node,
                                collection_id = node.collection_id,
                                _favorite_collection_id = node.collection_id,
                                _canonical_favorite = true,
                                _favorite_added = entry.added or 0,
                            }
                        end
                    end
                end
                SortCollectionRows(node)
                node._canonical_loaded_file_count = #node.files
                state.folder_clippers[node.path] = nil
            end
            PatchCollectionNodes(node.children)
        end
    end

    if state.favorites_mode then
        RefreshFavoriteRootFilesInPlace(paths)
        if next(affected_collections) ~= nil then
            PatchCollectionNodes(state.favorite_tree)
        end
    else
        state.favorite_tree_dirty = true
    end
    state.force_search_update = true
    state.needs_visible_update = true
end

function RefreshFavoritesView()
    state.media_favorite_generation =
        (state.media_favorite_generation or 0) + 1
    state.favorite_lookup_miss = {}
    state.favorite_membership_cache = {}
    state.favorite_membership_pending_paths = {}
    state.favorite_membership_inflight_paths = {}
    state.favorite_membership_next_at = 0
    state.favorite_membership_query_pending = false
    state.favorite_folder_id_cache = {}
    local valid_collection_ids = {}
    for _, folder in ipairs(state.favorite_collections or {}) do
        valid_collection_ids[tostring(folder.id)] = true
    end
    for collection_id in pairs(
        state.favorite_collection_drop_rects or {}) do
        if not valid_collection_ids[tostring(collection_id)] then
            state.favorite_collection_drop_rects[collection_id] = nil
        end
    end
    EnsureFavoriteIndex()
    -- Do not synchronously resolve every favorite folder during a heart
    -- toggle.  Folder IDs are resolved on demand when a favorite folder is
    -- actually opened.
    if state.favorites_mode then
        BuildFavoriteTree(state.database_startup_test.enabled,
            state.database_startup_test.enabled)
    else
        state.favorite_tree_dirty = true
    end
    state.random_candidates = {}
    state.random_candidates_key = nil
    -- Favorite membership is an indexed path lookup while drawing visible
    -- rows. Do not recursively walk the entire loaded Library after a toggle.
    state.force_search_update = true
    state.needs_visible_update = true
end

local function RefreshFavoriteMembershipPreservingTree(paths)
    state.media_favorite_generation =
        (state.media_favorite_generation or 0) + 1
    state.favorite_lookup_miss = {}
    EnsureFavoriteIndex()
    state.force_search_update = true
    state.needs_visible_update = true
    -- Keep the currently open physical folder intact. Rebuild the root list
    -- in place so direct favorites appear immediately above the folders.
    RefreshFavoriteRootFilesInPlace(paths)
end

function IsRootLibraryFolder(path)
    local key = NormalizeFavoritePath(path)
    for _, root in ipairs(state.root_folders) do
        if NormalizeFavoritePath(root) == key then return true end
    end
    -- Canonical root pages are authoritative for the currently displayed
    -- Library. Keep context-menu/root actions aligned with the same root
    -- identity used by the renderer when a configured display path differs
    -- only in representation from the stored root path.
    for _, node in ipairs(state.folder_tree or {}) do
        if node._canonical_is_library_root
            and NormalizeFavoritePath(node.path) == key then
            return true
        end
    end
    return false
end

function IsRootLibraryFolderNode(node)
    if not node or not node.is_folder then return false end
    -- Canonical rows carry their instance identity. This matters for
    -- overlapping roots: the same physical path can be a protected top-level
    -- root in one place and a normal, favoriteable child folder in another.
    if node._canonical_is_library_root ~= nil then
        return node._canonical_is_library_root == true
    end
    return node.parent == nil and IsRootLibraryFolder(node.path)
end

function IsCanonicalLibraryRootFolderId(folder_id)
    folder_id = tonumber(folder_id)
    if not folder_id then return false end
    for _, node in ipairs(state.folder_tree or {}) do
        if node._canonical_is_library_root == true
            and tonumber(node._canonical_folder_id) == folder_id then
            return true
        end
    end
    return false
end

function RootLibraryActionsBlocked()
    return not state.database.canonical
        or state.database.backend ~= "sqlite"
        or state.library_scan.scanning
        or state.database.scan_active
        or state.canonical_scan_sync.importing
end

function RequestRootLibraryRemoval(path)
    if not IsRootLibraryFolder(path) or RootLibraryActionsBlocked() then
        return false
    end
    state.pending_root_removal = path
    state.root_removal_popup_requested = true
    return true
end

function DrawRootLibraryRemovalConfirmation()
    if state.root_removal_popup_requested then
        state.root_removal_popup_requested = false
        imgui.OpenPopup(ctx, "Remove Library Folder?")
    end
    if not imgui.BeginPopupModal(ctx, "Remove Library Folder?", nil) then
        return
    end
    local path = state.pending_root_removal
    imgui.Text(ctx, "Remove this folder from ReaBrowse?")
    imgui.TextDisabled(ctx, tostring(path or ""))
    imgui.Spacing(ctx)
    imgui.TextDisabled(ctx,
        "Orphaned Favorites, user tags, notes, usage, and manual overrides "
            .. "will be removed.\nData still reachable through another configured "
            .. "root is preserved. Source media is never deleted.")
    imgui.Spacing(ctx)
    local blocked = RootLibraryActionsBlocked()
    if blocked and imgui.BeginDisabled then imgui.BeginDisabled(ctx, true) end
    if imgui.Button(ctx, "Remove Folder", 130, 0) and path then
        if RemoveRootLibraryFolder(path) then
            state.pending_root_removal = nil
            imgui.CloseCurrentPopup(ctx)
        end
    end
    if blocked and imgui.EndDisabled then imgui.EndDisabled(ctx) end
    imgui.SameLine(ctx)
    if imgui.Button(ctx, "Cancel", 90, 0) then
        state.pending_root_removal = nil
        imgui.CloseCurrentPopup(ctx)
    end
    imgui.EndPopup(ctx)
end

function RemoveRootLibraryFolder(path)
    local key = NormalizeFavoritePath(path)
    local surviving_child_keys = {}
    for _, root_path in ipairs(state.root_folders or {}) do
        local root_key = NormalizeFavoritePath(root_path)
        if root_key ~= key
            and root_key:sub(1, #key + 1) == key .. "/" then
            surviving_child_keys[#surviving_child_keys + 1] = root_key
        end
    end
    local function IsInsideRoot(candidate)
        local normalized = NormalizeFavoritePath(candidate)
        local inside = normalized == key
            or normalized:sub(1, #key + 1) == key .. "/"
        if not inside then return false end
        -- Removing an organizational parent must not remove user data or UI
        -- state owned by separately configured child roots beneath it.
        for _, child_key in ipairs(surviving_child_keys) do
            if normalized == child_key
                or normalized:sub(1, #child_key + 1) == child_key .. "/" then
                return false
            end
        end
        return true
    end
    local removed = false
    for index = #state.root_folders, 1, -1 do
        if NormalizeFavoritePath(state.root_folders[index]) == key then
            table.remove(state.root_folders, index)
            removed = true
        end
    end
    if not removed then return false end

    -- Favorites are references into the active Library, not independent file
    -- copies. Removing a root must therefore remove every favorite below it;
    -- keeping those entries created dead rows that could never resolve to a
    -- canonical folder or file again.
    local favorites_removed = false
    for index = #state.favorites, 1, -1 do
        local entry = state.favorites[index]
        if entry and IsInsideRoot(entry.path) then
            table.remove(state.favorites, index)
            state.favorite_index_dirty = true
            favorites_removed = true
        end
    end

    local tags_removed = false
    for tag_path in pairs(state.media_user_tags or {}) do
        if IsInsideRoot(tag_path) then
            state.media_user_tags[tag_path] = nil
            tags_removed = true
        end
    end
    for override_key in pairs(state.classification_overrides or {}) do
        local _, override_path = override_key:match("^(%a+)|(.+)$")
        if override_path and IsInsideRoot(override_path) then
            state.classification_overrides[override_key] = nil
        end
    end
    for override_path in pairs(state.key_overrides or {}) do
        if IsInsideRoot(override_path) then
            state.key_overrides[override_path] = nil
        end
    end
    state.key_override_generation =
        (state.key_override_generation or 0) + 1
    if tags_removed then SaveMediaUserTags() end

    local scan = state.library_scan
    if scan.scanning then
        local filtered, next_index = {}, 1
        for index, node in ipairs(scan.queue) do
            if not IsInsideRoot(node.path) then
                filtered[#filtered + 1] = node
                if index < scan.queue_index then
                    next_index = next_index + 1
                end
            end
        end
        scan.queue = filtered
        scan.queue_index = math.min(next_index, #filtered + 1)
        if scan.current and IsInsideRoot(scan.current.path) then
            scan.current = nil
        end
        for index = #scan.roots, 1, -1 do
            if IsInsideRoot(scan.roots[index].path) then
                table.remove(scan.roots, index)
            end
        end
    end

    for index = #state.folder_tree, 1, -1 do
        if NormalizeFavoritePath(state.folder_tree[index].path) == key then
            table.remove(state.folder_tree, index)
        end
    end
    -- A removed root invalidates every accordion node and cached page beneath
    -- it. Clear the whole navigation surface rather than leaving old folder
    -- IDs or deferred targets attached to a tree that no longer exists.
    state.open_folders = {}
    state.favorite_open_folders = state.favorite_open_folders or {}
    for open_path in pairs(state.favorite_open_folders) do
        if IsInsideRoot(open_path) then
            state.favorite_open_folders[open_path] = nil
        end
    end
    local browser = state.canonical_browser
    browser.cache = {}
    browser.cache_order = {}
    ClearCanonicalTagCatalogCache()
    browser.pending_prefetch = nil
    browser.pending_tag_folder_id = nil
    browser.pending_tag_time = nil
    browser.deferred_request = nil
    browser.accordion_error = nil
    browser.error = nil
    -- Root removal invalidates the legacy Lua-derived facet builder when its
    -- active scope was removed. Leaving that stack alive lets it keep walking
    -- the replacement tree after a root is re-added, which looks like every
    -- folder is rescanning tags. Preserve a valid scope from another root.
    local facet_scope_removed = state.selected_folder_scope
        and IsInsideRoot(state.selected_folder_scope)
    local pending_facet_removed = state.pending_tag_facet_node
        and IsInsideRoot(state.pending_tag_facet_node.path)
    if facet_scope_removed or pending_facet_removed then
        state.pending_tag_facet_node = nil
        state.pending_tag_facet_time = nil
        state.media_tag_facets = {
            building = false,
            scope = nil,
            stack = {},
            counts = {},
            files = {},
            by_tag = {},
            by_class = {
                ["loop"] = {}, ["one-shot"] = {},
                ["midi"] = {}, ["other"] = {},
            },
            processed = 0,
        }
        state.media_tag_bar.cache_key = nil
        state.media_tag_bar.tags = {}
        state.media_tag_bar.scope_catalog_key = nil
        state.media_tag_bar.catalog_complete = false
    end
    state.media_filter_index.ready = false
    state.media_filter_index.building = false
    state.media_filter_index.stack = {}
    state.media_filter_index.files = {}
    state.media_filter_index.by_tag = {}
    state.media_filter_index.by_class = {
        ["loop"] = {}, ["one-shot"] = {},
        ["midi"] = {}, ["other"] = {},
    }
    state.media_filter_index.seen_paths = {}
    state.media_filter_index.indexed_count = 0
    state.media_filter_index.requested = false
    if browser.current_path and IsInsideRoot(browser.current_path) then
        browser.current_folder_id = nil
        browser.current_name = "Library"
        browser.current_path = nil
        browser.history = {}
        browser.rows = {}
        browser.offset = 0
        browser.selected_path = nil
    end
    if state.selected_folder_scope
        and IsInsideRoot(state.selected_folder_scope) then
        state.selected_folder_scope = nil
    end
    if state.cursor_path and IsInsideRoot(state.cursor_path) then
        state.cursor_path = nil
        state.cursor_type = nil
    end
    for selected_path in pairs(state.multi_selected or {}) do
        if IsInsideRoot(selected_path) then
            state.multi_selected[selected_path] = nil
        end
    end

    if favorites_removed then
        -- Rebuild the visible smart-library tree after the database removed
        -- the root and its dependent favorite memberships.
        RefreshFavoritesView()
        InvalidateCanonicalFavoriteViews()
    end

    SaveSettings()
    if not state.database.canonical then
        SaveLibraryCache()
    end
    state.force_search_update = true
    state.needs_visible_update = true

    if state.database.backend == "sqlite" and not state.database.canonical then
        local prefix = key:gsub("([%%_])", "\\%1")
        local sql = "BEGIN IMMEDIATE;\n"
            .. "UPDATE media_files SET missing=1 WHERE path_norm="
            .. SQLQuote(key) .. " OR path_norm LIKE "
            .. SQLQuote(prefix .. "/%") .. " ESCAPE '\\';\n"
            .. "DELETE FROM media_files WHERE missing=1;\n"
            .. "COMMIT;\n"
        local ok, err = WriteDatabaseBatch(sql)
        if not ok then DisableMediaDatabase(err) end
    end
    if state.database_startup_test.enabled
        and FileExists(GetCanonicalDatabasePath()) then
        local now = os.time()
        local override_scope_sql = "(path_norm=" .. SQLQuote(key)
            .. " OR (substr(path_norm,1," .. tostring(#key) .. ")="
            .. SQLQuote(key) .. " AND substr(path_norm,"
            .. tostring(#key + 1) .. ",1)='/'))"
        for _, child_key in ipairs(surviving_child_keys) do
            override_scope_sql = override_scope_sql
                .. " AND NOT (path_norm=" .. SQLQuote(child_key)
                .. " OR (substr(path_norm,1," .. tostring(#child_key) .. ")="
                .. SQLQuote(child_key) .. " AND substr(path_norm,"
                .. tostring(#child_key + 1) .. ",1)='/'))"
        end
        local canonical_sql =
            -- Capture only canonical files reachable through the root being
            -- removed. Every subsequent orphan decision is bounded by this
            -- set rather than scanning the complete library.
            "DROP TABLE IF EXISTS remove_root_files;\n"
            .. "DROP TABLE IF EXISTS remove_root_effective_tags;\n"
            .. "DROP TABLE IF EXISTS remove_root_stats;\n"
            .. "CREATE TEMP TABLE remove_root_files(file_id INTEGER PRIMARY KEY) "
            .. "WITHOUT ROWID;\n"
            .. "INSERT OR IGNORE INTO remove_root_files SELECT file_id FROM "
            .. "folder_files WHERE root_id IN(SELECT id FROM roots WHERE "
            .. "path_norm=" .. SQLQuote(key) .. ");\n"
            .. "UPDATE roots SET enabled=0,last_checked_at="
            .. tostring(now) .. " WHERE path_norm=" .. SQLQuote(key) .. ";\n"
            .. "UPDATE folder_files SET missing=1 WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm="
            .. SQLQuote(key) .. ");\n"
            .. "UPDATE folders SET missing=1 WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm="
            .. SQLQuote(key) .. ");\n"
            .. "UPDATE files SET missing=CASE WHEN EXISTS("
            .. "SELECT 1 FROM folder_files WHERE "
            .. "folder_files.file_id=files.id "
            .. "AND folder_files.missing=0) THEN 0 ELSE 1 END WHERE id IN"
            .. "(SELECT file_id FROM remove_root_files);\n"
            -- Capture effective tag contributions before file deletion. A file
            -- with multiple sources for one tag contributes only once; user
            -- exclusions contribute zero, matching the catalog read model.
            .. "CREATE TEMP TABLE remove_root_effective_tags(file_id INTEGER,"
            .. "tag_id INTEGER,PRIMARY KEY(file_id,tag_id)) WITHOUT ROWID;\n"
            .. "INSERT INTO remove_root_effective_tags SELECT DISTINCT files.id,"
            .. "file_tags.tag_id FROM remove_root_files candidates JOIN files ON "
            .. "files.id=candidates.file_id JOIN file_tags ON file_tags.file_id="
            .. "files.id JOIN tags ON tags.id=file_tags.tag_id WHERE files.missing=1 "
            .. "AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions excluded WHERE "
            .. "excluded.file_id=file_tags.file_id AND excluded.tag_norm="
            .. "tags.name_norm);\n"
            .. "CREATE TEMP TABLE remove_root_stats(orphan_files INTEGER NOT NULL);\n"
            .. "INSERT INTO remove_root_stats SELECT count(*) FROM "
            .. "remove_root_files candidates JOIN files ON files.id="
            .. "candidates.file_id WHERE files.missing=1;\n"
            .. "DELETE FROM collection_items WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm=" .. SQLQuote(key) .. ") "
            .. "OR folder_id IN(SELECT id FROM folders WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm=" .. SQLQuote(key) .. ")) "
            .. "OR file_id IN(SELECT files.id FROM remove_root_files candidates "
            .. "JOIN files ON files.id=candidates.file_id WHERE files.missing=1);\n"
            .. "DELETE FROM folder_tag_counts WHERE folder_id IN"
            .. "(SELECT id FROM folders WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm=" .. SQLQuote(key) .. "));\n"
            .. "DELETE FROM classification_overrides WHERE "
            .. override_scope_sql .. ";\n"
            .. "DELETE FROM key_overrides WHERE "
            .. override_scope_sql .. ";\n"
            -- Make the root removal explicit even when a legacy database was
            -- created before all foreign-key cascades were present. The
            -- transaction still preserves files that have an active
            -- membership through another configured root.
            .. "DELETE FROM folder_files WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm=" .. SQLQuote(key)
            .. ");\n"
            .. "DELETE FROM folders WHERE root_id IN"
            .. "(SELECT id FROM roots WHERE path_norm=" .. SQLQuote(key)
            .. ");\n"
            -- Files that still belong to an overlapping active root remain
            -- missing=0. Purge only true orphans so removed roots cannot
            -- leave database, tag, favorite, or FTS debris behind.
            .. "DELETE FROM files WHERE missing=1 AND id IN"
            .. "(SELECT file_id FROM remove_root_files);\n"
            .. "DELETE FROM roots WHERE path_norm=" .. SQLQuote(key) .. ";\n"
            .. "UPDATE library_tag_counts AS counts SET file_count=max(0,"
            .. "counts.file_count-(SELECT count(*) FROM "
            .. "remove_root_effective_tags removed WHERE removed.tag_id="
            .. "counts.tag_id)) WHERE counts.tag_id IN(SELECT tag_id FROM "
            .. "remove_root_effective_tags);\n"
            .. "DELETE FROM library_tag_counts WHERE file_count<=0;\n"
            .. "DELETE FROM tags WHERE NOT EXISTS(SELECT 1 FROM file_tags "
            .. "WHERE file_tags.tag_id=tags.id);\n"
            .. "DELETE FROM app_meta WHERE key="
            .. SQLQuote("auto_tag_version:" .. key) .. ";\n"
            .. "INSERT OR REPLACE INTO app_meta(key,value) SELECT "
            .. "'library_file_count',CAST(max(0,COALESCE((SELECT CAST(value AS "
            .. "INTEGER) FROM app_meta WHERE key='library_file_count'),"
            .. "(SELECT count(*) FROM files WHERE missing=0)+(SELECT orphan_files "
            .. "FROM remove_root_stats))-(SELECT orphan_files FROM "
            .. "remove_root_stats)) AS TEXT);\n"
        local queued = QueueCanonicalUserDataSQL(
            canonical_sql, "remove_root:" .. key)
        if queued then
            BeginBlockingLibraryOperation(
                "remove", "remove", "Removing library folder",
                "Cleaning database records")
            state.database.status =
                "Root removed from Settings; cleaning its database records..."
            state.database.error = nil
            state.canonical_user_data.status =
                "Root removal queued for the database."
        else
            state.database.status =
                "Root removed from Settings; database cleanup is unavailable."
        end
    end
    return true
end

-- Build one virtual-folder facet cache only when it is actually visited.
-- The work is queued behind the existing canonical user-data lane, never
-- performed in the UI frame, and is subsequently reused across launches.
function CanonicalFolderPathPredicate(path_norm)
    local quoted = SQLQuote(path_norm)
    local root_id = "(SELECT roots.id FROM roots WHERE " .. quoted
        .. "=roots.path_norm OR substr(" .. quoted
        .. ",1,length(roots.path_norm)+1)=roots.path_norm||'/' "
        .. "ORDER BY length(roots.path_norm) DESC LIMIT 1)"
    return "folders.root_id=" .. root_id
        .. " AND folders.relative_path_norm=CASE WHEN " .. quoted
        .. "=(SELECT path_norm FROM roots WHERE id=" .. root_id
        .. ") THEN '' ELSE substr(" .. quoted
        .. ",length((SELECT path_norm FROM roots WHERE id=" .. root_id
        .. "))+2) END"
end

function CanonicalFavoriteFolderPredicate(path_norm, canonical_folder_id)
    local folder_id = tonumber(canonical_folder_id)
    if folder_id and folder_id >= 1 then
        return "folders.id=" .. tostring(math.floor(folder_id))
            .. " AND folders.missing=0"
    end
    return CanonicalFolderPathPredicate(path_norm)
end

local function BuildCanonicalFavoriteSQL(
    path, kind, favorite, canonical_folder_id)
    local path_norm = NormalizeFavoritePath(path)
    local now = os.time()
    local sql = "INSERT OR IGNORE INTO collections"
        .. "(id,parent_id,name,created_at,sort_order) "
        .. "VALUES(-1,NULL,'Favorites'," .. tostring(now) .. ",0);\n"
    if (kind or "file") == "file" then
        sql = sql
            .. "INSERT INTO user_file_data"
            .. "(file_id,favorite,play_count,updated_at) "
            .. "SELECT id," .. (favorite and "1" or "0")
            .. ",0," .. tostring(now)
            .. " FROM files WHERE canonical_path_norm="
            .. SQLQuote(path_norm)
            .. " ON CONFLICT(file_id) DO UPDATE SET favorite=excluded.favorite,"
            .. "updated_at=excluded.updated_at;\n"
        if favorite then
            sql = sql
                .. "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,file_id,added_at) SELECT -1,id,"
                .. tostring(now) .. " FROM files WHERE canonical_path_norm="
                .. SQLQuote(path_norm) .. ";\n"
        else
            sql = sql
                .. "DELETE FROM collection_items WHERE collection_id=-1 "
                .. "AND file_id=(SELECT id FROM files "
                .. "WHERE canonical_path_norm=" .. SQLQuote(path_norm) .. ");\n"
                .. "DELETE FROM user_file_data WHERE favorite=0 "
                .. "AND play_count=0 AND notes IS NULL "
                .. "AND last_used_at IS NULL AND file_id=(SELECT id FROM files "
                .. "WHERE canonical_path_norm=" .. SQLQuote(path_norm) .. ");\n"
        end
    else
        local folder_match = CanonicalFavoriteFolderPredicate(
            path_norm, canonical_folder_id)
        if favorite then
            sql = sql
                .. "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,root_id,folder_id,added_at) "
                .. "SELECT -1,folders.root_id,folders.id," .. tostring(now)
                .. " FROM folders "
                .. "WHERE " .. folder_match .. ";\n"
        else
            sql = sql
                .. "DELETE FROM collection_items WHERE collection_id=-1 "
                .. "AND folder_id IN(SELECT folders.id FROM folders WHERE "
                .. folder_match .. ");\n"
        end
    end
    return sql, path_norm
end

function BuildCanonicalFavoriteCollectionMembershipSQL(
    path, kind, collection_id, enabled, canonical_folder_id)
    if not path or not collection_id then return nil end
    local path_norm = NormalizeFavoritePath(path)
    local external_key = SQLQuote(tostring(collection_id))
    local collection_id_sql = "(SELECT collection_id FROM "
        .. "collection_external_keys WHERE external_key="
        .. external_key .. ")"
    local sql
    if (kind or "file") == "file" then
        if enabled then
            sql = "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,file_id,added_at) SELECT "
                .. collection_id_sql .. ",id," .. tostring(os.time())
                .. " FROM files WHERE canonical_path_norm="
                .. SQLQuote(path_norm) .. " AND " .. collection_id_sql
                .. " IS NOT NULL;\n"
        else
            sql = "DELETE FROM collection_items WHERE collection_id="
                .. collection_id_sql .. " AND file_id=(SELECT id FROM files "
                .. "WHERE canonical_path_norm=" .. SQLQuote(path_norm)
                .. ");\n"
        end
    else
        local folder_match = CanonicalFavoriteFolderPredicate(
            path_norm, canonical_folder_id)
        if enabled then
            sql = "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,root_id,folder_id,added_at) SELECT "
                .. collection_id_sql .. ",folders.root_id,folders.id,"
                .. tostring(os.time()) .. " FROM folders WHERE "
                .. folder_match .. " AND " .. collection_id_sql
                .. " IS NOT NULL;\n"
        else
            sql = "DELETE FROM collection_items WHERE collection_id="
                .. collection_id_sql .. " AND folder_id IN(SELECT id FROM "
                .. "folders WHERE " .. folder_match .. ");\n"
        end
    end
    return sql
end

function QueueCanonicalFavoriteIntentSQL(statements)
    if not statements or #statements == 0 then return false end
    if not state.favorite_intent_serial then
        state.favorite_intent_serial = math.floor(
            (r.time_precise() or os.time()) * 1000)
    end
    state.favorite_intent_serial =
        (state.favorite_intent_serial or 0) + 1
    return QueueCanonicalUserDataSQL(
        table.concat(statements),
        "favorites_batch:" .. tostring(state.favorite_intent_serial))
end

function QueueCanonicalFavorite(path, kind, favorite, canonical_folder_id)
    local sql, path_norm = BuildCanonicalFavoriteSQL(
        path, kind, favorite, canonical_folder_id)
    return QueueCanonicalUserDataSQL(
        sql, "favorite:" .. (kind or "file") .. ":" .. path_norm)
end

function QueueCanonicalFavoriteEntrySnapshot(path, fallback_kind)
    local index = FindCachedFavoriteIndex(path)
    local entry = index and state.favorites[index] or nil
    if not entry then
        return QueueCanonicalFavorite(path, fallback_kind or "file", false)
    end
    local sql = BuildCanonicalFavoriteSQL(
        entry.path, entry.kind or "file",
        entry._direct_favorite == true, entry._canonical_folder_id)
    local path_norm = NormalizeFavoritePath(entry.path)
    local item_predicate
    if (entry.kind or "file") == "file" then
        item_predicate = "file_id=(SELECT id FROM files WHERE "
            .. "canonical_path_norm=" .. SQLQuote(path_norm) .. ")"
    else
        item_predicate = "folder_id IN(SELECT id FROM folders WHERE "
            .. CanonicalFavoriteFolderPredicate(
                path_norm, entry._canonical_folder_id) .. ")"
    end
    sql = sql .. "DELETE FROM collection_items WHERE collection_id IN("
        .. "SELECT collection_id FROM collection_external_keys) AND "
        .. item_predicate .. ";\n"
    for collection_key in pairs(entry.collection_ids or {}) do
        local collection_id = "(SELECT collection_id FROM "
            .. "collection_external_keys WHERE external_key="
            .. SQLQuote(tostring(collection_key)) .. ")"
        if (entry.kind or "file") == "file" then
            sql = sql .. "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,file_id,added_at) SELECT "
                .. collection_id .. ",id," .. tostring(entry.added or os.time())
                .. " FROM files WHERE canonical_path_norm="
                .. SQLQuote(path_norm) .. " AND " .. collection_id
                .. " IS NOT NULL;\n"
        else
            sql = sql .. "INSERT OR IGNORE INTO collection_items"
                .. "(collection_id,root_id,folder_id,added_at) SELECT "
                .. collection_id .. ",folders.root_id,folders.id,"
                .. tostring(entry.added or os.time()) .. " FROM folders WHERE "
                .. CanonicalFavoriteFolderPredicate(
                    path_norm, entry._canonical_folder_id) .. " AND "
                .. collection_id .. " IS NOT NULL;\n"
        end
    end
    return QueueCanonicalUserDataSQL(
        sql, "favorite_entry:" .. path_norm)
end

function QueueCanonicalFavoriteCollectionCreate(external_key, name, parent_id, added)
    local parent = parent_id and "(SELECT collection_id FROM "
        .. "collection_external_keys WHERE external_key="
        .. SQLQuote(tostring(parent_id)) .. ")" or "NULL"
    local now = tonumber(added) or os.time()
    local sql = "INSERT INTO collections(parent_id,name,created_at,sort_order) VALUES("
        .. parent .. "," .. SQLQuote(name or "Favorites Folder") .. ","
        .. tostring(now) .. ",0);\n"
        .. "INSERT OR REPLACE INTO collection_external_keys(collection_id,external_key) "
        .. "VALUES(last_insert_rowid()," .. SQLQuote(tostring(external_key)) .. ");\n"
    return QueueCanonicalUserDataSQL(
        sql, "favorite_collection:create:" .. tostring(external_key))
end

function QueueCanonicalFavoriteCollectionRename(external_key, name)
    local sql = "UPDATE collections SET name=" .. SQLQuote(name or "Favorites Folder")
        .. " WHERE id=(SELECT collection_id FROM collection_external_keys WHERE external_key="
        .. SQLQuote(tostring(external_key)) .. ");\n"
    return QueueCanonicalUserDataSQL(
        sql, "favorite_collection:rename:" .. tostring(external_key))
end

function QueueCanonicalFavoriteCollectionReparent(external_key, parent_id)
    local parent = parent_id and "(SELECT collection_id FROM "
        .. "collection_external_keys WHERE external_key="
        .. SQLQuote(tostring(parent_id)) .. ")" or "NULL"
    local sql = "UPDATE collections SET parent_id=" .. parent
        .. " WHERE id=(SELECT collection_id FROM collection_external_keys WHERE external_key="
        .. SQLQuote(tostring(external_key)) .. ");\n"
    return QueueCanonicalUserDataSQL(
        sql, "favorite_collection:parent:" .. tostring(external_key))
end

function QueueCanonicalFavoriteCollectionDelete(external_key, parent_id)
    local old_id = "(SELECT collection_id FROM collection_external_keys WHERE external_key="
        .. SQLQuote(tostring(external_key)) .. ")"
    -- Deleting an organizational folder removes that folder's membership.
    -- Child organizational folders move up one level, but loose items are not
    -- silently promoted into the parent (which previously made delete behave
    -- differently for top-level and nested folders).
    local sql = "DELETE FROM collection_items WHERE collection_id="
        .. old_id .. ";\n"
        .. "UPDATE collections SET parent_id="
        .. (parent_id and "(SELECT collection_id FROM collection_external_keys WHERE external_key="
            .. SQLQuote(tostring(parent_id)) .. ")" or "NULL")
        .. " WHERE parent_id=" .. old_id .. ";\n"
        .. "DELETE FROM collection_external_keys WHERE collection_id=" .. old_id .. ";\n"
        .. "DELETE FROM collections WHERE id=" .. old_id .. ";\n"
    return QueueCanonicalUserDataSQL(
        sql, "favorite_collection:delete:" .. tostring(external_key))
end

function QueueCanonicalClearFavorites()
    local sql = ""
        .. "DELETE FROM collection_items WHERE collection_id=-1 OR collection_id IN "
        .. "(SELECT collection_id FROM collection_external_keys);\n"
        .. "DELETE FROM collection_external_keys;\n"
        .. "DELETE FROM collections WHERE id<>-1;\n"
        .. "UPDATE user_file_data SET favorite=0 WHERE favorite<>0;\n"
    return QueueCanonicalUserDataSQL(sql, "favorites_clear")
end

function ClearFavoriteSessionState()
    -- Keep false overrides for every favorite known to this session. Loaded
    -- Library/result rows can retain a canonical favorite decoration until
    -- they are rebuilt; the override makes those stale row flags resolve as
    -- cleared immediately without invalidating unrelated browser data.
    local overrides = state.favorite_pending_overrides or {}
    for key in pairs(overrides) do overrides[key] = false end
    for _, entry in ipairs(state.favorites or {}) do
        local key = NormalizeFavoritePath(entry.path)
        if key ~= "" then overrides[key] = false end
    end
    for key in pairs(state.favorite_mutation_pending or {}) do
        overrides[key] = false
    end
    for _, mutation in ipairs(state.favorite_mutation_inflight or {}) do
        local key = NormalizeFavoritePath(mutation.path)
        if key ~= "" then overrides[key] = false end
    end
    state.favorite_pending_overrides = overrides

    -- A deferred favorite lookup must not re-apply an older click after the
    -- clear. The database clear is already queued after prior user writes;
    -- this only retires their unfinished in-memory decoration work.
    state.favorite_mutation_pending = {}
    state.favorite_mutation_inflight = {}
    state.favorite_mutation_versions = {}
    state.favorite_mutation_next_frame = 0
end

function QueueCanonicalPruneMissingFavorites()
    local sql = ""
        .. "DELETE FROM collection_items WHERE file_id IN"
        .. "(SELECT id FROM files WHERE missing<>0) OR folder_id IN"
        .. "(SELECT id FROM folders WHERE missing<>0);\n"
        .. "UPDATE user_file_data SET favorite=0 WHERE favorite<>0 AND file_id IN"
        .. "(SELECT id FROM files WHERE missing<>0);\n"
    return QueueCanonicalUserDataSQL(sql, "favorites_prune_missing")
end

function BuildCanonicalUsageRetentionSQL(recent_limit, used_limit, threshold)
    recent_limit = math.max(1, math.floor(tonumber(recent_limit) or 1))
    used_limit = math.max(1, math.floor(tonumber(used_limit) or 1))
    threshold = math.max(recent_limit, used_limit,
        math.floor(tonumber(threshold) or 1))
    local active_usage = "(last_used_at IS NOT NULL OR play_count>0)"
    return table.concat({
        "DROP TABLE IF EXISTS temp.rb_usage_retention_keep;\n",
        "CREATE TEMP TABLE rb_usage_retention_keep("
            .. "file_id INTEGER PRIMARY KEY) WITHOUT ROWID;\n",
        -- The negative sentinel freezes the threshold decision for every
        -- statement. Protected rows are cleared before disposable rows are
        -- deleted, so recounting midway could otherwise stop a partial prune.
        "INSERT INTO rb_usage_retention_keep(file_id) SELECT -1 WHERE "
            .. "(SELECT count(*) FROM user_file_data WHERE "
            .. active_usage .. ")>" .. tostring(threshold) .. ";\n",
        "INSERT OR IGNORE INTO rb_usage_retention_keep(file_id) "
            .. "SELECT file_id FROM user_file_data WHERE last_used_at IS NOT NULL "
            .. "AND EXISTS(SELECT 1 FROM rb_usage_retention_keep WHERE file_id=-1) "
            .. "ORDER BY last_used_at DESC,file_id LIMIT "
            .. tostring(recent_limit) .. ";\n",
        "INSERT OR IGNORE INTO rb_usage_retention_keep(file_id) "
            .. "SELECT file_id FROM user_file_data WHERE play_count>0 "
            .. "AND EXISTS(SELECT 1 FROM rb_usage_retention_keep WHERE file_id=-1) "
            .. "ORDER BY play_count DESC,last_used_at DESC,file_id LIMIT "
            .. tostring(used_limit) .. ";\n",
        -- Direct Favorites and notes own this row, so retain it and clear only
        -- its evicted usage. Collection membership lives in collection_items
        -- and therefore remains valid even when an otherwise empty row is gone.
        "UPDATE user_file_data SET play_count=0,last_used_at=NULL WHERE "
            .. active_usage .. " AND file_id NOT IN(SELECT file_id FROM "
            .. "rb_usage_retention_keep) AND (favorite<>0 OR notes IS NOT NULL) "
            .. "AND EXISTS(SELECT 1 FROM rb_usage_retention_keep WHERE file_id=-1);\n",
        "DELETE FROM user_file_data WHERE " .. active_usage
            .. " AND file_id NOT IN(SELECT file_id FROM rb_usage_retention_keep) "
            .. "AND favorite=0 AND notes IS NULL AND EXISTS(SELECT 1 FROM "
            .. "rb_usage_retention_keep WHERE file_id=-1);\n",
        "DROP TABLE rb_usage_retention_keep;\n",
    })
end

function QueueCanonicalUsage(path)
    local path_norm = NormalizeFavoritePath(path)
    local now = os.time()
    local sql = "INSERT INTO user_file_data"
        .. "(file_id,favorite,play_count,last_used_at,updated_at) "
        .. "SELECT id,0,1," .. tostring(now) .. "," .. tostring(now)
        .. " FROM files WHERE canonical_path_norm=" .. SQLQuote(path_norm)
        .. " ON CONFLICT(file_id) DO UPDATE SET "
        .. "play_count=user_file_data.play_count+1,"
        .. "last_used_at=excluded.last_used_at,"
        .. "updated_at=excluded.updated_at;\n"
        .. BuildCanonicalUsageRetentionSQL(
            USAGE_RECENT_RETENTION_LIMIT,
            USAGE_MOST_USED_RETENTION_LIMIT,
            USAGE_RETENTION_PRUNE_THRESHOLD)
    return QueueCanonicalUserDataSQL(sql, nil)
end

function QueueCanonicalTags(path, tags, excluded, defer_journal)
    local path_norm = NormalizeFavoritePath(path)
    local now = os.time()
    local file_select = "(SELECT id FROM files WHERE canonical_path_norm="
        .. SQLQuote(path_norm) .. ")"
    local sql = "DROP TABLE IF EXISTS temp.rb_old_effective_tags;\n"
        .. "DROP TABLE IF EXISTS temp.rb_new_effective_tags;\n"
        .. "DROP TABLE IF EXISTS temp.rb_added_tags;\n"
        .. "DROP TABLE IF EXISTS temp.rb_removed_tags;\n"
        .. "DROP TABLE IF EXISTS temp.rb_affected_ancestors;\n"
        .. "CREATE TEMP TABLE rb_old_effective_tags(tag_id INTEGER PRIMARY KEY);\n"
        .. "INSERT INTO rb_old_effective_tags SELECT DISTINCT file_tags.tag_id "
        .. "FROM file_tags JOIN tags ON tags.id=file_tags.tag_id WHERE "
        .. "file_tags.file_id=" .. file_select
        .. " AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions WHERE "
        .. "file_tag_exclusions.file_id=file_tags.file_id AND "
        .. "file_tag_exclusions.tag_norm=tags.name_norm);\n"
        .. "DELETE FROM file_tags WHERE source='user' AND file_id="
        .. file_select .. ";\n"
        .. "DELETE FROM file_tag_exclusions WHERE file_id="
        .. file_select .. ";\n"
    for _, raw_tag in ipairs(tags or {}) do
        local tag = NormalizeTag(raw_tag)
        if tag ~= "" then
            sql = sql .. "INSERT OR IGNORE INTO tags(name,name_norm) VALUES("
                .. SQLQuote(tag) .. "," .. SQLQuote(tag) .. ");\n"
                .. "INSERT OR IGNORE INTO file_tags"
                .. "(file_id,tag_id,source,confidence) SELECT "
                .. file_select .. ",id,'user',1.0 FROM tags "
                .. "WHERE name_norm=" .. SQLQuote(tag)
                .. " AND " .. file_select .. " IS NOT NULL;\n"
        end
    end
    for _, raw_tag in ipairs(excluded or {}) do
        local tag = NormalizeTag(raw_tag)
        if tag ~= "" then
            sql = sql .. "INSERT OR IGNORE INTO file_tag_exclusions"
                .. "(file_id,tag_norm,updated_at) SELECT id,"
                .. SQLQuote(tag) .. "," .. tostring(now)
                .. " FROM files WHERE canonical_path_norm="
                .. SQLQuote(path_norm) .. ";\n"
        end
    end
    local affected_folders = "(SELECT folder_id FROM folder_files WHERE "
        .. "missing=0 AND file_id=" .. file_select .. ")"
    sql = sql .. "DELETE FROM folder_tag_counts WHERE folder_id IN "
        .. affected_folders .. ";\n"
        .. "INSERT INTO folder_tag_counts(folder_id,tag_id,file_count) "
        .. "SELECT locations.folder_id,file_tags.tag_id,"
        .. "count(DISTINCT locations.file_id) FROM folder_files AS locations "
        .. "JOIN files ON files.id=locations.file_id "
        .. "JOIN file_tags ON file_tags.file_id=locations.file_id "
        .. "JOIN tags ON tags.id=file_tags.tag_id "
        .. "WHERE locations.missing=0 AND files.missing=0 "
        .. "AND locations.folder_id IN " .. affected_folders .. " "
        .. "AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions "
        .. "WHERE file_tag_exclusions.file_id=locations.file_id "
        .. "AND file_tag_exclusions.tag_norm=tags.name_norm) "
        .. "GROUP BY locations.folder_id,file_tags.tag_id;\n"
        .. "CREATE TEMP TABLE rb_new_effective_tags(tag_id INTEGER PRIMARY KEY);\n"
        .. "INSERT INTO rb_new_effective_tags SELECT DISTINCT file_tags.tag_id "
        .. "FROM file_tags JOIN tags ON tags.id=file_tags.tag_id WHERE "
        .. "file_tags.file_id=" .. file_select
        .. " AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions WHERE "
        .. "file_tag_exclusions.file_id=file_tags.file_id AND "
        .. "file_tag_exclusions.tag_norm=tags.name_norm);\n"
        .. "CREATE TEMP TABLE rb_added_tags(tag_id INTEGER PRIMARY KEY);\n"
        .. "INSERT INTO rb_added_tags SELECT tag_id FROM rb_new_effective_tags "
        .. "EXCEPT SELECT tag_id FROM rb_old_effective_tags;\n"
        .. "CREATE TEMP TABLE rb_removed_tags(tag_id INTEGER PRIMARY KEY);\n"
        .. "INSERT INTO rb_removed_tags SELECT tag_id FROM rb_old_effective_tags "
        .. "EXCEPT SELECT tag_id FROM rb_new_effective_tags;\n"
        .. "CREATE TEMP TABLE rb_affected_ancestors(folder_id INTEGER PRIMARY KEY);\n"
        .. "INSERT INTO rb_affected_ancestors SELECT DISTINCT closure.ancestor_id "
        .. "FROM folder_files AS locations JOIN folder_closure AS closure ON "
        .. "closure.descendant_id=locations.folder_id WHERE locations.missing=0 "
        .. "AND locations.file_id=" .. file_select .. ";\n"
        .. "INSERT INTO folder_subtree_tag_counts(folder_id,tag_id,file_count) "
        .. "SELECT ancestors.folder_id,added.tag_id,1 FROM rb_affected_ancestors "
        .. "AS ancestors CROSS JOIN rb_added_tags AS added WHERE 1 "
        .. "ON CONFLICT(folder_id,tag_id) DO UPDATE SET "
        .. "file_count=folder_subtree_tag_counts.file_count+1;\n"
        .. "UPDATE folder_subtree_tag_counts SET file_count=file_count-1 WHERE "
        .. "folder_id IN(SELECT folder_id FROM rb_affected_ancestors) AND "
        .. "tag_id IN(SELECT tag_id FROM rb_removed_tags);\n"
        .. "DELETE FROM folder_subtree_tag_counts WHERE file_count<=0;\n"
        .. "INSERT INTO library_tag_counts(tag_id,file_count) SELECT tag_id,1 "
        .. "FROM rb_added_tags WHERE 1 ON CONFLICT(tag_id) DO UPDATE SET "
        .. "file_count=library_tag_counts.file_count+1;\n"
        .. "UPDATE library_tag_counts SET file_count=file_count-1 WHERE "
        .. "tag_id IN(SELECT tag_id FROM rb_removed_tags);\n"
        .. "DELETE FROM library_tag_counts WHERE file_count<=0;\n"
        .. "DROP TABLE rb_old_effective_tags;\n"
        .. "DROP TABLE rb_new_effective_tags;\n"
        .. "DROP TABLE rb_added_tags;\n"
        .. "DROP TABLE rb_removed_tags;\n"
        .. "DROP TABLE rb_affected_ancestors;\n"
        -- Any collection containing this file or a parent folder must rebuild
        -- its derived facet catalog before it is used again.
    ClearCanonicalTagCatalogCache()
    return QueueCanonicalUserDataSQL(
        sql, "tags:" .. path_norm, defer_journal)
end

function AddFavorite(path, kind, collection_id, defer_finalize, defer_queue,
    canonical_folder_id)
    if not path or path == "" then return false end
    if tostring(path):match("^__fav_collection__") then return false end
    if kind == "folder" and IsRootLibraryFolder(path)
        and (not canonical_folder_id
            or IsCanonicalLibraryRootFolderId(canonical_folder_id)) then
        return false
    end
    local existing = FindCachedFavoriteIndex(path)
    if existing then
        if collection_id then
            return AddFavoriteCollectionMembership(path, collection_id, kind)
        end
        return false
    end
    state.favorites[#state.favorites + 1] = {
        kind = kind or "file", path = path, added = os.time(),
        collection_ids = {}
    }
    if not collection_id then
        state.favorites[#state.favorites]._direct_favorite = true
    end
    if (kind or "file") == "folder" and canonical_folder_id then
        state.favorites[#state.favorites]._canonical_folder_id =
            tonumber(canonical_folder_id)
    end
    CacheFavoriteEntryIdentity(state.favorites[#state.favorites])
    if collection_id then
        state.favorites[#state.favorites].collection_ids[tostring(collection_id)] = true
    end
    local normalized_path = NormalizeFavoritePath(path)
    state.favorite_index[normalized_path] = #state.favorites
    if not collection_id then
        state.favorite_pending_overrides[normalized_path] = true
    end
    if not defer_queue then
        if collection_id then
            QueueCanonicalFavoriteEntrySnapshot(path, kind or "file")
        else
            QueueCanonicalFavorite(
                path, kind or "file", true, canonical_folder_id)
        end
    end
    if not defer_finalize then
        SaveFavorites(false)
        RefreshFavoritesView()
        InvalidateCanonicalFavoriteViews()
    end
    return true
end

function CreateFavoriteCollection(name, parent_id)
    name = (name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false end
    parent_id = parent_id and tostring(parent_id) or nil
    if parent_id then
        local parent_exists = false
        for _, folder in ipairs(state.favorite_collections or {}) do
            if tostring(folder.id) == parent_id then
                parent_exists = true
                break
            end
        end
        if not parent_exists then parent_id = nil end
    end
    local id
    repeat
        id = tostring(os.time()) .. "_"
            .. tostring(math.random(100000, 999999))
        local collision = false
        for _, folder in ipairs(state.favorite_collections or {}) do
            if tostring(folder.id) == id then collision = true; break end
        end
    until not collision
    local added = os.time()
    state.favorite_collections[#state.favorite_collections + 1] = {
        id = id,
        name = name, parent_id = parent_id, added = added
    }
    QueueCanonicalFavoriteCollectionCreate(id, name, parent_id, added)
    RefreshFavoritesView()
    InvalidateCanonicalFavoriteViews()
    return true
end

function RenameFavoriteCollection(collection_id, name)
    collection_id = collection_id and tostring(collection_id) or nil
    name = (name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if not collection_id or name == "" then return false end
    for _, folder in ipairs(state.favorite_collections or {}) do
        if tostring(folder.id) == collection_id then
            if folder.name == name then return false end
            folder.name = name
            QueueCanonicalFavoriteCollectionRename(collection_id, name)
            RefreshFavoritesView()
            InvalidateCanonicalFavoriteViews()
            return true
        end
    end
    return false
end

function DeleteFavoriteCollection(collection_id)
    collection_id = collection_id and tostring(collection_id) or nil
    if not collection_id then return false end
    local parent_id = nil
    local found = false
    for _, folder in ipairs(state.favorite_collections or {}) do
        if tostring(folder.id) == collection_id then
            parent_id = folder.parent_id and tostring(folder.parent_id) or nil
            found = true
            break
        end
    end
    if not found then return false end

    -- A lookup that was queued while the folder still existed must not publish
    -- that deleted collection back into the in-memory membership cache.
    CancelCanonicalFavoriteCollectionMutations(collection_id)

    local affected_paths = {}
    local affected_seen = {}
    for _, entry in ipairs(state.favorites or {}) do
        local memberships = entry.collection_ids or {}
        if memberships[collection_id] then
            memberships[collection_id] = nil
            local path_key = NormalizeFavoritePath(entry.path)
            if path_key ~= "" and not affected_seen[path_key] then
                affected_seen[path_key] = true
                affected_paths[#affected_paths + 1] = entry.path
            end
            if path_key ~= "" then
                state.favorite_pending_overrides[path_key] =
                    FavoriteEntryHasAnyMembership(entry)
            end
        end
    end
    for index = #state.favorites, 1, -1 do
        local entry = state.favorites[index]
        if entry._direct_favorite ~= true
            and next(entry.collection_ids or {}) == nil then
            state.favorite_pending_overrides[
                NormalizeFavoritePath(entry.path)] = false
            table.remove(state.favorites, index)
            state.favorite_index_dirty = true
        end
    end
    for index = #state.favorite_collections, 1, -1 do
        local folder = state.favorite_collections[index]
        if folder.parent_id
            and tostring(folder.parent_id) == collection_id then
            folder.parent_id = parent_id
        end
        if tostring(folder.id) == collection_id then
            table.remove(state.favorite_collections, index)
        end
    end
    state.favorite_open_folders["collection:" .. collection_id] = nil
    QueueCanonicalFavoriteCollectionDelete(collection_id, parent_id)
    RefreshFavoritesView()
    if #affected_paths > 0 then
        RefreshFavoriteMembershipRows(
            affected_paths, {[collection_id] = true}, "file")
    end
    InvalidateCanonicalFavoriteViews()
    return true
end

function GetFavoriteCollectionMenuRows()
    local generation = state.media_favorite_generation or 0
    if state.favorite_collection_menu_generation == generation then
        return state.favorite_collection_menu_rows or {}
    end
    local nodes_by_id = {}
    local roots = {}
    for _, folder in ipairs(state.favorite_collections or {}) do
        nodes_by_id[tostring(folder.id)] = {
            folder = folder, children = {}
        }
    end
    for id, node in pairs(nodes_by_id) do
        local parent_id = node.folder.parent_id
            and tostring(node.folder.parent_id) or nil
        local parent = parent_id and nodes_by_id[parent_id] or nil
        if parent and parent ~= node then
            parent.children[#parent.children + 1] = node
        else
            roots[#roots + 1] = node
        end
    end
    local function SortNodes(nodes)
        table.sort(nodes, function(a, b)
            local a_name = (a.folder.name or ""):lower()
            local b_name = (b.folder.name or ""):lower()
            if a_name == b_name then
                return tostring(a.folder.id) < tostring(b.folder.id)
            end
            return a_name < b_name
        end)
        for _, node in ipairs(nodes) do SortNodes(node.children) end
    end
    SortNodes(roots)
    state.favorite_collection_menu_tree = roots
    state.favorite_collection_menu_tree_generation = generation
    local rows = {}
    local function AddRows(nodes, depth)
        for _, node in ipairs(nodes) do
            rows[#rows + 1] = {
                id = tostring(node.folder.id),
                name = node.folder.name or "Favorites Folder",
                label = string.rep("  ", depth)
                    .. (node.folder.name or "Favorites Folder"),
                depth = depth,
            }
            AddRows(node.children, depth + 1)
        end
    end
    AddRows(roots, 0)
    state.favorite_collection_menu_rows = rows
    state.favorite_collection_menu_generation = generation
    return rows
end

function GetFavoriteCollectionMenuTree()
    GetFavoriteCollectionMenuRows()
    return state.favorite_collection_menu_tree or {}
end

function ApplyFavoriteCollectionMenuTarget(
    paths, collection_id, kind, canonical_folder_id)
    EnsureFavoriteIndex()
    local all_have = true
    for _, path in ipairs(paths or {}) do
        local index = state.favorite_index[
            NormalizeFavoritePath(path)]
        local entry = index and state.favorites[index]
        if not FavoriteEntryHasCollection(entry, collection_id) then
            all_have = false
            break
        end
    end
    if all_have then
        SetFavoriteCollectionMemberships(
            paths, collection_id, false, kind, canonical_folder_id)
    else
        SetFavoriteCollectionMemberships(
            paths, collection_id, true, kind, canonical_folder_id)
    end
end

function DrawFavoriteCollectionMenuTree(nodes, paths, kind, canonical_folder_id)
    EnsureFavoriteIndex()
    for _, node in ipairs(nodes or {}) do
        local folder = node.folder
        local folder_id = folder and folder.id
        local folder_name = folder and folder.name
            or "Favorites Folder"
        if #(node.children or {}) > 0 then
            if imgui.BeginMenu(ctx, folder_name) then
                local all_have = true
                for _, path in ipairs(paths or {}) do
                    local index = state.favorite_index[
                        NormalizeFavoritePath(path)]
                    local entry = index and state.favorites[index]
                    if not FavoriteEntryHasCollection(entry, folder_id) then
                        all_have = false
                        break
                    end
                end
                if imgui.MenuItem(ctx,
                    (all_have and "\xe2\x9c\x93 " or "")
                        .. "This folder") then
                    ApplyFavoriteCollectionMenuTarget(
                        paths, folder_id, kind, canonical_folder_id)
                end
                imgui.Separator(ctx)
                DrawFavoriteCollectionMenuTree(
                    node.children, paths, kind, canonical_folder_id)
                imgui.EndMenu(ctx)
            end
        else
            local all_have = true
            for _, path in ipairs(paths or {}) do
                local index = state.favorite_index[
                    NormalizeFavoritePath(path)]
                local entry = index and state.favorites[index]
                if not FavoriteEntryHasCollection(entry, folder_id) then
                    all_have = false
                    break
                end
            end
            if imgui.MenuItem(ctx,
                (all_have and "\xe2\x9c\x93 " or "") .. folder_name) then
                ApplyFavoriteCollectionMenuTarget(
                    paths, folder_id, kind, canonical_folder_id)
            end
        end
    end
end

function CanReparentFavoriteCollection(source_id, target_id)
    source_id = source_id and tostring(source_id) or nil
    target_id = target_id and tostring(target_id) or nil
    if not source_id then return false end
    local generation = state.media_favorite_generation or 0
    if state.favorite_reparent_cache_source ~= source_id
        or state.favorite_reparent_cache_generation ~= generation then
        local children = {}
        local existing = {}
        for _, folder in ipairs(state.favorite_collections or {}) do
            local id = tostring(folder.id)
            existing[id] = true
            local parent_id = folder.parent_id
                and tostring(folder.parent_id) or nil
            if parent_id then
                children[parent_id] = children[parent_id] or {}
                children[parent_id][#children[parent_id] + 1] = id
            end
        end
        local invalid = {}
        local function MarkDescendants(id)
            if invalid[id] then return end
            invalid[id] = true
            for _, child_id in ipairs(children[id] or {}) do
                MarkDescendants(child_id)
            end
        end
        if existing[source_id] then MarkDescendants(source_id) end
        state.favorite_reparent_cache_source = source_id
        state.favorite_reparent_cache_generation = generation
        state.favorite_reparent_invalid_targets = invalid
        state.favorite_reparent_existing_targets = existing
    end
    local existing = state.favorite_reparent_existing_targets or {}
    if not existing[source_id] then return false end
    if not target_id then return true end
    return existing[target_id] == true
        and not state.favorite_reparent_invalid_targets[target_id]
end

function ReparentFavoriteCollection(source_id, target_id)
    source_id = source_id and tostring(source_id) or nil
    target_id = target_id and tostring(target_id) or nil
    if not CanReparentFavoriteCollection(source_id, target_id) then
        return false
    end
    for _, folder in ipairs(state.favorite_collections or {}) do
        if tostring(folder.id) == source_id then
            local current_parent = folder.parent_id
                and tostring(folder.parent_id) or nil
            if current_parent == target_id then return false end
            folder.parent_id = target_id
            QueueCanonicalFavoriteCollectionReparent(source_id, target_id)
            RefreshFavoritesView()
            InvalidateCanonicalFavoriteViews()
            return true
        end
    end
    return false
end

function RemoveFavorite(path, fallback_kind, defer_finalize)
    return SetFavoritePaths(
        {path}, false, fallback_kind or "file") > 0
end

function RemoveAllFavoriteMemberships(paths, fallback_kind)
    local remove_keys = {}
    local sql = {}
    local changed_paths = {}
    local affected_collections = {}
    for _, path in ipairs(paths or {}) do
        local key = NormalizeFavoritePath(path)
        if key ~= "" and not remove_keys[key] then
            local index = FindCachedFavoriteIndex(path)
            local entry = index and state.favorites[index] or nil
            local kind = entry and entry.kind or fallback_kind or "file"
            local folder_id = entry and entry._canonical_folder_id or nil
            remove_keys[key] = true
            sql[#sql + 1] = BuildCanonicalFavoriteSQL(
                path, kind, false, folder_id)
            if kind == "file" then
                sql[#sql + 1] = "DELETE FROM collection_items WHERE "
                    .. "collection_id IN(SELECT collection_id FROM "
                    .. "collection_external_keys) AND file_id=(SELECT id "
                    .. "FROM files WHERE canonical_path_norm="
                    .. SQLQuote(key) .. ");\n"
            else
                sql[#sql + 1] = "DELETE FROM collection_items WHERE "
                    .. "collection_id IN(SELECT collection_id FROM "
                    .. "collection_external_keys) AND folder_id IN(SELECT id "
                    .. "FROM folders WHERE "
                    .. CanonicalFavoriteFolderPredicate(key, folder_id)
                    .. ");\n"
            end
            if entry then
                for collection_id in pairs(entry.collection_ids or {}) do
                    affected_collections[tostring(collection_id)] = true
                end
                entry._direct_favorite = false
                entry.collection_ids = {}
                state.favorite_pending_overrides[key] = false
                changed_paths[#changed_paths + 1] = entry.path
            else
                state.favorite_pending_overrides[key] = false
                changed_paths[#changed_paths + 1] = path
            end
        end
    end
    for index = #state.favorites, 1, -1 do
        local entry = state.favorites[index]
        if remove_keys[NormalizeFavoritePath(entry.path)] then
            table.remove(state.favorites, index)
            state.favorite_index_dirty = true
        end
    end
    local queued = state.database.canonical
        and QueueCanonicalFavoriteIntentSQL(sql) or false
    if not state.database.canonical then
        for _, path in ipairs(changed_paths) do
            QueueCanonicalFavoriteEntrySnapshot(path, fallback_kind or "file")
        end
    end
    if #changed_paths > 0 or queued then
        SaveFavorites(false)
        RefreshFavoriteMembershipRows(
            changed_paths, affected_collections,
            fallback_kind or "file")
        InvalidateCanonicalFavoriteViews()
    end
    return #changed_paths > 0 and #changed_paths or queued and #paths or 0
end

function SetFavoritePaths(
    paths, favorite, kind, collection_id, canonical_folder_id)
    if collection_id then
        return SetFavoriteCollectionMemberships(
            paths, collection_id, favorite, kind, canonical_folder_id)
            and #paths or 0
    end
    local changed = 0
    local sql = {}
    local changed_paths = {}
    local intent_sql = {}
    local intent_seen = {}
    if not favorite then
        CancelCanonicalFavoriteMutations(paths)
    end
    if favorite then
        for _, path in ipairs(paths or {}) do
            local added = false
            local index = FindCachedFavoriteIndex(path)
            local entry = index and state.favorites[index] or nil
            if entry and entry._direct_favorite ~= true then
                entry._direct_favorite = true
                if (kind or entry.kind or "file") == "folder"
                    and canonical_folder_id then
                    entry._canonical_folder_id =
                        tonumber(canonical_folder_id)
                end
                added = true
            else
                added = AddFavorite(
                    path, kind or "file", nil, true, true,
                    canonical_folder_id) == true
            end
            if added then
                state.favorite_pending_overrides[
                    NormalizeFavoritePath(path)] = favorite == true
                changed_paths[#changed_paths + 1] = path
                if not state.database.canonical then
                    sql[#sql + 1] = BuildCanonicalFavoriteSQL(
                        path, kind or "file", true, canonical_folder_id)
                end
                changed = changed + 1
            end
        end
    else
        local remove_keys = {}
        for _, path in ipairs(paths or {}) do
            local key = NormalizeFavoritePath(path)
            local index = FindCachedFavoriteIndex(path)
            local entry = index and state.favorites[index] or nil
            if not remove_keys[key] then
                remove_keys[key] = {
                    path = path, kind = entry and entry.kind
                        or kind or "file",
                    canonical_folder_id = entry and entry._canonical_folder_id
                        or canonical_folder_id,
                    entry = entry,
                    was_direct = entry and entry._direct_favorite == true}
            end
        end
        for index = #state.favorites, 1, -1 do
            local entry = state.favorites[index]
            local key = NormalizeFavoritePath(entry.path)
            if remove_keys[key] and entry._direct_favorite == true then
                entry._direct_favorite = false
                if next(entry.collection_ids or {}) == nil then
                    table.remove(state.favorites, index)
                    state.favorite_index_dirty = true
                end
            end
        end
        for key, target in pairs(remove_keys) do
            if target.was_direct then
                local current_index = FindCachedFavoriteIndex(target.path)
                local current_entry = current_index
                    and state.favorites[current_index] or nil
                local still_custom_favorite = current_entry
                    and next(current_entry.collection_ids or {}) ~= nil
                state.favorite_pending_overrides[key] =
                    still_custom_favorite and true or false
                changed_paths[#changed_paths + 1] = target.path
                if not state.database.canonical then
                    sql[#sql + 1] = BuildCanonicalFavoriteSQL(
                        target.path, target.kind, false,
                        target.canonical_folder_id)
                end
                changed = changed + 1
            end
        end
    end
    if state.database.canonical then
        for _, path in ipairs(paths or {}) do
            local key = NormalizeFavoritePath(path)
            if key ~= "" and not intent_seen[key] then
                intent_seen[key] = true
                if collection_id then
                    local membership_sql =
                        BuildCanonicalFavoriteCollectionMembershipSQL(
                            path, kind or "file", collection_id, favorite,
                            canonical_folder_id)
                    if membership_sql then
                        intent_sql[#intent_sql + 1] = membership_sql
                    end
                else
                    local direct_sql = BuildCanonicalFavoriteSQL(
                        path, kind or "file", favorite,
                        canonical_folder_id)
                    intent_sql[#intent_sql + 1] = direct_sql
                end
            end
        end
    end
    local queued = QueueCanonicalFavoriteIntentSQL(intent_sql)
    if not state.database.canonical and changed > 0 then
        QueueCanonicalUserDataSQL(table.concat(sql),
            "favorites_batch:" .. tostring(r.time_precise()))
        SaveFavorites(false)
    elseif queued then
        SaveFavorites(false)
    end
    if changed > 0 or queued then
        local refresh_paths = #changed_paths > 0
            and changed_paths or paths
        RefreshFavoriteMembershipRows(
            refresh_paths, {}, kind or "file")
        InvalidateCanonicalFavoriteViews()
    end
    return changed > 0 and changed or queued and #paths or 0
end


function RemoveFavoriteCompletely(path, fallback_kind)
    return RemoveFavoritePathsCompletely(
        {path}, fallback_kind) > 0
end

function RemoveFavoritePathsCompletely(paths, fallback_kind)
    return RemoveAllFavoriteMemberships(paths, fallback_kind)
end

function GetFavoriteActionPaths(node)
    if node and state.multi_selected[node.path] then
        local selected = GetSelectedFilePaths(node.path)
        if #selected > 0 then return selected end
    end
    return node and {node.path} or {}
end

function GetActiveTrees()
    return state.favorites_mode and state.favorite_tree or state.folder_tree
end

function GetFavoriteDisplayName(node)
    return node.name
end

function GetFavoriteContextCollectionId(node)
    if not state.favorites_mode or not node then return nil end
    local current = node
    while current do
        if current ~= node and current.is_folder
            and not current.is_collection
            and current.path ~= "__favorite_files__" then
            -- A child of a favorited physical folder is inherited from that
            -- folder. The organizational collection containing the folder is
            -- not a direct membership of each descendant.
            return nil
        end
        local collection_id = current._favorite_collection_id
            or current.collection_id
        if collection_id then return collection_id end
        current = current.parent
    end
    return nil
end

function IsFavoriteRootMembershipNode(node)
    return state.favorites_mode and node ~= nil
        and (node._favorite_root_membership == true
            or (node.parent ~= nil
                and node.parent.path == "__favorite_files__"))
end

function GetFavoriteDragSource(node)
    if not state.favorites_mode or not node then
        return "library", nil
    end
    local collection_id = GetFavoriteContextCollectionId(node)
    if collection_id then return "collection", collection_id end
    if node.parent and node.parent.path == "__favorite_files__" then
        return "root", nil
    end
    local parent = node.parent
    while parent do
        if parent.is_folder and not parent.is_collection
            and parent.path ~= "__favorite_files__" then
            return "inherited", nil
        end
        parent = parent.parent
    end
    local index = FindCachedFavoriteIndex(node.path)
    local entry = index and state.favorites[index] or nil
    if entry and entry._direct_favorite == true then
        return "root", nil
    end
    return "library", nil
end

-- Mouse-only favorite marker. This is deliberately draw-list based: the
-- TreeNode remains the only ImGui item in a browser row, preserving keyboard
-- navigation, arrow expansion, selection, and indentation.
function IsInsideFavoriteFolder(path, already_normalized)
    local parent = (already_normalized and (path or "")
        or NormalizeFavoritePath(path or ""))
        :match("^(.*)[/\\][^/\\]+$")
    while parent and parent ~= "" do
        local index = state.favorite_index[parent]
        local entry = index and state.favorites[index] or nil
        if entry and entry.kind == "folder" then return true end
        parent = parent:match("^(.*)[/\\][^/\\]+$")
    end
    return false
end

local favorite_gutter_scratch = {}
function GetFavoriteRowGutter(favorites_layout)
    local window_x = select(1, imgui.GetWindowPos(ctx))
    local gutter = favorite_gutter_scratch
    gutter.window_x = window_x
    gutter.heart_x = window_x + 8
    gutter.hit_left = window_x + 4
    gutter.hit_right = window_x + (favorites_layout and 26 or 34)
    gutter.hit_width = favorites_layout and 18 or 26
    gutter.indent = favorites_layout and 20 or 0
    return gutter
end

local function GetFavoriteRowMembership(node)
    EnsureFavoriteIndex()
    local generation = state.media_favorite_generation or 0
    if node._favorite_membership_generation == generation then
        return node._favorite_membership_direct,
            node._favorite_membership_inherited
    end
    local normalized = node._favorite_normalized_path
    if not normalized then
        normalized = NormalizeFavoritePath(node.path)
        node._favorite_normalized_path = normalized
    end
    local pending = state.favorite_pending_overrides[normalized]
    local favorite
    if pending ~= nil then
        favorite = pending == true
    else
        local index = state.favorite_index[normalized]
        local entry = index and state.favorites[index] or nil
        if entry then
            favorite = FavoriteEntryHasAnyMembership(entry)
        elseif state.favorite_membership_cache[normalized] ~= nil then
            favorite = state.favorite_membership_cache[normalized] == true
        elseif state.favorites_mode and node._canonical_favorite ~= nil then
            -- A row returned by an active Favorites query is authoritative for
            -- that view only. Never reuse it as global Library heart state.
            favorite = node._canonical_favorite == true
        else
            favorite = false
            if state.database.canonical and normalized ~= ""
                and not state.favorite_membership_pending_paths[normalized]
                and not state.favorite_membership_inflight_paths[normalized] then
                -- Mutations can invalidate decoration caches without reloading
                -- the Library page. Rehydrate visible unknown rows on demand.
                state.favorite_membership_pending_paths[normalized] = true
                state.favorite_membership_next_at = math.max(
                    state.favorite_membership_next_at or 0,
                    r.time_precise() + 0.10)
            end
        end
    end
    local inherited = not favorite
        and IsInsideFavoriteFolder(normalized, true)
    node._favorite_membership_generation = generation
    node._favorite_membership_direct = favorite
    node._favorite_membership_inherited = inherited
    return favorite, inherited
end

function GetFavoriteHeartAppearance(
    favorite, selected, hot, inherited)
    local accent = state.theme.use_custom and state.theme.colors.accent
        or ((state.resolved_theme and state.resolved_theme.accent)
            or 0x4A88DFFF)
    local active = selected or hot
    if inherited then
        return active and 0xD0D0D0B0 or 0xA0A0A078, "\xe2\x99\xa5"
    end
    if favorite then
        return active and GetSelectedTextColor() or accent, "\xe2\x99\xa5"
    end
    return active and GetSelectedTextColor()
        or ((accent & 0xFFFFFF00) | 0x54), "\xe2\x99\xa1"
end

local function PrepareFavoriteGutter(favorites_layout, indent_override)
    local gutter = GetFavoriteRowGutter(favorites_layout)
    if indent_override ~= nil then gutter.indent = indent_override end
    local _, row_y = imgui.GetCursorScreenPos(ctx)
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    local row_height = imgui.GetTextLineHeightWithSpacing(ctx)
    local hot = mouse_x >= gutter.hit_left
        and mouse_x <= gutter.hit_right
        and mouse_y >= row_y and mouse_y <= row_y + row_height
    if hot then imgui.PushStyleColor(ctx, imgui.Col_HeaderHovered, 0x00000000) end
    if gutter.indent > 0 then imgui.Indent(ctx, gutter.indent) end
    return hot, hot, gutter.indent
end

function ShouldDrawFavoriteRowHeart(node)
    if not node or not state.show_favorite_column
        or node.path == "__favorite_files__" or node.is_collection then
        return false
    end
    if not node.is_folder then return true end
    return not IsRootLibraryFolderNode(node)
end

function GetFavoriteNodeInstanceKey(node)
    if not node then return "" end
    if node.is_collection then
        return "collection:" .. tostring(node.collection_id or node.path)
    end
    if node.is_favorite_root_files then return "favorite-root-files" end
    local parent_key = node.parent
        and GetFavoriteNodeInstanceKey(node.parent) or "favorite-root"
    return parent_key .. "\30" .. tostring(
        node._canonical_folder_id or NormalizeFavoritePath(node.path or ""))
end

function GetFolderUIKey(node)
    if state.favorites_mode then return GetFavoriteNodeInstanceKey(node) end
    return node and node.path or ""
end

function IsFolderCursorNode(node)
    if not node or state.cursor_type ~= "folder"
        or state.cursor_path ~= node.path then return false end
    return not state.favorites_mode
        or state.cursor_favorite_instance_key == GetFavoriteNodeInstanceKey(node)
end

function PrepareFavoriteRowHeart(node)
    if not ShouldDrawFavoriteRowHeart(node) then
        return false, false, 0
    end
    -- Leaf rows use their native TreeNode icon slot just like Actions/FX.
    -- Only a root expandable folder needs an extra gutter for both heart and
    -- disclosure arrow; naturally indented child folders already have room.
    local gutter = GetFavoriteRowGutter(true)
    local cursor_x = select(1, imgui.GetCursorScreenPos(ctx))
    local indent = node.is_folder and cursor_x <= gutter.heart_x + 6
        and gutter.indent or 0
    return PrepareFavoriteGutter(true, indent)
end

function DrawFavoriteRowHeart(node, prepared_hot, row_key)
    if not ShouldDrawFavoriteRowHeart(node) then
        return false
    end
    local row_min_x, row_min_y = imgui.GetItemRectMin(ctx)
    local row_max_x, row_max_y = imgui.GetItemRectMax(ctx)
    local gutter = GetFavoriteRowGutter(true)
    local heart_x = gutter.heart_x
    local heart_y = row_min_y
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    local hit = prepared_hot or (mouse_x >= heart_x - 4
        and mouse_x <= heart_x + gutter.hit_width
        and mouse_y >= heart_y and mouse_y <= row_max_y
    )
    local favorite, inherited = GetFavoriteRowMembership(node)
    local collection_id = GetFavoriteContextCollectionId(node)
    local root_membership = IsFavoriteRootMembershipNode(node)
    if collection_id then
        -- Never perform an on-demand SQLite lookup from the draw loop. Paged
        -- collection rows are already membership-qualified; hydrate the one
        -- clicked row only if a mutation needs its complete membership set.
        EnsureFavoriteIndex()
        local index = state.favorite_index[
            NormalizeFavoritePath(node.path or "")]
        local entry = index and state.favorites[index] or nil
        if node._canonical_favorite ~= nil then
            -- Canonical collection pages report membership in their active
            -- collection, rather than the file's global Favorites status.
            favorite = node._canonical_favorite == true
        elseif entry then
            favorite = FavoriteEntryHasCollection(entry, collection_id)
        end
        inherited = false
    end
    local selected
    if node.is_folder then
        selected = IsFolderCursorNode(node)
    else
        selected = IsMediaFileRowSelected(node, row_key)
    end
    local row_hovered = imgui.IsItemHovered(ctx)
    if not row_hovered then
        row_hovered = node.is_folder
            and state.hovered_path == node.path
            and (not state.favorites_mode
                or state.hovered_favorite_instance_key
                    == GetFavoriteNodeInstanceKey(node))
            or (not node.is_folder
                and IsMediaFileRowHovered(node, row_key))
    end
    local color = select(1, GetFavoriteHeartAppearance(
        favorite, selected, row_hovered, inherited))
    local glyph = (favorite or inherited) and "♥" or "♡"
    glyph = (favorite or inherited) and "\xe2\x99\xa5" or "\xe2\x99\xa1"
    imgui.DrawList_AddText(
        imgui.GetWindowDrawList(ctx), heart_x, heart_y, color, glyph)
    local mouse_clicked = imgui.IsMouseClicked(ctx, 0)
    local popup_open = false
    if imgui.IsPopupOpen and imgui.PopupFlags_AnyPopup then
        local popup_ok, any_popup = pcall(
            imgui.IsPopupOpen, ctx, "", imgui.PopupFlags_AnyPopup)
        popup_open = popup_ok and any_popup == true
    end
    if hit and mouse_clicked and not popup_open
        and not state.context_menu_active then
        -- Popup menu clicks are global mouse clicks too. If a context menu is
        -- positioned over the heart gutter, allowing the underlying row to
        -- observe that click queues a direct/root favorite in the same frame
        -- as the chosen custom-folder action.
        -- The heart is draw-list geometry over an active TreeNode. Remember
        -- the press across frames so a small click movement cannot fall
        -- through into the row/folder drag handlers and stop playback.
        state.favorite_heart_press_path = node.path
        local action_paths = GetFavoriteActionPaths(node)
        local action_kind = node.is_folder and "folder" or "file"
        local changed = 0
        if favorite and collection_id then
            changed = SetFavoriteCollectionMemberships(
                action_paths, collection_id, false,
                action_kind, node._canonical_folder_id)
                    and #action_paths or 0
        elseif favorite and root_membership then
            -- The loose-root row represents only direct ownership. Removing it
            -- must preserve copies that still belong to custom folders.
            changed = SetFavoritePaths(
                action_paths, false, action_kind, nil,
                node._canonical_folder_id)
        elseif favorite then
            changed = RemoveAllFavoriteMemberships(
                action_paths, action_kind)
        else
            changed = SetFavoritePaths(action_paths, not favorite,
                action_kind, collection_id,
                node._canonical_folder_id)
        end
        node._canonical_favorite = not favorite
        return true
    end
    return false
end

function PromptAddFavoriteFolder(parent_id)
    state.favorite_folder_name = ""
    state.favorite_folder_parent_id = parent_id
    state.show_favorite_folder_dialog = true
end

function DrawFavoriteFolderDialog()
    if not state.show_favorite_folder_dialog then return end
    imgui.SetNextWindowSize(ctx, 360, 0, imgui.Cond_Appearing)
    local visible, open = imgui.Begin(
        ctx, "New Favorites Folder", true,
        imgui.WindowFlags_AlwaysAutoResize | imgui.WindowFlags_NoCollapse
    )
    if visible then
        imgui.Text(ctx, state.favorite_folder_parent_id and "Create a nested Favorites folder" or "Create a Favorites folder")
        imgui.Spacing(ctx)
        imgui.SetNextItemWidth(ctx, 300)
        local changed, name = imgui.InputTextWithHint(ctx, "##favorite_folder_name", "Folder name", state.favorite_folder_name)
        if changed then state.favorite_folder_name = name end
        imgui.Spacing(ctx)
        if imgui.Button(ctx, "Create", 90, 0) and state.favorite_folder_name:match("%S") then
            CreateFavoriteCollection(state.favorite_folder_name, state.favorite_folder_parent_id)
            state.show_favorite_folder_dialog = false
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Cancel", 90, 0) then state.show_favorite_folder_dialog = false end
        imgui.End(ctx)
    end
    if not open then state.show_favorite_folder_dialog = false end
end

function FavoriteSortLabel()
    if state.favorite_sort == "newest" then return "Newest"
    elseif state.favorite_sort == "az" then return "Name A-Z"
    elseif state.favorite_sort == "za" then return "Name Z-A"
    end
    return "Added Order"
end

function SetFavoriteSort(mode)
    state.favorite_sort = mode
    r.SetExtState(EXT_SECTION, "favorite_sort", mode, true)
    RefreshFavoritesView()
    InvalidateCanonicalFavoriteViews()
end

function DrawFavoriteSortMenu(popup_id)
    if imgui.BeginPopup(ctx, popup_id) then
        if imgui.MenuItem(ctx, (state.favorite_sort == "added" and "\xe2\x9c\x93 " or "") .. "Added order") then SetFavoriteSort("added") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "newest" and "\xe2\x9c\x93 " or "") .. "Newest first") then SetFavoriteSort("newest") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "az" and "\xe2\x9c\x93 " or "") .. "Name A-Z") then SetFavoriteSort("az") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "za" and "\xe2\x9c\x93 " or "") .. "Name Z-A") then SetFavoriteSort("za") end
        imgui.EndPopup(ctx)
    end
end

function SaveSettings()
    -- SetExtState(..., persist=true) rewrites REAPER's durable ExtState file.
    -- Rewriting all settings for a one-value combo/button change can stall all
    -- REAPER/ReaImGui windows. Cache the persisted values and write only keys
    -- that actually changed, matching the lightweight interaction behavior of
    -- the main browser controls.
    state.settings_persisted_values =
        state.settings_persisted_values or {}
    state.settings_persisted_loaded =
        state.settings_persisted_loaded or {}
    local function PersistSetting(key, value)
        value = tostring(value or "")
        if not state.settings_persisted_loaded[key] then
            state.settings_persisted_values[key] =
                r.GetExtState(EXT_SECTION, key) or ""
            state.settings_persisted_loaded[key] = true
        end
        if state.settings_persisted_values[key] ~= value then
            r.SetExtState(EXT_SECTION, key, value, true)
            state.settings_persisted_values[key] = value
        end
    end

    local root_paths = table.concat(state.root_folders, "\n")
    local saved_root_paths = r.GetExtState(EXT_SECTION, "root_paths") or ""
    local saved_root_count = math.max(0, math.floor(
        tonumber(r.GetExtState(EXT_SECTION, "root_count")) or 0))
    local roots_changed = saved_root_paths ~= root_paths
        or saved_root_count ~= #state.root_folders
    if roots_changed then
        for index, folder in ipairs(state.root_folders) do
            PersistSetting("root_" .. tostring(index), folder)
        end
    end
    -- Keep the numbered keys for compatibility with older ReaBrowse builds,
    -- but remove leftovers so a deleted root cannot reappear on migration.
    if roots_changed and r.DeleteExtState then
        local slot = #state.root_folders + 1
        local empty_run = 0
        while empty_run < 16 and slot <= #state.root_folders + 1024 do
            local key = "root_" .. tostring(slot)
            local value = r.GetExtState(EXT_SECTION, key)
            if value and value ~= "" then
                r.DeleteExtState(EXT_SECTION, key, true)
                state.settings_persisted_values[key] = ""
                state.settings_persisted_loaded[key] = true
                empty_run = 0
            else
                empty_run = empty_run + 1
            end
            slot = slot + 1
        end
    end
    PersistSetting("root_paths", root_paths)
    PersistSetting("root_count", #state.root_folders)
    PersistSetting("auto_play", state.auto_play and "1" or "0")
    PersistSetting("preview_transport_mode",
        state.preview_transport_mode or "follow")
    PersistSetting("loop_preview", state.loop_preview and "1" or "0")
    PersistSetting("tempo_match_enabled",
        state.tempo_match_enabled and "1" or "0")
    PersistSetting("one_shot_mode", state.one_shot_mode and "1" or "0")
    PersistSetting("external_drag_default_native", state.external_drag_default_native and "1" or "0")
    PersistSetting("one_shot_native_drag", state.one_shot_native_drag and "1" or "0")
    PersistSetting("scan_speed", state.scan_speed or "balanced")
    PersistSetting("audio_auto_one_shot",
        state.audio_auto_one_shot and "1" or "0")
    PersistSetting("one_shot_bypass_sync",
        state.one_shot_bypass.sync and "1" or "0")
    PersistSetting("one_shot_bypass_loop",
        state.one_shot_bypass.loop and "1" or "0")
    PersistSetting("one_shot_bypass_tempo_match",
        state.one_shot_bypass.tempo_match and "1" or "0")
    PersistSetting("one_shot_bypass_key_sync",
        state.one_shot_bypass.key_sync and "1" or "0")
    PersistSetting("one_shot_bypass_playrate",
        state.one_shot_bypass.playrate and "1" or "0")
    PersistSetting("playrate", state.playrate)
    PersistSetting("pitch_shift", state.pitch_shift)
    PersistSetting("preview_stretch_mode",
        state.preview_stretch_mode or "elastique_pro")
    PersistSetting("audio_volume_db", state.audio_volume_db)
    PersistSetting("audio_route_mode", state.audio_route_mode)
    PersistSetting("audio_route_output_channel",
        state.audio_route_output_channel or 0)
    PersistSetting("audio_route_output_mono",
        state.audio_route_output_mono and "1" or "0")
    PersistSetting("media_tag_bar_open",
        state.media_tag_bar.open and "1" or "0")
    PersistSetting("media_tag_height", state.media_tag_bar.height or "")
    PersistSetting("tag_sort_mode", state.tag_sort_mode or "count")
    PersistSetting("piano_open", state.piano_open and "1" or "0")
    PersistSetting("favorite_sort", state.favorite_sort)
    PersistSetting("show_favorite_column",
        state.show_favorite_column and "1" or "0")
    PersistSetting("theme_use_custom", "1")
    PersistSetting("theme_window_bg", state.theme.colors.window_bg)
    PersistSetting("theme_panel_bg", state.theme.colors.panel_bg)
    PersistSetting("theme_text", state.theme.colors.text)
    PersistSetting("theme_selected_text", state.theme.colors.selected_text)
    PersistSetting("theme_accent", state.theme.colors.accent)
    PersistSetting("theme_header_icon", state.theme.colors.header_icon)
    PersistSetting("theme_border", state.theme.colors.border)
    PersistSetting("theme_folder_text", state.theme.colors.folder_text)
    PersistSetting("theme_midi_note", state.theme.colors.midi_note)
    PersistSetting("theme_preview_bg", state.theme.colors.preview_bg)
    PersistSetting("theme_preview_grid", state.theme.colors.preview_grid)
    for _, key in ipairs(THEME_COLOR_KEYS) do
        local parts = {}
        for _, choice in ipairs(state.theme.suggestions[key] or {}) do
            parts[#parts + 1] = choice.label:gsub("[|;]", "") .. "|" .. tostring(choice.color)
        end
        PersistSetting("theme_suggestions_" .. key,
            table.concat(parts, ";"))
    end
    
    PersistSetting("theme_font_name", state.theme.font_name)
    PersistSetting("theme_font_size", state.theme.font_size)

    PersistSetting("key_sync_enabled", state.key_sync.enabled and "1" or "0")
    PersistSetting("key_sync_target_pc", state.key_sync.target_pc)
end

function LoadSettings()
    local root_count = math.max(0, math.floor(
        tonumber(r.GetExtState(EXT_SECTION, "root_count")) or 0))
    local numbered_roots = {}
    for index = 1, root_count do
        local folder = r.GetExtState(EXT_SECTION, "root_" .. tostring(index))
        if folder and folder ~= "" then
            numbered_roots[#numbered_roots + 1] = folder
        end
    end

    local saved_root_paths = r.GetExtState(EXT_SECTION, "root_paths")
    local saved_roots = {}
    if saved_root_paths and saved_root_paths ~= "" then
        for folder in saved_root_paths:gmatch("[^\r\n]+") do
            saved_roots[#saved_roots + 1] = folder
            AddRootFolderIfMissing(folder)
        end
    end
    -- Older builds persisted only root_1..root_N. Use those when the newer
    -- atomic list is absent, while allowing the canonical database repair to
    -- recover roots when the two stores disagree.
    if #saved_roots == 0 then
        for _, folder in ipairs(numbered_roots) do
            AddRootFolderIfMissing(folder)
        end
    end
    local function RootListSignature(values)
        local normalized = {}
        for _, value in ipairs(values or {}) do
            normalized[#normalized + 1] = NormalizeFavoritePath(value)
        end
        return table.concat(normalized, "\30")
    end
    state.root_settings_need_repair = root_count ~= #state.root_folders
        or RootListSignature(saved_roots) ~= RootListSignature(numbered_roots)
    state.auto_play = r.GetExtState(EXT_SECTION, "auto_play") ~= "0"
    local saved_transport_mode = r.GetExtState(
        EXT_SECTION, "preview_transport_mode")
    if saved_transport_mode ~= "independent"
        and saved_transport_mode ~= "follow"
        and saved_transport_mode ~= "control" then
        saved_transport_mode = "follow"
    end
    state.preview_transport_mode = saved_transport_mode
    state.loop_preview = r.GetExtState(EXT_SECTION, "loop_preview") ~= "0"
    state.tempo_match_enabled =
        r.GetExtState(EXT_SECTION, "tempo_match_enabled") == "1"
    state.one_shot_mode = r.GetExtState(EXT_SECTION, "one_shot_mode") == "1"
    state.external_drag_default_native = r.GetExtState(EXT_SECTION, "external_drag_default_native") == "1"
    state.one_shot_native_drag = r.GetExtState(EXT_SECTION, "one_shot_native_drag") == "1"
    local saved_scan_speed = r.GetExtState(EXT_SECTION, "scan_speed")
    if LIBRARY_SCAN_SPEEDS[saved_scan_speed] then
        state.scan_speed = saved_scan_speed
    end
    state.audio_auto_one_shot =
        r.GetExtState(EXT_SECTION, "audio_auto_one_shot") ~= "0"
    state.one_shot_bypass.sync =
        r.GetExtState(EXT_SECTION, "one_shot_bypass_sync") ~= "0"
    state.one_shot_bypass.loop =
        r.GetExtState(EXT_SECTION, "one_shot_bypass_loop") ~= "0"
    state.one_shot_bypass.tempo_match =
        r.GetExtState(EXT_SECTION, "one_shot_bypass_tempo_match") ~= "0"
    state.one_shot_bypass.key_sync =
        r.GetExtState(EXT_SECTION, "one_shot_bypass_key_sync") ~= "0"
    state.one_shot_bypass.playrate =
        r.GetExtState(EXT_SECTION, "one_shot_bypass_playrate") ~= "0"
    -- Dice navigation replaces the retired persistent Randomize mode.
    state.randomize_on = false
    state.playrate = tonumber(r.GetExtState(EXT_SECTION, "playrate")) or 1.0
    state.pitch_shift = tonumber(r.GetExtState(EXT_SECTION, "pitch_shift")) or 0
    local saved_stretch_mode = r.GetExtState(
        EXT_SECTION, "preview_stretch_mode")
    if saved_stretch_mode ~= "project_default"
        and saved_stretch_mode ~= "elastique_pro"
        and saved_stretch_mode ~= "elastique_efficient" then
        saved_stretch_mode = "elastique_pro"
    end
    state.preview_stretch_mode = saved_stretch_mode
    state.audio_volume_db = tonumber(
        r.GetExtState(EXT_SECTION, "audio_volume_db")) or 0
    local audio_route_mode = r.GetExtState(EXT_SECTION, "audio_route_mode")
    if audio_route_mode == "selected_track"
        or audio_route_mode == "hardware_output" then
        state.audio_route_mode = audio_route_mode
    end
    state.audio_route_output_channel = math.max(0, math.floor(
        tonumber(r.GetExtState(
            EXT_SECTION, "audio_route_output_channel")) or 0))
    state.audio_route_output_mono =
        r.GetExtState(EXT_SECTION, "audio_route_output_mono") == "1"
    state.media_tag_bar.open =
        r.GetExtState(EXT_SECTION, "media_tag_bar_open") ~= "0"
    state.media_tag_bar.height = tonumber(r.GetExtState(EXT_SECTION, "media_tag_height"))
    local saved_tag_sort = r.GetExtState(EXT_SECTION, "tag_sort_mode")
    if saved_tag_sort == "az" or saved_tag_sort == "count" then
        state.tag_sort_mode = saved_tag_sort
    end
    state.piano_open = r.GetExtState(EXT_SECTION, "piano_open") ~= "0"
    local favorite_sort = r.GetExtState(EXT_SECTION, "favorite_sort")
    if favorite_sort == "az" or favorite_sort == "za" or favorite_sort == "newest" then
        state.favorite_sort = favorite_sort
    end
    state.show_favorite_column = r.GetExtState(EXT_SECTION, "show_favorite_column") ~= "0"
    local function LoadColor(key, default)
        local v = tonumber(r.GetExtState(EXT_SECTION, key))
        return v or default
    end
    -- Imported REAPER colors are snapshots, never a persistent live-follow mode.
    state.theme.use_custom = true
    state.theme.colors.window_bg     = LoadColor("theme_window_bg", state.theme.colors.window_bg)
    state.theme.colors.panel_bg      = LoadColor("theme_panel_bg", state.theme.colors.panel_bg)
    state.theme.colors.text          = LoadColor("theme_text", state.theme.colors.text)
    state.theme.colors.selected_text = LoadColor("theme_selected_text", state.theme.colors.selected_text)
    state.theme.colors.accent        = LoadColor("theme_accent", state.theme.colors.accent)
    state.theme.colors.header_icon   = LoadColor("theme_header_icon", state.theme.colors.header_icon)
    state.theme.colors.border        = LoadColor("theme_border", state.theme.colors.border)
    state.theme.colors.folder_text   = LoadColor("theme_folder_text", state.theme.colors.folder_text)
    state.theme.colors.midi_note     = LoadColor("theme_midi_note", state.theme.colors.midi_note)
    state.theme.colors.preview_bg    = LoadColor("theme_preview_bg", state.theme.colors.preview_bg)
    state.theme.colors.preview_grid  = LoadColor("theme_preview_grid", state.theme.colors.preview_grid)
    for _, key in ipairs(THEME_COLOR_KEYS) do
        local encoded = r.GetExtState(EXT_SECTION, "theme_suggestions_" .. key)
        local choices = {}
        for part in (encoded or ""):gmatch("[^;]+") do
            local label, value = part:match("^(.-)|(%d+)$")
            if label and value then choices[#choices + 1] = {label = label, color = tonumber(value)} end
        end
        state.theme.suggestions[key] = choices
    end
    
    local saved_font = r.GetExtState(EXT_SECTION, "theme_font_name")
    if saved_font and saved_font ~= "" then state.theme.font_name = saved_font end
    state.theme.font_size = tonumber(r.GetExtState(EXT_SECTION, "theme_font_size")) or state.theme.font_size

    state.key_sync.enabled = r.GetExtState(EXT_SECTION, "key_sync_enabled") == "1"
    if not state.piano_open then state.key_sync.enabled = false end
    state.key_sync.target_pc = tonumber(r.GetExtState(EXT_SECTION, "key_sync_target_pc")) or 0
end

local function RepairConfiguredRootsFromCanonicalDatabase()
    if not state.root_settings_need_repair
        or state.database.backend ~= "sqlite"
        or not FileExists(GetCanonicalDatabasePath()) then
        return false
    end
    local rows = QueryDatabaseScalar(
        "SELECT display_path FROM roots WHERE enabled=1 ORDER BY id;")
    if not rows or rows == "" then return false end

    local changed = false
    for folder in tostring(rows):gmatch("[^\r\n]+") do
        if AddRootFolderIfMissing(folder) then changed = true end
    end
    state.root_settings_need_repair = false
    -- This also rewrites root_paths when it differed from the numbered keys,
    -- and removes stale numbered entries left by older builds.
    SaveSettings()
    return changed
end

-- ============================================================
-- AUTO-THEMING
-- ============================================================
function GetREAPERThemeColor(key, default)
    local ok, col = pcall(r.GetThemeColor, key, 0)
    if not ok or col == -1 then return default end
    -- Theme colors are OS-native and may be negative when their high flag byte
    -- is set. Only -1 means missing; convert the low 24 color bits explicitly.
    local red, green, blue = r.ColorFromNative(col & 0xFFFFFF)
    if red == nil then return default end
    return (red << 24) | (green << 16) | (blue << 8) | 0xFF
end

function GetOptionalREAPERThemeColor(key)
    local ok, col = pcall(r.GetThemeColor, key, 0)
    if not ok or col == -1 then return nil end
    local red, green, blue = r.ColorFromNative(col & 0xFFFFFF)
    if red == nil then return nil end
    return (red << 24) | (green << 16) | (blue << 8) | 0xFF
end

function GetSelectedTextColor()
    if state.resolved_theme and state.resolved_theme.selected_text then
        return state.resolved_theme.selected_text
    end
    if state.theme.use_custom then return state.theme.colors.selected_text end
    local text = GetREAPERThemeColor("genlist_selfg", 0xFFFFFFFF)
    if state.resolved_theme then
        text = EnsureReadableText(text, state.resolved_theme.accent, 105)
    end
    return text
end

function GetFolderTextColor()
    if state.resolved_theme and state.resolved_theme.folder_text then
        return state.resolved_theme.folder_text
    end
    if state.theme.use_custom then return state.theme.colors.folder_text end
    local _, _, folders = GetREAPERAccentPalette()
    if state.resolved_theme then
        folders = EnsureColorContrast(folders, state.resolved_theme.panel_bg, 86)
    end
    return folders
end

function AdjustColor(col, amt)
    local r8 = (col >> 24) & 0xFF
    local g8 = (col >> 16) & 0xFF
    local b8 = (col >> 8) & 0xFF
    local a8 = col & 0xFF
    local function adj(c)
        if amt >= 0 then return math.floor(c + (255 - c) * amt + 0.5)
        else return math.floor(c + c * amt + 0.5) end
    end
    r8, g8, b8 = adj(r8), adj(g8), adj(b8)
    r8 = math.max(0, math.min(255, r8))
    g8 = math.max(0, math.min(255, g8))
    b8 = math.max(0, math.min(255, b8))
    return (r8 << 24) | (g8 << 16) | (b8 << 8) | a8
end

function ColorLuminance(col)
    local red = (col >> 24) & 0xFF
    local green = (col >> 16) & 0xFF
    local blue = (col >> 8) & 0xFF
    return red * 0.299 + green * 0.587 + blue * 0.114
end

function BlendColor(first, second, amount)
    amount = math.max(0, math.min(1, amount or 0.5))
    local inverse = 1 - amount
    local red = math.floor((((first >> 24) & 0xFF) * inverse) + (((second >> 24) & 0xFF) * amount) + 0.5)
    local green = math.floor((((first >> 16) & 0xFF) * inverse) + (((second >> 16) & 0xFF) * amount) + 0.5)
    local blue = math.floor((((first >> 8) & 0xFF) * inverse) + (((second >> 8) & 0xFF) * amount) + 0.5)
    local alpha = first & 0xFF
    return (red << 24) | (green << 16) | (blue << 8) | alpha
end

function GetREAPERAccentPalette()
    local list_blue = GetREAPERThemeColor("genlist_selbg", 0x4A88DFFF)
    local toolbar_blue = GetREAPERThemeColor("col_toolbar_text_on", 0x6AB4FFFF)
    local selected_text = GetREAPERThemeColor("genlist_selfg", 0xFFFFFFFF)

    -- Use only browser-facing theme roles. Armed/fader colors can represent
    -- warnings, recording, meters, or track states rather than the UI accent.
    local accent = BlendColor(list_blue, toolbar_blue, 0.46)
    local notes = BlendColor(accent, toolbar_blue, 0.56)
    local folders = BlendColor(toolbar_blue, selected_text, 0.18)
    return accent, notes, folders
end

function EnsureColorContrast(foreground, background, minimum_delta)
    local adjusted = foreground
    local background_lum = ColorLuminance(background)
    for _ = 1, 8 do
        if math.abs(ColorLuminance(adjusted) - background_lum) >= minimum_delta then
            break
        end
        adjusted = AdjustColor(adjusted, background_lum < 128 and 0.14 or -0.14)
    end
    return adjusted
end

function EnsureReadableText(foreground, background, minimum_delta)
    minimum_delta = minimum_delta or 90
    if math.abs(ColorLuminance(foreground) - ColorLuminance(background)) >= minimum_delta then
        return foreground
    end
    return ColorLuminance(background) >= 128 and 0x181818FF or 0xEEEEEEFF
end

function PushBrowserFolderRowStyle(selected)
    local palette = ResolveREAPERThemePalette()
    local text_color = selected and GetSelectedTextColor()
        or GetFolderTextColor()
    -- Folder labels intentionally use an accent color, but that accent can be
    -- almost identical to the selection/hover fill in some REAPER themes.
    -- Keep the configured label color at rest and move only the interaction
    -- fills far enough away from the active text color to remain legible.
    local header = EnsureColorContrast(
        palette.selection, text_color, 96)
    local hovered = EnsureColorContrast(
        palette.header_hover, text_color, 96)
    local active = EnsureColorContrast(
        palette.header_active, text_color, 96)
    imgui.PushStyleColor(ctx, imgui.Col_Text, text_color)
    imgui.PushStyleColor(ctx, imgui.Col_HeaderHovered, hovered)
    imgui.PushStyleColor(ctx, imgui.Col_HeaderActive, active)
    if selected then imgui.PushStyleColor(ctx, imgui.Col_Header, header) end
    return selected and 4 or 3
end

function PopBrowserFolderRowStyle(count)
    imgui.PopStyleColor(ctx, count or 3)
end

function DrawBrowserFolderTreeNode(label, flags, selected)
    local count = PushBrowserFolderRowStyle(selected == true)
    local open = imgui.TreeNode(ctx, label, flags or FLG_SPAN_WIDTH)
    PopBrowserFolderRowStyle(count)
    return open
end

function ResolveREAPERThemePalette()
    local c = state.theme.colors
    local use_custom = state.theme.use_custom
    local now = r.time_precise()
    local cached = state._resolved_theme_cache
    if use_custom then
        if cached and cached.use_custom == true
            and cached.window_bg == c.window_bg
            and cached.panel_bg == c.panel_bg
            and cached.text == c.text
            and cached.selected_text == c.selected_text
            and cached.accent == c.accent
            and cached.border == c.border
            and cached.folder_text == c.folder_text then
            state.resolved_theme = cached.resolved
            return cached
        end
    elseif cached and cached.use_custom == false
        and now < (cached.refresh_at or 0) then
        state.resolved_theme = cached.resolved
        return cached
    end

    local window_bg = use_custom and c.window_bg or GetREAPERThemeColor("col_main_bg2", 0x2B2B2BFF)
    local panel_bg  = use_custom and c.panel_bg  or GetREAPERThemeColor("genlist_bg", 0x333333FF)
    local text_col  = use_custom and c.text      or GetREAPERThemeColor("genlist_fg", 0xE0E0E0FF)
    local border_col = use_custom and c.border   or AdjustColor(panel_bg, -0.3)
    local auto_accent, _, auto_folders = GetREAPERAccentPalette()
    local accent_col = use_custom and c.accent or auto_accent
    local list_selection = accent_col
    local btn_bg     = use_custom and AdjustColor(panel_bg, 0.25) or GetREAPERThemeColor("col_buttonbg", 0x555555FF)

    if not use_custom then
        -- Use REAPER's main background as the dark/light authority. Hybrid
        -- themes often expose generic-list colors from the opposite mode.
        local main_is_light = ColorLuminance(window_bg) >= 145
        if main_is_light then
            panel_bg = ColorLuminance(panel_bg) < 145
                and AdjustColor(window_bg, -0.07)
                or BlendColor(panel_bg, window_bg, 0.28)
        else
            panel_bg = ColorLuminance(panel_bg) >= 145
                and AdjustColor(window_bg, 0.07)
                or BlendColor(panel_bg, window_bg, 0.28)
        end
        text_col = EnsureReadableText(text_col, panel_bg, 100)
        border_col = ColorLuminance(panel_bg) >= 128
            and AdjustColor(panel_bg, -0.28)
            or AdjustColor(panel_bg, 0.28)
        btn_bg = main_is_light and AdjustColor(panel_bg, -0.14)
            or AdjustColor(panel_bg, 0.16)
        accent_col = EnsureColorContrast(accent_col, panel_bg, 68)
        list_selection = accent_col
    end
    local disabled_col = use_custom and AdjustColor(text_col, -0.4)
        or EnsureReadableText(GetREAPERThemeColor("col_main_text2", 0xAAAAAAFF), panel_bg, 58)
    local frame_bg = use_custom and AdjustColor(panel_bg, 0.15)
        or (ColorLuminance(panel_bg) >= 145
            and AdjustColor(panel_bg, -0.08)
            or AdjustColor(panel_bg, 0.10))
    local selected_text_col = use_custom and c.selected_text
        or EnsureReadableText(
            GetREAPERThemeColor("genlist_selfg", 0xFFFFFFFF),
            accent_col, 105)
    local folder_text_col = use_custom and c.folder_text
        or EnsureColorContrast(auto_folders, panel_bg, 86)
    local resolved = {
        window_bg = window_bg,
        panel_bg = panel_bg,
        text = text_col,
        button_bg = btn_bg,
        frame_bg = frame_bg,
        accent = accent_col,
        selected_text = selected_text_col,
        folder_text = folder_text_col,
        is_light = ColorLuminance(window_bg) >= 145,
    }
    cached = {
        use_custom = use_custom,
        window_bg = c.window_bg,
        panel_bg = c.panel_bg,
        text = c.text,
        selected_text = c.selected_text,
        accent = c.accent,
        border = c.border,
        folder_text = c.folder_text,
        refresh_at = use_custom and math.huge or (now + 1.0),
        resolved = resolved,
        border = border_col,
        disabled = disabled_col,
        selection = list_selection,
        popup = resolved.is_light
            and AdjustColor(window_bg, -0.035)
            or AdjustColor(window_bg, 0.045),
        button_hover = AdjustColor(btn_bg, 0.2),
        header_hover = AdjustColor(list_selection, 0.15),
        header_active = AdjustColor(list_selection, 0.3),
        slider_active = AdjustColor(accent_col, 0.2),
    }
    state._resolved_theme_cache = cached
    state.resolved_theme = resolved
    return cached
end

function PushREAPERTheme()
    state._theme_push_count = 0
    local function PushCol(col, val)
        if pcall(imgui.PushStyleColor, ctx, col, val) then
            state._theme_push_count = state._theme_push_count + 1
        end
    end
    local palette = ResolveREAPERThemePalette()
    local resolved = palette.resolved
    local window_bg = resolved.window_bg
    local panel_bg = resolved.panel_bg
    local text_col = resolved.text
    local btn_bg = resolved.button_bg
    local frame_bg = resolved.frame_bg
    local accent_col = resolved.accent
    local border_col = palette.border
    local disabled_col = palette.disabled
    local list_selection = palette.selection
    PushCol(imgui.Col_WindowBg, window_bg)
    PushCol(imgui.Col_ChildBg, panel_bg)
    -- Lift popups slightly away from the main canvas so long context menus are
    -- easier to scan without looking like another browser panel.
    PushCol(imgui.Col_PopupBg, palette.popup)
    PushCol(imgui.Col_Text, text_col)
    PushCol(imgui.Col_TextDisabled, disabled_col)
    PushCol(imgui.Col_TextSelectedBg, list_selection)
    PushCol(imgui.Col_FrameBg, frame_bg)
    
    PushCol(imgui.Col_Button, btn_bg)
    PushCol(imgui.Col_ButtonHovered, palette.button_hover)
    PushCol(imgui.Col_ButtonActive, accent_col)
    
    PushCol(imgui.Col_Border, border_col)
    PushCol(imgui.Col_Separator, border_col)
    
    PushCol(imgui.Col_Header, list_selection)
    PushCol(imgui.Col_HeaderHovered, palette.header_hover)
    PushCol(imgui.Col_HeaderActive, palette.header_active)
    PushCol(imgui.Col_FrameBgHovered, accent_col)
    PushCol(imgui.Col_FrameBgActive, accent_col)
    PushCol(imgui.Col_CheckMark, accent_col)
    PushCol(imgui.Col_SliderGrab, accent_col)
    PushCol(imgui.Col_SliderGrabActive, palette.slider_active)

    state._theme_var_count = 0
    local function PushVar(var, val, val2)
        local ok
        if val2 ~= nil then
            ok = pcall(imgui.PushStyleVar, ctx, var, val, val2)
        else
            ok = pcall(imgui.PushStyleVar, ctx, var, val)
        end
        if ok then state._theme_var_count = state._theme_var_count + 1 end
    end
    PushVar(imgui.StyleVar_WindowRounding, 4)
    PushVar(STYLE_POPUP_ROUNDING, 6)
    PushVar(STYLE_POPUP_BORDER_SIZE, 1)
    PushVar(imgui.StyleVar_ChildRounding, 4)
    PushVar(imgui.StyleVar_FrameRounding, 5)
    PushVar(imgui.StyleVar_FrameBorderSize, 1)
    PushVar(imgui.StyleVar_FramePadding, 5, 3)
    PushVar(imgui.StyleVar_ItemSpacing, 5, 4)
    PushVar(imgui.StyleVar_WindowPadding, 4, 3)
end

function PopREAPERTheme()
    if state._theme_push_count > 0 then imgui.PopStyleColor(ctx, state._theme_push_count) end
    if state._theme_var_count > 0 then imgui.PopStyleVar(ctx, state._theme_var_count) end
end

-- ============================================================
-- FONT MANAGEMENT
-- ============================================================
function RebuildFont()
    local ok, new_font = pcall(imgui.CreateFont, state.theme.font_name, state.theme.font_size)
    local built_name = state.theme.font_name
    if not ok or not new_font then
        ok, new_font = pcall(imgui.CreateFont, "sans-serif", state.theme.font_size)
        built_name = "sans-serif"
    end
    -- If neither requested nor generic font can be created, leave state.font
    -- unset so ReaImGui naturally uses its built-in default font.
    if not ok or not new_font then
        state.font = nil
        state.font_built_name = state.theme.font_name
        state.font_built_size = state.theme.font_size
        return
    end

    local attach_ok = pcall(imgui.Attach, ctx, new_font)
    if not attach_ok and built_name ~= "sans-serif" then
        ok, new_font = pcall(imgui.CreateFont, "sans-serif", state.theme.font_size)
        built_name = "sans-serif"
        attach_ok = ok and new_font and pcall(imgui.Attach, ctx, new_font)
    end
    if not attach_ok then
        state.font = nil
        state.font_built_name = state.theme.font_name
        state.font_built_size = state.theme.font_size
        return
    end

    local old_font = state.font
    local old_star_font = state.star_font
    local old_favorite_font = state.favorite_font
    state.font = new_font
    state.font_built_name = state.theme.font_name
    state.font_built_size = state.theme.font_size

    if old_font then pcall(imgui.Detach, ctx, old_font) end
    local star_ok, star_font = pcall(imgui.CreateFont, "sans-serif", state.theme.font_size + 7)
    if star_ok and star_font and pcall(imgui.Attach, ctx, star_font) then
        state.star_font = star_font
    else
        state.star_font = nil
    end
    local favorite_ok, favorite_font =
        pcall(imgui.CreateFont, "sans-serif", state.theme.font_size + 12)
    if favorite_ok and favorite_font
        and pcall(imgui.Attach, ctx, favorite_font) then
        state.favorite_font = favorite_font
    else
        state.favorite_font = nil
    end
    if old_star_font then pcall(imgui.Detach, ctx, old_star_font) end
    if old_favorite_font then pcall(imgui.Detach, ctx, old_favorite_font) end
end

function EnsureFontUpToDate()
    if state.theme.font_name ~= state.font_built_name or state.theme.font_size ~= state.font_built_size then
        RebuildFont()
    end
end

function FlushPendingFontSize()
    local requested = state.pending_font_size
    if requested == nil or imgui.IsMouseDown(ctx, 0) then return end
    state.pending_font_size = nil
    requested = math.max(10, math.min(28, math.floor(requested + 0.5)))
    if requested == state.theme.font_size then return end

    -- Apply only after the current frame has popped the old font. Calling the
    -- full SaveSettings path from the clicked widget repeats dozens of durable
    -- ExtState writes and can freeze every ReaImGui script in REAPER.
    state.theme.font_size = requested
    r.SetExtState(
        EXT_SECTION, "theme_font_size", tostring(requested), true)
end

-- ============================================================
-- FILE SYSTEM BROWSER
-- ============================================================
function ScanFolder(path, depth, parent)
    if depth > MAX_LIBRARY_SCAN_DEPTH then return nil end
    local fname = GetFileName(path)
    local result = { name = fname, name_lower = fname:lower(), path = path, is_folder = true, children = {}, files = {}, depth = depth, parent = parent }
    
    local i = 0
    while true do
        local folder = r.EnumerateSubdirectories(path, i)
        if not folder then break end
        if folder:lower() ~= "__macosx" then
            local child = ScanFolder(path:gsub("[/\\]+$", "") .. "/" .. folder, depth + 1, result)
            if child and (#child.children > 0 or #child.files > 0) then table.insert(result.children, child) end
        end
        i = i + 1
    end

    i = 0
    while true do
        local file = r.EnumerateFiles(path, i)
        if not file then break end
        if IsBrowserMediaFile(file) then
            local full_path = path:gsub("[/\\]+$", "") .. "/" .. file
            table.insert(result.files, {
                name = file,
                name_lower = file:lower(),
                path = full_path,
                is_folder = false,
                media_kind = IsMidiFile(file) and "midi" or "audio",
                parent = result
            })
        end
        i = i + 1
    end

    table.sort(result.children, function(a, b) return a.name:lower() < b.name:lower() end)
    table.sort(result.files, function(a, b) return a.name:lower() < b.name:lower() end)
    return result
end

local FinishCanonicalScanManifest
local WriteCanonicalManifestFolder

function GetLibraryCacheFilePath()
    return GetReaBrowseDataDirectory() .. "/ReaBrowse_Library_Cache.tsv"
end

local function SortAndPruneLibraryNode(node)
    for i = #node.children, 1, -1 do
        local child = node.children[i]
        SortAndPruneLibraryNode(child)
        if #child.children == 0 and #child.files == 0 then
            table.remove(node.children, i)
        end
    end
    table.sort(node.children, function(a, b) return a.name_lower < b.name_lower end)
    table.sort(node.files, function(a, b) return a.name_lower < b.name_lower end)
end

local function StartLibraryFinalize()
    local scan = state.library_scan
    scan.phase = "finalize"
    scan.phase_started_at = r.time_precise()
    scan.phase_label = "Finalizing scan manifest"
    scan.phase_done = 0
    scan.phase_total = scan.discovered_folders or 0
    scan.finalize_stack = {}
    scan.finalized_folders = 0
    scan.finalize_total = scan.discovered_folders or 0
    for index = #scan.roots, 1, -1 do
        scan.finalize_stack[#scan.finalize_stack + 1] = {
            node = scan.roots[index], visited = false
        }
    end
end

local function FinishLibraryScan()
    local scan = state.library_scan
    local incremental_root = scan.incremental_root
    local completed_roots = scan.roots or {}
    local sync = state.canonical_scan_sync
    -- Canonical browsing must never publish a half-finished replacement tree.
    -- Keep generation N visible until SQLite commits generation N+1; the
    -- finalize path reloads canonical roots after that atomic handoff. The
    -- legacy fallback still needs its in-memory replacement here.
    if not state.database.canonical then
        if incremental_root then
            local root_key = NormalizeFavoritePath(incremental_root)
            for index = #state.folder_tree, 1, -1 do
                if NormalizeFavoritePath(state.folder_tree[index].path)
                    == root_key then
                    table.remove(state.folder_tree, index)
                end
            end
            for _, root in ipairs(completed_roots) do
                state.folder_tree[#state.folder_tree + 1] = root
            end
        else
            state.folder_tree = completed_roots
        end
    end
    scan.current = nil
    scan.incremental_root = nil
    scan.configured_root_keys = {}
    scan.finalize_stack = nil
    scan.tree_replaced = true
    BuildFavoriteTree()
    if incremental_root then
        AppendMediaFilterIndexRoots(completed_roots)
    else
        StartMediaFilterIndexBuild()
    end
    state.force_search_update = true
    state.needs_visible_update = true

    -- Build the favorite-preservation lookup incrementally.  This keeps the
    -- preparation phase visible and prevents a large post-scan tree walk from
    -- looking like a frozen browser.
    sync.scanned_root_keys = {}
    sync.scanned_folder_keys = {}
    sync.favorite_file_candidates = sync.favorite_file_candidates or {}
    sync.scanned_favorite_file_keys = sync.scanned_favorite_file_keys or {}
    scan.prepare_stack = {}
    for index = #completed_roots, 1, -1 do
        local root = completed_roots[index]
        sync.scanned_root_keys[NormalizeFavoritePath(root.path)] = true
        scan.prepare_stack[#scan.prepare_stack + 1] = root
    end
    scan.prepare_total = scan.discovered_folders or 0
    scan.prepared_folders = 0
    scan.prepare_incremental_root = incremental_root
    scan.prepare_completed_roots = completed_roots
    scan.phase = "prepare"
    scan.phase_started_at = r.time_precise()
    scan.phase_label = "Preparing database manifest"
    scan.phase_detail = nil
end

local function ProcessLibraryPrepare()
    local scan = state.library_scan
    local sync = state.canonical_scan_sync
    local stack = scan.prepare_stack or {}
    local profile = GetLibraryScanSpeedProfile()
    local deadline = r.time_precise() + profile.finalize_slice
    local budget = profile.finalize_budget
    while budget > 0 and r.time_precise() < deadline do
        local folder = table.remove(stack)
        if not folder then
            scan.prepare_stack = nil
            FinishCanonicalScanManifest(false)
            local manifest_ready = state.database.backend == "sqlite"
                and sync.ready
            if manifest_ready then
                -- The manifest is emitted by this process with tabs/newlines
                -- sanitized, and the worker/Lua file counts were already
                -- compared at EOF. The transaction's sync_assert performs the
                -- authoritative imported-row check. Re-reading ten million
                -- lines here added a complete pass without improving recovery.
                sync.validation = nil
                sync.validated = true
                sync.apply_requested = true
                scan.phase = "commit"
                scan.phase_started_at = r.time_precise()
                scan.phase_label = "Writing database"
                sync.status = string.format(
                    "Manifest ready: %d folders, %d files",
                    sync.folders or 0, sync.files or 0)
                if StartCanonicalScanImport
                    and not state.database.write_active then
                    StartCanonicalScanImport()
                end
            else
                scan.scanning = false
                scan.phase = nil
                scan.browser_blocked = false
                scan.operation_kind = nil
                sync.scanned_root_keys = {}
                sync.scanned_folder_keys = {}
                sync.favorite_file_candidates = {}
                sync.scanned_favorite_file_keys = {}
                -- The canonical SQLite runtime never reads the full-tree TSV
                -- during normal startup. Keep this cache for compatibility
                -- mode or when a manifest cannot be imported safely.
                SaveLibraryCache()
                CompleteMediaDatabaseScan()
            end
            return
        end
        sync.scanned_folder_keys[NormalizeFavoritePath(folder.path)] = true
        for _, child in ipairs(folder.children or {}) do
            stack[#stack + 1] = child
        end
        for _, file in ipairs(folder.files or {}) do
            local file_key = NormalizeFavoritePath(file.path)
            if sync.favorite_file_candidates[file_key] then
                sync.scanned_favorite_file_keys[file_key] = true
            end
        end
        scan.prepared_folders = (scan.prepared_folders or 0) + 1
        budget = budget - 1
    end
end

local function ProcessLibraryManifestValidation()
    local scan = state.library_scan
    local sync = state.canonical_scan_sync
    local validation = sync.validation
    if not validation then
        scan.phase = "prepare"
        return
    end
    if not validation.file then
        validation.file = io.open(sync.manifest_path or "", "r")
        if not validation.file then
            sync.error = "The completed scan change file is unavailable."
            sync.status = sync.error
            validation.malformed = 1
        else
            local header = validation.file:read("*l")
            validation.lines = 1
            validation.header_ok = header
                == "kind\tpath\tpath_norm\tname\tparent_path\tparent_norm"
                    .. "\tmedia_type\tfile_size\tmodified_at\tchanged"
                    .. "\ttags\tclassification"
                    .. "\tclassification_source\tclassification_confidence\tkey_pc"
                    .. "\troot_norm"
        end
    end
    if not validation.file then
        sync.validated = false
        sync.validation = nil
        scan.scanning = false
        scan.phase = nil
        scan.browser_blocked = false
        scan.operation_kind = nil
        sync.scanned_root_keys = {}
        sync.scanned_folder_keys = {}
        sync.favorite_file_candidates = {}
        sync.scanned_favorite_file_keys = {}
        SaveLibraryCache()
        CompleteMediaDatabaseScan()
        scan.queue = {}
        scan.roots = {}
        scan.current = nil
        scan.retain_file_nodes = nil
    else
        local profile = GetLibraryScanSpeedProfile()
        local deadline = r.time_precise() + profile.finalize_slice
        local budget = profile.finalize_budget
        while budget > 0 and r.time_precise() < deadline do
            local line = validation.file:read("*l")
            if not line then
                validation.file:close()
                validation.file = nil
                local valid = validation.header_ok
                    and validation.malformed == 0
                    and validation.folders == (sync.folders or 0)
                    and validation.files == (sync.files or 0)
                sync.validated = valid
                sync.error = valid and nil or "Scan manifest validation failed."
                sync.status = valid
                    and string.format("Scan manifest validated: %d folders, %d files",
                        validation.folders, validation.files)
                    or string.format(
                        "Scan manifest validation failed: found %d folders, %d files",
                        validation.folders, validation.files)
                sync.validation = nil
                if valid then
                    scan.phase = "commit"
                    scan.phase_started_at = r.time_precise()
                    scan.phase_label = "Writing database"
                    sync.apply_requested = true
                    if StartCanonicalScanImport
                        and not state.database.write_active then
                        StartCanonicalScanImport()
                    end
                else
                    scan.scanning = false
                    scan.phase = nil
                    scan.browser_blocked = false
                    scan.operation_kind = nil
                    sync.scanned_root_keys = {}
                    sync.scanned_folder_keys = {}
                    sync.favorite_file_candidates = {}
                    sync.scanned_favorite_file_keys = {}
                    SaveLibraryCache()
                    CompleteMediaDatabaseScan()
                end
                return
            end
            validation.lines = validation.lines + 1
            local _, tab_count = line:gsub("\t", "")
            if tab_count ~= 15 then validation.malformed = validation.malformed + 1 end
            if line:sub(1, 2) == "D\t" then
                validation.folders = validation.folders + 1
            elseif line:sub(1, 2) == "F\t" then
                validation.files = validation.files + 1
            end
            budget = budget - 1
        end
    end
end

local function ProcessLibraryDatabaseFinalize()
    local scan = state.library_scan
    local database = state.database
    local browser = state.canonical_browser
    local paging = state.canonical_paging
    if database.worker_restart_pending or database.worker_prewarm_requested
        or database.worker_refresh_requested then
        scan.phase_detail = "Refreshing database worker"
        scan.phase_done = 0.2
        return
    end
    if database.worker_started and not IsDatabaseWorkerReady() then
        local now = r.time_precise()
        if not database.worker_unready_since then
            database.worker_unready_since = math.min(
                now, database.worker_started_at or now)
        end
        local worker_start_elapsed = math.max(
            0, now - database.worker_unready_since)
        if worker_start_elapsed > 10 then
            -- Do not leave a completed database scan in an infinite wait if
            -- the helper was missing or exited before publishing a heartbeat.
            -- Subsequent browser requests can use the SQLite CLI fallback.
            database.worker_started = false
            database.worker_started_at = nil
            database.worker_unready_since = nil
            database.worker_status =
                "Database worker did not become ready; using SQLite fallback."
        else
            scan.phase_detail = string.format(
                "Warming database worker (%.0f s)", worker_start_elapsed)
            scan.phase_done = 0.45
            return
        end
    else
        database.worker_unready_since = nil
    end
    if database.write_active then
        scan.phase_detail = "Waiting for database writes to finish"
        scan.phase_done = 0.6
        return
    end
    if browser.accordion_loading or paging.active then
        scan.phase_detail = "Loading root navigation"
        scan.phase_done = 0.8
        return
    end
    if browser.deferred_request then
        scan.phase_detail = "Applying final navigation request"
        scan.phase_done = 0.9
        return
    end
    scan.phase_done = 1
    scan.phase_detail = browser.accordion_error
        and "Navigation ready with a database warning"
        or "Database and navigation ready"
    scan.scanning = false
    scan.phase = nil
    scan.browser_blocked = false
    scan.operation_kind = nil
    scan.tree_replaced = false
    scan.previous_folder_tree = nil
    scan.newly_added_root = nil
    scan.queue = {}
    scan.roots = {}
    scan.current = nil
    scan.retain_file_nodes = nil
    state.canonical_scan_sync.progress_path = nil
    state.canonical_scan_sync.scanned_root_keys = {}
    state.canonical_scan_sync.scanned_folder_keys = {}
    state.canonical_scan_sync.favorite_file_candidates = {}
    state.canonical_scan_sync.scanned_favorite_file_keys = {}
    if state.canonical_scan_sync.restored_user_data_path then
        pcall(os.remove,
            state.canonical_scan_sync.restored_user_data_path)
        state.canonical_scan_sync.restored_user_data_path = nil
    end
end

local function ProcessLibraryFinalize()
    local scan = state.library_scan
    local profile = GetLibraryScanSpeedProfile()
    local stack = scan.finalize_stack
    local deadline = r.time_precise() + profile.finalize_slice
    local budget = profile.finalize_budget
    while budget > 0 and r.time_precise() < deadline do
        local work = table.remove(stack)
        if not work then
            FinishLibraryScan()
            return
        end
        local node = work.node
        if not work.visited then
            stack[#stack + 1] = {node = node, visited = true}
            for index = #node.children, 1, -1 do
                stack[#stack + 1] = {
                    node = node.children[index], visited = false
                }
            end
        else
            for index = #node.children, 1, -1 do
                local child = node.children[index]
                if #child.children == 0 and #child.files == 0
                    and not child._scan_has_media then
                    table.remove(node.children, index)
                end
            end
            table.sort(node.children,
                function(a, b) return a.name_lower < b.name_lower end)
            table.sort(node.files,
                function(a, b) return a.name_lower < b.name_lower end)
            -- Persist folders only after empty/unsupported branches have
            -- been pruned. Writing them during discovery caused directories
            -- with no browser media to reappear as apparently broken rows
            -- after the canonical database was reloaded.
            WriteCanonicalManifestFolder(node)
            scan.finalized_folders = (scan.finalized_folders or 0) + 1
        end
        budget = budget - 1
    end
end

local function CacheSafePath(path)
    return (path or ""):gsub("[\t\r\n]", " ")
end

function SaveLibraryCache()
    -- SQLite is the only supported Library backend. Keep the legacy writer
    -- dormant until its remaining compatibility-only callers are removed.
    if state.database.backend ~= "tsv" then return false end
    EnsureReaBrowseDataLayout()
    local save = state.library_cache_save
    if save.file then save.file:close() end
    local target_path = GetLibraryCacheFilePath()
    local temp_path = target_path .. ".writing"
    pcall(os.remove, temp_path)
    local file = io.open(temp_path, "w")
    if not file then return false end
    file:write("REABROWSE_LIBRARY_CACHE\t3\n")
    for _, root in ipairs(state.root_folders) do
        file:write("R\t", CacheSafePath(root), "\n")
    end
    file:write("BEGIN\n")
    save.active = true
    save.file = file
    save.temp_path = temp_path
    save.target_path = target_path
    save.stack = {}
    for index = #state.folder_tree, 1, -1 do
        save.stack[#save.stack + 1] = {
            kind = "root", value = state.folder_tree[index]
        }
    end
    return true
end

function ProcessLibraryCacheSave()
    local save = state.library_cache_save
    if not save.active or not save.file then return end
    local budget = 500
    local deadline = r.time_precise() + 0.003
    while budget > 0 and r.time_precise() < deadline do
        local work = table.remove(save.stack)
        if not work then
            save.file:close()
            save.file = nil
            save.active = false
            local backup_path = save.target_path .. ".previous"
            pcall(os.remove, backup_path)
            os.rename(save.target_path, backup_path)
            local renamed = os.rename(save.temp_path, save.target_path)
            if renamed then
                pcall(os.remove, backup_path)
            else
                os.rename(backup_path, save.target_path)
                pcall(os.remove, save.temp_path)
            end
            return
        end
        if work.kind == "node" or work.kind == "root" then
            local node = work.value
            save.file:write(
                work.kind == "root" and "T\t" or "D\t",
                CacheSafePath(node.path), "\n")
            for index = #node.files, 1, -1 do
                save.stack[#save.stack + 1] = {
                    kind = "file", value = node.files[index]
                }
            end
            for index = #node.children, 1, -1 do
                save.stack[#save.stack + 1] = {
                    kind = "node", value = node.children[index]
                }
            end
        else
            local entry = work.value
            local names = {}
            for _, tag in ipairs(EnsureGeneratedTags(entry)) do
                names[#names + 1] = tag.source .. ":" .. tag.name
            end
            save.file:write("F\t", CacheSafePath(entry.path), "\t",
                table.concat(names, "|"), "\n")
        end
        budget = budget - 1
    end
end

function LoadLibraryCache()
    local file = io.open(GetLibraryCacheFilePath(), "r")
    if not file then return false end
    local header = file:read("*l")
    local cache_version = tonumber(header and header:match(
        "^REABROWSE_LIBRARY_CACHE\t(%d+)$"))
    if cache_version ~= 1 and cache_version ~= 2
        and cache_version ~= 3 then
        file:close()
        return false
    end

    local cached_roots = {}
    local first_entry = nil
    while true do
        local line = file:read("*l")
        if not line then file:close(); return false end
        if line == "BEGIN" then break end
        local kind, path = line:match("^([^\t]+)\t(.*)$")
        if kind ~= "R" then file:close(); return false end
        cached_roots[#cached_roots + 1] = path
    end
    if #cached_roots ~= #state.root_folders then file:close(); return false end
    for i, root in ipairs(state.root_folders) do
        if NormalizeFavoritePath(root) ~= NormalizeFavoritePath(cached_roots[i]) then
            file:close()
            return false
        end
    end

    local roots, nodes, root_keys = {}, {}, {}
    local cached_tag_counts = {}
    for _, root in ipairs(cached_roots) do
        root_keys[NormalizeFavoritePath(root)] = true
    end
    for line in file:lines() do
        local kind, path, generated_text
        if line:sub(1, 2) == "F\t" then
            kind, path, generated_text = line:match("^([F])\t([^\t]*)\t?(.*)$")
        else
            kind, path = line:match("^([DT])\t(.*)$")
        end
        if (kind == "D" or kind == "T") and path and path ~= "" then
            local normalized = path:gsub("\\", "/"):gsub("/+$", "")
            local parent_path = normalized:match("^(.*)/[^/]+$")
            local path_key = NormalizeFavoritePath(path)
            local explicit_root = cache_version >= 3 and kind == "T"
            local parent = not explicit_root
                and not (cache_version < 3 and root_keys[path_key])
                and parent_path and nodes[NormalizeFavoritePath(parent_path)]
                or nil
            local name = GetFileName(path)
            local node = {
                name = name, name_lower = name:lower(), path = path,
                is_folder = true, children = {}, files = {},
                depth = parent and ((parent.depth or 0) + 1) or 0,
                parent = parent, _scan_complete = true
            }
            nodes[NormalizeFavoritePath(path)] = node
            if parent then
                parent.children[#parent.children + 1] = node
            else
                roots[#roots + 1] = node
            end
        elseif kind == "F" and path and path ~= "" then
            local normalized = path:gsub("\\", "/")
            local parent_path = normalized:match("^(.*)/[^/]+$")
            local parent = parent_path and nodes[NormalizeFavoritePath(parent_path)] or nil
            if parent then
                local name = GetFileName(path)
                local entry = {
                    name = name, name_lower = name:lower(), path = path,
                    is_folder = false,
                    media_kind = IsMidiFile(name) and "midi" or "audio",
                    parent = parent
                }
                if cache_version >= 2 then
                    entry.generated_tags = {}
                    local seen_cached_tags = {}
                    for packed in (generated_text or ""):gmatch("[^|]+") do
                        local source, tag = packed:match("^([^:]+):(.*)$")
                        if source and tag and tag ~= "" then
                            entry.generated_tags[#entry.generated_tags + 1] = {
                                source = source, name = tag,
                                confidence = source == "filename" and 0.9 or 0.75
                            }
                            local normalized_tag = NormalizeTag(tag)
                            if normalized_tag ~= ""
                                and not seen_cached_tags[normalized_tag] then
                                cached_tag_counts[normalized_tag] =
                                    (cached_tag_counts[normalized_tag] or 0) + 1
                                seen_cached_tags[normalized_tag] = true
                            end
                        end
                    end
                    for _, user_tag in ipairs(
                        GetMediaUserTags(path) or {}) do
                        local normalized_tag = NormalizeTag(user_tag)
                        if normalized_tag ~= ""
                            and not seen_cached_tags[normalized_tag] then
                            cached_tag_counts[normalized_tag] =
                                (cached_tag_counts[normalized_tag] or 0) + 1
                            seen_cached_tags[normalized_tag] = true
                        end
                    end
                end
                parent.files[#parent.files + 1] = entry
            end
        end
    end
    file:close()
    if #roots ~= #state.root_folders then return false end

    state.folder_tree = roots
    local cached_tags = {}
    for name, count in pairs(cached_tag_counts) do
        if not TAG_BAR_EXCLUDED[name] then
            cached_tags[#cached_tags + 1] = {name = name, count = count}
        end
    end
    table.sort(cached_tags, function(a, b) return a.name < b.name end)
    state.media_tag_bar.tags = cached_tags
    state.media_tag_bar.catalog_complete = true
    state.media_tag_bar.cache_key = nil
    BuildFavoriteTree()
    state.force_search_update = true
    state.needs_visible_update = true
    return true
end

-- Build a replacement tree incrementally. The first-ever scan publishes the
-- complete directory hierarchy before progressively adding files; later scans
-- keep the previous completed library visible until replacement is complete.
local function CanonicalManifestField(value)
    return (tostring(value or ""):gsub("[\t\r\n]", " "))
end

local function StartCanonicalScanManifest()
    local sync = state.canonical_scan_sync
    if sync.manifest_file then
        pcall(function() sync.manifest_file:close() end)
    end
    local data_dir = GetReaBrowseDataDirectory()
    if r.RecursiveCreateDirectory then
        r.RecursiveCreateDirectory(data_dir, 0)
    end
    local token = tostring(os.time()) .. "_"
        .. tostring(math.random(100000, 999999))
    local path = data_dir .. "/Pending_Scan_" .. token .. ".tsv"
    local file, err = io.open(path, "w")
    sync.manifest_path = path
    sync.manifest_file = file
    sync.roots = 0
    sync.folders = 0
    sync.files = 0
    sync.ready = false
    sync.validated = false
    sync.apply_requested = false
    sync.importing = false
    sync.progress_path = nil
    ClearDatabaseWriteProgress()
    sync.error = err and tostring(err) or nil
    sync.scanned_root_keys = {}
    sync.scanned_folder_keys = {}
    sync.favorite_file_candidates = {}
    sync.scanned_favorite_file_keys = {}
    sync.current_auto_tag_roots = {}
    if state.database.canonical and FileExists(GetCanonicalDatabasePath()) then
        local output = QueryDatabaseScalarAtPath(GetCanonicalDatabasePath(),
            "SELECT substr(meta.key,18) FROM app_meta AS meta WHERE meta.key LIKE "
                .. "'auto_tag_version:%' AND CAST(meta.value AS INTEGER)>="
                .. tostring(AUTO_TAG_VERSION)
                .. " AND (NOT EXISTS(SELECT 1 FROM roots JOIN folder_files "
                .. "ON folder_files.root_id=roots.id WHERE roots.path_norm="
                .. "substr(meta.key,18) AND folder_files.missing=0) OR EXISTS("
                .. "SELECT 1 FROM roots JOIN folder_files ON folder_files.root_id="
                .. "roots.id JOIN file_tags ON file_tags.file_id="
                .. "folder_files.file_id WHERE roots.path_norm=substr(meta.key,18) "
                .. "AND folder_files.missing=0 AND file_tags.source IN"
                .. "('filename','folder') LIMIT 1));")
        for root_key in tostring(output or ""):gmatch("[^\r\n]+") do
            sync.current_auto_tag_roots[NormalizeFavoritePath(root_key)] = true
        end
    end
    sync.status = file and "Capturing scan changes..."
        or "Could not capture database scan changes."
    if file then
        file:write(
            "kind\tpath\tpath_norm\tname\tparent_path\tparent_norm"
                .. "\tmedia_type\tfile_size\tmodified_at\tchanged"
                .. "\ttags\tclassification"
                .. "\tclassification_source\tclassification_confidence"
                .. "\tkey_pc\troot_norm\n")
    end
    return file ~= nil
end

WriteCanonicalManifestFolder = function(node)
    local sync = state.canonical_scan_sync
    local file = sync.manifest_file
    if not file or not node then return end
    local parent_path = node.parent and node.parent.path or ""
    file:write(table.concat({
        "D",
        CanonicalManifestField(node.path),
        CanonicalManifestField(NormalizeFavoritePath(node.path)),
        CanonicalManifestField(node.name),
        CanonicalManifestField(parent_path),
        CanonicalManifestField(
            parent_path ~= "" and NormalizeFavoritePath(parent_path) or ""),
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        CanonicalManifestField(node.scan_root_key or
            NormalizeFavoritePath(node.path)),
    }, "\t"), "\n")
    sync.folders = sync.folders + 1
    if parent_path == "" then sync.roots = sync.roots + 1 end
end

local function WriteCanonicalManifestFile(entry)
    local sync = state.canonical_scan_sync
    local file = sync.manifest_file
    if not file or not entry then return end
    local entry_key = NormalizeFavoritePath(entry.path)
    if sync.favorite_file_candidates
        and sync.favorite_file_candidates[entry_key] then
        sync.scanned_favorite_file_keys[entry_key] = true
    end
    local root_key = entry.parent and entry.parent.scan_root_key or ""
    -- A glossary/version change deliberately promotes otherwise unchanged
    -- entries into the delta once. Without this, the SQL retag path would see
    -- an empty packed-tag field and erase the old automatic tags.
    local change_kind = tostring(entry._scan_change_kind or "1")
    local changed = change_kind == "1"
        or not sync.current_auto_tag_roots[NormalizeFavoritePath(root_key)]
    if changed then change_kind = "1" end
    local packed = {}
    local automatic_class, classification_source,
        classification_confidence, detected_key_pc
    if changed then
        -- Scan-time tags are automatic associations. Do not call
        -- EnsureGeneratedTags here: its UI path lazily loads user exclusions
        -- from SQLite, which would launch one synchronous query for every new
        -- file before that file even exists in the database. Exclusions remain
        -- authoritative in every effective-tag SQL read model.
        detected_key_pc = DetectFileKeyPitchClass(entry.path, nil)
        entry.detected_key_pc = detected_key_pc
        automatic_class, classification_source,
            classification_confidence = ClassifyAutomaticMedia(
                entry.path, detected_key_pc, true)
        entry.automatic_classification = automatic_class
        for _, tag in ipairs(CollectGeneratedTags(entry) or {}) do
            packed[#packed + 1] = tostring(tag.source or "filename")
                .. ":" .. NormalizeTag(tag.name)
        end
    end
    file:write(table.concat({
        "F",
        CanonicalManifestField(entry.path),
        CanonicalManifestField(NormalizeFavoritePath(entry.path)),
        CanonicalManifestField(entry.name),
        CanonicalManifestField(entry.parent and entry.parent.path or ""),
        CanonicalManifestField(entry.parent
            and NormalizeFavoritePath(entry.parent.path) or ""),
        CanonicalManifestField(entry.media_kind),
        CanonicalManifestField(entry._scan_file_size),
        CanonicalManifestField(entry._scan_modified_at),
        change_kind,
        CanonicalManifestField(table.concat(packed, "|")),
        CanonicalManifestField(automatic_class),
        CanonicalManifestField(classification_source),
        CanonicalManifestField(classification_confidence),
        CanonicalManifestField(detected_key_pc),
        CanonicalManifestField(root_key),
    }, "\t"), "\n")
    sync.files = sync.files + 1
end

FinishCanonicalScanManifest = function(cancelled)
    local sync = state.canonical_scan_sync
    if sync.manifest_file then
        sync.manifest_file:flush()
        sync.manifest_file:close()
        sync.manifest_file = nil
    end
    if cancelled then
        if sync.manifest_path then pcall(os.remove, sync.manifest_path) end
        if sync.progress_path then pcall(os.remove, sync.progress_path) end
        if sync.validation and sync.validation.file then
            pcall(function() sync.validation.file:close() end)
        end
        sync.validation = nil
        ClearDatabaseWriteProgress()
        sync.manifest_path = nil
        sync.newly_added_root = nil
        sync.ready = false
        sync.validated = false
        sync.apply_requested = false
        sync.importing = false
        sync.scanned_root_keys = {}
        sync.scanned_folder_keys = {}
        sync.favorite_file_candidates = {}
        sync.scanned_favorite_file_keys = {}
        sync.status = "Cancelled scan changes were discarded."
        return
    end
    sync.ready = sync.manifest_path ~= nil and sync.error == nil
    sync.validation = nil
    sync.validated = false
    sync.apply_requested = false
    sync.importing = false
    sync.status = sync.ready and string.format(
        "Scan delta ready: %d folders, %d files",
        sync.folders, sync.files)
        or "Scan completed without a database change manifest."
end

StartCanonicalScanImport = function()
    local sync = state.canonical_scan_sync
    if not sync.validated or sync.importing
        or not sync.manifest_path
        or state.database.write_active then
        return false
    end
    local metrics = state.library_scan.scan_metrics or {}
    state.library_scan.scan_metrics = metrics
    metrics.prepare_seconds = math.max(0, r.time_precise()
        - (metrics.ingest_started_at or metrics.discovery_started_at
            or metrics.started_at or r.time_precise())
        - (metrics.ingest_seconds or 0))
    metrics.commit_started_at = r.time_precise()
    local manifest = sync.manifest_path:gsub("\\", "/"):gsub('"', '""')
    local now = os.time()
    local platform = r.GetOS() or ""
    local progress_path = GetReaBrowseDataDirectory() .. "/Scan_Progress_"
        .. tostring(now) .. "_" .. tostring(math.random(100000, 999999)) .. ".txt"
    sync.progress_path = progress_path
    pcall(os.remove, progress_path)
    state.database.write_progress_path = progress_path
    local progress_file = progress_path:gsub("\\", "/"):gsub('"', '""')
    local function progress(stage, done, total, label)
        return ".output \"" .. progress_file .. "\"\n"
            .. ".print RB_PROGRESS|" .. tostring(stage) .. "|"
            .. tostring(done or 0) .. "|" .. tostring(total or 0) .. "|"
            .. tostring(label or "") .. "\n.output stdout\n"
    end
    local restore_attach_sql, restore_pre_sql,
        restore_post_sql, restore_detach_sql = "", "", "", ""
    local user_backup = GetCanonicalUserDataBackupPath()
    if FileExists(user_backup) then
        restore_attach_sql = "ATTACH DATABASE " .. SQLQuote(user_backup)
            .. " AS preserved;\n"
        restore_pre_sql = table.concat({
            "INSERT OR IGNORE INTO collections(id,parent_id,name,created_at,sort_order) ",
            "VALUES(-1,NULL,'Favorites',strftime('%s','now'),0);\n",
            "CREATE TEMP TABLE restore_collection_map AS SELECT saved.*,",
            "(SELECT CASE WHEN COALESCE(max(id),0)>0 THEN max(id) ELSE 0 END ",
            "FROM collections)+row_number() OVER(",
            "ORDER BY saved.external_key) AS new_id FROM ",
            "preserved.saved_collections saved;\n",
            "INSERT OR IGNORE INTO collections(id,parent_id,name,created_at,sort_order) ",
            "SELECT new_id,NULL,name,created_at,sort_order FROM ",
            "restore_collection_map;\n",
            "INSERT OR IGNORE INTO collection_external_keys(collection_id,external_key) ",
            "SELECT new_id,external_key FROM restore_collection_map;\n",
            "UPDATE collections AS target SET parent_id=parent.new_id FROM ",
            "restore_collection_map child JOIN restore_collection_map parent ON ",
            "parent.external_key=child.parent_external_key WHERE ",
            "target.id=child.new_id;\n",
            "INSERT INTO user_file_data(file_id,favorite,notes,play_count,",
            "last_used_at,updated_at) SELECT files.id,saved.favorite,saved.notes,",
            "saved.play_count,saved.last_used_at,saved.updated_at FROM ",
            "preserved.saved_user_file_data saved JOIN files ON ",
            "files.canonical_path_norm=saved.path_norm WHERE 1 ",
            "ON CONFLICT(file_id) DO ",
            "UPDATE SET favorite=excluded.favorite,notes=excluded.notes,",
            "play_count=excluded.play_count,last_used_at=excluded.last_used_at,",
            "updated_at=excluded.updated_at;\n",
            "INSERT OR IGNORE INTO collection_items(collection_id,file_id,added_at) ",
            "SELECT CASE WHEN saved.collection_key='' THEN -1 ELSE map.new_id END,",
            "files.id,saved.added_at FROM preserved.saved_collection_items saved ",
            "JOIN files ON files.canonical_path_norm=saved.path_norm LEFT JOIN ",
            "restore_collection_map map ON map.external_key=saved.collection_key ",
            "WHERE saved.kind='file' AND (saved.collection_key='' OR map.new_id IS NOT NULL);\n",
            "INSERT OR IGNORE INTO collection_items(collection_id,root_id,folder_id,added_at) ",
            "SELECT CASE WHEN saved.collection_key='' THEN -1 ELSE map.new_id END,",
            "folders.root_id,folders.id,saved.added_at FROM ",
            "preserved.saved_collection_items saved JOIN roots ON ",
            "saved.path_norm=roots.path_norm OR substr(saved.path_norm,1,",
            "length(roots.path_norm)+1)=roots.path_norm||'/' JOIN folders ON ",
            "folders.root_id=roots.id AND folders.relative_path_norm=CASE WHEN ",
            "saved.path_norm=roots.path_norm THEN '' ELSE substr(saved.path_norm,",
            "length(roots.path_norm)+2) END LEFT JOIN restore_collection_map map ",
            "ON map.external_key=saved.collection_key WHERE saved.kind='folder' ",
            "AND (saved.collection_key='' OR map.new_id IS NOT NULL);\n",
            "INSERT OR IGNORE INTO tags(name,name_norm) SELECT min(name),name_norm ",
            "FROM preserved.saved_user_tags GROUP BY name_norm;\n",
            "INSERT OR IGNORE INTO file_tags(file_id,tag_id,source,confidence) ",
            "SELECT files.id,tags.id,'user',saved.confidence FROM ",
            "preserved.saved_user_tags saved JOIN files ON ",
            "files.canonical_path_norm=saved.path_norm JOIN tags ON ",
            "tags.name_norm=saved.name_norm;\n",
            "INSERT OR IGNORE INTO file_tag_exclusions(file_id,tag_norm,updated_at) ",
            "SELECT files.id,saved.tag_norm,saved.updated_at FROM ",
            "preserved.saved_exclusions saved JOIN files ON ",
            "files.canonical_path_norm=saved.path_norm;\n",
            "INSERT OR REPLACE INTO classification_overrides(scope_type,path_norm,",
            "classification,created_at,updated_at) SELECT scope_type,path_norm,",
            "classification,created_at,updated_at FROM preserved.saved_overrides;\n",
            "INSERT OR REPLACE INTO key_overrides(path_norm,key_pc,",
            "detected_key_pc,created_at,updated_at) SELECT path_norm,key_pc,",
            "detected_key_pc,created_at,updated_at FROM ",
            "preserved.saved_key_overrides;\n",
        })
        restore_post_sql = table.concat({
            -- User tags existed before scan_new_effective_tags was measured,
            -- so rebuild only this compact global read model once after a
            -- database reset restore.
            "DELETE FROM library_tag_counts;\n",
            "INSERT INTO library_tag_counts(tag_id,file_count) SELECT ",
            "file_tags.tag_id,count(DISTINCT file_tags.file_id) FROM file_tags ",
            "JOIN files ON files.id=file_tags.file_id JOIN tags ON ",
            "tags.id=file_tags.tag_id WHERE files.missing=0 AND NOT EXISTS(",
            "SELECT 1 FROM file_tag_exclusions WHERE file_tag_exclusions.file_id=",
            "file_tags.file_id AND file_tag_exclusions.tag_norm=tags.name_norm) ",
            "GROUP BY file_tags.tag_id;\n",
        })
        restore_detach_sql = "DETACH DATABASE preserved;\n"
        sync.restored_user_data_path = user_backup
    end
    local sql = table.concat({
        ".headers off\n.mode tabs\n",
        "PRAGMA foreign_keys=ON;\n",
        restore_attach_sql,
        "CREATE TEMP TABLE scan_delta(kind TEXT,path TEXT,path_norm TEXT,",
        "name TEXT,parent_path TEXT,parent_norm TEXT,media_type TEXT,",
        "file_size INTEGER,modified_at INTEGER,changed INTEGER,",
        "tags_text TEXT,classification TEXT,classification_source TEXT,",
        "classification_confidence REAL,key_pc INTEGER,root_norm TEXT);\n",
        progress("manifest", 0, 2, "Loading scan manifest"),
        '.import --skip 1 "', manifest, '" scan_delta\n',
        progress("manifest", 1, 2, "Indexing scan manifest"),
        "CREATE INDEX scan_delta_kind_path ON scan_delta(kind,path_norm);\n",
        "CREATE INDEX scan_delta_parent_kind_path ON scan_delta(",
        "parent_norm,kind,path_norm);\n",
        progress("manifest", 2, 2, "Scan manifest indexed"),
        progress("roots", 0, 1, "Updating library roots"),
        "BEGIN IMMEDIATE;\n",
        "INSERT INTO roots(identity,display_path,path_norm,platform,",
        "created_at,last_checked_at,enabled) ",
        "SELECT path_norm,path,path_norm,", SQLQuote(platform), ",",
        tostring(now), ",", tostring(now), ",1 FROM scan_delta ",
        "WHERE kind='D' AND parent_norm='' AND path_norm<>'' ",
        "ON CONFLICT(identity) DO UPDATE SET ",
        "display_path=excluded.display_path,platform=excluded.platform,",
        "last_checked_at=excluded.last_checked_at,enabled=1;\n",
        "CREATE TEMP TABLE scan_roots AS SELECT roots.id AS root_id,",
        "roots.path_norm AS root_norm,roots.display_path AS root_path ",
        "FROM roots JOIN scan_delta ON scan_delta.path_norm=roots.path_norm ",
        "WHERE scan_delta.kind='D' AND scan_delta.parent_norm='';\n",
        progress("roots", 1, 1, "Library roots updated"),
        progress("files", 0, sync.files or 0, "Writing media records"),
        -- Compare the filesystem manifest against the indexed active
        -- membership table; unchanged files never enter a write statement.
        "CREATE TEMP TABLE scan_new_paths AS SELECT DISTINCT delta.path_norm ",
        "FROM scan_delta AS delta WHERE delta.kind='F' AND NOT EXISTS(",
        "SELECT 1 FROM files WHERE files.canonical_path_norm=delta.path_norm);\n",
        "CREATE UNIQUE INDEX scan_new_paths_path ON scan_new_paths(path_norm);\n",
        "CREATE TEMP TABLE scan_changed_paths(path_norm TEXT PRIMARY KEY) ",
        "WITHOUT ROWID;\n",
        "INSERT OR IGNORE INTO scan_changed_paths SELECT path_norm FROM ",
        "scan_new_paths;\n",
        "INSERT OR IGNORE INTO scan_changed_paths SELECT path_norm FROM ",
        "scan_delta WHERE kind='F' AND changed=1;\n",
        "INSERT INTO files(canonical_path,canonical_path_norm,name,extension,",
        "media_type,file_size,modified_at,classification,automatic_classification,",
        "classification_source,classification_confidence,",
        "key_pc,metadata_version,missing,created_at,updated_at) ",
        "SELECT path,path_norm,name,lower(substr(name,length(rtrim(name,",
        "replace(name,'.','')))+1)),media_type,file_size,modified_at,",
        "CASE WHEN classification IN('loop','one-shot','midi','other') ",
        "THEN classification WHEN media_type='midi' THEN 'midi' ELSE 'other' END,",
        "CASE WHEN classification IN('loop','one-shot','midi','other') ",
        "THEN classification WHEN media_type='midi' THEN 'midi' ELSE 'other' END,",
        "COALESCE(NULLIF(classification_source,''),'uncategorized'),",
        "COALESCE(classification_confidence,0.0),",
        "CASE WHEN key_pc BETWEEN 0 AND 11 THEN key_pc ELSE NULL END,",
        "1,0,", tostring(now), ",", tostring(now),
        " FROM scan_delta WHERE kind='F' AND path_norm<>'' AND ",
        "path_norm IN(SELECT path_norm FROM scan_new_paths) GROUP BY path_norm;\n",
        -- Some pre-fingerprint databases already contain MIDI paths but mark
        -- every row as audio. Once size/mtime are backfilled those paths are
        -- fingerprint-unchanged forever, so changed-only updates can never
        -- repair them. Media type and extension come directly from the
        -- current discovery row and are safe to repair for any scanned file.
        -- Neither column participates in the FTS update trigger, and this
        -- deliberately leaves automatic tags untouched.
        "UPDATE files SET extension=CASE WHEN files.extension IS NULL OR ",
        "files.extension='' THEN lower(substr(delta.name,length(rtrim(",
        "delta.name,replace(delta.name,'.','')))+1)) ELSE files.extension END,",
        "media_type=CASE WHEN delta.media_type='midi' THEN 'midi' ELSE ",
        "files.media_type END,automatic_classification=CASE WHEN ",
        "delta.media_type='midi' THEN 'midi' ELSE ",
        "files.automatic_classification END,classification=CASE WHEN ",
        "delta.media_type='midi' THEN 'midi' ELSE files.classification END,",
        "classification_source=CASE WHEN delta.media_type='midi' THEN ",
        "'media type' ELSE files.classification_source END,",
        "classification_confidence=CASE WHEN delta.media_type='midi' THEN ",
        "1.0 ELSE files.classification_confidence END,missing=0,updated_at=",
        tostring(now), " FROM scan_delta AS delta WHERE delta.kind='F' AND ",
        "delta.path_norm=files.canonical_path_norm AND ((files.extension IS ",
        "NULL OR files.extension='') OR (delta.media_type='midi' AND ",
        "files.media_type<>'midi'));\n",
        "UPDATE files SET random_key=(random() & 0x7fffffffffffffff) "
            .. "WHERE random_key IS NULL AND canonical_path_norm IN("
            .. "SELECT path_norm FROM scan_new_paths);\n",
        -- A scan is a comparison, not a rewrite. Keep the FTS-covered path
        -- fields in their own statement so classification/key refreshes never
        -- fire the files_search_au trigger for an unchanged filename.
        "UPDATE files SET canonical_path=delta.path,name=delta.name,",
        "extension=lower(substr(delta.name,length(rtrim(delta.name,",
        "replace(delta.name,'.','')))+1)),updated_at=", tostring(now),
        " FROM scan_delta AS delta WHERE delta.kind='F' AND ",
        "delta.changed=1 AND delta.path_norm=files.canonical_path_norm AND (",
        "files.canonical_path IS NOT delta.path OR files.name IS NOT delta.name ",
        "OR files.extension IS NOT lower(substr(delta.name,length(rtrim(",
        "delta.name,replace(delta.name,'.','')))+1)));\n",
        -- Removing a root preserves canonical file rows because another root
        -- may still reference them. A later re-add refreshes only fields that
        -- actually changed; unchanged rows never enter a write statement.
        "UPDATE files SET file_size=delta.file_size,modified_at=delta.modified_at,",
        "missing=0,updated_at=", tostring(now),
        " FROM scan_delta AS delta WHERE delta.kind='F' AND delta.changed=1 ",
        "AND delta.path_norm=files.canonical_path_norm AND (files.file_size IS NOT ",
        "delta.file_size OR files.modified_at IS NOT delta.modified_at OR ",
        "files.missing<>0);\n",
        "UPDATE files SET media_type=delta.media_type,",
        "automatic_classification=CASE WHEN delta.media_type='midi' THEN 'midi' ",
        "WHEN delta.classification IN('loop','one-shot','other') THEN ",
        "delta.classification ELSE 'other' END,classification_source=COALESCE(",
        "NULLIF(delta.classification_source,''),'uncategorized'),",
        "classification_confidence=COALESCE(delta.classification_confidence,0.0),",
        "key_pc=CASE WHEN delta.key_pc BETWEEN 0 AND 11 THEN delta.key_pc ELSE ",
        "NULL END,missing=0,updated_at=", tostring(now),
        " FROM scan_delta AS delta WHERE delta.kind='F' AND ",
        "delta.changed=1 AND delta.path_norm=files.canonical_path_norm AND (",
        "files.media_type IS NOT ",
        "delta.media_type OR files.automatic_classification IS NOT CASE WHEN ",
        "delta.media_type='midi' THEN 'midi' WHEN delta.classification IN",
        "('loop','one-shot','other') THEN delta.classification ELSE 'other' END ",
        "OR files.classification_source IS NOT COALESCE(NULLIF(",
        "delta.classification_source,''),'uncategorized') OR ",
        "files.classification_confidence IS NOT COALESCE(",
        "delta.classification_confidence,0.0) OR files.key_pc IS NOT CASE WHEN ",
        "delta.key_pc BETWEEN 0 AND 11 THEN delta.key_pc ELSE NULL END OR ",
        "files.missing<>0);\n",
        progress("files", sync.files or 0, sync.files or 0,
            "Media records written"),
        progress("memberships", 0, 10,
            "Resolving folder ownership"),
        "CREATE TEMP TABLE scan_folder_rows AS ",
        "SELECT delta.path,delta.path_norm,delta.name,delta.parent_norm,",
        "scan_roots.root_id,scan_roots.root_norm,scan_roots.root_path,",
        "CASE WHEN delta.path_norm=scan_roots.root_norm THEN '' ",
        "ELSE substr(delta.path,length(scan_roots.root_path)+2) END AS relative_path,",
        "CASE WHEN delta.path_norm=scan_roots.root_norm THEN '' ",
        "ELSE substr(delta.path_norm,length(scan_roots.root_norm)+2) END AS relative_path_norm ",
        "FROM scan_delta AS delta JOIN scan_roots ON ",
        "scan_roots.root_norm=delta.root_norm WHERE delta.kind='D';\n",
        progress("memberships", 1, 10,
            "Indexing folder paths"),
        "CREATE UNIQUE INDEX scan_folder_rows_path ON ",
        "scan_folder_rows(path_norm);\n",
        "CREATE INDEX scan_folder_rows_root_relative ON ",
        "scan_folder_rows(root_id,relative_path_norm);\n",
        progress("memberships", 2, 10,
            "Writing folder records"),
        "INSERT INTO folders(root_id,parent_id,name,relative_path,",
        "relative_path_norm,missing) SELECT root_id,NULL,name,relative_path,",
        "relative_path_norm,0 FROM scan_folder_rows WHERE 1 ",
        "ON CONFLICT(root_id,relative_path_norm) DO UPDATE SET ",
        "name=excluded.name,relative_path=excluded.relative_path,missing=0 ",
        "WHERE folders.name<>excluded.name OR folders.relative_path<>",
        "excluded.relative_path OR folders.missing<>0;\n",
        progress("memberships", 3, 10,
            "Resolving parent folders"),
        "CREATE TEMP TABLE scan_folder_parent_ids AS SELECT child.id AS ",
        "folder_id,parent.id AS parent_id FROM scan_folder_rows AS row ",
        "JOIN folders AS child ON child.root_id=row.root_id AND ",
        "child.relative_path_norm=row.relative_path_norm JOIN folders AS ",
        "parent ON parent.root_id=row.root_id AND parent.relative_path_norm=",
        "CASE WHEN row.parent_norm=row.root_norm THEN '' ELSE ",
        "substr(row.parent_norm,length(row.root_norm)+2) END ",
        "WHERE row.relative_path_norm<>'';\n",
        "CREATE UNIQUE INDEX scan_folder_parent_ids_folder ON ",
        "scan_folder_parent_ids(folder_id);\n",
        progress("memberships", 4, 10,
            "Applying parent links"),
        "UPDATE folders AS target SET parent_id=links.parent_id FROM ",
        "scan_folder_parent_ids AS links WHERE target.id=links.folder_id ",
        "AND target.parent_id IS NOT links.parent_id;\n",
        progress("memberships", 5, 10,
            "Resolving file locations"),
        "CREATE TEMP TABLE scan_file_rows AS SELECT DISTINCT folder_row.root_id,",
        "folder.id AS folder_id,files.id AS file_id,lower(files.name) AS name_sort,",
        "CASE WHEN files.canonical_path_norm=folder_row.root_norm THEN ",
        "files.name ELSE substr(files.canonical_path,",
        "length(folder_row.root_path)+2) END AS relative_path,",
        "CASE WHEN files.canonical_path_norm=folder_row.root_norm THEN ",
        "lower(files.name) ELSE substr(files.canonical_path_norm,",
        "length(folder_row.root_norm)+2) END AS relative_path_norm ",
        "FROM scan_delta AS delta ",
        "JOIN scan_folder_rows AS folder_row ",
        "ON folder_row.path_norm=delta.parent_norm ",
        "JOIN folders AS folder ON folder.root_id=folder_row.root_id ",
        "AND folder.relative_path_norm=folder_row.relative_path_norm ",
        "JOIN files ON files.canonical_path_norm=delta.path_norm ",
        "WHERE delta.kind='F';\n",
        "CREATE UNIQUE INDEX scan_file_rows_path ON scan_file_rows(",
        "root_id,relative_path_norm);\n",
        progress("memberships", 6, 10,
            "Comparing existing memberships"),
        "CREATE TEMP TABLE scan_added_locations AS SELECT current.root_id,",
        "current.folder_id,current.file_id,current.name_sort,current.relative_path,",
        "current.relative_path_norm FROM scan_file_rows AS current WHERE NOT ",
        "EXISTS(SELECT 1 FROM folder_files AS old WHERE old.missing=0 AND ",
        "old.root_id=current.root_id AND old.relative_path_norm=",
        "current.relative_path_norm);\n",
        "CREATE TEMP TABLE scan_removed_locations AS SELECT old.root_id,",
        "old.folder_id,old.file_id,old.relative_path_norm FROM ",
        "folder_files AS old WHERE old.missing=0 AND old.root_id IN(SELECT ",
        "root_id FROM scan_roots) AND NOT EXISTS(SELECT 1 FROM ",
        "scan_file_rows AS current WHERE current.root_id=old.root_id AND ",
        "current.relative_path_norm=old.relative_path_norm);\n",
        -- Step 8 probes removals by membership identity, folder and file.
        -- Without these indexes a full-library refresh can rescan the entire
        -- removal delta once per canonical membership and appear hung.
        "CREATE UNIQUE INDEX scan_removed_locations_path ON ",
        "scan_removed_locations(root_id,relative_path_norm);\n",
        "CREATE INDEX scan_removed_locations_folder ON ",
        "scan_removed_locations(folder_id);\n",
        "CREATE INDEX scan_removed_locations_file ON ",
        "scan_removed_locations(file_id);\n",
        progress("memberships", 7, 10,
            "Applying added memberships"),
        "INSERT INTO folder_files(root_id,folder_id,file_id,name_sort,relative_path,",
        "relative_path_norm,missing) SELECT root_id,",
        "folder_id,file_id,name_sort,relative_path,relative_path_norm,0",
        " FROM scan_added_locations WHERE 1 ON CONFLICT(root_id,",
        "relative_path_norm) DO UPDATE SET folder_id=excluded.folder_id,",
        "file_id=excluded.file_id,name_sort=excluded.name_sort,",
        "relative_path=excluded.relative_path,",
        "missing=0;\n",
        progress("memberships", 8, 10,
            "Removing stale memberships"),
        "CREATE TEMP TABLE scan_changed_folders AS SELECT folder_id FROM ",
        "scan_added_locations UNION SELECT folder_id FROM scan_removed_locations;\n",
        -- Capture removal effects while the old closure rows still exist.
        -- This lets subtree counts advance by delta instead of recounting all
        -- files below every scanned root.
        "CREATE TEMP TABLE scan_removed_stat_deltas AS SELECT ",
        "closure.ancestor_id AS folder_id,count(*) AS n FROM ",
        "scan_removed_locations removed JOIN folder_closure closure ON ",
        "closure.descendant_id=removed.folder_id GROUP BY closure.ancestor_id;\n",
        "UPDATE folders SET missing=1 WHERE root_id IN(SELECT root_id FROM ",
        "scan_roots) AND NOT EXISTS(SELECT 1 FROM scan_folder_rows AS seen ",
        "WHERE seen.root_id=folders.root_id AND seen.relative_path_norm=",
        "folders.relative_path_norm);\n",
        "DELETE FROM folder_files WHERE EXISTS(SELECT 1 FROM ",
        "scan_removed_locations AS removed WHERE removed.root_id=",
        "folder_files.root_id AND removed.relative_path_norm=",
        "folder_files.relative_path_norm);\n",
        "UPDATE files SET missing=1 WHERE id IN(SELECT file_id FROM ",
        "scan_removed_locations) AND NOT EXISTS(SELECT 1 FROM folder_files ",
        "WHERE folder_files.file_id=files.id AND folder_files.missing=0);\n",
        progress("memberships", 9, 10,
            "Pruning orphaned records"),
        "DELETE FROM folders WHERE missing=1 AND root_id IN(SELECT root_id ",
        "FROM scan_roots);\n",
        -- Preserve the effective tag contribution of canonical files that are
        -- about to become true orphans. Global tag counts can then be updated
        -- by delta instead of regrouping every file_tags row in the library.
        "CREATE TEMP TABLE scan_removed_effective_tags(file_id INTEGER,",
        "tag_id INTEGER,PRIMARY KEY(file_id,tag_id)) WITHOUT ROWID;\n",
        "INSERT INTO scan_removed_effective_tags SELECT DISTINCT files.id,",
        "file_tags.tag_id FROM files JOIN file_tags ON file_tags.file_id=files.id ",
        "JOIN tags ON tags.id=file_tags.tag_id WHERE files.missing=1 AND NOT ",
        "EXISTS(SELECT 1 FROM file_tag_exclusions WHERE ",
        "file_tag_exclusions.file_id=file_tags.file_id AND ",
        "file_tag_exclusions.tag_norm=tags.name_norm);\n",
        "DELETE FROM key_overrides WHERE path_norm IN(SELECT ",
        "canonical_path_norm FROM files WHERE missing=1);\n",
        "DELETE FROM files WHERE missing=1;\n",
        -- Rebuild materialized folder ancestry only for roots covered by this
        -- explicit scan. Interactive scope queries never recurse the tree.
        "DELETE FROM folder_closure WHERE root_id IN(SELECT root_id FROM ",
        "scan_roots);\n",
        "WITH RECURSIVE closure(root_id,ancestor_id,descendant_id,depth) AS (",
        "SELECT root_id,id,id,0 FROM folders WHERE missing=0 AND root_id IN(",
        "SELECT root_id FROM scan_roots) UNION ALL SELECT closure.root_id,",
        "closure.ancestor_id,child.id,closure.depth+1 FROM closure JOIN folders ",
        "AS child ON child.parent_id=closure.descendant_id WHERE child.missing=0) ",
        "INSERT INTO folder_closure(root_id,ancestor_id,descendant_id,depth) ",
        "SELECT root_id,ancestor_id,descendant_id,depth FROM closure;\n",
        "CREATE TEMP TABLE scan_added_stat_deltas AS SELECT ",
        "closure.ancestor_id AS folder_id,count(*) AS n FROM ",
        "scan_added_locations added JOIN folder_closure closure ON ",
        "closure.descendant_id=added.folder_id GROUP BY closure.ancestor_id;\n",
        "INSERT OR IGNORE INTO folder_subtree_stats(folder_id,file_count) ",
        "SELECT folders.id,0 FROM folders WHERE folders.root_id IN(",
        "SELECT root_id FROM scan_roots);\n",
        "UPDATE folder_subtree_stats AS stats SET file_count=max(0,",
        "stats.file_count+COALESCE((SELECT n FROM scan_added_stat_deltas ",
        "WHERE folder_id=stats.folder_id),0)-COALESCE((SELECT n FROM ",
        "scan_removed_stat_deltas WHERE folder_id=stats.folder_id),0)) WHERE ",
        "stats.folder_id IN(SELECT folder_id FROM scan_added_stat_deltas UNION ",
        "SELECT folder_id FROM scan_removed_stat_deltas);\n",
        progress("memberships", 10, 10,
            "Folder memberships updated"),
        progress("classification", 0, sync.files or 0,
            "Updating tags and classifications"),
        restore_pre_sql,
        -- Retag every scanned file once when the shipped glossary changes.
        -- Ordinary updates remain incremental after this version is recorded.
        "CREATE TEMP TABLE scan_tag_paths(path_norm TEXT PRIMARY KEY);\n",
        "INSERT OR IGNORE INTO scan_tag_paths SELECT path_norm FROM ",
        "scan_changed_paths;\n",
        "INSERT OR IGNORE INTO scan_tag_paths SELECT path_norm FROM scan_delta ",
        "WHERE kind='F' AND COALESCE((SELECT CAST(value AS INTEGER) FROM ",
        "app_meta WHERE key='auto_tag_version:'||scan_delta.root_norm),0)<",
        tostring(AUTO_TAG_VERSION), ";\n",
        "CREATE TEMP TABLE scan_old_effective_tags(file_id INTEGER,",
        "tag_id INTEGER,PRIMARY KEY(file_id,tag_id)) WITHOUT ROWID;\n",
        "INSERT INTO scan_old_effective_tags SELECT DISTINCT file_tags.file_id,",
        "file_tags.tag_id FROM scan_tag_paths JOIN files ON ",
        "files.canonical_path_norm=scan_tag_paths.path_norm JOIN file_tags ON ",
        "file_tags.file_id=files.id JOIN tags ON tags.id=file_tags.tag_id WHERE ",
        "NOT EXISTS(SELECT 1 FROM file_tag_exclusions WHERE ",
        "file_tag_exclusions.file_id=file_tags.file_id AND ",
        "file_tag_exclusions.tag_norm=tags.name_norm);\n",
        "INSERT INTO scan_changed_folders SELECT DISTINCT locations.folder_id ",
        "FROM folder_files AS locations JOIN files ON files.id=locations.file_id ",
        "JOIN scan_tag_paths ON scan_tag_paths.path_norm=files.canonical_path_norm ",
        "WHERE locations.missing=0;\n",
        "DELETE FROM file_tags WHERE source IN('filename','folder') ",
        "AND file_id IN(SELECT files.id FROM scan_tag_paths JOIN files ",
        "ON files.canonical_path_norm=scan_tag_paths.path_norm);\n",
        "CREATE TEMP TABLE scan_parsed_tags AS WITH RECURSIVE packed(",
        "file_id,rest,token) AS (SELECT files.id,scan_delta.tags_text||'|','' ",
        "FROM scan_delta JOIN scan_tag_paths ON scan_tag_paths.path_norm=",
        "scan_delta.path_norm JOIN files ON files.canonical_path_norm=",
        "scan_delta.path_norm WHERE scan_delta.kind='F' ",
        "AND scan_delta.tags_text<>'' UNION ALL SELECT file_id,",
        "substr(rest,instr(rest,'|')+1),substr(rest,1,instr(rest,'|')-1) ",
        "FROM packed WHERE rest<>''),parsed AS (SELECT file_id,",
        "lower(trim(substr(token,1,instr(token,':')-1))) AS source,",
        "trim(substr(token,instr(token,':')+1)) AS name,",
        "lower(trim(substr(token,instr(token,':')+1))) AS name_norm ",
        "FROM packed WHERE token<>'' AND instr(token,':')>1) ",
        "SELECT DISTINCT file_id,source,name,name_norm FROM parsed ",
        "WHERE name_norm<>'' AND source IN('filename','folder');\n",
        "INSERT OR IGNORE INTO tags(name,name_norm) SELECT min(name),name_norm ",
        "FROM scan_parsed_tags GROUP BY name_norm;\n",
        "INSERT OR IGNORE INTO file_tags(file_id,tag_id,source,confidence) ",
        "SELECT parsed.file_id,tags.id,parsed.source,",
        "CASE parsed.source WHEN 'filename' THEN 0.90 ELSE 0.75 END ",
        "FROM scan_parsed_tags AS parsed JOIN tags ",
        "ON tags.name_norm=parsed.name_norm;\n",
        -- Resolve otherwise ambiguous files from strong sibling agreement.
        -- This is a compact set-based pass over the scan transaction; it does
        -- not open media or add background work during ordinary browsing.
        "CREATE TEMP TABLE scan_folder_evidence AS SELECT ",
        "locations.folder_id,",
        "sum(files.automatic_classification='loop') AS loops,",
        "sum(files.automatic_classification='one-shot') AS shots,",
        "count(*) AS evidence_n FROM folder_files AS locations ",
        "JOIN files ON files.id=locations.file_id WHERE ",
        "locations.missing=0 AND files.missing=0 AND ",
        "locations.folder_id IN(SELECT folder_id FROM ",
        "scan_changed_folders) AND ",
        "files.automatic_classification IN('loop','one-shot') AND ",
        "files.classification_confidence>=0.86 GROUP BY locations.folder_id ",
        "HAVING count(*)>=3;\n",
        "CREATE TEMP TABLE scan_folder_consensus AS SELECT folder_id,",
        "CASE WHEN loops>shots THEN 'loop' ELSE 'one-shot' END AS category,",
        "evidence_n FROM scan_folder_evidence WHERE ",
        "max(loops,shots)*10>=evidence_n*9;\n",
        "UPDATE files SET automatic_classification=(SELECT category FROM ",
        "folder_files AS location JOIN scan_folder_consensus AS consensus ",
        "ON consensus.folder_id=location.folder_id WHERE location.file_id=files.id ",
        "AND location.missing=0 ORDER BY consensus.evidence_n DESC LIMIT 1),",
        "classification=(SELECT category FROM folder_files AS location ",
        "JOIN scan_folder_consensus AS consensus ON consensus.folder_id=",
        "location.folder_id WHERE location.file_id=files.id AND ",
        "location.missing=0 ORDER BY consensus.evidence_n DESC LIMIT 1),",
        "classification_source='folder consensus',",
        "classification_confidence=0.82 WHERE media_type='audio' AND ",
        "automatic_classification='other' AND canonical_path_norm IN(",
        "SELECT path_norm FROM scan_changed_paths) AND ",
        "classification_source='uncategorized' AND ",
        "EXISTS(SELECT 1 FROM ",
        "folder_files AS location JOIN scan_folder_consensus AS consensus ",
        "ON consensus.folder_id=location.folder_id WHERE ",
        "location.file_id=files.id AND location.missing=0);\n",
        -- Persist direct-folder facet counts during the explicit scan commit.
        -- Interactive root/subfolder tag catalogs can then sum compact rows
        -- instead of revisiting every file and file_tag association.
        "DELETE FROM folder_tag_counts WHERE folder_id IN ",
        "(SELECT folder_id FROM scan_changed_folders);\n",
        "INSERT INTO folder_tag_counts(folder_id,tag_id,file_count) ",
        "SELECT locations.folder_id,file_tags.tag_id,",
        "count(DISTINCT locations.file_id) FROM folder_files AS locations ",
        "JOIN files ON files.id=locations.file_id ",
        "JOIN file_tags ON file_tags.file_id=locations.file_id ",
        "JOIN tags ON tags.id=file_tags.tag_id ",
        "WHERE locations.missing=0 AND files.missing=0 ",
        "AND locations.folder_id IN(SELECT folder_id FROM ",
        "scan_changed_folders) ",
        "AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions ",
        "WHERE file_tag_exclusions.file_id=locations.file_id ",
        "AND file_tag_exclusions.tag_norm=tags.name_norm) ",
        "GROUP BY locations.folder_id,file_tags.tag_id;\n",
        -- Publish scan-time tag read models. Subtree catalogs are compact sums
        -- of direct-folder counts; the global catalog deduplicates canonical
        -- files that may appear through overlapping roots.
        "DELETE FROM folder_subtree_tag_counts WHERE folder_id IN(",
        "SELECT id FROM folders WHERE root_id IN(SELECT root_id FROM scan_roots));\n",
        "INSERT INTO folder_subtree_tag_counts(folder_id,tag_id,file_count) ",
        "SELECT closure.ancestor_id,direct.tag_id,sum(direct.file_count) ",
        "FROM folder_closure AS closure JOIN folder_tag_counts AS direct ",
        "ON direct.folder_id=closure.descendant_id WHERE closure.root_id IN(",
        "SELECT root_id FROM scan_roots) GROUP BY closure.ancestor_id,direct.tag_id;\n",
        -- Maintain the global catalog from changed canonical files only.
        "CREATE TEMP TABLE scan_new_effective_tags(file_id INTEGER,",
        "tag_id INTEGER,PRIMARY KEY(file_id,tag_id)) WITHOUT ROWID;\n",
        "INSERT INTO scan_new_effective_tags SELECT DISTINCT file_tags.file_id,",
        "file_tags.tag_id FROM scan_tag_paths JOIN files ON ",
        "files.canonical_path_norm=scan_tag_paths.path_norm JOIN file_tags ON ",
        "file_tags.file_id=files.id JOIN tags ON tags.id=file_tags.tag_id WHERE ",
        "files.missing=0 AND NOT EXISTS(SELECT 1 FROM file_tag_exclusions WHERE ",
        "file_tag_exclusions.file_id=file_tags.file_id AND ",
        "file_tag_exclusions.tag_norm=tags.name_norm);\n",
        "CREATE TEMP TABLE scan_added_effective_tags AS SELECT file_id,tag_id ",
        "FROM scan_new_effective_tags EXCEPT SELECT file_id,tag_id FROM ",
        "scan_old_effective_tags;\n",
        "CREATE TEMP TABLE scan_removed_tag_deltas AS SELECT file_id,tag_id ",
        "FROM scan_old_effective_tags EXCEPT SELECT file_id,tag_id FROM ",
        "scan_new_effective_tags UNION SELECT file_id,tag_id FROM ",
        "scan_removed_effective_tags;\n",
        "INSERT INTO library_tag_counts(tag_id,file_count) SELECT tag_id,",
        "count(*) FROM scan_added_effective_tags GROUP BY tag_id HAVING 1 ",
        "ON CONFLICT(tag_id) DO UPDATE SET file_count=",
        "library_tag_counts.file_count+excluded.file_count;\n",
        "UPDATE library_tag_counts SET file_count=file_count-(SELECT count(*) ",
        "FROM scan_removed_tag_deltas AS removed WHERE removed.tag_id=",
        "library_tag_counts.tag_id) WHERE tag_id IN(SELECT tag_id FROM ",
        "scan_removed_tag_deltas);\n",
        "DELETE FROM library_tag_counts WHERE file_count<=0;\n",
        restore_post_sql,
        -- Reapply manual classification precedence after the scan has
        -- refreshed automatic classifications and folder memberships.
        "UPDATE files SET classification=CASE WHEN files.media_type='midi' ",
        "THEN 'midi' ELSE COALESCE(\n",
        "(SELECT CASE WHEN classification='uncategorized' THEN 'other' ELSE classification END FROM classification_overrides WHERE ",
        "scope_type='file' AND path_norm=files.canonical_path_norm LIMIT 1),\n",
        "(SELECT CASE WHEN files.classification_source IN('explicit filename','explicit file BPM/bar structure','explicit BPM/bar structure','BPM-labeled rhythmic FX','folder-timed rhythmic FX','local terminal/FX structure','local drum/instrument structure','musical fragment descriptor','contextual bare-tempo structure','local instrument/ordinal structure','conflicting filename category','direct category folder','ancestor category folder') THEN files.automatic_classification ELSE CASE WHEN overrides.classification='uncategorized' THEN 'other' ELSE overrides.classification END END FROM classification_overrides AS overrides ",
        "WHERE overrides.scope_type='folder' AND ",
        "(files.canonical_path_norm=overrides.path_norm OR ",
        "(substr(files.canonical_path_norm,1,length(overrides.path_norm))=",
        "overrides.path_norm AND substr(files.canonical_path_norm,",
        "length(overrides.path_norm)+1,1)='/')) ORDER BY length(overrides.path_norm) DESC LIMIT 1),\n",
        "(SELECT CASE WHEN files.classification_source IN('explicit filename','explicit file BPM/bar structure','explicit BPM/bar structure','BPM-labeled rhythmic FX','folder-timed rhythmic FX','local terminal/FX structure','local drum/instrument structure','musical fragment descriptor','contextual bare-tempo structure','local instrument/ordinal structure','conflicting filename category','direct category folder','ancestor category folder') THEN files.automatic_classification ELSE CASE WHEN overrides.classification='uncategorized' THEN 'other' ELSE overrides.classification END END FROM classification_overrides AS overrides ",
        "WHERE overrides.scope_type='root' AND ",
        "(files.canonical_path_norm=overrides.path_norm OR ",
        "(substr(files.canonical_path_norm,1,length(overrides.path_norm))=",
        "overrides.path_norm AND substr(files.canonical_path_norm,",
        "length(overrides.path_norm)+1,1)='/')) LIMIT 1),\n",
        "files.automatic_classification) END WHERE canonical_path_norm IN(",
        "SELECT path_norm FROM scan_changed_paths);\n",
        -- Capture the latest automatic result before restoring the sparse
        -- manual value to the indexed effective key column.
        "UPDATE key_overrides SET detected_key_pc=(SELECT files.key_pc FROM ",
        "files WHERE files.canonical_path_norm=key_overrides.path_norm) WHERE ",
        "path_norm IN(SELECT path_norm FROM scan_changed_paths) AND EXISTS(",
        "SELECT 1 FROM files WHERE files.canonical_path_norm=",
        "key_overrides.path_norm);\n",
        "UPDATE files SET key_pc=(SELECT key_overrides.key_pc FROM ",
        "key_overrides WHERE key_overrides.path_norm=files.canonical_path_norm) ",
        "WHERE canonical_path_norm IN(SELECT path_norm FROM scan_changed_paths) ",
        "AND EXISTS(SELECT 1 FROM key_overrides WHERE ",
        "key_overrides.path_norm=files.canonical_path_norm);\n",
        progress("classification", sync.files or 0, sync.files or 0,
            "Tags and classifications updated"),
        progress("indexes", 0, 1, "Refreshing database indexes"),
        -- FTS insert/delete triggers maintain only the changed file rows.
        "INSERT OR REPLACE INTO app_meta(key,value) VALUES",
        "('file_search_ready_v1',strftime('%s','now')),",
        "('schema_v5_read_models_ready','1');\n",
        -- Refresh planner statistics during the explicit update, never during
        -- browsing. The broad mask considers newly created v5 indexes while
        -- SQLite still decides which ones actually require analysis.
        "PRAGMA optimize=0x10002;\n",
        -- PRAGMA optimize deliberately skips some moderately stale tables.
        -- A bounded sampled ANALYZE keeps row-count/selectivity estimates
        -- representative after large root additions without scanning every
        -- index entry in a ten-million-file library.
        "PRAGMA analysis_limit=1000;\n",
        "ANALYZE files; ANALYZE folder_files; ANALYZE file_tags; ",
        "ANALYZE folder_closure; ANALYZE user_file_data;\n",
        "PRAGMA analysis_limit=0;\n",
        progress("indexes", 1, 1, "Database indexes refreshed"),
        progress("commit", 0, 1, "Committing database transaction"),
        "CREATE TEMP TABLE sync_assert(ok INTEGER CHECK(ok=1));\n",
        "INSERT INTO sync_assert SELECT CASE WHEN ",
        "(SELECT count(DISTINCT path_norm) FROM scan_delta WHERE kind='D')=",
        tostring(sync.folders), " AND ",
        "(SELECT count(DISTINCT path_norm) FROM scan_delta WHERE kind='F')=",
        tostring(sync.files), " AND ",
        "(SELECT count(*) FROM folders WHERE missing=0 AND root_id IN ",
        "(SELECT root_id FROM scan_roots))=", tostring(sync.folders),
        " AND (SELECT count(*) FROM folder_files WHERE missing=0 ",
        "AND root_id IN(SELECT root_id FROM scan_roots))=",
        tostring(sync.files), " THEN 1 ELSE 0 END;\n",
        "INSERT OR REPLACE INTO app_meta(key,value) VALUES",
        "('last_delta_sync_at',", SQLQuote(now), "),",
        "('folder_tag_counts_ready','1');\n",
        "INSERT OR REPLACE INTO app_meta(key,value) SELECT ",
        "'library_file_count',CAST(count(*) AS TEXT) FROM files ",
        "WHERE missing=0;\n",
        "INSERT OR REPLACE INTO app_meta(key,value) SELECT ",
        "'auto_tag_version:'||root_norm,",
        SQLQuote(tostring(AUTO_TAG_VERSION)), " FROM scan_roots;\n",
        "COMMIT;\n",
        restore_detach_sql,
        progress("commit", 1, 1, "Database transaction committed"),
        "SELECT 'SYNC',",
        "(SELECT count(DISTINCT path_norm) FROM scan_delta WHERE kind='D'),",
        "(SELECT count(DISTINCT path_norm) FROM scan_delta WHERE kind='F'),",
        "(SELECT count(*) FROM folder_files WHERE missing=0 AND root_id IN ",
        "(SELECT root_id FROM scan_roots)),",
        "(SELECT count(*) FROM scan_added_locations),",
        "(SELECT count(*) FROM scan_removed_locations),",
        "(SELECT count(*) FROM files WHERE missing=0);\n",
    })
    local ok, err = StartDatabaseBatchAsync(
        sql, 0, "canonical_scan_sync", GetCanonicalDatabasePath())
    if not ok then
        ClearDatabaseWriteProgress()
        sync.progress_path = nil
        sync.apply_requested = false
        sync.importing = false
        state.library_scan.scanning = false
        state.library_scan.phase = nil
        state.library_scan.browser_blocked = false
        state.library_scan.operation_kind = nil
        state.library_scan.queue = {}
        state.library_scan.roots = {}
        state.library_scan.current = nil
        state.library_scan.retain_file_nodes = nil
        sync.status = "Library update could not start; database unchanged."
        sync.error = tostring(err)
        sync.scanned_root_keys = {}
        sync.scanned_folder_keys = {}
        sync.favorite_file_candidates = {}
        sync.scanned_favorite_file_keys = {}
        if sync.newly_added_root
            and RemoveConfiguredRootValue(sync.newly_added_root) then
            SaveSettings()
        end
        sync.newly_added_root = nil
        return false
    end
    sync.importing = true
    sync.status = string.format(
        "Writing database: %d folders, %d files...",
        sync.folders or 0, sync.files or 0)
    return true
end

function StartWorkerLibraryDiscovery(paths)
    local scan = state.library_scan
    local database = state.database
    r.SetExtState(EXT_SECTION, "last_worker_discovery",
        "attempt|" .. tostring(os.time()), true)
    if not EnsureDatabaseWorkerStarted(GetCanonicalDatabasePath()) then
        r.SetExtState(EXT_SECTION, "last_worker_discovery",
            "start_failed|" .. tostring(database.worker_status or "unknown"), true)
        return false
    end
    -- Requests are published by atomic rename into a session-owned queue. They
    -- remain valid while a cold worker opens SQLite, so readiness must not gate
    -- publication. The old gate repeatedly observed a false-negative heartbeat
    -- and entered Lua fallback without ever sending a discovery request.
    scan.discovery_paths = nil
    scan.worker_wait_started_at = nil
    local queue = database.worker_queue
    if not queue then return false end
    if r.RecursiveCreateDirectory then r.RecursiveCreateDirectory(queue, 0) end
    local token = "discover_" .. tostring(os.time()) .. "_"
        .. tostring(math.random(100000, 999999))
    local request_path = queue .. "/" .. token .. ".req"
    local result_path = queue .. "/" .. token .. ".res"
    local output_path = GetReaBrowseDataDirectory() .. "/Discovery_"
        .. token .. ".tsv"
    local extensions = {}
    for extension in pairs(RB_AUDIO_FILE_EXTENSIONS) do
        -- Discovery runs out of process, so pass it the decoder-aware set
        -- computed once here rather than indexing known containers that this
        -- REAPER installation cannot actually preview.
        if type(r.IsMediaExtension) ~= "function"
            or r.IsMediaExtension(extension, false) then
            extensions[#extensions + 1] = extension
        end
    end
    extensions[#extensions + 1] = "mid"
    extensions[#extensions + 1] = "midi"
    table.sort(extensions)
    local request = {
        token, "\n@discover:", tostring(DATABASE_WORKER_PROTOCOL_VERSION),
        "\n", output_path, "\n", tostring(MAX_LIBRARY_SCAN_DEPTH), "\n",
        table.concat(extensions, ","), "\n@speed:",
        tostring(state.scan_speed or "balanced"), "\n",
    }
    for _, path in ipairs(paths or {}) do
        request[#request + 1] = path
        request[#request + 1] = "\n"
    end
    local published, publish_error = PublishDatabaseWorkerRequest(
        request_path, table.concat(request))
    if not published then
        r.SetExtState(EXT_SECTION, "last_worker_discovery",
            "publish_failed|" .. tostring(publish_error or "unknown"), true)
        return false
    end
    r.SetExtState(EXT_SECTION, "last_worker_discovery",
        "published|" .. token, true)
    scan.discovery_request_path = request_path
    scan.discovery_result_path = result_path
    scan.discovery_output_path = output_path
    scan.discovery_progress_path = output_path .. ".progress"
    scan.discovery_nodes = {}
    scan.discovery_worker_unready_since = nil
    scan.discovery_last_progress_at = r.time_precise()
    scan.discovery_progress_signature = nil
    for _, root in ipairs(scan.roots or {}) do
        scan.discovery_nodes[NormalizeFavoritePath(root.path)] = root
    end
    scan.phase = "worker_discovery"
    scan.scan_metrics.mode = "worker"
    scan.scan_metrics.discovery_started_at = r.time_precise()
    scan.phase_label = "Discovering folders and files in background"
    scan.phase_detail = "Database worker is scanning the filesystem"
    return true
end

local function FallBackFromWorkerLibraryDiscovery(detail)
    local scan = state.library_scan
    if scan.discovery_request_path then
        local cancel = io.open(scan.discovery_request_path .. ".cancel", "wb")
        if cancel then cancel:write("worker unavailable\n"); cancel:close() end
        pcall(os.remove, scan.discovery_request_path)
    end
    pcall(os.remove, scan.discovery_result_path)
    pcall(os.remove, scan.discovery_output_path)
    pcall(os.remove, scan.discovery_output_path
        and (scan.discovery_output_path .. ".writing") or nil)
    pcall(os.remove, scan.discovery_progress_path)
    scan.discovery_request_path = nil
    scan.discovery_result_path = nil
    scan.discovery_output_path = nil
    scan.discovery_progress_path = nil
    scan.discovery_nodes = nil
    scan.discovery_worker_unready_since = nil
    scan.discovery_last_progress_at = nil
    scan.discovery_progress_signature = nil
    scan.phase = "folders"
    scan.scan_metrics.mode = "lua-fallback"
    scan.phase_label = "Discovering folders"
    scan.phase_detail = detail
        or "Background discovery unavailable; using incremental discovery"
    r.SetExtState(EXT_SECTION, "last_worker_discovery",
        "fallback|" .. tostring(scan.phase_detail), true)
    scan.queue_index = 1
    scan.current = nil
end

function PollWorkerLibraryDiscovery()
    local scan = state.library_scan
    local result = scan.discovery_result_path
        and io.open(scan.discovery_result_path, "rb")
    if not result then
        local progress = scan.discovery_progress_path
            and io.open(scan.discovery_progress_path, "rb")
        if progress then
            local folders, files, sequence =
                (progress:read("*a") or ""):match("(%d+)|(%d+)|?(%d*)")
            progress:close()
            local signature = tostring(folders) .. "|" .. tostring(files)
                .. "|" .. tostring(sequence)
            if signature ~= scan.discovery_progress_signature then
                scan.discovery_progress_signature = signature
                scan.discovery_last_progress_at = r.time_precise()
            end
            scan.discovered_folders = tonumber(folders)
                or scan.discovered_folders
            scan.discovered_files = tonumber(files) or scan.discovered_files
            scan.phase_detail = string.format(
                "%d folders, %d media files discovered",
                scan.discovered_folders or 0, scan.discovered_files or 0)
        end
        -- A live discovery request owns its queue entry and publishes progress
        -- from inside directory enumeration. Heartbeat reads can false-negative
        -- during atomic replacement; cancel only on sustained lack of actual
        -- scan progress, never merely because one readiness read failed.
        if r.time_precise() - (scan.discovery_last_progress_at
                or r.time_precise()) >= 15 then
            FallBackFromWorkerLibraryDiscovery(
                "Background scanner made no progress for 15 seconds")
        end
        return
    end
    local response = result:read("*a") or ""
    result:close()
    pcall(os.remove, scan.discovery_result_path)
    scan.discovery_request_path = nil
    scan.discovery_result_path = nil
    local _, status, _, payload = response:match(
        "^([^\t]*)\t([^\t]*)\t([^\t]*)\t?(.*)$")
    if status ~= "ok" then
        r.SetExtState(EXT_SECTION, "last_worker_discovery",
            "response_error|" .. tostring(DecodeWorkerPayload(payload or response)), true)
        FallBackFromWorkerLibraryDiscovery(
            "Background discovery failed; using incremental discovery")
        return
    end
    local folders, files = DecodeWorkerPayload(payload):match(
        "^(%d+)|(%d+)|")
    r.SetExtState(EXT_SECTION, "last_worker_discovery",
        "completed|folders=" .. tostring(folders or "?")
            .. "|files=" .. tostring(files or "?"), true)
    scan.discovered_folders = tonumber(folders) or scan.discovered_folders
    scan.scan_metrics.discovery_seconds = math.max(0,
        r.time_precise() - (scan.scan_metrics.discovery_started_at
            or scan.started_at or r.time_precise()))
    scan.scan_metrics.ingest_started_at = r.time_precise()
    scan.discovered_files = 0
    scan.discovery_processed_files = 0
    scan.phase_total = tonumber(files) or 0
    scan.discovery_file = io.open(scan.discovery_output_path or "", "rb")
    if not scan.discovery_file then
        scan.phase = "folders"
        scan.queue_index = 1
        scan.current = nil
        return
    end
    scan.phase = "worker_ingest"
    scan.phase_label = "Comparing media metadata"
    scan.phase_detail = "Only new and changed files generate tags"
end

function ProcessWorkerLibraryDiscovery()
    local scan = state.library_scan
    local file = scan.discovery_file
    if not file then return PollWorkerLibraryDiscovery() end
    local profile = GetLibraryScanSpeedProfile()
    local budget = math.max(128, profile.budget * 2)
    local time_slice = profile.time_slice
    if state.scan_speed ~= "turbo"
        and (state.is_playing or ((r.GetPlayState() or 0) & 1) ~= 0) then
        -- Scanning is maintenance; an active preview or arrangement transport
        -- gets virtually the whole GUI frame and audio scheduling window.
        -- Dedicated is the explicit throughput-first profile and must not be
        -- silently reduced to the Background ingestion slice by Auto Play.
        budget = math.min(budget, 128)
        time_slice = math.min(time_slice, 0.001)
    end
    local deadline = r.time_precise() + math.max(0.0005, time_slice)
    while budget > 0 and r.time_precise() < deadline do
        local line = file:read("*l")
        if not line then
            file:close()
            scan.discovery_file = nil
            local expected_files = tonumber(scan.phase_total) or 0
            local processed_files = tonumber(scan.discovery_processed_files) or 0
            if processed_files ~= expected_files then
                local message = string.format(
                    "Discovery integrity check failed: worker found %d files, ingestion processed %d.",
                    expected_files, processed_files)
                CancelLibraryScan()
                state.canonical_scan_sync.status = message
                state.canonical_scan_sync.error = message
                return
            end
            pcall(os.remove, scan.discovery_output_path)
            pcall(os.remove, scan.discovery_progress_path)
            scan.discovery_output_path = nil
            scan.discovery_progress_path = nil
            scan.discovery_nodes = nil
            scan.scan_metrics.ingest_seconds = math.max(0,
                r.time_precise() - (scan.scan_metrics.ingest_started_at
                    or r.time_precise()))
            StartLibraryFinalize()
            return
        end
        local kind, _, path, parent_path, name, file_size,
            modified_at, changed = line:match(
            "^([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)"
                .. "\t([^\t]*)\t([^\t]*)\t(.*)$")
        path = DecodeWorkerPayload(path)
        parent_path = DecodeWorkerPayload(parent_path)
        name = DecodeWorkerPayload(name)
        if kind == "D" and not IsMacOSMetadataPath(path) then
            local key = NormalizeFavoritePath(path)
            local node = scan.discovery_nodes[key]
            if not node then
                local parent = scan.discovery_nodes[
                    NormalizeFavoritePath(parent_path)]
                if parent then
                    node = {
                        name = name, name_lower = (name or ""):lower(),
                        path = path, is_folder = true, children = {}, files = {},
                        depth = (parent.depth or 0) + 1, parent = parent,
                        _scan_complete = true,
                        scan_root_key = parent.scan_root_key,
                    }
                    parent.children[#parent.children + 1] = node
                    scan.discovery_nodes[key] = node
                end
            end
        elseif kind == "F" then
            scan.discovery_processed_files =
                (scan.discovery_processed_files or 0) + 1
            -- Discovery received the authoritative extension allow-list and
            -- only emits matching files. Re-checking through REAPER here was
            -- redundant and, for some hosts/extensions, rejected every worker
            -- result after a successful scan.
            local parent = scan.discovery_nodes[
                NormalizeFavoritePath(parent_path)]
            if parent and not IsMacOSMetadataPath(path) then
                local entry = {
                    name = name, name_lower = (name or ""):lower(), path = path,
                    is_folder = false,
                    media_kind = IsMidiFile(name or path) and "midi" or "audio",
                    parent = parent,
                    _scan_file_size = file_size,
                    _scan_modified_at = modified_at,
                    _scan_change_kind = changed,
                    _scan_unchanged = changed ~= "1",
                }
                parent._scan_has_media = true
                if scan.retain_file_nodes then
                    parent.files[#parent.files + 1] = entry
                end
                QueueMediaDatabaseFile(entry)
                WriteCanonicalManifestFile(entry)
                scan.discovered_files = scan.discovered_files + 1
            end
        end
        budget = budget - 1
    end
    scan.phase_done = scan.discovered_files or 0
end

function StartLibraryScan(only_root, newly_added)
    local scan = state.library_scan
    if scan.scanning then return false end
    if not state.database.canonical
        or state.database.backend ~= "sqlite" then
        state.database.status = "SQLite database required for Library updates"
        state.canonical_scan_sync.status = state.database.error
            or "The ReaBrowse SQLite database is unavailable."
        return false
    end
    if only_root and not IsRootLibraryFolder(only_root) then
        state.canonical_scan_sync.status =
            "Only configured library folders can be updated."
        return false
    end
    -- Existing committed rows remain the visible snapshot while discovery
    -- prepares the next generation. A foreground read is cancelled only when
    -- the final delta is ready to commit, not when a potentially long scan
    -- begins.
    -- The manifest now owns automatic classification. Never reuse a
    -- pre-scan Lua classification when rebuilding or refreshing a root.
    state.media_class_by_path = {}
    scan.previous_folder_tree = state.folder_tree
    scan.tree_replaced = false
    scan.incremental_root = only_root
    scan.newly_added_root = newly_added and only_root or nil
    scan.scanning = true
    scan.operation_kind = "scan"
    scan.phase = "folders"
    scan.browser_blocked = not (state.database.canonical
        and (tonumber(state.database.library_file_count) or 0) > 0)
    scan.started_at = r.time_precise()
    scan.scan_metrics = {
        mode = "lua-fallback",
        started_at = scan.started_at,
        discovery_started_at = scan.started_at,
    }
    scan.worker_relaunch_attempted = false
    scan.phase_started_at = scan.started_at
    scan.phase_done = 0
    scan.phase_total = 0
    scan.phase_label = "Discovering folders"
    scan.phase_detail = nil
    scan.queue = {}
    scan.queue_index = 1
    scan.current = nil
    scan.roots = {}
    -- Every add/update is atomic from the user's perspective. Keep the last
    -- completed library hidden behind one progress surface until filesystem
    -- discovery, database commit, worker refresh, and navigation reload all
    -- finish. Publishing a partial replacement tree created a hybrid browser
    -- that looked usable before its database generation was ready.
    scan.progressive = false
    scan.last_tree_publish = 0
    scan.discovered_files = 0
    scan.discovered_folders = 0
    scan.finalize_stack = nil
    scan.finalized_folders = 0
    scan.finalize_total = 0
    scan.prepare_stack = nil
    scan.prepare_total = 0
    scan.prepared_folders = 0
    scan.configured_root_keys = {}
    for _, configured_root in ipairs(state.root_folders or {}) do
        scan.configured_root_keys[NormalizeFavoritePath(configured_root)] = true
    end
    state.canonical_scan_sync.metadata_root = nil
    BeginMediaDatabaseScan(only_root ~= nil)
    StartCanonicalScanManifest()
    -- Canonical scans stream file records to the manifest and must not retain
    -- one Lua table per file until commit. Ten million files would otherwise
    -- exhaust memory even though browsing itself is database-paged. Keep file
    -- nodes only for the legacy/fallback path or if manifest creation failed.
    scan.retain_file_nodes = not state.database.canonical
        or not state.canonical_scan_sync.manifest_file
    local sync = state.canonical_scan_sync
    sync.favorite_file_candidates = {}
    sync.scanned_favorite_file_keys = {}
    for _, favorite in ipairs(state.favorites or {}) do
        if favorite.kind == "file" then
            sync.favorite_file_candidates[
                NormalizeFavoritePath(favorite.path)] = true
        end
    end
    state.canonical_scan_sync.newly_added_root = scan.newly_added_root

    local paths = only_root and {only_root} or state.root_folders
    for _, path in ipairs(paths) do
        local name = GetFileName(path)
        local root = {
            name = name, name_lower = name:lower(), path = path,
            is_folder = true, children = {}, files = {}, depth = 0, parent = nil,
            _scan_complete = false,
            scan_root_key = NormalizeFavoritePath(path),
        }
        scan.roots[#scan.roots + 1] = root
        scan.queue[#scan.queue + 1] = root
        scan.discovered_folders = scan.discovered_folders + 1
    end
    if state.database.canonical
        and StartWorkerLibraryDiscovery(paths) then
        return true
    end
    if scan.progressive then
        if only_root then
            local root_key = NormalizeFavoritePath(only_root)
            local visible = {}
            for _, existing in ipairs(state.folder_tree or {}) do
                if NormalizeFavoritePath(existing.path) ~= root_key then
                    visible[#visible + 1] = existing
                end
            end
            for _, root in ipairs(scan.roots) do visible[#visible + 1] = root end
            state.folder_tree = visible
        else
            state.folder_tree = scan.roots
        end
        state.force_search_update = true
        state.needs_visible_update = true
    end
    return true
end

function CancelLibraryScan()
    local scan = state.library_scan
    local was_progressive = scan.progressive
    local tree_replaced = scan.tree_replaced
    local newly_added_root = scan.newly_added_root
    if scan.discovery_request_path then
        local cancel = io.open(scan.discovery_request_path .. ".cancel", "wb")
        if cancel then cancel:write("cancelled\n"); cancel:close() end
    end
    if scan.discovery_file then scan.discovery_file:close() end
    scan.discovery_file = nil
    pcall(os.remove, scan.discovery_output_path)
    pcall(os.remove, scan.discovery_output_path
        and (scan.discovery_output_path .. ".writing") or nil)
    pcall(os.remove, scan.discovery_progress_path)
    scan.discovery_request_path = nil
    scan.discovery_result_path = nil
    scan.discovery_output_path = nil
    scan.discovery_progress_path = nil
    scan.discovery_nodes = nil
    scan.discovery_last_progress_at = nil
    scan.discovery_progress_signature = nil
    scan.discovery_worker_unready_since = nil
    scan.discovery_paths = nil
    scan.worker_wait_started_at = nil
    scan.scanning = false
    scan.phase = nil
    scan.browser_blocked = false
    scan.operation_kind = nil
    scan.queue = {}
    scan.queue_index = 1
    scan.current = nil
    scan.roots = {}
    scan.progressive = false
    scan.retain_file_nodes = nil
    scan.incremental_root = nil
    scan.newly_added_root = nil
    scan.configured_root_keys = {}
    scan.finalize_stack = nil
    scan.finalize_total = 0
    scan.finalized_folders = 0
    scan.prepare_stack = nil
    scan.prepare_total = 0
    scan.prepared_folders = 0
    state.canonical_scan_sync.validation = nil
    FinishCanonicalScanManifest(true)
    if was_progressive or tree_replaced then
        state.folder_tree = scan.previous_folder_tree or {}
        state.force_search_update = true
        state.needs_visible_update = true
    end
    scan.tree_replaced = false
    scan.previous_folder_tree = nil
    if newly_added_root and RemoveConfiguredRootValue(newly_added_root) then
        SaveSettings()
        state.canonical_scan_sync.status =
            "Cancelled new library folder was removed from Settings."
    end
    CancelMediaDatabaseScan()
end

function ProcessLibraryScan()
    local scan = state.library_scan
    if not scan.scanning then return end
    if scan.phase == "worker_discovery" or scan.phase == "worker_ingest" then
        ProcessWorkerLibraryDiscovery()
        return
    end
    if scan.phase == "commit" then return end
    if scan.phase == "remove" or scan.phase == "compact_prepare"
        or scan.phase == "compact" then return end
    if scan.phase == "finalize_db" then
        ProcessLibraryDatabaseFinalize()
        return
    end
    if scan.phase == "prepare" then
        ProcessLibraryPrepare()
        return
    end
    if scan.phase == "validate" then
        ProcessLibraryManifestValidation()
        return
    end
    if scan.phase == "finalize" then
        ProcessLibraryFinalize()
        return
    end

    -- Use both an entry cap and a short time slice. A single slow filesystem
    -- call can exceed the target, but the next frame will yield immediately.
    local profile = GetLibraryScanSpeedProfile()
    local budget = profile.budget
    local initial_budget = budget
    local time_slice = profile.time_slice
    local frame_deadline = r.time_precise() + time_slice
    while budget > 0
        and (budget == initial_budget or r.time_precise() < frame_deadline) do
        if not scan.current then
            scan.current = scan.queue[scan.queue_index]
            if not scan.current then
                if scan.phase == "folders" then
                    -- Every directory is now known. Publish the complete
                    -- hierarchy before doing the slower file/tag pass.
                    scan.phase = "files"
                    scan.phase_started_at = r.time_precise()
                    scan.phase_label = "Scanning files"
                    scan.queue_index = 1
                    scan.current = nil
                    if scan.progressive then
                        local root_key = scan.incremental_root
                            and NormalizeFavoritePath(scan.incremental_root)
                        if root_key then
                            local visible = {}
                            for _, existing in ipairs(state.folder_tree or {}) do
                                if NormalizeFavoritePath(existing.path)
                                    ~= root_key then
                                    visible[#visible + 1] = existing
                                end
                            end
                            for _, root in ipairs(scan.roots) do
                                visible[#visible + 1] = root
                            end
                            state.folder_tree = visible
                        else
                            state.folder_tree = scan.roots
                        end
                        state.force_search_update = true
                        state.needs_visible_update = true
                    end
                    return
                end
                StartLibraryFinalize()
                return
            end
            scan.queue_index = scan.queue_index + 1
            scan.current._scan_index = 0
        end

        local node = scan.current
        if scan.phase == "folders" then
            local name = r.EnumerateSubdirectories(node.path, node._scan_index)
            if name then
                node._scan_index = node._scan_index + 1
                if node.depth < MAX_LIBRARY_SCAN_DEPTH
                    and name:lower() ~= "__macosx" then
                    local path = node.path:gsub("[/\\]+$", "") .. "/" .. name
                    local child_key = NormalizeFavoritePath(path)
                    local crosses_configured_root =
                        scan.configured_root_keys[child_key]
                        and child_key ~= node.scan_root_key
                    if not crosses_configured_root then
                        local child = {
                            name = name, name_lower = name:lower(), path = path,
                            is_folder = true, children = {}, files = {},
                            depth = node.depth + 1, parent = node,
                            _scan_complete = false,
                            scan_root_key = node.scan_root_key,
                        }
                        node.children[#node.children + 1] = child
                        scan.queue[#scan.queue + 1] = child
                        scan.discovered_folders = scan.discovered_folders + 1
                    end
                end
                budget = budget - 1
            else
                node._scan_index = nil
                scan.current = nil
                if scan.progressive
                    and r.time_precise() - (scan.last_tree_publish or 0)
                        >= 0.12 then
                    scan.last_tree_publish = r.time_precise()
                    state.force_search_update = true
                    state.needs_visible_update = true
                end
            end
        else
            local name = r.EnumerateFiles(node.path, node._scan_index)
            if name then
                node._scan_index = node._scan_index + 1
                if IsBrowserMediaFile(name) then
                    local path = node.path:gsub("[/\\]+$", "") .. "/" .. name
                    local file_size = GetFileSizeBytes(path)
                    -- Match worker discovery: zero-byte decoder inputs are not
                    -- media. Unknown sizes remain eligible so a transient stat
                    -- failure cannot silently remove a valid network file.
                    if file_size ~= 0 then
                        local entry = {
                            name = name, name_lower = name:lower(), path = path,
                            is_folder = false,
                            media_kind = IsMidiFile(name) and "midi" or "audio",
                            parent = node, _scan_file_size = file_size,
                        }
                        node._scan_has_media = true
                        if scan.retain_file_nodes then
                            node.files[#node.files + 1] = entry
                        end
                        QueueMediaDatabaseFile(entry)
                        WriteCanonicalManifestFile(entry)
                        scan.discovered_files = scan.discovered_files + 1
                    end
                end
                budget = budget - 1
            else
                node._scan_index = nil
                node._scan_complete = true
                scan.current = nil
                -- Publish navigation changes only when a directory is complete.
                -- Rebuilding the visible list after every small file batch makes
                -- very large directories shift underneath the user's mouse.
                if scan.progressive
                    and r.time_precise() - (scan.last_tree_publish or 0)
                        >= 1.0 then
                    scan.last_tree_publish = r.time_precise()
                    -- The open tree reads completed directory contents
                    -- directly, so a normal folder view needs no full
                    -- navigation-list rebuild here. Filtered/search views do.
                    if state.search_text ~= ""
                        or MediaFiltersActive() then
                        state.force_search_update = true
                        state.needs_visible_update = true
                    end
                end
            end
        end
    end
end

-- ============================================================
-- KEY DETECTION & KEY SYNC
-- ============================================================
local PITCH_CLASS_NAMES = { "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B" }

function GetKeyDisplaySummary(paths)
    local detected_labels, override_labels, effective_labels = {}, {}, {}
    local function AddDistinct(target, label)
        for _, existing in ipairs(target) do
            if existing == label then return end
        end
        target[#target + 1] = label
    end
    for _, path in ipairs(paths or {}) do
        local entry = GetManualKeyOverrideEntry(path)
        local detected
        if NormalizeFavoritePath(state.source_file or "")
            == NormalizeFavoritePath(path) then
            detected = state.media_kind == "audio"
                and state.audio_detected_key_automatic_pc
                or (state.loaded_midi
                    and state.loaded_midi.automatic_key_pc)
        elseif entry then
            detected = entry.detected_key_pc == false
                and nil or entry.detected_key_pc
        else
            detected = DetectFileKeyPitchClass(path, nil)
        end
        AddDistinct(detected_labels,
            KeyPitchClassLabel(detected, "Undetected"))
        if entry then
            AddDistinct(override_labels, entry.key_pc == false
                and "Unkeyed" or KeyPitchClassLabel(entry.key_pc))
        else
            AddDistinct(override_labels, "None")
        end
        AddDistinct(effective_labels,
            KeyPitchClassLabel(
                ResolveEffectiveKeyPitchClass(path, detected), "Unkeyed"))
    end
    local function Summary(values)
        if #values == 0 then return "Undetected" end
        if #values == 1 then return values[1] end
        return "Mixed"
    end
    return Summary(detected_labels), Summary(override_labels),
        Summary(effective_labels)
end
local LETTER_TO_PC = { C = 0, D = 2, E = 4, F = 5, G = 7, A = 9, B = 11 }
local MAJOR_PC_BY_SF = {
    [-7] = 11, [-6] = 6, [-5] = 1, [-4] = 8, [-3] = 3, [-2] = 10, [-1] = 5,
    [0] = 0, [1] = 7, [2] = 2, [3] = 9, [4] = 4, [5] = 11, [6] = 6, [7] = 1,
}

function NoteLetterToPitchClass(letter, accidental)
    local pc = LETTER_TO_PC[letter:upper()]
    if not pc then return nil end
    if accidental == "#" then pc = pc + 1
    elseif accidental == "b" then pc = pc - 1 end
    return pc % 12
end

function KeySigToPitchClass(sf, mi)
    local maj = MAJOR_PC_BY_SF[sf]
    if not maj then return nil end
    if mi == 1 then return (maj - 3) % 12 end
    return maj
end

function DetectFileKeyPitchClass(filepath, take)
    if take and r.ValidatePtr(take, "MediaItem_Take*") then
        local ok, result = pcall(function()
            local idx = 0
            while true do
                local retval, _, _, _, typeidx, msg = r.MIDI_GetTextSysexEvt(take, idx, false, false, 0, 0, "")
                if not retval then break end
                if typeidx == 89 and msg and #msg >= 2 then
                    local sf = string.byte(msg, 1)
                    if sf and sf > 127 then sf = sf - 256 end
                    local mi = string.byte(msg, 2) or 0
                    local pc = KeySigToPitchClass(sf, mi)
                    if pc then return pc end
                end
                idx = idx + 1
            end
            return nil
        end)
        if ok and result then return result end
    end

    local name = GetFileName(filepath)
    local function parse(str, allow_loose)
        local n, a
        -- Prefix once so every compact key expression can require a true
        -- non-letter boundary. Without this, ordinary words ending in "am"
        -- or "em" (scream, dream, stem, core) were interpreted as keys.
        local bounded = " " .. str
        -- Producers also use compact spelled accidentals such as dsharpmin,
        -- asharpminor, or eflatmaj. Recognize complete key expressions while
        -- retaining the non-letter boundary that rejects ordinary words.
        n = bounded:match(
            "[^%a]([A-Ga-g])[sS][hH][aA][rR][pP][%s%._%-]*[mM][iI][nN][oO]?[rR]?")
        if n then return n, "#" end
        n = bounded:match(
            "[^%a]([A-Ga-g])[fF][lL][aA][tT][%s%._%-]*[mM][iI][nN][oO]?[rR]?")
        if n then return n, "b" end
        n = bounded:match(
            "[^%a]([A-Ga-g])[sS][hH][aA][rR][pP][%s%._%-]*[mM][aA][jJ][oO]?[rR]?")
        if n then return n, "#" end
        n = bounded:match(
            "[^%a]([A-Ga-g])[fF][lL][aA][tT][%s%._%-]*[mM][aA][jJ][oO]?[rR]?")
        if n then return n, "b" end
        n = bounded:match(
            "[^%a]([A-Ga-g])[%s%._%-]+[sS][hH][aA][rR][pP]")
        if n then return n, "#" end
        n = bounded:match(
            "[^%a]([A-Ga-g])[%s%._%-]+[fF][lL][aA][tT]")
        if n then return n, "b" end
        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][iI][nN][oO][rR]")
        if n then return n, a end
        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][iI][nN][^%a]")
        if not n then n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][iI][nN]$") end
        if n then return n, a end
        
        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][aA][jJ][oO][rR]")
        if n then return n, a end
        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][aA][jJ][^%a]")
        if not n then n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[mM][aA][jJ]$") end
        if n then return n, a end

        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*m[^%a]")
        if not n then n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*m$") end
        if n then return n, a end

        n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[M][^%a]")
        if not n then n, a = bounded:match(
            "[^%a]([A-Ga-g])([#b]?)[%s%._%-]*[M]$") end
        if n then return n, a end

        if not allow_loose then return nil, nil end
        n, a = str:match("[%s%._%-]([A-Ga-g])([#b]?)[%s%._%-]")
        if not n then n, a = str:match("^([A-Ga-g])([#b]?)[%s%._%-]") end
        if not n then n, a = str:match("[%s%._%-]([A-Ga-g])([#b]?)$") end
        return n, a
    end

    local note, accidental = parse(name, true)
    if note then return NoteLetterToPitchClass(note, accidental) end
    -- Scan only nearby folders. Key-labelled sample folders are common, while
    -- distant pack/vendor names add false positives and unnecessary work.
    local parent_path = (filepath or ""):gsub("\\", "/")
    parent_path = parent_path:match("^(.*)/[^/]+$") or ""
    for _ = 1, 3 do
        if parent_path == "" then break end
        local folder_name = parent_path:match("([^/]+)$") or parent_path
        local bare_note, bare_accidental = folder_name:match(
            "^%s*([A-Ga-g])([#b]?)%s*$")
        if bare_note then
            return NoteLetterToPitchClass(bare_note, bare_accidental)
        end
        -- Parent folders require explicit key wording unless the same folder
        -- also contains a plausible tempo token (for example "95 C#"). This
        -- avoids treating ordinary pack names such as "Pack A" as keys.
        local tempo_key_folder = folder_name:match(
            "%d%d?%d[%s%._%-]+[A-Ga-g][#b]?") ~= nil
        note, accidental = parse(folder_name, tempo_key_folder)
        if note then return NoteLetterToPitchClass(note, accidental) end
        parent_path = parent_path:match("^(.*)/[^/]+$") or ""
    end
    return nil
end

function ComputeKeySyncShift(source_pc, target_pc)
    if not source_pc then return 0 end
    return ((target_pc - source_pc + 6) % 12) - 6
end

-- Lightweight key handling for ReaBrowse. Detection currently uses filename
-- and embedded media metadata; no FFT/chroma detector is run here. The
-- pitch-class conversion and semitone-shift helpers are shared by the audio
-- and MIDI correction paths. This code does not control Media Explorer.
function DetectAudioKeyFromMetadata(source)
    if not source then return nil end
    local count, identifiers = r.GetMediaFileMetadata(source, "")
    if not count or count <= 0 or not identifiers then return nil end
    for identifier in identifiers:gmatch("[^\r\n]+") do
        local upper = identifier:upper()
        if upper:find("KEY", 1, true) or upper:find("ROOT", 1, true) then
            local ok, value = r.GetMediaFileMetadata(source, identifier)
            if ok and ok > 0 and value then
                local note, accidental = value:match("([A-Ga-g])([#b]?)")
                if note then return NoteLetterToPitchClass(note, accidental) end
            end
        end
    end
    return nil
end

function DetectAudioKey(filepath, source)
    -- Embedded key metadata is explicit and should outrank a weak filename
    -- token such as a standalone A-G variant label.
    local pc = DetectAudioKeyFromMetadata(source)
    if pc ~= nil then return pc, "metadata" end
    pc = DetectFileKeyPitchClass(filepath, nil)
    if pc ~= nil then return pc, "filename" end
    return nil, "undetected"
end

function DetectExplicitFilenameBPM(filepath)
    local name = GetFileName(filepath or ""):lower()
        :gsub("%.[^%.]+$", "")
    -- Accept ordinary, compact and reversed declarations: 128 BPM, 128bpm,
    -- name128bpm and bpm128. Plausibility validation below prevents IDs and
    -- years outside the supported musical range from becoming tempo.
    local bpm = tonumber(name:match("(%d%d?%d?)%s*bpm"))
        or tonumber(name:match("bpm%s*(%d%d?%d?)"))
    -- Sounds of KSHMR uses a stable vendor schema where the field immediately
    -- after SOK<volume> is tempo, for example KSHMR_sok5_120_fx_pulse_....
    -- Keep this positional exception vendor-specific rather than treating
    -- arbitrary bare numbers as authoritative BPM.
    if not bpm then
        bpm = tonumber(name:match(
            "kshmr[%s_%-]+sok%d+[%s_%-]+(%d%d?%d?)[%s_%-]+"))
    end
    -- Loop libraries commonly use a bare tempo field, for example
    -- MUL_125_TOP_LOOP_03. Only infer an unlabeled value when the filename
    -- itself says loop, exactly one distinct token is in the conservative
    -- 50-200 BPM range, and smaller ordinal fields therefore cannot qualify.
    if not bpm then
        local tokens = " " .. name:gsub("[^%w]+", " ") .. " "
        local names_loop = tokens:find(" loop ", 1, true)
            or tokens:find(" loops ", 1, true)
        if names_loop then
            local inferred = nil
            local ambiguous = false
            for token in tokens:gmatch("%S+") do
                -- Only standalone numeric fields qualify. Technical/version
                -- tokens such as 96k, 24bit, v120, and sr48 must remain IDs.
                local value = tonumber(token)
                if value and value >= 50 and value <= 200 then
                    if inferred and inferred ~= value then
                        ambiguous = true
                        break
                    end
                    inferred = value
                end
            end
            if not ambiguous then bpm = inferred end
        end
    end
    return bpm and bpm >= 30 and bpm <= 400 and bpm or nil
end

function DetectAudioOneShot(filepath, source, source_length)
    local category = ResolveEffectiveMediaClass(filepath)
    return category == "one-shot", "database classification: " .. category
end

function ResolveAudioOneShot(filepath, source, source_length)
    return DetectAudioOneShot(filepath, source, source_length)
end

function BuildAudioWaveform(source)
    local length = r.GetMediaSourceLength(source)
    if not length or length <= 0 then return nil end
    local points = 1024
    -- A fixed low peak rate can depend on a prebuilt .reapeaks file. Read a
    -- bounded, moderately dense summary instead, then reduce it to the display
    -- width. This is immediate and predictable without PCM_Source_BuildPeaks.
    local raw_points = math.min(32768,
        math.max(points, math.ceil(length * 200)))
    local peak_rate = raw_points / length
    local channels = math.max(1, math.min(2, r.GetMediaSourceNumChannels(source) or 1))
    local buffer = r.new_array(raw_points * channels * 2)
    buffer.clear()
    local returned = r.PCM_Source_GetPeaks(
        source, peak_rate, 0, channels, raw_points, 0, buffer)
    if not returned then return nil end
    local count = returned & 0xFFFFF
    if count <= 0 then return nil end
    local peaks = {}
    local has_signal = false
    for column = 1, points do
        local first = math.floor((column - 1) * count / points) + 1
        local last = math.max(first, math.floor(column * count / points))
        local peak = 0
        for i = first, math.min(last, count) do
            for channel = 0, channels - 1 do
                -- Peak samples are interleaved by channel inside separate
                -- maximum and minimum blocks.
                local interleaved = (i - 1) * channels + channel + 1
                local maximum = buffer[interleaved] or 0
                local minimum = buffer[
                    raw_points * channels + interleaved] or 0
                peak = math.max(peak, math.abs(maximum), math.abs(minimum))
            end
        end
        peaks[column] = math.min(1, peak)
        if peak > 0.000001 then has_signal = true end
    end
    if not has_signal then return nil end
    return peaks
end

function HasPotentiallyProvisionalPreviewLength(filepath)
    local extension = (filepath or ""):match("%.([^%.\\/]+)$")
    extension = extension and extension:lower() or ""
    -- Packetized and container sources may report a short provisional length
    -- until REAPER's decoder has scanned enough metadata. Never use that
    -- estimate as an authoritative stop timer.
    if extension == "wav" or extension == "wave"
        or extension == "aif" or extension == "aiff"
        or extension == "aifc" or extension == "flac"
        or extension == "wv" then
        return false
    end
    return extension == "mp3" or extension == "ogg"
        or extension == "opus" or extension == "m4a"
        or extension == "aac" or extension == "mp4"
        or extension == "mov" or extension == "avi"
        or extension == "caf"
        -- Unknown-but-REAPER-supported formats are conservatively treated as
        -- provisional. Native cursor stability, not a guessed duration, then
        -- decides when the preview is truly finished.
        or RB_AUDIO_FILE_EXTENSIONS[extension] ~= true
end

function GetExistingAudioPeakFile(filepath)
    if not filepath or filepath == "" then return nil end
    local peak_path
    if type(r.GetPeakFileNameEx2) == "function" then
        local ok, resolved = pcall(
            r.GetPeakFileNameEx2, filepath, "", false, ".reapeaks")
        if ok then peak_path = resolved end
    elseif type(r.GetPeakFileNameEx) == "function" then
        local ok, resolved = pcall(
            r.GetPeakFileNameEx, filepath, "", false)
        if ok then peak_path = resolved end
    elseif type(r.GetPeakFileName) == "function" then
        local ok, resolved = pcall(r.GetPeakFileName, filepath)
        if ok then peak_path = resolved end
    end
    return type(peak_path) == "string" and FileExists(peak_path)
        and peak_path or nil
end

function CacheAudioWaveform(filepath, peaks)
    if not filepath or not peaks then return end
    -- Refresh cache hits so repeatedly auditioned files stay resident. The
    -- previous FIFO order could evict a hot waveform merely because it was
    -- first opened a long time ago.
    for index = #state.audio_waveform_cache_order, 1, -1 do
        if state.audio_waveform_cache_order[index] == filepath then
            table.remove(state.audio_waveform_cache_order, index)
            break
        end
    end
    state.audio_waveform_cache_order[#state.audio_waveform_cache_order + 1] =
        filepath
    state.audio_waveform_cache[filepath] = peaks
    while #state.audio_waveform_cache_order > 128 do
        local oldest = table.remove(state.audio_waveform_cache_order, 1)
        state.audio_waveform_cache[oldest] = nil
    end
end

function CacheAudioKey(filepath, pitch_class, method)
    if not filepath then return end
    for index = #state.audio_key_cache_order, 1, -1 do
        if state.audio_key_cache_order[index] == filepath then
            table.remove(state.audio_key_cache_order, index)
            break
        end
    end
    state.audio_key_cache_order[#state.audio_key_cache_order + 1] = filepath
    state.audio_key_cache[filepath] = {
        pc = pitch_class,
        method = method,
    }
    while #state.audio_key_cache_order > 512 do
        local oldest = table.remove(state.audio_key_cache_order, 1)
        state.audio_key_cache[oldest] = nil
    end
end

-- ============================================================
-- NATIVE PREVIEW PLAYBACK ENGINE
-- ============================================================
function GetTotalPreviewPitchShift()
    local total_shift = state.pitch_shift or 0
    local bypass_key_sync = state.media_kind == "midi"
        and state.current_file_is_one_shot
        and state.one_shot_bypass.key_sync
    if state.key_sync.enabled and not bypass_key_sync
        and state.loaded_midi and state.loaded_midi.detected_key_pc then
        total_shift = total_shift + ComputeKeySyncShift(state.loaded_midi.detected_key_pc, state.key_sync.target_pc)
    end
    return total_shift
end

local preview_stretch_mode_catalog
function GetPreviewStretchModeCatalog()
    if preview_stretch_mode_catalog then return preview_stretch_mode_catalog end

    local catalog = {{
        key = "project_default",
        label = "Project default",
        pitch_mode = -1,
    }}
    preview_stretch_mode_catalog = catalog
    if not r.EnumPitchShiftModes then return catalog end

    local best = {
        elastique_pro = {score = -1},
        elastique_efficient = {score = -1},
    }
    for mode = 0, 255 do
        local available, name = r.EnumPitchShiftModes(mode)
        if not available then break end
        local mode_name = tostring(name or "")
        local normalized = mode_name:lower()
        if normalized:find("lastique", 1, true) then
            local key, score
            if normalized:find("pro", 1, true) then
                key = "elastique_pro"
                score = normalized:find("3.3.3", 1, true) and 300
                    or (normalized:find("3", 1, true) and 200 or 100)
            elseif normalized:find("efficient", 1, true) then
                key = "elastique_efficient"
                score = normalized:find("3.3.3", 1, true) and 300
                    or (normalized:find("3", 1, true) and 200 or 100)
            end
            if key and score > best[key].score then
                best[key] = {score = score, mode = mode, name = mode_name}
            end
        end
    end

    for _, key in ipairs({"elastique_pro", "elastique_efficient"}) do
        local candidate = best[key]
        if candidate.mode ~= nil then
            local submode, submode_name = 0, ""
            if r.EnumPitchShiftSubModes then
                for index = 0, 255 do
                    local name = r.EnumPitchShiftSubModes(candidate.mode, index)
                    if not name or name == "" then break end
                    if index == 0 then submode_name = tostring(name) end
                    local normalized = tostring(name):lower()
                    if normalized == "normal"
                        or normalized:find("normal", 1, true) then
                        submode, submode_name = index, tostring(name)
                        break
                    end
                end
            end
            local label = candidate.name
            if submode_name ~= "" then label = label .. " - " .. submode_name end
            catalog[#catalog + 1] = {
                key = key,
                label = label,
                pitch_mode = (candidate.mode << 16) | submode,
            }
        end
    end
    return catalog
end

function GetSelectedPreviewStretchMode()
    local requested = state.preview_stretch_mode or "elastique_pro"
    local catalog = GetPreviewStretchModeCatalog()
    for _, choice in ipairs(catalog) do
        if choice.key == requested then return choice end
    end
    -- Preserve the old compatibility chain when Pro is requested but is not
    -- installed: Efficient is preferable to losing tempo matching entirely.
    if requested == "elastique_pro" then
        for _, choice in ipairs(catalog) do
            if choice.key == "elastique_efficient" then return choice end
        end
    end
    return catalog[1]
end

function GetPreferredElastiquePitchMode()
    return GetSelectedPreviewStretchMode().pitch_mode
end

function GetSelectedPreviewPitchMode()
    return GetSelectedPreviewStretchMode().pitch_mode
end

function GetMIDILoopEnabled()
    return state.loop_preview
        and not (state.current_file_is_one_shot
            and state.one_shot_bypass.loop)
end

function GetMIDIPreviewCycleQN(arrangement_sync)
    local authored_qn = math.max(0.000001,
        tonumber(state.file_playback_duration_qn)
            or tonumber(state.file_duration_qn) or 0.000001)
    if GetMIDILoopEnabled() then
        -- Exported MIDI commonly stores only its final event rather than the
        -- original item boundary. Looping at that event puts terminal note-off
        -- and source-cleanup messages directly against tick-zero note-ons,
        -- which can silence the opening chord at an exact 1x boundary. Every
        -- looped musical preview therefore uses the already calculated visual
        -- bar cycle, whether free-running or arrangement-synced. Non-loop and
        -- non-loop playback retains the exact authored endpoint.
        return math.max(authored_qn,
            tonumber(state.file_duration_qn) or authored_qn)
    end
    return authored_qn
end

function GetNativeMIDITempoRate(source_duration, project_qn, cycle_qn)
    local bypass_tempo = state.current_file_is_one_shot
        and state.one_shot_bypass.tempo_match
    if not state.tempo_match_enabled or bypass_tempo then return 1.0 end
    local midi_qn = math.max(0.000001,
        tonumber(cycle_qn) or GetMIDIPreviewCycleQN(false))
    local qn_to_time = r.TimeMap2_QNToTime
    if type(qn_to_time) ~= "function" then return 1.0 end
    local start_time = qn_to_time(0, project_qn)
    local end_time = qn_to_time(0, project_qn + midi_qn)
    local target_duration = math.max(0.000001, end_time - start_time)
    -- Native MIDI preview time is based at 120 BPM: one QN is 0.5 seconds.
    -- Use the same parsed musical QN span on both sides so trailing rests do
    -- not alter the tempo ratio.
    local baseline_duration = midi_qn * 0.5
    return math.max(0.01, baseline_duration / target_duration)
end

function GetQNSpanSeconds(start_qn, length_qn)
    if type(r.TimeMap2_QNToTime) ~= "function" then return nil end
    local start_time = r.TimeMap2_QNToTime(0, start_qn)
    local end_time = r.TimeMap2_QNToTime(0, start_qn + length_qn)
    return math.max(0.000001, end_time - start_time)
end

function GetNativeMIDIOutputLength(source_duration, project_qn,
    manual_rate, tempo_rate, cycle_qn_override)
    local bypass_tempo = state.current_file_is_one_shot
        and state.one_shot_bypass.tempo_match
    if state.tempo_match_enabled and not bypass_tempo then
        local musical_qn = math.max(0.000001,
            (tonumber(cycle_qn_override)
                or GetMIDIPreviewCycleQN(false)) / manual_rate)
        local musical_seconds = GetQNSpanSeconds(project_qn, musical_qn)
        if musical_seconds then return musical_seconds end
    end
    if cycle_qn_override then
        -- Without tempo matching, native MIDI's neutral clock is 120 BPM.
        -- Preserve the arrangement-only padded cycle at that clock rate.
        return math.max(0.000001,
            tonumber(cycle_qn_override) * 0.5 / manual_rate)
    end
    return math.max(0.000001, source_duration
        / math.max(0.01, tempo_rate * manual_rate))
end

function GetLoopBounds()
    local repeat_enabled = r.GetSetRepeat(-1) == 1
    local loop_start_time, loop_end_time =
        r.GetSet_LoopTimeRange2(0, false, true, 0, 0, false)
    if not repeat_enabled or loop_end_time <= loop_start_time then
        return nil, nil, nil, nil
    end
    return r.TimeMap2_timeToQN(0, loop_start_time),
        r.TimeMap2_timeToQN(0, loop_end_time),
        loop_start_time, loop_end_time
end

function GetLoopBoundsQN()
    local loop_start_qn, loop_end_qn = GetLoopBounds()
    return loop_start_qn, loop_end_qn
end

function GetNativeMIDITransportLoopSnapshot(sync_enabled)
    if not sync_enabled then return 0, 0, 0, 0 end
    local start_qn, end_qn, start_time, end_time = GetLoopBounds()
    if not start_qn or not end_qn or not start_time or not end_time then
        return 0, 0, 0, 0
    end
    return 1, start_time, end_time,
        math.max(0.000001, end_qn - start_qn)
end

function RefreshPlaybackClassification()
    local raw_qn = state.loaded_midi and state.loaded_midi.raw_duration_qn or 0
    local bar_qn = state.file_bar_qn or 4
    local raw_bars = bar_qn > 0 and raw_qn / bar_qn or 0
    local one_shot_class = state.current_media_class == "one-shot"
    state.current_file_is_one_shot = state.one_shot_mode
        and (one_shot_class or raw_bars < 1)
end

function GetPreviewTransportMode()
    local mode = state.preview_transport_mode
    if mode ~= "independent" and mode ~= "follow" and mode ~= "control" then
        mode = "follow"
    end
    state.preview_transport_mode = mode
    return mode
end

-- Preview controls are clicked frequently and are also used beside unrelated
-- REAPER script GUIs. Persist only their small preference set here instead of
-- running the full settings writer (which also serializes roots, themes,
-- Favorites, tags, and FX state on every click).
function SavePreviewPreferences(kind)
    if not kind or kind == "auto_play" then
        r.SetExtState(EXT_SECTION, "auto_play",
            state.auto_play and "1" or "0", true)
    end
    if not kind or kind == "transport" then
        r.SetExtState(EXT_SECTION, "preview_transport_mode",
            state.preview_transport_mode or "follow", true)
    end
    if not kind or kind == "loop" then
        r.SetExtState(EXT_SECTION, "loop_preview",
            state.loop_preview and "1" or "0", true)
    end
    if not kind or kind == "tempo" then
        r.SetExtState(EXT_SECTION, "tempo_match_enabled",
            state.tempo_match_enabled and "1" or "0", true)
    end
    if not kind or kind == "stretch_mode" then
        r.SetExtState(EXT_SECTION, "preview_stretch_mode",
            state.preview_stretch_mode or "elastique_pro", true)
    end
    if not kind or kind == "playrate" then
        r.SetExtState(EXT_SECTION, "playrate",
            tostring(state.playrate or 1.0), true)
    end
    if not kind or kind == "piano" or kind == "key_sync" then
        r.SetExtState(EXT_SECTION, "piano_open",
            state.piano_open and "1" or "0", true)
        r.SetExtState(EXT_SECTION, "key_sync_enabled",
            state.key_sync.enabled and "1" or "0", true)
        r.SetExtState(EXT_SECTION, "key_sync_target_pc",
            tostring(state.key_sync.target_pc or 0), true)
    end
end

function PreviewFollowsArrangement()
    return GetPreviewTransportMode() == "follow"
end

function PreviewControlsTransport()
    return GetPreviewTransportMode() == "control"
end

function PreviewUsesArrangementClock()
    local mode = GetPreviewTransportMode()
    return mode == "follow" or mode == "control"
end

function SetPreviewTransportMode(mode)
    if mode ~= "independent" and mode ~= "follow" and mode ~= "control" then
        return
    end
    local previous_mode = GetPreviewTransportMode()
    state.preview_transport_mode = mode
    if mode == "control" and previous_mode ~= "control"
        and state.is_playing then
        -- Entering Control is an explicit handoff. Do not unexpectedly move
        -- an already-running REAPER transport; wait for the next browser Play.
        StopPreview(true)
    else
        ApplyPlaybackSettings()
    end
    SavePreviewPreferences("transport")
end

function GetManualPreviewRate()
    local bypass = state.media_kind == "audio"
        and GetCurrentAudioPlaybackPolicy().is_one_shot
        and state.one_shot_bypass.playrate
    if state.media_kind == "midi" then
        bypass = state.current_file_is_one_shot
            and state.one_shot_bypass.playrate
    end
    return bypass and 1.0 or math.max(0.01, state.playrate or 1.0)
end

function GetArrangementQNPosition()
    local position = (r.GetPlayState() & 1) ~= 0
        and ((r.GetPlayPosition2 and r.GetPlayPosition2()) or r.GetPlayPosition())
        or r.GetCursorPosition()
    return r.TimeMap2_timeToQN(0, position), position
end

function GetArrangementSyncOriginQN(project_qn)
    local loop_start_qn, loop_end_qn = GetLoopBoundsQN()
    if loop_start_qn and project_qn >= loop_start_qn - 0.000001
        and project_qn < loop_end_qn + 0.000001 then
        return loop_start_qn
    end
    return 0
end

function GetAudioArrangementSourcePosition(duration, effective_rate,
    output_length_s, ignore_seek_offset)
    duration = math.max(tonumber(duration) or 0, 0)
    if duration <= 0 then return 0 end
    effective_rate = math.max(0.000001, effective_rate or 1.0)
    local project_qn, project_time = GetArrangementQNPosition()
    local origin_qn = GetArrangementSyncOriginQN(project_qn)
    output_length_s = math.max(0.000001,
        tonumber(output_length_s) or (duration / effective_rate))
    local end_qn = r.TimeMap2_timeToQN(
        0, project_time + output_length_s)
    local raw_length_qn = math.max(end_qn - project_qn, 0.000001)
    -- Media decoders commonly expose a few padded samples at either end.
    -- Never use that fractional tail as the musical modulo: two nominally
    -- identical loops would otherwise acquire different phase grids during a
    -- handoff. Quarter-note normalization matches the browser's launch
    -- resolution while retaining long-loop bar counts.
    local effective_length_qn = math.max(
        0.25, math.floor(raw_length_qn * 4 + 0.5) / 4)
    local phase_qn = math.max(0, project_qn - origin_qn)
        % effective_length_qn
    if not ignore_seek_offset then
        phase_qn = (phase_qn
            + (state.preview_sync_phase_offset_fraction or 0)
                * effective_length_qn) % effective_length_qn
    end
    return (phase_qn / effective_length_qn) * duration,
        effective_length_qn
end

function ResyncAudioPreviewToArrangement()
    if state.media_kind ~= "audio" or not state.audio_preview then return end
    local duration = math.max(
        state.audio_preview_length or state.audio_length or 0, 0)
    if duration <= 0 then return end
    local source_position = GetAudioArrangementSourcePosition(
        duration, state.audio_preview_rate or 1.0,
        state.audio_preview_output_length)
    if state.native_preview_kind == "audio"
        and type(r.ReaBrowse_SetNativePreviewPosition) == "function" then
        r.ReaBrowse_SetNativePreviewPosition(source_position)
    end
end

function MIDITransportModeApplies()
    return not (state.current_file_is_one_shot
        and state.one_shot_bypass.sync)
end

function PrepareLinkedTransportStart(enabled)
    if not enabled then return false end
    local play_state = r.GetPlayState()
    if (play_state & 4) ~= 0 then return nil end
    if (play_state & 1) ~= 0 then r.CSurf_OnStop() end
    r.SetEditCurPos(0, false, false)
    return true
end

function StartPreparedLinkedTransport(prepared)
    if prepared then r.CSurf_OnPlay() end
end

function GetControlTransportRestartDelay()
    local function ReadDeviceNumber(attribute)
        if not r.GetAudioDeviceInfo then return nil end
        local ok, first, second = pcall(r.GetAudioDeviceInfo, attribute)
        if not ok then return nil end
        local value = type(first) == "string" and first or second
        value = tonumber(value)
        return value and value > 0 and value or nil
    end
    local block_size = ReadDeviceNumber("BSIZE")
    local sample_rate = ReadDeviceNumber("SRATE")
    if not block_size or not sample_rate then return 0.10 end
    -- Leave two complete device blocks plus a small scheduling margin between
    -- REAPER's transport stop cleanup and the replacement preview.
    return math.max(0.06, math.min(0.25,
        block_size / sample_rate * 2 + 0.03))
end

-- Keep the audio playback policy in one place.  Classification and the MX
-- tuner/key path remain separate; this only prevents one-shot audio from
-- accidentally inheriting loop/tempo behavior in one of the UI paths.
function GetCurrentAudioPlaybackPolicy()
    local is_audio = state.media_kind == "audio"
    -- While One-Shot Mode is enabled, protect sub-100 ms triggers from loop and
    -- tempo behavior even when classification is ambiguous. Disabling the mode
    -- releases this safeguard along with every other one-shot bypass.
    local very_short = is_audio
        and (tonumber(state.audio_length) or 0) > 0
        and (tonumber(state.audio_length) or 0) <= 0.10
    -- One-Shot Mode is the authority. Classification remains available while
    -- the mode is disabled, but it must not leave any playback behavior latched.
    local is_one_shot = is_audio and state.audio_auto_one_shot
        and (very_short or state.current_media_class == "one-shot")
    local bypass = state.one_shot_bypass
    local transport_allowed = not (is_one_shot and bypass.sync)
    local transport_mode = GetPreviewTransportMode()
    return {
        is_one_shot = is_one_shot,
        sync = is_audio and transport_mode == "follow"
            and transport_allowed,
        link_transport = is_audio and transport_mode == "control"
            and transport_allowed,
        loop = is_audio and state.loop_preview
            and not (is_one_shot and bypass.loop),
        tempo_match = is_audio
            and state.tempo_match_enabled
            and not (is_one_shot and bypass.tempo_match),
        key_sync = is_audio and state.key_sync.enabled
            and not (is_one_shot and bypass.key_sync),
        rate_controls = is_audio
            and not (is_one_shot and bypass.playrate),
    }
end

function ApplyOneShotPolicyChange()
    if state.media_kind == "audio" then
        local was_one_shot = state.audio_current_is_one_shot
        local policy = GetCurrentAudioPlaybackPolicy()
        state.audio_current_is_one_shot = policy.is_one_shot
        if policy.loop then
            state.audio_preview_expected_end = nil
        end
        if state.is_playing and (was_one_shot or policy.is_one_shot) then
            StartPreview()
        else
            ApplyPlaybackSettings()
        end
    elseif state.media_kind == "midi" then
        RefreshPlaybackClassification()
        if state.is_playing then StartPreview() else ApplyPlaybackSettings() end
    end
end

local function ReadBE16(data, pos)
    local a, b = data:byte(pos, pos + 1)
    if not a or not b then return nil end
    return a * 256 + b
end

local function ReadBE32(data, pos)
    local a, b, c, d = data:byte(pos, pos + 3)
    if not a or not b or not c or not d then return nil end
    return ((a * 256 + b) * 256 + c) * 256 + d
end

local function ReadVLQ(data, pos, limit)
    local value = 0
    for _ = 1, 4 do
        if pos > limit then return nil, pos end
        local byte = data:byte(pos)
        pos = pos + 1
        value = (value << 7) | (byte & 0x7F)
        if (byte & 0x80) == 0 then return value, pos end
    end
    -- Standard MIDI VLQs are at most four bytes. A continuation bit on the
    -- fourth byte is malformed rather than a truncated-but-usable value.
    return nil, pos
end

function CloneParsedMIDIForUse(parsed)
    if not parsed then return nil end
    local copy = {}
    for key, value in pairs(parsed) do copy[key] = value end
    return copy
end

function RemoveParsedMIDICacheEntry(cache_key)
    local entry = state.midi_parse_cache[cache_key]
    if not entry then return end
    state.midi_parse_cache[cache_key] = nil
    state.midi_parse_cache_bytes = math.max(0,
        (state.midi_parse_cache_bytes or 0) - (entry.bytes or 0))
    for index = #state.midi_parse_cache_order, 1, -1 do
        if state.midi_parse_cache_order[index] == cache_key then
            table.remove(state.midi_parse_cache_order, index)
            break
        end
    end
end

function TouchParsedMIDICacheEntry(cache_key)
    for index = #state.midi_parse_cache_order, 1, -1 do
        if state.midi_parse_cache_order[index] == cache_key then
            table.remove(state.midi_parse_cache_order, index)
            break
        end
    end
    state.midi_parse_cache_order[#state.midi_parse_cache_order + 1] = cache_key
end

function CacheParsedMIDI(cache_key, parsed, file_size)
    -- Account for the source bytes and a conservative estimate of Lua table
    -- storage. Oversized/complex files remain one-shot parses rather than
    -- displacing the entire bounded audition cache.
    local estimated_bytes = math.max(0, tonumber(file_size) or 0)
        + #(parsed.events or {}) * 96 + #(parsed.notes or {}) * 80 + 1024
    RemoveParsedMIDICacheEntry(cache_key)
    if estimated_bytes > MAX_MIDI_PARSE_CACHE_BYTES then return end
    state.midi_parse_cache[cache_key] = {
        parsed = parsed,
        file_size = file_size,
        bytes = estimated_bytes,
        expires_at = r.time_precise() + MIDI_PARSE_CACHE_TTL_SECONDS,
    }
    state.midi_parse_cache_order[#state.midi_parse_cache_order + 1] = cache_key
    state.midi_parse_cache_bytes =
        (state.midi_parse_cache_bytes or 0) + estimated_bytes
    while #state.midi_parse_cache_order > MAX_MIDI_PARSE_CACHE_ENTRIES
        or state.midi_parse_cache_bytes > MAX_MIDI_PARSE_CACHE_BYTES do
        RemoveParsedMIDICacheEntry(state.midi_parse_cache_order[1])
    end
end

function ParseStandardMIDIFile(filepath)
    local file = io.open(filepath, "rb")
    if not file then return nil, "Could not open MIDI file." end
    local file_size = file:seek("end")
    if not file_size then
        file:close()
        return nil, "Could not determine MIDI file size."
    end
    if file_size > MAX_MIDI_PREVIEW_FILE_BYTES then
        file:close()
        return nil, string.format(
            "MIDI file is too large to preview safely (%d MB limit).",
            math.floor(MAX_MIDI_PREVIEW_FILE_BYTES / 1024 / 1024))
    end
    -- MIDI event seconds depend on the current project tempo. Include it in
    -- the cache identity so a tempo change cannot reuse stale timing. File
    -- size plus a short TTL catches normal external edits without requiring a
    -- platform-specific stat API on every navigation step.
    local tempo = r.Master_GetTempo()
    local cache_key = NormalizeFavoritePath(filepath) .. "|"
        .. string.format("%.9g", tempo)
    local cached = state.midi_parse_cache[cache_key]
    if cached and cached.file_size == file_size
        and r.time_precise() <= (cached.expires_at or 0) then
        -- Refresh recency but not expiry: a repeatedly auditioned file must
        -- still be reparsed periodically so same-size external edits become
        -- visible without an application restart.
        TouchParsedMIDICacheEntry(cache_key)
        file:close()
        return CloneParsedMIDIForUse(cached.parsed)
    elseif cached then
        RemoveParsedMIDICacheEntry(cache_key)
    end
    file:seek("set", 0)
    local data = file:read("*a")
    file:close()
    if not data then return nil, "Could not read MIDI file." end

    if #data < 14 or data:sub(1, 4) ~= "MThd" then
        return nil, "Not a valid Standard MIDI File."
    end

    local header_length = ReadBE32(data, 5)
    local format = ReadBE16(data, 9)
    local track_count = ReadBE16(data, 11)
    local division = ReadBE16(data, 13)
    if not header_length or not format or not track_count or not division or division == 0 then
        return nil, "Invalid MIDI header."
    end
    if format > 2 or track_count == 0
        or track_count > MAX_MIDI_PREVIEW_TRACKS then
        return nil, "Unsupported or excessive MIDI track count."
    end

    local ticks_per_quarter
    local smpte_fps, smpte_ticks
    if (division & 0x8000) == 0 then
        ticks_per_quarter = division
    else
        local fps_byte = (division >> 8) & 0xFF
        local signed_fps = fps_byte >= 128 and fps_byte - 256 or fps_byte
        smpte_fps = math.abs(signed_fps)
        if smpte_fps == 29 then smpte_fps = 29.97 end
        smpte_ticks = division & 0xFF
        if smpte_fps == 0 or smpte_ticks == 0 then
            return nil, "Invalid MIDI SMPTE division."
        end
    end

    local events, order, parsed_event_count = {}, 0, 0
    local max_track_tick = 0
    local key_pc, file_numerator, file_denominator
    local pos = 9 + header_length

    for _ = 1, track_count do
        if pos + 7 > #data or data:sub(pos, pos + 3) ~= "MTrk" then
            return nil, "Invalid or truncated MIDI track."
        end
        local track_length = ReadBE32(data, pos + 4)
        local track_pos = pos + 8
        local track_end = track_pos + track_length - 1
        if track_end > #data then return nil, "Truncated MIDI track data." end

        local tick, running_status = 0, nil
        while track_pos <= track_end do
            parsed_event_count = parsed_event_count + 1
            if parsed_event_count > MAX_MIDI_PREVIEW_EVENTS then
                return nil, string.format(
                    "MIDI file has too many events to preview safely (%d limit).",
                    MAX_MIDI_PREVIEW_EVENTS)
            end
            local delta
            delta, track_pos = ReadVLQ(data, track_pos, track_end)
            if delta == nil then return nil, "Invalid MIDI delta time." end
            tick = tick + delta
            max_track_tick = math.max(max_track_tick, tick)

            local status = data:byte(track_pos)
            if not status then return nil, "Unexpected end of MIDI track." end
            if status < 0x80 then
                if not running_status then return nil, "Invalid MIDI running status." end
                status = running_status
            else
                track_pos = track_pos + 1
                if status < 0xF0 then running_status = status else running_status = nil end
            end

            if status == 0xFF then
                local meta_type = data:byte(track_pos)
                track_pos = track_pos + 1
                local length
                length, track_pos = ReadVLQ(data, track_pos, track_end)
                if not length or track_pos + length - 1 > track_end then return nil, "Invalid MIDI meta event." end
                if meta_type == 0x59 and length >= 2 and not key_pc then
                    local sf = data:byte(track_pos)
                    if sf >= 128 then sf = sf - 256 end
                    key_pc = KeySigToPitchClass(sf, data:byte(track_pos + 1) or 0)
                elseif meta_type == 0x58 and length >= 1 and not file_numerator then
                    file_numerator = data:byte(track_pos)
                    file_denominator = 2 ^ (data:byte(track_pos + 1) or 2)
                end
                track_pos = track_pos + length
            elseif status == 0xF0 or status == 0xF7 then
                local length
                length, track_pos = ReadVLQ(data, track_pos, track_end)
                if not length or track_pos + length - 1 > track_end then return nil, "Invalid SysEx event." end
                track_pos = track_pos + length
            elseif status >= 0x80 and status < 0xF0 then
                local kind = status & 0xF0
                local length = (kind == 0xC0 or kind == 0xD0) and 2 or 3
                local data1 = data:byte(track_pos)
                if not data1 then return nil, "Truncated MIDI channel event." end
                track_pos = track_pos + 1
                local data2 = 0
                if length == 3 then
                    data2 = data:byte(track_pos)
                    if not data2 then return nil, "Truncated MIDI channel event." end
                    track_pos = track_pos + 1
                end
                order = order + 1
                events[#events + 1] = {
                    tick = tick, order = order, status = status,
                    data1 = data1, data2 = data2, length = length,
                }
            else
                return nil, string.format("Unsupported MIDI status 0x%02X.", status)
            end
        end
        pos = track_end + 1
    end

    table.sort(events, function(a, b)
        if a.tick == b.tick then return a.order < b.order end
        return a.tick < b.tick
    end)

    local seconds_per_tick
    if ticks_per_quarter then
        seconds_per_tick = 60 / (tempo * ticks_per_quarter)
    else
        seconds_per_tick = 1 / (smpte_fps * smpte_ticks)
    end
    for _, event in ipairs(events) do
        event.time = event.tick * seconds_per_tick
        if ticks_per_quarter then
            event.qn = event.tick / ticks_per_quarter
        else
            event.qn = event.time * tempo / 60
        end
    end

    local notes = {}
    local active_notes = {}
    local min_note, max_note = 127, 0
    local min_time, max_time = math.huge, 0

    for _, event in ipairs(events) do
        local kind = event.status & 0xF0
        local channel = event.status & 0x0F
        local pitch = event.data1
        local key = channel * 128 + pitch
        local is_note_on = kind == 0x90 and event.data2 > 0
        local is_note_off = kind == 0x80 or (kind == 0x90 and event.data2 == 0)

        if is_note_on then
            active_notes[key] = active_notes[key] or {}
            table.insert(active_notes[key], {
                pitch = pitch, vel = event.data2, start_time = event.time, chan = channel
            })
            min_note = math.min(min_note, pitch)
            max_note = math.max(max_note, pitch)
            min_time = math.min(min_time, event.time)
        elseif is_note_off and active_notes[key] and #active_notes[key] > 0 then
            local note = table.remove(active_notes[key], 1)
            note.end_time = math.max(event.time, note.start_time + 0.000001)
            notes[#notes + 1] = note
            max_time = math.max(max_time, note.end_time)
        end
    end

    local last_event_time = #events > 0 and events[#events].time or 0
    local raw_duration = max_track_tick * seconds_per_tick
    local raw_duration_qn = ticks_per_quarter
        and max_track_tick / ticks_per_quarter
        or raw_duration * tempo / 60
    for _, stack in pairs(active_notes) do
        for _, note in ipairs(stack) do
            note.end_time = math.max(
                raw_duration, last_event_time, note.start_time + 0.001)
            notes[#notes + 1] = note
            max_time = math.max(max_time, note.end_time)
        end
    end
    table.sort(notes, function(a, b) return a.start_time < b.start_time end)

    local parsed = {
        format = format,
        events = events,
        notes = notes,
        min_note = min_note,
        max_note = max_note,
        min_time = min_time,
        max_time = max_time,
        key_pc = key_pc,
        numerator = file_numerator,
        denominator = file_denominator,
        -- Track time includes an explicit End-of-Track delta when present.
        -- This preserves authored trailing rests without adding bar padding.
        raw_duration_qn = raw_duration_qn,
        raw_duration = math.max(max_time, last_event_time, raw_duration),
    }
    CacheParsedMIDI(cache_key, parsed, file_size)
    return CloneParsedMIDIForUse(parsed)
end

function ApplyPlaybackSettings(kind)
    if state.media_kind == "audio" then
        if not state.audio_preview then return end
        if state.native_preview_kind == "audio" then
            if (not kind or kind == "volume")
                and type(r.ReaBrowse_SetNativePreviewVolume) == "function" then
                r.ReaBrowse_SetNativePreviewVolume(
                    10 ^ ((state.audio_volume_db or 0) / 20))
            elseif kind then
                -- Native rate, pitch, tempo and loop changes are applied when
                -- a preview starts, so recreate it with the new values.
                StartPreview()
            end
            if not kind and state.is_playing
                and PreviewUsesArrangementClock() then
                ResyncAudioPreviewToArrangement()
            end
            return
        end
        return
    else
        if state.native_preview_kind == "midi" and state.is_playing
            and type(r.ReaBrowse_ConfigureNativePreview) == "function" then
            -- Reconfiguring the native MIDI voice can reset its cursor. Keep
            -- the live position for independent preview loops so metadata
            -- changes (such as a key override) do not retrigger from zero.
            local preserved_position = nil
            if type(r.ReaBrowse_GetNativePreviewPosition) == "function" then
                preserved_position = tonumber(GetPreviewPosition())
            end
            local source_duration = math.max(0.000001,
                (tonumber(state.file_playback_duration_qn)
                    or tonumber(state.file_duration_qn) or 0.000001) * 0.5)
            local manual_rate = GetManualPreviewRate()
            local project_qn = GetArrangementQNPosition()
            local sync_enabled = PreviewUsesArrangementClock()
                and MIDITransportModeApplies()
                and (not PreviewFollowsArrangement()
                    or (r.GetPlayState() & 1) ~= 0)
            local cycle_qn = GetMIDIPreviewCycleQN(sync_enabled)
            local tempo_rate = GetNativeMIDITempoRate(
                source_duration, project_qn, cycle_qn)
            local origin_qn = GetArrangementSyncOriginQN(project_qn)
            local sync_length_qn = math.max(
                0.000001, cycle_qn / manual_rate)
            if sync_enabled then
                origin_qn = origin_qn
                    - (state.preview_sync_phase_offset_fraction or 0)
                        * sync_length_qn
            end
            local output_length = GetNativeMIDIOutputLength(
                source_duration, project_qn, manual_rate, tempo_rate,
                GetMIDILoopEnabled() and cycle_qn or nil)
            local authored_qn = math.max(0.000001,
                tonumber(state.file_playback_duration_qn) or cycle_qn)
            local transport_loop, transport_loop_start_s,
                transport_loop_end_s, transport_loop_length_qn =
                GetNativeMIDITransportLoopSnapshot(sync_enabled)
            local sync_spec = string.format(
                "%.17g|%.17g|%.17g|%.17g|%.17g|%.17g|%d|%d|%.17g|%.17g|%d|%.17g|%.17g|%.17g",
                sync_enabled and 1 or 0, origin_qn, sync_length_qn,
                tempo_rate * manual_rate, GetTotalPreviewPitchShift(),
                output_length, -1, 1, cycle_qn, authored_qn,
                transport_loop, transport_loop_start_s,
                transport_loop_end_s, transport_loop_length_qn)
            r.ReaBrowse_ConfigureNativePreview(sync_spec)
            if preserved_position and not sync_enabled
                and type(r.ReaBrowse_SetNativePreviewPosition) == "function" then
                local restored_position = math.max(0,
                    math.min(output_length, preserved_position))
                r.ReaBrowse_SetNativePreviewPosition(restored_position)
                state.preview_seek_fraction = output_length > 0
                    and restored_position / output_length or 0
            end
            state.audio_preview_rate = tempo_rate * manual_rate
            state.audio_preview_output_length = output_length
        end
    end
end

function RequestPlaybackSettingsApply(force, kind)
    -- Native slider movement stays local to the UI until it is committed.
    -- Wheel changes are coalesced, while mouse-up applies the final value.
    if force then
        ApplyPlaybackSettings(kind)
        state.playback_settings_last_apply = r.time_precise()
        state.playback_settings_apply_pending = false
        state.playback_settings_pending_kind = nil
    else
        state.playback_settings_apply_pending = true
        if not state.playback_settings_pending_kind then
            state.playback_settings_pending_kind = kind
        elseif state.playback_settings_pending_kind ~= kind then
            state.playback_settings_pending_kind = nil
        end
    end
end

function FlushPlaybackSettingsApply()
    if not state.playback_settings_apply_pending then return end
    -- Keep the preview responsive while dragging, but coalesce host writes so
    -- a fast mouse move does not issue a setter on every GUI frame. The
    -- committed mouse-up path still applies the final value immediately.
    local now = r.time_precise()
    if state.playback_settings_apply_pending
        and now - (state.playback_settings_last_apply or 0) >= 0.04 then
        ApplyPlaybackSettings(state.playback_settings_pending_kind)
        state.playback_settings_last_apply = now
        state.playback_settings_apply_pending = false
        state.playback_settings_pending_kind = nil
    end
end

function SavePlaybackControlSettings(kind)
    -- Slider changes must not call the full SaveSettings path. That function
    -- persists roots, theme palettes, suggestions, and every other setting;
    -- dozens of synchronous ExtState writes can stall every REAPER GUI script.
    if not kind or kind == "all" or kind == "pitch" then
        r.SetExtState(
            EXT_SECTION, "pitch_shift", tostring(state.pitch_shift), true)
    end
    if not kind or kind == "all" or kind == "volume" then
        r.SetExtState(
            EXT_SECTION, "audio_volume_db",
            tostring(state.audio_volume_db), true)
    end
end

function RequestPlaybackSettingsSave(immediate, kind)
    if immediate then
        SavePlaybackControlSettings(kind)
        state.playback_settings_save_pending = false
        state.playback_settings_save_pending_kind = nil
        state.playback_settings_save_due = 0
    else
        state.playback_settings_save_pending = true
        if state.playback_settings_save_pending_kind == "all" then
            -- Keep both values pending.
        elseif not state.playback_settings_save_pending_kind then
            state.playback_settings_save_pending_kind = kind
        elseif state.playback_settings_save_pending_kind ~= kind then
            state.playback_settings_save_pending_kind = "all"
        end
        state.playback_settings_save_due = r.time_precise() + 0.15
    end
end

function FlushPlaybackSettingsSave()
    if not state.playback_settings_save_pending then return end
    if r.time_precise() < (state.playback_settings_save_due or 0) then return end
    SavePlaybackControlSettings(state.playback_settings_save_pending_kind)
    state.playback_settings_save_pending = false
    state.playback_settings_save_pending_kind = nil
    state.playback_settings_save_due = 0
end

function ReleaseLoadedAudioSource()
    if state.audio_loaded_source then
        r.PCM_Source_Destroy(state.audio_loaded_source)
        state.audio_loaded_source = nil
    end
    state.audio_loaded_source_path = nil
end

function DestroyLoadedOrTemporaryAudioSource(source)
    if not source then return end
    if state.audio_loaded_source == source then
        state.audio_loaded_source = nil
        state.audio_loaded_source_path = nil
    end
    r.PCM_Source_Destroy(source)
end

function StopAudioPreview()
    if state.audio_preview_native
        and type(r.ReaBrowse_StopNativePreview) == "function" then
        r.ReaBrowse_StopNativePreview()
    end
    state.audio_preview = nil
    state.audio_preview_native = false
    state.native_preview_kind = nil
    state.audio_preview_output_length = nil
    state.audio_preview_expected_end = nil
    state.audio_preview_eof_watch_position = nil
    state.audio_preview_eof_watch_time = nil
    state.pending_audio_phase_sync_frames = 0
end

function LoadAudioFile(filepath, classification)
    if not FileExists(filepath) then return false end
    if type(r.ReaBrowse_CancelNativeWaveform) == "function" then
        r.ReaBrowse_CancelNativeWaveform()
    end
    local native_preview_available =
        type(r.ReaBrowse_StartNativePreview) == "function"
        and type(r.ReaBrowse_StopNativePreview) == "function"
    if not native_preview_available then
        local api_exists = type(r.APIExists) == "function"
        local start_registered = api_exists
            and r.APIExists("ReaBrowse_StartNativePreview") or false
        local stop_registered = api_exists
            and r.APIExists("ReaBrowse_StopNativePreview") or false
        local configure_registered = api_exists
            and r.APIExists("ReaBrowse_ConfigureNativePreview") or false
        r.ShowMessageBox(
            "Audio preview requires the ReaBrowse native companion DLL.\n\n"
                .. "Lua bindings: start="
                .. tostring(type(r.ReaBrowse_StartNativePreview))
                .. ", stop="
                .. tostring(type(r.ReaBrowse_StopNativePreview))
                .. "\nREAPER APIs: start=" .. tostring(start_registered)
                .. ", stop=" .. tostring(stop_registered)
                .. ", configure=" .. tostring(configure_registered),
            "ReaBrowse", 0)
        return false
    end

    ReleaseLoadedAudioSource()
    state.audio_waveform_native_pending = false
    state.audio_waveform_native_generation = nil
    state.audio_waveform_native_path = nil
    local source = r.PCM_Source_CreateFromFileEx(filepath, true)
    if not source then
        r.ShowMessageBox("REAPER could not open this audio file.",
            "ReaBrowse", 0)
        return false
    end
    local source_channels = r.GetMediaSourceNumChannels(source) or 0
    if source_channels <= 0 then
        r.PCM_Source_Destroy(source)
        r.ShowMessageBox(
            "REAPER opened this container, but it has no previewable audio stream.",
            "ReaBrowse", 0)
        return false
    end

    state.source_file = filepath
    state.media_kind = "audio"
    state.file_playback_duration_qn = 0
    state.audio_current_is_one_shot = false
    state.current_file_is_one_shot = false
    state.loaded_midi = nil
    state.preview_setup_message = nil
    state.audio_length = r.GetMediaSourceLength(source) or 0
    state.audio_preview_length = state.audio_length
    state.file_duration_seconds = state.audio_length
    state.current_media_class = ResolveEffectiveMediaClass(
        filepath, classification)
    state.audio_detected_one_shot =
        state.current_media_class == "one-shot"
    state.audio_one_shot_method = "database classification"
    state.audio_peaks = state.audio_waveform_cache[filepath]
    if state.audio_peaks then
        CacheAudioWaveform(filepath, state.audio_peaks)
    elseif GetExistingAudioPeakFile(filepath) then
        -- Reading an existing REAPER peak cache from the source that is already
        -- open is cheap and does not start a second compressed-media decoder.
        state.audio_peaks = BuildAudioWaveform(source)
        if state.audio_peaks then
            CacheAudioWaveform(filepath, state.audio_peaks)
        end
    end
    local defer_waveform = state.keyboard_navigation_at
        and (r.time_precise() - state.keyboard_navigation_at) < 0.10
    state.audio_waveform_poll_at = 0
    if not state.audio_peaks then
        state.preview_setup_message =
            "Audio is playing; waveform peaks are still being prepared."
        state.audio_waveform_poll_at = r.time_precise()
            + (defer_waveform and 0.30 or 0.20)
        if type(r.ReaBrowse_RequestNativeWaveform) == "function"
            and type(r.ReaBrowse_PollNativeWaveform) == "function" then
            -- Let the native preview claim the cold decoder and storage path
            -- first. The UI loop starts peak generation after a short delay,
            -- preventing compressed/network files from opening twice during
            -- the first-sound critical path.
            state.audio_waveform_native_generation = nil
            state.audio_waveform_native_path = filepath
            state.audio_waveform_native_pending = true
        end
    end
    local cached_key = state.audio_key_cache[filepath]
    if cached_key then
        state.audio_detected_key_automatic_pc = cached_key.pc
        state.audio_detection_automatic_method = cached_key.method
        CacheAudioKey(filepath, cached_key.pc, cached_key.method)
    else
        state.audio_detected_key_automatic_pc,
            state.audio_detection_automatic_method =
            DetectAudioKey(filepath, source)
        CacheAudioKey(filepath, state.audio_detected_key_automatic_pc,
            state.audio_detection_automatic_method)
    end
    local manual_key = GetManualKeyOverrideEntry(filepath)
    state.audio_detected_key_pc = ResolveEffectiveKeyPitchClass(
        filepath, state.audio_detected_key_automatic_pc)
    state.audio_detection_method = manual_key
        and (manual_key.key_pc == false
            and "manual unkeyed" or "manual override")
        or state.audio_detection_automatic_method
    -- FFT analysis is intentionally reserved for the future background
    -- database worker. Running it from the GUI thread causes random hitches.
    -- Preserve the already-open source for the first preview trigger. Opening,
    -- inspecting, closing, and immediately reopening the same cold file added
    -- avoidable latency to the first audition inside a folder.
    state.audio_loaded_source = source
    state.audio_loaded_source_path = filepath
    return true
end

function LoadMIDIFile(filepath, classification, start_immediately)
    if not FileExists(filepath) then return false end
    ReleaseLoadedAudioSource()
    local parsed, err = ParseStandardMIDIFile(filepath)
    if not parsed then
        r.ShowMessageBox(err or "Could not parse MIDI file.", "ReaBrowse", 0)
        return false
    end

    -- Keep an active native MIDI voice registered when this selection will
    -- immediately replace it. StartNativePreview serializes that direct
    -- MIDI-to-MIDI handoff before the incoming opening notes are emitted.
    -- Stopping here would instead retire the old source for asynchronous
    -- cleanup; its delayed all-notes-off could then cut the new first chord.
    local preserve_native_midi_handoff = start_immediately == true
        and state.is_playing
        and state.audio_preview_native
        and state.native_preview_kind == "midi"

    state.source_file = filepath
    state.media_kind = "midi"
    state.current_media_class = ResolveEffectiveMediaClass(
        filepath, classification)
    if not preserve_native_midi_handoff then StopAudioPreview() end
    state.preview_setup_message = nil
    state.audio_peaks = nil
    state.audio_detected_key_pc = nil
    state.audio_detected_key_automatic_pc = nil
    state.loaded_midi = parsed
    state.loaded_midi.min_note = #parsed.notes > 0 and math.max(0, parsed.min_note - 4) or 0
    state.loaded_midi.max_note = #parsed.notes > 0 and math.min(127, parsed.max_note + 4) or 127

    local beat_len = 60 / r.Master_GetTempo()
    local project_num, project_denom = r.TimeMap_GetTimeSigAtTime(0, 0)
    local num = parsed.numerator or project_num
    local denom = parsed.denominator or project_denom
    if not denom or denom <= 0 then denom = 4 end
    local measure_qn = (num > 0 and num or 4) * 4 / denom
    state.file_bar_qn = measure_qn

    RefreshPlaybackClassification()

    if parsed.raw_duration_qn > 0 then
        -- Preserve both lengths. Free-running preview uses the SMF's authored
        -- endpoint; arrangement-synced looping may use a bar-aligned cycle so
        -- non-bar-aligned phrases do not drift against the grid.
        state.file_playback_duration_qn = parsed.raw_duration_qn
        local measures = math.ceil(
            (parsed.raw_duration_qn - 0.000001) / measure_qn)
        state.file_duration_qn = measures * measure_qn
    else
        state.file_playback_duration_qn = measure_qn
        state.file_duration_qn = measure_qn
    end
    state.file_duration_seconds = state.file_duration_qn * beat_len

    -- Keep the piano-roll axis on the complete file timeline used by the
    -- preview. Hiding leading MIDI silence made notes appear to start before
    -- playback reached them. This is display-only: MIDI parsing, playback,
    -- looping, and insertion retain their existing behavior.
    state.loaded_midi.display_duration = math.max(
        state.file_duration_seconds, 0.001)
    state.loaded_midi.automatic_key_pc =
        parsed.key_pc or DetectFileKeyPitchClass(filepath, nil)
    state.loaded_midi.detected_key_pc = ResolveEffectiveKeyPitchClass(
        filepath, state.loaded_midi.automatic_key_pc)

    -- The immediate StartPreview call installs the replacement configuration.
    -- Do not apply the new file's timing to the outgoing voice during the
    -- small direct-handoff window.
    if not preserve_native_midi_handoff then ApplyPlaybackSettings() end
    return true
end

function LoadBrowserFile(filepath, classification, start_immediately)
    if start_immediately ~= true then
        state.pending_control_transport_restart_at = nil
    end
    state.preview_seek_fraction = 0
    state.preview_sync_phase_offset_fraction = 0
    if IsMidiFile(filepath) then
        return LoadMIDIFile(filepath, classification, start_immediately)
    end
    if IsAudioFile(filepath) then
        -- The deferred transport restart is MIDI-only.  If the user selects
        -- audio during that short window, cancel the MIDI restart so it
        -- cannot suppress or replace the audio preview.
        state.pending_control_transport_restart_at = nil
        return LoadAudioFile(filepath, classification)
    end
    return false
end

function SetPlayrate(rate)
    local one_shot_bypasses_rate = state.one_shot_bypass.playrate
        and ((state.media_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().is_one_shot)
            or (state.media_kind == "midi"
                and state.current_file_is_one_shot))
    if math.abs(state.playrate - rate) < 0.0001 then
        state.playrate = 1.0
    else
        state.playrate = rate
    end
    -- The control always remains interactive. When the one-shot profile says
    -- to bypass manual rate, clicking only changes the global button state;
    -- the settings profile remains the sole authority over playback behavior.
    if not one_shot_bypasses_rate then ApplyPlaybackSettings("rate") end
    SavePreviewPreferences("playrate")
end

function GetAudioOutputPairLabel(channel)
    channel = math.max(0, math.floor(channel or 0))
    local first = r.GetOutputChannelName
        and r.GetOutputChannelName(channel) or nil
    local second = r.GetOutputChannelName
        and r.GetOutputChannelName(channel + 1) or nil
    first = first and first ~= "" and first
        or ("Output " .. tostring(channel + 1))
    second = second and second ~= "" and second
        or ("Output " .. tostring(channel + 2))
    return first .. " / " .. second
end

function GetAudioOutputMonoLabel(channel)
    channel = math.max(0, math.floor(channel or 0))
    local name = r.GetOutputChannelName
        and r.GetOutputChannelName(channel) or nil
    return name and name ~= "" and name
        or ("Output " .. tostring(channel + 1))
end

function GetAvailableAudioOutputs()
    local reported_count = r.GetNumAudioOutputs
        and math.max(0, math.floor(r.GetNumAudioOutputs() or 0)) or 0
    local outputs = {}
    local seen = {}
    for channel = 0, reported_count - 1 do
        local name = r.GetOutputChannelName
            and r.GetOutputChannelName(channel) or nil
        outputs[#outputs + 1] = {
            channel = channel,
            name = name and name ~= "" and name
                or ("Output " .. tostring(channel + 1)),
        }
        seen[channel] = true
    end
    return outputs, seen
end

function GetAudioRouteLabel()
    if state.audio_route_mode == "hardware_output" then
        if state.audio_route_output_mono then
            return GetAudioOutputMonoLabel(state.audio_route_output_channel)
                .. " (mono)"
        end
        return GetAudioOutputPairLabel(state.audio_route_output_channel)
    end
    return "Selected track"
end

function GetActiveAudioPreviewRouteText()
    if not state.is_playing
        or state.native_preview_kind ~= "audio" then
        return nil
    end
    if state.routed_track then
        local ok, _, track_name = pcall(
            r.GetTrackName, state.routed_track)
        if ok and track_name and track_name ~= "" then
            return "Preview: " .. track_name .. " > Master"
        end
        return "Preview: track destination > Master"
    end
    local channel = state.routed_output_channel or 0
    local output = state.routed_output_mono
        and GetAudioOutputMonoLabel(channel)
        or GetAudioOutputPairLabel(channel)
    if state.routed_output_mono then output = output .. " (mono)" end
    return "Preview: direct output > " .. output
end

function GetAudioPreviewStatusText()
    local message = state.preview_setup_message
    local route_message = not message
        or message == "Audio: native preview > selected track"
        or message == "Audio: native preview > hardware output"
        or message == "Preview: selected track > Master"
    local actual_route = GetActiveAudioPreviewRouteText()
    if actual_route then return actual_route end
    if not route_message then return message end
    if state.audio_route_mode == "hardware_output" then
        return "Preview: direct output > " .. GetAudioRouteLabel()
    end
    return "Preview: selected track > Master"
end

function SetAudioRoute(mode, output_channel, mono)
    if mode ~= "selected_track" and mode ~= "hardware_output" then return end
    local changed = state.audio_route_mode ~= mode
        or (mode == "hardware_output"
            and (state.audio_route_output_channel ~= output_channel
                or state.audio_route_output_mono ~= (mono == true)))
    state.audio_route_mode = mode
    if mode == "hardware_output" then
        state.audio_route_output_channel = math.max(
            0, math.floor(output_channel or 0))
        state.audio_route_output_mono = mono == true
    end
    SaveSettings()
    if changed and state.media_kind == "audio" and state.is_playing then
        StartPreview()
    end
end

function StartPreview()
    if state.pending_control_transport_restart_at then return end
    if state.media_kind == "midi" and PreviewControlsTransport()
        and MIDITransportModeApplies() then
        local play_state = r.GetPlayState()
        if (play_state & 1) ~= 0 and (play_state & 4) == 0 then
            -- REAPER's transport stop sends a track-wide MIDI reset. Starting
            -- the replacement preview and transport in this same UI frame lets
            -- that reset arrive after its first note-ons. Complete the stop
            -- first; Loop() starts only the latest selected file after two
            -- audio blocks have drained.
            StopAudioPreview()
            state.is_playing = false
            r.CSurf_OnStop()
            r.SetEditCurPos(0, false, false)
            state.pending_control_transport_restart_at = r.time_precise()
                + GetControlTransportRestartDelay()
            state.preview_setup_message = "Preparing MIDI transport..."
            return
        end
    end
    if state.media_kind == "audio" then
        if not state.source_file or state.source_file == "" then
            state.preview_setup_message = "No audio file is selected."
            return
        end
        -- Explicit Independent-mode file triggers are sampler-style starts:
        -- use only the waveform seek for the selected source. Settings-driven
        -- rebuilds still preserve the live cursor through the normal fallback.
        local start_from_waveform_seek =
            state.pending_audio_start_from_seek == true
        state.pending_audio_start_from_seek = false
        local handoff_position = not start_from_waveform_seek
            and (state.pending_audio_handoff_position
                or (state.is_playing and GetPreviewPosition() or nil)) or nil
        state.pending_audio_handoff_position = nil
        -- The global mode only changes audio classified as a one-shot. Audio
        -- loops keep their normal rate, key, loop and transport behavior.
        local policy = GetCurrentAudioPlaybackPolicy()
        local transport_running = (r.GetPlayState() & 1) ~= 0
        local arrangement_sync_active = policy.sync and transport_running
        -- Follow Arrangement supplies phase only while REAPER is actually
        -- playing. While stopped, selection changes behave like an ordinary
        -- browser preview and begin at the saved seek point.
        if policy.sync and not transport_running then
            handoff_position = nil
        end
        local source
        if policy.tempo_match then
            if state.audio_loaded_source
                and state.audio_loaded_source_path == state.source_file then
                source = state.audio_loaded_source
            else
                ReleaseLoadedAudioSource()
                source = r.PCM_Source_CreateFromFileEx(
                    state.source_file, true)
                state.audio_loaded_source = source
                state.audio_loaded_source_path = source
                    and state.source_file or nil
            end
            if not source then
                state.preview_setup_message =
                    "REAPER could not open this audio source."
                return
            end
        else
            -- The source opened during selection can become the native
            -- preview decoder after all Lua-side inspection is complete.
            -- Retriggers after that first handoff still use the native
            -- engine's normal open path so the active voice is never stolen.
            if state.audio_loaded_source
                and state.audio_loaded_source_path == state.source_file then
                source = state.audio_loaded_source
            else
                ReleaseLoadedAudioSource()
            end
        end
        if policy.is_one_shot then
            -- One-shots are triggers, not phase-continuous handoffs. Carrying
            -- the outgoing cursor into a retrigger made Right Arrow resume the
            -- same hit, and could clamp a shorter replacement to its EOF.
            handoff_position = nil
        end
        local linked_start = policy.link_transport == true
        local position = linked_start and 0 or ((r.GetPlayState() & 1) ~= 0
            and r.GetPlayPosition() or r.GetCursorPosition())
        state.audio_current_is_one_shot = policy.is_one_shot
        local manual_rate = policy.rate_controls
            and math.max(0.01, state.playrate or 1.0) or 1.0
        local tempo_rate = 1.0
        local tempo_target_length = nil
        if policy.tempo_match then
            local source_bpm = DetectExplicitFilenameBPM(state.source_file)
            local project_bpm = r.TimeMap_GetDividedBpmAtTime
                and r.TimeMap_GetDividedBpmAtTime(0, position)
                or r.Master_GetTempo()
            if source_bpm and project_bpm and project_bpm > 0 then
                tempo_rate = project_bpm / source_bpm
            else
                local matched, rate, target_length = r.GetTempoMatchPlayRate(
                    source, 1.0, position, 1.0)
                if matched and rate and rate > 0 then
                    tempo_rate = rate
                    if type(target_length) == "number"
                        and target_length > 0 then
                        tempo_target_length = target_length
                    end
                end
            end
        end
        local matched_rate = tempo_rate * manual_rate
        local correction = 0
        if policy.key_sync and state.audio_detected_key_pc ~= nil then
            correction = ComputeKeySyncShift(
                state.audio_detected_key_pc, state.key_sync.target_pc)
        end
        local pitch = (state.pitch_shift or 0) + correction
        local duration = math.max(
            tonumber(state.audio_length) or 0,
            tonumber(state.audio_preview_length) or 0)
        local output_length = math.max(0.000001,
            (tempo_target_length or (duration / tempo_rate)) / manual_rate)
        local sync_origin_qn = 0
        local sync_length_qn = 0
        local seek_position = linked_start and 0 or math.max(0, math.min(
            duration,
            handoff_position or ((state.preview_seek_fraction or 0) * duration)))
        if arrangement_sync_active and duration > 0 then
            local project_qn = GetArrangementQNPosition()
            sync_origin_qn = GetArrangementSyncOriginQN(project_qn)
            seek_position, sync_length_qn = GetAudioArrangementSourcePosition(
                duration, matched_rate, output_length)
            sync_origin_qn = sync_origin_qn
                - (state.preview_sync_phase_offset_fraction or 0)
                    * sync_length_qn
        elseif handoff_position and duration > 0 and policy.loop then
            seek_position = handoff_position % duration
        end
        local native_available =
            type(r.ReaBrowse_StartNativePreview) == "function"
            and type(r.ReaBrowse_StopNativePreview) == "function"
        if native_available then
            local output_track = state.audio_route_mode == "selected_track"
                and r.GetSelectedTrack(0, 0) or nil
            local outchan = math.max(0, math.floor(
                state.audio_route_output_channel or 0))
                | (state.audio_route_output_mono and 1024 or 0)
            local project = r.EnumProjects(-1, "")
            local linked_transport_prepared =
                PrepareLinkedTransportStart(linked_start)
            if linked_start and linked_transport_prepared == nil then
                DestroyLoadedOrTemporaryAudioSource(source)
                state.is_playing = false
                state.preview_setup_message =
                    "Linked transport is unavailable while recording."
                return
            end
            -- The selected installed stretch mode is packed as REAPER's
            -- (mode << 16) | submode quality value. Project default is -1.
            local pitch_mode = GetSelectedPreviewPitchMode()
            -- Companion v6 treats a neutral one-shot as one persistent,
            -- monophonic source. Older companions ignore the optional final
            -- field and retain their previous preview lifecycle.
            local native_sync_spec = string.format(
                "%.17g|%.17g|%.17g|%.17g|%.17g|%.17g|%d|0|0|0|0|0|0|0|%d",
                arrangement_sync_active and 1 or 0,
                sync_origin_qn, sync_length_qn, matched_rate, pitch,
                output_length, pitch_mode, policy.is_one_shot and 1 or 0)
            if type(r.ReaBrowse_ConfigureNativePreview) ~= "function"
                or r.ReaBrowse_ConfigureNativePreview(native_sync_spec) ~= 1 then
                ReleaseLoadedAudioSource()
                state.is_playing = false
                state.preview_setup_message =
                    "The native audio engine configuration API is unavailable."
                return
            end
            if source
                and type(r.ReaBrowse_PrepareNativePreviewSource)
                    == "function" then
                -- Ownership crosses the API boundary only on an explicit
                -- success result. StartNativePreview consumes this exact path
                -- synchronously; on any rejection Lua retains and destroys it.
                local accepted = r.ReaBrowse_PrepareNativePreviewSource(
                    state.source_file, source)
                if accepted == 1 or accepted == true then
                    if state.audio_loaded_source == source then
                        state.audio_loaded_source = nil
                        state.audio_loaded_source_path = nil
                    end
                    source = nil
                end
            end
            if source then
                DestroyLoadedOrTemporaryAudioSource(source)
                source = nil
            end
            local played = r.ReaBrowse_StartNativePreview(
                state.source_file, seek_position,
                policy.loop and 1 or 0,
                10 ^ ((state.audio_volume_db or 0) / 20),
                outchan, output_track, project)
            if played ~= 1 and played ~= true then
                state.is_playing = false
                state.preview_setup_message =
                    "REAPER could not start the native audio preview."
                return
            end
            state.audio_preview = true
            state.audio_preview_native = true
            state.native_preview_kind = "audio"
            state.audio_preview_length = duration
            state.audio_preview_output_length = output_length
            state.audio_preview_rate = matched_rate
            state.routed_track = output_track
            state.routed_output_channel = outchan & 1023
            state.routed_output_mono = (outchan & 1024) ~= 0
            state.preview_setup_message = output_track
                and "Audio: native preview > selected track"
                or "Audio: native preview > hardware output"
            state.audio_preview_expected_end = not policy.loop and duration > 0
                and (r.time_precise() + math.max(0,
                    output_length * (1 - seek_position / duration)) + 0.12)
                or nil
            state.audio_preview_eof_watch_position = nil
            state.audio_preview_eof_watch_time = nil
            state.is_playing = true
            -- The native audio decoder accepts its start cursor
            -- asynchronously. Re-apply arrangement phase once after two UI
            -- frames, matching the last stable pre-pitch audio lifecycle.
            state.pending_audio_phase_sync_frames =
                (arrangement_sync_active or policy.link_transport) and 2 or 0
            StartPreparedLinkedTransport(linked_transport_prepared)
            return
        end
        if not native_available then
            if source then r.PCM_Source_Destroy(source) end
            state.is_playing = false
            state.preview_setup_message =
                "The ReaBrowse native audio engine is unavailable."
            return
        end
    end
    if not state.loaded_midi then return end
    do
        local native_version = 0
        if type(r.ReaBrowse_GetNativeApiVersion) == "function" then
            local ok, value = pcall(r.ReaBrowse_GetNativeApiVersion)
            if ok then native_version = tonumber(value) or 0 end
        end
        state.native_companion_version = native_version
        if native_version < 5 then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "MIDI preview requires ReaBrowse native companion v5."
            return
        end
        local output_track = r.GetSelectedTrack(0, 0)
        if not output_track then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "Select the instrument track for native MIDI preview."
            return
        end
        if type(r.ReaBrowse_ConfigureNativePreview) ~= "function"
            or type(r.ReaBrowse_StartNativePreview) ~= "function" then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "The native MIDI preview API is unavailable."
            return
        end
        -- Control Transport is a one-time handoff: stop REAPER, place both
        -- clocks at project zero, register the MIDI preview, then start the
        -- transport.  The MIDI branch previously omitted this handoff and
        -- calculated its first phase from the old cursor position.
        local linked_transport_prepared =
            PrepareLinkedTransportStart(PreviewControlsTransport())
        if PreviewControlsTransport() and linked_transport_prepared == nil then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "Linked transport is unavailable while recording."
            return
        end
        local source_duration = math.max(0.000001,
            (tonumber(state.file_playback_duration_qn)
                or tonumber(state.file_duration_qn) or 0.000001) * 0.5)
        local project_qn = GetArrangementQNPosition()
        local manual_rate = GetManualPreviewRate()
        local sync_enabled = PreviewUsesArrangementClock()
            and MIDITransportModeApplies()
            and (not PreviewFollowsArrangement()
                or (r.GetPlayState() & 1) ~= 0)
        local cycle_qn = GetMIDIPreviewCycleQN(sync_enabled)
        local tempo_rate = GetNativeMIDITempoRate(
            source_duration, project_qn, cycle_qn)
        local effective_rate = tempo_rate * manual_rate
        local origin_qn = GetArrangementSyncOriginQN(project_qn)
        local sync_length_qn = math.max(
            0.000001, cycle_qn / manual_rate)
        if sync_enabled then
            origin_qn = origin_qn
                - (state.preview_sync_phase_offset_fraction or 0)
                    * sync_length_qn
        end
        -- MIDI pitch is note transposition only. The DLL applies it to note
        -- events without resetting or modifying the established tempo clock.
        local midi_pitch = GetTotalPreviewPitchShift()
        local output_length = GetNativeMIDIOutputLength(
            source_duration, project_qn, manual_rate, tempo_rate,
            GetMIDILoopEnabled() and cycle_qn or nil)
        -- The scheduled MIDI source consumes the configured output-cycle
        -- clock. Do not convert this phase through the neutral source duration
        -- or the tempo factor is applied a second time.
        local source_position
        if sync_enabled then
            local phase_qn = math.max(0, project_qn - origin_qn)
                % sync_length_qn
            source_position = phase_qn / sync_length_qn * output_length
        else
            source_position = math.max(0, math.min(1,
                state.preview_seek_fraction or 0)) * output_length
        end
        local authored_qn = math.max(0.000001,
            tonumber(state.file_playback_duration_qn) or cycle_qn)
        local transport_loop, transport_loop_start_s,
            transport_loop_end_s, transport_loop_length_qn =
            GetNativeMIDITransportLoopSnapshot(sync_enabled)
        local sync_spec = string.format(
            "%.17g|%.17g|%.17g|%.17g|%.17g|%.17g|%d|%d|%.17g|%.17g|%d|%.17g|%.17g|%.17g",
            sync_enabled and 1 or 0, origin_qn,
            sync_length_qn, effective_rate, midi_pitch, output_length,
            -1, 1, cycle_qn, authored_qn,
            transport_loop, transport_loop_start_s,
            transport_loop_end_s, transport_loop_length_qn)
        if r.ReaBrowse_ConfigureNativePreview(sync_spec) ~= 1 then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "Native MIDI configuration failed."
            return
        end
        local project = r.EnumProjects(-1, "")
        local loop_midi = GetMIDILoopEnabled()
        local played = r.ReaBrowse_StartNativePreview(
            state.source_file, source_position,
            loop_midi and 1 or 0, 1.0, 0,
            output_track, project)
        if played ~= 1 and played ~= true then
            StopAudioPreview()
            state.is_playing = false
            state.preview_setup_message =
                "REAPER could not start native MIDI preview."
            return
        end
        state.audio_preview = true
        state.audio_preview_native = true
        state.native_preview_kind = "midi"
        state.audio_preview_rate = effective_rate
        state.audio_preview_length = source_duration
        state.audio_preview_output_length = output_length
        state.routed_track = output_track
        state.is_playing = true
        state.preview_setup_message =
            "MIDI: native REAPER preview > selected track"
        StartPreparedLinkedTransport(linked_transport_prepared)
        return
    end
end

function StopPreview(skip_linked_transport_stop)
    state.pending_control_transport_restart_at = nil
    local stop_linked_transport = not skip_linked_transport_stop
        and PreviewControlsTransport()
        and ((state.media_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().link_transport)
            or (state.media_kind == "midi" and MIDITransportModeApplies()))
    state.is_playing = false
    StopAudioPreview()
    state.routed_track = nil
    state.routed_output_channel = nil
    state.routed_output_mono = false
    if stop_linked_transport and (r.GetPlayState() & 1) ~= 0 then
        r.CSurf_OnStop()
    end
end

-- ============================================================
-- INSERT/DROP FILE
-- ============================================================
function SetTrackNameIfBlank(track, track_name)
    if not track or not track_name or track_name == "" then return false end
    local _, existing_name = r.GetSetMediaTrackInfo_String(
        track, "P_NAME", "", false)
    if existing_name and existing_name ~= "" then return false end
    r.GetSetMediaTrackInfo_String(track, "P_NAME", track_name, true)
    return true
end

local function GetInsertionProperties(filepath, source, insert_pos)
    local manual_rate = state.playrate or 1.0
    local rate = manual_rate
    local length = nil
    local detected_pc = nil

    if IsMidiFile(filepath) then
        local parsed = ParseStandardMIDIFile(filepath)
        detected_pc = parsed
            and (parsed.key_pc or DetectFileKeyPitchClass(filepath, nil))
            or DetectFileKeyPitchClass(filepath, nil)
        detected_pc = ResolveEffectiveKeyPitchClass(filepath, detected_pc)

        if parsed then
            local project_num, project_denom =
                r.TimeMap_GetTimeSigAtTime(0, insert_pos)
            local num = parsed.numerator or project_num or 4
            local denom = parsed.denominator or project_denom or 4
            if denom <= 0 then denom = 4 end
            local measure_qn = math.max(0.25, num * 4 / denom)
            local raw_qn = parsed.raw_duration_qn or 0
            local duration_qn = raw_qn > 0
                and math.ceil((raw_qn - 0.000001) / measure_qn) * measure_qn
                or measure_qn
            local start_qn = r.TimeMap2_timeToQN(0, insert_pos)
            local end_qn = start_qn + (duration_qn / rate)
            length = r.TimeMap2_QNToTime(0, end_qn) - insert_pos
        end
    else
        local source_length, length_is_qn = r.GetMediaSourceLength(source)
        local detected_one_shot = ResolveAudioOneShot(
            filepath, source, source_length)
        local current_is_one_shot =
            state.audio_auto_one_shot and detected_one_shot
        local bypass = state.one_shot_bypass

        if not (current_is_one_shot and bypass.key_sync) then
            detected_pc = ResolveEffectiveKeyPitchClass(
                filepath, select(1, DetectAudioKey(filepath, source)))
        end
        if current_is_one_shot and bypass.playrate then
            rate = 1.0
        end
        if state.tempo_match_enabled
            and not (current_is_one_shot and bypass.tempo_match) then
            local tempo_manual_rate = current_is_one_shot and bypass.playrate
                and 1.0 or manual_rate
            local source_bpm = DetectExplicitFilenameBPM(filepath)
            local project_bpm = r.TimeMap_GetDividedBpmAtTime
                and r.TimeMap_GetDividedBpmAtTime(0, insert_pos)
                or r.Master_GetTempo()
            if source_bpm and project_bpm and project_bpm > 0 then
                -- Explicit filename BPM is authoritative. REAPER can report a
                -- successful neutral 1.0 match for files without embedded beat
                -- metadata, which previously prevented this known tempo from
                -- being applied.
                rate = (project_bpm / source_bpm) * tempo_manual_rate
                length = source_length / math.max(0.000001, rate)
            else
                local matched, matched_rate, target_length =
                    r.GetTempoMatchPlayRate(
                        source, 1.0, insert_pos, tempo_manual_rate)
                if matched and matched_rate and matched_rate > 0 then
                    rate = matched_rate
                    if target_length and target_length > 0 then
                        length = target_length
                    end
                end
            end
        end

        if not length then
            if length_is_qn then
                local start_qn = r.TimeMap2_timeToQN(0, insert_pos)
                local end_qn = start_qn + (source_length / rate)
                length = r.TimeMap2_QNToTime(0, end_qn) - insert_pos
            else
                length = source_length / rate
            end
        end
    end

    if not length or length <= 0 then
        local source_length, length_is_qn = r.GetMediaSourceLength(source)
        if length_is_qn then
            local start_qn = r.TimeMap2_timeToQN(0, insert_pos)
            length = r.TimeMap2_QNToTime(
                0, start_qn + (source_length / rate)) - insert_pos
        else
            length = source_length / rate
        end
    end

    local pitch = state.pitch_shift or 0
    if state.key_sync.enabled and detected_pc ~= nil then
        pitch = pitch + ComputeKeySyncShift(
            detected_pc, state.key_sync.target_pc)
    end
    return rate, math.max(0.000001, length), pitch
end

local function BeginInsertedItemPeakBuild(source, item, track)
    if not r.PCM_Source_BuildPeaks then return end
    local remaining = r.PCM_Source_BuildPeaks(source, 0)
    if remaining and remaining ~= 0 then
        state.pending_insert_peak_builds[#state.pending_insert_peak_builds + 1] = {
            source = source,
            item = item,
            track = track,
        }
    elseif r.UpdateItemInProject then
        r.UpdateItemInProject(item)
    end
end

local function ProcessInsertedItemPeakBuild()
    local build = state.pending_insert_peak_builds[1]
    if not build then return end
    if (r.ValidatePtr and not r.ValidatePtr(build.source, "PCM_source*"))
        or (r.ValidatePtr2
            and not r.ValidatePtr2(0, build.item, "MediaItem*")) then
        table.remove(state.pending_insert_peak_builds, 1)
        return
    end
    local remaining = r.PCM_Source_BuildPeaks(build.source, 1)
    if remaining and remaining ~= 0 then return end

    r.PCM_Source_BuildPeaks(build.source, 2)
    if r.UpdateItemInProject then r.UpdateItemInProject(build.item) end
    if r.MarkTrackItemsDirty then
        r.MarkTrackItemsDirty(build.track, build.item)
    end
    r.UpdateArrange()
    table.remove(state.pending_insert_peak_builds, 1)
end

function InsertMIDIAt(filepath, track, pos)
    if not track then track = r.GetSelectedTrack(0, 0) end
    if not track then
        r.ShowMessageBox("Please select a track first.", "No Track Selected", 0)
        return
    end

    StopPreview()
    local item = r.AddMediaItemToTrack(track)
    local take = r.AddTakeToMediaItem(item)
    local source = r.PCM_Source_CreateFromFile(filepath)
    
    if not source then return false end
    r.SetMediaItemTake_Source(take, source)
    
    local insert_pos = pos or r.GetCursorPosition()
    r.SetMediaItemInfo_Value(item, "D_POSITION", insert_pos)
    local insert_rate, insert_length, insert_pitch =
        GetInsertionProperties(filepath, source, insert_pos)
    r.SetMediaItemTakeInfo_Value(take, "D_PLAYRATE", insert_rate)
    r.SetMediaItemTakeInfo_Value(take, "D_PITCH", insert_pitch)
    r.SetMediaItemTakeInfo_Value(take, "B_PPITCH", 1)
    if not IsMidiFile(filepath) then
        -- Inserted media follows the user's REAPER/project pitch default.
        r.SetMediaItemTakeInfo_Value(take, "I_PITCHMODE", -1)
    end
    r.SetMediaItemInfo_Value(item, "D_LENGTH", insert_length)
    r.SetMediaItemInfo_Value(item, "C_BEATATTACHMODE", 1)
    if not IsMidiFile(filepath) then
        BeginInsertedItemPeakBuild(source, item, track)
    end
    
    r.UpdateArrange()
    r.Undo_OnStateChange("Insert media from Browser")
    QueueCanonicalUsage(filepath)
    return true
end

-- Returns window, track, snapped_pos for whatever the mouse is currently over
-- in the arrange view (requires SWS). track may be nil if hovering empty space
-- past the last track; window is nil if SWS isn't installed or mouse isn't
-- over a recognized area.
function GetArrangeHoverTarget()
    if not r.BR_GetMouseCursorContext then return nil end
    local window, segment, details = r.BR_GetMouseCursorContext()
    local track = r.BR_GetMouseCursorContext_Track()
    -- TCP rows have a valid track but no meaningful timeline position.
    -- Preserve that track so dropping on an unselected TCP row targets it;
    -- only empty TCP space should return a nil track and create a new one.
    if window == "tcp" then return window, track, nil end
    if window ~= "arrange" then return window, nil, nil end
    local pos = r.BR_GetMouseCursorContext_Position()
    local snapped_pos = r.SnapToGrid(0, pos)
    return window, track, snapped_pos
end

function InsertFilesOnConsecutiveTracks(paths, first_track, position, allow_selected_fallback)
    if not paths or #paths == 0 then return false end
    StopPreview()
    if not first_track and allow_selected_fallback ~= false then
        first_track = r.GetSelectedTrack(0, 0)
    end
    local base_index = first_track
        and math.max(0, math.floor(r.GetMediaTrackInfo_Value(first_track, "IP_TRACKNUMBER") - 1))
        or r.CountTracks(0)
    position = position or r.GetCursorPosition()
    r.Undo_BeginBlock()
    local destination_tracks = {}
    local track_index = base_index
    while #destination_tracks < #paths do
        local track = r.GetTrack(0, track_index)
        if not track then
            r.InsertTrackAtIndex(track_index, true)
            track = r.GetTrack(0, track_index)
        end
        destination_tracks[#destination_tracks + 1] = track
        track_index = track_index + 1
    end
    local inserted_count = 0
    for i, path in ipairs(paths) do
        if InsertMIDIAt(path, destination_tracks[i], position) then
            local track_name = GetFileName(path):gsub("%.[^./\\]+$", "")
            if track_name == "" then track_name = GetFileName(path) end
            SetTrackNameIfBlank(destination_tracks[i], track_name)
            inserted_count = inserted_count + 1
        end
    end
    r.Undo_EndBlock("Insert selected MIDI files on separate tracks", -1)
    r.TrackList_AdjustWindows(false)
    r.UpdateArrange()
    return inserted_count == #paths
end

-- Cartridge's official REAPER integration writes the selected sample path to
-- a small cross-platform handoff file, then toggles the plug-in's named
-- "Load Trigger" parameter. ReaBrowse already owns the exact browser path, so
-- use that protocol directly instead of routing through Media Explorer.
function GetCartridgeDataDirectory()
    local os_name = (r.GetOS() or ""):lower()
    local base
    if os_name:find("win", 1, true) then
        base = os.getenv("APPDATA")
    else
        local user_home = os.getenv("HOME")
        if user_home and (os_name:find("osx", 1, true)
            or os_name:find("mac", 1, true)) then
            base = user_home .. "/Library/Application Support"
        elseif user_home then
            base = user_home .. "/.config"
        end
    end
    if not base or base == "" then return nil end
    return base:gsub("[/\\]+$", "") .. "/Cartridge"
end

function WriteCartridgePendingLoad(filepath)
    if not filepath or filepath == "" then
        return false, "No sample file was selected."
    end
    local exists = r.file_exists and r.file_exists(filepath) or FileExists(filepath)
    if not exists then return false, "Sample file not found:\n\n" .. filepath end

    local directory = GetCartridgeDataDirectory()
    if not directory then
        return false, "ReaBrowse could not resolve Cartridge's data directory."
    end
    if not r.RecursiveCreateDirectory
        or r.RecursiveCreateDirectory(directory, 0) == false then
        return false, "ReaBrowse could not create Cartridge's data directory:\n\n"
            .. directory
    end

    local pending_path = directory .. "/pending_load.txt"
    local file = io.open(pending_path, "wb")
    if not file then
        return false, "ReaBrowse could not write Cartridge's sample handoff:\n\n"
            .. pending_path
    end
    file:write(filepath)
    file:close()
    return true
end

function IsCartridgeFX(track, fx_index)
    if not track or fx_index == nil or fx_index < 0 then return false end
    local _, name = r.TrackFX_GetFXName(track, fx_index, "")
    return name and name:lower():find("cartridge", 1, true) ~= nil
end

function TriggerCartridgeLoad(track, fx_index, filepath)
    if not IsCartridgeFX(track, fx_index) then
        return false, "The destination FX is not Cartridge."
    end
    local trigger_index
    for parameter = 0, r.TrackFX_GetNumParams(track, fx_index) - 1 do
        local _, name = r.TrackFX_GetParamName(track, fx_index, parameter, "")
        if name == "Load Trigger" then
            trigger_index = parameter
            break
        end
    end
    if trigger_index == nil then
        return false, "This Cartridge version does not expose its Load Trigger parameter."
    end

    local written, write_error = WriteCartridgePendingLoad(filepath)
    if not written then return false, write_error end
    local value = r.TrackFX_GetParam(track, fx_index, trigger_index)
    r.TrackFX_SetParam(track, fx_index, trigger_index, value < 0.5 and 1 or 0)
    return true
end

function FindActiveCartridge()
    -- Match Cartridge's official action semantics: an open Cartridge UI is the
    -- active destination. Prefer the selected track, then search the project.
    local selected_track = r.GetSelectedTrack(0, 0)
    if selected_track then
        for fx = 0, r.TrackFX_GetCount(selected_track) - 1 do
            if r.TrackFX_GetOpen(selected_track, fx)
                and IsCartridgeFX(selected_track, fx) then
                return selected_track, fx
            end
        end
    end
    for track_index = 0, r.CountTracks(0) - 1 do
        local track = r.GetTrack(0, track_index)
        if track ~= selected_track then
            for fx = 0, r.TrackFX_GetCount(track) - 1 do
                if r.TrackFX_GetOpen(track, fx) and IsCartridgeFX(track, fx) then
                    return track, fx
                end
            end
        end
    end
    local master = r.GetMasterTrack(0)
    for fx = 0, r.TrackFX_GetCount(master) - 1 do
        if r.TrackFX_GetOpen(master, fx) and IsCartridgeFX(master, fx) then
            return master, fx
        end
    end
    return nil, nil
end

function LoadFileIntoActiveCartridge(filepath)
    local track, fx_index = FindActiveCartridge()
    if not track then
        r.ShowMessageBox(
            "No active Cartridge instance was found.\n\nOpen a Cartridge interface and try again.",
            "ReaBrowse - Cartridge", 0)
        return false
    end
    StopPreview()
    r.Undo_BeginBlock()
    local loaded, load_error = TriggerCartridgeLoad(track, fx_index, filepath)
    r.Undo_EndBlock(loaded and "Load sample into Cartridge"
        or "Cartridge sample load failed", -1)
    if not loaded then
        r.ShowMessageBox(load_error or "Cartridge could not load this sample.",
            "ReaBrowse - Cartridge", 0)
        return false
    end
    QueueCanonicalUsage(filepath)
    return true
end

function OpenFileInNewCartridge(filepath)
    StopPreview()
    local track_index = r.CountTracks(0)
    r.Undo_BeginBlock()
    r.InsertTrackAtIndex(track_index, true)
    local track = r.GetTrack(0, track_index)
    if not track then
        r.Undo_EndBlock("Create Cartridge track failed", -1)
        r.ShowMessageBox("REAPER could not create a track for Cartridge.",
            "ReaBrowse - Cartridge", 0)
        return false
    end

    local fx_index = r.TrackFX_AddByName(track, "Cartridge", false, -1)
    if fx_index < 0 then
        fx_index = r.TrackFX_AddByName(track, "VST3:Cartridge", false, -1)
    end
    if fx_index < 0 then
        r.DeleteTrack(track)
        r.Undo_EndBlock("Create Cartridge track failed", -1)
        r.ShowMessageBox(
            "Cartridge was not found. Install Cartridge, then rescan REAPER's plug-ins.",
            "ReaBrowse - Cartridge", 0)
        return false
    end

    local track_name = GetFileName(filepath):gsub("%.[^./\\]+$", "")
    r.GetSetMediaTrackInfo_String(track, "P_NAME", track_name, true)
    r.SetMediaTrackInfo_Value(track, "I_RECINPUT", 6112)
    r.SetMediaTrackInfo_Value(track, "I_RECARM", 1)
    r.SetMediaTrackInfo_Value(track, "I_RECMON", 1)

    local loaded, load_error = TriggerCartridgeLoad(track, fx_index, filepath)
    if not loaded then
        r.DeleteTrack(track)
        r.Undo_EndBlock("Create Cartridge track failed", -1)
        r.ShowMessageBox(load_error or "Cartridge could not load this sample.",
            "ReaBrowse - Cartridge", 0)
        return false
    end

    r.SetOnlyTrackSelected(track)
    r.TrackFX_Show(track, fx_index, 3)
    r.TrackList_AdjustWindows(false)
    r.UpdateArrange()
    r.Undo_EndBlock("Create Cartridge track: " .. track_name, -1)
    QueueCanonicalUsage(filepath)
    return true
end

function SetRS5KSample(track, fx_index, filepath)
    if not r.TrackFX_SetNamedConfigParm then
        return false, "This REAPER version cannot set RS5K samples directly."
    end
    local ok, loaded = pcall(
        r.TrackFX_SetNamedConfigParm, track, fx_index, "FILE", filepath)
    if not ok or not loaded then
        return false, "ReaSamplOmatic5000 could not load this sample."
    end
    -- RS5K accepts FILE as a write-only configuration field. DONE tells it to
    -- finish reading the updated file state before the UI is shown.
    pcall(r.TrackFX_SetNamedConfigParm, track, fx_index, "DONE", "")
    return true
end

function InsertFileInNewRS5K(filepath)
    if not filepath or not IsAudioFile(filepath) or not FileExists(filepath) then
        r.ShowMessageBox("The selected file is not a readable audio file.",
            "ReaBrowse - RS5K", 0)
        return false
    end

    StopPreview()
    local track_index = r.CountTracks(0)
    r.Undo_BeginBlock()
    r.InsertTrackAtIndex(track_index, true)
    local track = r.GetTrack(0, track_index)
    if not track then
        r.Undo_EndBlock("Create RS5K track failed", -1)
        r.ShowMessageBox("REAPER could not create a track for RS5K.",
            "ReaBrowse - RS5K", 0)
        return false
    end

    local fx_index = -1
    for _, fx_name in ipairs({
        "ReaSamplOmatic5000",
        "VST3: ReaSamplOmatic5000",
        "VST: ReaSamplOmatic5000",
    }) do
        fx_index = r.TrackFX_AddByName(track, fx_name, false, -1)
        if fx_index >= 0 then break end
    end
    if fx_index < 0 then
        r.DeleteTrack(track)
        r.Undo_EndBlock("Create RS5K track failed", -1)
        r.ShowMessageBox(
            "ReaSamplOmatic5000 was not found. Enable the Cockos plug-in and rescan REAPER's plug-ins.",
            "ReaBrowse - RS5K", 0)
        return false
    end

    local loaded, load_error = SetRS5KSample(track, fx_index, filepath)
    if not loaded then
        r.DeleteTrack(track)
        r.Undo_EndBlock("Create RS5K track failed", -1)
        r.ShowMessageBox(load_error or "RS5K could not load this sample.",
            "ReaBrowse - RS5K", 0)
        return false
    end

    local track_name = GetFileName(filepath):gsub("%.[^./\\]+$", "")
    r.GetSetMediaTrackInfo_String(track, "P_NAME", track_name, true)
    r.SetOnlyTrackSelected(track)
    r.TrackFX_Show(track, fx_index, 3)
    r.TrackList_AdjustWindows(false)
    r.UpdateArrange()
    r.Undo_EndBlock("Create RS5K track: " .. track_name, -1)
    QueueCanonicalUsage(filepath)
    return true
end

function InsertFileFromBrowserDoubleClick(filepath)
    local selected_track = r.GetSelectedTrack(0, 0)
    if selected_track then
        return InsertMIDIAt(
            filepath, selected_track, r.GetCursorPosition())
    end
    -- With no destination selected, create exactly one new track and use the
    -- already validated shared insertion path for both audio and MIDI.
    return InsertFilesOnConsecutiveTracks(
        {filepath}, nil, r.GetCursorPosition(), false)
end

function GetPreviewPosition()
    if state.media_kind == "audio" then
        if not state.audio_preview then return 0 end
        if state.native_preview_kind == "audio"
            and type(r.ReaBrowse_GetNativePreviewPosition) == "function" then
            return math.max(0, r.ReaBrowse_GetNativePreviewPosition() or 0)
        end
        return 0
    end
    if not state.loaded_midi then return 0 end
    if state.native_preview_kind == "midi"
        and type(r.ReaBrowse_GetNativePreviewPosition) == "function" then
        return math.max(0, r.ReaBrowse_GetNativePreviewPosition() or 0)
    end
    return 0
end

function SeekPreviewToFraction(fraction)
    fraction = math.max(0, math.min(1, fraction or 0))
    state.preview_seek_fraction = fraction
    local arrangement_seek = PreviewFollowsArrangement()
        and (r.GetPlayState() & 1) ~= 0 and state.is_playing
        and ((state.media_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().sync)
            or (state.media_kind == "midi" and MIDITransportModeApplies()))
    if arrangement_seek then
        state.preview_sync_phase_offset_fraction = 0
        local project_qn = GetArrangementQNPosition()
        local origin_qn = GetArrangementSyncOriginQN(project_qn)
        local effective_length_qn
        if state.media_kind == "audio" then
            local duration = math.max(
                state.audio_preview_length or state.audio_length or 0, 0)
            if duration > 0 then
                local _, audio_length_qn = GetAudioArrangementSourcePosition(
                    duration, state.audio_preview_rate or 1.0,
                    state.audio_preview_output_length, true)
                effective_length_qn = audio_length_qn
            end
        else
            effective_length_qn = math.max(
                GetMIDIPreviewCycleQN(true), 0.000001)
                / GetManualPreviewRate()
        end
        if effective_length_qn and effective_length_qn > 0 then
            -- Follow Arrangement has one authority: REAPER's transport. Seek
            -- to the requested phase in the current browser-length cycle, then
            -- let the active preview re-latch to that transport position.
            local relative_qn = math.max(0, project_qn - origin_qn)
            local cycle_start_qn = origin_qn
                + math.floor(relative_qn / effective_length_qn)
                    * effective_length_qn
            local target_project_qn = cycle_start_qn
                + fraction * effective_length_qn
            r.SetEditCurPos(r.TimeMap2_QNToTime(
                0, target_project_qn), true, true)
        end
    end
    if not arrangement_seek then
        state.preview_sync_phase_offset_fraction = 0
    end
    if PreviewControlsTransport() then
        local target_qn
        if state.media_kind == "midi" then
            local effective_length_qn = math.max(
                GetMIDIPreviewCycleQN(true), 0.000001)
                / GetManualPreviewRate()
            target_qn = fraction * effective_length_qn
        else
            local duration = math.max(
                state.audio_preview_length or state.audio_length or 0, 0)
            local _, effective_length_qn =
                GetAudioArrangementSourcePosition(
                    duration, state.audio_preview_rate or 1.0,
                    state.audio_preview_output_length)
            target_qn = fraction * effective_length_qn
        end
        r.SetEditCurPos(r.TimeMap2_QNToTime(0, target_qn), true, true)
    end
    if state.media_kind == "audio" then
        local duration = math.max(
            state.audio_preview_length or state.audio_length or 0, 0)
        local position = duration * fraction
        if state.audio_preview then
            if state.native_preview_kind == "audio"
                and type(r.ReaBrowse_SetNativePreviewPosition) == "function" then
                r.ReaBrowse_SetNativePreviewPosition(position)
            end
            local policy = GetCurrentAudioPlaybackPolicy()
            if not policy.loop and state.is_playing then
                state.audio_preview_expected_end = r.time_precise()
                    + math.max(0, duration - position)
                        / math.max(0.001, state.audio_preview_rate or 1)
                    + 0.12
            end
        end
        return
    end
    if state.loaded_midi then
        if state.native_preview_kind == "midi"
            and type(r.ReaBrowse_SetNativePreviewPosition) == "function" then
            local duration = math.max(
                state.audio_preview_output_length
                    or state.audio_preview_length or 0, 0)
            r.ReaBrowse_SetNativePreviewPosition(duration * fraction)
            return true
        end
    end
    return true
end

-- ============================================================
-- ACCORDION LOGIC & NAVIGATION
-- ============================================================
local function ResolveFavoriteCanonicalFolderId(node)
    if not node or node._canonical_folder_id
        or not state.database_startup_test.enabled
        or not FileExists(GetCanonicalDatabasePath()) then
        return node and node._canonical_folder_id, nil
    end
    local key = NormalizeFavoritePath(node.path)
    local cached_id = state.favorite_folder_id_cache
        and state.favorite_folder_id_cache[key]
    if cached_id then
        node._canonical_folder_id = cached_id
        node._canonical_resolution_error = nil
        return cached_id, nil
    end
    if node._canonical_resolution_pending then
        return nil, "Locating favorite folder..."
    end
    node._canonical_resolution_pending = true
    node._canonical_resolution_error = nil
    local queued = RequestCanonicalBrowserPage(
        "resolve_favorite_folder", nil, 0, false, false, node)
    if not queued then
        node._canonical_resolution_pending = false
        node._canonical_resolution_error =
            "Favorite folder lookup could not be queued."
        return nil, node._canonical_resolution_error
    end
    return nil, "Locating favorite folder..."
end

function OpenFolderAccordion(node)
    if not node then return false end
    local open_map = state.favorites_mode
        and state.favorite_open_folders or state.open_folders
    local open_key = GetFolderUIKey(node)
    if state.favorites_mode then
        local needs_canonical_folder = not node.is_collection
            and node.path ~= "__favorite_files__"
            and state.database_startup_test.enabled
        if needs_canonical_folder then
            local folder_id, resolve_error =
                ResolveFavoriteCanonicalFolderId(node)
            if not folder_id then
                open_map[open_key] = false
                state.canonical_browser.accordion_error = resolve_error
                    or "Favorite folder could not be resolved."
                state.needs_visible_update = true
                return false
            end
        end
    end
    if state.database_startup_test.enabled then
        local browser = state.canonical_browser
        -- A full-row click selects the folder before it opens the accordion.
        -- Preserve the tag request that selection just queued for this node.
        -- Only discard a request belonging to the previously selected folder.
        if browser.pending_tag_folder_id ~= node._canonical_folder_id then
            browser.pending_tag_folder_id = nil
            browser.pending_tag_time = nil
        end
    end
    if not state.favorites_mode then
        local siblings = node.parent and node.parent.children or GetActiveTrees()
        for _, sibling in ipairs(siblings) do
            if sibling.path ~= node.path then
                open_map[sibling.path] = false
            end
        end
    end
    open_map[open_key] = true
    if state.database_startup_test.enabled
        and node._canonical_folder_id
        and node._canonical_loaded then
        state.canonical_browser.pending_tag_folder_id =
            node._canonical_folder_id
        state.canonical_browser.pending_tag_time =
            r.time_precise() + 0.4
    end
    if state.database_startup_test.enabled
        and (node.is_collection or node._canonical_folder_id)
        and not node._canonical_loaded then
        LoadCanonicalAccordionFolder(node)
    end
    state.needs_visible_update = true
    return true
end

function GatherSearchResults()
    local results = {}
    local scope = state.selected_folder_scope
    local scope_key = scope and NormalizeFavoritePath(scope) or nil
    local function IsInsideSelectedFolder(node)
        if not scope_key or scope_key == "" then return true end
        local candidate = node._normalized_browser_path
        if not candidate then
            candidate = NormalizeFavoritePath(node.path)
            node._normalized_browser_path = candidate
        end
        return candidate == scope_key
            or candidate:sub(1, #scope_key + 1) == scope_key .. "/"
    end

    local function GatherFiles(node)
        if not node then return end
        if not node.is_folder then
            if MediaMatchesSearch(node) and MediaMatchesFilters(node) then
                if IsInsideSelectedFolder(node) then
                    table.insert(results, node)
                end
            end
        else
            for _, c in ipairs(node.children) do GatherFiles(c) end
            for _, f in ipairs(node.files) do GatherFiles(f) end
        end
    end
    local indexed_candidates = GetIndexedFilterCandidates()
    if indexed_candidates then
        for _, node in ipairs(indexed_candidates) do
            if MediaMatchesSearch(node)
                and MediaMatchesFilters(node)
                and IsInsideSelectedFolder(node) then
                results[#results + 1] = node
            end
        end
    else
        for _, tree in ipairs(GetActiveTrees()) do GatherFiles(tree) end
    end
    return results
end

function GetCachedSearchResults()
    if state.search_text ~= state.last_search_text or state.selected_folder_scope ~= state.last_folder_scope or state.force_search_update then
        state.cached_search_results = GatherSearchResults()
        state.search_index_by_path = {}
        for i, file in ipairs(state.cached_search_results) do
            state.search_index_by_path[file.path] = i
        end
        state.last_search_text = state.search_text
        state.last_folder_scope = state.selected_folder_scope
        state.force_search_update = false
    end
    return state.cached_search_results
end

function BuildVisibleItems()
    local items = {}
    local function ReusableVisibleItem(node, kind, depth, row_key)
        local item = node._browser_visible_item
        if not item then
            item = {}
            node._browser_visible_item = item
        end
        item.type = kind
        item.path = node.path
        item.node = node
        item.depth = depth
        item.row_key = row_key
        item.instance_key = kind == "folder" and GetFolderUIKey(node) or nil
        node._visible_row_key = row_key
        return item
    end
    if state.search_text ~= "" or MediaFiltersActive() then
        for index, f in ipairs(GetCachedSearchResults()) do
            local row_key = GetMediaRowSelectionKey(
                f, "result:" .. tostring(index))
            items[#items + 1] = ReusableVisibleItem(f, "file", 0, row_key)
        end
    else
        local open_map = state.favorites_mode
            and state.favorite_open_folders or state.open_folders
        local function Walk(node, depth)
            if not node then return end
            items[#items + 1] =
                ReusableVisibleItem(node, "folder", depth)
            if open_map[GetFolderUIKey(node)] then
                for _, child in ipairs(node.children) do Walk(child, depth + 1) end
                for file_index, file in ipairs(node.files) do
                    local row_key = GetMediaRowSelectionKey(
                        file, "accordion:" .. tostring(node.path)
                            .. ":" .. tostring(file_index))
                    items[#items + 1] =
                        ReusableVisibleItem(
                            file, "file", depth + 1, row_key)
                end
            end
        end
        for _, tree in ipairs(GetActiveTrees()) do
            if state.favorites_mode and tree.path == "__favorite_files__" then
                for file_index, file in ipairs(tree.files) do
                    local row_key = GetMediaRowSelectionKey(
                        file, "favorite_root:" .. tostring(file_index))
                    items[#items + 1] = ReusableVisibleItem(
                        file, "file", 0, row_key)
                end
            else
                Walk(tree, 0)
            end
        end
    end
    local index_by_path = {}
    local index_by_row_key = {}
    local index_by_instance_key = {}
    for i, item in ipairs(items) do
        -- A favorite file can be rendered more than once.  Keep the first
        -- path fallback stable; occurrence-sensitive selection uses row_key.
        if not index_by_path[item.path] then index_by_path[item.path] = i end
        if item.row_key then index_by_row_key[item.row_key] = i end
        if item.instance_key then index_by_instance_key[item.instance_key] = i end
    end
    state.visible_items = items
    state.visible_index_by_path = index_by_path
    state.visible_index_by_row_key = index_by_row_key
    state.visible_index_by_instance_key = index_by_instance_key
    state.needs_visible_update = false
end

function FindCursorIndex()
    if not state.cursor_path then return nil end
    if state.favorites_mode and state.cursor_type == "folder"
        and state.cursor_favorite_instance_key then
        return state.visible_index_by_instance_key
            and state.visible_index_by_instance_key[
                state.cursor_favorite_instance_key]
    end
    return state.visible_index_by_path[state.cursor_path]
end

function GetSelectionModifiers()
    local frame = state.ui_frame_index or 0
    if state.selection_modifiers_frame == frame then
        return state.selection_modifier_ctrl,
            state.selection_modifier_shift,
            state.selection_modifier_alt
    end
    local ok, mods = pcall(imgui.GetKeyMods, ctx)
    mods = ok and mods or 0
    local ctrl = (mods & MOD_CTRL) ~= 0
    local shift = (mods & MOD_SHIFT) ~= 0
    local alt = (mods & MOD_ALT) ~= 0
    local function KeyHeld(name)
        if not imgui.IsKeyDown then return false end
        local key = imgui[name]
        if type(key) == "function" then
            local key_ok, value = pcall(key)
            key = key_ok and value or nil
        end
        if key == nil then return false end
        local down_ok, down = pcall(imgui.IsKeyDown, ctx, key)
        return down_ok and down == true
    end
    ctrl = ctrl or KeyHeld("Key_LeftCtrl") or KeyHeld("Key_RightCtrl")
    shift = shift or KeyHeld("Key_LeftShift") or KeyHeld("Key_RightShift")
    alt = alt or KeyHeld("Key_LeftAlt") or KeyHeld("Key_RightAlt")
    state.selection_modifiers_frame = frame
    state.selection_modifier_ctrl = ctrl
    state.selection_modifier_shift = shift
    state.selection_modifier_alt = alt
    return ctrl, shift, alt
end

function RefreshNativeCompanionAvailability()
    local version = 0
    if type(r.ReaBrowse_GetNativeApiVersion) == "function" then
        local ok, value = pcall(r.ReaBrowse_GetNativeApiVersion)
        if ok then version = tonumber(value) or 0 end
    end
    state.native_companion_version = version
    local command_id = 0
    if r.NamedCommandLookup then
        -- Older companion builds registered this identifier without the
        -- conventional leading underscore. Accept both spellings so the
        -- fallback remains usable without replacing/restarting the DLL.
        command_id = r.NamedCommandLookup("_ReaBrowseNativeFileDrag") or 0
        if command_id == 0 then
            command_id = r.NamedCommandLookup("ReaBrowseNativeFileDrag") or 0
        end
    end
    state.native_drag_command_id = command_id
    -- Some REAPER builds load the extension and register its named command,
    -- but do not publish APIdef functions into the Lua reaper table.  The
    -- command path exists specifically for that case, so it must not depend
    -- on the version API being visible as well.
    state.native_drag_available =
        (version >= 2
            and type(r.ReaBrowse_StartNativeFileDrag) == "function")
        or command_id ~= 0
    return state.native_drag_available
end

local function StartNativeExternalFileDrag(paths)
    if not paths or #paths == 0 then
        return false
    end
    local payload = table.concat(paths, "\n")
    if RefreshNativeCompanionAvailability()
        and type(r.ReaBrowse_StartNativeFileDrag) == "function" then
        local ok, started = pcall(
            r.ReaBrowse_StartNativeFileDrag, payload, 0)
        if ok and (started == true or started == 1) then return true end
    end

    local command_id = state.native_drag_available
        and (state.native_drag_command_id or 0) or 0
    if command_id == 0 then return false end

    r.SetExtState("ReaBrowseNativeDrag", "paths", payload, false)
    r.Main_OnCommand(command_id, 0)
    r.DeleteExtState("ReaBrowseNativeDrag", "paths", false)
    return true
end

function SelectFileNode(
    node, ensure_visible, ctrl_override, shift_override, row_key)
    local ctrl, shift
    if ctrl_override ~= nil or shift_override ~= nil then
        ctrl = ctrl_override == true
        shift = shift_override == true
    else
        ctrl, shift = GetSelectionModifiers()
    end
    local first = state.selection_anchor_row_key
        and state.visible_index_by_row_key
        and state.visible_index_by_row_key[state.selection_anchor_row_key]
        or (state.selection_anchor
            and state.visible_index_by_path[state.selection_anchor])
    local last = row_key and state.visible_index_by_row_key
        and state.visible_index_by_row_key[row_key]
        or state.visible_index_by_path[node.path]
    -- Accordion Favorites rows are drawn directly from the tree and may not
    -- have rebuilt the shared visible-index cache yet. Build the small index
    -- lazily so Shift-range selection has identical semantics in both views.
    if shift and (not first or not last) then
        for i, item in ipairs(state.visible_items or {}) do
            if state.selection_anchor_row_key
                and item.row_key == state.selection_anchor_row_key then
                first = i
            elseif not state.selection_anchor_row_key
                and item.path == state.selection_anchor then
                first = i
            end
            if row_key and item.row_key == row_key then
                last = i
            elseif not row_key and item.path == node.path then
                last = i
            end
        end
    end
    if shift and first and last then
        if first and last then
            if not ctrl then
                state.multi_selected = {}
                state.selected_file_row_keys = {}
            end
            if first > last then first, last = last, first end
            for i = first, last do
                local item = state.visible_items[i]
                if item and item.type == "file" then
                    state.multi_selected[item.path] = true
                    if item.row_key
                        and not state.selected_file_row_keys[item.path] then
                        state.selected_file_row_keys[item.path] = item.row_key
                    end
                end
            end
            if row_key then
                state.selected_file_row_keys[node.path] = row_key
            end
            state.cursor_path = node.path
            state.cursor_type = "file"
            state.scroll_to_cursor = ensure_visible == true
            return
        end
    elseif ctrl then
        state.multi_selected[node.path] = not state.multi_selected[node.path] or nil
        if state.multi_selected[node.path] and row_key then
            state.selected_file_row_keys[node.path] = row_key
        elseif not state.multi_selected[node.path] then
            state.selected_file_row_keys[node.path] = nil
        end
        state.selection_anchor = node.path
        state.selection_anchor_row_key = row_key
        state.cursor_path = node.path
        state.cursor_type = "file"
        return
    end
    state.multi_selected = {[node.path] = true}
    state.selection_anchor = node.path
    state.selection_anchor_row_key = row_key
    state.selected_file_row_keys = row_key
        and {[node.path] = row_key} or {}
    SetCursorToFileNode(node, ensure_visible, row_key)
end

function GetSelectedFilePaths(fallback_path)
    local paths = {}
    local added = {}
    for _, item in ipairs(state.visible_items) do
        if item.type == "file" and state.multi_selected[item.path]
            and not added[item.path] then
            paths[#paths + 1] = item.path
            added[item.path] = true
        end
    end
    for path, selected in pairs(state.multi_selected) do
        if selected and not added[path] then paths[#paths + 1] = path end
    end
    if #paths == 0 and fallback_path then paths[1] = fallback_path end
    return paths
end

READRUM_BRIDGE_SECTION = "ReaDrumBridge"
READRUM_BRIDGE_TIMEOUT_SECONDS = 10.0

function NewReaDrumBridgeRequestID()
    -- Combine wall time, REAPER's high-resolution clock, and a random suffix.
    -- The acknowledgement is accepted only when this entire value matches.
    return string.format("reabrowse-%d-%d-%06d", os.time(),
        math.floor((r.time_precise() % 1) * 1000000),
        math.random(0, 999999))
end

function SendSelectedFilesToReaDrum(fallback_path)
    if state.readrum_bridge_pending then
        r.ShowMessageBox(
            "ReaDrum is still processing the previous sample batch.",
            "ReaBrowse - ReaDrum", 0)
        return false
    end

    local paths = GetSelectedFilePaths(fallback_path)
    if #paths == 0 then return false end

    local project = select(1, r.EnumProjects(-1, ""))
    if not project then
        r.ShowMessageBox("No current REAPER project is available.",
            "ReaBrowse - ReaDrum", 0)
        return false
    end

    local request_id = NewReaDrumBridgeRequestID()
    -- command_id is the request commit marker and must always be written last.
    r.SetProjExtState(project, READRUM_BRIDGE_SECTION,
        "command", "load_batch")
    r.SetProjExtState(project, READRUM_BRIDGE_SECTION,
        "paths", table.concat(paths, "\n"))
    r.SetProjExtState(project, READRUM_BRIDGE_SECTION, "pad", "")
    r.SetProjExtState(project, READRUM_BRIDGE_SECTION,
        "command_id", request_id)

    state.readrum_bridge_pending = {
        project = project,
        id = request_id,
        submitted_at = r.time_precise(),
        count = #paths,
        next_poll_at = 0,
    }
    return true
end

function PollReaDrumBridgeAcknowledgement()
    local pending = state.readrum_bridge_pending
    if not pending then return end

    local now = r.time_precise()
    if now < (pending.next_poll_at or 0) then return end
    pending.next_poll_at = now + 0.05

    local _, ack_id = r.GetProjExtState(
        pending.project, READRUM_BRIDGE_SECTION, "ack_id")
    if ack_id == pending.id then
        -- ack_id is ReaDrum's acknowledgement commit marker, so read status
        -- only after the matching ID has become visible.
        local _, ack_status = r.GetProjExtState(
            pending.project, READRUM_BRIDGE_SECTION, "ack_status")
        state.readrum_bridge_pending = nil
        if ack_status ~= "ok" then
            r.ShowMessageBox(
                "ReaDrum rejected the selected sample batch.",
                "ReaBrowse - ReaDrum", 0)
        end
        return
    end

    if now - pending.submitted_at >= READRUM_BRIDGE_TIMEOUT_SECONDS then
        state.readrum_bridge_pending = nil
        r.ShowMessageBox(
            "ReaDrum did not acknowledge the sample batch. "
                .. "ReaDrumXT must be open to load samples.",
            "ReaBrowse - ReaDrum", 0)
    end
end

function ClearMediaFileSelection()
    state.cursor_path = nil
    state.cursor_type = nil
    state.cursor_favorite_instance_key = nil
    state.selected_path = nil
    state.multi_selected = {}
    state.selected_file_row_keys = {}
    state.selection_anchor = nil
    state.selection_anchor_row_key = nil
    state.pending_single_node = nil
    state.pending_single_row_key = nil
    state.pending_ctrl_file = nil
end

function ClearMediaBrowserSelection()
    local canonical_favorite_scope_changed = false
    if state.favorites_mode and state.database_startup_test.enabled then
        local browser = state.canonical_browser
        canonical_favorite_scope_changed = browser.current_folder_id ~= nil
            or browser.collection_scope_key ~= nil
    end
    if state.favorites_mode and state.database_startup_test.enabled
        and ClearCanonicalFavoriteFolderFacetScope then
        ClearCanonicalFavoriteFolderFacetScope(true)
    end
    state.selected_folder_scope = nil
    ClearMediaFileSelection()
    if state.search_text ~= "" or MediaFiltersActive() then
        state.force_search_update = true
        state.needs_visible_update = true
    end
    state.media_tag_bar.cache_key = nil
    state.media_tag_bar.scope_catalog_key = nil
    state.media_tag_facets.building = false
    if state.favorites_mode and state.database_startup_test.enabled then
        local browser = state.canonical_browser
        browser.current_folder_id = nil
        browser.current_name = "Favorites"
        browser.current_path = nil
        browser.collection_scope_key = nil
        browser.available_tags = {}
        -- Favorites home deliberately has no aggregate tag catalog.
        if canonical_favorite_scope_changed
            and (NormalizeTag(browser.search_text or "") ~= ""
                or CanonicalBrowserHasStructuredFilters()) then
            ResetCanonicalForegroundView("Favorites scope cleared", true)
            RequestCanonicalBrowserPage(
                CanonicalBrowserCurrentMode(), nil, 0, false, false)
        end
    end
end

local function StartFolderTagFacetBuild(node)
    local facet = state.media_tag_facets
    facet.building = node ~= nil
    facet.scope = node and node.path or nil
    facet.stack = node and {{kind = "node", value = node}} or {}
    facet.counts = {}
    facet.files = {}
    facet.by_tag = {}
    facet.by_class = {
        ["loop"] = {}, ["one-shot"] = {},
        ["midi"] = {}, ["other"] = {},
    }
    facet.processed = 0
end

local function ProcessFolderTagFacetBuild()
    local facet = state.media_tag_facets
    if state.pending_tag_facet_node ~= nil then
        StartFolderTagFacetBuild(state.pending_tag_facet_node)
        state.pending_tag_facet_node = nil
        state.pending_tag_facet_time = nil
        return
    end
    if not facet.building then return end
    -- Facets are deliberately background work. Keep each slice short enough
    -- that navigation, preview and input handling always get priority.
    local deadline = r.time_precise() + 0.0015
    local budget = 128
    while budget > 0 and r.time_precise() < deadline do
        local work = table.remove(facet.stack)
        if not work then
            local tags = {}
            for name, count in pairs(facet.counts) do
                if not TAG_BAR_EXCLUDED[name] then
                    tags[#tags + 1] = {name = name, count = count}
                end
            end
            SortMediaTagCatalog(tags, state.media_filters.selected_tags)
            state.media_tag_bar.tags = tags
            state.media_tag_bar.scope_catalog_key = facet.scope
            state.media_tag_bar.cache_key = nil
            facet.building = false
            return
        end
        if work.kind == "node" then
            local node = work.value
            for i = #node.children, 1, -1 do
                facet.stack[#facet.stack + 1] = {
                    kind = "node", value = node.children[i]
                }
            end
            for i = #node.files, 1, -1 do
                facet.stack[#facet.stack + 1] = {
                    kind = "file", value = node.files[i]
                }
            end
        else
            local node = work.value
            facet.files[#facet.files + 1] = node
            local class_entries = facet.by_class[GetMediaClass(node)]
            if class_entries then class_entries[#class_entries + 1] = node end
            local seen = {}
            for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
                local name = NormalizeTag(tag)
                if name ~= "" and not seen[name] then
                    facet.counts[name] = (facet.counts[name] or 0) + 1
                    local entries = facet.by_tag[name]
                    if not entries then
                        entries = {}
                        facet.by_tag[name] = entries
                    end
                    entries[#entries + 1] = node
                    seen[name] = true
                end
            end
            for _, generated in ipairs(EnsureGeneratedTags(node)) do
                local name = NormalizeTag(generated.name)
                if name ~= "" and not seen[name] then
                    facet.counts[name] = (facet.counts[name] or 0) + 1
                    local entries = facet.by_tag[name]
                    if not entries then
                        entries = {}
                        facet.by_tag[name] = entries
                    end
                    entries[#entries + 1] = node
                    seen[name] = true
                end
            end
            facet.processed = facet.processed + 1
        end
        budget = budget - 1
    end
end

function SetCursorToFolderNode(node, ensure_visible)
    if not node then return end
    if state.favorites_mode and node.is_collection
        and SetFavoriteCollectionTagScope then
        SetFavoriteCollectionTagScope(node)
        state.scroll_to_cursor = ensure_visible == true
        return
    end
    state.multi_selected = {}
    state.selection_anchor = nil
    state.selection_anchor_row_key = nil
    state.selected_file_row_keys = {}
    state.cursor_path = node.path
    state.cursor_type = "folder"
    state.cursor_favorite_instance_key = state.favorites_mode
        and GetFavoriteNodeInstanceKey(node) or nil
    if state.database_startup_test.enabled and node._canonical_folder_id then
        local browser = state.canonical_browser
        if state.favorites_mode
            and browser.current_folder_id ~= node._canonical_folder_id then
            ClearCanonicalFavoriteFolderFacetScope(true)
        end
        browser.collection_scope_key = nil
        browser.current_folder_id = node._canonical_folder_id
        browser.current_name = node.name
        browser.current_path = node.path
        -- Folder selection and accordion expansion are separate actions.
        -- Keep the precomputed tag scope in sync with the selected folder even
        -- when a click merely closes an already-open row.
        if state.media_tag_bar.open then
            browser.available_tags = {}
            browser.pending_tag_folder_id = node._canonical_folder_id
            browser.pending_tag_time = r.time_precise() + 0.35
        end
        if NormalizeTag(browser.search_text or "") ~= ""
            or CanonicalBrowserHasStructuredFilters() then
            ResetCanonicalForegroundView("Favorite folder scope changed", true)
            RequestCanonicalBrowserPage(
                CanonicalBrowserCurrentMode(), browser.current_folder_id,
                0, false, false)
        end
    end
    if state.selected_folder_scope ~= node.path then
        state.selected_folder_scope = node.path
        if not state.database_startup_test.enabled
            and (state.media_tag_bar.open or MediaFiltersActive()) then
            state.pending_tag_facet_node = node
            state.pending_tag_facet_time = r.time_precise() + 0.25
            state.media_tag_facets.building = false
        end
        if state.search_text ~= "" or MediaFiltersActive() then
            state.force_search_update = true
            state.needs_visible_update = true
        end
    end
    state.scroll_to_cursor = ensure_visible == true
end

function SetFavoriteCollectionTagScope(node)
    if not node or not node.is_collection then return false end
    state.multi_selected = {}
    state.selection_anchor = nil
    state.selection_anchor_row_key = nil
    state.selected_file_row_keys = {}
    state.cursor_path = node.path
    state.cursor_type = "folder"
    state.cursor_favorite_instance_key = state.favorites_mode
        and GetFavoriteNodeInstanceKey(node) or nil
    state.selected_folder_scope = nil
    if state.database_startup_test.enabled then
        local browser = state.canonical_browser
        ResetCanonicalForegroundView(
            "Favorites collection selected in accordion", true)
        state.favorite_smart_mode = nil
        browser.smart_mode = nil
        browser.collection_key = nil
        browser.collection_scope_key = tostring(node.collection_id)
        browser.history = {}
        browser.current_folder_id = nil
        browser.current_name = node.name
        browser.current_path = nil
        browser.offset = 0
        browser.selected_path = nil
    end
    state.needs_visible_update = true
    return true
end

function SetCursorToFileNode(node, ensure_visible, row_key)
    if not node then return end
    if state.favorites_mode and state.database_startup_test.enabled then
        local browser = state.canonical_browser
        local physical_parent = node.parent
        while physical_parent
            and (physical_parent.is_collection
                or not physical_parent._canonical_folder_id) do
            physical_parent = physical_parent.parent
        end
        -- Canonical filtered result rows are detached from the accordion tree,
        -- so they have no parent pointer even though the active query is still
        -- scoped to the selected physical Favorites folder. Preserve that
        -- authoritative browser scope instead of returning to Favorites home
        -- when a filtered file is clicked.
        if not physical_parent and not browser.current_folder_id
            and not CanonicalResultViewActive() then
            ClearCanonicalFavoriteFolderFacetScope(true)
            browser.current_folder_id = nil
            browser.current_path = nil
            browser.available_tags = {}
        end
    end
    local independent_audio_trigger =
        GetPreviewTransportMode() == "independent"
        and IsAudioFile(node.path)
    state.pending_audio_start_from_seek = independent_audio_trigger
    if independent_audio_trigger then
        state.pending_audio_handoff_position = nil
    elseif state.is_playing and state.media_kind == "audio"
        and not (GetCurrentAudioPlaybackPolicy().sync
            and (r.GetPlayState() & 1) == 0) then
        state.pending_audio_handoff_position = GetPreviewPosition()
    else
        state.pending_audio_handoff_position = nil
    end
    state.current_media_class = GetMediaClass(node)
    state.multi_selected = {[node.path] = true}
    state.selection_anchor = node.path
    state.selection_anchor_row_key = row_key
    state.selected_file_row_keys = row_key
        and {[node.path] = row_key} or {}
    state.cursor_path = node.path
    state.cursor_type = "file"
    state.selected_path = node.path
    state.scroll_to_cursor = ensure_visible == true
    LoadBrowserFile(node.path, state.current_media_class,
        state.auto_play == true)
    if state.auto_play then StartPreview() end
end

function PlayFile(filepath)
    local independent_audio_trigger =
        GetPreviewTransportMode() == "independent"
        and IsAudioFile(filepath)
    state.pending_audio_start_from_seek = independent_audio_trigger
    local retriggering_audio_one_shot = state.selected_path == filepath
        and state.media_kind == "audio"
        and GetCurrentAudioPlaybackPolicy().is_one_shot
    if independent_audio_trigger or retriggering_audio_one_shot then
        -- An explicit trigger starts from the selected seek point rather than
        -- inheriting the outgoing cursor. Avoid querying that native cursor on
        -- an explicit trigger so StartPreview can replace the source immediately.
        state.pending_audio_handoff_position = nil
    elseif state.is_playing and state.media_kind == "audio"
        and not (GetCurrentAudioPlaybackPolicy().sync
            and (r.GetPlayState() & 1) == 0) then
        state.pending_audio_handoff_position = GetPreviewPosition()
    else
        state.pending_audio_handoff_position = nil
    end
    if state.selected_path ~= filepath then LoadBrowserFile(filepath, nil, true) end
    StartPreview()
end

function GetAllFilesInScope()
    -- Random browsing follows the folder containing the current file. Merely
    -- having another library folder open (or previously scoped) must not allow
    -- Randomize to jump into it.
    local current_index = state.visible_index_by_path[state.selected_path or ""]
    local current_item = current_index and state.visible_items[current_index] or nil
    local current_node = current_item and current_item.node or nil
    local parent_path = current_node and current_node.parent
        and current_node.parent.path or ""
    local selected_tags = {}
    for tag, enabled in pairs(state.media_filters.selected_tags or {}) do
        if enabled then selected_tags[#selected_tags + 1] = tag end
    end
    table.sort(selected_tags)
    local quick_types = {}
    for kind, enabled in pairs(state.media_filters.quick_types or {}) do
        if enabled then quick_types[#quick_types + 1] = kind end
    end
    table.sort(quick_types)
    local candidate_key = table.concat({
        tostring(state.favorites_mode), tostring(state.search_text or ""),
        tostring(state.selected_folder_scope or ""), parent_path,
        table.concat(selected_tags, ","), table.concat(quick_types, ","),
        tostring(state.media_filters.key_pc or -1),
        tostring(state.media_tag_generation or 0),
    }, "|")
    if state.random_candidates_key == candidate_key
        and state.random_candidates then
        return state.random_candidates
    end

    if state.search_text ~= "" or MediaFiltersActive() then
        state.random_candidates = GetCachedSearchResults()
        state.random_candidates_key = candidate_key
        return state.random_candidates
    end

    if current_node and current_node.parent then
        local siblings = {}
        for _, file in ipairs(current_node.parent.files or {}) do
            siblings[#siblings + 1] = file
        end
        state.random_candidates = siblings
        state.random_candidates_key = candidate_key
        return siblings
    end

    local files = {}
    local function Gather(node)
        if not node then return end
        for _, f in ipairs(node.files) do table.insert(files, f) end
        for _, c in ipairs(node.children) do Gather(c) end
    end
    if state.selected_folder_scope and state.selected_folder_scope ~= "" then
        local function FindNode(node, path)
            if not node then return nil end
            if node.path == path then return node end
            for _, c in ipairs(node.children) do
                local found = FindNode(c, path)
                if found then return found end
            end
            return nil
        end
        local scope_node = nil
        for _, tree in ipairs(GetActiveTrees()) do
            scope_node = FindNode(tree, state.selected_folder_scope)
            if scope_node then break end
        end
        Gather(scope_node)
    else
        for _, tree in ipairs(GetActiveTrees()) do Gather(tree) end
    end
    state.random_candidates = files
    state.random_candidates_key = candidate_key
    return files
end

function PlayRandomFile()
    local files = GetAllFilesInScope()
    if #files == 0 then return nil end
    local pick
    if #files > 1 and state.selected_path then
        repeat pick = files[math.random(#files)] until pick.path ~= state.selected_path
    else
        pick = files[math.random(#files)]
    end
    -- Search results are already flat and normal random browsing is restricted
    -- to the current open folder, so no unrelated folder needs to be opened.
    -- This keeps the browser/search viewport stable while randomizing.
    local node = pick.node or pick
    SetCursorToFileNode(node, true)
    return node
end

local function CurrentRandomNode()
    local idx = state.visible_index_by_path[state.selected_path or ""]
    local item = idx and state.visible_items[idx] or nil
    return item and item.type == "file" and item.node or nil
end

local function SelectRandomHistoryEntry(index)
    local entry = state.random_history[index]
    if not entry then return false end
    state.random_history_index = index
    SetCursorToFileNode(entry.node, true)
    return true
end

function NavigateRandomHistory(direction)
    if CanonicalResultViewActive() then
        local browser = state.canonical_browser
        local rows = browser.random_rows or {}
        local active = rows[browser.random_index or 0]
        if active and state.selected_path ~= active.path then
            browser.random_history = {}
            browser.random_rows = {}
            browser.random_pool = {}
            browser.random_index = 0
            browser.random_force_start = false
            browser.random_wrap_rows = nil
            browser.random_cursor_key = nil
            browser.random_cursor_id = nil
            rows = browser.random_rows
        end
        if direction < 0 then
            if (browser.random_index or 0) > 1 then
                browser.random_index = browser.random_index - 1
                local picked = rows[browser.random_index]
                SelectCanonicalRandomResult(picked, false)
            end
            return
        end
        if (browser.random_index or 0) < #rows then
            browser.random_index = browser.random_index + 1
            local picked = rows[browser.random_index]
            SelectCanonicalRandomResult(picked, false)
            return
        end
        if #(browser.random_pool or {}) > 0 then
            local picked = table.remove(browser.random_pool, 1)
            SelectCanonicalRandomResult(picked, true)
            return
        end
        if not browser.loading then
            RequestCanonicalBrowserPage(
                "browser_random",
                browser.current_folder_id, 0, false, false)
        end
        return
    end

    local history = state.random_history
    local current = CurrentRandomNode()

    -- A manual click or other navigation starts a fresh random trail.
    local active = history[state.random_history_index]
    if current and (not active or active.path ~= current.path) then
        history = {{ path = current.path, node = current }}
        state.random_history = history
        state.random_history_index = 1
    end

    if direction < 0 then
        if state.random_history_index > 1 then
            SelectRandomHistoryEntry(state.random_history_index - 1)
        end
        return
    end

    if state.random_history_index < #history then
        SelectRandomHistoryEntry(state.random_history_index + 1)
        return
    end

    local before = state.selected_path
    local node = PlayRandomFile()
    if state.selected_path and state.selected_path ~= before then
        history[#history + 1] = { path = state.selected_path, node = node }
        if #history > state.random_history_limit then table.remove(history, 1) end
        state.random_history_index = #history
    end
end

function SetCursorToIndex(idx)
    local it = state.visible_items[idx]
    if not it then return end
    if it.type == "folder" then
        if it.node and it.node._canonical_row
            and state.database_startup_test.enabled then
            state.multi_selected = {}
            state.selection_anchor = nil
            state.selection_anchor_row_key = nil
            state.selected_file_row_keys = {}
            state.cursor_path = it.node.path
            state.cursor_type = "folder"
            state.cursor_favorite_instance_key = state.favorites_mode
                and GetFavoriteNodeInstanceKey(it.node) or nil
            state.scroll_to_cursor = true
        else
            SetCursorToFolderNode(it.node, true)
        end
    else
        SetCursorToFileNode(it.node, true, it.row_key)
    end
end

function HandleRightArrow(idx)
    if not idx then if #state.visible_items > 0 then SetCursorToIndex(1) end return end
    local it = state.visible_items[idx]
    if not it then return end
    if it.type == "folder" then
        local open_map = state.favorites_mode
            and state.favorite_open_folders or state.open_folders
        local open_key = GetFolderUIKey(it.node)
        if not open_map[open_key] then
            OpenFolderAccordion(it.node)
            state.scroll_to_cursor = true
        else
            local next_item = state.visible_items[idx + 1]
            if next_item and next_item.depth > it.depth then SetCursorToIndex(idx + 1) end
        end
    else
        local selected_is_loaded = state.source_file == it.path
        local can_retrigger = not PreviewFollowsArrangement()
            or (selected_is_loaded and (
                state.media_kind == "audio"
                or (state.current_file_is_one_shot
                    and state.one_shot_bypass.sync)))
        if not state.auto_play or can_retrigger then PlayFile(it.path) end
    end
end

function HandleLeftArrow(idx)
    -- Filtered results are a flat list, not a folder level. Do not let Left
    -- jump to a hidden parent and make the current result appear to vanish.
    if state.search_text ~= "" or MediaFiltersActive() then return end
    if not idx then return end
    local it = state.visible_items[idx]
    if not it then return end
    if it.type == "file" then
        SetCursorToFolderNode(it.node.parent, true)
    else
        local open_map = state.favorites_mode
            and state.favorite_open_folders or state.open_folders
        local open_key = GetFolderUIKey(it.node)
        if open_map[open_key] then
            open_map[open_key] = false
            state.scroll_to_cursor = true
            state.needs_visible_update = true
        else
            SetCursorToFolderNode(it.node.parent, true)
        end
    end
end

function HandleBrowserKeys()
    if state.block_browser_input then return end
    local idx = FindCursorIndex()
    local it = idx and state.visible_items[idx] or nil
    local on_file = (it and it.type == "file")
    local canonical_random_list = CanonicalResultViewActive()

    local ctrl = select(1, GetSelectionModifiers())
    if ctrl and imgui.IsKeyPressed(ctx, imgui.Key_A, false) then
        local selected, first_path = {}, nil
        for _, visible in ipairs(state.visible_items or {}) do
            if visible.type == "file" then
                selected[visible.path] = true
                first_path = first_path or visible.path
            end
        end
        state.multi_selected = selected
        state.selected_file_row_keys = {}
        state.selection_anchor_row_key = nil
        if not state.selection_anchor
            or not selected[state.selection_anchor] then
            state.selection_anchor = first_path
        end
        return
    end

    local keyboard_navigation_pressed =
        imgui.IsKeyPressed(ctx, imgui.Key_DownArrow, true)
        or imgui.IsKeyPressed(ctx, imgui.Key_UpArrow, true)
        or imgui.IsKeyPressed(ctx, imgui.Key_RightArrow, true)
        or imgui.IsKeyPressed(ctx, imgui.Key_LeftArrow, true)
    if keyboard_navigation_pressed then
        -- Mouse row activation is deliberately deferred until release so an
        -- existing multi-selection can become a drag. Once the keyboard takes
        -- ownership, that deferred click is stale: allowing a later click on
        -- playback/Home to release it jumps the browser back to the old row.
        CancelPendingMediaRowActivation()
        state.suppress_mouse_hover = true
        state.hovered_path = nil
        state.keyboard_navigation_at = r.time_precise()
        state.suppress_hover_mouse_x,
            state.suppress_hover_mouse_y = imgui.GetMousePos(ctx)
    end

    if imgui.IsKeyPressed(ctx, imgui.Key_Space, false) then
        if state.is_playing then
            StopPreview()
            if (r.GetPlayState() & 1) ~= 0 then r.CSurf_OnStop() end
        else
            r.Main_OnCommand(40044, 0) -- Transport: Play/stop
        end
    elseif imgui.IsKeyPressed(ctx, imgui.Key_DownArrow, true) then
        if state.randomize_on and on_file
            and not canonical_random_list then
            NavigateRandomHistory(1)
        else
            local new_idx = (idx or 0) + 1
            if new_idx <= #state.visible_items then SetCursorToIndex(new_idx) end
        end
    elseif imgui.IsKeyPressed(ctx, imgui.Key_UpArrow, true) then
        if state.randomize_on and on_file
            and not canonical_random_list then
            NavigateRandomHistory(-1)
        else
            local new_idx = (idx or (#state.visible_items + 1)) - 1
            if new_idx >= 1 then SetCursorToIndex(new_idx) end
        end
    elseif imgui.IsKeyPressed(ctx, imgui.Key_RightArrow, true) then
        if canonical_random_list and it and it.type == "folder"
            and it.node and it.node._canonical_row
            then
            EnterCanonicalBrowserFolder(it.node._canonical_row)
        else
            HandleRightArrow(idx)
        end
    elseif imgui.IsKeyPressed(ctx, imgui.Key_LeftArrow, true) then
        if canonical_random_list then
            local browser = state.canonical_browser
            if browser.discovery_active then
                ExitCanonicalLuckyDraw()
            elseif CanonicalBrowserFiltersActive() then
                ClearCanonicalBrowserFilters()
            elseif state.favorites_mode and state.favorite_smart_mode then
                CloseFavoriteSmartFolder()
            elseif #browser.history > 0 and not browser.loading then
                BackCanonicalBrowserFolder()
            end
        else
            HandleLeftArrow(idx)
        end
    elseif imgui.IsKeyPressed(ctx, imgui.Key_Enter, false)
        or imgui.IsKeyPressed(ctx, imgui.Key_KeypadEnter, false) then
        if idx then
            if it.type == "file" and IsAudioFile(it.path) then
                SendSelectedFilesToReaDrum(it.path)
            elseif it.type == "file" then
                PlayFile(it.path)
            elseif canonical_random_list and it.node
                and it.node._canonical_row
                then
                EnterCanonicalBrowserFolder(it.node._canonical_row)
            elseif it.type == "folder" then
                local open_map = state.favorites_mode
                    and state.favorite_open_folders or state.open_folders
                local open_key = GetFolderUIKey(it.node)
                if open_map[open_key] then
                    open_map[open_key] = false
                    state.needs_visible_update = true
                else
                    OpenFolderAccordion(it.node)
                end
            end
        end
    end
end

-- ============================================================
-- UI DRAWING
-- ============================================================
function ClearThemeSuggestions()
    state.theme.suggestions = {}
end

function ThemeColorChroma(color)
    local red = (color >> 24) & 0xFF
    local green = (color >> 16) & 0xFF
    local blue = (color >> 8) & 0xFF
    return math.max(red, green, blue) - math.min(red, green, blue)
end

function AddThemeSuggestion(row, label, color)
    if not color then return end
    if row == "accent" and ThemeColorChroma(color) < 20 then return end
    local choices = state.theme.suggestions[row] or {}
    for _, choice in ipairs(choices) do
        local dr = math.abs(((choice.color >> 24) & 0xFF) - ((color >> 24) & 0xFF))
        local dg = math.abs(((choice.color >> 16) & 0xFF) - ((color >> 16) & 0xFF))
        local db = math.abs(((choice.color >> 8) & 0xFF) - ((color >> 8) & 0xFF))
        if dr + dg + db < 24 then return end
    end
    if #choices < 4 then
        choices[#choices + 1] = {label = label, color = color}
        state.theme.suggestions[row] = choices
    end
end

function ImportREAPERTheme(mode)
    ClearThemeSuggestions()
    local main = GetREAPERThemeColor("col_main_bg2", 0x333333FF)
    local main_lum = ColorLuminance(main)
    local light = mode == "light" or (mode == "auto" and main_lum >= 145)
    if mode == "dark" then light = false end

    local c = state.theme.colors
    if light then
        c.window_bg = BlendColor(main, 0xEEEEEEFF, main_lum < 170 and 0.72 or 0.32)
        c.panel_bg = AdjustColor(c.window_bg, 0.035)
        c.text = 0x202020FF
        c.border = AdjustColor(c.panel_bg, -0.24)
        c.preview_bg = AdjustColor(c.panel_bg, -0.035)
        c.preview_grid = AdjustColor(c.preview_bg, -0.16)
    else
        c.window_bg = BlendColor(main, 0x2B2B2BFF, main_lum > 85 and 0.72 or 0.34)
        c.panel_bg = AdjustColor(c.window_bg, 0.065)
        c.text = 0xE2E2E2FF
        c.border = AdjustColor(c.panel_bg, -0.30)
        c.preview_bg = AdjustColor(c.panel_bg, -0.16)
        c.preview_grid = AdjustColor(c.preview_bg, 0.14)
    end

    local accent, notes, folders = GetREAPERAccentPalette()
    c.accent = EnsureColorContrast(accent, c.panel_bg, 68)
    c.header_icon = EnsureColorContrast(accent, c.window_bg, 86)
    c.selected_text = EnsureReadableText(
        GetREAPERThemeColor("genlist_selfg", light and 0x181818FF or 0xFFFFFFFF),
        c.accent,
        105
    )
    c.folder_text = EnsureColorContrast(folders, c.panel_bg, 86)
    c.midi_note = EnsureColorContrast(notes, c.preview_bg, 100)
    state.theme.use_custom = true
    AddThemeSuggestion("accent", "Auto choice", c.accent)
    AddThemeSuggestion("header_icon", "Auto choice", c.header_icon)

    local candidate_rows = {
        window_bg = {
            {"Main background", "col_main_bg2"}, {"Main surface", "col_main_bg"},
        },
        panel_bg = {
            {"List background", "genlist_bg"}, {"Track-list background", "col_tracklistbg"},
            {"Arrange background", "col_arrangebg"},
        },
        text = {
            {"List text", "genlist_fg"}, {"Main text", "col_main_text"},
            {"Toolbar text", "col_toolbar_text"},
        },
        selected_text = {
            {"Selected-list text", "genlist_selfg"}, {"Active toolbar text", "col_toolbar_text_on"},
        },
        accent = {
            {"List selection", "genlist_selbg"}, {"Toolbar highlight", "col_toolbar_text_on"},
            {"Pressed toolbar", "toolbararmed_color"}, {"Selected highlight", "genlist_hilite_sel"},
        },
        header_icon = {
            {"Toolbar highlight", "col_toolbar_text_on"}, {"Pressed toolbar", "toolbararmed_color"},
            {"List selection", "genlist_selbg"},
        },
        border = {
            {"Toolbar frame", "col_toolbar_frame"}, {"3D shadow", "col_main_3dsh"},
        },
        preview_bg = {
            {"Editor background", "col_main_editbk"}, {"Arrange background", "col_arrangebg"},
        },
        preview_grid = {
            {"Arrange grid", "arrange_vgrid"}, {"Grid lines", "col_gridlines"},
        },
    }
    for row, entries in pairs(candidate_rows) do
        for _, entry in ipairs(entries) do
            AddThemeSuggestion(row, entry[1], GetOptionalREAPERThemeColor(entry[2]))
        end
    end
    for _, choice in ipairs(state.theme.suggestions.accent or {}) do
        AddThemeSuggestion("folder_text", choice.label, choice.color)
        AddThemeSuggestion("midi_note", choice.label, choice.color)
    end
    SaveSettings()
end

function DrawThemeSwatch(id, color, tooltip, active)
    local width, height = 38, 23
    local x, y = imgui.GetCursorScreenPos(ctx)
    -- Use the same native Button capture path as the hardened browser
    -- controls. InvisibleButton could leave the host's shared mouse capture
    -- active after a popup interaction and interfere with REAPER or other GUIs.
    imgui.PushStyleColor(ctx, imgui.Col_Text, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_Button, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive, 0x00000000)
    local clicked = imgui.Button(ctx, id, width, height)
    imgui.PopStyleColor(ctx, 4)
    if clicked then CancelPendingMediaRowActivation() end
    local draw_list = imgui.GetWindowDrawList(ctx)
    imgui.DrawList_AddRectFilled(draw_list, x + 2, y + 3, x + width + 2, y + height + 3, 0x0000004C, 5)
    imgui.DrawList_AddRectFilled(draw_list, x, y, x + width, y + height, color, 5)
    local outline = ColorLuminance(color) >= 128 and 0x303030D0 or 0xE0E0E0B0
    imgui.DrawList_AddRect(draw_list, x, y, x + width, y + height, outline, 5, 0, active and 2 or 1)
    if active then
        imgui.DrawList_AddCircleFilled(draw_list, x + width - 6, y + 6, 3, outline)
    end
    if imgui.IsItemHovered(ctx) and tooltip then imgui.SetTooltip(ctx, tooltip) end
    return clicked
end

function DrawThemeColorRow(key, label)
    local c = state.theme.colors
    local row_x = imgui.GetCursorPosX(ctx)
    imgui.Text(ctx, label)
    imgui.SameLine(ctx)
    imgui.SetCursorPosX(ctx, row_x + 172)
    if DrawThemeSwatch("##active_" .. key, c[key], "Edit " .. label, true) then
        imgui.OpenPopup(ctx, "Edit " .. label .. "##" .. key)
    end
    if imgui.BeginPopup(ctx, "Edit " .. label .. "##" .. key) then
        local changed, value = imgui.ColorEdit4(ctx, "##picker_" .. key, c[key])
        if changed then c[key] = value; SaveSettings() end
        imgui.EndPopup(ctx)
    end

    for index, choice in ipairs(state.theme.suggestions[key] or {}) do
        imgui.SameLine(ctx)
        if index == 1 then
            imgui.SetCursorPosX(ctx, row_x + 238)
        end
        if DrawThemeSwatch(
            "##choice_" .. key .. "_" .. index,
            choice.color,
            choice.label,
            choice.color == c[key]
        ) then
            c[key] = choice.color
            SaveSettings()
        end
    end
end

function DrawOneShotBypassSetting(label, key, detail)
    local changed, value = imgui.Checkbox(
        ctx, label, state.one_shot_bypass[key] == true)
    if changed then
        state.one_shot_bypass[key] = value
        SaveSettings()
        ApplyOneShotPolicyChange()
    end
    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx,
            detail .. "\nThe global control remains enabled for loops and other files.")
    end
end

function DrawOneShotModeSettings()
    local drag_changed, native_default = imgui.Checkbox(ctx,
        "Native file drag by default (Alt: transformed timeline drag)",
        state.external_drag_default_native)
    if drag_changed then
        state.external_drag_default_native = native_default
        SaveSettings()
    end
    local shot_changed, shot_native = imgui.Checkbox(ctx,
        "Use native drag for audio one-shots (Alt: transformed)",
        state.one_shot_native_drag)
    if shot_changed then
        state.one_shot_native_drag = shot_native
        SaveSettings()
    end
    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx, "Applies when One-Shot Mode is enabled and every dragged file is classified as an audio one-shot. Mixed selections use the general drag default.")
    end
    imgui.Spacing(ctx)
    local audio_changed, audio_enabled = imgui.Checkbox(
        ctx, "One-Shot Mode", state.audio_auto_one_shot)
    if audio_changed then
        state.audio_auto_one_shot = audio_enabled
        SaveSettings()
        ApplyOneShotPolicyChange()
    end
    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx,
            "Apply the configurable one-shot playback profile to audio\n" ..
            "classified as One-shot. Turning this off immediately restores\n" ..
            "normal playback controls for the loaded sample.")
    end
    local midi_changed, midi_enabled = imgui.Checkbox(
        ctx, "Treat sub-bar MIDI as one-shots", state.one_shot_mode)
    if midi_changed then
        state.one_shot_mode = midi_enabled
        SaveSettings()
        ApplyOneShotPolicyChange()
    end
    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx,
            "Apply the same profile to MIDI classified as One-shot or\n" ..
            "shorter than one bar. Disabled by default.")
    end
    imgui.Spacing(ctx)
    imgui.Text(ctx, "When One-Shot Mode applies, bypass:")
    imgui.Indent(ctx, 18)
    DrawOneShotBypassSetting(
        "Transport sync/link", "sync",
        "One-shots start independently instead of waiting for a bar or controlling REAPER's transport.")
    DrawOneShotBypassSetting(
        "Loop preview", "loop",
        "One-shots stop at the end instead of following Loop preview.")
    DrawOneShotBypassSetting(
        "Tempo Match", "tempo_match",
        "Audio one-shots play at their native tempo.")
    DrawOneShotBypassSetting(
        "Key Sync", "key_sync",
        "One-shots keep their detected/native key; manual pitch remains available.")
    DrawOneShotBypassSetting(
        "Half/double playback rate", "playrate",
        "One-shots play at normal 1x rate.")
    imgui.Unindent(ctx, 18)
end

function DrawSettingsPopup()
    if not state.show_settings then return end
    -- A bounded, scrolling window prevents the accumulated settings from
    -- growing past the monitor and remains user-resizable. Keep this as an
    -- independent window instead of a modal popup: ImGui's modal background
    -- layer changes the apparent browser colors and makes live theme editing
    -- misleading.
    imgui.SetNextWindowSize(ctx, 660, 620, imgui.Cond_Appearing)
    -- The tab body owns scrolling. Keep the window itself fixed so users do
    -- not get a second scrollbar beside the tab's scrollbar.
    local settings_visible, settings_open = imgui.Begin(
        ctx, "Settings", true,
        imgui.WindowFlags_NoCollapse | FLG_NO_SCROLLBAR | FLG_NO_NAV_INPUTS)
    if settings_visible then
        if imgui.IsWindowHovered(ctx)
            and (imgui.IsMouseClicked(ctx, 0)
                or imgui.IsMouseClicked(ctx, 1)) then
            CancelPendingMediaRowActivation()
        end
        local _, settings_available_height = imgui.GetContentRegionAvail(ctx)
        local settings_body_height = math.max(
            260, settings_available_height - 58)
        if imgui.BeginTabBar(ctx, "##settings_tabs") then
            if imgui.BeginTabItem(ctx, "Playback") then
                if imgui.BeginChild(
                    ctx, "##settings_playback", 0,
                    settings_body_height, 0, FLG_NO_NAV_INPUTS) then
        imgui.Text(ctx, "Playback")
        imgui.Separator(ctx)
        DrawOneShotModeSettings()
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Preview stretch mode")
        local selected_stretch = GetSelectedPreviewStretchMode()
        if imgui.BeginCombo(
            ctx, "##preview_stretch_mode", selected_stretch.label) then
            for _, choice in ipairs(GetPreviewStretchModeCatalog()) do
                if imgui.Selectable(ctx, choice.label,
                    state.preview_stretch_mode == choice.key) then
                    state.preview_stretch_mode = choice.key
                    SavePreviewPreferences("stretch_mode")
                    ApplyPlaybackSettings("stretch_mode")
                end
            end
            imgui.EndCombo(ctx)
        end
        if imgui.IsItemHovered(ctx) then
            imgui.SetTooltip(ctx,
                "Select the time-stretch engine used by native audio preview. "
                    .. "Project default follows REAPER; installed Elastique "
                    .. "Pro and Efficient modes are listed separately.")
        end
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Audio preview route")
        if imgui.Button(
            ctx, GetAudioRouteLabel() .. "  \xe2\x96\xbe", 300, 0) then
            imgui.OpenPopup(ctx, "Audio Route Options")
        end
        if imgui.IsItemHovered(ctx) then
            imgui.SetTooltip(ctx,
                state.audio_route_mode == "hardware_output"
                and "This direct route bypasses the project master."
                or "Selected tracks play through their track FX and the master.")
        end
        if imgui.BeginPopup(ctx, "Audio Route Options") then
            local check = "\xe2\x9c\x93 "
            if imgui.MenuItem(ctx,
                (state.audio_route_mode == "selected_track" and check or "")
                    .. "Selected track > Master") then
                SetAudioRoute("selected_track")
            end
            imgui.TextDisabled(
                ctx, "With no selected track, uses the first stereo output.")
            imgui.Separator(ctx)
            imgui.TextDisabled(ctx, "Direct outputs (bypass master)")

            local outputs, available = GetAvailableAudioOutputs()
            local pair_count = 0
            for _, output in ipairs(outputs) do
                local channel = output.channel
                if channel % 2 == 0 and available[channel + 1] then
                    pair_count = pair_count + 1
                    local selected = state.audio_route_mode == "hardware_output"
                        and state.audio_route_output_channel == channel
                        and not state.audio_route_output_mono
                    if imgui.MenuItem(ctx,
                        (selected and check or "")
                            .. GetAudioOutputPairLabel(channel)) then
                        SetAudioRoute("hardware_output", channel, false)
                    end
                end
            end
            if pair_count == 0 then
                imgui.TextDisabled(ctx, "No stereo output pairs available")
            end

            if #outputs > 0 then
                imgui.Separator(ctx)
                imgui.TextDisabled(ctx, "Individual outputs (mono)")
                for _, output in ipairs(outputs) do
                    local channel = output.channel
                    local selected = state.audio_route_mode == "hardware_output"
                        and state.audio_route_output_channel == channel
                        and state.audio_route_output_mono
                    if imgui.MenuItem(ctx,
                        (selected and check or "") .. output.name) then
                        SetAudioRoute("hardware_output", channel, true)
                    end
                end
            end
            imgui.EndPopup(ctx)
        end
                imgui.EndChild(ctx)
                end
                imgui.EndTabItem(ctx)
            end

            if imgui.BeginTabItem(ctx, "Database") then
                if imgui.BeginChild(
                    ctx, "##settings_library", 0,
                    settings_body_height, 0, FLG_NO_NAV_INPUTS) then
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Library database")
        imgui.Separator(ctx)
        if state.database.backend == "sqlite" then
            imgui.Text(ctx, "SQLite ready")
            imgui.SameLine(ctx)
            imgui.TextDisabled(
                ctx, "(schema " .. tostring(state.database.schema_version) .. ")")
        elseif state.database.rebuild_required then
            imgui.TextDisabled(ctx, "Delete the incompatible database to continue")
            if imgui.IsItemHovered(ctx) then
                imgui.SetTooltip(ctx,
                    state.database.error
                        or "Delete the incompatible database and restart ReaBrowse.")
            end
        else
            imgui.TextDisabled(ctx, "SQLite unavailable")
            if imgui.IsItemHovered(ctx) then
                imgui.SetTooltip(
                    ctx,
                    state.database.error
                        or "The bundled database helper is unavailable.")
            end
        end
        imgui.TextDisabled(
            ctx,
            state.database.backend == "sqlite"
                and GetMediaDatabasePath()
                or "Library browsing and updates require SQLite.")
        local database_status = state.database.status or ""
        local status_belongs_to_maintenance =
            database_status:match("^Worker ") ~= nil
            or database_status:match("^Library database") ~= nil
            or database_status:match("^Library reset") ~= nil
            or database_status:match("^Factory reset") ~= nil
        if database_status ~= "" and not status_belongs_to_maintenance then
            imgui.TextDisabled(ctx, database_status)
        end
        local sync = state.canonical_scan_sync
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Scan")
        imgui.SameLine(ctx)
        if state.library_scan.scanning then
            local scan_label, scan_detail, scan_done, scan_total,
                scan_fraction = GetLibraryScanProgress()
            imgui.TextDisabled(ctx, scan_label .. " - " .. scan_detail)
            if scan_fraction and imgui.ProgressBar then
                imgui.ProgressBar(ctx, scan_fraction, -1, 0,
                    FormatLibraryProgressCaption(
                        scan_done, scan_total, scan_fraction))
            end
            if state.library_scan.operation_kind ~= "scan"
                or state.library_scan.phase == "commit"
                or state.library_scan.phase == "finalize_db" then
                imgui.TextDisabled(ctx,
                    "This database operation cannot be interrupted.")
            elseif imgui.Button(ctx, "Cancel", 90, 0) then
                CancelLibraryScan()
            end
        else
            local update_blocked = RootLibraryActionsBlocked()
            if update_blocked and imgui.BeginDisabled then
                imgui.BeginDisabled(ctx, true)
            end
            if imgui.Button(ctx, "Update all folders", 150, 0)
                and not update_blocked then
                StartLibraryScan()
            end
            if update_blocked and imgui.EndDisabled then imgui.EndDisabled(ctx) end
        end
        imgui.Spacing(ctx)
        if not state.database.canonical then
            imgui.Text(ctx, "Configured folders")
            imgui.Separator(ctx)
            imgui.TextDisabled(ctx,
                "Saved folder settings are preserved and will return when SQLite is available.")
        else
            imgui.Text(ctx,
                "Configured folders (" .. tostring(#state.root_folders) .. ")")
            imgui.Separator(ctx)
            if #state.root_folders == 0 then
                imgui.TextDisabled(ctx,
                    "No library folders configured. Use + in the top bar to add one.")
            else
                imgui.TextDisabled(ctx,
                    "Update only the selected folder, or remove it from ReaBrowse.")
                for index, root_path in ipairs(state.root_folders) do
                    local row_x = imgui.GetCursorPosX(ctx)
                    local row_width = select(1, imgui.GetContentRegionAvail(ctx))
                    local button_gap = 8
                    local buttons_width = 90 + button_gap + 90
                    local label_width = math.max(120,
                        row_width - buttons_width - 16)
                    local shown_path = root_path
                    if imgui.CalcTextSize
