                    imgui.Text(ctx, shown_path)
                    if shown_path ~= root_path and imgui.IsItemHovered(ctx) then
                        imgui.SetTooltip(ctx, root_path)
                    end
                    imgui.SameLine(ctx)
                    imgui.SetCursorPosX(ctx,
                        row_x + row_width - buttons_width)
                    local root_actions_blocked = RootLibraryActionsBlocked()
                    if root_actions_blocked and imgui.BeginDisabled then
                        imgui.BeginDisabled(ctx, true)
                    end
                    if imgui.Button(
                        ctx, "Update##settings_root_update_" .. tostring(index),
                        90, 0) then
                        StartLibraryScan(root_path)
                    end
                    imgui.SameLine(ctx)
                    if imgui.Button(
                        ctx, "Remove##settings_root_remove_" .. tostring(index),
                        90, 0) then
                        RequestRootLibraryRemoval(root_path)
                    end
                    if root_actions_blocked and imgui.EndDisabled then
                        imgui.EndDisabled(ctx)
                    end
                    if index < #state.root_folders then imgui.Separator(ctx) end
                end
            end
        end
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Scan speed")
        imgui.SameLine(ctx)
        local scan_profile = GetLibraryScanSpeedProfile()
        imgui.SetNextItemWidth(ctx, 220)
