        if imgui.BeginPopup(ctx, "Factory Reset ReaBrowse?") then
            imgui.Text(ctx, "Factory reset ReaBrowse?")
            imgui.TextDisabled(ctx,
                "This removes the database, Favorites, user tags, and settings.\n"
