            if imgui.BeginTabItem(ctx, "Appearance") then
                if imgui.BeginChild(
                    ctx, "##settings_appearance", 0,
                    settings_body_height, 0, FLG_NO_NAV_INPUTS) then
        imgui.Spacing(ctx)
        imgui.Text(ctx, "Media Tags")
        imgui.Separator(ctx)
        imgui.Text(ctx, "Tag order")
        imgui.SameLine(ctx)
        imgui.SetNextItemWidth(ctx, 150)
        local tag_sort_label = state.tag_sort_mode == "az"
            and "A-Z" or "Most used"
        if imgui.BeginCombo(ctx, "##media_tag_sort", tag_sort_label) then
            for _, choice in ipairs({
                {key = "count", label = "Most used"},
                {key = "az", label = "A-Z"},
            }) do
                if imgui.Selectable(ctx, choice.label,
                    state.tag_sort_mode == choice.key) then
                    state.tag_sort_mode = choice.key
                    state.media_tag_bar.cache_key = nil
                    state.media_tag_bar.stable_key = nil
                    state.media_tag_bar.stable_tags = {}
                    state.canonical_browser.tag_catalog_cache = {}
                    state.canonical_browser.tag_catalog_cache_order = {}
                    SortMediaTagCatalog(
                        state.canonical_browser.available_tags or {},
                        state.canonical_browser.selected_tags)
                    SaveSettings()
                end
            end
            imgui.EndCombo(ctx)
        end
        imgui.TextDisabled(ctx,
            "Available broad tags stay first; remaining tags use this order.")

        imgui.Spacing(ctx)
        imgui.Text(ctx, "Theme Colors")
        imgui.Separator(ctx)

        imgui.TextDisabled(ctx, "Import from the current REAPER theme")
        if imgui.Button(ctx, "Auto Detect") then ImportREAPERTheme("auto") end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Import Dark") then ImportREAPERTheme("dark") end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Import Light") then ImportREAPERTheme("light") end

        imgui.Spacing(ctx)
        local has_alternatives = false
        for _, key in ipairs(THEME_COLOR_KEYS) do
            if #(state.theme.suggestions[key] or {}) > 0 then has_alternatives = true break end
        end
        local header_x = imgui.GetCursorPosX(ctx)
        imgui.SetCursorPosX(ctx, header_x + 172)
        imgui.TextDisabled(ctx, "Active")
        if has_alternatives then
            imgui.SameLine(ctx)
            imgui.SetCursorPosX(ctx, header_x + 238)
            imgui.TextDisabled(ctx, "Alternate")
        end
        imgui.Separator(ctx)

        DrawThemeColorRow("window_bg", "Window Background")
        DrawThemeColorRow("panel_bg", "Panel Background")
        DrawThemeColorRow("text", "Normal Text")
        DrawThemeColorRow("selected_text", "Selected / Hover Text")
        DrawThemeColorRow("folder_text", "Folder Text")
        DrawThemeColorRow("accent", "Accent (highlight)")
        DrawThemeColorRow("header_icon", "Header Icons")
        DrawThemeColorRow("border", "Border")
        DrawThemeColorRow("midi_note", "MIDI Notes")
        DrawThemeColorRow("preview_bg", "Preview Background")
        DrawThemeColorRow("preview_grid", "Preview Gridlines")

        imgui.Spacing(ctx)
        imgui.Text(ctx, "Font")
        imgui.Separator(ctx)

        imgui.SetNextItemWidth(ctx, 220)
        if state.font_name_input == nil then
            state.font_name_input = state.theme.font_name
        end
        local fchanged, fname = imgui.InputTextWithHint(
            ctx, "Font Name", "e.g. sans-serif, Arial, Verdana",
            state.font_name_input)
        if fchanged then state.font_name_input = fname end
        local apply_font_name = false
        if imgui.IsItemDeactivatedAfterEdit then
            local ok, deactivated = pcall(imgui.IsItemDeactivatedAfterEdit, ctx)
            apply_font_name = ok and deactivated
        else
            apply_font_name = fchanged and not imgui.IsItemActive(ctx)
        end
        if apply_font_name then
            local requested = (state.font_name_input or "")
                :gsub("^%s+", ""):gsub("%s+$", "")
            if requested == "" then requested = "sans-serif" end
            state.font_name_input = requested
            if requested ~= state.theme.font_name then
                state.theme.font_name = requested
                SaveSettings()
            end
        end

        imgui.Text(ctx, "Text size")
        imgui.SameLine(ctx)
        local displayed_font_size = state.pending_font_size
            or state.theme.font_size
        local requested_font_size
        if imgui.Button(ctx, "-##font_size_down", 30, 0) then
            requested_font_size = displayed_font_size - 1
        end
        imgui.SameLine(ctx)
        imgui.SetNextItemWidth(ctx, 78)
        if imgui.BeginCombo(ctx, "##font_size_combo",
            string.format("%d px", displayed_font_size)) then
            for size = 10, 28 do
                if imgui.Selectable(ctx, string.format("%d px", size),
                    displayed_font_size == size) then
                    requested_font_size = size
                end
            end
            imgui.EndCombo(ctx)
        end
        if imgui.IsItemHovered(ctx) then
            imgui.SetTooltip(ctx, "Choose an exact text size")
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "+##font_size_up", 30, 0) then
            requested_font_size = displayed_font_size + 1
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Reset##font_size_reset") then
            requested_font_size = 14
        end
        if requested_font_size then
            requested_font_size = math.max(10,
                math.min(28, requested_font_size))
            state.pending_font_size = requested_font_size
        end

        imgui.Spacing(ctx)
        
        if imgui.Button(ctx, "Preset: Dark (Default)") then
            state.theme.use_custom = true
            ClearThemeSuggestions()
            state.theme.colors.window_bg     = 0x2B2B2BFF
            state.theme.colors.panel_bg      = 0x333333FF
            state.theme.colors.text          = 0xE0E0E0FF
            state.theme.colors.selected_text = 0xFFFFFFFF
            state.theme.colors.accent        = 0x4A88DFFF
            state.theme.colors.header_icon   = 0x6AB4FFFF
            state.theme.colors.border        = 0x222222FF
            state.theme.colors.folder_text   = 0x6AB4FFFF
            state.theme.colors.midi_note     = 0x4AA0E8FF
            state.theme.colors.preview_bg    = 0x1A1A1AFF
            state.theme.colors.preview_grid  = 0x333333FF
            state.theme.font_name = "sans-serif"
            state.theme.font_size = 14
            state.pending_font_size = nil
            SaveSettings()
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Preset: Light") then
            state.theme.use_custom = true
            ClearThemeSuggestions()
            state.theme.colors.window_bg     = 0xE8E8E8FF
            state.theme.colors.panel_bg      = 0xF4F4F4FF
            state.theme.colors.text          = 0x1A1A1AFF
            state.theme.colors.selected_text = 0xFFFFFFFF
            state.theme.colors.accent        = 0x2E75D3FF
            state.theme.colors.header_icon   = 0x2E75D3FF
            state.theme.colors.border        = 0xB8B8B8FF
            state.theme.colors.folder_text   = 0x1A5CA5FF
            state.theme.colors.midi_note     = 0x3288E6FF
            state.theme.colors.preview_bg    = 0xE8E8E8FF
            state.theme.colors.preview_grid  = 0xCCCCCCFF
            state.theme.font_name = "sans-serif"
            state.theme.font_size = 14
            state.pending_font_size = nil
            SaveSettings()
        end
                imgui.EndChild(ctx)
                end
                imgui.EndTabItem(ctx)
            end

            imgui.EndTabBar(ctx)
        end

        imgui.Spacing(ctx)
        if imgui.Button(ctx, "Close", 100, 0) then
            state.show_settings = false
        end
    end
    imgui.End(ctx)
    if not settings_open then state.show_settings = false end
end

function DrawSearchClearOverlay(id, has_text)
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local max_x, max_y = imgui.GetItemRectMax(ctx)
    local restore_x, restore_y = imgui.GetCursorScreenPos(ctx)
    local button_size = math.max(14, math.min(20, max_y - min_y - 4))
    local button_x = max_x - button_size - 3
    local button_y = min_y + ((max_y - min_y - button_size) * 0.5)
    imgui.SetCursorScreenPos(ctx, button_x, button_y)
    local pressed = imgui.InvisibleButton(ctx, id, button_size, button_size)
    local hovered = imgui.IsItemHovered(ctx)
        and not state.suppress_mouse_hover
    local clicked = has_text and pressed
    if has_text then
        local draw_list = imgui.GetWindowDrawList(ctx)
        local color = state.resolved_theme and state.resolved_theme.text
            or state.theme.colors.text
        if not hovered then color = (color & 0xFFFFFF00) | 0xA0 end
        local inset = 5
        imgui.DrawList_AddLine(draw_list,
            button_x + inset, button_y + inset,
            button_x + button_size - inset, button_y + button_size - inset,
            color, 1.5)
        imgui.DrawList_AddLine(draw_list,
            button_x + button_size - inset, button_y + inset,
            button_x + inset, button_y + button_size - inset,
            color, 1.5)
        if hovered then imgui.SetTooltip(ctx, "Clear search") end
    end
    imgui.SetCursorScreenPos(ctx, restore_x, restore_y)
    return clicked
end

local function DrawFavoriteBookIcon(draw_list, color, x1, y1, x2, y2)
    imgui.DrawList_AddRect(
        draw_list, x1, y1, x2, y2, color, 1, 0, 1.5)
    imgui.DrawList_AddLine(
        draw_list, x1 + 1.5, y1 + 4, x2 - 1.5, y1 + 4, color, 1)
    imgui.DrawList_AddLine(
        draw_list, x1 + 1.5, y2 - 3, x2 - 1.5, y2 - 3, color, 1)
end

function DrawTopBar()
    imgui.BeginGroup(ctx)
    local add_disabled_scope = false
    local add_blocked = RootLibraryActionsBlocked()
    if add_blocked and imgui.BeginDisabled then
        imgui.BeginDisabled(ctx, true)
        add_disabled_scope = true
    end
    local add_folder_pressed = imgui.Button(ctx, "+##add_library_folder", 28, 0)
    if add_disabled_scope then imgui.EndDisabled(ctx) end
    if add_folder_pressed and not add_blocked then
        local path, dialog_available = BrowseForRootFolder()
        if path then
            local newly_added = AddRootFolderIfMissing(path)
            if newly_added or IsRootLibraryFolder(path) then
                SaveSettings()
                -- Adding a Library root is a Library-tree action. Clear any
                -- stale search/random/smart result mode so the published root
                -- behaves like every other accordion root when clicked.
                HomeCanonicalBrowser()
                state.pending_scan_root = path
                state.pending_scan_root_is_new = newly_added
                state.needs_refresh = true
            end
        elseif not dialog_available then
            imgui.OpenPopup(ctx, "Manual Add Folder")
        end
    end
    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx, not state.database.canonical
            and "SQLite is required before adding Library folders."
            or state.library_scan.scanning
                and "Finish the current library update first." or "Add folder")
    end

    if imgui.BeginPopupModal(ctx, "Manual Add Folder", nil, imgui.WindowFlags_AlwaysAutoResize) then
        imgui.Text(ctx, "Enter full path to folder:")
        local changed, path = imgui.InputText(ctx, "##manual_path", state.manual_add_path)
        if changed then state.manual_add_path = path end
        local manual_add_blocked = RootLibraryActionsBlocked()
        if manual_add_blocked and imgui.BeginDisabled then
            imgui.BeginDisabled(ctx, true)
        end
        local manual_add_pressed = imgui.Button(ctx, "Add")
        if manual_add_blocked and imgui.EndDisabled then imgui.EndDisabled(ctx) end
        if manual_add_pressed and not manual_add_blocked
            and state.manual_add_path ~= "" then
            local newly_added = AddRootFolderIfMissing(state.manual_add_path)
            if newly_added or IsRootLibraryFolder(state.manual_add_path) then
                SaveSettings()
                HomeCanonicalBrowser()
                state.pending_scan_root = state.manual_add_path
                state.pending_scan_root_is_new = newly_added
                state.needs_refresh = true
            end
            state.manual_add_path = ""
            imgui.CloseCurrentPopup(ctx)
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Cancel") then imgui.CloseCurrentPopup(ctx) end
        imgui.EndPopup(ctx)
    end

    imgui.SameLine(ctx)
    -- Search expands while reserving only the Favorites heart.
    imgui.SetNextItemWidth(ctx, -50)
    local scope_name = state.selected_folder_scope and GetFileName(state.selected_folder_scope) or "All Folders"
    if imgui.SetNextItemAllowOverlap then
        imgui.SetNextItemAllowOverlap(ctx)
    end
    local changed, new_search = imgui.InputTextWithHint(
        ctx, "##search", "Search " .. scope_name .. "...", state.search_input
    )
    local _, search_min_y = imgui.GetItemRectMin(ctx)
    local _, search_max_y = imgui.GetItemRectMax(ctx)
    if changed then
        state.search_input = new_search
        state.last_search_time = r.time_precise()
    end
    state.search_active = imgui.IsItemActive(ctx)
    if state.search_active
        and imgui.IsKeyPressed(ctx, imgui.Key_Enter, false) then
        -- Enter commits the current text immediately. Normal typing keeps the
        -- short debounce that prevents a query per keystroke at large scale.
        state.canonical_browser.search_commit_requested = true
    end
    if DrawSearchClearOverlay(
        "##clear_media_search", state.search_input ~= "") then
        state.search_input = ""
        state.search_text = ""
        state.force_search_update = true
        state.needs_visible_update = true
    end

    imgui.SameLine(ctx)
    imgui.SameLine(ctx)
    local heart_cursor_x = select(1, imgui.GetCursorScreenPos(ctx))
    local heart_height = 36
    imgui.SetCursorScreenPos(
        ctx, heart_cursor_x,
        (search_min_y + search_max_y - heart_height) * 0.5)
    if state.favorite_font then
        imgui.PushFont(ctx, state.favorite_font)
    elseif state.star_font then
        imgui.PushFont(ctx, state.star_font)
    end
    imgui.InvisibleButton(ctx, "##favorites_view_toggle", 42, heart_height)
    local icon_x, icon_y = imgui.GetItemRectMin(ctx)
    local icon_max_x, icon_max_y = imgui.GetItemRectMax(ctx)
    local icon_draw_list = imgui.GetWindowDrawList(ctx)
    local favorite_icon_color = state.resolved_theme and state.resolved_theme.accent or state.theme.colors.accent
    local favorite_icon_hovered = imgui.IsItemHovered(ctx, FLG_HOVER_ALLOW_BLOCKED)
    if favorite_icon_hovered or state.favorites_mode then
        local hover_fill = (favorite_icon_color & 0xFFFFFF00) | (favorite_icon_hovered and 0x26 or 0x14)
        imgui.DrawList_AddRectFilled(icon_draw_list, icon_x, icon_y, icon_max_x, icon_max_y, hover_fill, 6)
    end
    if state.favorites_mode then
        local cx = (icon_x + icon_max_x) * 0.5
        local cy = (icon_y + icon_max_y) * 0.5
        DrawFavoriteBookIcon(icon_draw_list, favorite_icon_color,
            cx - 12, cy - 9, cx - 6, cy + 10)
        DrawFavoriteBookIcon(icon_draw_list, favorite_icon_color,
            cx - 4, cy - 11, cx + 3, cy + 10)
        DrawFavoriteBookIcon(icon_draw_list, favorite_icon_color,
            cx + 5, cy - 8, cx + 12, cy + 10)
    else
        local heart_width, heart_height =
            imgui.CalcTextSize(ctx, "\xe2\x99\xa5")
        imgui.DrawList_AddText(
            icon_draw_list,
            icon_x + ((icon_max_x - icon_x)
                - heart_width) * 0.5,
            icon_y + ((icon_max_y - icon_y)
                - heart_height) * 0.5,
            favorite_icon_color, "\xe2\x99\xa5"
        )
    end
    if state.favorite_font or state.star_font then imgui.PopFont(ctx) end
    if imgui.IsItemClicked(ctx, 0) then
        ResetCanonicalForegroundView("Favorites view changed", true)
        state.favorites_mode = not state.favorites_mode
        local browser = state.canonical_browser
        browser.discovery_active = false
        browser.search_text = ""
        browser.selected_tags = {}
        browser.selected_classes = {}
        browser.key_pc = -1
        browser.offset = 0
        browser.selected_path = nil
        state.search_input = ""
        state.search_text = ""
        state.media_filters.selected_tags = {}
        state.media_filters.quick_types = {}
        state.media_filters.key_pc = -1
        if not state.favorites_mode and state.favorite_smart_mode then
            CloseFavoriteSmartFolder()
        end
        if state.favorites_mode then
            browser.smart_mode = nil
            browser.collection_key = nil
            browser.collection_scope_key = nil
            browser.history = {}
            browser.current_folder_id = nil
            browser.current_name = "Favorites"
            browser.current_path = nil
            state.favorite_smart_mode = nil
            if state.favorite_tree_dirty then
                BuildFavoriteTree(
                    state.database_startup_test.enabled,
                    state.database_startup_test.enabled)
            end
            -- Favorites is its own database scope. Do not leave the tag bar
            -- showing Library tags until a folder happens to be opened.
            ClearCanonicalTagCatalogCache()
        elseif state.database_startup_test.enabled then
            browser.smart_mode = nil
            browser.collection_scope_key = nil
            browser.history = {}
            browser.current_folder_id = nil
            browser.current_name = "Library"
            browser.current_path = nil
            browser.offset = 0
            browser.selected_path = nil
            if #state.folder_tree == 0 then LoadCanonicalAccordionRoots() end
        end
        state.selected_folder_scope = nil
        state.cursor_path = nil
        state.multi_selected = {}
        state.selection_anchor = nil
        state.selection_anchor_row_key = nil
        state.selected_file_row_keys = {}
        state.pending_single_node = nil
        state.pending_single_row_key = nil
        state.pending_ctrl_file = nil
        state.favorite_drag_pending_path = nil
        state.favorite_drag_pending_copy = false
        state.force_search_update = true
        state.needs_visible_update = true
    end
    state.favorite_drop_hovered = state.drag_active and favorite_icon_hovered
    if favorite_icon_hovered then
        imgui.SetTooltip(ctx, state.drag_active
            and (state.favorites_mode
                and "Drop to move to Favorites root"
                or "Drop to add to Favorites")
            or (state.favorites_mode and "Library view" or "Favorites view"))
    end
    if imgui.BeginPopupContextItem(ctx, "##favorites_heart_menu") then
        state.context_menu_active = true
        if imgui.MenuItem(ctx, "Add Favorite Folder...") then
            PromptAddFavoriteFolder()
        end
        imgui.Separator(ctx)
        imgui.TextDisabled(ctx, "Sort Favorites")
        if imgui.MenuItem(ctx, (state.favorite_sort == "added" and "\xe2\x9c\x93 " or "") .. "Added order") then SetFavoriteSort("added") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "newest" and "\xe2\x9c\x93 " or "") .. "Newest first") then SetFavoriteSort("newest") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "az" and "\xe2\x9c\x93 " or "") .. "Name A-Z") then SetFavoriteSort("az") end
        if imgui.MenuItem(ctx, (state.favorite_sort == "za" and "\xe2\x9c\x93 " or "") .. "Name Z-A") then SetFavoriteSort("za") end
        imgui.EndPopup(ctx)
    end
    imgui.EndGroup(ctx)

    imgui.Separator(ctx)
end

local function GetRelevantMediaTags()
    local bar = state.media_tag_bar
    local scan = state.library_scan
    local filter_index = state.media_filter_index
    if state.selected_folder_scope
        and bar.scope_catalog_key == state.selected_folder_scope then
        return bar.tags or {}
    end
    if state.media_tag_facets.building then return bar.tags or {} end
    if filter_index.building then
        if bar.catalog_complete then return bar.tags or {} end
        -- The index is authoritative as it grows. Refresh the lightweight tag
        -- catalog periodically so startup never presents an unavailable tag
        -- section, without recounting hundreds of thousands of files.
        local now = r.time_precise()
        if now >= (bar.next_progressive_refresh or 0) then
            local tags = {}
            for name, entries in pairs(filter_index.by_tag or {}) do
                if not TAG_BAR_EXCLUDED[name] then
                    tags[#tags + 1] = {name = name, count = #entries}
                end
            end
            SortMediaTagCatalog(tags, state.media_filters.selected_tags)
            bar.tags = tags
            bar.next_progressive_refresh = now + 0.2
            if MediaFiltersActive() then
                state.force_search_update = true
                state.needs_visible_update = true
            end
        end
        return bar.tags or {}
    end
    -- Never recount every tag synchronously from an interactive folder/tag
    -- click. The global in-memory index already has authoritative counts and
    -- can populate this row immediately. Context-sensitive facet pruning can
    -- be layered back in as a progressive background job.
    if filter_index.ready then
        local cache_key = table.concat({
            "indexed-global",
            tostring(state.media_tag_generation),
            tostring(filter_index.indexed_count or 0),
        }, "|")
        if bar.cache_key == cache_key then return bar.tags end
        local tags = {}
        for name, entries in pairs(filter_index.by_tag or {}) do
            if not TAG_BAR_EXCLUDED[name] then
                tags[#tags + 1] = {name = name, count = #entries}
            end
        end
        SortMediaTagCatalog(tags, state.media_filters.selected_tags)
        bar.cache_key = cache_key
        bar.tags = tags
        bar.catalog_complete = true
        return tags
    end
    local selected_names = {}
    for tag, enabled in pairs(state.media_filters.selected_tags or {}) do
        if enabled and not TAG_BAR_EXCLUDED[tag] then
            selected_names[#selected_names + 1] = tag
        end
    end
    table.sort(selected_names)
    local stable_key = table.concat({
        tostring(state.media_tag_generation),
        tostring(state.selected_folder_scope or ""),
        tostring(state.favorites_mode),
    }, "|")
    local cache_key = table.concat({
        stable_key,
        -- Freeze partial facets during a scan. Recounting all tags every time
        -- the discovered-file total changes becomes increasingly expensive.
        tostring(scan and scan.scanning
            and "scan-in-progress"
            or (scan and scan.discovered_files or 0)),
        tostring(state.search_text or ""),
        table.concat(selected_names, ","),
        tostring(state.media_filters.key_pc or -1),
        QuickTypeSelectionKey(),
    }, "|")
    if bar.cache_key == cache_key then return bar.tags end

    local counts = {}
    -- The result cache has already applied search, key, type, and all
    -- selected tags. Deriving the remaining facets from it removes obsolete
    -- tags without running a second full-tree filter pass.
    for _, node in ipairs(GetCachedSearchResults()) do
        local seen = {}
        for _, tag in ipairs(GetMediaUserTags(node.path) or {}) do
            if not TAG_BAR_EXCLUDED[tag] and not seen[tag] then
                counts[tag] = (counts[tag] or 0) + 1
                seen[tag] = true
            end
        end
        for _, generated in ipairs(EnsureGeneratedTags(node)) do
            local tag = generated.name
            if tag and not TAG_BAR_EXCLUDED[tag] and not seen[tag] then
                counts[tag] = (counts[tag] or 0) + 1
                seen[tag] = true
            end
        end
    end
    for _, name in ipairs(selected_names) do
        counts[name] = math.max(1, counts[name] or 0)
    end

    local tags = {}
    for name, count in pairs(counts) do
        tags[#tags + 1] = {name = name, count = count}
    end
    if bar.stable_key ~= stable_key or not bar.stable_tags then
        SortMediaTagCatalog(tags, state.media_filters.selected_tags)
        bar.stable_key = stable_key
        bar.stable_order = {}
        bar.stable_tags = {}
        for index, tag in ipairs(tags) do
            bar.stable_order[tag.name] = index
            bar.stable_tags[index] = tag.name
        end
    else
        local stable = {}
        local included = {}
        for _, name in ipairs(bar.stable_tags) do
            if (counts[name] or 0) > 0
                or state.media_filters.selected_tags[name] == true then
                stable[#stable + 1] = {
                    name = name,
                    count = counts[name] or 0,
                }
                included[name] = true
            end
        end
        local additions = {}
        for name, count in pairs(counts) do
            if not included[name] then
                additions[#additions + 1] = {name = name, count = count}
            end
        end
        SortMediaTagCatalog(additions, state.media_filters.selected_tags)
        for _, tag in ipairs(additions) do
            stable[#stable + 1] = tag
            bar.stable_tags[#bar.stable_tags + 1] = tag.name
        end
        tags = stable
    end
    bar.cache_key, bar.tags = cache_key, tags
    return tags
end

local MEDIA_KEY_FILTER_NAMES = {
    "Key", "C", "C#", "D", "D#", "E", "F",
    "F#", "G", "G#", "A", "A#", "B"
}

local function GetMediaTagLayoutRows(tags, available_width)
    local bar = state.media_tag_bar
    local width_key = math.max(1, math.floor(available_width or 1))
    local font_key = tostring(state.font_built_name or "") .. "|"
        .. tostring(state.font_built_size or state.theme.font_size)
    if bar.layout_source == tags
        and bar.layout_count == #tags
        and bar.layout_width == width_key
        and bar.layout_font_key == font_key then
        return bar.layout_rows or {}
    end

    local rows = {}
    local row_start = 1
    local used = 0
    for index, tag in ipairs(tags) do
        local priority_label = MEDIA_PRIORITY_TAG_LABELS[tag.name]
        -- Reserve enough text space for the separately drawn accent star.
        -- Two spaces allowed the star to overlap the first letter at larger
        -- UI/font scales.
        local display_name = priority_label and ("    " .. priority_label)
            or tag.name
        if tag._media_button_font_key ~= font_key then
            tag._media_button_font_key = font_key
            tag._media_button_width =
                select(1, imgui.CalcTextSize(ctx, display_name)) + 10
        end
        if not tag._media_button_label or tag._media_button_display ~= display_name then
            tag._media_button_display = display_name
            tag._media_button_label =
                display_name .. "##media_tag_" .. tag.name
        end
        local button_width = tag._media_button_width
        if used > 0 and used + button_width > width_key then
            rows[#rows + 1] = {first = row_start, last = index - 1}
            row_start = index
            used = 0
        end
        used = used + button_width + (used > 0 and 3 or 0)
    end
    if #tags > 0 then
        rows[#rows + 1] = {first = row_start, last = #tags}
    end
    bar.layout_source = tags
    bar.layout_count = #tags
    bar.layout_width = width_key
    bar.layout_font_key = font_key
    bar.layout_rows = rows
    return rows
end

local function DrawMediaTagButton(
    tag, selected_tags, database_mode, bar, tag_accent)
    local selected = selected_tags[tag.name] == true
    local broad = TAG_BROAD_PRIORITY[tag.name] ~= nil
        or MEDIA_PRIORITY_TAGS[tag.name] ~= nil
    local pushed_colors = 0
    local pushed_border = false
    if broad then
        imgui.PushStyleColor(ctx, imgui.Col_Button,
            selected and tag_accent
                or ((tag_accent & 0xFFFFFF00) | 0x20))
        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
            (tag_accent & 0xFFFFFF00) | 0x48)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
            (tag_accent & 0xFFFFFF00) | 0x68)
        imgui.PushStyleColor(ctx, imgui.Col_Border,
            (tag_accent & 0xFFFFFF00) | 0x90)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FrameBorderSize, 1)
        pushed_colors = 4
        pushed_border = true
    elseif selected then
        imgui.PushStyleColor(ctx, imgui.Col_Button, tag_accent)
        pushed_colors = 1
    end
    local clicked = imgui.SmallButton(ctx, tag._media_button_label)
    if MEDIA_PRIORITY_TAGS[tag.name] then
        local min_x, min_y = imgui.GetItemRectMin(ctx)
        local _, max_y = imgui.GetItemRectMax(ctx)
        local _, star_height = imgui.CalcTextSize(ctx, MEDIA_PRIORITY_TAG_STAR)
        local star_y = min_y + ((max_y - min_y - star_height) * 0.5)
        imgui.DrawList_AddText(imgui.GetWindowDrawList(ctx),
            min_x + 4, star_y, MEDIA_PRIORITY_TAG_STAR_COLOR,
            MEDIA_PRIORITY_TAG_STAR)
    end
    if clicked then
        if database_mode then
            ToggleCanonicalBrowserTag(tag.name)
        else
            selected_tags[tag.name] = selected and nil or true
            state.media_filters.tag_text = ""
            state.force_search_update = true
            state.needs_visible_update = true
            bar.cache_key = nil
            bar.stable_key = nil
        end
    end
    if pushed_border then imgui.PopStyleVar(ctx) end
    if pushed_colors > 0 then imgui.PopStyleColor(ctx, pushed_colors) end
end

-- Native button capture keeps divider gestures separate from deferred row clicks.
-- Store only on release, so dragging does not write settings every frame.
function DrawMediaPanelDivider(id, value, minimum, maximum, direction, setting, panel_x, panel_width)
    if panel_x then imgui.SetCursorPosX(ctx, panel_x) end
    local width = math.max(1, panel_width or select(1, imgui.GetContentRegionAvail(ctx)))
    local accent = state.resolved_theme and state.resolved_theme.accent
        or state.theme.colors.accent
    imgui.PushStyleColor(ctx, imgui.Col_Button, (accent & 0xFFFFFF00) | 0x18)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered, (accent & 0xFFFFFF00) | 0x60)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive, (accent & 0xFFFFFF00) | 0x90)
    imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 0, 0)
    imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 0, 1)
    imgui.Button(ctx, id, width, 5)
    imgui.PopStyleVar(ctx, 2)
    imgui.PopStyleColor(ctx, 3)
    local hovered = imgui.IsItemHovered(ctx)
    local active = imgui.IsItemActive(ctx)
    local x1, y1 = imgui.GetItemRectMin(ctx)
    local x2, y2 = imgui.GetItemRectMax(ctx)
    local center_x, center_y = (x1 + x2) * 0.5, (y1 + y2) * 0.5
    local text_color = state.resolved_theme and state.resolved_theme.text
        or state.theme.colors.text
    local grip_color = (hovered or active) and accent
        or ((text_color & 0xFFFFFF00) | 0xB0)
    local draw = imgui.GetWindowDrawList(ctx)
    local grip_half = math.min(18, width * 0.25)
    for offset = -1, 1, 2 do
        imgui.DrawList_AddLine(draw, center_x - grip_half, center_y + offset,
            center_x + grip_half, center_y + offset, grip_color, 1.5)
    end
    state.media_panel_drag = state.media_panel_drag or {}
    local drag = state.media_panel_drag
    if active then
        CancelPendingMediaRowActivation()
        local _, mouse_y = imgui.GetMousePos(ctx)
        if drag.id ~= id then
            drag.id, drag.start_y, drag.start_value = id, mouse_y, value
        end
        value = math.max(minimum, math.min(maximum,
            drag.start_value + (mouse_y - drag.start_y) * direction))
        drag.value = value
    elseif drag.id == id then
        value = math.max(minimum, math.min(maximum, drag.value or value))
        r.SetExtState(EXT_SECTION, setting, tostring(value), true)
        drag.id = nil
    end
    if hovered or active then
        if imgui.SetMouseCursor and imgui.MouseCursor_ResizeNS then
            imgui.SetMouseCursor(ctx, imgui.MouseCursor_ResizeNS)
        end
        if hovered and not active then imgui.SetTooltip(ctx, "Drag to resize") end
    end
    return value
end

function DrawMediaTagBar()
    local bar = state.media_tag_bar
    local database_mode = state.database_startup_test.enabled
    local canonical = state.canonical_browser
    local accent = state.resolved_theme and state.resolved_theme.accent
        or state.theme.colors.accent
    local normal_text = state.resolved_theme and state.resolved_theme.text
        or state.theme.colors.text
    local icon_size = 26

    imgui.PushStyleColor(ctx, imgui.Col_Text, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_Button, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
        (accent & 0xFFFFFF00) | 0x24)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
        (accent & 0xFFFFFF00) | 0x40)
    imgui.Button(ctx, "##media_tag_bar", icon_size, icon_size)
    imgui.PopStyleColor(ctx, 4)
    local tag_min_x, tag_min_y = imgui.GetItemRectMin(ctx)
    local tag_max_x, tag_max_y = imgui.GetItemRectMax(ctx)
    local tag_hovered = imgui.IsItemHovered(ctx)
    if imgui.IsItemClicked(ctx, 0) then
        bar.open = not bar.open
        r.SetExtState(EXT_SECTION, "media_tag_bar_open",
            bar.open and "1" or "0", true)
        if bar.open and not database_mode and state.selected_folder_scope then
            local target = state.cursor_type == "folder"
                and state.cursor_path or nil
            if target then
                state.pending_tag_facet_node = nil
                state.pending_tag_facet_time = r.time_precise() + 0.05
                state.media_tag_facets.building = false
                for _, tree in ipairs(state.folder_tree or {}) do
                    local function FindNode(node)
                        if node.path == target then return node end
                        for _, child in ipairs(node.children or {}) do
                            local found = FindNode(child)
                            if found then return found end
                        end
                    end
                    local found = FindNode(tree)
                    if found then
                        state.pending_tag_facet_node = found
                        break
                    end
                end
            end
        end
    end
    local tag_draw = imgui.GetWindowDrawList(ctx)
    if tag_hovered or bar.open then
        imgui.DrawList_AddRectFilled(
            tag_draw, tag_min_x, tag_min_y, tag_max_x, tag_max_y,
            (accent & 0xFFFFFF00) | (tag_hovered and 0x24 or 0x14), 3)
    end
    local tx, ty = tag_min_x + 5, tag_min_y + 7
    local tag_color = bar.open and accent or normal_text
    imgui.DrawList_AddLine(tag_draw, tx, ty, tx + 9, ty, tag_color, 1.5)
    imgui.DrawList_AddLine(tag_draw, tx + 9, ty, tx + 15, ty + 6, tag_color, 1.5)
    imgui.DrawList_AddLine(tag_draw, tx + 15, ty + 6, tx + 9, ty + 12, tag_color, 1.5)
    imgui.DrawList_AddLine(tag_draw, tx + 9, ty + 12, tx, ty + 12, tag_color, 1.5)
    imgui.DrawList_AddLine(tag_draw, tx, ty + 12, tx, ty, tag_color, 1.5)
    imgui.DrawList_AddCircleFilled(tag_draw, tx + 3, ty + 3, 1.5, tag_color)
    if tag_hovered then
        imgui.SetTooltip(ctx, bar.open and "Collapse tags" or "Expand tags")
    end
    local selected_tags = database_mode
        and canonical.selected_tags or state.media_filters.selected_tags

    if database_mode and bar.open and canonical.tag_catalog_refreshing
        and not state.canonical_paging.active
        and not canonical.deferred_request
        and canonical.pending_tag_folder_id == nil then
        -- Last-resort scheduler invariant: every visible refreshing state must
        -- own either an active, deferred, or pending catalog request. A fast
        -- sequence of tag clicks used to leave none of the three, displaying
        -- the previous scope indefinitely until the sequence was repeated.
        canonical.pending_tag_folder_id =
            canonical.current_folder_id or false
        canonical.pending_tag_time = 0
    end

    if database_mode and state.favorites_mode and bar.open
        and CanonicalFavoriteFacetScopeActive() then
        local tag_scope_key = table.concat({
            "favorites",
            tostring(canonical.current_folder_id or ""),
            tostring(canonical.collection_scope_key or ""),
            tostring(canonical.smart_mode or ""),
            tostring(canonical.collection_key or ""),
        }, "|")
        local active_tag_request = state.canonical_paging.browser_request
            and state.canonical_paging.browser_request.mode == "tag_catalog"
        if bar.canonical_scope_key ~= tag_scope_key and not active_tag_request
            and not state.canonical_paging.active then
            bar.canonical_scope_key = tag_scope_key
            -- Tags are secondary UI data. Queue them after the foreground
            -- Favorites page has had a chance to render so opening a folder
            -- or pressing Random is never held behind a facet query.
            canonical.pending_tag_folder_id =
                canonical.current_folder_id or false
            canonical.pending_tag_time = r.time_precise() + 0.35
        end
    end

    -- Keep clearing available even when the scrollable tag list is not at
    -- its first row.
    imgui.SameLine(ctx)
    imgui.PushStyleColor(ctx, imgui.Col_Text, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_Button, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
        (accent & 0xFFFFFF00) | 0x24)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
        (accent & 0xFFFFFF00) | 0x40)
    imgui.Button(ctx, "##clear_selected_tags", icon_size, icon_size)
    imgui.PopStyleColor(ctx, 4)
    local trash_min_x, trash_min_y = imgui.GetItemRectMin(ctx)
    local trash_max_x, trash_max_y = imgui.GetItemRectMax(ctx)
    local trash_hovered = imgui.IsItemHovered(ctx)
    local has_selected_tags = next(selected_tags) ~= nil
    if imgui.IsItemClicked(ctx, 0) and has_selected_tags then
        if database_mode then
            ClearCanonicalBrowserTags()
            selected_tags = canonical.selected_tags
        else
            state.media_filters.selected_tags = {}
            selected_tags = state.media_filters.selected_tags
            state.media_filters.tag_text = ""
            state.force_search_update = true
            state.needs_visible_update = true
            bar.cache_key = nil
            bar.stable_key = nil
        end
    end
    local trash_draw = imgui.GetWindowDrawList(ctx)
    local trash_color = has_selected_tags and normal_text
        or ((normal_text & 0xFFFFFF00) | 0x48)
    if trash_hovered and has_selected_tags then
        imgui.DrawList_AddRectFilled(
            trash_draw, trash_min_x, trash_min_y, trash_max_x, trash_max_y,
            (accent & 0xFFFFFF00) | 0x24, 3)
    end
    local trash_cx = (trash_min_x + trash_max_x) * 0.5
    local trash_top = trash_min_y + 6
    imgui.DrawList_AddLine(trash_draw,
        trash_cx - 6, trash_top + 3, trash_cx + 6, trash_top + 3,
        trash_color, 1.5)
    imgui.DrawList_AddLine(trash_draw,
        trash_cx - 3, trash_top + 1, trash_cx + 3, trash_top + 1,
        trash_color, 1.5)
    imgui.DrawList_AddRect(trash_draw,
        trash_cx - 5, trash_top + 5, trash_cx + 5, trash_top + 14,
        trash_color, 1, 0, 1.5)
    imgui.DrawList_AddLine(trash_draw,
        trash_cx - 2, trash_top + 7, trash_cx - 2, trash_top + 12,
        trash_color, 1)
    imgui.DrawList_AddLine(trash_draw,
        trash_cx + 2, trash_top + 7, trash_cx + 2, trash_top + 12,
        trash_color, 1)
    if trash_hovered then
        imgui.SetTooltip(ctx, has_selected_tags
            and "Clear selected tags" or "No selected tags")
    end

    imgui.SameLine(ctx)
    imgui.SetNextItemWidth(ctx, 56)
    local key_pc = database_mode
        and (canonical.key_pc or -1) or (state.media_filters.key_pc or -1)
    if imgui.BeginCombo(ctx, "##media_key_filter",
        MEDIA_KEY_FILTER_NAMES[key_pc + 2]) then
        for value = -1, 11 do
            if imgui.Selectable(
                ctx, MEDIA_KEY_FILTER_NAMES[value + 2], key_pc == value) then
                if database_mode then
                    if value >= 0 then
                        CaptureCanonicalAccordionReturnState()
                    end
                    canonical.key_pc = value
                    ApplyCanonicalStructuredFilterChange()
                else
                    state.media_filters.key_pc = value
                    state.force_search_update = true
                    state.needs_visible_update = true
                    bar.cache_key = nil
                    bar.stable_key = nil
                end
            end
        end
        imgui.EndCombo(ctx)
    end

    local function QuickFilterIcon(kind, tooltip)
        local quick_types = database_mode
            and canonical.selected_classes
            or (state.media_filters.quick_types or {})
        local selected = (kind == "all" and next(quick_types) == nil)
            or quick_types[kind] == true
        imgui.PushStyleColor(ctx, imgui.Col_Text, 0x00000000)
        imgui.PushStyleColor(ctx, imgui.Col_Button, 0x00000000)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
            (accent & 0xFFFFFF00) | 0x24)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
            (accent & 0xFFFFFF00) | 0x40)
        imgui.Button(ctx, "##quick_" .. kind, icon_size, icon_size)
        imgui.PopStyleColor(ctx, 4)
        local min_x, min_y = imgui.GetItemRectMin(ctx)
        local max_x, max_y = imgui.GetItemRectMax(ctx)
        local hovered = imgui.IsItemHovered(ctx)
        if imgui.IsItemClicked(ctx, 0) then
            if database_mode and kind ~= "all" then
                CaptureCanonicalAccordionReturnState()
            end
            if kind == "all" then
                if database_mode then
                    canonical.selected_classes = {}
                    quick_types = canonical.selected_classes
                else
                    state.media_filters.quick_types = {}
                    quick_types = state.media_filters.quick_types
                end
            else
                if selected then
                    quick_types[kind] = nil
                else
                    quick_types[kind] = true
                end
                local every_type_selected = true
                for _, category in ipairs({
                    "loop", "one-shot", "midi", "other"
                }) do
                    if not quick_types[category] then
                        every_type_selected = false
                        break
                    end
                end
                if every_type_selected then
                    if database_mode then
                        canonical.selected_classes = {}
                        quick_types = canonical.selected_classes
                    else
                        state.media_filters.quick_types = {}
                        quick_types = state.media_filters.quick_types
                    end
                end
            end
            if database_mode then
                ApplyCanonicalStructuredFilterChange()
            else
                state.force_search_update = true
                state.needs_visible_update = true
                bar.cache_key = nil
            end
        end
        local draw = imgui.GetWindowDrawList(ctx)
        local color = selected and accent or normal_text
        if selected or hovered then
            imgui.DrawList_AddRectFilled(
                draw, min_x, min_y, max_x, max_y,
                (accent & 0xFFFFFF00) | (hovered and 0x24 or 0x14), 3)
        end
        local cx, cy = (min_x + max_x) * 0.5, (min_y + max_y) * 0.5
        if kind == "all" then
            imgui.DrawList_AddCircle(draw, cx, cy, 8, color, 0, 1.3)
            imgui.DrawList_AddLine(
                draw, cx - 8, cy, cx + 8, cy, color, 1)
            imgui.DrawList_AddLine(
                draw, cx, cy - 8, cx, cy + 8, color, 1)
            imgui.DrawList_AddCircle(
                draw, cx, cy, 4, color, 0, 1)
        elseif kind == "loop" then
            imgui.DrawList_AddRect(draw,
                cx - 8, cy - 8, cx + 8, cy + 8, color, 1, 0, 1.2)
            imgui.DrawList_AddLine(
                draw, cx - 6, cy, cx - 3, cy - 4, color, 1.3)
            imgui.DrawList_AddLine(
                draw, cx - 3, cy - 4, cx, cy + 4, color, 1.3)
            imgui.DrawList_AddLine(
                draw, cx, cy + 4, cx + 3, cy - 3, color, 1.3)
            imgui.DrawList_AddLine(
                draw, cx + 3, cy - 3, cx + 6, cy, color, 1.3)
        elseif kind == "midi" then
            imgui.DrawList_AddRect(draw,
                cx - 9, cy - 7, cx + 9, cy + 7, color, 1, 0, 1.2)
            for i = 1, 5 do
                local x = cx - 9 + i * 3
                imgui.DrawList_AddLine(draw, x, cy - 7, x, cy + 7, color, 1)
            end
            imgui.DrawList_AddRectFilled(
                draw, cx - 6.5, cy - 7, cx - 3.5, cy, color)
            imgui.DrawList_AddRectFilled(
                draw, cx - 0.5, cy - 7, cx + 2.5, cy, color)
            imgui.DrawList_AddRectFilled(
                draw, cx + 5.5, cy - 7, cx + 8.5, cy, color)
        elseif kind == "one-shot" then
            imgui.DrawList_AddCircle(draw, cx, cy, 8, color, 0, 1.2)
            imgui.DrawList_AddCircle(draw, cx, cy, 4, color, 0, 1.2)
            imgui.DrawList_AddCircleFilled(draw, cx, cy, 1.8, color)
        else
            for row = 0, 1 do
                for col = 0, 1 do
                    imgui.DrawList_AddRectFilled(draw,
                        cx - 7 + col * 8, cy - 7 + row * 8,
                        cx - 1 + col * 8, cy - 1 + row * 8, color, 1)
                end
            end
        end
        if hovered then imgui.SetTooltip(ctx, tooltip) end
    end

    imgui.SameLine(ctx)
    local quick_start = imgui.GetCursorPosX(ctx)
    local quick_available = select(1, imgui.GetContentRegionAvail(ctx))
    local quick_width = icon_size * 5 + 16
    if quick_available > quick_width then
        imgui.SetCursorPosX(ctx, quick_start + quick_available - quick_width)
    end
    imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 4, 4)
    QuickFilterIcon("all", "All files")
    imgui.SameLine(ctx)
    QuickFilterIcon("loop", "Audio loops")
    imgui.SameLine(ctx)
    QuickFilterIcon("one-shot", "One-shots")
    imgui.SameLine(ctx)
    QuickFilterIcon("midi", "MIDI files")
    imgui.SameLine(ctx)
    QuickFilterIcon("other", "Other audio")
    imgui.PopStyleVar(ctx)

    if not bar.open then
        imgui.Separator(ctx)
        return
    end

    local tags = database_mode
        and (canonical.available_tags or {}) or GetRelevantMediaTags()
    local default_height = imgui.GetTextLineHeightWithSpacing(ctx) * 5 + 8
    local available_height = select(2, imgui.GetContentRegionAvail(ctx))
    local tag_minimum = imgui.GetTextLineHeightWithSpacing(ctx) + 8
    local tag_maximum = math.max(tag_minimum, available_height - 220)
    local tag_area_height = math.max(tag_minimum,
        math.min(tag_maximum, bar.height or default_height))
    local tag_panel_x = imgui.GetCursorPosX(ctx)
    -- ContentRegionAvail can retain a wider content extent after narrowing
    -- the window. Bound this child to the current visible window instead.
    local visible_width = select(1, imgui.GetWindowSize(ctx))
    local tag_panel_width = math.max(1, math.min(
        select(1, imgui.GetContentRegionAvail(ctx)),
        visible_width - tag_panel_x - math.max(8, tag_panel_x)))
    local tag_panel_left, tag_panel_right
    imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 0, 1)
    if imgui.BeginChild(
        ctx, "##media_tag_facets", tag_panel_width, tag_area_height, 0, 0) then
        local child_x = select(1, imgui.GetWindowPos(ctx))
        local child_width = select(1, imgui.GetWindowSize(ctx))
        tag_panel_left, tag_panel_right = child_x, child_x + child_width
        local tag_line_width = select(1, imgui.GetContentRegionAvail(ctx))
        if state.media_tag_facets.building then
            imgui.TextDisabled(ctx, string.format(
                "Updating folder tags... %d files",
                state.media_tag_facets.processed or 0))
        end
        if #tags == 0 then
            if database_mode and state.favorites_mode
                and not CanonicalFavoriteFacetScopeActive() then
                -- Favorites-wide tags would grow with the whole collection.
                -- The empty tag area is intentional until a physical favorite
                -- folder supplies its precomputed subtree catalog.
            elseif database_mode and not state.database.folder_tag_counts_ready then
                imgui.TextDisabled(
                    ctx, "Folder tags will be indexed on the next Update")
            else
                imgui.TextDisabled(ctx, "No tags available")
            end
        else
        imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 4, 1)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FrameRounding, 0)
        imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 3, 2)
        local layout_rows = GetMediaTagLayoutRows(tags, tag_line_width)
        local tag_accent = state.resolved_theme
            and state.resolved_theme.accent or state.theme.colors.accent
        if not bar.layout_clipper then
            bar.layout_clipper = imgui.CreateListClipper(ctx)
            if imgui.Attach then imgui.Attach(ctx, bar.layout_clipper) end
        end
        local clipper_ok = pcall(
            imgui.ListClipper_Begin, bar.layout_clipper, #layout_rows)
        if clipper_ok then
            while imgui.ListClipper_Step(bar.layout_clipper) do
                local first_row, last_row =
                    imgui.ListClipper_GetDisplayRange(bar.layout_clipper)
                for row_index = first_row + 1, last_row do
                    local layout_row = layout_rows[row_index]
                    for tag_index = layout_row.first, layout_row.last do
                        if tag_index > layout_row.first then
                            imgui.SameLine(ctx)
                        end
                        DrawMediaTagButton(
                            tags[tag_index], selected_tags,
                            database_mode, bar, tag_accent)
                    end
                end
            end
        else
            bar.layout_clipper = nil
            for _, layout_row in ipairs(layout_rows) do
                for tag_index = layout_row.first, layout_row.last do
                    if tag_index > layout_row.first then imgui.SameLine(ctx) end
                    DrawMediaTagButton(
                        tags[tag_index], selected_tags,
                        database_mode, bar, tag_accent)
                end
            end
        end
        imgui.PopStyleVar(ctx, 3)
        end
        imgui.EndChild(ctx)
    end
    imgui.PopStyleVar(ctx)
    -- Use the tag child's actual bounds, not a content width affected by
    -- other controls or horizontal scrolling in the parent window.
    if tag_panel_left then
        local screen_x = select(1, imgui.GetCursorScreenPos(ctx))
        tag_panel_x = imgui.GetCursorPosX(ctx) + tag_panel_left - screen_x
        tag_panel_width = tag_panel_right - tag_panel_left
    end
    bar.height = DrawMediaPanelDivider("##tag_panel_resize", tag_area_height,
        tag_minimum, tag_maximum, 1, "media_tag_height", tag_panel_x, tag_panel_width)
end

function RevealFileInExplorer(filepath)
    if not FileExists(filepath) then return false end
    local os_name = r.GetOS() or ""
    local normalized = filepath
    if os_name:match("^Win") then
        normalized = filepath:gsub("/", "\\")
        if r.CF_LocateInExplorer then
            local ok, result = pcall(r.CF_LocateInExplorer, normalized)
            if ok and result then return true end
        end
        if r.BR_Win32_ShellExecute then
            local windows_dir = os.getenv("WINDIR") or "C:\\Windows"
            local explorer = windows_dir:gsub("[/\\]+$", "") .. "\\explorer.exe"
            local ok, result = pcall(
                r.BR_Win32_ShellExecute,
                "open",
                explorer,
                '/select,"' .. normalized .. '"',
                windows_dir,
                1
            )
            if ok and type(result) == "number" and result > 32 then return true end
        end
    end

    if not os_name:match("^Win") and r.CF_LocateInExplorer then
        local ok, result = pcall(r.CF_LocateInExplorer, normalized)
        if ok and result then return true end
    end

    local folder = normalized:match("^(.*)[/\\][^/\\]+$") or normalized
    if r.CF_ShellExecute then
        local ok, result = pcall(r.CF_ShellExecute, folder)
        if ok and result then return true end
    end
    return false
end

function RevealFolderInExplorer(folderpath)
    if not folderpath or folderpath == "" then return false end
    local normalized = folderpath
    local os_name = r.GetOS() or ""
    if os_name:match("^Win") then normalized = folderpath:gsub("/", "\\") end
    if r.CF_ShellExecute then
        local ok, result = pcall(r.CF_ShellExecute, normalized)
        if ok and result then return true end
    end
    if os_name:match("^Win") and r.BR_Win32_ShellExecute then
        local windows_dir = os.getenv("WINDIR") or "C:\\Windows"
        local explorer = windows_dir:gsub("[/\\]+$", "") .. "\\explorer.exe"
        local ok, result = pcall(
            r.BR_Win32_ShellExecute,
            "open", explorer, '"' .. normalized .. '"', windows_dir, 1)
        if ok and type(result) == "number" and result > 32 then return true end
    end
    return false
end

function DrawRevealFolderInExplorerMenuItem(node)
    if not node or node.is_collection or not node.path then return end
    if imgui.MenuItem(ctx, "Reveal in System File Browser") then
        if not RevealFolderInExplorer(node.path) then
            r.ShowMessageBox(
                "The system file browser could not open this folder:\n\n"
                    .. node.path,
                "ReaBrowse",
                0
            )
        end
    end
end

function OpenReaBrowseDataLocation()
    local folder = GetReaBrowseDataDirectory()
    if r.CF_ShellExecute then
        local ok, result = pcall(r.CF_ShellExecute, folder)
        if ok and result then return true end
    end
    local os_name = r.GetOS() or ""
    if os_name:match("^Win") and r.BR_Win32_ShellExecute then
        local windows_dir = os.getenv("WINDIR") or "C:\\Windows"
        local explorer = windows_dir:gsub("[/\\\\]+$", "") .. "\\explorer.exe"
        local normalized = folder:gsub("/", "\\")
        local ok, result = pcall(
            r.BR_Win32_ShellExecute,
            "open", explorer, '"' .. normalized .. '"', windows_dir, 1)
        if ok and type(result) == "number" and result > 32 then return true end
    end
    return false
end

function RevealFileInLibrary(filepath)
    if not filepath or filepath == "" then return false end
    if not state.database_startup_test.enabled
        or state.database.backend ~= "sqlite"
        or not FileExists(GetCanonicalDatabasePath()) then
        state.canonical_browser.status =
            "Reveal in Library requires the SQLite library database."
        return false
    end

    local target_norm = NormalizeFavoritePath(filepath)
    local target_sql = SQLQuote(target_norm)
    local full_folder_path =
        "roots.display_path||CASE WHEN folders.relative_path='' "
        .. "THEN '' ELSE '/'||folders.relative_path END"
    -- One indexed, explicit-navigation query returns the exact folder chain
    -- and file. This avoids paging through every sibling merely to discover
    -- a target that may sort beyond the first hundred rows.
    local sql =
        "WITH target(id) AS (SELECT id FROM files WHERE "
        .. "canonical_path_norm=" .. target_sql
        .. " AND missing=0 LIMIT 1),location(folder_id,root_id,relative_path_norm) "
        .. "AS (SELECT folder_files.folder_id,folders.root_id,"
        .. "folders.relative_path_norm FROM target JOIN folder_files ON "
        .. "folder_files.file_id=target.id JOIN folders ON folders.id="
        .. "folder_files.folder_id JOIN roots ON roots.id=folders.root_id "
        .. "WHERE folder_files.missing=0 AND folders.missing=0 "
        .. "AND roots.enabled=1 ORDER BY length(roots.path_norm) DESC,"
        .. "length(folders.relative_path_norm) DESC LIMIT 1),"
        .. "ancestor_rows AS (SELECT folders.id,folders.parent_id,folders.name,"
        .. full_folder_path .. " AS full_path,folders.relative_path_norm "
        .. "FROM location JOIN folders ON folders.root_id=location.root_id "
        .. "JOIN roots ON roots.id=folders.root_id WHERE folders.missing=0 AND ("
        .. "folders.relative_path_norm='' OR folders.relative_path_norm="
        .. "location.relative_path_norm OR (length(folders.relative_path_norm)"
        .. "<length(location.relative_path_norm) AND substr("
        .. "location.relative_path_norm,1,length(folders.relative_path_norm))="
        .. "folders.relative_path_norm AND substr(location.relative_path_norm,"
        .. "length(folders.relative_path_norm)+1,1)='/'))) "
        .. "SELECT 'D'||char(9)||id||char(9)||COALESCE(parent_id,0)||char(9)||"
        .. "hex(name)||char(9)||hex(full_path)||char(9)||hex('')||char(9)||"
        .. "hex('') FROM ancestor_rows ORDER BY length(relative_path_norm);"
        .. "SELECT 'F'||char(9)||files.id||char(9)||folders.id||char(9)||"
        .. "hex(files.name)||char(9)||hex(files.canonical_path)||char(9)||"
        .. "hex(COALESCE(files.media_type,''))||char(9)||"
        .. "hex(COALESCE(NULLIF(files.classification,''),'other')) FROM files "
        .. "JOIN folder_files ON folder_files.file_id=files.id "
        .. "JOIN folders ON folders.id=folder_files.folder_id "
        .. "JOIN roots ON roots.id=folders.root_id WHERE "
        .. "files.canonical_path_norm=" .. target_sql
        .. " AND files.missing=0 AND folder_files.missing=0 "
        .. "AND folders.missing=0 AND roots.enabled=1 "
        .. "ORDER BY length(roots.path_norm) DESC,"
        .. "length(folders.relative_path_norm) DESC LIMIT 1;"

    local output, query_error = QueryDatabaseScalarAtPath(
        GetCanonicalDatabasePath(), sql)
    if not output or output == "" then
        state.canonical_browser.status = query_error
            or "The file is not present in the active Library."
        return false
    end

    local folder_rows, file_row = {}, nil
    for line in output:gmatch("[^\r\n]+") do
        local kind, item_id, parent_id, name_hex, path_hex,
            media_hex, class_hex = line:match(
                "^([DF])\t(%d+)\t(%d+)\t(%x*)\t(%x*)\t(%x*)\t(%x*)$")
        if kind == "D" then
            folder_rows[#folder_rows + 1] = {
                id = tonumber(item_id),
                parent_id = tonumber(parent_id) or 0,
                name = DecodeSQLHex(name_hex),
                path = DecodeSQLHex(path_hex),
            }
        elseif kind == "F" then
            file_row = {
                id = tonumber(item_id),
                folder_id = tonumber(parent_id),
                name = DecodeSQLHex(name_hex),
                path = DecodeSQLHex(path_hex),
                media_type = DecodeSQLHex(media_hex),
                classification = DecodeSQLHex(class_hex),
            }
        end
    end
    if not file_row or #folder_rows == 0 then
        state.canonical_browser.status =
            "The file's Library folder could not be resolved."
        return false
    end

    local function FindTreeNode(nodes, folder_id, path)
        local normalized = NormalizeFavoritePath(path or "")
        for _, candidate in ipairs(nodes or {}) do
            if candidate._canonical_folder_id == folder_id
                or NormalizeFavoritePath(candidate.path) == normalized then
                return candidate
            end
            local found = FindTreeNode(candidate.children, folder_id, path)
            if found then return found end
        end
        return nil
    end
    local function ContainsNode(nodes, wanted)
        for _, candidate in ipairs(nodes or {}) do
            if candidate == wanted then return true end
        end
        return false
    end

    local nodes_by_id = {}
    for _, row in ipairs(folder_rows) do
        local parent = row.parent_id > 0 and nodes_by_id[row.parent_id] or nil
        local node = FindTreeNode(state.folder_tree, row.id, row.path)
        if not node then
            node = CanonicalAccordionNode({
                kind = parent and "D" or "R",
                name = row.name,
                path = row.path,
                folder_id = row.id,
            }, parent)
        end
        node._canonical_folder_id = row.id
        node.name = row.name
        node.name_lower = (row.name or ""):lower()
        node.path = row.path
        if parent then
            node.parent = parent
            node.depth = (parent.depth or 0) + 1
            if not ContainsNode(parent.children, node) then
                parent.children[#parent.children + 1] = node
            end
        elseif not ContainsNode(state.folder_tree, node) then
            state.folder_tree[#state.folder_tree + 1] = node
        end
        nodes_by_id[row.id] = node
    end

    local parent = nodes_by_id[file_row.folder_id]
    if not parent then
        state.canonical_browser.status =
            "The file's parent folder could not be resolved."
        return false
    end
    local file_node = nil
    for _, candidate in ipairs(parent.files or {}) do
        if NormalizeFavoritePath(candidate.path) == target_norm then
            file_node = candidate
            break
        end
    end
    if not file_node then
        file_node = CanonicalAccordionNode({
            kind = "F",
            id = file_row.id,
            name = file_row.name,
            path = file_row.path,
            media_type = file_row.media_type,
            classification = file_row.classification,
        }, parent)
        parent.files[#parent.files + 1] = file_node
    end

    -- The folder's first canonical page may still be loading. Keep the exact
    -- reveal target through that response so replacing the bounded page cannot
    -- discard the row before the accordion has a chance to focus it.
    -- Preserve the exact target until any in-flight/replacement page for this
    -- folder has been applied. Limiting this handoff to folders currently marked
    -- loading allowed a slightly later page response to discard a revealed row.
    local canonical_reveal = {
        folder_id = parent._canonical_folder_id,
        folder_path = parent.path,
        path = target_norm,
        node = file_node,
    }

    -- Reset search/Favorites/random state only after the exact chain has been
    -- installed, so HomeCanonicalBrowser cannot start a competing root load.
    HomeCanonicalBrowser()
    state.canonical_reveal = canonical_reveal
    state.active_main_tab = "media"
    for _, row in ipairs(folder_rows) do
        local node = nodes_by_id[row.id]
        if node then state.open_folders[node.path] = true end
    end
    SetCursorToFolderNode(parent, false)
    SetCursorToFileNode(file_node, true)
    state.needs_visible_update = true
    state.canonical_browser.status =
        "Revealed in Library: " .. (file_row.name or GetFileName(filepath))
    return true
end

function ApplyLoadedMediaTagEditorData(editor, batch_data)
    local union, seen_union = {}, {}
    editor.detected_tags = {}
    editor.detected_by_path = {}
    editor.suppressed_tags = {}
    editor.excluded_by_path = {}
    local seen_detected, seen_suppressed = {}, {}
    for _, path in ipairs(editor.paths or {}) do
        local path_norm = NormalizeFavoritePath(path)
        local loaded = batch_data and batch_data[path_norm]
            or {user = {}, detected = {}, excluded = {}}
        state.media_user_tags[path_norm] = {
            path = path,
            tags = loaded.user,
            excluded = loaded.excluded,
            _sql_loaded = true,
        }
        for _, tag in ipairs(loaded.user or {}) do
            if not seen_union[tag] then
                seen_union[tag] = true
                union[#union + 1] = tag
            end
        end
        local excluded_for_path = {}
        for _, tag in ipairs(loaded.excluded or {}) do
            excluded_for_path[tag] = true
            if not seen_suppressed[tag] then
                seen_suppressed[tag] = true
                editor.suppressed_tags[#editor.suppressed_tags + 1] = tag
            end
        end
        editor.excluded_by_path[path_norm] = excluded_for_path
        local path_tags = {}
        for _, tag in ipairs(loaded.detected or {}) do
            if not TAG_BAR_EXCLUDED[tag] then
                path_tags[tag] = true
                if not seen_detected[tag] then
                    seen_detected[tag] = true
                    editor.detected_tags[#editor.detected_tags + 1] = tag
                end
            end
        end
        editor.detected_by_path[path_norm] = path_tags
    end
    table.sort(union)
    table.sort(editor.detected_tags)
    table.sort(editor.suppressed_tags)
    editor.tags = union
    editor.original_tags = {}
    for index, tag in ipairs(union) do editor.original_tags[index] = tag end
    editor.original_detected_tags = {}
    for index, tag in ipairs(editor.detected_tags) do
        editor.original_detected_tags[index] = tag
    end
    editor.value = ""
    editor.added_tags = {}
    editor.removed_tags = {}
    editor.restored_tags = {}
end

function DrawMediaTagEditor()
    local editor = state.tag_editor
    if editor.open then
        editor.open = false
        imgui.OpenPopup(ctx, "Edit Tags")
    end
    if imgui.BeginPopupModal(
        ctx, "Edit Tags", nil, imgui.WindowFlags_AlwaysAutoResize) then
        imgui.Text(
            ctx,
            #editor.paths == 1 and GetFileName(editor.paths[1])
                or (tostring(#editor.paths) .. " selected files"))

        if editor.loading then
            imgui.Spacing(ctx)
            imgui.TextDisabled(ctx, "Loading tags...")
            if editor.loading_visible_frame == nil then
                editor.loading_visible_frame = state.ui_frame_index
            elseif state.ui_frame_index > editor.loading_visible_frame then
                local database = state.database
                if not editor.loading_request_started
                    and not database.write_active
                    and not state.canonical_paging.active then
                    local sql = BuildCanonicalTagEditorSQL(editor.paths)
                    local ok, load_error
                    if sql then
                        ok, load_error = StartDatabaseBatchAsync(
                            sql, #(editor.paths or {}),
                            "canonical_tag_editor", GetCanonicalDatabasePath())
                    else
                        ok, load_error = false, "No selected files."
                    end
                    if ok then
                        editor.loading_request_started = true
                    else
                        editor.loading = false
                        editor.loading_error = tostring(
                            load_error or "Unable to start tag loading.")
                    end
                end
            end
            imgui.Spacing(ctx)
            if imgui.Button(ctx, "Cancel", 90, 0) then
                editor.loading_cancelled = true
                if not editor.loading_request_started then
                    editor.loading = false
                end
                imgui.CloseCurrentPopup(ctx)
            end
            imgui.EndPopup(ctx)
            return
        elseif editor.loading_error then
            imgui.Spacing(ctx)
            imgui.TextDisabled(ctx, editor.loading_error)
            if imgui.Button(ctx, "Close", 90, 0) then
                editor.loading_error = nil
                imgui.CloseCurrentPopup(ctx)
            end
            imgui.EndPopup(ctx)
            return
        end

        local function HasEditorTag(wanted)
            wanted = NormalizeTag(wanted)
            for _, tag in ipairs(editor.tags or {}) do
                if tag == wanted then return true end
            end
            return false
        end

        local function AddEditorTags(value)
            editor.tags = editor.tags or {}
            editor.added_tags = editor.added_tags or {}
            editor.removed_tags = editor.removed_tags or {}
            for raw_tag in (value or ""):gmatch("[^,]+") do
                local tag = NormalizeTag(raw_tag)
                if tag ~= "" then
                    -- An explicit add applies to every selected file, even
                    -- when the union already contains this tag.
                    editor.added_tags[tag] = true
                    editor.removed_tags[tag] = nil
                    if not HasEditorTag(tag) then
                        editor.tags[#editor.tags + 1] = tag
                    end
                end
            end
        end

        local function RemoveEditorTag(tag)
            tag = NormalizeTag(tag)
            if tag == "" then return end
            editor.removed_tags = editor.removed_tags or {}
            editor.added_tags = editor.added_tags or {}
            editor.removed_tags[tag] = true
            editor.added_tags[tag] = nil
            if editor.restored_tags then editor.restored_tags[tag] = nil end
            for _, list in ipairs({editor.tags, editor.detected_tags}) do
                for index = #(list or {}), 1, -1 do
                    if list[index] == tag then table.remove(list, index) end
                end
            end
        end

        imgui.Spacing(ctx)
        imgui.Text(ctx, "Active tags")
        imgui.PushStyleVar(ctx, imgui.StyleVar_FrameRounding, 0)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 5, 2)
        imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 4, 3)
        if #(editor.tags or {}) == 0 then
            imgui.TextDisabled(ctx, "No tags added")
        else
            local remove_index = nil
            local used = 0
            local available = 410
            for index, tag in ipairs(editor.tags) do
                local label = "\xc3\x97 " .. tag .. "##remove_editor_tag_" .. index
                local width = select(1, imgui.CalcTextSize(ctx, "\xc3\x97 " .. tag)) + 12
                if used > 0 and used + width <= available then
                    imgui.SameLine(ctx)
                elseif used > 0 then
                    used = 0
                end
                if imgui.SmallButton(ctx, label) then remove_index = index end
                if imgui.IsItemHovered(ctx) then
                    imgui.SetTooltip(ctx, "Remove " .. tag)
                end
                used = used + width + 4
            end
            if remove_index then RemoveEditorTag(editor.tags[remove_index]) end
        end

        if #(editor.detected_tags or {}) > 0 then
            imgui.Spacing(ctx)
            imgui.TextDisabled(ctx, "Detected automatically")
            local remove_detected = nil
            local detected_used = 0
            for index, tag in ipairs(editor.detected_tags) do
                local label = "\xc3\x97 " .. tag
                    .. "##remove_detected_tag_" .. index
                local width = select(1, imgui.CalcTextSize(
                    ctx, "\xc3\x97 " .. tag)) + 12
                if detected_used > 0 and detected_used + width <= 410 then
                    imgui.SameLine(ctx)
                elseif detected_used > 0 then
                    detected_used = 0
                end
                if imgui.SmallButton(ctx, label) then
                    remove_detected = index
                end
                if imgui.IsItemHovered(ctx) then
                    imgui.SetTooltip(ctx, "Stop using this detected tag")
                end
                detected_used = detected_used + width + 4
            end
            if remove_detected then
                RemoveEditorTag(editor.detected_tags[remove_detected])
            end
        end

        if #(editor.suppressed_tags or {}) > 0 then
            imgui.Spacing(ctx)
            imgui.TextDisabled(ctx, "Suppressed automatically")
            local restore_index = nil
            local suppressed_used = 0
            for index, tag in ipairs(editor.suppressed_tags) do
                local label = "+ " .. tag
                    .. "##restore_detected_tag_" .. index
                local width = select(1, imgui.CalcTextSize(
                    ctx, "+ " .. tag)) + 12
                if suppressed_used > 0
                    and suppressed_used + width <= 410 then
                    imgui.SameLine(ctx)
                elseif suppressed_used > 0 then
                    suppressed_used = 0
                end
                if imgui.SmallButton(ctx, label) then restore_index = index end
                if imgui.IsItemHovered(ctx) then
                    imgui.SetTooltip(ctx, "Restore this detected tag")
                end
                suppressed_used = suppressed_used + width + 4
            end
            if restore_index then
                local tag = table.remove(editor.suppressed_tags, restore_index)
                editor.restored_tags = editor.restored_tags or {}
                editor.removed_tags = editor.removed_tags or {}
                editor.restored_tags[tag] = true
                editor.removed_tags[tag] = nil
                local found = false
                for _, detected in ipairs(editor.detected_tags or {}) do
                    if detected == tag then found = true break end
                end
                if not found then
                    editor.detected_tags[#editor.detected_tags + 1] = tag
                    table.sort(editor.detected_tags)
                end
            end
        end

        imgui.Spacing(ctx)
        imgui.Text(ctx, "Add tags")
        imgui.SetNextItemWidth(ctx, 330)
        local changed, value = imgui.InputTextWithHint(
            ctx, "##media_tags", "Type tags, separated by commas", editor.value)
        if changed then editor.value = value end
        -- Match the main search field: while this text box owns the keyboard,
        -- browser shortcuts must not invoke REAPER actions such as transport.
        state.search_active = state.search_active or imgui.IsItemActive(ctx)
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Add", 72, 0) then
            AddEditorTags(editor.value)
            editor.value = ""
        end

        imgui.TextDisabled(ctx, "Common tags")
        local common_used = 0
        for index, tag in ipairs(COMMON_USER_TAGS) do
            if not HasEditorTag(tag) then
                local width = select(1, imgui.CalcTextSize(ctx, tag)) + 12
                if common_used > 0 and common_used + width <= 410 then
                    imgui.SameLine(ctx)
                elseif common_used > 0 then
                    common_used = 0
                end
                if imgui.SmallButton(
                    ctx, tag .. "##common_editor_tag_" .. index) then
                    editor.tags[#editor.tags + 1] = tag
                    editor.added_tags = editor.added_tags or {}
                    editor.removed_tags = editor.removed_tags or {}
                    editor.added_tags[tag] = true
                    editor.removed_tags[tag] = nil
                end
                common_used = common_used + width + 4
            end
        end
        imgui.PopStyleVar(ctx, 3)

        imgui.Spacing(ctx)
        if imgui.Button(ctx, "Save tags", 100, 0) then
            AddEditorTags(editor.value)
            local removed = editor.removed_tags or {}
            local added = editor.added_tags or {}
            local restored = editor.restored_tags or {}
            local any_changed = false
            for _, path in ipairs(editor.paths) do
                local merged = {}
                local manual_for_path = {}
                for _, tag in ipairs(GetMediaUserTags(path) or {}) do
                    manual_for_path[tag] = true
                    if not removed[tag] then merged[#merged + 1] = tag end
                end
                local detected_for_path = editor.detected_by_path
                    and editor.detected_by_path[NormalizeFavoritePath(path)] or {}
                local path_changed = false
                for tag in pairs(removed) do
                    if manual_for_path[tag] or detected_for_path[tag] then
                        path_changed = true
                        break
                    end
                end
                if not path_changed then
                    for tag in pairs(added) do
                        if not manual_for_path[tag]
                            and not detected_for_path[tag] then
                            path_changed = true
                            break
                        end
                    end
                end
                if not path_changed then
                    local excluded_for_path = editor.excluded_by_path
                        and editor.excluded_by_path[
                            NormalizeFavoritePath(path)] or {}
                    for tag in pairs(restored) do
                        if excluded_for_path[tag] then
                            path_changed = true
                            break
                        end
                    end
                end
                local present = {}
                for _, tag in ipairs(merged) do present[tag] = true end
                for tag in pairs(added) do
                    if not present[tag] then
                        merged[#merged + 1] = tag
                        present[tag] = true
                    end
                end
                local excluded, excluded_seen = {}, {}
                for _, tag in ipairs(GetMediaExcludedTags(path) or {}) do
                    if not present[tag] and not restored[tag] then
                        excluded[#excluded + 1] = tag
                        excluded_seen[tag] = true
                    end
                end
                for tag in pairs(removed) do
                    if detected_for_path[tag] and not present[tag]
                        and not excluded_seen[tag] then
                        excluded[#excluded + 1] = tag
                        excluded_seen[tag] = true
                    end
                end
                if path_changed then
                    SetMediaTagData(path, merged, excluded, true, true)
                    any_changed = true
                end
            end
            if any_changed then
                -- Every file mutation is already queued. Persist the durable
                -- journal once for the complete edit instead of rewriting an
                -- increasingly large queue once per selected file.
                PersistCanonicalUserDataJournal()
                state.media_tag_generation = state.media_tag_generation + 1
                state.force_search_update = true
                state.needs_visible_update = true
                SaveMediaUserTags()
                if StartMediaFilterIndexBuild then StartMediaFilterIndexBuild() end
            end
            editor.value = ""
            imgui.CloseCurrentPopup(ctx)
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Cancel", 90, 0) then imgui.CloseCurrentPopup(ctx) end
        imgui.EndPopup(ctx)
    end
end

function GetMediaRowSelectionKey(node, occurrence_key)
    local scope = "library"
    local path = tostring(node and node.path or "")
    if not state.favorites_mode then
        if node and node._library_selection_key_path == path then
            return node._library_selection_key
        end
        local key = scope .. "|" .. path
        if node then
            node._library_selection_key_path = path
            node._library_selection_key = key
        end
        return key
    end
    scope = tostring(GetFavoriteContextCollectionId(node) or "root")
    -- Favorite files can occur in several custom folders. Include both the
    -- file path and the rendered occurrence so repeated rows never share an
    -- ImGui/hover identity. The fallback remains path-stable for callers that
    -- do not have a renderer-specific occurrence token.
    return scope .. "|" .. path .. "|"
        .. tostring(occurrence_key or path)
end

function IsMediaFileRowSelected(node, row_key)
    if not node or not state.multi_selected[node.path] then return false end
    -- The Library has one logical row per file. Do not let a refreshed page
    -- row key hide its selection; occurrence-specific filtering is only
    -- needed for the same file appearing in multiple Favorites folders.
    if not state.favorites_mode then return true end
    local selected_key = state.selected_file_row_keys[node.path]
    if selected_key then
        return selected_key == row_key
    end
    -- Range/keyboard selection stores file paths before a rendered row is
    -- available. Bind that path to the first visible occurrence this frame so
    -- all other copies stay unselected instead of inheriting the path-wide
    -- selection.
    if row_key then
        state.selected_file_row_keys[node.path] = row_key
        return true
    end
    return true
end

function IsMediaFileRowHovered(node, row_key)
    if not node or state.suppress_mouse_hover then return false end
    if state.favorites_mode then
        return state.hovered_row_key ~= nil
            and state.hovered_row_key == row_key
    end
    return state.hovered_path == node.path
end

local browser_row_interaction = {}
-- Resolve the external protocol once at mouse-down, using the gesture's
-- selection rather than the currently loaded preview. Alt always inverts it.
function ResolveFileDragNative(paths, alt)
    local native = state.external_drag_default_native == true
    if state.one_shot_native_drag and state.audio_auto_one_shot
        and #paths > 0 then
        local all_one_shots = true
        for _, path in ipairs(paths) do
            if not IsAudioFile(path)
                or ResolveEffectiveMediaClass(path) ~= "one-shot" then
                all_one_shots = false
                break
            end
        end
        if all_one_shots then native = true end
    end
    if alt then native = not native end
    return native
end

local function CaptureBrowserRowInteraction(row_key)
    if state.block_browser_input then
        local interaction = browser_row_interaction
        interaction.clicked = false
        interaction.hovered = false
        interaction.active = false
        interaction.double_clicked = false
        interaction.right_clicked = false
        interaction.middle_clicked = false
        interaction.ctrl = false
        interaction.shift = false
        interaction.row_key = row_key
        return interaction
    end
    local hovered = imgui.IsItemHovered(ctx)
    local ctrl, shift = GetSelectionModifiers()
    local interaction = browser_row_interaction
    interaction.clicked = imgui.IsItemClicked(ctx, 0)
    interaction.hovered = hovered
    interaction.active = imgui.IsItemActive(ctx)
    interaction.double_clicked = hovered
        and imgui.IsMouseDoubleClicked(ctx, 0)
    interaction.right_clicked = hovered and imgui.IsMouseClicked(ctx, 1)
    interaction.middle_clicked = hovered and imgui.IsMouseClicked(ctx, 2)
    interaction.ctrl = ctrl
    interaction.shift = shift
    interaction.row_key = row_key
    return interaction
end

function HandleFileInteraction(file_node, suppress_click, interaction)
    local filepath = file_node.path
    interaction = interaction or CaptureBrowserRowInteraction()
    if interaction.clicked then
        -- A file click can happen on the last visible row at the same time the
        -- accordion's end sentinel becomes visible. Let selection settle
        -- before advancing the rolling page window, otherwise the newly
        -- appended page can release the row that was just selected.
        state.accordion_page_load_suppressed = true
    end
    if not suppress_click and interaction.clicked then
        -- Only a new physical press can re-arm a gesture consumed by OLE.
        -- Its queued drag loop can leave this ImGui row active across frames.
        state.file_drag_handed_off = false
        GetMediaClass(file_node)
        local ctrl = interaction.ctrl == true
        local shift = interaction.shift == true
        local row_key = interaction.row_key
            or GetMediaRowSelectionKey(file_node, filepath)
        state.selected_file_row_keys = state.selected_file_row_keys or {}
        state.favorite_drag_pending_path = filepath
        state.favorite_drag_pending_copy = ctrl
        local selected_count = #GetSelectedFilePaths(nil)
        -- Standard browser drag behavior: pressing an item that is already
        -- part of a multi-selection must not collapse the selection before
        -- ImGui has a chance to recognize the drag.
        if not ctrl and not shift and state.multi_selected[filepath]
            and selected_count > 1 then
            state.cursor_path = filepath
            state.cursor_type = "file"
            state.pending_single_node = file_node
            state.pending_single_row_key = row_key
            state.pending_ctrl_file = nil
        elseif ctrl then
            -- Ctrl is both the multi-select modifier and the copy modifier.
            -- Defer the selection toggle until mouse-up so starting a drag
            -- cannot remove the source from an existing multi-selection.
            state.pending_single_node = nil
            state.pending_single_row_key = nil
            state.pending_ctrl_file = {
                node = file_node, row_key = row_key
            }
        else
            state.pending_single_node = nil
            state.pending_single_row_key = nil
            state.pending_ctrl_file = nil
            SelectFileNode(file_node, false, ctrl, shift, row_key)
            if shift then
                state.selected_file_row_keys[filepath] = row_key
            else
                state.selected_file_row_keys = {[filepath] = row_key}
            end
        end
        local drag_paths = state.multi_selected[filepath]
            and GetSelectedFilePaths(filepath) or {filepath}
        state.pending_file_drag_native = ResolveFileDragNative(
            drag_paths, select(3, GetSelectionModifiers()) == true)
        state.pending_file_drag_paths = drag_paths
    end
    if interaction.hovered then
        state.next_hovered_path = filepath
        state.next_hovered_row_key = interaction.row_key
        -- Hover and right-click must never launch a synchronous database
        -- helper merely to populate a tooltip. Use only already-cached tags.
        local cached_tags = state.media_user_tags[
            NormalizeFavoritePath(filepath)]
        local tags = cached_tags and cached_tags.tags or nil
        if tags and #tags > 0 then
            imgui.SetTooltip(ctx, "Tags: " .. table.concat(tags, ", "))
        end
        if interaction.double_clicked then
            InsertFileFromBrowserDoubleClick(filepath)
        end
    end

    -- One middle-click provides both Cartridge actions: target the currently
    -- open Cartridge interface when one exists, otherwise create a new one.
    -- Keep this independent from left-click selection and drag handling.
    if not suppress_click and interaction.middle_clicked
        and IsAudioFile(filepath) then
        local cartridge_track = FindActiveCartridge()
        if cartridge_track then
            LoadFileIntoActiveCartridge(filepath)
        else
            OpenFileInNewCartridge(filepath)
        end
    end
    
    if not suppress_click
        and not state.file_drag_handed_off
        and (interaction.active or state.favorite_drag_pending_path == filepath)
        and not state.favorite_heart_press_path
        and imgui.IsMouseDragging(ctx, 0) then
        if not state.drag_active then
            state.pending_single_node = nil
            state.pending_single_row_key = nil
            state.pending_ctrl_file = nil
            if not state.multi_selected[filepath] then
                state.multi_selected = {[filepath] = true}
                state.selection_anchor = filepath
                state.selection_anchor_row_key = interaction.row_key
                    or GetMediaRowSelectionKey(file_node, filepath)
                state.selected_file_row_keys = {}
            end
            state.selected_file_row_keys =
                state.selected_file_row_keys or {}
            state.selected_file_row_keys[filepath] =
                interaction.row_key
                    or GetMediaRowSelectionKey(file_node, filepath)
            state.drag_active = true
            state.drag_path = filepath
            state.drag_kind = "file"
            -- Choose the destination protocol at mouse-down. Switching from
            -- the custom Arrange drag to OLE after the gesture has started can
            -- let both paths observe the same mouse release.
            state.native_drag_alt_latched = state.pending_file_drag_native
            state.drag_paths = state.pending_file_drag_paths or {filepath}
            state.pending_file_drag_paths = nil
            state.favorite_drag_copy = state.favorite_drag_pending_copy
                or select(1, GetSelectionModifiers())
            state.favorite_drag_source_kind,
                state.favorite_drag_source_collection_id =
                GetFavoriteDragSource(file_node)
            state.drag_orig_cursor_pos = r.GetCursorPosition()
            state.drag_last_track = nil
            state.drag_last_pos = nil
            state.drag_hover_arrange = false
            state.favorite_drag_pending_path = nil
            state.favorite_drag_pending_copy = false
            if state.is_playing then StopPreview() end
        end
    end

    local popup_id = file_node._media_context_popup_id
    if not popup_id then
        popup_id = "##file_context_" .. filepath
        file_node._media_context_popup_id = popup_id
    end
    if interaction.right_clicked then imgui.OpenPopup(ctx, popup_id) end
    if imgui.BeginPopup(ctx, popup_id) then
        state.context_menu_active = true
        -- Optional cache hydration must not claim the database worker while a
        -- context menu is being displayed or interacted with.
        state.file_context_menu_open_frame = state.ui_frame_index
        imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 7, 5)
        state.next_hovered_path = filepath
        state.next_hovered_row_key = interaction.row_key
        if not state.multi_selected[filepath] then
            state.multi_selected = {[filepath] = true}
            state.selection_anchor = filepath
            state.cursor_path = filepath
            state.selected_file_row_keys = {
                [filepath] = interaction.row_key
                    or GetMediaRowSelectionKey(file_node, filepath)
            }
        end
        local selected_paths = GetSelectedFilePaths(filepath)
        local selected_paths_are_audio = #selected_paths > 0
        for _, selected_path in ipairs(selected_paths) do
            if not IsAudioFile(selected_path) then
                selected_paths_are_audio = false
                break
            end
        end
        if selected_paths_are_audio then
            if imgui.MenuItem(ctx, #selected_paths > 1
                and "Add Selected to ReaDrum"
                or "Add to ReaDrum") then
                SendSelectedFilesToReaDrum(filepath)
            end
            imgui.Separator(ctx)
        end
        if #selected_paths == 1 and IsAudioFile(selected_paths[1]) then
            local cartridge_accent = state.resolved_theme
                and state.resolved_theme.accent or state.theme.colors.accent
            local function DrawCartridgeMenuItem(label, action)
                local item_x, item_y = imgui.GetCursorScreenPos(ctx)
                local item_width = select(1, imgui.GetContentRegionAvail(ctx))
                local item_height = imgui.GetTextLineHeightWithSpacing(ctx)
                local mouse_x, mouse_y = imgui.GetMousePos(ctx)
                local hovered = mouse_x >= item_x
                    and mouse_x <= item_x + item_width
                    and mouse_y >= item_y
                    and mouse_y <= item_y + item_height
                imgui.PushStyleColor(ctx, imgui.Col_Text,
                    hovered and 0xFFFFFFFF or cartridge_accent)
                local clicked = imgui.MenuItem(ctx, label)
                imgui.PopStyleColor(ctx)
                if clicked then action() end
            end
            DrawCartridgeMenuItem("Insert to New Cartridge", function()
                OpenFileInNewCartridge(selected_paths[1])
            end)
            DrawCartridgeMenuItem("Load into Active Cartridge", function()
                LoadFileIntoActiveCartridge(selected_paths[1])
            end)
            DrawCartridgeMenuItem("Insert to New RS5K", function()
                InsertFileInNewRS5K(selected_paths[1])
            end)
            imgui.Separator(ctx)
        end
        local favorite_collection_id =
            GetFavoriteContextCollectionId(file_node)
        local favorite_root_membership =
            IsFavoriteRootMembershipNode(file_node)
        local selected_favorites = true
        local favorite_membership_known = true
        for _, path in ipairs(selected_paths) do
            local key = NormalizeFavoritePath(path)
            local index = state.favorite_index[key]
            local entry = index and state.favorites[index] or nil
            local membership
            if favorite_collection_id then
                membership = entry and FavoriteEntryHasCollection(
                    entry, favorite_collection_id) or nil
            elseif favorite_root_membership then
                -- A row rendered in the loose-root section is authoritative
                -- for direct/root membership, regardless of copies elsewhere.
                membership = true
            else
                local pending = state.favorite_pending_overrides[key]
                if pending ~= nil then
                    membership = pending == true
                elseif entry then
                    membership = FavoriteEntryHasAnyMembership(entry)
                elseif state.favorite_membership_cache[key] ~= nil then
                    membership = state.favorite_membership_cache[key] == true
                end
            end
            if membership == nil then
                favorite_membership_known = false
                if not favorite_collection_id then
                    state.favorite_membership_pending_paths[key] = true
                    state.favorite_membership_next_at = math.max(
                        state.favorite_membership_next_at or 0,
                        r.time_precise() + 0.25)
                end
                selected_favorites = false
                break
            elseif not membership then
                selected_favorites = false
                break
            end
        end
        if not favorite_membership_known and imgui.BeginDisabled then
            imgui.BeginDisabled(ctx)
        end
        if imgui.MenuItem(
            ctx, not favorite_membership_known and "Checking Favorites..."
                or selected_favorites
                and (favorite_collection_id
                    and (#selected_paths > 1
                        and "Remove Selected from this Favorites folder"
                        or "Remove from this Favorites folder")
                    or favorite_root_membership
                    and (#selected_paths > 1
                        and "Remove Selected from Favorites root"
                        or "Remove from Favorites root")
                    or (#selected_paths > 1
                        and "Remove Selected from Favorites"
                        or "Remove from Favorites"))
                or (#selected_paths > 1
                    and "Add Selected to Favorites"
                    or "Add to Favorites")) then
            if selected_favorites and favorite_collection_id then
                SetFavoriteCollectionMemberships(
                    selected_paths, favorite_collection_id, false, "file")
            elseif selected_favorites and favorite_root_membership then
                SetFavoritePaths(selected_paths, false, "file")
            elseif selected_favorites then
                RemoveAllFavoriteMemberships(selected_paths, "file")
            elseif favorite_collection_id then
                SetFavoriteCollectionMemberships(
                    selected_paths, favorite_collection_id, true, "file")
            else
                SetFavoritePaths(selected_paths, true, "file")
            end
        end
        if not favorite_membership_known and imgui.EndDisabled then
            imgui.EndDisabled(ctx)
        end
        if selected_favorites
            and (favorite_collection_id or favorite_root_membership)
            and imgui.MenuItem(ctx, #selected_paths > 1
                and "Remove Selected from Favorites completely"
                or "Remove from Favorites completely") then
            RemoveFavoritePathsCompletely(selected_paths, "file")
        end
        if #state.favorite_collections > 0 then
            if imgui.BeginMenu(ctx, #selected_paths > 1
                and "Add/Remove Selected from Favorites Folder"
                or "Add/Remove from Favorites Folder") then
                DrawFavoriteCollectionMenuTree(
                    GetFavoriteCollectionMenuTree(),
                    selected_paths, "file")
                imgui.EndMenu(ctx)
            end
        else
            if imgui.MenuItem(ctx, "Create Favorites Folder...") then
                PromptAddFavoriteFolder()
            end
        end
        imgui.Separator(ctx)
        if imgui.BeginMenu(ctx, "Category") then
            local detected_label, override_label, effective_label =
                GetClassificationDisplaySummary(selected_paths, file_node)
            imgui.TextDisabled(ctx, "Detected: " .. detected_label)
            imgui.TextDisabled(ctx, "Override: " .. override_label)
            imgui.TextDisabled(ctx, "Effective: " .. effective_label)
            imgui.TextDisabled(ctx, "Set manual override:")
            local category_options = {
                {key = "loop", label = "Loop"},
                {key = "one-shot", label = "One-shot"},
                {key = "uncategorized", label = "Other"},
            }
            for _, option in ipairs(category_options) do
                local all_category = true
                for _, path in ipairs(selected_paths) do
                    local current = GetManualCategoryKey(path)
                    local has_category = option.key == "uncategorized"
                        and current == "other" or current == option.key
                    if not has_category then all_category = false; break end
                end
                local label = (all_category and "[x] " or "") .. option.label
                if imgui.MenuItem(ctx, label) then
                    SetClassificationOverrides(
                        selected_paths, option.key)
                end
            end
            imgui.Separator(ctx)
            if imgui.MenuItem(ctx, "Clear Manual Override") then
                local queued_any = false
                for _, path in ipairs(selected_paths) do
                    if not IsMidiFile(path) then
                        queued_any = ClearClassificationOverride(
                            "file", path, false, false, true) or queued_any
                    end
                end
                if queued_any then
                    PersistCanonicalUserDataJournal()
                    RefreshClassificationViews()
                end
            end
            imgui.TextDisabled(ctx, "MIDI is determined by file type")
            imgui.EndMenu(ctx)
        end
        if imgui.BeginMenu(ctx, "Key") then
            local detected_label, override_label, effective_label =
                GetKeyDisplaySummary(selected_paths)
            imgui.TextDisabled(ctx, "Detected: " .. detected_label)
            imgui.TextDisabled(ctx, "Override: " .. override_label)
            imgui.TextDisabled(ctx, "Effective: " .. effective_label)
            imgui.TextDisabled(ctx, "Set manual override:")
            for key_pc = 0, 11 do
                local all_match = true
                for _, path in ipairs(selected_paths) do
                    local entry = GetManualKeyOverrideEntry(path)
                    if not entry or entry.key_pc ~= key_pc then
                        all_match = false
                        break
                    end
                end
                local label = (all_match and "[x] " or "")
                    .. PITCH_CLASS_NAMES[key_pc + 1]
                if imgui.MenuItem(ctx, label) then
                    SetKeyOverrides(selected_paths, key_pc)
                end
            end
            local all_unkeyed = true
            for _, path in ipairs(selected_paths) do
                local entry = GetManualKeyOverrideEntry(path)
                if not entry or entry.key_pc ~= false then
                    all_unkeyed = false
                    break
                end
            end
            if imgui.MenuItem(ctx,
                (all_unkeyed and "[x] " or "") .. "Mark as Unkeyed") then
                SetKeyOverrides(selected_paths, nil)
            end
            imgui.Separator(ctx)
            if imgui.MenuItem(ctx, "Clear Manual Key Override") then
                local queued_any = false
                local refresh_path = nil
                for _, path in ipairs(selected_paths) do
                    queued_any = ClearKeyOverride(path, true) or queued_any
                    if NormalizeFavoritePath(path)
                        == NormalizeFavoritePath(state.source_file or "") then
                        refresh_path = path
                    end
                end
                if queued_any then
                    PersistCanonicalUserDataJournal()
                    RefreshKeyOverrideViews(refresh_path)
                end
            end
            imgui.EndMenu(ctx)
        end
        if imgui.MenuItem(ctx, #selected_paths > 1 and "Edit Tags for Selected..." or "Edit Tags...") then
            state.tag_editor.paths = selected_paths
            state.tag_editor.loading = true
            state.tag_editor.loading_visible_frame = nil
            state.tag_editor.loading_request_started = false
            state.tag_editor.loading_cancelled = false
            state.tag_editor.loading_error = nil
            state.tag_editor.open = true
        end
        imgui.Separator(ctx)
        if imgui.MenuItem(
            ctx,
            #selected_paths > 1
                and "Insert Selected on Consecutive Tracks"
                or "Insert on Selected Track at Edit Cursor"
        ) then
            InsertFilesOnConsecutiveTracks(
                selected_paths,
                r.GetSelectedTrack(0, 0),
                r.GetCursorPosition()
            )
        end
        imgui.Separator(ctx)
        if #selected_paths == 1 then
            if imgui.BeginMenu(ctx, "Reveal") then
                if imgui.MenuItem(ctx, "In Library") then
                    if not RevealFileInLibrary(selected_paths[1]) then
                        r.ShowMessageBox(
                            "ReaBrowse could not locate this file in the active Library:\n\n"
                                .. selected_paths[1],
                            "ReaBrowse",
                            0
                        )
                    end
                end
                if imgui.MenuItem(ctx, "In System File Browser") then
                    if not RevealFileInExplorer(selected_paths[1]) then
                        r.ShowMessageBox(
                            "The system file browser could not locate this file:\n\n"
                                .. selected_paths[1],
                            "ReaBrowse",
                            0
                        )
                    end
                end
                imgui.EndMenu(ctx)
            end
        end
        if imgui.MenuItem(ctx, #selected_paths > 1 and "Copy selected paths" or "Copy file path") then
            local copied_paths = table.concat(selected_paths, "\n")
            if imgui.SetClipboardText then
                imgui.SetClipboardText(ctx, copied_paths)
            elseif r.CF_SetClipboard then
                r.CF_SetClipboard(copied_paths)
            end
        end
        imgui.PopStyleVar(ctx)
        imgui.EndPopup(ctx)
    end
end

function ProcessPendingMediaCtrlClick()
    local pending = state.pending_ctrl_file
    if not pending or state.drag_active or imgui.IsMouseDown(ctx, 0) then
        return
    end
    state.pending_ctrl_file = nil
    local node = pending.node
    if not node then return end
    SelectFileNode(node, false, true, false, pending.row_key)
    state.selected_file_row_keys = state.selected_file_row_keys or {}
    if state.multi_selected[node.path] then
        state.selected_file_row_keys[node.path] = pending.row_key
    else
        state.selected_file_row_keys[node.path] = nil
    end
end

local function DrawCanonicalNavigationIcon(kind, enabled)
    local size = 24
    local x, y = imgui.GetCursorScreenPos(ctx)
    imgui.InvisibleButton(
        ctx, "##canonical_nav_" .. kind, size, size)
    local hovered = enabled and imgui.IsItemHovered(ctx)
        and not state.suppress_mouse_hover
    local pressed = enabled and imgui.IsItemClicked(ctx, 0)
    if pressed then
        state.canonical_nav_flash = {
            kind = kind, until_time = r.time_precise() + 0.16
        }
    end
    local draw = imgui.GetWindowDrawList(ctx)
    local flash = state.canonical_nav_flash
    local clicked = flash and flash.kind == kind
        and r.time_precise() < (flash.until_time or 0)
    local accent = (state.resolved_theme and state.resolved_theme.accent)
        or state.theme.colors.accent
    local color = clicked and accent or 0xFFFFFFFF
    if not enabled then color = (color & 0xFFFFFF00) | 0x58 end
    if hovered then
        imgui.DrawList_AddRectFilled(
            draw, x, y, x + size, y + size, 0xFFFFFF18, 4)
    end
    if kind == "home" then
        imgui.DrawList_AddLine(
            draw, x + 5, y + 12, x + 12, y + 5, color, 1.8)
        imgui.DrawList_AddLine(
            draw, x + 12, y + 5, x + 19, y + 12, color, 1.8)
        imgui.DrawList_AddLine(
            draw, x + 7, y + 10, x + 7, y + 19, color, 1.8)
        imgui.DrawList_AddLine(
            draw, x + 17, y + 10, x + 17, y + 19, color, 1.8)
        imgui.DrawList_AddLine(
            draw, x + 7, y + 19, x + 17, y + 19, color, 1.8)
        imgui.DrawList_AddRect(
            draw, x + 10, y + 14, x + 14, y + 19, color, 0, 0, 1.4)
    else
        imgui.DrawList_AddLine(
            draw, x + 15, y + 6, x + 8, y + 12, color, 3)
        imgui.DrawList_AddLine(
            draw, x + 8, y + 12, x + 15, y + 18, color, 3)
    end
    if hovered then
        imgui.SetTooltip(ctx, kind == "home"
            and "Home - clear search and filters" or "Back")
    end
    return pressed
end

local function DrawCanonicalLuckyDice(browser)
    local size = 24
    local x, y = imgui.GetCursorScreenPos(ctx)
    local pressed = imgui.InvisibleButton(ctx, "##canonical_lucky_dice", size, size)
    local hovered = imgui.IsItemHovered(ctx)
        and not state.suppress_mouse_hover
    if pressed then
        state.canonical_nav_flash = {
            kind = "dice", until_time = r.time_precise() + 0.16
        }
    end
    local draw = imgui.GetWindowDrawList(ctx)
    local flash = state.canonical_nav_flash
    local clicked = flash and flash.kind == "dice"
        and r.time_precise() < (flash.until_time or 0)
    local accent = (state.resolved_theme and state.resolved_theme.accent)
        or state.theme.colors.accent
    local color = clicked and accent or 0xFFFFFFFF
    local background = hovered and 0xFFFFFF18 or 0x00000000
    if background ~= 0 then
        imgui.DrawList_AddRectFilled(
            draw, x, y, x + size, y + size, background, 4)
    end
    imgui.DrawList_AddRect(
        draw, x + 4, y + 4, x + size - 4, y + size - 4,
        color, 3, 0, 1.5)
    local radius = 1.7
    imgui.DrawList_AddCircleFilled(draw, x + 9, y + 9, radius, color)
    imgui.DrawList_AddCircleFilled(
        draw, x + size - 9, y + 9, radius, color)
    imgui.DrawList_AddCircleFilled(draw, x + size / 2, y + size / 2,
        radius, color)
    imgui.DrawList_AddCircleFilled(
        draw, x + 9, y + size - 9, radius, color)
    imgui.DrawList_AddCircleFilled(
        draw, x + size - 9, y + size - 9, radius, color)
    if hovered then
        imgui.SetTooltip(ctx, "Roll the Dice from all current matches")
    end
    return pressed
end

local function DrawFavoritesNavigationIcon(kind, active, tooltip)
    local size = 24
    local x, y = imgui.GetCursorScreenPos(ctx)
    local pressed = imgui.InvisibleButton(
        ctx, "##favorites_navigation_" .. tostring(kind), size, size)
    local hovered = imgui.IsItemHovered(ctx)
        and not state.suppress_mouse_hover
    local draw = imgui.GetWindowDrawList(ctx)
    local accent = (state.resolved_theme and state.resolved_theme.accent)
        or state.theme.colors.accent
    local normal = (state.resolved_theme and state.resolved_theme.text)
        or state.theme.colors.text
    local color = (active or hovered) and accent or normal
    if hovered then
        imgui.DrawList_AddRectFilled(
            draw, x, y, x + size, y + size, 0xFFFFFF18, 4)
    end
    local cx, cy = x + size * 0.5, y + size * 0.5
    if tostring(kind):find("add", 1, true) then
        imgui.DrawList_AddLine(
            draw, cx - 6, cy, cx + 6, cy, color, 1.8)
        imgui.DrawList_AddLine(
            draw, cx, cy - 6, cx, cy + 6, color, 1.8)
    elseif kind == "sort" then
        imgui.DrawList_AddLine(
            draw, cx - 8, cy - 6, cx + 4, cy - 6, color, 1.4)
        imgui.DrawList_AddLine(
            draw, cx - 8, cy, cx + 1, cy, color, 1.4)
        imgui.DrawList_AddLine(
            draw, cx - 8, cy + 6, cx - 2, cy + 6, color, 1.4)
        imgui.DrawList_AddLine(
            draw, cx + 7, cy - 7, cx + 7, cy + 6, color, 1.4)
        imgui.DrawList_AddTriangleFilled(
            draw, cx + 3, cy + 3, cx + 11, cy + 3,
            cx + 7, cy + 8, color)
    end
    if hovered and tooltip then imgui.SetTooltip(ctx, tooltip) end
    return pressed
end

function DrawFavoritesLibraryHeader(kind, tooltip)
    local start_x, start_y = imgui.GetCursorScreenPos(ctx)
    local available_w = select(1, imgui.GetContentRegionAvail(ctx))
    imgui.TextDisabled(ctx, "LIBRARY")
    local _, text_min_y = imgui.GetItemRectMin(ctx)
    local _, text_max_y = imgui.GetItemRectMax(ctx)
    local restore_x, restore_y = imgui.GetCursorScreenPos(ctx)
    local icon_size = 24
    imgui.SetCursorScreenPos(
        ctx,
        start_x + math.max(0, available_w - icon_size),
        text_min_y + (text_max_y - text_min_y - icon_size) * 0.5)
    local pressed = DrawFavoritesNavigationIcon(kind, false, tooltip)
    imgui.SetCursorScreenPos(
        ctx, restore_x, math.max(restore_y, start_y + icon_size))
    return pressed
end

local function TriggerUnifiedBrowserRandom()
    if not CanonicalFavoriteRandomScopeAvailable() then
        return false
    end
    if state.database_startup_test.enabled then
        -- Favorites can contain unloaded folders, so canonical random queries
        -- must not depend on the partially hydrated Lua tree.
        local browser = state.canonical_browser
        local continue_dice_cycle = browser.random_cursor_key ~= nil
            and browser.random_result ~= nil
            and browser.selected_path == browser.random_result.path
        ResetCanonicalForegroundView("Random view changed", true)
        CaptureCanonicalAccordionReturnState()
        state.randomize_on = false
        state.random_history = {}
        state.random_history_index = 0
        browser.random_history = {}
        browser.random_rows = {}
        browser.random_pool = {}
        browser.random_index = 0
        browser.random_force_start = false
        browser.random_wrap_rows = nil
        if not continue_dice_cycle then
            browser.random_cursor_key = nil
            browser.random_cursor_id = nil
        end
        browser.selected_path = nil
        browser.random_result = nil
        state.multi_selected = {}
        state.selected_file_row_keys = {}
        state.selection_anchor = nil
        state.selection_anchor_row_key = nil
        state.pending_single_node = nil
        state.pending_single_row_key = nil
        state.pending_ctrl_file = nil
        local root_favorites_scope = state.favorites_mode
            and browser.current_folder_id == nil
            and browser.collection_scope_key == nil
            and browser.smart_mode == nil
        local request_mode = root_favorites_scope
            and GetCanonicalFavoriteScopeCount(nil) == nil
            and "favorite_scope_count" or "browser_random"
        RequestCanonicalBrowserPage(
            request_mode, browser.current_folder_id, 0, false, false)
        return true
    end

    state.random_history = {}
    state.random_history_index = 0
    local picked = PlayRandomFile()
    if picked then
        state.random_history[1] = {path = picked.path, node = picked}
        state.random_history_index = 1
    end
    return picked ~= nil
end

