local function GetNavigationVisibleFileCount()
    local count = 0
    if CanonicalResultViewActive() then
        local browser = state.canonical_browser
        if browser.total_count ~= nil then
            return browser.total_count, false
        end
        if browser.loaded_file_count ~= nil then
            return browser.loaded_file_count, browser.has_more == true
        end
        local row_count = #(browser.rows or {})
        if browser._visible_file_count_source == browser.rows
            and browser._visible_file_count_rows == row_count then
            return browser._visible_file_count or 0,
                browser.has_more == true
        end
        for _, row in ipairs(browser.rows or {}) do
            if row.kind ~= "R" and row.kind ~= "D"
                and row.kind ~= "T" then
                count = count + 1
            end
        end
        browser._visible_file_count_source = browser.rows
        browser._visible_file_count_rows = row_count
        browser._visible_file_count = count
        return count, browser.has_more == true
    end
    if state.database_startup_test.enabled then
        local open_map = state.favorites_mode
            and state.favorite_open_folders or state.open_folders
        local has_more = false
        local function CountOpenNode(node)
            if not node or not open_map[GetFolderUIKey(node)] then return end
            if node._canonical_loaded_file_count ~= nil then
                count = count + node._canonical_loaded_file_count
            else
                count = count + #(node.files or {})
            end
            if node._canonical_has_more then has_more = true end
            for _, child in ipairs(node.children or {}) do
                CountOpenNode(child)
            end
        end
        for _, tree in ipairs(GetActiveTrees()) do
            if state.favorites_mode and tree.path == "__favorite_files__" then
                count = count + (tree._canonical_loaded_file_count
                    or #(tree.files or {}))
                if tree._canonical_has_more then has_more = true end
            else
                CountOpenNode(tree)
            end
        end
        return count, has_more
    end
    for _, item in ipairs(state.visible_items or {}) do
        if item.type == "file" then count = count + 1 end
    end
    return count, false
end

local function DrawUnifiedBrowserNavigation()
    local browser = state.canonical_browser
    if DrawCanonicalNavigationIcon("home", true) then
        if state.favorites_mode then
            CloseFavoriteSmartFolder()
            state.favorite_open_folders = {}
            browser.collection_scope_key = nil
            browser.discovery_active = false
            browser.search_text = ""
            browser.selected_tags = {}
            browser.selected_classes = {}
            browser.key_pc = -1
            browser.available_tags = {}
            browser.pending_tag_folder_id = nil
            browser.pending_tag_time = nil
            browser.tag_catalog_cache = {}
            state.search_input = ""
            state.search_text = ""
            state.media_filters.selected_tags = {}
            state.media_filters.quick_types = {}
            state.media_filters.key_pc = -1
            state.media_tag_bar.tags = {}
            state.cursor_path = nil
            state.cursor_type = nil
            state.cursor_favorite_instance_key = nil
            state.selected_folder_scope = nil
            state.needs_visible_update = true
            ClearCanonicalTagCatalogCache()
        else
            HomeCanonicalBrowser()
            if #state.folder_tree == 0 then
                LoadCanonicalAccordionRoots()
            end
        end
    end
    imgui.SameLine(ctx)
    local filtered = CanonicalBrowserFiltersActive()
    local can_go_back = browser.discovery_active
        or filtered
        or #browser.history > 0
        or (state.favorites_mode and state.favorite_smart_mode ~= nil)
        or state.cursor_path ~= nil
    if DrawCanonicalNavigationIcon(
        "back", can_go_back) then
        if browser.discovery_active then
            ExitCanonicalLuckyDraw()
        elseif filtered then
            ClearCanonicalBrowserFilters()
        elseif state.favorites_mode then
            -- Back navigates within Favorites only. The Library icon is the
            -- sole control that switches from Favorites to Library mode.
            if #browser.history > 0 then
                BackCanonicalBrowserFolder()
            elseif state.favorite_smart_mode then
                CloseFavoriteSmartFolder()
            elseif state.cursor_path ~= nil then
                HandleLeftArrow(FindCursorIndex())
            end
        elseif #browser.history > 0 then
            BackCanonicalBrowserFolder()
        else
            HandleLeftArrow(FindCursorIndex())
        end
    end
    local file_count, has_more_files = GetNavigationVisibleFileCount()
    local count_label = string.format(
        "%d%s", file_count, has_more_files and "+" or "")
    local count_width, count_height = imgui.CalcTextSize(ctx, count_label)
    imgui.SameLine(ctx)
    local count_cursor_x, count_cursor_y = imgui.GetCursorScreenPos(ctx)
    imgui.SetCursorScreenPos(ctx, count_cursor_x,
        count_cursor_y + 2)
    local badge_width = count_width + 16
    local badge_height = 20
    imgui.Dummy(ctx, badge_width, badge_height)
    local badge_min_x, badge_min_y = imgui.GetItemRectMin(ctx)
    local badge_max_x, badge_max_y = imgui.GetItemRectMax(ctx)
    local badge_theme = state.resolved_theme or state.theme.colors
    local badge_accent = badge_theme.accent or state.theme.colors.accent
    local badge_text = badge_theme.text or state.theme.colors.text
    local badge_draw = imgui.GetWindowDrawList(ctx)
    imgui.DrawList_AddRectFilled(
        badge_draw, badge_min_x, badge_min_y, badge_max_x, badge_max_y,
        (badge_accent & 0xFFFFFF00) | 0x24, badge_height * 0.5)
    imgui.DrawList_AddRect(
        badge_draw, badge_min_x, badge_min_y, badge_max_x, badge_max_y,
        (badge_accent & 0xFFFFFF00) | 0x58, badge_height * 0.5,
        0, 1)
    imgui.DrawList_AddText(
        badge_draw,
        badge_min_x + (badge_width - count_width) * 0.5,
        badge_min_y + (badge_height - count_height) * 0.5,
        (badge_text & 0xFFFFFF00) | 0xC8, count_label)
    local button_size = 24
    local button_spacing = 4
    local button_count = state.favorites_mode and 3 or 1
    local toolbar_width = button_count * button_size
        + (button_count - 1) * button_spacing
    local toolbar_start = imgui.GetCursorPosX(ctx)
        + select(1, imgui.GetContentRegionAvail(ctx)) - toolbar_width
    imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, button_spacing, 4)
    imgui.SameLine(ctx)
    imgui.SetCursorPosX(ctx, toolbar_start)
    local toolbar_screen_x = select(1, imgui.GetCursorScreenPos(ctx))
    imgui.SetCursorScreenPos(ctx, toolbar_screen_x, count_cursor_y)
    if state.favorites_mode then
        if DrawFavoritesNavigationIcon(
            "add", false, "New Favorites folder") then
            PromptAddFavoriteFolder(nil)
        end
        imgui.SameLine(ctx)
        if DrawFavoritesNavigationIcon(
            "sort", state.favorite_sort ~= "added",
            "Sort Favorites: " .. FavoriteSortLabel()) then
            imgui.OpenPopup(ctx, "##navigation_favorite_sort")
        end
        imgui.SameLine(ctx)
    end
    local random_scope_available = CanonicalFavoriteRandomScopeAvailable()
    local random_disabled_scope = false
    if not random_scope_available and imgui.BeginDisabled then
        imgui.BeginDisabled(ctx, true)
        random_disabled_scope = true
    end
    local random_pressed = DrawCanonicalLuckyDice(browser)
    if random_disabled_scope and imgui.EndDisabled then
        imgui.EndDisabled(ctx)
    end
    if random_pressed and random_scope_available then
        TriggerUnifiedBrowserRandom()
    end
    imgui.PopStyleVar(ctx)
    if state.favorites_mode then
        DrawFavoriteSortMenu("##navigation_favorite_sort")
    end
end

function FormatLibraryScanElapsed(seconds)
    seconds = math.max(0, tonumber(seconds) or 0)
    local whole = math.floor(seconds)
    local minutes = math.floor(whole / 60)
    local secs = whole % 60
    return string.format("%02d:%02d", minutes, secs)
end

GetLibraryScanProgress = function()
    local scan = state.library_scan
    local phase = scan.phase
    local label, detail, done, total, fraction
    if phase == "worker_discovery" then
        label = scan.phase_label or "Discovering folders and files"
        detail = scan.phase_detail or string.format(
            "%d folders, %d media files discovered",
            scan.discovered_folders or 0, scan.discovered_files or 0)
    elseif phase == "worker_ingest" then
        label = scan.phase_label or "Indexing media and generating tags"
        done = scan.discovered_files or 0
        total = scan.phase_total or 0
        detail = string.format("%d / %d media files indexed", done, total)
        if scan.phase_detail and scan.phase_detail ~= "" then
            detail = detail .. "; " .. scan.phase_detail
        end
    elseif phase == "folders" then
        label = "Discovering folders"
        detail = string.format("%d folders found", scan.discovered_folders or 0)
    elseif phase == "files" then
        label = "Scanning and classifying files"
        detail = string.format("%d media files found", scan.discovered_files or 0)
    elseif phase == "finalize" then
        label = "Finalizing scan manifest"
        done = scan.finalized_folders or 0
        total = scan.finalize_total or 0
        detail = string.format("%d / %d folders", done, total)
    elseif phase == "prepare" then
        label = "Preparing database manifest"
        done = scan.prepared_folders or 0
        total = scan.prepare_total or 0
        detail = string.format("%d / %d folders", done, total)
    elseif phase == "validate" then
        label = "Validating scan manifest"
        local validation = state.canonical_scan_sync.validation or {}
        done = validation.lines or 0
        total = validation.total or 0
        detail = string.format("%d / %d records", done, total)
    elseif phase == "remove" then
        label = scan.phase_label or "Removing library folder"
        detail = state.canonical_user_data.status
            or scan.phase_detail or "Cleaning database records"
    elseif phase == "compact_prepare" then
        label = "Preparing database compaction"
        detail = scan.phase_detail or "Closing the database reader"
    elseif phase == "compact" then
        local database = state.database
        local stage_order = {checkpoint = 1, vacuum = 2, optimize = 3}
        local stage_labels = {
            checkpoint = "Preparing database",
            vacuum = "Reclaiming unused space",
            optimize = "Optimizing indexes",
        }
        local stage = database.write_progress_stage
        label = "Compacting database"
        detail = database.write_progress_label
            or (stage and (stage_labels[stage] or stage))
            or "Starting database maintenance"
        done = database.write_progress_done or 0
        total = database.write_progress_total or 0
        if stage then
            local stage_index = stage_order[stage] or 1
            local stage_fraction = total > 0
                and math.max(0, math.min(1, done / total)) or 0
            fraction = ((stage_index - 1) + stage_fraction) / 3
            detail = detail .. "; elapsed " .. FormatLibraryScanElapsed(
                r.time_precise() - (scan.phase_started_at or r.time_precise()))
        end
    elseif phase == "commit" then
        local database = state.database
        local stage_order = {
            manifest = 1, roots = 2, files = 3, memberships = 4,
            classification = 5, indexes = 6, commit = 7,
        }
        label = database.write_progress_stage
            and ("Writing database: " .. database.write_progress_stage)
            or "Writing database"
        done = database.write_progress_done or 0
        total = database.write_progress_total or 0
        detail = database.write_progress_stage
            and string.format("step %d / 7; %d / %d records; %s; %s in this step",
                stage_order[database.write_progress_stage] or 1,
                done, total,
                database.write_progress_label or "working",
                FormatLibraryScanElapsed(r.time_precise()
                    - (database.write_progress_stage_started_at
                        or r.time_precise())))
            or string.format("database write starting; %s",
                state.canonical_scan_sync.status or "working")
        if database.write_progress_stage then
            local stage_index = stage_order[database.write_progress_stage] or 1
            local stage_fraction = total > 0
                and math.max(0, math.min(1, done / total))
                or 0
            fraction = ((stage_index - 1) + stage_fraction) / 7
        end
    elseif phase == "finalize_db" then
        label = scan.phase_label or "Finalizing browser"
        done = scan.phase_done or 0
        total = scan.phase_total or 1
        detail = scan.phase_detail or "Refreshing database and navigation"
    else
        label = "Working"
        detail = state.canonical_scan_sync.status or "Please wait"
    end
    if not fraction and total and total > 0 then
        fraction = math.max(0, math.min(1, (done or 0) / total))
    end
    return label, detail, done, total, fraction
end

DrawLibraryScanProgressPanel = function()
    local scan = state.library_scan
    local label, detail, done, total, fraction = GetLibraryScanProgress()
    local elapsed = FormatLibraryScanElapsed(
        r.time_precise() - (scan.started_at or r.time_precise()))
    imgui.Spacing(ctx)
    local operation_title = scan.operation_kind == "remove"
        and "Removing library folder"
        or scan.operation_kind == "compact"
        and "Database maintenance in progress"
        or "Library update in progress"
    imgui.Text(ctx, operation_title)
    imgui.TextDisabled(ctx,
        "Browsing returns when the database and navigation are fully ready.")
    imgui.Spacing(ctx)
    imgui.Text(ctx, label)
    imgui.TextDisabled(ctx, detail)
    if fraction then
        if imgui.ProgressBar then
            imgui.ProgressBar(ctx, fraction, -1, 0,
                FormatLibraryProgressCaption(done, total, fraction))
        else
            imgui.TextDisabled(ctx, "Progress: "
                .. FormatLibraryProgressCaption(done, total, fraction))
        end
    elseif imgui.ProgressBar then
        local pulse = 0.15 + 0.70 *
            ((math.sin(r.time_precise() * 3.0) + 1) * 0.5)
        imgui.ProgressBar(ctx, pulse, -1, 0, "Working...")
    end
    imgui.TextDisabled(ctx, "Elapsed: " .. elapsed)
    imgui.Spacing(ctx)
    if scan.operation_kind ~= "scan"
        or scan.phase == "commit" or scan.phase == "finalize_db" then
        imgui.TextDisabled(ctx,
            "This database step cannot be interrupted; finishing safely.")
    elseif imgui.Button(ctx, "Cancel##library_scan_progress", 100, 0) then
        CancelLibraryScan()
    end
end

function DrawLibraryScanSnapshotBanner()
    if not state.library_scan.scanning
        or state.library_scan.browser_blocked then
        return
    end
    local label, _, done, total, fraction = GetLibraryScanProgress()
    local caption = "Updating library in background: " .. tostring(label)
    if total and total > 0 then
        caption = caption .. "  "
            .. FormatLibraryProgressCaption(done, total, fraction or 0)
    end
    imgui.TextDisabled(ctx, caption)
    if state.library_scan.operation_kind == "scan"
        and state.library_scan.phase ~= "commit"
        and state.library_scan.phase ~= "finalize_db" then
        imgui.SameLine(ctx)
        if imgui.SmallButton(ctx, "Cancel##library_scan_snapshot") then
            CancelLibraryScan()
        end
    end
    imgui.Separator(ctx)
end

function DrawCanonicalMainBrowser(avail_h)
    local browser = state.canonical_browser
    local active_collection_key = browser.smart_mode == "smart_collection"
        and browser.collection_key or browser.collection_scope_key
    if state.suppress_mouse_hover then
        local mouse_x, mouse_y = imgui.GetMousePos(ctx)
        local moved = math.abs(
            mouse_x - (state.suppress_hover_mouse_x or mouse_x)) > 1
            or math.abs(mouse_y
                - (state.suppress_hover_mouse_y or mouse_y)) > 1
        if moved or imgui.IsMouseClicked(ctx, 0)
            or imgui.IsMouseClicked(ctx, 1) then
            state.suppress_mouse_hover = false
        end
    end
    state.next_hovered_path = nil
    state.next_hovered_row_key = nil
    state.next_hovered_favorite_instance_key = nil

    if not state.library_scan.browser_blocked then
        if browser._search_input_source ~= state.search_input then
            browser._search_input_source = state.search_input
            browser._normalized_search_input =
                NormalizeTag(state.search_input or "")
        end
        local requested_search = browser._normalized_search_input or ""
        if requested_search ~= (browser.search_text or "")
            and ((browser.search_commit_requested == true)
                or (r.time_precise() - (state.last_search_time or 0)) > 0.15)
            and not state.database.write_active then
            browser.search_commit_requested = false
            if requested_search ~= "" then
                CaptureCanonicalAccordionReturnState()
            end
            local restore_accordion = requested_search == ""
                and not CanonicalBrowserHasStructuredFilters()
                and not browser.smart_mode
            browser.search_text = requested_search
            ResetCanonicalRandomState()
            PrepareCanonicalTagCatalogRefresh()
            browser.offset = 0
            browser.selected_path = nil
            state.multi_selected = {}
            state.selected_file_row_keys = {}
            state.selection_anchor = nil
            state.selection_anchor_row_key = nil
            state.pending_single_node = nil
            state.pending_single_row_key = nil
            state.pending_ctrl_file = nil
            if restore_accordion then
                browser.loading = false
                browser.rows = {}
                RestoreCanonicalAccordionReturnState()
            else
                RequestCanonicalBrowserPage(
                    CanonicalBrowserCurrentMode(),
                    browser.current_folder_id, 0, false, false)
            end
        elseif requested_search == (browser.search_text or "") then
            browser.search_commit_requested = false
        end
    end

    if not imgui.BeginChild(
        ctx, "browser_pane", 0, avail_h,
        FLG_CHILD_BORDER,
        FLG_NO_NAV_INPUTS | FLG_NO_SCROLLBAR | FLG_NO_SCROLL_MOUSE) then
        state.hovered_path = nil
        state.hovered_row_key = nil
        return
    end
    if state.library_scan.browser_blocked then
        DrawLibraryScanProgressPanel()
        imgui.EndChild(ctx)
        state.hovered_path = nil
        state.hovered_row_key = nil
        return
    end
    DrawLibraryScanSnapshotBanner()
    local wheel = imgui.GetMouseWheel and imgui.GetMouseWheel(ctx) or 0
    if wheel ~= 0 and imgui.IsWindowHovered(ctx) then
        state.suppress_mouse_hover = true
        state.hovered_path = nil
        state.suppress_hover_mouse_x,
            state.suppress_hover_mouse_y = imgui.GetMousePos(ctx)
    end
    DrawUnifiedBrowserNavigation()
    if state.library_scan.scanning then
        local scan_label, scan_detail, scan_done, scan_total,
            scan_fraction = GetLibraryScanProgress()
        imgui.TextDisabled(ctx, scan_label .. " - " .. scan_detail)
        if scan_fraction and imgui.ProgressBar then
            imgui.ProgressBar(ctx, scan_fraction, -1, 0,
                FormatLibraryProgressCaption(
                    scan_done, scan_total, scan_fraction))
        end
    end
    if browser.loading then
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx,
            browser.search_text ~= "" and " Searching..."
                or (#browser.rows == 0 and " Loading library..." or " Loading..."))
    end
    if browser.error then
        imgui.TextDisabled(ctx, " Library page could not be loaded.")
        if imgui.IsItemHovered(ctx) then
            imgui.SetTooltip(ctx, tostring(browser.error))
        end
    end
    imgui.Separator(ctx)

    if not imgui.BeginChild(
        ctx, "##canonical_main_scroll_rows", 0, 0, 0,
        FLG_NO_NAV_INPUTS) then
        imgui.EndChild(ctx)
        state.hovered_path = nil
        state.hovered_row_key = nil
        return
    end

    if (browser.window_start_offset or 0) > 0 then
        local previous_offset = math.max(0,
            (browser.window_start_offset or 0)
                - (state.canonical_paging.page_size or 100))
        imgui.Dummy(ctx, 1, 3)
        imgui.PushStyleColor(ctx, imgui.Col_Text, 0xFFFFFFFF)
        imgui.PushStyleColor(ctx, imgui.Col_Button,
            (((state.resolved_theme and state.resolved_theme.accent)
                or state.theme.colors.accent) & 0xFFFFFF00) | 0x58)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
            (((state.resolved_theme and state.resolved_theme.accent)
                or state.theme.colors.accent) & 0xFFFFFF00) | 0x78)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
            (((state.resolved_theme and state.resolved_theme.accent)
                or state.theme.colors.accent) & 0xFFFFFF00) | 0x98)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 8, 5)
        if imgui.Button(ctx,
            state.favorites_mode
                and "\226\134\145  Load earlier favorite files##canonical_previous_window"
                or "\226\134\145  Load earlier library files##canonical_previous_window",
            select(1, imgui.GetContentRegionAvail(ctx)), 0)
            and not browser.loading then
            browser.loading = true
            browser.pending_prefetch = nil
            browser.offset = previous_offset
            RequestCanonicalBrowserPage(
                CanonicalBrowserCurrentMode(), browser.current_folder_id,
                previous_offset, false, false)
        end
        if imgui.IsItemHovered(ctx) then
            imgui.SetTooltip(ctx,
                "Older rows were released to keep memory usage bounded.")
        end
        imgui.PopStyleVar(ctx)
        imgui.PopStyleColor(ctx, 4)
        imgui.Dummy(ctx, 1, 3)
    end

    local suppress_hover_style = state.suppress_mouse_hover == true
    if suppress_hover_style then
        imgui.PushStyleColor(ctx, imgui.Col_HeaderHovered, 0x00000000)
    end

    if browser._visible_rows_source ~= browser.rows
        or browser._visible_rows_scope ~= active_collection_key
        or browser._visible_rows_count ~= #browser.rows then
        local visible_items = {}
        local visible_index = {}
        local visible_index_by_row_key = {}
        for row_index, row in ipairs(browser.rows or {}) do
            local is_folder = row.kind == "R" or row.kind == "D"
            local node = row._main_node
            if not node then
                node = {
                    path = row.path,
                    name = row.name,
                    is_folder = is_folder,
                    _canonical_folder_id = is_folder and row.folder_id or nil,
                }
                row._main_node = node
            end
            node._canonical_row = row
            if state.favorites_mode and active_collection_key then
                node._favorite_collection_id = active_collection_key
            else
                node._favorite_collection_id = nil
            end
            if not is_folder and (browser.smart_mode == "smart_favorites"
                or browser.smart_mode == "smart_collection") then
                node._canonical_favorite = true
            end
            local row_key = not is_folder
                and GetMediaRowSelectionKey(
                    node, "main:" .. tostring(row.id)
                        .. ":" .. tostring(row_index))
                or nil
            row._selection_key = row_key
            node._visible_row_key = row_key
            if is_folder then
                row._tree_label = node.name
                    .. "##db_main_folder_" .. tostring(row.id)
            else
                row._tree_label = node.name
                    .. "##db_main_file_" .. tostring(row.id)
                    .. "_" .. tostring(row_index)
            end
            visible_items[#visible_items + 1] = {
                type = is_folder and "folder" or "file",
                path = node.path, node = node, depth = 0,
                row_key = row_key,
            }
            if not visible_index[node.path] then
                visible_index[node.path] = #visible_items
            end
            if row_key then
                visible_index_by_row_key[row_key] = #visible_items
            end
        end
        browser._visible_rows_source = browser.rows
        browser._visible_rows_scope = active_collection_key
        browser._visible_rows_count = #browser.rows
        browser._visible_items = visible_items
        browser._visible_index = visible_index
        browser._visible_index_by_row_key = visible_index_by_row_key
    end
    local visible_items = browser._visible_items or {}
    local visible_index = browser._visible_index or {}
    state.visible_items = visible_items
    state.visible_index_by_path = visible_index
    state.visible_index_by_row_key = browser._visible_index_by_row_key or {}
    local folder_text_color = GetFolderTextColor()
    local selected_text_color = GetSelectedTextColor()

    local function DrawCanonicalBrowserRow(index)
        local row = browser.rows[index]
        if not row then return end
        local is_folder = row.kind == "R" or row.kind == "D"
        if is_folder then
            local node = row._main_node
            if not node then
                node = {
                    path = row.path,
                    name = row.name,
                    is_folder = true,
                    _canonical_is_library_root = row.kind == "R",
                    _canonical_folder_id = row.folder_id,
                }
                row._main_node = node
            end
            if state.favorites_mode and active_collection_key then
                node._favorite_collection_id = active_collection_key
            else
                node._favorite_collection_id = nil
            end
            local selected = state.cursor_type == "folder"
                and state.cursor_path == node.path
            local flags = FLG_SPAN_WIDTH
                | imgui.TreeNodeFlags_OpenOnArrow
            if selected then flags = flags | imgui.TreeNodeFlags_Selected end
            imgui.PushStyleColor(ctx, imgui.Col_Text, folder_text_color)
            local heart_hot, heart_hover_style, heart_indent =
                PrepareFavoriteRowHeart(node)
            local tree_label = tostring(row._tree_label or "")
            if tree_label == "" or tree_label == "##" then
                tree_label = tostring(node.name or node.path or "Folder")
                    .. "##db_main_folder_" .. tostring(row.id or index)
                row._tree_label = tree_label
            end
            local opened = imgui.TreeNode(
                ctx, tree_label, flags)
            if heart_hover_style then imgui.PopStyleColor(ctx) end
            if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
            local heart_clicked = DrawFavoriteRowHeart(node, heart_hot)
            local clicked = imgui.IsItemClicked(ctx, 0)
            local hovered = imgui.IsItemHovered(ctx)
            if state.favorites_mode
                and imgui.BeginPopupContextItem(
                    ctx, "##db_favorite_folder_context_"
                        .. tostring(row.id)) then
                state.context_menu_active = true
                DrawRevealFolderInExplorerMenuItem(node)
                imgui.Separator(ctx)
                local collection_id = GetFavoriteContextCollectionId(node)
                if imgui.MenuItem(ctx, collection_id
                    and "Remove from this Favorites folder"
                    or "Remove from Favorites") then
                    if collection_id then
                        RemoveFavoriteCollectionMembership(node.path, collection_id)
                    else
                        RemoveFavorite(node.path, "folder")
                    end
                end
                imgui.EndPopup(ctx)
            end
            if not state.favorites_mode
                and imgui.BeginPopupContextItem(
                ctx, "##db_main_folder_context_" .. tostring(row.id)) then
                state.context_menu_active = true
                local scope_type = row.kind == "R" and "root" or "folder"
                DrawRevealFolderInExplorerMenuItem(node)
                imgui.Separator(ctx)
                if imgui.BeginMenu(ctx, "Category") then
                    imgui.TextDisabled(ctx, "Applies to this folder and descendants")
                    local current_override, current_scope =
                        GetManualOverrideInfo(node.path)
                    imgui.TextDisabled(ctx,
                        "Current override: "
                            .. (current_override
                                and ClassificationLabel(current_override)
                                    .. " (" .. current_scope .. ")"
                                or "None"))
                    for _, option in ipairs({
                        {key = "loop", label = "Loop"},
                        {key = "one-shot", label = "One-shot"},
                        {key = "uncategorized", label = "Other"},
                    }) do
                        local current_category =
                            GetManualCategoryKey(node.path)
                        local effective_option = option.key == "uncategorized"
                            and "other" or option.key
                        local option_label =
                            (current_category == effective_option
                                and "[x] " or "") .. option.label
                        if imgui.MenuItem(ctx, option_label) then
                            QueueClassificationOverride(
                                scope_type, node.path, option.key)
                        end
                    end
                    imgui.Separator(ctx)
                    if imgui.MenuItem(ctx, "Clear This Folder Override") then
                        ClearClassificationOverride(
                            scope_type, node.path, false, false)
                    end
                    if imgui.MenuItem(ctx,
                        "Clear Folder and Subfolder Overrides") then
                        ClearClassificationOverride(
                            scope_type, node.path, true, false)
                    end
                    if imgui.MenuItem(ctx,
                        "Clear Overrides in Folder, Subfolders, and Files") then
                        ClearClassificationOverride(
                            scope_type, node.path, true, true)
                    end
                    imgui.EndMenu(ctx)
                end
                if row.kind == "R" then
                    imgui.Separator(ctx)
                    local scan_disabled = RootLibraryActionsBlocked()
                    local disabled_scope = false
                    if scan_disabled and imgui.BeginDisabled then
                        imgui.BeginDisabled(ctx, true)
                        disabled_scope = true
                    end
                    if imgui.MenuItem(ctx, T("check_folder_changes"))
                        and not scan_disabled then
                        StartLibraryScan(node.path)
                    end
                    if disabled_scope then imgui.EndDisabled(ctx) end
                end
                imgui.EndPopup(ctx)
            end
            imgui.PopStyleColor(ctx)
            -- Folder navigation is safe while another page is loading:
            -- RequestCanonicalBrowserPage queues the newest foreground target.
            -- Ignoring the click here made some Library folders appear dead
            -- immediately after rebuilds or during the first page transition.
            if clicked and not heart_clicked
                and not state.block_browser_input then
                state.cursor_path = node.path
                state.cursor_type = "folder"
                EnterCanonicalBrowserFolder(row)
            end
            if hovered then
                state.next_hovered_path = node.path
                state.next_hovered_row_key = nil
            end
            if opened then imgui.TreePop(ctx) end
        else
            local node = row._main_node
            if not node then
                node = {
                    path = row.path,
                    name = row.name,
                    is_folder = false,
                }
                row._main_node = node
            end
            if state.favorites_mode and active_collection_key then
                node._favorite_collection_id = active_collection_key
            else
                node._favorite_collection_id = nil
            end
            local row_key = row._selection_key
                or GetMediaRowSelectionKey(node,
                    "main:" .. tostring(row.id) .. ":" .. tostring(index))
            local selected = IsMediaFileRowSelected(node, row_key)
            local hovered = IsMediaFileRowHovered(node, row_key)
            local flags = imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
            if selected then flags = flags | imgui.TreeNodeFlags_Selected end
            if selected or hovered then
                imgui.PushStyleColor(
                    ctx, imgui.Col_Text, selected_text_color)
            end
            local heart_hot, heart_hover_style, heart_indent =
                PrepareFavoriteRowHeart(node)
            local tree_label = tostring(row._tree_label or "")
            if tree_label == "" or tree_label == "##" then
                tree_label = tostring(node.name or node.path or "File")
                    .. "##db_main_file_" .. tostring(row.id or index)
                    .. "_" .. tostring(index)
                row._tree_label = tree_label
            end
            local opened = imgui.TreeNode(
                ctx, tree_label, flags)
            if heart_hover_style then imgui.PopStyleColor(ctx) end
            if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
            local heart_clicked = DrawFavoriteRowHeart(
                node, heart_hot, row_key)
            local interaction = CaptureBrowserRowInteraction(row_key)
            if selected or hovered then imgui.PopStyleColor(ctx) end
            if state.scroll_to_cursor and state.cursor_path == node.path then
                imgui.SetScrollHereY(ctx, 0.35)
                state.scroll_to_cursor = false
            end
            HandleFileInteraction(node, heart_clicked, interaction)
            if opened then imgui.TreePop(ctx) end
        end
    end

    -- Category, key, and search pages share this renderer. Clip even modest
    -- result sets so filtered mode never submits a full 100-row page merely
    -- because the viewport is tall or the first page is still loading.
    if #(browser.rows or {}) > 24 then
        if not browser.clipper then
            browser.clipper = imgui.CreateListClipper(ctx)
            if imgui.Attach then imgui.Attach(ctx, browser.clipper) end
        end
        -- Row interaction can invalidate browser.clipper (for example a
        -- Favorites mutation resets the foreground view) while this render
        -- loop is still stepping it. Keep the frame's native pointer local;
        -- never read the mutable field from inside the Step loop.
        local clipper = browser.clipper
        local clipper_ok = pcall(
            imgui.ListClipper_Begin, clipper, #browser.rows)
        if not clipper_ok then
            clipper = imgui.CreateListClipper(ctx)
            browser.clipper = clipper
            if imgui.Attach then imgui.Attach(ctx, clipper) end
            clipper_ok = pcall(
                imgui.ListClipper_Begin, clipper, #browser.rows)
        end
        if clipper_ok then
            if state.scroll_to_cursor and state.cursor_path
                and imgui.ListClipper_IncludeItemByIndex then
                local selected_index = visible_index[state.cursor_path]
                if selected_index then
                    pcall(imgui.ListClipper_IncludeItemByIndex,
                        clipper, selected_index - 1)
                end
            end
            while imgui.ListClipper_Step(clipper) do
                local first, last =
                    imgui.ListClipper_GetDisplayRange(clipper)
                for index = first + 1, last do
                    DrawCanonicalBrowserRow(index)
                end
            end
        else
            browser.clipper = nil
            for index = 1, #browser.rows do
                DrawCanonicalBrowserRow(index)
            end
        end
    else
        for index = 1, #(browser.rows or {}) do
            DrawCanonicalBrowserRow(index)
        end
    end

    if browser.has_more then
        imgui.Dummy(ctx, 1, 1)
    end

    if imgui.GetScrollY and imgui.GetScrollMaxY then
        local scroll_y = imgui.GetScrollY(ctx)
        local scroll_max = imgui.GetScrollMaxY(ctx)
        if browser.scroll_rebase_pending
            and not (imgui.IsMouseDown and imgui.IsMouseDown(ctx, 0)) then
            scroll_y = math.max(0, scroll_max * 0.67)
            imgui.SetScrollY(ctx, scroll_y)
            browser.scroll_rebase_pending = false
        end
        local near_page_end = scroll_max > 0
            and scroll_y >= scroll_max - 120
        if near_page_end
            and not browser.loading
            and not (imgui.IsMouseDown and imgui.IsMouseDown(ctx, 0)) then
            LoadNextCanonicalBrowserPage()
        end
    end
    DrawFavoritesRootContextMenu()
    if not state.block_browser_input and imgui.IsWindowHovered(ctx)
        and imgui.IsMouseClicked(ctx, 0)
        and not imgui.IsAnyItemHovered(ctx) then
        -- Blank space in a flat search/filter result clears only the selected
        -- file. The query, key/type/tag filters and Favorites scope remain
        -- active until the user explicitly changes or clears them.
        ClearMediaFileSelection()
    end
    if not state.search_active then HandleBrowserKeys() end
    if suppress_hover_style then imgui.PopStyleColor(ctx) end
    imgui.EndChild(ctx)
    imgui.EndChild(ctx)
    state.hovered_path = state.suppress_mouse_hover
        and nil or state.next_hovered_path
    state.hovered_row_key = state.suppress_mouse_hover
        and nil or state.next_hovered_row_key
    state.hovered_favorite_instance_key = nil
end

function DrawAccordionBrowser(avail_h)
    state.accordion_page_load_suppressed = false
    local popup_was_active = state.context_menu_active == true
    state.context_menu_active = false
    state.block_browser_input = PreviewPaneOwnsMouseInput()
        or popup_was_active
    if state.block_browser_input then
        CancelPendingMediaRowActivation()
    end
    if CanonicalResultViewActive() then
        DrawCanonicalMainBrowser(avail_h)
        return
    end
    if state._accordion_search_input_source ~= state.search_input then
        state._accordion_search_input_source = state.search_input
        state._accordion_search_input_lower =
            (state.search_input or ""):lower()
    end
    local accordion_search = state._accordion_search_input_lower or ""
    if accordion_search ~= state.search_text then
        if (r.time_precise() - state.last_search_time) > 0.15 then
            state.search_text = accordion_search
            state.force_search_update = true
            state.needs_visible_update = true
        end
    end

    if state.needs_visible_update then BuildVisibleItems() end
    if state.suppress_mouse_hover then
        local mouse_x, mouse_y = imgui.GetMousePos(ctx)
        if math.abs(mouse_x - (state.suppress_hover_mouse_x or mouse_x)) > 1
            or math.abs(mouse_y
                - (state.suppress_hover_mouse_y or mouse_y)) > 1 then
            state.suppress_mouse_hover = false
        end
    end
    state.next_hovered_path = nil
    state.next_hovered_row_key = nil
    state.next_hovered_favorite_instance_key = nil

    if not imgui.BeginChild(
        ctx, "browser_pane", 0, avail_h,
        FLG_CHILD_BORDER,
        FLG_NO_NAV_INPUTS | FLG_NO_SCROLLBAR | FLG_NO_SCROLL_MOUSE) then
        state.hovered_path = nil
        state.hovered_row_key = nil
        return
    end
    if state.library_scan.browser_blocked then
        DrawLibraryScanProgressPanel()
        imgui.EndChild(ctx)
        state.hovered_path = nil
        state.hovered_row_key = nil
        return
    end
    DrawLibraryScanSnapshotBanner()
    if state.database_startup_test.enabled then
        DrawUnifiedBrowserNavigation()
        imgui.Separator(ctx)
    end
    if not imgui.BeginChild(
        ctx, "accordion_browser_scroll", 0, 0,
        0, FLG_NO_NAV_INPUTS) then
        imgui.EndChild(ctx)
        return
    end
    if imgui.GetMouseWheel and imgui.IsWindowHovered(ctx) then
        local accordion_wheel = imgui.GetMouseWheel(ctx) or 0
        if accordion_wheel ~= 0 then
            -- Manual scrolling owns the viewport. Do not let a delayed cursor
            -- reveal pull it back down on the first upward gesture.
            state.scroll_to_cursor = false
            if accordion_wheel > 0 then
                state.accordion_page_load_suppressed = true
            end
        end
    end
    local selected_text_color = GetSelectedTextColor()
    local folder_text_color = GetFolderTextColor()
    local accordion_page_candidate = nil
    if not state.search_active then HandleBrowserKeys() end
    if state.library_scan.scanning then
        local scan_label, scan_detail, scan_done, scan_total,
            scan_fraction = GetLibraryScanProgress()
        imgui.TextDisabled(ctx, scan_label .. " - " .. scan_detail)
        if scan_fraction and imgui.ProgressBar then
            imgui.ProgressBar(ctx, scan_fraction, -1, 0,
                FormatLibraryProgressCaption(
                    scan_done, scan_total, scan_fraction))
        end
        imgui.SameLine(ctx)
        if state.library_scan.phase ~= "commit"
            and state.library_scan.phase ~= "finalize_db"
            and imgui.SmallButton(ctx, "Cancel##library_scan") then
            CancelLibraryScan()
        end
        imgui.Separator(ctx)
        if state.library_scan.progressive then
            imgui.TextDisabled(
                ctx,
                state.library_scan.phase == "folders"
                    and " Building the complete folder structure first."
                    or state.library_scan.phase == "finalize"
                    and " Finishing in the background."
                    or " Files appear progressively as they are discovered."
            )
            if state.library_scan.phase == "folders" then
                state.hovered_path = nil
                state.hovered_row_key = nil
                imgui.EndChild(ctx)
                imgui.EndChild(ctx)
                return
            end
        end
    end
    if state.library_cache_save.active
        and not state.library_scan.scanning then
        imgui.TextDisabled(ctx, " Saving library for fast startup...")
        imgui.Separator(ctx)
    end
    if state.media_filter_index.building
        and not state.library_scan.scanning then
        local filter_index = state.media_filter_index
        imgui.TextDisabled(ctx, string.format(
            filter_index.build_mode == "append"
                and " Adding new files to filters... %d"
                or " Optimizing filters... %d files",
            filter_index.build_mode == "append"
                and (filter_index.session_count or 0)
                or (filter_index.indexed_count or 0)))
        imgui.Separator(ctx)
    end
    if state.favorites_mode then
        if imgui.Selectable(
            ctx, "Recent##favorite_smart_recent",
            state.favorite_smart_mode == "smart_recent"
                and state.canonical_browser.smart_mode == "smart_recent") then
            OpenFavoriteSmartFolder("smart_recent", "Recent")
        end
        if imgui.Selectable(
            ctx, "Most Used##favorite_smart_used",
            state.favorite_smart_mode == "smart_used"
                and state.canonical_browser.smart_mode == "smart_used") then
            OpenFavoriteSmartFolder("smart_used", "Most Used")
        end
        DrawFavoritesLibraryRootRow()
        imgui.Separator(ctx)
    end
    if state.favorites_mode and #state.favorite_tree == 0 then
        if state.database_startup_test.enabled then
            imgui.TextDisabled(ctx, " Loading favorites...")
        else
            imgui.TextDisabled(
                ctx, " No favorites yet.\n Drag a MIDI file or folder onto the heart.")
        end
    elseif not state.favorites_mode and #state.root_folders == 0 then
        imgui.TextDisabled(ctx, " No folders added.\n Click '+ Add folder' above.")
    end

    if state.search_text ~= "" or MediaFiltersActive() then
        local results = GetCachedSearchResults()
        if not state.clipper then
            state.clipper = imgui.CreateListClipper(ctx)
            imgui.Attach(ctx, state.clipper)
        end
        
        imgui.ListClipper_Begin(state.clipper, #results)

        if state.scroll_to_cursor then
            local cached_index = state.search_index_by_path[state.cursor_path]
            local target_idx = cached_index and (cached_index - 1) or nil
            if target_idx then
                if imgui.ListClipper_IncludeItemByIndex then
                    pcall(imgui.ListClipper_IncludeItemByIndex, state.clipper, target_idx)
                else
                    local item_y = target_idx * imgui.GetTextLineHeightWithSpacing(ctx)
                    imgui.SetScrollY(ctx, item_y - (imgui.GetWindowHeight(ctx) * 0.3))
                end
            end
        end

        while imgui.ListClipper_Step(state.clipper) do
            local dmin, dmax = imgui.ListClipper_GetDisplayRange(state.clipper)
            for i = dmin + 1, dmax do
                local f = results[i]
                local flags = imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
                local row_key = f._visible_row_key
                    or GetMediaRowSelectionKey(
                        f, "result:" .. tostring(i))
                local is_selected = IsMediaFileRowSelected(f, row_key)
                local is_hovered = IsMediaFileRowHovered(f, row_key)

                if is_selected then flags = flags | imgui.TreeNodeFlags_Selected end
                if is_selected or is_hovered then 
                    imgui.PushStyleColor(ctx, imgui.Col_Text, selected_text_color)
                end
                
                local heart_hot, heart_hover_style, heart_indent =
                    PrepareFavoriteRowHeart(f)
                local is_open = imgui.TreeNode(
                    ctx, GetFavoriteDisplayName(f) .. "##media_search_" .. row_key,
                    flags)
                if heart_hover_style then imgui.PopStyleColor(ctx) end
                if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
                local heart_clicked = DrawFavoriteRowHeart(
                    f, heart_hot, row_key)
                local interaction = CaptureBrowserRowInteraction(row_key)
                
                if is_selected or is_hovered then imgui.PopStyleColor(ctx) end
                
                if state.scroll_to_cursor and state.cursor_path == f.path then 
                    imgui.SetScrollHereY(ctx, 0.3)
                    state.scroll_to_cursor = false 
                end

                HandleFileInteraction(f, heart_clicked, interaction)
                if is_open then imgui.TreePop(ctx) end
            end
        end
    else
        local suppress_hover_style = state.suppress_mouse_hover == true
        if suppress_hover_style then
            imgui.PushStyleColor(
                ctx, imgui.Col_HeaderHovered, 0x00000000)
        end
        local function DrawLooseFavoriteFiles(container)
            if container and not container._canonical_started
                and not container._canonical_loading
                and CanonicalUserDataQueueCount(
                    state.canonical_user_data) == 0
                and #(state.canonical_user_data.inflight or {}) == 0 then
                LoadCanonicalAccordionFolder(container)
            end
            local files = container and container.files or {}
            if container
                and (container._canonical_window_start_offset or 0) > 0 then
                imgui.Dummy(ctx, 1, 3)
                imgui.PushStyleColor(ctx, imgui.Col_Text, 0xFFFFFFFF)
                imgui.PushStyleColor(ctx, imgui.Col_Button,
                    (((state.resolved_theme and state.resolved_theme.accent)
                        or state.theme.colors.accent) & 0xFFFFFF00) | 0x58)
                imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
                    (((state.resolved_theme and state.resolved_theme.accent)
                        or state.theme.colors.accent) & 0xFFFFFF00) | 0x78)
                imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
                    (((state.resolved_theme and state.resolved_theme.accent)
                        or state.theme.colors.accent) & 0xFFFFFF00) | 0x98)
                imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 8, 5)
                if imgui.Button(ctx,
                    "\226\134\145  Load earlier favorite files##favorite_root_previous",
                    select(1, imgui.GetContentRegionAvail(ctx)), 0)
                    and not container._canonical_loading then
                    LoadPreviousCanonicalAccordionPage(container)
                end
                if imgui.IsItemHovered(ctx) then
                    imgui.SetTooltip(ctx,
                        "Older rows were released to keep memory bounded.")
                end
                imgui.PopStyleVar(ctx)
                imgui.PopStyleColor(ctx, 4)
                imgui.Dummy(ctx, 1, 3)
            end
            if #files == 0 then
                if container and container._canonical_loading then
                    imgui.Dummy(ctx, 1, 1)
                end
                return
            end
            local clipper = state.folder_clippers.__favorite_root_files
            if not clipper then
                clipper = imgui.CreateListClipper(ctx)
                imgui.Attach(ctx, clipper)
                state.folder_clippers.__favorite_root_files = clipper
            end
            imgui.ListClipper_Begin(clipper, #files)
            if state.scroll_to_cursor
                and imgui.ListClipper_IncludeItemByIndex then
                for index, file in ipairs(files) do
                    if file.path == state.cursor_path then
                        pcall(imgui.ListClipper_IncludeItemByIndex,
                            clipper, index - 1)
                        break
                    end
                end
            end
            while imgui.ListClipper_Step(clipper) do
                local first, last = imgui.ListClipper_GetDisplayRange(clipper)
                for index = first + 1, last do
                    local file = files[index]
                    if not file then break end
                    local row_key = file._visible_row_key
                        or GetMediaRowSelectionKey(
                            file, "favorite_root:" .. tostring(index))
                    local selected = IsMediaFileRowSelected(file, row_key)
                    local hovered = IsMediaFileRowHovered(file, row_key)
                    local flags = imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
                    if selected then flags = flags | imgui.TreeNodeFlags_Selected end
                    if selected or hovered then
                        imgui.PushStyleColor(
                            ctx, imgui.Col_Text, selected_text_color)
                    end
                    local heart_hot, heart_hover_style, heart_indent =
                        PrepareFavoriteRowHeart(file)
                    local opened = imgui.TreeNode(
                        ctx, GetFavoriteDisplayName(file)
                            .. "##media_favorite_root_" .. row_key, flags)
                    if heart_hover_style then imgui.PopStyleColor(ctx) end
                    if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
                    local heart_clicked = DrawFavoriteRowHeart(
                        file, heart_hot, row_key)
                    local interaction = CaptureBrowserRowInteraction(row_key)
                    if selected or hovered then imgui.PopStyleColor(ctx) end
                    if state.scroll_to_cursor
                        and state.cursor_path == file.path then
                        imgui.SetScrollHereY(ctx, 0.3)
                        state.scroll_to_cursor = false
                    end
                    HandleFileInteraction(file, heart_clicked, interaction)
                    if opened then imgui.TreePop(ctx) end
                end
            end
            if container._canonical_has_more then
                accordion_page_candidate = container
                imgui.Dummy(ctx, 1, 1)
            end
        end
        local function DrawNode(node)
            if not node then return end
            if not state.favorites_mode
                and state.database_startup_test.enabled
                and node.parent == nil
                and node._canonical_is_library_root ~= true then
                -- Canonical Library top-level rows must come from a database
                -- kind="R" row. Never render reconstructed/misclassified
                -- child folders as temporary roots during startup handoff.
                return
            end
            local open_map = state.favorites_mode
                and state.favorite_open_folders or state.open_folders
            local instance_key = GetFolderUIKey(node)
            local was_open = open_map[instance_key] == true
            -- An unfinished directory is never a leaf: its children/files may
            -- still be arriving from the incremental startup scan.
            local is_leaf = not node.is_collection
                and node._scan_complete ~= false
                and node._canonical_loaded ~= false
                and (#node.children == 0 and #node.files == 0)
            local node_flags = FLG_SPAN_WIDTH
            local is_selected = IsFolderCursorNode(node)
            local is_hovered = not state.suppress_mouse_hover
                and (state.hovered_path == node.path)
                and (not state.favorites_mode
                    or state.hovered_favorite_instance_key == instance_key)
            
            if is_leaf then
                node_flags = node_flags | imgui.TreeNodeFlags_Leaf
            end
            -- The row spans the browser width for selection highlighting,
            -- but only the disclosure arrow may toggle folder expansion.
            -- This prevents a manual heart-gutter click from also toggling
            -- the underlying TreeNode.
            if not is_leaf then
                node_flags = node_flags | imgui.TreeNodeFlags_OpenOnArrow
            end
            if is_selected then node_flags = node_flags | imgui.TreeNodeFlags_Selected end

            imgui.SetNextItemOpen(ctx, open_map[instance_key] == true)
            
            if is_selected or is_hovered then
                imgui.PushStyleColor(ctx, imgui.Col_Text, 0xFFFFFFFF)
            else
                imgui.PushStyleColor(ctx, imgui.Col_Text, folder_text_color)
            end
            
            local heart_hot, heart_hover_style, heart_indent =
                PrepareFavoriteRowHeart(node)
            local is_open = imgui.TreeNode(ctx,
                GetFavoriteDisplayName(node)
                .. "##" .. instance_key, node_flags)
            -- Capture the TreeNode rectangle before any later drawing changes
            -- the current-item state. ReaImGui may suppress IsItemHovered
            -- while another row owns the active mouse drag, but a manual
            -- rectangle test remains reliable for Favorites drop targets.
            local folder_min_x, folder_min_y = imgui.GetItemRectMin(ctx)
            local folder_max_x, folder_max_y = imgui.GetItemRectMax(ctx)
            if node.is_collection then
                local rect = state.favorite_collection_drop_rects[
                    node.collection_id]
                if not rect then
                    rect = {}
                    state.favorite_collection_drop_rects[
                        node.collection_id] = rect
                end
                rect[1], rect[2], rect[3], rect[4] =
                    folder_min_x, folder_min_y, folder_max_x, folder_max_y
                rect[5] = state.ui_frame_index
            end
            if heart_hover_style then imgui.PopStyleColor(ctx) end
            if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
            local tree_pushed = is_open
            local heart_clicked = DrawFavoriteRowHeart(node, heart_hot)
            -- Capture the folder row state before the heart creates another
            -- ImGui item and changes what IsItemClicked/Hovered refer to.
            local folder_clicked = imgui.IsItemClicked(ctx, 0)
            if not folder_clicked and node.is_folder and not heart_clicked
                and imgui.IsMouseClicked(ctx, 0) then
                local mouse_x, mouse_y = imgui.GetMousePos(ctx)
                folder_clicked = mouse_x >= folder_min_x
                    and mouse_x <= folder_max_x
                    and mouse_y >= folder_min_y
                    and mouse_y <= folder_max_y
                    and not heart_hot
            end
            local toggled_by_arrow = imgui.IsItemToggledOpen
                and imgui.IsItemToggledOpen(ctx)
            local folder_hovered = imgui.IsItemHovered(ctx)
            local folder_active = imgui.IsItemActive(ctx)
            if state.block_browser_input then
                folder_clicked = false
                toggled_by_arrow = false
                folder_hovered = false
                folder_active = false
            end
            local folder_context_id =
                "##folder_context_" .. tostring(instance_key)
            if folder_hovered and imgui.IsMouseClicked(ctx, 1) then
                imgui.OpenPopup(ctx, folder_context_id)
            end
            -- The favorite control is rendered as its own column item before
            -- the TreeNode; do not overlay another hit area here.
            local favorite_toggle_handled = false
            imgui.PopStyleColor(ctx)

            if not heart_clicked and folder_clicked then
                if node.path == "__favorite_files__" then
                    state.cursor_path = node.path
                    state.cursor_type = "folder"
                    state.cursor_favorite_instance_key = state.favorites_mode
                        and GetFavoriteNodeInstanceKey(node) or nil
                    state.selected_folder_scope = nil
                    state.force_search_update = true
                    state.needs_visible_update = true
                    open_map[instance_key] = not was_open
                else
                    if IsFolderCursorNode(node)
                        and state.selected_folder_scope == node.path then
                        ClearMediaBrowserSelection()
                    elseif state.favorites_mode then
                        -- Physical favorite folders own database-backed tag
                        -- scopes. Organizational collections remain navigation
                        -- scopes and never aggregate an ever-growing tag set.
                        if node.is_collection then
                            if not toggled_by_arrow then
                                SetFavoriteCollectionTagScope(node)
                            end
                        else
                            SetCursorToFolderNode(node, false)
                        end
                    else
                        SetCursorToFolderNode(node, false)
                    end
                    -- OpenOnArrow prevents the full-width row from reacting
                    -- to the heart gutter. Restore normal folder-name clicks
                    -- explicitly, after excluding heart and arrow clicks.
                    if node.is_folder
                        and not toggled_by_arrow then
                        favorite_toggle_handled = true
                        if was_open then
                            open_map[instance_key] = false
                            is_open = false
                        else
                            is_open = OpenFolderAccordion(node) == true
                        end
                        state.needs_visible_update = true
                    end
                end
            end
            
            -- Single-click smart toggle handling
            if not heart_clicked
                and not favorite_toggle_handled
                and node.path ~= "__favorite_files__"
                and open_map[instance_key] ~= is_open then
                if is_open then
                    is_open = OpenFolderAccordion(node) == true
                else
                    open_map[instance_key] = false
                    state.needs_visible_update = true
                end
            end

            if folder_hovered then
                state.next_hovered_path = node.path
                state.next_hovered_row_key = nil
                state.next_hovered_favorite_instance_key = state.favorites_mode
                    and instance_key or nil
                if state.favorites_mode
                    and node.path == "__favorite_files__" then
                    imgui.SetTooltip(ctx,
                        "Favorites stored directly at the Favorites root.")
                end
            end
            local drop_target_hovered = false
            if state.drag_active and state.favorites_mode then
                local mouse_x, mouse_y = imgui.GetMousePos(ctx)
                drop_target_hovered = mouse_x >= folder_min_x
                    and mouse_x <= folder_max_x
                    and mouse_y >= folder_min_y
                    and mouse_y <= folder_max_y
            end
            if state.drag_active
                and (drop_target_hovered
                    or imgui.IsItemHovered(ctx, FLG_HOVER_ALLOW_BLOCKED)) then
                local collection_drag =
                    state.drag_kind == "favorite_collection"
                local valid_collection_target = node.is_collection
                    and (not collection_drag
                        or CanReparentFavoriteCollection(
                            state.favorite_drag_source_collection_id,
                            node.collection_id))
                if node.path == "__favorite_files__" then
                    state.favorite_root_drop_hovered = true
                elseif valid_collection_target then
                    state.favorite_collection_drop_id = node.collection_id
                end
                if node.path == "__favorite_files__"
                    or valid_collection_target then
                    local accent = state.resolved_theme
                        and state.resolved_theme.accent
                        or state.theme.colors.accent
                    imgui.DrawList_AddRect(
                        imgui.GetWindowDrawList(ctx),
                        folder_min_x, folder_min_y,
                        folder_max_x, folder_max_y,
                        accent, 2, 0, 2)
                    if node.is_collection and collection_drag then
                        imgui.SetTooltip(ctx,
                            "Move Favorites folder into " .. node.name)
                    elseif node.is_collection then
                        local source_kind = state.favorite_drag_source_kind
                        local copy_to_folder =
                            select(1, GetSelectionModifiers()) == true
                        imgui.SetTooltip(ctx,
                            (source_kind == "inherited"
                                or source_kind == "library")
                                and "Add a copy to this Favorites folder"
                                or (copy_to_folder
                                    and "Copy into this Favorites folder"
                                    or "Move into this Favorites folder; hold Ctrl to copy"))
                    end
                elseif collection_drag and node.is_collection then
                    imgui.SetTooltip(ctx,
                        "A folder cannot be moved into itself or its descendant")
                end
            end

            if node.path ~= "__favorite_files__"
                and not (not state.favorites_mode and node.depth == 0)
                and folder_active
                and not state.favorite_heart_press_path
                and imgui.IsMouseDragging(ctx, 0) then
                if not state.drag_active then
                    state.drag_active = true
                    state.drag_path = node.path
                    state.drag_kind = node.is_collection
                        and "favorite_collection" or "folder"
                    if node.is_collection then
                        state.favorite_drag_source_kind = "collection"
                        state.favorite_drag_source_collection_id =
                            node.collection_id
                    else
                        state.favorite_drag_source_kind,
                            state.favorite_drag_source_collection_id =
                            GetFavoriteDragSource(node)
                    end
                    state.favorite_drag_copy = false
                    state.drag_orig_cursor_pos = r.GetCursorPosition()
                    state.drag_last_track = nil
                    state.drag_last_pos = nil
                    state.drag_hover_arrange = false
                    if state.is_playing then StopPreview() end
                end
            end
            
            if state.scroll_to_cursor and IsFolderCursorNode(node) then 
                imgui.SetScrollHereY(ctx, 0.3)
                state.scroll_to_cursor = false 
            end

            if node.path ~= "__favorite_files__"
                and imgui.BeginPopup(ctx, folder_context_id) then
                state.context_menu_active = true
                imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 7, 5)
                state.next_hovered_path = node.path
                state.next_hovered_row_key = nil
                state.next_hovered_favorite_instance_key = state.favorites_mode
                    and instance_key or nil
                if node.is_collection then
                    if imgui.MenuItem(ctx, "New Subfolder...") then
                        PromptAddFavoriteFolder(node.collection_id)
                    end
                    imgui.Separator(ctx)
                    if imgui.MenuItem(ctx, "Rename...") then
                        local ok, name = r.GetUserInputs("Rename Favorites Folder", 1, "Folder name:", node.name)
                        if ok then
                            RenameFavoriteCollection(
                                node.collection_id, name)
                        end
                    end
                    if imgui.MenuItem(ctx, "Delete Folder") then
                        DeleteFavoriteCollection(node.collection_id)
                    end
                else
                    DrawRevealFolderInExplorerMenuItem(node)
                    imgui.Separator(ctx)
                    if node.is_folder and not node.is_collection
                        and node.path ~= "__favorite_files__" then
                        local scope_type = IsRootLibraryFolderNode(node)
                            and "root" or "folder"
                        if imgui.BeginMenu(ctx, "Category") then
                            imgui.TextDisabled(ctx,
                                "Applies to this folder and descendants")
                            local current_override, current_scope =
                                GetManualOverrideInfo(node.path)
                            imgui.TextDisabled(ctx,
                                "Current override: "
                                    .. (current_override
                                        and ClassificationLabel(current_override)
                                            .. " (" .. current_scope .. ")"
                                        or "None"))
                            for _, option in ipairs({
                                {key = "loop", label = "Loop"},
                                {key = "one-shot", label = "One-shot"},
                                {key = "uncategorized", label = "Other"},
                            }) do
                                local current_category =
                                    GetManualCategoryKey(node.path)
                                local effective_option =
                                    option.key == "uncategorized"
                                        and "other" or option.key
                                local option_label =
                                    (current_category == effective_option
                                        and "[x] " or "") .. option.label
                                if imgui.MenuItem(ctx, option_label) then
                                    QueueClassificationOverride(
                                        scope_type, node.path, option.key)
                                end
                            end
                            imgui.Separator(ctx)
                            if imgui.MenuItem(
                                ctx, "Clear This Folder Override") then
                                ClearClassificationOverride(
                                    scope_type, node.path, false, false)
                            end
                            if imgui.MenuItem(
                                ctx, "Clear Folder and Subfolder Overrides") then
                                ClearClassificationOverride(
                                    scope_type, node.path, true, false)
                            end
                            if imgui.MenuItem(ctx,
                                "Clear Overrides in Folder, Subfolders, and Files") then
                                ClearClassificationOverride(
                                    scope_type, node.path, true, true)
                            end
                            imgui.EndMenu(ctx)
                        end
                    end
                    local folder_collection_id =
                        GetFavoriteContextCollectionId(node)
                    local has_context_membership
                    if folder_collection_id
                        and node._canonical_favorite ~= nil then
                        has_context_membership =
                            node._canonical_favorite == true
                    else
                        has_context_membership = FavoritePathHasMembership(
                            node.path, folder_collection_id)
                    end
                    if not IsRootLibraryFolderNode(node)
                        and not has_context_membership
                        and imgui.MenuItem(ctx, "Add to Favorites") then
                        SetFavoritePaths(
                            {node.path}, true,
                            node.is_folder and "folder" or "file",
                            folder_collection_id, node._canonical_folder_id)
                    end
                    if state.favorites_mode and has_context_membership
                        and imgui.MenuItem(ctx,
                            folder_collection_id
                                and "Remove from this Favorites folder"
                                or "Remove from Favorites") then
                        if folder_collection_id then
                            RemoveFavoriteCollectionMembership(
                                node.path, folder_collection_id)
                        else
                            RemoveFavorite(node.path,
                                node.is_folder and "folder" or "file")
                        end
                    end
                    if state.favorites_mode
                        and FavoritePathHasMembership(node.path)
                        and folder_collection_id
                        and imgui.MenuItem(ctx, "Remove from Favorites completely") then
                        RemoveFavoriteCompletely(
                            node.path, node.is_folder and "folder" or "file")
                    end
                    if not IsRootLibraryFolderNode(node)
                        and #state.favorite_collections > 0
                        and imgui.BeginMenu(ctx,
                            state.multi_selected[node.path]
                                and "Add/Remove Selected from Favorites Folder"
                                or "Add/Remove from Favorites Folder") then
                        local target_paths = state.multi_selected[node.path]
                            and GetSelectedFilePaths(node.path) or {node.path}
                        DrawFavoriteCollectionMenuTree(
                            GetFavoriteCollectionMenuTree(),
                            target_paths,
                            node.is_folder and "folder" or "file",
                            node._canonical_folder_id)
                        imgui.Separator(ctx)
                        if imgui.MenuItem(
                            ctx, "New Favorites Folder...") then
                            PromptAddFavoriteFolder(nil)
                        end
                        imgui.EndMenu(ctx)
                    elseif not IsRootLibraryFolderNode(node)
                        and #state.favorite_collections == 0
                        and imgui.MenuItem(
                            ctx, "Create Favorites Folder...") then
                        PromptAddFavoriteFolder()
                    end
                end
                if not node.is_collection and not state.favorites_mode
                    and IsRootLibraryFolderNode(node) then
                    imgui.Separator(ctx)
                    local refresh_disabled = RootLibraryActionsBlocked()
                    local refresh_disabled_scope = false
                    if refresh_disabled and imgui.BeginDisabled then
                        imgui.BeginDisabled(ctx, true)
                        refresh_disabled_scope = true
                    end
                    if imgui.MenuItem(ctx, T("check_folder_changes")) then
                        StartLibraryScan(node.path)
                    end
                    imgui.Separator(ctx)
                    if imgui.MenuItem(ctx, T("remove_folder"))
                        and not refresh_disabled then
                        RequestRootLibraryRemoval(node.path)
                    end
                    if refresh_disabled_scope then imgui.EndDisabled(ctx) end
                end
                imgui.PopStyleVar(ctx)
                imgui.EndPopup(ctx)
            end

            if is_open and tree_pushed then
                if not is_leaf then
                    if not node._canonical_loaded
                        and not node._canonical_loading
                        and not node._canonical_started
                        and (node.is_collection
                            or node.is_favorite_root_files
                            or node._canonical_folder_id)
                        and CanonicalUserDataQueueCount(
                            state.canonical_user_data) == 0
                        and #(state.canonical_user_data.inflight or {}) == 0 then
                        LoadCanonicalAccordionFolder(node)
                    end
                    if (node._canonical_window_start_offset or 0) > 0 then
                        imgui.Dummy(ctx, 1, 3)
                        imgui.PushStyleColor(ctx, imgui.Col_Text, 0xFFFFFFFF)
                        imgui.PushStyleColor(ctx, imgui.Col_Button,
                            (((state.resolved_theme
                                and state.resolved_theme.accent)
                                or state.theme.colors.accent)
                                & 0xFFFFFF00) | 0x58)
                        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
                            (((state.resolved_theme
                                and state.resolved_theme.accent)
                                or state.theme.colors.accent)
                                & 0xFFFFFF00) | 0x78)
                        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
                            (((state.resolved_theme
                                and state.resolved_theme.accent)
                                or state.theme.colors.accent)
                                & 0xFFFFFF00) | 0x98)
                        imgui.PushStyleVar(
                            ctx, imgui.StyleVar_FramePadding, 8, 5)
                        if imgui.Button(ctx,
                            (state.favorites_mode
                                and "\226\134\145  Load earlier favorite files"
                                or "\226\134\145  Load earlier library files")
                                .. "##accordion_previous_"
                                .. tostring(
                                    node._canonical_folder_id or node.path),
                            select(1, imgui.GetContentRegionAvail(ctx)), 0)
                            and not node._canonical_loading then
                            LoadPreviousCanonicalAccordionPage(node)
                        end
                        if imgui.IsItemHovered(ctx) then
                            imgui.SetTooltip(ctx,
                                "Older rows were released to keep memory bounded.")
                        end
                        imgui.PopStyleVar(ctx)
                        imgui.PopStyleColor(ctx, 4)
                        imgui.Dummy(ctx, 1, 3)
                    end
                    for _, child in ipairs(node.children) do DrawNode(child) end
                    if #node.files > 0 then
                        local clipper = state.folder_clippers[node.path]
                        if not clipper then
                            clipper = imgui.CreateListClipper(ctx)
                            imgui.Attach(ctx, clipper)
                            state.folder_clippers[node.path] = clipper
                        end
                        imgui.ListClipper_Begin(clipper, #node.files)
                        if state.scroll_to_cursor then
                            for file_index, file in ipairs(node.files) do
                                if file.path == state.cursor_path
                                    and imgui.ListClipper_IncludeItemByIndex then
                                    pcall(
                                        imgui.ListClipper_IncludeItemByIndex,
                                        clipper, file_index - 1)
                                    break
                                end
                            end
                        end
                        while imgui.ListClipper_Step(clipper) do
                            local file_min, file_max =
                                imgui.ListClipper_GetDisplayRange(clipper)
                            for file_index = file_min + 1, file_max do
                                local file = node.files[file_index]
                                -- A row interaction can invalidate the
                                -- folder's file window while the clipper is
                                -- still reporting its previous range.
                                if not file then break end
                                local file_flags =
                                    imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
                                local file_row_key = file._visible_row_key
                                    or GetMediaRowSelectionKey(
                                        file, "accordion:" .. tostring(node.path)
                                            .. ":" .. tostring(file_index))
                                local is_file_selected =
                                    IsMediaFileRowSelected(file, file_row_key)
                                local is_file_hovered =
                                    IsMediaFileRowHovered(file, file_row_key)

                                if is_file_selected then
                                    file_flags =
                                        file_flags | imgui.TreeNodeFlags_Selected
                                end
                                if is_file_selected or is_file_hovered then
                                    imgui.PushStyleColor(
                                        ctx, imgui.Col_Text,
                                        selected_text_color)
                                end

                                local heart_hot, heart_hover_style,
                                    heart_indent =
                                    PrepareFavoriteRowHeart(file)
                                local is_file_open = imgui.TreeNode(
                                    ctx, GetFavoriteDisplayName(file)
                                        .. "##media_file_" .. file_row_key,
                                    file_flags)
                                if heart_hover_style then
                                    imgui.PopStyleColor(ctx)
                                end
                                if heart_indent > 0 then
                                    imgui.Unindent(ctx, heart_indent)
                                end
                                local file_heart_clicked =
                                    DrawFavoriteRowHeart(
                                        file, heart_hot, file_row_key)
                                local file_interaction =
                                    CaptureBrowserRowInteraction(file_row_key)
                                if is_file_selected or is_file_hovered then
                                    imgui.PopStyleColor(ctx)
                                end

                                if state.scroll_to_cursor
                                    and state.cursor_path == file.path then
                                    imgui.SetScrollHereY(ctx, 0.3)
                                    state.scroll_to_cursor = false
                                end

                                HandleFileInteraction(
                                    file, file_heart_clicked,
                                    file_interaction)
                                if is_file_open then imgui.TreePop(ctx) end
                            end
                        end
                    end
                    if node._canonical_has_more then
                        accordion_page_candidate = node
                        imgui.Dummy(ctx, 1, 1)
                        if imgui.IsItemVisible(ctx)
                            and not node._canonical_loading
                            and not (imgui.IsMouseDown
                                and imgui.IsMouseDown(ctx, 0))
                            and not state.accordion_page_load_suppressed then
                            LoadNextCanonicalAccordionPage(node)
                        end
                    elseif node._canonical_loading then
                        imgui.Dummy(ctx, 1, 1)
                    end
                end
            end
            if tree_pushed then imgui.TreePop(ctx) end
        end
        for _, tree in ipairs(GetActiveTrees()) do
            if state.favorites_mode and tree.path == "__favorite_files__" then
                DrawLooseFavoriteFiles(tree)
            else
                DrawNode(tree)
            end
        end
        if suppress_hover_style then imgui.PopStyleColor(ctx) end
    end
    if imgui.GetScrollY and imgui.GetScrollMaxY then
        local scroll_y = imgui.GetScrollY(ctx)
        local scroll_max = imgui.GetScrollMaxY(ctx)
        if state.accordion_scroll_rebase_pending
            and not (imgui.IsMouseDown and imgui.IsMouseDown(ctx, 0)) then
            scroll_y = math.max(0, scroll_max * 0.67)
            imgui.SetScrollY(ctx, scroll_y)
            state.accordion_scroll_rebase_pending = false
            state.accordion_page_load_suppressed = true
        end
        local near_page_end = scroll_max > 0
            and scroll_y >= scroll_max - 120
        if accordion_page_candidate
            and near_page_end
            and not accordion_page_candidate._canonical_loading
            and not (imgui.IsMouseDown and imgui.IsMouseDown(ctx, 0))
            and not state.accordion_page_load_suppressed then
            LoadNextCanonicalAccordionPage(accordion_page_candidate)
        end
    end
    DrawFavoritesRootContextMenu()
    if imgui.IsWindowHovered(ctx)
        and imgui.IsMouseClicked(ctx, 0)
        and not imgui.IsAnyItemHovered(ctx) then
        ClearMediaBrowserSelection()
    end
    imgui.EndChild(ctx)
    imgui.EndChild(ctx)

    state.hovered_path = state.suppress_mouse_hover
        and nil or state.next_hovered_path
    state.hovered_row_key = state.suppress_mouse_hover
        and nil or state.next_hovered_row_key
    state.hovered_favorite_instance_key = state.suppress_mouse_hover
        and nil or state.next_hovered_favorite_instance_key
end

function DrawKeyLockPiano()
    local piano_w = math.max(1, select(1, imgui.GetContentRegionAvail(ctx)))
    local piano_h = 50
    imgui.Separator(ctx)
    local status
    local one_shot_key_bypassed = state.key_sync.enabled
        and state.one_shot_bypass.key_sync
        and ((state.media_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().is_one_shot)
            or (state.media_kind == "midi"
                and state.current_file_is_one_shot))
    local current_key_override = GetManualKeyOverrideEntry(state.source_file)
    if not state.key_sync.enabled then
        status = "Auto Key: Off  \xc2\xb7  Correction: 0 st"
    elseif one_shot_key_bypassed then
        status = "Auto Key: On  \xc2\xb7  Bypassed by One-Shot Mode"
    elseif (state.media_kind == "audio" and state.audio_detected_key_pc ~= nil)
        or (state.loaded_midi and state.loaded_midi.detected_key_pc ~= nil) then
        local detected_pc = state.media_kind == "audio"
            and state.audio_detected_key_pc
            or state.loaded_midi.detected_key_pc
        local detected = PITCH_CLASS_NAMES[detected_pc + 1]
        local shift = ComputeKeySyncShift(
            detected_pc,
            state.key_sync.target_pc
        )
        status = string.format(
            "%s Key: %s  \xc2\xb7  Correction: %+d st",
            current_key_override and "Manual" or "Auto",
            detected, shift
        )
    elseif current_key_override
        and current_key_override.key_pc == false then
        status = "Manual Key: Unkeyed  \xc2\xb7  Correction: 0 st"
    else
        status = "Auto Key: Undetected  \xc2\xb7  Correction: 0 st"
    end
    -- Native Button owns input capture; the existing header artwork below is
    -- retained so the control remains visually unchanged.
    local header_text = (state.resolved_theme and state.resolved_theme.text)
        or state.theme.colors.text
    local header_accent = (state.resolved_theme and state.resolved_theme.accent)
        or state.theme.colors.accent
    imgui.PushStyleColor(ctx, imgui.Col_Text, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_Button, 0x00000000)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
        (header_accent & 0xFFFFFF00) | 0x18)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
        (header_accent & 0xFFFFFF00) | 0x30)
    local disclosure_clicked = imgui.Button(ctx, "##piano_disclosure", piano_w, 24)
    imgui.PopStyleColor(ctx, 4)
    local header_min_x, header_min_y = imgui.GetItemRectMin(ctx)
    local header_max_x, header_max_y = imgui.GetItemRectMax(ctx)
    local header_hovered = imgui.IsItemHovered(ctx)
    local header_draw = imgui.GetWindowDrawList(ctx)
    local arrow_x = header_min_x + 8
    local arrow_y = (header_min_y + header_max_y) * 0.5
    if state.piano_open then
        imgui.DrawList_AddTriangleFilled(header_draw,
            arrow_x - 4, arrow_y - 2, arrow_x + 4, arrow_y - 2,
            arrow_x, arrow_y + 3, header_text)
    else
        imgui.DrawList_AddTriangleFilled(header_draw,
            arrow_x - 2, arrow_y - 4, arrow_x - 2, arrow_y + 4,
            arrow_x + 3, arrow_y, header_text)
    end
    local keyboard_color = state.piano_open and header_accent or header_text
    local key_x1, key_y1 = header_min_x + 19, header_min_y + 6
    local key_x2, key_y2 = key_x1 + 22, key_y1 + 13
    imgui.DrawList_AddRect(
        header_draw, key_x1, key_y1, key_x2, key_y2,
        keyboard_color, 2, 0, 1.2)
    local white_key_w = (key_x2 - key_x1) / 5
    for index = 1, 4 do
        local divider_x = key_x1 + index * white_key_w
        imgui.DrawList_AddLine(
            header_draw, divider_x, key_y1, divider_x, key_y2,
            keyboard_color, 1)
    end
    for _, boundary in ipairs({1, 2, 4}) do
        local black_x = key_x1 + boundary * white_key_w
        imgui.DrawList_AddRectFilled(
            header_draw, black_x - 1.5, key_y1,
            black_x + 1.5, key_y1 + 7, keyboard_color, 1)
    end
    local visible_status = state.piano_open and status or "Auto Key: Off"
    local status_w, status_h = imgui.CalcTextSize(ctx, visible_status)
    imgui.DrawList_AddText(header_draw,
        header_min_x + math.max(48, (piano_w - status_w) * 0.5),
        header_min_y + (24 - status_h) * 0.5,
        (header_text & 0xFFFFFF00) | 0x98, visible_status)
    if disclosure_clicked then
        state.piano_open = not state.piano_open
        if not state.piano_open and state.key_sync.enabled then
            state.key_sync.enabled = false
            -- Removing Auto Key changes the effective pitch just like the
            -- manual semitone control. Recreate native audio through the
            -- already-validated pitch path instead of the generic update,
            -- which only refreshes volume/position for audio.
            ApplyPlaybackSettings("pitch")
        end
        SavePreviewPreferences("piano")
    end
    if header_hovered then
        imgui.SetTooltip(ctx, state.piano_open
            and "Collapse keyboard and disable Auto Key"
            or "Expand Auto Key keyboard")
    end
    if not state.piano_open then return end

    local x, y = imgui.GetCursorScreenPos(ctx)
    local white_w = piano_w / 7
    local black_w = white_w * 0.58
    local black_h = piano_h * 0.62
    local white_pcs = {0, 2, 4, 5, 7, 9, 11}
    local black_keys = {
        {pc = 1, boundary = 1}, {pc = 3, boundary = 2},
        {pc = 6, boundary = 4}, {pc = 8, boundary = 5},
        {pc = 10, boundary = 6},
    }

    imgui.InvisibleButton(ctx, "##key_lock_piano", piano_w, piano_h)
    state.preview_piano_height = select(2, imgui.GetCursorScreenPos(ctx)) - y
    local clicked_pc = nil
    if imgui.IsItemClicked(ctx) then
        local mx, my = imgui.GetMousePos(ctx)
        local lx, ly = mx - x, my - y
        if ly >= 0 and ly <= black_h then
            for _, key in ipairs(black_keys) do
                local kx = key.boundary * white_w - black_w / 2
                if lx >= kx and lx < kx + black_w then
                    clicked_pc = key.pc
                    break
                end
            end
        end
        if clicked_pc == nil and lx >= 0 and lx < piano_w then
            local white_index = math.min(7, math.floor(lx / white_w) + 1)
            clicked_pc = white_pcs[white_index]
        end
    end

    if clicked_pc ~= nil then
        if state.key_sync.enabled and state.key_sync.target_pc == clicked_pc then
            state.key_sync.enabled = false
        else
            state.key_sync.enabled = true
            state.key_sync.target_pc = clicked_pc
        end
        -- Auto Key correction feeds the same effective audio pitch value as
        -- the working manual pitch control.
        ApplyPlaybackSettings("pitch")
        SavePreviewPreferences("key_sync")
    end

    local draw_list = imgui.GetWindowDrawList(ctx)
    local accent = state.theme.use_custom
        and state.theme.colors.accent
        or ((state.resolved_theme and state.resolved_theme.accent)
            or GetREAPERAccentPalette())
    local base = state.theme.use_custom
        and state.theme.colors.panel_bg
        or ((state.resolved_theme and state.resolved_theme.button_bg)
            or GetREAPERThemeColor("col_buttonbg", 0x555555FF))
    local white_col = AdjustColor(base, 0.72)
    local black_col = AdjustColor(base, -0.62)
    local border_col = state.theme.use_custom
        and state.theme.colors.border
        or GetREAPERThemeColor("col_main_text2", 0x202020FF)
    local white_text = AdjustColor(black_col, 0.08)

    for i, pc in ipairs(white_pcs) do
        local x1 = x + (i - 1) * white_w
        local x2 = x + i * white_w
        local selected = state.key_sync.enabled and state.key_sync.target_pc == pc
        imgui.DrawList_AddRectFilled(draw_list, x1, y, x2, y + piano_h,
            selected and accent or white_col, 4)
        imgui.DrawList_AddRect(draw_list, x1, y, x2, y + piano_h, border_col, 4, 0, 1)
        local label = PITCH_CLASS_NAMES[pc + 1]
        local tw = select(1, imgui.CalcTextSize(ctx, label))
        imgui.DrawList_AddText(draw_list, x1 + (white_w - tw) / 2, y + piano_h - 18,
            selected and GetSelectedTextColor() or white_text, label)
    end

    for _, key in ipairs(black_keys) do
        local x1 = x + key.boundary * white_w - black_w / 2
        local selected = state.key_sync.enabled and state.key_sync.target_pc == key.pc
        imgui.DrawList_AddRectFilled(draw_list, x1, y, x1 + black_w, y + black_h,
            selected and accent or black_col, 4)
        imgui.DrawList_AddRect(draw_list, x1, y, x1 + black_w, y + black_h,
            border_col, 4, 0, 1)
    end

    if imgui.IsItemHovered(ctx) then
        imgui.SetTooltip(ctx, "Click a note to enable Key Lock.\nClick the selected note again to disable it.")
    end

end

function DrawSmoothValueControl(id, value, min_value, max_value, width, format_value, options)
    options = options or {}
    local control = state.value_control
    local was_active = control.active_id == id
    imgui.SetNextItemWidth(ctx, width)
    local native_changed, native_value = imgui.SliderDouble(
        ctx, id, value, min_value, max_value, "")
    local hovered = imgui.IsItemHovered(ctx)
    local active = imgui.IsItemActive(ctx)
    local changed, committed, wheel_changed = false, false, false

    -- Let ReaImGui/ Dear ImGui own the drag interaction. The old control used
    -- an InvisibleButton plus a hand-drawn vertical gesture, which made the
    -- widget fight the host while the preview was being updated.
    if native_changed == true then
        local candidate = math.max(min_value, math.min(max_value, native_value))
        if options.step then
            candidate = math.floor(candidate / options.step + 0.5)
                * options.step
            candidate = math.max(min_value, math.min(max_value, candidate))
        end
        if candidate ~= value then
            value = candidate
            changed = true
        end
    end
    if active then
        control.active_id = id
    elseif was_active then
        control.active_id = nil
        committed = true
    end

    -- Match TK Media Browser's direct wheel behavior. Volume uses 0.1 dB;
    -- pitch intentionally stays at one semitone per wheel step.
    if hovered then
        local wheel_ok, wheel = pcall(imgui.GetMouseWheel, ctx)
        if wheel_ok and wheel and wheel ~= 0 then
            local mods = 0
            local mods_ok, current_mods = pcall(imgui.GetKeyMods, ctx)
            if mods_ok then mods = current_mods end
            local increment = ((mods & MOD_SHIFT) ~= 0)
                and (options.fine_wheel_step or options.wheel_step)
                or options.wheel_step
            local candidate = math.max(min_value, math.min(max_value,
                value + wheel * increment))
            if options.step then
                candidate = math.floor(candidate / options.step + 0.5)
                    * options.step
                candidate = math.max(min_value, math.min(max_value, candidate))
            end
            if candidate ~= value then
                value = candidate
                changed, committed, wheel_changed = true, true, true
            end
        end
    end

    if hovered and imgui.IsMouseClicked(ctx, 1) then
        value = options.reset_value or 0
        changed, committed, wheel_changed = true, true, false
        control.active_id = nil
    end

    -- Keep the native slider's interaction and theme, but draw the current
    -- value over it like TK's browser so the control remains compact.
    local x1, y1 = imgui.GetItemRectMin(ctx)
    local x2, y2 = imgui.GetItemRectMax(ctx)
    local draw_list = imgui.GetWindowDrawList(ctx)
    local panel = state.theme.use_custom and state.theme.colors.panel_bg
        or ((state.resolved_theme and state.resolved_theme.button_bg) or 0x454545FF)
    local text_col = state.theme.use_custom and state.theme.colors.text
        or ((state.resolved_theme and state.resolved_theme.text) or 0xE0E0E0FF)
    local display = format_value(value)
    local text_w, text_h = imgui.CalcTextSize(ctx, display)
    local tx = x1 + (x2 - x1 - text_w) * 0.5
    local ty = y1 + (y2 - y1 - text_h) * 0.5
    imgui.DrawList_AddRectFilled(
        draw_list, tx - 4, ty - 1, tx + text_w + 4, ty + text_h + 1,
        (panel & 0xFFFFFF00) | 0xCC, 3)
    imgui.DrawList_AddText(draw_list, tx, ty, text_col, display)

    if hovered then
        imgui.SetTooltip(ctx, "Drag or scroll to adjust\nRight-click to reset")
    end

    return changed, value, committed, wheel_changed
end

function GetMediaPreviewFooterHeight(font_height)
    local height = state.preview_footer_height or (font_height * 5 + 75)
    if state.preview_footer_piano_open ~= nil
        and state.preview_footer_piano_open ~= state.piano_open then
        height = height + (state.piano_open and 1 or -1)
            * (state.preview_piano_height or 54)
    end
    return math.max(100, height)
end

function DrawMIDIPreview()
    local preview_window_flags = FLG_NO_SCROLLBAR | FLG_NO_SCROLL_MOUSE
    if not imgui.BeginChild(
        ctx, "preview_pane", 0, 0,
        FLG_CHILD_BORDER, preview_window_flags) then
        return
    end

    state.preview_pane_bounds = state.preview_pane_bounds or {}
    state.preview_pane_bounds.x1,
        state.preview_pane_bounds.y1 = imgui.GetWindowPos(ctx)
    state.preview_pane_bounds.x2,
        state.preview_pane_bounds.y2 = imgui.GetWindowSize(ctx)
    state.preview_pane_bounds.x2 = state.preview_pane_bounds.x1
        + state.preview_pane_bounds.x2
    state.preview_pane_bounds.y2 = state.preview_pane_bounds.y1
        + state.preview_pane_bounds.y2

    -- The preview pane is a separate input surface below the browser. A row
    -- press can remain deferred while ReaImGui decides whether it will become
    -- a multi-row drag; any subsequent mouse gesture owned by this pane must
    -- cancel that browser gesture before the end-of-frame release processor
    -- can activate the old row. Guard the whole pane rather than relying on
    -- each individual control to report a completed click.
    if imgui.IsWindowHovered(ctx)
        and (imgui.IsMouseDown(ctx, 0)
            or imgui.IsMouseClicked(ctx, 0)
            or (imgui.IsMouseReleased and imgui.IsMouseReleased(ctx, 0))) then
        CancelPendingMediaRowActivation()
    end

    local preview_caption
    if state.media_kind == "audio" and state.source_file ~= "" then
        preview_caption = GetFileName(state.source_file) .. string.format(
            " | Audio | %.2fs", state.audio_length or 0)
    elseif state.loaded_midi then
        preview_caption = GetFileName(state.source_file) .. string.format(" | %d notes | %.2fs",
            #state.loaded_midi.notes,
            state.loaded_midi.display_duration
                or state.file_duration_seconds)
    else
        preview_caption = "Select a MIDI or audio file to preview..."
    end

    local avail_x, avail_y = imgui.GetContentRegionAvail(ctx)
    -- During a live resize Dear ImGui can briefly report an exactly zero-width
    -- content region. InvisibleButton asserts on either zero dimension, so keep
    -- the interaction/draw canvas valid for that transitional frame.
    avail_x = math.max(1, avail_x)
    -- Derive the footer from the active font instead of reserving a fixed
    -- pixel block. The canvas absorbs the remainder, keeping the piano flush
    -- with the bottom at every browser font size.
    local font_height = select(2, imgui.CalcTextSize(ctx, "Ag"))
    local control_reserve = GetMediaPreviewFooterHeight(font_height)
    local canvas_h = math.max(40, avail_y - control_reserve)
    local canvas_p0_x, canvas_p0_y = imgui.GetCursorScreenPos(ctx)
    local draw_list = imgui.GetWindowDrawList(ctx)
    local caption_scale = 0.65
    local caption_font_size = imgui.GetFontSize(ctx) * caption_scale
    local caption_height = select(2, imgui.CalcTextSize(ctx, "Ag")) * caption_scale
    local caption_strip_height = math.min(caption_height + 8, canvas_h * 0.4)

    local c_bg = state.theme.use_custom and state.theme.colors.preview_bg
        or GetREAPERThemeColor("col_main_editbk", 0x1A1A1AFF)
    if not state.theme.use_custom and state.resolved_theme then
        local resolved = state.resolved_theme
        local preview_is_light = ColorLuminance(c_bg) >= 145
        if preview_is_light ~= resolved.is_light then
            c_bg = resolved.is_light
                and AdjustColor(resolved.panel_bg, 0.05)
                or AdjustColor(resolved.panel_bg, -0.12)
        else
            c_bg = BlendColor(c_bg, resolved.panel_bg, 0.12)
        end
    end
    local c_grid = state.theme.use_custom and state.theme.colors.preview_grid
        or GetREAPERThemeColor("arrange_vgrid", 0x333333FF)
    -- The arrange-grid color can be nearly as prominent as small MIDI notes in
    -- some REAPER themes. Keep its hue but move it closer to the preview floor.
    if not state.theme.use_custom then
        c_grid = BlendColor(c_grid, c_bg, 0.58)
    end
    
    local function GetStripeCol(bg)
        local lum = (((bg>>24)&0xFF)*0.299 + ((bg>>16)&0xFF)*0.587 + ((bg>>8)&0xFF)*0.114)
        return lum > 128 and AdjustColor(bg, -0.03) or AdjustColor(bg, 0.05)
    end
    
    local c_stripe = GetStripeCol(c_bg)
    local c_note
    if state.theme.use_custom then
        c_note = state.theme.colors.midi_note
    else
        -- REAPER pairs its muted selection background with a bright selected
        -- foreground. Blend the pair so dense MIDI remains visible while the
        -- color still belongs to the active REAPER theme.
        local _, notes = GetREAPERAccentPalette()
        c_note = EnsureColorContrast(notes, c_bg, 100)
    end
    local c_note_edge = state.theme.use_custom
        and AdjustColor(c_note, 0.30)
        or c_note
    -- Do not brighten notes only as the playhead crosses them; that made the
    -- contrast correction look like a brighter playhead instead of clearer MIDI.
    local c_note_playing = c_note

    imgui.InvisibleButton(ctx, "midi_canvas", avail_x, canvas_h)
    local canvas_hovered = imgui.IsItemHovered(ctx)
    if canvas_hovered and imgui.IsItemClicked(ctx, 1) then
        SeekPreviewToFraction(0)
    elseif imgui.IsItemClicked(ctx, 0) and avail_x > 0 then
        local mouse_x = select(1, imgui.GetMousePos(ctx))
        SeekPreviewToFraction(
            (mouse_x - canvas_p0_x) / avail_x)
    end
    if canvas_hovered then
        imgui.SetTooltip(ctx,
            "Click to seek\nRight-click to return to the beginning")
    end
    imgui.DrawList_AddRectFilled(draw_list, canvas_p0_x, canvas_p0_y, canvas_p0_x + avail_x, canvas_p0_y + canvas_h, c_bg)
    imgui.DrawList_AddRect(draw_list, canvas_p0_x, canvas_p0_y, canvas_p0_x + avail_x, canvas_p0_y + canvas_h, c_grid, 0, 0, 1)

    do
    -- Keep all waveform/notes below the slim caption strip. The enclosing
    -- canvas and its seek target retain their original dimensions.
    local canvas_p0_y = canvas_p0_y + caption_strip_height
    local canvas_h = math.max(1, canvas_h - caption_strip_height)
    if state.media_kind == "audio" and state.audio_peaks
        and #state.audio_peaks > 0 then
        local center_y = canvas_p0_y + canvas_h * 0.5
        local waveform_col = c_note
        local peak_count = #state.audio_peaks
        local columns = math.max(1, math.floor(avail_x))
        for column = 0, columns - 1 do
            local first = math.floor(column * peak_count / columns) + 1
            local last = math.max(first,
                math.floor((column + 1) * peak_count / columns))
            local peak = 0
            for i = first, math.min(last, peak_count) do
                peak = math.max(peak, state.audio_peaks[i] or 0)
            end
            local x = canvas_p0_x + column
            local half_height = peak * canvas_h * 0.46
            imgui.DrawList_AddLine(
                draw_list, x, center_y - half_height,
                x, center_y + half_height, waveform_col, 1)
        end
        imgui.DrawList_AddLine(
            draw_list, canvas_p0_x, center_y,
            canvas_p0_x + avail_x, center_y, c_grid, 1)
        local duration = math.max(
            state.audio_preview_length > 0
                and state.audio_preview_length
                or state.audio_length,
            0.001)
        local preview_pos = state.is_playing
            and GetPreviewPosition()
            or ((state.preview_seek_fraction or 0) * duration)
        preview_pos = math.max(0, math.min(duration, preview_pos))
        local playhead_x = canvas_p0_x + preview_pos / duration * avail_x
        imgui.DrawList_AddLine(draw_list, playhead_x, canvas_p0_y,
            playhead_x, canvas_p0_y + canvas_h, 0xFFBB00FF, 2)
    elseif state.media_kind == "audio" then
        local waveform_status = state.audio_waveform_native_pending
            and "Preparing waveform peaks..."
            or "Waveform unavailable for this audio source."
        local text_w = select(1, imgui.CalcTextSize(ctx, waveform_status))
        imgui.DrawList_AddText(
            draw_list,
            canvas_p0_x + math.max(8, (avail_x - text_w) * 0.5),
            canvas_p0_y + canvas_h * 0.5 - 8,
            c_grid, waveform_status)
    elseif state.loaded_midi and #state.loaded_midi.notes > 0 then
        local note_range = state.loaded_midi.max_note - state.loaded_midi.min_note + 1
        local time_range = math.max(state.loaded_midi.display_duration
            or state.file_duration_seconds, 0.001)
        local note_height = canvas_h / note_range

        for i = 0, note_range - 1 do
            local y = canvas_p0_y + i * note_height
            local note_num = state.loaded_midi.max_note - i
            local is_black = ({false,true,false,true,false,false,true,false,true,false,true,false})[(note_num % 12) + 1]
            imgui.DrawList_AddRectFilled(draw_list, canvas_p0_x, y, canvas_p0_x + avail_x, y + note_height, is_black and c_stripe or c_bg)
        end

        local beat_time = 60 / r.Master_GetTempo()
        for i = 0, math.ceil(time_range / beat_time) do
            local x = canvas_p0_x + ((i * beat_time) / time_range) * avail_x
            if x <= canvas_p0_x + avail_x then
                imgui.DrawList_AddLine(draw_list, x, canvas_p0_y, x, canvas_p0_y + canvas_h, c_grid, 1)
            end
        end

        local preview_pos
        if state.is_playing then
            local native_position = GetPreviewPosition()
            if state.native_preview_kind == "midi" then
                -- The DLL reports MIDI's tempo/rate-adjusted output clock,
                -- while note rectangles use the original source-time axis.
                -- Convert through total output duration before drawing so
                -- half/double speed and tempo matching share one playhead.
                local output_length = math.max(
                    state.audio_preview_output_length or 0, 0.000001)
                -- The piano roll was parsed onto the project-tempo seconds
                -- axis, not the MIDI source's neutral 120-BPM clock. Map the
                -- rendered clock to that same displayed axis; otherwise its
                -- playhead drifts at 0.5x/2x whenever project tempo != 120.
                local source_length = math.max(time_range, 0.000001)
                native_position = (native_position / output_length)
                    * source_length
            end
            preview_pos = math.max(0, math.min(
                time_range, native_position))
        else
            preview_pos = (state.preview_seek_fraction or 0) * time_range
        end

        for _, note in ipairs(state.loaded_midi.notes) do
            local disp_start = note.start_time
            local disp_end = note.end_time
            local x1 = canvas_p0_x + (disp_start / time_range) * avail_x
            local x2 = canvas_p0_x + (disp_end / time_range) * avail_x
            local y1 = canvas_p0_y
                + (state.loaded_midi.max_note - note.pitch) * note_height
            local y2 = y1 + note_height

            local ny1 = y1 + (note_height >= 6 and 1 or 0)
            local ny2 = y2 - (note_height >= 6 and 1 or 0)
            if ny2 - ny1 < 2 then
                local center_y = (y1 + y2) * 0.5
                ny1, ny2 = center_y - 1, center_y + 1
            end

            if x2 > canvas_p0_x and x1 < canvas_p0_x + avail_x then
                x1 = math.max(canvas_p0_x, x1)
                x2 = math.min(canvas_p0_x + avail_x,
                    math.max(x2, x1 + 1.5))
                local col = (state.is_playing
                    and preview_pos >= disp_start
                    and preview_pos < disp_end)
                    and c_note_playing or c_note
                imgui.DrawList_AddRectFilled(
                    draw_list, x1, ny1, x2, ny2, col, 2)
                imgui.DrawList_AddLine(
                    draw_list, x1, ny1, x2, ny1, c_note_edge, 1)
            end
        end

        local playhead_x = canvas_p0_x + (preview_pos / time_range) * avail_x
        imgui.DrawList_AddLine(draw_list, playhead_x, canvas_p0_y, playhead_x, canvas_p0_y + canvas_h, 0xFFBB00FF, 2)
    end

    end -- plot area

    -- Caption uses the canvas background directly and never covers the plot.
    local caption_color = state.resolved_theme and state.resolved_theme.text
        or state.theme.colors.text
    imgui.DrawList_PushClipRect(draw_list, canvas_p0_x + 1, canvas_p0_y + 1,
        canvas_p0_x + avail_x - 1, canvas_p0_y + caption_strip_height, true)
    imgui.DrawList_AddTextEx(draw_list, nil, caption_font_size,
        canvas_p0_x + 6, canvas_p0_y + 3, caption_color, preview_caption)
    imgui.DrawList_PopClipRect(draw_list)

    local footer_start_y = canvas_p0_y + canvas_h + 5
    imgui.SetCursorScreenPos(ctx, canvas_p0_x, footer_start_y)

    local function DrawCompactAudioVolume()
        imgui.SameLine(ctx)
        local current_x = imgui.GetCursorPosX(ctx)
        local remaining_x = select(1, imgui.GetContentRegionAvail(ctx))
        local label_width = select(1, imgui.CalcTextSize(ctx, "Vol"))
        local volume_width = label_width + 90
        if remaining_x > volume_width then
            imgui.SetCursorPosX(
                ctx, current_x + remaining_x - volume_width)
        end
        imgui.TextDisabled(ctx, "Vol")
        imgui.SameLine(ctx)
        local changed, value, committed, wheel_changed = DrawSmoothValueControl(
            "##audio_volume_control", state.audio_volume_db, -60, 12, 82,
            function(v) return string.format("%.1f dB", v) end,
            {
                wheel_step = 0.1,
                fine_wheel_step = 0.1,
                step = 0.1,
                reset_value = 0,
            })
        if changed then
            state.audio_volume_db =
                math.floor(math.max(-60, math.min(12, value)) * 10 + 0.5) / 10
            RequestPlaybackSettingsApply(
                committed and not wheel_changed, "volume")
        end
        if committed then RequestPlaybackSettingsSave(false, "volume") end
    end

    if state.media_kind == "audio" then
        imgui.TextDisabled(ctx, GetAudioPreviewStatusText())
    elseif state.preview_setup_message then
        imgui.TextDisabled(ctx, state.preview_setup_message)
    else
        imgui.TextDisabled(ctx, "Preview: select an instrument track when you press Play")
    end
    
    local active_col = state.theme.use_custom and state.theme.colors.accent
        or ((state.resolved_theme and state.resolved_theme.accent)
            or GetREAPERAccentPalette())
    local inactive_button = state.theme.use_custom
        and AdjustColor(state.theme.colors.panel_bg, 0.25)
        or ((state.resolved_theme and state.resolved_theme.button_bg)
            or GetREAPERThemeColor("col_buttonbg", 0x555555FF))

    local function CompactDivider()
        imgui.SameLine(ctx)
        imgui.Dummy(ctx, 1, 24)
        local x1, y1 = imgui.GetItemRectMin(ctx)
        local x2, y2 = imgui.GetItemRectMax(ctx)
        local color = (((state.resolved_theme and state.resolved_theme.text)
            or state.theme.colors.text) & 0xFFFFFF00) | 0x58
        imgui.DrawList_AddLine(
            imgui.GetWindowDrawList(ctx), (x1 + x2) * 0.5, y1 + 4,
            (x1 + x2) * 0.5, y2 - 4, color, 1)
        imgui.SameLine(ctx)
    end

    local function CompactToggle(id, label, tooltip, enabled, width)
        width = width or 30
        local normal_text = (state.resolved_theme and state.resolved_theme.text)
            or state.theme.colors.text
        -- Keep these controls on ReaImGui's native input path. The former
        -- draw-list/InvisibleButton implementation could leave the host's
        -- shared mouse capture active and freeze unrelated script GUIs.
        local button_bg = enabled
            and ((active_col & 0xFFFFFF00) | 0x14) or 0x00000000
        local button_hover = (active_col & 0xFFFFFF00) | 0x24
        local button_active = (active_col & 0xFFFFFF00) | 0x40
        imgui.PushStyleColor(ctx, imgui.Col_Text,
            enabled and active_col or normal_text)
        imgui.PushStyleColor(ctx, imgui.Col_Button, button_bg)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered, button_hover)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive, button_active)
        local clicked = imgui.Button(ctx, "##" .. id, width, 24)
        if clicked or imgui.IsItemActive(ctx) then
            -- Claim the gesture on mouse-down as well as mouse-up. Waiting for
            -- Button's completed-click result left an old browser activation
            -- alive when the pointer moved or the release was interrupted.
            CancelPendingMediaRowActivation()
        end
        local min_x, min_y = imgui.GetItemRectMin(ctx)
        local max_x, max_y = imgui.GetItemRectMax(ctx)
        local hovered = imgui.IsItemHovered(ctx)
        imgui.PopStyleColor(ctx, 4)

        -- Retain the compact icon artwork while letting native Button own
        -- capture/focus behavior.
        local draw = imgui.GetWindowDrawList(ctx)
        local color = enabled and active_col or normal_text
        local cx, cy = (min_x + max_x) * 0.5, (min_y + max_y) * 0.5
        if id == "play" or id == "retrigger" then
            imgui.DrawList_AddTriangleFilled(
                draw, cx - 5, cy - 7, cx - 5, cy + 7,
                cx + 7, cy, color)
        elseif id == "stop" then
            imgui.DrawList_AddRectFilled(
                draw, cx - 6, cy - 6, cx + 6, cy + 6, color, 1)
        elseif id == "autoplay" then
            imgui.DrawList_AddTriangleFilled(
                draw, cx - 6, cy - 6, cx - 6, cy + 6,
                cx + 5, cy, color)
            imgui.DrawList_AddCircleFilled(draw, cx + 7, cy - 7, 2, color)
        elseif id == "transport_mode" then
            if PreviewControlsTransport() then
                imgui.DrawList_AddCircle(draw, cx - 4, cy + 3, 5, color, 0, 1.8)
                imgui.DrawList_AddCircle(draw, cx + 4, cy - 3, 5, color, 0, 1.8)
                imgui.DrawList_AddLine(draw, cx - 2, cy + 1, cx + 2, cy - 1, color, 1.8)
            else
                imgui.DrawList_AddLine(draw, cx - 7, cy - 4, cx + 6, cy - 4, color, 1.5)
                imgui.DrawList_AddLine(draw, cx + 6, cy - 4, cx + 2, cy - 7, color, 1.5)
                imgui.DrawList_AddLine(draw, cx + 6, cy - 4, cx + 2, cy - 1, color, 1.5)
                imgui.DrawList_AddLine(draw, cx + 7, cy + 4, cx - 6, cy + 4, color, 1.5)
                imgui.DrawList_AddLine(draw, cx - 6, cy + 4, cx - 2, cy + 1, color, 1.5)
                imgui.DrawList_AddLine(draw, cx - 6, cy + 4, cx - 2, cy + 7, color, 1.5)
            end
        elseif id == "tempo_match" then
            imgui.DrawList_AddCircle(draw, cx, cy, 7, color, 0, 1.5)
            imgui.DrawList_AddLine(draw, cx, cy, cx, cy - 4, color, 1.5)
            imgui.DrawList_AddLine(draw, cx, cy, cx + 4, cy + 2, color, 1.5)
        elseif id == "loop" then
            imgui.DrawList_AddCircle(draw, cx, cy, 7, color, 0, 1.5)
            imgui.DrawList_AddLine(draw, cx + 7, cy, cx + 3, cy - 4, color, 1.5)
            imgui.DrawList_AddLine(draw, cx + 7, cy, cx + 8, cy - 5, color, 1.5)
        else
            local text_w, text_h = imgui.CalcTextSize(ctx, label)
            imgui.DrawList_AddText(
                draw, min_x + (width - text_w) * 0.5,
                min_y + (24 - text_h) * 0.5, color, label)
        end
        if hovered then imgui.SetTooltip(ctx, tooltip) end
        return clicked
    end

    -- === COMPACT PLAYBACK ROW ===
    local row_origin_x = imgui.GetCursorPosX(ctx)
    local row_available_x = select(1, imgui.GetContentRegionAvail(ctx))
    if state.playback_row_width
        and row_available_x > state.playback_row_width then
        imgui.SetCursorPosX(
            ctx, row_origin_x
                + (row_available_x - state.playback_row_width) * 0.5)
    end
    local row_start_screen_x = select(1, imgui.GetCursorScreenPos(ctx))
    if state.is_playing then
        if state.media_kind == "midi" and state.current_file_is_one_shot then
            if CompactToggle(
                "retrigger", "\226\150\182", "Play again", false, 30) then
                StartPreview()
            end
            imgui.SameLine(ctx)
        end
        if CompactToggle(
            "stop", "\226\150\160", "Stop preview", true, 30) then
            StopPreview()
        end
    else
        if CompactToggle(
            "play", "\226\150\182", "Play preview", false, 30) then
            StartPreview()
        end
    end

    CompactDivider()
    if CompactToggle(
        "autoplay", "A", "Auto Play", state.auto_play, 28) then
        state.auto_play = not state.auto_play
        if not state.auto_play then
            state.pending_control_transport_restart_at = nil
        end
        SavePreviewPreferences("auto_play")
    end
    imgui.SameLine(ctx)
    local transport_mode = GetPreviewTransportMode()
    local transport_tooltip = transport_mode == "independent"
        and "Independent: browser has its own clock (click for Follow Arrangement)"
        or (transport_mode == "follow"
            and "Follow Arrangement: REAPER owns time (click for Control Transport)"
            or "Control Transport: browser controls REAPER from project start (click for Independent)")
    if CompactToggle(
        "transport_mode", "S", transport_tooltip,
        transport_mode ~= "independent", 30) then
        SetPreviewTransportMode(transport_mode == "independent" and "follow"
            or (transport_mode == "follow" and "control" or "independent"))
    end
    imgui.SameLine(ctx)
    if CompactToggle(
        "tempo_match", "\226\143\177",
        "Tempo Match: use REAPER's tempo matching for preview and insertion",
        state.tempo_match_enabled, 30) then
        state.tempo_match_enabled = not state.tempo_match_enabled
        ApplyPlaybackSettings("tempo")
        SavePreviewPreferences("tempo")
    end
    imgui.SameLine(ctx)
    if CompactToggle(
        "loop", "\226\134\187", "Loop preview", state.loop_preview, 28) then
        state.loop_preview = not state.loop_preview
        ApplyPlaybackSettings("loop")
        SavePreviewPreferences("loop")
    end

    CompactDivider()
    if CompactToggle(
        "half_rate", "\194\189", "Half speed",
        math.abs(state.playrate - 0.5) < 0.0001, 30) then
        SetPlayrate(0.5)
    end
    imgui.SameLine(ctx)
    if CompactToggle(
        "double_rate", "2x", "Double speed",
        math.abs(state.playrate - 2.0) < 0.0001, 32) then
        SetPlayrate(2.0)
    end

    local row_end_screen_x = select(1, imgui.GetItemRectMax(ctx))
    local measured_row_width = row_end_screen_x - row_start_screen_x
    if measured_row_width > 0 then
        state.playback_row_width = measured_row_width
    end

    -- === PITCH AND VOLUME ROW ===
    local pitch_changed, new_pitch, pitch_committed, pitch_wheel_changed =
        DrawSmoothValueControl(
            "##pitch_control",
            state.pitch_shift,
            -12, 12, 75,
            function(v) return string.format("%+d st", v) end,
            {
                wheel_step = 1,
                fine_wheel_step = 1,
                step = 1,
                reset_value = 0,
            }
        )
    if pitch_changed then
        state.pitch_shift = new_pitch
        RequestPlaybackSettingsApply(
            pitch_committed and not pitch_wheel_changed, "pitch")
    end
    if pitch_committed then
        RequestPlaybackSettingsSave(false, "pitch")
    end
    if state.media_kind == "audio" then DrawCompactAudioVolume() end
    FlushPlaybackSettingsApply()
    FlushPlaybackSettingsSave()

    DrawKeyLockPiano()

    local _, footer_end_y = imgui.GetCursorScreenPos(ctx)
    local measured_footer = math.max(100, footer_end_y - footer_start_y + 4)
    if not state.preview_footer_height
        or math.abs(state.preview_footer_height - measured_footer) > 0.5 then
        state.preview_footer_height = measured_footer
    end
    state.preview_footer_piano_open = state.piano_open

    imgui.EndChild(ctx)
end

-- ============================================================
-- MAIN LOOP
-- ============================================================
cleanup_done = false

function ClassifyInstalledFX(name, ident)
    local combined = ((name or "") .. " " .. (ident or "")):lower()
    local kind = "effect"
    if combined:find("vsti", 1, true)
        or combined:find("vst3i", 1, true)
        or combined:find("clapi", 1, true)
        or combined:find("aui", 1, true)
        or combined:find("instrument", 1, true) then
        kind = "instrument"
    end

    local format = (name or ""):match("^([^:]+):") or ""
    if format == "" then
        if combined:find("vst3", 1, true) then format = "VST3"
        elseif combined:find("vst", 1, true) then format = "VST"
        elseif combined:find("clap", 1, true) then format = "CLAP"
        elseif combined:find(" au", 1, true) then format = "AU"
        elseif combined:find("js:", 1, true) then format = "JS"
        elseif combined:find("dx", 1, true) then format = "DX"
        end
    end

    format = format:upper()
    if format == "VST3I" then format = "VST3"
    elseif format == "VSTI" or format == "VST2" or format == "VST2I" then
        format = "VST"
    elseif format == "CLAPI" then format = "CLAP"
    elseif format == "AUI" then format = "AU"
    end

    return kind, format
end

function NormalizeFXMetadataName(value)
    value = (value or ""):gsub("!!!VSTi", "")
    value = value:gsub("^[^:]+:%s*", "")
    value = value:gsub("%s+", " ")
    return value:lower():match("^%s*(.-)%s*$")
end

local LoadFXBrowserPreferences

function EncodeFXStateField(value)
    -- Parentheses force one return value. string.gsub also returns a
    -- replacement count; leaking that value appended ",0" to FX usage IDs
    -- every time state was saved and reloaded.
    return (tostring(value or ""):gsub("%%", "%%25")
        :gsub(";", "%%3B"):gsub(",", "%%2C")
        :gsub("\t", "%%09"):gsub("\r", "%%0D"):gsub("\n", "%%0A"))
end

function DecodeFXStateField(value)
    return (tostring(value or ""):gsub("%%(%x%x)", function(hex)
        return string.char(tonumber(hex, 16))
    end))
end

function GetFXInventoryCachePath()
    return GetReaBrowseDataDirectory() .. "/ReaBrowse_FX_Inventory.tsv"
end

function SaveFXInventoryCache()
    if not EnsureReaBrowseDataLayout() then return false end
    local target = GetFXInventoryCachePath()
    local temporary = target .. ".tmp"
    local file = io.open(temporary, "w")
    if not file then return false end
    file:write("ReaBrowseFXInventory\t1\n")
    for _, item in ipairs(state.fx_browser.items or {}) do
        file:write(table.concat({
            EncodeFXStateField(item.ident),
            EncodeFXStateField(item.name),
            EncodeFXStateField(item.kind),
            EncodeFXStateField(item.format),
            EncodeFXStateField(item.maker),
            EncodeFXStateField(item.category),
        }, "\t"), "\n")
    end
    file:close()
    pcall(os.remove, target)
    local ok = os.rename(temporary, target)
    if not ok then pcall(os.remove, temporary) end
    return ok == true
end

function LoadFXInventoryCache()
    local fx = state.fx_browser
    local file = io.open(GetFXInventoryCachePath(), "r")
    if not file then return false end
    if file:read("*l") ~= "ReaBrowseFXInventory\t1" then
        file:close()
        return false
    end
    local items = {}
    for line in file:lines() do
        local fields = {}
        for field in (line .. "\t"):gmatch("(.-)\t") do
            fields[#fields + 1] = DecodeFXStateField(field)
        end
        local ident, name = fields[1], fields[2]
        if ident and ident ~= "" and name and name ~= "" then
            local maker = fields[5] or ""
            items[#items + 1] = {
                ident = ident,
                name = name,
                name_lower = name:lower(),
                ident_lower = ident:lower(),
                kind = fields[3] ~= "" and fields[3] or "effect",
                format = fields[4] ~= "" and fields[4] or "Other",
                maker = maker,
                maker_lower = maker:lower(),
                category = fields[6] ~= "" and fields[6] or "Effects",
            }
        end
    end
    file:close()
    if #items == 0 then return false end
    fx.items = items
    fx.filtered_items = {}
    fx.scanning = false
    fx.scan_complete = true
    fx.generation = fx.generation + 1
    fx.filtered_generation = -1
    fx.group_cache = {}
    fx.status = string.format("%d cached plug-ins ready.", #items)
    return true
end

function EachFXStateRecord(value, callback)
    value = tostring(value or "")
    if value:sub(1, 3) ~= "v2;" then return end
    for record in value:sub(4):gmatch("[^;]+") do callback(record) end
end

function LoadREAPERFXMetadata()
    local fx = state.fx_browser
    if fx.metadata_loaded then return end
    fx.metadata_loaded = true

    local resource = r.GetResourcePath()
    local tags = io.open(resource .. "/reaper-fxtags.ini", "r")
    if tags then
        local section = ""
        for line in tags:lines() do
            local header = line:match("^%[([^]]+)%]$")
            if header then
                section = header:lower()
            else
                local key, value = line:match("^([^=]+)=(.*)$")
                if key and value then
                    key = key:lower()
                    if section == "developer" then
                        fx.metadata_developer[key] = value
                    elseif section == "category" then
                        fx.metadata_category[key] = value
                    end
                end
            end
        end
        tags:close()
    end

    local vst_cache = io.open(resource .. "/reaper-vstplugins64.ini", "r")
    if vst_cache then
        local in_cache = false
        for line in vst_cache:lines() do
            local header = line:match("^%[([^]]+)%]$")
            if header then
                in_cache = header:lower() == "vstcache"
            elseif in_cache then
                local key, value = line:match("^([^=]+)=(.*)$")
                if key and value then
                    local display = value:match("^[^,]*,[^,]*,(.*)$")
                    if display then
                        fx.metadata_display_key[
                            NormalizeFXMetadataName(display)] = key:lower()
                    end
                end
            end
        end
        vst_cache:close()
    end

    local recent = io.open(resource .. "/reaper-recentfx.ini", "r")
    if recent then
        for line in recent:lines() do
            local index, value = line:match("^Name(%d+)=(.*)$")
            if index and value then
                fx.recent_names[tonumber(index) + 1] = value
            end
        end
        recent:close()
    end

    local saved_folders = r.GetExtState(EXT_SECTION, "FXFavoriteFolders")
    EachFXStateRecord(saved_folders, function(record)
        local path = DecodeFXStateField(record)
        if path ~= "" then fx.favorite_folders[path] = true end
    end)
    local saved_favorites = r.GetExtState(EXT_SECTION, "FXFavorites")
    EachFXStateRecord(saved_favorites, function(line)
        local encoded_folder, encoded_ident = line:match("^(.-),(.*)$")
        local folder = DecodeFXStateField(encoded_folder)
        local ident = DecodeFXStateField(encoded_ident)
        if folder and ident and ident ~= "" then
            fx.favorites[ident] = true
            fx.favorite_memberships[ident] = fx.favorite_memberships[ident] or {}
            fx.favorite_memberships[ident][folder ~= ""
                and folder or RB_FAVORITES_ROOT_MEMBERSHIP] = true
        end
    end)
    local saved_usage = r.GetExtState(EXT_SECTION, "FXUsage")
    local repaired_usage = false
    EachFXStateRecord(saved_usage, function(line)
        local count, last_used, sequence, encoded_ident =
            line:match("^(%d+),(%d+),(%d+),(.*)$")
        local ident = DecodeFXStateField(encoded_ident)
        if ident and ident ~= "" then
            local repaired = 0
            while ident:sub(-2) == ",0" do
                ident = ident:sub(1, -3)
                repaired = repaired + 1
            end
            if repaired > 0 then
                repaired_usage = true
            end
            local existing = fx.usage[ident]
            local loaded_count = tonumber(count) or 0
            local loaded_last_used = tonumber(last_used) or 0
            local loaded_sequence = tonumber(sequence) or 0
            if existing then
                -- Corrupted identifiers forked the same plug-in's history on
                -- successive launches. Merge those records back together.
                existing.count = (existing.count or 0) + loaded_count
                existing.last_used = math.max(
                    existing.last_used or 0, loaded_last_used)
                existing.sequence = math.max(
                    existing.sequence or 0, loaded_sequence)
                repaired_usage = true
            else
                fx.usage[ident] = {
                    count = loaded_count,
                    last_used = loaded_last_used,
                    sequence = loaded_sequence,
                }
            end
            fx.usage_generation = math.max(
                fx.usage_generation or 0, loaded_sequence)
        end
    end)
    LoadFXBrowserPreferences()
    if repaired_usage then
        SaveFXFavorites()
    end
end

function SaveFXFavorites()
    local fx = state.fx_browser
    fx.filtered_generation = -1
    fx.favorite_generation = (fx.favorite_generation or 0) + 1
    fx.favorite_view_cache_signature = nil
    fx.row_key_cache = {}
    local folders = {}
    for path in pairs(fx.favorite_folders) do
        folders[#folders + 1] = EncodeFXStateField(path)
    end
    table.sort(folders)
    r.SetExtState(
        EXT_SECTION, "FXFavoriteFolders", "v2;" .. table.concat(folders, ";"), true)

    local favorites = {}
    for ident in pairs(fx.favorites) do
        local memberships = fx.favorite_memberships[ident] or {}
        local wrote = false
        for folder in pairs(memberships) do
            local persisted_folder = folder == RB_FAVORITES_ROOT_MEMBERSHIP
                and "" or folder
            favorites[#favorites + 1] = EncodeFXStateField(persisted_folder)
                .. "," .. EncodeFXStateField(ident)
            wrote = true
        end
        if not wrote then
            favorites[#favorites + 1] = "," .. EncodeFXStateField(ident)
        end
    end
    table.sort(favorites)
    r.SetExtState(
        EXT_SECTION, "FXFavorites", "v2;" .. table.concat(favorites, ";"), true)

    local usage = {}
    for ident, record in pairs(fx.usage or {}) do
        usage[#usage + 1] = table.concat({
            tostring(record.count or 0), tostring(record.last_used or 0),
            tostring(record.sequence or 0), EncodeFXStateField(ident)
        }, ",")
    end
    table.sort(usage)
    r.SetExtState(
        EXT_SECTION, "FXUsage", "v2;" .. table.concat(usage, ";"), true)
end

function RecordFXUse(item, defer_save)
    if not item or not item.ident then return end
    local fx = state.fx_browser
    local record = fx.usage[item.ident] or {count = 0, last_used = 0, sequence = 0}
    record.count = (record.count or 0) + 1
    record.last_used = os.time()
    fx.usage_generation = (fx.usage_generation or 0) + 1
    record.sequence = fx.usage_generation
    fx.usage[item.ident] = record
    fx.smart_cache = {}
    fx.usage_dirty = true
    if not defer_save then SaveFXFavorites() end
end

function SaveFXBrowserPreferences()
    local fx = state.fx_browser
    r.SetExtState(EXT_SECTION, "FXTypeFilter", fx.type_filter, true)
    r.SetExtState(EXT_SECTION, "FXViewMode", fx.view_mode, true)
    r.SetExtState(EXT_SECTION, "FXSortMode", fx.sort_mode, true)
    local enabled = {}
    for format, value in pairs(fx.format_enabled) do
        if value then enabled[#enabled + 1] = format end
    end
    table.sort(enabled)
    r.SetExtState(
        EXT_SECTION, "FXFormatFilters", table.concat(enabled, "|"), true)
end

LoadFXBrowserPreferences = function()
    local fx = state.fx_browser
    local type_filter = r.GetExtState(EXT_SECTION, "FXTypeFilter")
    if type_filter == "all" or type_filter == "instrument"
        or type_filter == "effect" then
        fx.type_filter = type_filter
    end
    local view_mode = r.GetExtState(EXT_SECTION, "FXViewMode")
    if view_mode == "category" or view_mode == "vendor"
        or view_mode == "all" then
        fx.view_mode = view_mode
    end
    local sort_mode = r.GetExtState(EXT_SECTION, "FXSortMode")
    if sort_mode == "name_az" or sort_mode == "name_za"
        or sort_mode == "maker" or sort_mode == "format"
        or sort_mode == "type" then
        fx.sort_mode = sort_mode
    end
    local formats = r.GetExtState(EXT_SECTION, "FXFormatFilters")
    for format in (formats or ""):gmatch("[^|]+") do
        fx.format_enabled[format] = true
    end
end

function ResolveFXMetadata(name, ident)
    local fx = state.fx_browser
    local keys = {}
    local ident_lower = (ident or ""):lower()
    keys[#keys + 1] = ident_lower
    keys[#keys + 1] = ident_lower:gsub("^[^:]+:%s*", "")
    keys[#keys + 1] = ident_lower:match("([^/\\]+)$") or ""
    local display_key =
        fx.metadata_display_key[NormalizeFXMetadataName(name)]
    if display_key then keys[#keys + 1] = display_key end

    local developer, category = nil, nil
    for _, key in ipairs(keys) do
        if key ~= "" then
            developer = developer or fx.metadata_developer[key]
            category = category or fx.metadata_category[key]
        end
    end
    return developer, category
end

function StartFXScan()
    local fx = state.fx_browser
    LoadREAPERFXMetadata()
    -- REAPER 7.42+ requires EnumInstalledFX(-1) to re-read JSFX metadata
    -- before enumerating. Without this, a newly added JSFX can appear in
    -- REAPER's FX browser but remain absent from ReaBrowse's inventory.
    pcall(r.EnumInstalledFX, -1)
    fx.items = {}
    fx.filtered_items = {}
    fx.scan_index = 0
    fx.scanning = true
    fx.scan_complete = false
    fx.generation = fx.generation + 1
    fx.filtered_generation = -1
    fx.chain_tree = nil
    fx.track_template_tree = nil
    fx.preset_init_deferred = false
    fx.template_init_deferred = false
    fx.preset_search_query = nil
    fx.chain_search_results = {}
    fx.template_search_results = {}
    fx.group_cache = {}
    fx.status = "Refreshing installed plug-ins..."
end

function ProcessFXScan()
    local fx = state.fx_browser
    if not fx.scanning then return end

    local per_frame = 32
    for _ = 1, per_frame do
        local ok, found, name, ident = pcall(r.EnumInstalledFX, fx.scan_index)
        if not ok or not found then
            fx.scanning = false
            fx.scan_complete = true
            fx.generation = fx.generation + 1
            fx.status = "Plug-ins ready."
            SaveFXInventoryCache()
            return
        end

        name = name or ident or ("Plug-in " .. tostring(fx.scan_index + 1))
        ident = ident or name
        local kind, format = ClassifyInstalledFX(name, ident)
        local maker = name:match("%(([^()]*)%)%s*$") or ""
        if maker:lower() == "x64" or maker:lower() == "x86"
            or maker:lower() == "64-bit" or maker:lower() == "32-bit" then
            maker = ""
        end
        local metadata_maker, category = ResolveFXMetadata(name, ident)
        if metadata_maker and metadata_maker ~= "" then maker = metadata_maker end
        if category and maker ~= ""
            and category:lower() == maker:lower() then
            category = nil
        end
        if not category or category == "" then
            category = kind == "instrument" and "Instruments" or "Effects"
        end
        fx.items[#fx.items + 1] = {
            name = name,
            ident = ident,
            name_lower = name:lower(),
            ident_lower = ident:lower(),
            kind = kind,
            format = format,
            maker = maker,
            maker_lower = maker:lower(),
            category = category,
        }
        fx.scan_index = fx.scan_index + 1
    end
    -- Rebuilding and sorting the filtered list after every 32 discovered
    -- plug-ins wastes GUI time. Publish progress in larger batches, then once
    -- more when enumeration completes.
    if fx.scan_index % 256 == 0 then
        fx.generation = fx.generation + 1
    end
    fx.status = "Refreshing plug-in list..."
end

function UpdateFXFilter()
    local fx = state.fx_browser
    local enabled_formats = {}
    for format, enabled in pairs(fx.format_enabled) do
        if enabled then enabled_formats[#enabled_formats + 1] = format end
    end
    table.sort(enabled_formats)
    local format_signature = table.concat(enabled_formats, "|")
    if fx.filtered_generation == fx.generation
        and fx.last_search == fx.search
        and fx.last_type_filter == fx.type_filter
        and fx.last_format_signature == format_signature
        and fx.last_maker_filter == fx.maker_filter
        and fx.last_sort_mode == fx.sort_mode then
        return
    end

    local query = NormalizeBrowserSearchTokens(fx.search)
    local maker_query = NormalizeBrowserSearchTokens(fx.maker_filter)
    local results = {}
    for _, item in ipairs(fx.items) do
        item.search_text = item.search_text or NormalizeBrowserSearchTokens(
            item.name .. " " .. item.ident .. " " .. item.maker .. " "
                .. item.category .. " " .. item.format)
        item.maker_search_text = item.maker_search_text
            or NormalizeBrowserSearchTokens(item.maker .. " " .. item.ident)
        local type_ok = fx.type_filter == "all" or item.kind == fx.type_filter
        local format_ok = #enabled_formats == 0
            or fx.format_enabled[item.format] == true
        local maker_ok = maker_query == ""
            or BrowserSearchTokensMatch(item.maker_search_text, maker_query)
        local search_ok = BrowserSearchTokensMatch(item.search_text, query)
        if type_ok and format_ok and maker_ok and search_ok then
            results[#results + 1] = item
        end
    end

    table.sort(results, function(a, b)
        local a_favorite = fx.favorites[a.ident] ~= nil
        local b_favorite = fx.favorites[b.ident] ~= nil
        if a_favorite ~= b_favorite then return a_favorite end
        if fx.sort_mode == "name_za" then
            return a.name_lower > b.name_lower
        elseif fx.sort_mode == "maker" then
            local am = a.maker_lower ~= "" and a.maker_lower or "\255"
            local bm = b.maker_lower ~= "" and b.maker_lower or "\255"
            if am ~= bm then return am < bm end
        elseif fx.sort_mode == "format" then
            if a.format ~= b.format then return a.format < b.format end
        elseif fx.sort_mode == "type" then
            if a.kind ~= b.kind then return a.kind < b.kind end
        end
        return a.name_lower < b.name_lower
    end)

    fx.row_key_cache = {}
    fx.filtered_items = results
    fx.filtered_generation = fx.generation
    fx.last_search = fx.search
    fx.last_type_filter = fx.type_filter
    fx.last_format_signature = format_signature
    fx.last_maker_filter = fx.maker_filter
    fx.last_sort_mode = fx.sort_mode
    fx.group_cache = {}
end

function GetTrackFXShowIndex(fx_index, rec_fx)
    -- TrackFX_AddByName returns a position within the selected chain, while
    -- the other TrackFX APIs address input/monitoring FX with the high bit.
    if rec_fx and fx_index >= 0 and fx_index < 0x1000000 then
        return fx_index + 0x1000000
    end
    return fx_index
end

function GetFXChainDestinationName(track, rec_fx)
    if rec_fx and track == r.GetMasterTrack(0) then return "Monitoring FX" end
    return rec_fx and "input FX" or "track FX"
end

function GetFXInstantiatePosition(insert_index)
    if insert_index == nil then return -1 end
    return -1000 - math.max(0, math.floor(insert_index))
end

function ShowAddedTrackFX(track, fx_index, rec_fx, show_chain)
    local index = GetTrackFXShowIndex(fx_index, rec_fx)
    -- Let REAPER finish its chain-window updates before floating the new FX.
    -- Resolve by GUID because the chain can change before the deferred call.
    local guid = r.TrackFX_GetFXGUID(track, index)
    r.defer(function()
        if not r.ValidatePtr2(0, track, "MediaTrack*") then return end
        local count = rec_fx and r.TrackFX_GetRecCount(track)
            or r.TrackFX_GetCount(track)
        for i = 0, count - 1 do
            local candidate = GetTrackFXShowIndex(i, rec_fx)
            if r.TrackFX_GetFXGUID(track, candidate) == guid then
                r.TrackFX_Show(track, candidate, 3)
                return
            end
        end
    end)
end

function GetSelectedTrackFXInsertIndex(track, rec_fx)
    local get_visible = rec_fx and r.TrackFX_GetRecChainVisible
        or (not rec_fx and r.TrackFX_GetChainVisible)
    if not get_visible then return nil end
    local index = get_visible(track)
    if index and index >= 0 and (index & 0x2000000) == 0 then
        return index & 0xFFFFFF
    end
end

function ConfigureTrackForInstrumentInput(track)
    if not track or track == r.GetMasterTrack(0) then return end
    -- Match REAPER's virtual-instrument insertion defaults: all MIDI inputs,
    -- all channels, armed, with input monitoring enabled.
    r.SetMediaTrackInfo_Value(track, "I_RECINPUT", 6112)
    r.SetMediaTrackInfo_Value(track, "I_RECARM", 1)
    r.SetMediaTrackInfo_Value(track, "I_RECMON", 1)
end

function GetTrackFXSlotInsertIndex(track, slot, rec_fx)
    local count = rec_fx and r.TrackFX_GetRecCount(track)
        or r.TrackFX_GetCount(track)
    -- Slot mapping needs an existing chain. The first FX always has chain
    -- index zero; slot_hint places it in the requested visual mixer slot.
    if count == 0 then return 0 end
    if not r.TrackFX_GetNamedConfigParm then return nil end
    local address = slot + (rec_fx and 0x1000000 or 0)
    local ok, value = r.TrackFX_GetNamedConfigParm(
        track, address, "chain_slot_to_index")
    if not ok then return nil end
    local index = tonumber(value) or tonumber(tostring(value):match("^empty:(%d+)$"))
    if not index then return nil end
    return index & 0xFFFFFF
end

function GetFXPanelDropSlot(info)
    return tonumber(tostring(info or ""):match("^[tm]cp%.fxlist%s+(%d+)$"))
end

function AddFXToTrack(item, track, rec_fx, show_chain, insert_index, insert_slot)
    if not track then
        state.fx_browser.status = "Select a track, then add the plug-in."
        return false
    end

    if insert_slot ~= nil then
        insert_index = GetTrackFXSlotInsertIndex(track, insert_slot, rec_fx)
        if insert_index == nil then
            state.fx_browser.status = "REAPER could not resolve the destination FX slot."
            return false
        end
    end
    r.Undo_BeginBlock()
    local instantiate = GetFXInstantiatePosition(insert_index)
    local fx_index = r.TrackFX_AddByName(
        track, item.ident, rec_fx == true, instantiate)
    if fx_index < 0 and item.name ~= item.ident then
        fx_index = r.TrackFX_AddByName(
            track, item.name, rec_fx == true, instantiate)
    end
    if fx_index >= 0 then
        if insert_slot ~= nil then
            r.TrackFX_SetNamedConfigParm(track,
                GetTrackFXShowIndex(fx_index, rec_fx), "slot_hint", tostring(insert_slot))
        end
        if item.kind == "instrument" and not rec_fx then
            ConfigureTrackForInstrumentInput(track)
        end
        ShowAddedTrackFX(track, fx_index, rec_fx, show_chain)
        RecordFXUse(item)
        local display_name = (item.name or item.ident or "")
            :gsub("^[^:]+:%s*", "")
        SetTrackNameIfBlank(track, display_name)
        local destination = GetFXChainDestinationName(track, rec_fx)
        local action = "Add " .. destination .. ": "
        r.Undo_EndBlock(action .. item.name, -1)
        state.fx_browser.status = "Added to " .. destination .. ": " .. item.name
        return true
    end

    r.Undo_EndBlock("Add FX", -1)
    state.fx_browser.status = "REAPER could not add: " .. item.name
    return false
end

function AddFXToSelectedTrack(item, rec_fx)
    local track = r.GetSelectedTrack(0, 0)
    local insert_index = track and GetSelectedTrackFXInsertIndex(track, rec_fx)
    return AddFXToTrack(item, track, rec_fx, false, insert_index)
end

function AddFXItemsToTrack(items, track, rec_fx, show_chain, insert_index, insert_slot)
    if not items or #items == 0 then return false end
    -- Browser buttons/menus use the chain selection; direct track drops pass
    -- show_chain=false explicitly and continue to append.
    if track and show_chain == nil and insert_index == nil then
        insert_index = GetSelectedTrackFXInsertIndex(track, rec_fx)
    end
    if #items == 1 then
        return AddFXToTrack(
            items[1], track, rec_fx, show_chain, insert_index, insert_slot)
    end
    if not track then
        state.fx_browser.status = "Select a track, then add the plug-ins."
        return false
    end

    r.Undo_BeginBlock()
    local added, last_index = 0, nil
    local added_instrument = false
    local track_names = {}
    for _, item in ipairs(items) do
        local slot = insert_slot and (insert_slot + added) or nil
        local position
        if slot ~= nil then
            position = GetTrackFXSlotInsertIndex(track, slot, rec_fx)
        else
            position = insert_index and (insert_index + added) or nil
        end
        if slot ~= nil and position == nil then break end
        local instantiate = GetFXInstantiatePosition(
            position)
        local fx_index = r.TrackFX_AddByName(
            track, item.ident, rec_fx == true, instantiate)
        if fx_index < 0 and item.name ~= item.ident then
            fx_index = r.TrackFX_AddByName(
                track, item.name, rec_fx == true, instantiate)
        end
        if fx_index >= 0 then
            if slot ~= nil then
                r.TrackFX_SetNamedConfigParm(track,
                    GetTrackFXShowIndex(fx_index, rec_fx), "slot_hint", tostring(slot))
            end
            added = added + 1
            last_index = fx_index
            added_instrument = added_instrument or item.kind == "instrument"
            local display_name = (item.name or item.ident or "")
                :gsub("^[^:]+:%s*", "")
            if display_name ~= "" then
                track_names[#track_names + 1] = display_name
            end
            RecordFXUse(item, true)
        end
    end
    if added_instrument and not rec_fx then
        ConfigureTrackForInstrumentInput(track)
    end
    if #track_names > 0 then
        SetTrackNameIfBlank(track, table.concat(track_names, " + "))
    end
    if added > 0 then SaveFXFavorites() end
    if last_index then
        ShowAddedTrackFX(track, last_index, rec_fx, show_chain)
    end
    local destination = GetFXChainDestinationName(track, rec_fx)
    local action = "Add " .. destination
    r.Undo_EndBlock(action .. " (" .. tostring(#items) .. " plug-ins)", -1)
    state.fx_browser.status = added == #items
        and ("Added " .. tostring(added) .. " plug-ins to " .. destination .. ".")
        or ("Added " .. tostring(added) .. " of " .. tostring(#items)
            .. " plug-ins to " .. destination .. ".")
    return added > 0
end

function GetTakeFXDestinationName(take)
    return take and r.TakeIsMIDI and r.TakeIsMIDI(take)
        and "MIDI item FX" or "audio item FX"
end

function AddFXItemsToTake(items, take, show_chain)
    if not items or #items == 0 then return false end
    if not take or not r.TakeFX_AddByName then
        state.fx_browser.status = "Drop on an audio or MIDI item with an active take."
        return false
    end

    r.Undo_BeginBlock()
    local added, last_index = 0, nil
    for _, item in ipairs(items) do
        -- A negative instantiate value always creates a fresh instance. This
        -- is a drop operation, so it must not resolve to an existing plug-in.
        local fx_index = r.TakeFX_AddByName(take, item.ident, -1)
        if fx_index < 0 and item.name ~= item.ident then
            fx_index = r.TakeFX_AddByName(take, item.name, -1)
        end
        if fx_index >= 0 then
            added = added + 1
            last_index = fx_index
            RecordFXUse(item, true)
        end
    end
    if added > 0 then SaveFXFavorites() end
    if last_index and r.TakeFX_Show then
        r.TakeFX_Show(take, last_index, show_chain and 1 or 3)
    end
    local destination = GetTakeFXDestinationName(take)
    r.Undo_EndBlock("Add " .. destination .. " ("
        .. tostring(#items) .. " plug-in"
        .. (#items == 1 and ")" or "s)"), -1)
    r.UpdateArrange()
    state.fx_browser.status = added == #items
        and ("Added " .. tostring(added) .. " plug-in"
            .. (added == 1 and "" or "s") .. " to " .. destination .. ".")
        or ("Added " .. tostring(added) .. " of " .. tostring(#items)
            .. " plug-ins to " .. destination .. ".")
    return added > 0
end

function CreateTrackWithFXItems(items, rec_fx)
    if not items or #items == 0 then return false end
    local track_index = r.CountTracks(0)
    r.Undo_BeginBlock()
    r.InsertTrackAtIndex(track_index, true)
    local track = r.GetTrack(0, track_index)
    if track then
        r.SetOnlyTrackSelected(track)
        r.TrackList_AdjustWindows(false)
    end
    if not track then
        r.Undo_EndBlock("Create track for plug-ins", -1)
        state.fx_browser.status = "REAPER could not create the destination track."
        return false
    end
    local added, last_index = 0, nil
    local added_instrument = false
    local track_names = {}
    for _, item in ipairs(items) do
        local fx_index = r.TrackFX_AddByName(
            track, item.ident, rec_fx == true, -1)
        if fx_index < 0 and item.name ~= item.ident then
            fx_index = r.TrackFX_AddByName(
                track, item.name, rec_fx == true, -1)
        end
        if fx_index >= 0 then
            added = added + 1
            last_index = fx_index
            added_instrument = added_instrument or item.kind == "instrument"
            local display_name = (item.name or item.ident or "")
                :gsub("^[^:]+:%s*", "")
            if display_name ~= "" then
                track_names[#track_names + 1] = display_name
            end
            RecordFXUse(item, true)
        end
    end
    if added_instrument and not rec_fx then
        ConfigureTrackForInstrumentInput(track)
    end
    if #track_names > 0 then
        SetTrackNameIfBlank(track, table.concat(track_names, " + "))
    end
    if added > 0 then SaveFXFavorites() end
    if last_index then
        ShowAddedTrackFX(track, last_index, rec_fx, false)
    end
    local action = rec_fx and "Create track with input FX"
        or "Create track with FX"
    r.Undo_EndBlock(action, -1)
    state.fx_browser.status = added == #items
        and ("Created track with " .. tostring(added) .. " plug-in"
            .. (added == 1 and "." or "s."))
        or ("Created track with " .. tostring(added) .. " of "
            .. tostring(#items) .. " plug-ins.")
    return added > 0
end

function GetFXWindowPathAtPoint(mouse_x, mouse_y)
    -- WindowFromPoint returns the deepest control under the cursor. Retain its
    -- complete parent path so docked chains, floating chains, and plug-in UIs
    -- can all be classified from their REAPER window titles.
    local window_from_point, get_window_title, get_parent
    if r.BR_Win32_WindowFromPoint and r.BR_Win32_GetWindowText
        and r.BR_Win32_GetParent then
        window_from_point = r.BR_Win32_WindowFromPoint
        get_window_title = function(hwnd)
            -- SWS builds expose this as either `string title` or
            -- `boolean ok, string title`. Accept both ABI wrappers; taking
            -- only the second result made every title blank on the former,
            -- so docked sampler windows looked like ordinary REAPER chrome
            -- and never started the Shell-native file drag.
            local first, second = r.BR_Win32_GetWindowText(hwnd)
            if type(second) == "string" then return second end
            return type(first) == "string" and first or ""
        end
        get_parent = r.BR_Win32_GetParent
    elseif r.JS_Window_FromPoint and r.JS_Window_GetTitle
        and r.JS_Window_GetParent then
        window_from_point = r.JS_Window_FromPoint
        get_window_title = r.JS_Window_GetTitle
        get_parent = r.JS_Window_GetParent
    else
        return {}
    end

    local ok, hwnd = pcall(window_from_point, mouse_x, mouse_y)
    if not ok or not hwnd then return {} end
    local path, visited = {}, {}
    for _ = 1, 16 do
        if not hwnd or visited[hwnd] then break end
        visited[hwnd] = true
        local title_ok, title = pcall(get_window_title, hwnd)
        path[#path + 1] = {
            hwnd = hwnd,
            title = title_ok and tostring(title or "") or "",
        }
        local parent_ok, parent = pcall(get_parent, hwnd)
        if not parent_ok or not parent or parent == hwnd then break end
        hwnd = parent
    end
    return path
end

function ClassifyFXWindowPath(path)
    local saw_track_fx = false
    for _, entry in ipairs(path or {}) do
        local title = tostring(entry.title or ""):lower()
        local trimmed = title:match("^%s*(.-)%s*$")
        if trimmed == "monitoring fx" or trimmed == "monitor fx"
            or title:find("monitoring fx", 1, true)
            or title:find("fx: monitoring", 1, true)
            or title:find("fx:monitoring", 1, true) then
            return "monitoring_fx", entry.title
        end
        if title:find("input fx", 1, true)
            or title:find("input/monitoring", 1, true)
            or title:find("record input fx", 1, true)
            or title:find("record fx", 1, true)
            or title:find("rec fx", 1, true) then
            return "input_fx", entry.title
        end
        -- A floating plug-in's top-level window often has only its format
        -- prefix (for example `VSTi: Kontakt 7`) and no `FX:` ancestor.
        -- Treat those standard REAPER plug-in titles as explicit file-drop
        -- targets so sampler drags enter OLE before the mouse is released.
        -- Requiring the colon avoids matching ordinary window text that just
        -- happens to contain a format name.
        if trimmed:match("^vst%d?i?:")
            or trimmed:match("^clap[i]?:")
            or trimmed:match("^au[i]?:")
            or trimmed:match("^lv2i?:")
            or trimmed:match("^dxi?:")
            or trimmed:match("^js:") then
            saw_track_fx = entry.title
        end
        if title:find("fx:", 1, true)
            or title:find("fx chain", 1, true)
            or title:find("add fx", 1, true) then
            saw_track_fx = entry.title
        end
    end
    return saw_track_fx and "track_fx" or nil, saw_track_fx or nil
end

function GetExplicitFXDropTarget(mouse_x, mouse_y)
    local path = GetFXWindowPathAtPoint(mouse_x, mouse_y)
    local window_kind, window_title = ClassifyFXWindowPath(path)
    local track, info = nil, ""
    if r.GetThingFromPoint then
        local ok, found_track, found_info = pcall(
            r.GetThingFromPoint, mouse_x, mouse_y)
        if ok then
            track = found_track
            info = tostring(found_info or ""):lower()
        end
    end

    -- GetTrackFromPoint explicitly reports track-associated FX windows via
    -- info bit 2. It is a useful fallback for older GetThingFromPoint builds.
    local track_point_fx = false
    if r.GetTrackFromPoint then
        local ok, found_track, point_info = pcall(
            r.GetTrackFromPoint, mouse_x, mouse_y)
        if ok and found_track and ((tonumber(point_info) or 0) & 2) ~= 0 then
            track = track or found_track
            track_point_fx = true
        end
    end

    local fx_address = tonumber(info:match("^fx_(%d+)"))
    local encoded_input = fx_address
        and (fx_address & 0x1000000) ~= 0 or false
    local input_button = info:find("fxin", 1, true)
        or info:find("input_fx", 1, true)
    local monitoring_info = info:find("monitor", 1, true)
        and info:find("fx", 1, true)
    local fx_info = info == "fx_chain" or fx_address ~= nil
        or input_button ~= nil or info:match("^[tm]cp%.fx") ~= nil
    local explicit = fx_info or track_point_fx or window_kind ~= nil
    if not explicit then return nil end

    local kind = window_kind
    if monitoring_info then kind = "monitoring_fx" end
    if encoded_input or input_button then kind = "input_fx" end
    -- REAPER reports the global Monitor FX button/chain as a trackless
    -- fx_chain hit. Other Add/FX windows identify their track or title.
    if info == "fx_chain" and not track and not window_kind then
        kind = "monitoring_fx"
    end
    if kind == "monitoring_fx" then
        track = r.GetMasterTrack(0)
    elseif not track then
        -- A title alone can identify Monitoring FX, but other chain windows
        -- still require an associated destination track.
        return nil
    elseif kind == "input_fx" and track == r.GetMasterTrack(0) then
        kind = "monitoring_fx"
    else
        kind = kind or "track_fx"
    end

    local insert_index = nil
    local insert_slot = GetFXPanelDropSlot(info)
    if fx_address and (fx_address & 0x2000000) == 0 then
        insert_index = fx_address & 0xFFFFFF
    elseif info == "fx_chain" or window_kind ~= nil or track_point_fx then
        insert_index = GetSelectedTrackFXInsertIndex(
            track, kind == "input_fx" or kind == "monitoring_fx")
    end
    return {
        track = track,
        kind = kind,
        explicit_chain = true,
        insert_index = insert_index,
        insert_slot = insert_slot,
        region = info ~= "" and info or (window_title or "fx_window"),
    }
end

function GetFXTakeDropTarget(mouse_x, mouse_y)
    local take, item
    if r.GetTakeFromPoint then
        local ok, found_take = pcall(r.GetTakeFromPoint, mouse_x, mouse_y)
        if ok then take = found_take end
    end
    if r.GetItemFromPoint then
        local ok, found_item, found_take = pcall(
            r.GetItemFromPoint, mouse_x, mouse_y, true)
        if ok then
            item = found_item
            take = take or found_take
        end
    end
    if not item and r.BR_GetMouseCursorContext_Item then
        local ok, found_item = pcall(r.BR_GetMouseCursorContext_Item)
        if ok then item = found_item end
    end
    if not take and r.BR_GetMouseCursorContext_Take then
        local ok, found_take = pcall(r.BR_GetMouseCursorContext_Take)
        if ok then take = found_take end
    end
    if not take and item and r.GetActiveTake then
        take = r.GetActiveTake(item)
    end
    if not item and take and r.GetMediaItemTake_Item then
        item = r.GetMediaItemTake_Item(take)
    end
    if not take then return nil end
    local midi = r.TakeIsMIDI and r.TakeIsMIDI(take) or false
    return {
        item = item,
        take = take,
        kind = "take_fx",
        region = midi and "midi_item" or "audio_item",
    }
end

function GetFXDropTarget(mouse_x, mouse_y)
    local explicit = GetExplicitFXDropTarget(mouse_x, mouse_y)
    if explicit then return explicit end

    -- SWS reports generic arrange/TCP/MCP destinations without mistaking
    -- unrelated track-owned windows for a track-row drop.
    if r.BR_GetMouseCursorContext then
        local window = select(1, r.BR_GetMouseCursorContext())
        if window == "arrange" or window == "tcp" or window == "mcp" then
            if window == "arrange" then
                local take_target = GetFXTakeDropTarget(mouse_x, mouse_y)
                if take_target then return take_target end
            end
            local track = r.BR_GetMouseCursorContext_Track()
            return {
                track = track,
                kind = "track",
                create_new =
                    (window == "arrange" or window == "tcp") and track == nil,
                region = window,
            }
        end
        return {kind = "invalid", region = window}
    end

    local take_target = GetFXTakeDropTarget(mouse_x, mouse_y)
    if take_target then return take_target end

    if r.GetThingFromPoint then
        local track, info = r.GetThingFromPoint(mouse_x, mouse_y)
        info = (info or ""):lower()
        local valid_region = info:find("tcp", 1, true)
            or info:find("mcp", 1, true)
            or info:find("track", 1, true)
            or info:find("arrange", 1, true)
        if valid_region then
            return {track = track, kind = "track", region = info}
        end
    end
    return {kind = "invalid"}
end

function DrawFXToolbarIcon(kind, active, tooltip)
    local size = 28
    local clicked = imgui.InvisibleButton(
        ctx, "##fx_toolbar_" .. tostring(kind), size, size)
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local max_x, max_y = imgui.GetItemRectMax(ctx)
    local hovered = imgui.IsItemHovered(ctx)
    local accent = state.resolved_theme and state.resolved_theme.accent
        or state.theme.colors.accent
    local normal = state.resolved_theme and state.resolved_theme.text
        or state.theme.colors.text
    local color = (active or hovered) and accent or normal
    local draw = imgui.GetWindowDrawList(ctx)
    if active or hovered then
        imgui.DrawList_AddRectFilled(
            draw, min_x, min_y, max_x, max_y,
            (accent & 0xFFFFFF00) | (hovered and 0x24 or 0x14), 3)
    end
    local cx, cy = (min_x + max_x) * 0.5, (min_y + max_y) * 0.5
    if kind == "refresh" then
        imgui.DrawList_AddCircle(draw, cx, cy, 7, color, 0, 1.5)
        imgui.DrawList_AddTriangleFilled(
            draw, cx + 7, cy - 5, cx + 8, cy + 1,
            cx + 3, cy - 1, color)
    elseif kind == "categories" then
        for row = 0, 1 do
            for column = 0, 1 do
                local x = cx - 8 + column * 9
                local y = cy - 8 + row * 9
                imgui.DrawList_AddRect(
                    draw, x, y, x + 6, y + 6, color, 1, 0, 1.3)
            end
        end
    elseif kind == "vendors" then
        imgui.DrawList_AddLine(draw, cx - 8, cy + 7, cx + 8, cy + 7, color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 7, cy + 7, cx - 7, cy - 5, color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 7, cy - 5, cx, cy - 9, color, 1.4)
        imgui.DrawList_AddLine(draw, cx, cy - 9, cx + 7, cy - 5, color, 1.4)
        imgui.DrawList_AddLine(draw, cx + 7, cy - 5, cx + 7, cy + 7, color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 2, cy - 3, cx - 2, cy + 7, color, 1.2)
        imgui.DrawList_AddLine(draw, cx + 3, cy - 3, cx + 3, cy + 7, color, 1.2)
    elseif kind == "all_plugins" or kind == "action_event_list" then
        for row = -1, 1 do
            local y = cy + row * 6
            imgui.DrawList_AddCircleFilled(draw, cx - 7, y, 1.5, color)
            imgui.DrawList_AddLine(draw, cx - 3, y, cx + 8, y, color, 1.4)
        end
    elseif kind == "action_all" then
        -- Compact clapperboard: striped hinged slate over a solid action body.
        imgui.DrawList_AddRect(draw, cx - 8, cy - 3, cx + 8, cy + 8,
            color, 1, 0, 1.4)
        imgui.DrawList_AddRect(draw, cx - 8, cy - 8, cx + 8, cy - 3,
            color, 1, 0, 1.4)
        for x = -6, 6, 6 do
            imgui.DrawList_AddLine(draw,
                cx + x - 2, cy - 8, cx + x + 1, cy - 3, color, 1.1)
        end
    elseif kind == "action_main" then
        imgui.DrawList_AddLine(draw, cx - 8, cy + 5, cx + 8, cy + 5,
            color, 1.4)
        for x = -7, 7, 7 do
            imgui.DrawList_AddLine(draw, cx + x, cy + 2, cx + x, cy + 8,
                color, 1.2)
        end
        imgui.DrawList_AddTriangleFilled(draw,
            cx - 3, cy - 7, cx - 3, cy + 1, cx + 5, cy - 3, color)
    elseif kind == "type_all" then
        -- Plug body, two prongs, and cable. This represents the complete
        -- installed plug-in inventory without implying a specific FX type.
        imgui.DrawList_AddRect(draw, cx - 6, cy - 2, cx + 6, cy + 5,
            color, 2, 0, 1.4)
        imgui.DrawList_AddLine(draw, cx - 3, cy - 8, cx - 3, cy - 2,
            color, 1.5)
        imgui.DrawList_AddLine(draw, cx + 3, cy - 8, cx + 3, cy - 2,
            color, 1.5)
        imgui.DrawList_AddLine(draw, cx, cy + 5, cx, cy + 9,
            color, 1.5)
    elseif kind == "instrument" or kind == "action_midi" then
        imgui.DrawList_AddRect(draw, cx - 9, cy - 7, cx + 9, cy + 7,
            color, 1, 0, 1.3)
        for offset = -5, 5, 5 do
            imgui.DrawList_AddLine(
                draw, cx + offset, cy - 7, cx + offset, cy + 7,
                color, 1)
        end
        for _, offset in ipairs({-3, 2}) do
            imgui.DrawList_AddRectFilled(
                draw, cx + offset, cy - 7, cx + offset + 2, cy,
                color, 0)
        end
    elseif kind == "effect" then
        -- Use the same three-channel mixer language for both audio and MIDI FX.
        for offset = -6, 6, 6 do
            imgui.DrawList_AddLine(
                draw, cx + offset, cy - 8, cx + offset, cy + 8,
                color, 1.2)
        end
        imgui.DrawList_AddCircleFilled(draw, cx - 6, cy - 3, 2.4, color)
        imgui.DrawList_AddCircleFilled(draw, cx, cy + 4, 2.4, color)
        imgui.DrawList_AddCircleFilled(draw, cx + 6, cy - 1, 2.4, color)
    elseif kind == "sort" then
        imgui.DrawList_AddLine(draw, cx - 8, cy - 6, cx + 4, cy - 6, color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 8, cy, cx + 1, cy, color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 8, cy + 6, cx - 2, cy + 6, color, 1.4)
        imgui.DrawList_AddLine(draw, cx + 7, cy - 7, cx + 7, cy + 6, color, 1.4)
        imgui.DrawList_AddTriangleFilled(
            draw, cx + 3, cy + 3, cx + 11, cy + 3, cx + 7, cy + 8, color)
    elseif kind == "add_track" then
        imgui.DrawList_AddLine(draw, cx - 9, cy + 5, cx + 9, cy + 5, color, 1.5)
        imgui.DrawList_AddLine(draw, cx - 9, cy, cx + 2, cy, color, 1.5)
        imgui.DrawList_AddCircleFilled(draw, cx - 6, cy - 5, 1.8, color)
        imgui.DrawList_AddLine(draw, cx + 5, cy - 7, cx + 5, cy + 1, color, 1.6)
        imgui.DrawList_AddLine(draw, cx + 1, cy - 3, cx + 9, cy - 3, color, 1.6)
    elseif kind == "add_input" then
        -- Track rails plus an arrow entering the record/input side.
        imgui.DrawList_AddLine(draw, cx - 2, cy - 7, cx + 9, cy - 7,
            color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 2, cy, cx + 9, cy,
            color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 2, cy + 7, cx + 9, cy + 7,
            color, 1.4)
        imgui.DrawList_AddLine(draw, cx - 9, cy, cx + 3, cy,
            color, 1.6)
        imgui.DrawList_AddTriangleFilled(
            draw, cx + 3, cy - 4, cx + 3, cy + 4, cx + 8, cy, color)
    end
    if hovered and tooltip then imgui.SetTooltip(ctx, tooltip) end
    return clicked
end

function DrawFXSortCombo()
    local fx = state.fx_browser
    local labels = {
        name_az = "Name A-Z",
        name_za = "Name Z-A",
        maker = "Maker",
        format = "Format",
        type = "Type",
    }
    if DrawFXToolbarIcon(
        "sort", fx.sort_mode ~= "name_az",
        "Sort: " .. (labels[fx.sort_mode] or "Name A-Z")) then
        imgui.OpenPopup(ctx, "##fx_sort_popup")
    end
    if imgui.BeginPopup(ctx, "##fx_sort_popup") then
        local order = {"name_az", "name_za", "maker", "format", "type"}
        for _, value in ipairs(order) do
            local prefix = fx.sort_mode == value and "\xe2\x9c\x93 " or ""
            if imgui.MenuItem(ctx, prefix .. labels[value]) then
                fx.sort_mode = value
                SaveFXBrowserPreferences()
            end
        end
        imgui.EndPopup(ctx)
    end
end

function DrawFXFormatChecks()
    local fx = state.fx_browser
    if fx.format_cache_generation ~= fx.generation then
        local present = {}
        for _, item in ipairs(fx.items) do
            if item.format ~= "" then present[item.format] = true end
        end
        local formats = {}
        for format in pairs(present) do formats[#formats + 1] = format end
        local priority = {VST3 = 1, VST = 2}
        table.sort(formats, function(a, b)
            local ap, bp = priority[a] or 100, priority[b] or 100
            if ap ~= bp then return ap < bp end
            return a < b
        end)
        fx.available_formats = formats
        fx.format_cache_generation = fx.generation
    end
    local formats = fx.available_formats

    imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 2, 1)
    for index, format in ipairs(formats) do
        local changed, enabled = imgui.Checkbox(
            ctx, format .. "##fx_format_" .. format,
            fx.format_enabled[format] == true)
        if changed then
            fx.format_enabled[format] = enabled
            SaveFXBrowserPreferences()
        end
        if index < #formats then
            local remaining_w = select(1, imgui.GetContentRegionAvail(ctx))
            local next_w = imgui.CalcTextSize(ctx, formats[index + 1]) + 34
            if remaining_w > next_w then imgui.SameLine(ctx) end
        end
    end
    imgui.PopStyleVar(ctx)
end

function SetOnlyFXSelected(item, row_key)
    local fx = state.fx_browser
    fx.selected_idents = {}
    fx.selected_row_keys = {}
    if item then
        fx.selected_idents[item.ident] = true
        fx.selected_row_keys[item.ident] = row_key
        fx.selected_ident = item.ident
        fx.selected_name = item.name
        fx.selection_anchor_ident = item.ident
        fx.selected_row_key = row_key
        fx.keyboard_cursor_kind = "item"
    else
        fx.selected_ident = nil
        fx.selected_name = nil
        fx.selection_anchor_ident = nil
        fx.selected_row_key = nil
    end
end

function ToggleFXSelected(item, row_key)
    local fx = state.fx_browser
    fx.selected_idents = fx.selected_idents or {}
    fx.selected_row_keys = fx.selected_row_keys or {}

    -- Discard legacy/range selections that have no owning row. Keeping those
    -- identities would make them appear in every repeated occurrence,
    -- including Browse Plug-ins, and could put unrelated items in a drag.
    for selected_ident in pairs(fx.selected_idents) do
        if not fx.selected_row_keys[selected_ident] then
            fx.selected_idents[selected_ident] = nil
        end
    end

    local ident = item and item.ident
    if not ident then return end

    -- Selection is identity-based for the drag payload, but the row key keeps
    -- the highlight local to the exact occurrence that was clicked. This is
    -- important because a favorite plug-in can appear in several folders and
    -- also in Browse Plug-ins at the same time.
    if fx.selected_idents[ident]
        and fx.selected_row_keys[ident] == row_key then
        fx.selected_idents[ident] = nil
        fx.selected_row_keys[ident] = nil
    else
        fx.selected_idents[ident] = true
        fx.selected_row_keys[ident] = row_key
    end

    fx.selection_anchor_ident = ident
    fx.selected_ident = nil
    fx.selected_name = nil
    for selected_ident in pairs(fx.selected_idents) do
        fx.selected_ident = selected_ident
        break
    end
    if fx.selected_ident then
        for _, candidate in ipairs(fx.items or {}) do
            if candidate.ident == fx.selected_ident then
                fx.selected_name = candidate.name
                break
            end
        end
    end
    fx.selected_row_key = row_key
    fx.keyboard_cursor_kind = "item"
end

function GetSelectedFXItems(fallback_item)
    local fx = state.fx_browser
    local selected = fx.selected_idents or {}
    local result, seen = {}, {}
    -- Preserve the currently visible filter/sort order first. Favorites rows
    -- or hidden selections are appended in stable discovery order.
    for _, item in ipairs(fx.filtered_items or {}) do
        if selected[item.ident] and not seen[item.ident] then
            result[#result + 1] = item
            seen[item.ident] = true
        end
    end
    for _, item in ipairs(fx.items or {}) do
        if selected[item.ident] and not seen[item.ident] then
            result[#result + 1] = item
            seen[item.ident] = true
        end
    end
    if #result == 0 and fallback_item then result[1] = fallback_item end
    return result
end

function SelectFXItem(item, selection_order, row_key,
    ctrl_override, shift_override, row_key_map)
    local fx = state.fx_browser
    local ctrl, shift = GetSelectionModifiers()
    if ctrl_override ~= nil then ctrl = ctrl_override end
    if shift_override ~= nil then shift = shift_override end
    fx.selected_idents = fx.selected_idents or {}
    fx.selected_row_keys = fx.selected_row_keys or {}
    if shift and fx.selection_anchor_ident then
        local first, last = nil, nil
        selection_order = selection_order or fx.filtered_items or {}
        for index, candidate in ipairs(selection_order) do
            if candidate.ident == fx.selection_anchor_ident then first = index end
            if candidate.ident == item.ident then last = index end
        end
        if first and last then
            if not ctrl then
                fx.selected_idents = {}
                fx.selected_row_keys = {}
            end
            if first > last then first, last = last, first end
            for index = first, last do
                local candidate = selection_order[index]
                fx.selected_idents[candidate.ident] = true
                fx.selected_row_keys[candidate.ident] = row_key_map
                    and row_key_map[candidate.ident] or nil
            end
            fx.selected_row_keys[item.ident] = row_key
        else
            SetOnlyFXSelected(item, row_key)
            return
        end
    elseif ctrl then
        if fx.selected_idents[item.ident] then
            fx.selected_idents[item.ident] = nil
            fx.selected_row_keys[item.ident] = nil
        else
            fx.selected_idents[item.ident] = true
            fx.selected_row_keys[item.ident] = row_key
        end
        fx.selection_anchor_ident = item.ident
    else
        SetOnlyFXSelected(item, row_key)
        return
    end

    fx.selected_ident = fx.selected_idents[item.ident] and item.ident or nil
    fx.selected_name = fx.selected_ident and item.name or nil
    if not fx.selected_ident then
        local remaining = GetSelectedFXItems()
        if remaining[1] then
            fx.selected_ident = remaining[1].ident
            fx.selected_name = remaining[1].name
        end
    end
    fx.keyboard_cursor_kind = "item"
    fx.selected_row_key = row_key
end

function EnsureFXContextSelection(item, row_key)
    local fx = state.fx_browser
    fx.selected_idents = fx.selected_idents or {}
    fx.selected_row_keys = fx.selected_row_keys or {}
    if not fx.selected_idents[item.ident] then
        SetOnlyFXSelected(item, row_key)
    else
        fx.selected_ident = item.ident
        fx.selected_name = item.name
        fx.selected_row_key = row_key
        fx.selected_row_keys[item.ident] = row_key
        fx.keyboard_cursor_kind = "item"
    end
end

function SetFXFavoritesFolder(items, folder)
    if not items or #items == 0 then return end
    local fx = state.fx_browser
    for _, item in ipairs(items) do
        fx.favorites[item.ident] = true
        fx.favorite_memberships[item.ident] =
            fx.favorite_memberships[item.ident] or {}
        fx.favorite_memberships[item.ident][folder and folder ~= ""
            and folder or RB_FAVORITES_ROOT_MEMBERSHIP] = true
    end
    SaveFXFavorites()
    fx.status = #items == 1 and "Updated plug-in favorite."
        or ("Updated " .. tostring(#items) .. " plug-in favorites.")
end

function ToggleFXFavoriteMembership(items, folder)
    if not items or #items == 0 or not folder or folder == "" then return end
    local fx = state.fx_browser
    local all_have = true
    for _, item in ipairs(items) do
        if not (fx.favorite_memberships[item.ident]
            and fx.favorite_memberships[item.ident][folder]) then
            all_have = false
            break
        end
    end
    for _, item in ipairs(items) do
        fx.favorite_memberships[item.ident] =
            fx.favorite_memberships[item.ident] or {}
        if all_have then
            fx.favorite_memberships[item.ident][folder] = nil
        else
            fx.favorites[item.ident] = true
            fx.favorite_memberships[item.ident][folder] = true
        end
    end
    SaveFXFavorites()
    fx.status = all_have and "Removed from FX Favorites folder."
        or "Added to FX Favorites folder."
end

function RemoveFXFavorites(items)
    if not items or #items == 0 then return end
    local fx = state.fx_browser
    for _, item in ipairs(items) do
        fx.favorites[item.ident] = nil
        fx.favorite_memberships[item.ident] = nil
    end
    SaveFXFavorites()
    fx.status = #items == 1 and "Removed plug-in favorite."
        or ("Removed " .. tostring(#items) .. " plug-in favorites.")
end

function RemoveFXFavoriteMembership(items, folder)
    if not items or #items == 0 or not folder then return end
    local fx = state.fx_browser
    local membership_key = folder ~= ""
        and folder or RB_FAVORITES_ROOT_MEMBERSHIP
    for _, item in ipairs(items) do
        local memberships = fx.favorite_memberships[item.ident]
        if memberships and memberships[membership_key] then
            memberships[membership_key] = nil
            if next(memberships) == nil then
                fx.favorite_memberships[item.ident] = nil
                fx.favorites[item.ident] = nil
            end
        end
    end
    SaveFXFavorites()
    fx.status = #items == 1 and "Removed from Favorites folder."
        or ("Removed " .. tostring(#items) .. " plug-ins from Favorites folder.")
end

function ApplyFXFavoriteDrop(items, source_folder, target_folder, copy_drop)
    local fx = state.fx_browser
    target_folder = target_folder or ""
    local target_key = target_folder ~= ""
        and target_folder or RB_FAVORITES_ROOT_MEMBERSHIP
    local source_key = source_folder ~= nil and (source_folder ~= ""
        and source_folder or RB_FAVORITES_ROOT_MEMBERSHIP) or nil
    for _, item in ipairs(items or {}) do
        local memberships = fx.favorite_memberships[item.ident] or {}
        fx.favorites[item.ident] = true
        memberships[target_key] = true
        if not copy_drop and source_key and source_key ~= target_key then
            memberships[source_key] = nil
        end
        fx.favorite_memberships[item.ident] = memberships
    end
    -- A move previously serialized every FX favorite twice: once for the
    -- destination and again for the source removal. Commit the final state.
    SaveFXFavorites()
end

function DrawFXItemRow(
    item, unique_id, selection_order, row_folder, grouped_view, row_key_map)
    local fx = state.fx_browser
    -- The drag payload is identity-based, but the visual selection is tied to
    -- the exact row occurrence that was clicked. The same plug-in can appear
    -- in several Favorites folders and in Browse Plug-ins; only the clicked
    -- occurrence should light up.
    local selected = fx.selected_idents[item.ident] == true
        and (not fx.selected_row_keys[item.ident]
            or fx.selected_row_keys[item.ident] == unique_id)
    local display_name = item.name:gsub("^[^:]+:%s*", "")
    local format_label = tostring(item.format or ""):upper()
    if format_label == "" then format_label = "OTHER" end
    local display_label = "[" .. format_label .. "]  " .. display_name
    local is_favorite = fx.favorites[item.ident] ~= nil
    -- FX rows use the exact media-row primitive and gutter geometry. The
    -- SpanAllWidth leaf keeps selection/hover color across the full row while
    -- the shared preparation step reserves only the heart control column.
    local flags = imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
    if selected then flags = flags | imgui.TreeNodeFlags_Selected end
    if selected then
        imgui.PushStyleColor(ctx, imgui.Col_Text, GetSelectedTextColor())
    end
    local heart_prepared_hot, heart_hover_style, heart_indent =
        PrepareFavoriteGutter(true, 0)
    local opened = imgui.TreeNode(
        ctx, display_label .. "##fx_" .. unique_id, flags)
    if heart_hover_style then imgui.PopStyleColor(ctx) end
    if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local _, max_y = imgui.GetItemRectMax(ctx)
    local hovered = imgui.IsItemHovered(ctx)
    if selected then imgui.PopStyleColor(ctx) end
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    local gutter = GetFavoriteRowGutter(true)
    local heart_x = gutter.heart_x
    local heart_hovered = heart_prepared_hot or (
        mouse_x >= heart_x - 2 and mouse_x <= heart_x + gutter.hit_width
        and mouse_y >= min_y and mouse_y <= max_y
    )
    local glyph_color, glyph = GetFavoriteHeartAppearance(
        is_favorite, selected, hovered, false)
    imgui.DrawList_AddText(
        imgui.GetWindowDrawList(ctx), heart_x, min_y, glyph_color, glyph)
    local heart_clicked = heart_hovered and imgui.IsMouseClicked(ctx, 0)
    -- Use the same interaction snapshot as Media Favorites. In particular,
    -- keep the row active after the click so a TreeNode cannot swallow the
    -- transition into a drag on the next frame.
    local interaction = CaptureBrowserRowInteraction()
    if heart_clicked then
        local target_items = selected
            and GetSelectedFXItems(item) or {item}
        if row_folder ~= nil then
            local membership_key = row_folder ~= ""
                and row_folder or RB_FAVORITES_ROOT_MEMBERSHIP
            local has_membership = fx.favorite_memberships[item.ident]
                and fx.favorite_memberships[item.ident][membership_key]
            if has_membership then
                RemoveFXFavoriteMembership(target_items, row_folder)
            else
                SetFXFavoritesFolder(target_items, row_folder)
            end
        elseif is_favorite then
            RemoveFXFavorites(target_items)
        else
            SetFXFavoritesFolder(target_items, "")
        end
    elseif interaction.clicked then
        -- Ctrl serves two roles here: it toggles this row in the selection and
        -- remains latched as the copy modifier if the gesture becomes a drag.
        -- Read it from the same ImGui snapshot used by the working media
        -- browser; do not mix in a separate global mouse-state bitmask.
        local click_ctrl = interaction.ctrl == true
        fx.drag_pending_item = item
        fx.drag_pending_row_key = unique_id
        fx.drag_pending_ctrl = click_ctrl
        fx.drag_ctrl_at_click = click_ctrl == true
        if click_ctrl then
            -- Defer the toggle until mouse-up. If this gesture crosses the
            -- drag threshold, the existing selection must remain intact so a
            -- Ctrl-drag can copy several selected plug-ins.
            fx.pending_ctrl_click = {
                item = item, row_key = unique_id, toggle = true}
        elseif selected and #GetSelectedFXItems(item) > 1
            and not interaction.shift then
            -- Keep a multi-selection intact until we know whether this is a
            -- click or a drag. Mouse-up collapses to this row; dragging carries
            -- every selected plug-in.
            fx.pending_ctrl_click = {
                item = item, row_key = unique_id, collapse = true}
        else
            fx.pending_ctrl_click = nil
            local _, click_shift = GetSelectionModifiers()
            SelectFXItem(
                item, selection_order, unique_id, false, click_shift,
                row_key_map)
        end
    end
    if fx.keyboard_scroll_ident == item.ident then
        imgui.SetScrollHereY(ctx, 0.5)
        fx.keyboard_scroll_ident = nil
    end
    if not heart_hovered and interaction.double_clicked then
        SetOnlyFXSelected(item, unique_id)
        AddFXToSelectedTrack(item)
    end
    -- Mirror the media browser's pending-row drag detection. The item can stop
    -- reporting as active after the click, even though the mouse is still
    -- dragging from it.
    if (interaction.active
        or (fx.drag_pending_item == item
            and fx.drag_pending_row_key == unique_id))
        and imgui.IsMouseDragging(ctx, 0) then
        if not fx.drag_active then
            fx.pending_ctrl_click = nil
            if not fx.selected_idents[item.ident] then
                SetOnlyFXSelected(item, unique_id)
            end
            fx.drag_active = true
            fx.drag_item = item
            fx.drag_items = GetSelectedFXItems(item)
            fx.drag_source_folder = row_folder
            fx.drag_ctrl_at_click = fx.drag_pending_ctrl
            fx.drag_copy_favorite = fx.drag_pending_ctrl
                or select(1, GetSelectionModifiers())
            fx.drag_pending_item = nil
            fx.drag_pending_row_key = nil
            fx.drag_pending_ctrl = false
            -- Keep file auditioning active while dragging/adding plug-ins.
        end
    end
    if imgui.BeginPopupContextItem(ctx, "##fx_context_" .. unique_id) then
        imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 7, 5)
        EnsureFXContextSelection(item, unique_id)
        local selected_items = GetSelectedFXItems(item)
        local plural = #selected_items > 1
        if imgui.MenuItem(ctx, plural and "Add selected plug-ins to track"
            or "Add to selected track") then
            AddFXItemsToTrack(
                selected_items, r.GetSelectedTrack(0, 0), false)
        end
        if imgui.MenuItem(ctx, plural and "Add selected plug-ins as input FX"
            or "Add as input FX") then
            AddFXItemsToTrack(
                selected_items, r.GetSelectedTrack(0, 0), true)
        end
        if imgui.MenuItem(ctx, plural and "Create track with selected plug-ins"
            or "Create new track with plug-in") then
            CreateTrackWithFXItems(selected_items, false)
        end
        imgui.Separator(ctx)
        if imgui.MenuItem(ctx, plural and "Add Selected to Favorites"
            or "Add to Favorites") then
            SetFXFavoritesFolder(selected_items, "")
        end
        local any_favorite = false
        for _, selected_item in ipairs(selected_items) do
            if fx.favorites[selected_item.ident] ~= nil then
                any_favorite = true
                break
            end
        end
        if any_favorite and imgui.MenuItem(ctx,
            row_folder and "Remove from this Favorites folder"
                or (plural and "Remove Selected from Favorites"
                    or "Remove from Favorites")) then
            if row_folder then
                RemoveFXFavoriteMembership(selected_items, row_folder)
            else
                RemoveFXFavorites(selected_items)
            end
        end
        local folder_paths = {}
        for path in pairs(fx.favorite_folders) do
            folder_paths[#folder_paths + 1] = path
        end
        table.sort(folder_paths)
        local folder_menu = plural and "Add Selected to Favorite Folder"
            or "Add to Favorite Folder"
        if #folder_paths > 0 and imgui.BeginMenu(ctx, folder_menu) then
            for _, path in ipairs(folder_paths) do
                local all_have = true
                for _, selected_item in ipairs(selected_items) do
                    if not (fx.favorite_memberships[selected_item.ident]
                        and fx.favorite_memberships[selected_item.ident][path]) then
                        all_have = false
                        break
                    end
                end
                if imgui.MenuItem(ctx, (all_have and "✓ " or "") .. path) then
                    ToggleFXFavoriteMembership(selected_items, path)
                end
            end
            imgui.EndMenu(ctx)
        end
        imgui.Separator(ctx)
        if imgui.MenuItem(ctx, "Copy plug-in name") then
            imgui.SetClipboardText(ctx, item.name)
        end
        imgui.PopStyleVar(ctx)
        imgui.EndPopup(ctx)
    end
    if opened then imgui.TreePop(ctx) end
end

function InferInstrumentFamily(item)
    local haystack = ((item.category or "") .. " " .. (item.name or "")):lower()
    local tests = {
        {"Drums & Percussion", {"drum", "percussion", "808", "rhythm", "beat"}},
        {"Samplers", {"sampler", "sample player", "rompler", "kontakt"}},
        {"Pianos & Keys", {"piano", "keys", "keyboard", "electric piano", "clav"}},
        {"Organs", {"organ"}},
        {"Guitars", {"guitar"}},
        {"Bass Instruments", {"bass"}},
        {"Strings", {"string", "violin", "viola", "cello", "harp"}},
        {"Brass & Winds", {"brass", "horn", "trumpet", "sax", "flute", "woodwind"}},
        {"Orchestral", {"orchestra", "orchestral", "choir", "cinematic"}},
        {"Synthesizers", {"synth", "generator", "analog", "wavetable", "fm synth"}},
    }
    for _, test in ipairs(tests) do
        for _, token in ipairs(test[2]) do
            if haystack:find(token, 1, true) then return test[1] end
        end
    end
    return "Other Instruments"
end

function RefineEffectCategory(raw, item)
    local value = (raw or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    local haystack = value .. " " .. (item.name or ""):lower()
    local tests = {
        {"EQ", {"equalizer", " eq", "eq ", "eq-", "eq/"}},
        {"Dynamics", {"dynamics", "compressor", "limiter", "gate", "expander", "de-esser"}},
        {"Reverb", {"reverb"}},
        {"Delay", {"delay", "echo"}},
        {"Distortion & Saturation", {"distortion", "saturation", "overdrive", "amp sim", "exciter"}},
        {"Modulation", {"modulation", "chorus", "flanger", "phaser", "tremolo", "vibrato"}},
        {"Filter", {"filter"}},
        {"Pitch & Time", {"pitch", "tuner", "time stretch", "time-stretch"}},
        {"Stereo & Imaging", {"stereo", "imaging", "spatial", "surround", "panner"}},
        {"Metering & Analysis", {"analyzer", "analysis", "meter", "scope", "loudness"}},
        {"Channel Strips", {"channel strip", "channelstrip"}},
        {"Mastering", {"mastering"}},
        {"MIDI Tools", {"midi"}},
        {"Utilities", {"utility", "tools", "external"}},
    }
    for _, test in ipairs(tests) do
        for _, token in ipairs(test[2]) do
            if haystack:find(token, 1, true) then return test[1] end
        end
    end
    local title = value:gsub("^%l", string.upper)
    if title == "Effect" or title == "Effects" or title == "" then
        return "Other Effects"
    end
    if title == "Eq" then return "EQ" end
    if title == "Drum" or title == "Drums" then return "Drum Processing" end
    return title
end

function BuildFXGroups(items, mode)
    local by_name = {}
    for _, item in ipairs(items) do
        local group_names = {}
        if mode == "vendor" then
            group_names[1] = item.maker ~= "" and item.maker or "Unknown Vendor"
        elseif item.kind == "instrument" then
            group_names[1] = InferInstrumentFamily(item)
        else
            for category in (item.category or "Uncategorized"):gmatch("[^|]+") do
                category = category:match("^%s*(.-)%s*$")
                if category ~= "" then
                    local refined = RefineEffectCategory(category, item)
                    local duplicate = false
                    for _, existing in ipairs(group_names) do
                        if existing == refined then duplicate = true break end
                    end
                    if not duplicate then group_names[#group_names + 1] = refined end
                end
            end
            if #group_names == 0 then group_names[1] = "Other Effects" end
        end
        for _, group_name in ipairs(group_names) do
            if not by_name[group_name] then by_name[group_name] = {} end
            by_name[group_name][#by_name[group_name] + 1] = item
        end
    end

    local groups = {}
    for name, group_items in pairs(by_name) do
        groups[#groups + 1] = {name = name, items = group_items}
    end
    table.sort(groups, function(a, b)
        local a_other = a.name == "Unknown Vendor"
            or a.name == "Uncategorized"
            or a.name == "Other Instruments"
            or a.name == "Other Effects"
        local b_other = b.name == "Unknown Vendor"
            or b.name == "Uncategorized"
            or b.name == "Other Instruments"
            or b.name == "Other Effects"
        if a_other and not b_other then
            return false
        elseif b_other and not a_other then
            return true
        end
        return a.name:lower() < b.name:lower()
    end)
    return groups
end

function GetCachedFXGroups(mode)
    local fx = state.fx_browser
    if not fx.group_cache[mode] then
        fx.group_cache[mode] = BuildFXGroups(fx.filtered_items, mode)
    end
    return fx.group_cache[mode]
end

function OpenFXFolderDialog(mode, parent, target)
    local dialog = state.fx_browser.folder_dialog
    dialog.mode = mode
    dialog.parent = parent or ""
    dialog.target = target or ""
    dialog.value = target and target:match("([^/\\]+)$") or ""
    dialog.open = true
end

function FavoritePathParent(path)
    return path:match("^(.*)/[^/]+$") or ""
end

function RenameFavoriteFolder(old_path, new_name)
    local fx = state.fx_browser
    local parent = FavoritePathParent(old_path)
    local new_path = parent ~= "" and (parent .. "/" .. new_name) or new_name
    if new_path == old_path or fx.favorite_folders[new_path] then return false end
    local replacements = {}
    for path in pairs(fx.favorite_folders) do
        if path == old_path or path:sub(1, #old_path + 1) == old_path .. "/" then
            replacements[path] = new_path .. path:sub(#old_path + 1)
        end
    end
    for old, new in pairs(replacements) do
        fx.favorite_folders[old] = nil
        fx.favorite_folders[new] = true
    end
    for ident, memberships in pairs(fx.favorite_memberships) do
        local replacements_for_item = {}
        for folder in pairs(memberships) do
            if folder == old_path
                or folder:sub(1, #old_path + 1) == old_path .. "/" then
                replacements_for_item[folder] =
                    new_path .. folder:sub(#old_path + 1)
            end
        end
        for old, new in pairs(replacements_for_item) do
            memberships[old] = nil
            memberships[new] = true
        end
    end
    SaveFXFavorites()
    return true
end

function MoveFXFavoriteFolder(old_path, target_parent)
    local fx = state.fx_browser
    target_parent = target_parent or ""
    if target_parent == old_path
        or target_parent:sub(1, #old_path + 1) == old_path .. "/" then
        return false
    end
    local name = old_path:match("([^/]+)$") or old_path
    local new_path = target_parent ~= ""
        and (target_parent .. "/" .. name) or name
    if new_path == old_path or fx.favorite_folders[new_path] then return false end
    local replacements = {}
    for path in pairs(fx.favorite_folders) do
        if path == old_path or path:sub(1, #old_path + 1) == old_path .. "/" then
            replacements[path] = new_path .. path:sub(#old_path + 1)
        end
    end
    for old in pairs(replacements) do fx.favorite_folders[old] = nil end
    for _, replacement in pairs(replacements) do
        fx.favorite_folders[replacement] = true
    end
    for _, memberships in pairs(fx.favorite_memberships) do
        local moved = {}
        for old, replacement in pairs(replacements) do
            if memberships[old] then moved[replacement] = true end
            memberships[old] = nil
        end
        for replacement in pairs(moved) do memberships[replacement] = true end
    end
    SaveFXFavorites()
    fx.status = "Moved Favorites folder."
    return true
end

function DeleteFavoriteFolder(path)
    local fx = state.fx_browser
    for folder in pairs(fx.favorite_folders) do
        if folder == path or folder:sub(1, #path + 1) == path .. "/" then
            fx.favorite_folders[folder] = nil
        end
    end
    for ident, memberships in pairs(fx.favorite_memberships) do
        for folder in pairs(memberships) do
            if folder == path
                or folder:sub(1, #path + 1) == path .. "/" then
                memberships[folder] = nil
            end
        end
    end
    SaveFXFavorites()
end

function IsMouseInsideLastItem()
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local max_x, max_y = imgui.GetItemRectMax(ctx)
    return mouse_x >= min_x and mouse_x <= max_x
        and mouse_y >= min_y and mouse_y <= max_y
end

function GetFXRowKeyMap(cache_key, items, prefix, use_ident)
    local fx = state.fx_browser
    local cached = fx.row_key_cache[cache_key]
    if cached and cached.items == items and cached.count == #items then
        return cached.map
    end
    local map = {}
    for index, item in ipairs(items) do
        map[item.ident] = prefix
            .. (use_ident and item.ident or tostring(index))
    end
    fx.row_key_cache[cache_key] = {
        items = items, count = #items, map = map}
    return map
end

function GetFXFavoriteViewCache()
    local fx = state.fx_browser
    local signature = tostring(fx.generation or 0) .. ":"
        .. tostring(fx.favorite_generation or 0)
    if fx.favorite_view_cache
        and fx.favorite_view_cache_signature == signature then
        return fx.favorite_view_cache
    end
    local cache = {children = {[''] = {}}, items = {}, root_items = {}}
    for path in pairs(fx.favorite_folders) do
        cache.items[path] = {}
        local parent = FavoritePathParent(path)
        cache.children[parent] = cache.children[parent] or {}
        cache.children[parent][#cache.children[parent] + 1] = path
        cache.children[path] = cache.children[path] or {}
    end
    for _, children in pairs(cache.children) do table.sort(children) end
    for _, item in ipairs(fx.items) do
        if fx.favorites[item.ident] == true then
            local memberships = fx.favorite_memberships[item.ident] or {}
            if next(memberships) == nil then
                memberships[RB_FAVORITES_ROOT_MEMBERSHIP] = true
                fx.favorite_memberships[item.ident] = memberships
            end
            if memberships[RB_FAVORITES_ROOT_MEMBERSHIP] then
                cache.root_items[#cache.root_items + 1] = item
            end
            for folder in pairs(memberships) do
                if folder ~= RB_FAVORITES_ROOT_MEMBERSHIP then
                    local folder_items = cache.items[folder]
                    if folder_items then
                        folder_items[#folder_items + 1] = item
                    end
                end
            end
        end
    end
    fx.favorite_view_cache = cache
    fx.favorite_view_cache_signature = signature
    return cache
end

function DrawFavoriteFXFolder(path, label, depth, cache)
    local fx = state.fx_browser
    local folder_style_count = PushBrowserFolderRowStyle(false)
    local open = imgui.TreeNode(
        ctx,
        label .. "##fx_fav_folder_" .. path,
        FLG_SPAN_WIDTH)
    PopBrowserFolderRowStyle(folder_style_count)
    if fx.drag_active and IsMouseInsideLastItem() then
        fx.favorite_drop_active = true
        fx.favorite_drop_target = path
    end
    if imgui.BeginPopupContextItem(ctx, "##fx_fav_folder_menu_" .. path) then
        if imgui.MenuItem(ctx, "Create New Subfolder...") then
            OpenFXFolderDialog("create_favorite", path, nil)
        end
        if imgui.MenuItem(ctx, "Rename Folder...") then
            OpenFXFolderDialog("rename_favorite", "", path)
        end
        local current_parent = FavoritePathParent(path)
        if current_parent ~= ""
            and imgui.MenuItem(ctx, "Move to Favorites Root") then
            MoveFXFavoriteFolder(path, "")
        end
        local move_targets = {}
        for candidate in pairs(fx.favorite_folders) do
            if candidate ~= path and candidate ~= current_parent
                and candidate:sub(1, #path + 1) ~= path .. "/" then
                move_targets[#move_targets + 1] = candidate
            end
        end
        table.sort(move_targets)
        if #move_targets > 0 and imgui.BeginMenu(ctx, "Move to Folder") then
            for _, target in ipairs(move_targets) do
                if imgui.MenuItem(ctx, target) then
                    MoveFXFavoriteFolder(path, target)
                end
            end
            imgui.EndMenu(ctx)
        end
        imgui.Separator(ctx)
        if imgui.MenuItem(ctx, "Delete Folder") then DeleteFavoriteFolder(path) end
        imgui.EndPopup(ctx)
    end
    if open then
        local child_paths = cache.children[path] or {}
        for _, child in ipairs(child_paths) do
            DrawFavoriteFXFolder(
                child, child:match("([^/]+)$") or child,
                (depth or 0) + 1, cache)
        end
        local folder_items = cache.items[path] or {}
        local folder_row_keys = GetFXRowKeyMap(
            "favorite:" .. path, folder_items,
            "favorite_" .. path .. "_", true)
        for _, item in ipairs(folder_items) do
            DrawFXItemRow(item,
                folder_row_keys[item.ident], folder_items, path, true,
                folder_row_keys)
        end
        imgui.TreePop(ctx)
    end
end

function ScanFXChainDirectory(path)
    local node = {path = path, folders = {}, files = {}}
    local index = 0
    while true do
        local name = r.EnumerateSubdirectories(path, index)
        if not name then break end
        node.folders[#node.folders + 1] =
            ScanFXChainDirectory(path .. "/" .. name)
        index = index + 1
    end
    index = 0
    while true do
        local name = r.EnumerateFiles(path, index)
        if not name then break end
        if name:lower():match("%.rfxchain$") then
            node.files[#node.files + 1] = {
                name = name:gsub("%.[Rr][Ff][Xx][Cc]hain$", ""),
                path = path .. "/" .. name,
            }
        end
        index = index + 1
    end
    table.sort(node.folders, function(a, b) return a.path:lower() < b.path:lower() end)
    table.sort(node.files, function(a, b) return a.name:lower() < b.name:lower() end)
    return node
end

function ScanTrackTemplateDirectory(path)
    local node = {path = path, folders = {}, files = {}}
    local index = 0
    while true do
        local name = r.EnumerateSubdirectories(path, index)
        if not name then break end
        node.folders[#node.folders + 1] =
            ScanTrackTemplateDirectory(path .. "/" .. name)
        index = index + 1
    end
    index = 0
    while true do
        local name = r.EnumerateFiles(path, index)
        if not name then break end
        if name:lower():match("%.rtracktemplate$") then
            node.files[#node.files + 1] = {
                name = name:gsub("%.[Rr][Tt][Rr][Aa][Cc][Kk][Tt][Ee][Mm][Pp][Ll][Aa][Tt][Ee]$", ""),
                path = path .. "/" .. name,
            }
        end
        index = index + 1
    end
    table.sort(node.folders, function(a, b)
        return a.path:lower() < b.path:lower()
    end)
    table.sort(node.files, function(a, b)
        return a.name:lower() < b.name:lower()
    end)
    return node
end

function FindTrackChunkBlockClosingLine(chunk, block_name)
    local block_start = chunk:find("<" .. block_name .. "[%s\r\n]")
    if not block_start then return nil end
    local depth, position = 0, block_start
    while position <= #chunk do
        local newline = chunk:find("\n", position, true)
        local line_end = newline and newline - 1 or #chunk
        local line = chunk:sub(position, line_end):gsub("\r$", "")
        if line:match("^%s*<") then
            depth = depth + 1
        elseif line:match("^%s*>%s*$") then
            depth = depth - 1
            if depth == 0 then return position end
        end
        if not newline then break end
        position = newline + 1
    end
    return nil
end

function BuildTrackChunkWithAppendedFXChain(track_chunk, chain_chunk)
    if not track_chunk or track_chunk == ""
        or not chain_chunk or chain_chunk == "" then return nil end
    chain_chunk = chain_chunk:gsub("^%s+", ""):gsub("%s+$", "")
    if chain_chunk == "" or not chain_chunk:find("^REQUIRED_CHANNELS%s+%d+")
        and not chain_chunk:find("^BYPASS%s+") then
        return nil
    end

    local fx_close = FindTrackChunkBlockClosingLine(track_chunk, "FXCHAIN")
    if fx_close then
        return track_chunk:sub(1, fx_close - 1)
            .. chain_chunk .. "\n" .. track_chunk:sub(fx_close)
    end

    local track_close_newline = track_chunk:match("()\n>%s*$")
    if not track_close_newline then return nil end
    local new_fx_chain = "<FXCHAIN\nSHOW 0\nLASTSEL 0\nDOCKED 0\n"
        .. chain_chunk .. "\n>\n"
    return track_chunk:sub(1, track_close_newline)
        .. new_fx_chain .. track_chunk:sub(track_close_newline + 1)
end

function AddFXChainToTrack(chain, track)
    track = track or r.GetSelectedTrack(0, 0)
    if not track then
        state.fx_browser.status = "Select a track, then add the FX Chain."
        return false
    end
    if not chain or not chain.path or chain.path == "" then
        state.fx_browser.status = "The FX Chain file is unavailable."
        return false
    end

    local file, open_error = io.open(chain.path, "rb")
    if not file then
        state.fx_browser.status = "Could not read FX Chain: "
            .. tostring(open_error or chain.name)
        return false
    end
    local chain_chunk = file:read("*a")
    file:close()

    local got_chunk, original_chunk = r.GetTrackStateChunk(track, "", false)
    if not got_chunk or not original_chunk or original_chunk == "" then
        state.fx_browser.status = "REAPER could not read the selected track."
        return false
    end
    local updated_chunk = BuildTrackChunkWithAppendedFXChain(
        original_chunk, chain_chunk)
    if not updated_chunk then
        state.fx_browser.status = "Invalid FX Chain file: " .. chain.name
        return false
    end

    local before = r.TrackFX_GetCount(track)
    r.Undo_BeginBlock()
    local applied = r.SetTrackStateChunk(track, updated_chunk, false)
    local after = applied and r.TrackFX_GetCount(track) or before
    if not applied or after <= before then
        if applied then r.SetTrackStateChunk(track, original_chunk, false) end
        r.Undo_EndBlock("Add FX Chain failed: " .. chain.name, -1)
        state.fx_browser.status = "REAPER could not add FX Chain: " .. chain.name
        return false
    end
    r.Undo_EndBlock("Add FX Chain: " .. chain.name, -1)
    r.TrackList_AdjustWindows(false)
    r.UpdateArrange()
    state.fx_browser.status = string.format("Added FX Chain: %s (%d FX)",
        chain.name, after - before)
    return true
end

function InsertTrackTemplate(template)
    if not template or not template.path or template.path == "" then
        return false
    end
    local before = r.CountTracks(0)
    r.Undo_BeginBlock()
    r.Main_openProject(template.path)
    r.Undo_EndBlock("Insert Track Template: " .. template.name, -1)
    local inserted = math.max(0, r.CountTracks(0) - before)
    state.fx_browser.status = inserted > 0
        and string.format(
            "Inserted Track Template: %s (%d track%s)",
            template.name, inserted, inserted == 1 and "" or "s")
        or ("REAPER did not insert Track Template: " .. template.name)
    return inserted > 0
end

function DrawFXChainNode(node, is_root)
    local label = is_root and "FX Chains"
        or (node.path:match("([^/\\]+)$") or node.path)
    local open = is_root or DrawBrowserFolderTreeNode(
        label .. "##fx_chain_folder_" .. node.path, FLG_SPAN_WIDTH, false)
    if open then
        for _, folder in ipairs(node.folders) do DrawFXChainNode(folder, false) end
        for index, chain in ipairs(node.files) do
            imgui.Selectable(
                ctx, chain.name .. "##fx_chain_" .. chain.path, false)
            if imgui.IsItemHovered(ctx)
                and imgui.IsMouseDoubleClicked(ctx, 0) then
                AddFXChainToTrack(chain)
            end
            if imgui.BeginPopupContextItem(
                ctx, "##fx_chain_item_menu_" .. tostring(index) .. chain.path) then
                if imgui.MenuItem(ctx, "Add to selected track") then
                    AddFXChainToTrack(chain)
                end
                imgui.EndPopup(ctx)
            end
        end
        if not is_root then imgui.TreePop(ctx) end
    end
end

function DrawTrackTemplateNode(node, is_root)
    local label = is_root and "Track Templates"
        or (node.path:match("([^/\\]+)$") or node.path)
    local open = is_root or DrawBrowserFolderTreeNode(
        label .. "##track_template_folder_" .. node.path,
        FLG_SPAN_WIDTH, false)
    if open then
        for _, folder in ipairs(node.folders) do
            DrawTrackTemplateNode(folder, false)
        end
        for index, template in ipairs(node.files) do
            imgui.Selectable(
                ctx, template.name .. "##track_template_" .. template.path,
                false)
            if imgui.IsItemHovered(ctx)
                and imgui.IsMouseDoubleClicked(ctx, 0) then
                InsertTrackTemplate(template)
            end
            if imgui.BeginPopupContextItem(
                ctx, "##track_template_item_menu_"
                    .. tostring(index) .. template.path) then
                if imgui.MenuItem(ctx, "Insert track template") then
                    InsertTrackTemplate(template)
                end
                imgui.EndPopup(ctx)
            end
        end
        if not is_root then imgui.TreePop(ctx) end
    end
end

function CollectPresetTreeMatches(node, query, results)
    if not node then return results end
    results = results or {}
    query = NormalizeBrowserSearchTokens(query)
    for _, folder in ipairs(node.folders or {}) do
        CollectPresetTreeMatches(folder, query, results)
    end
    for _, item in ipairs(node.files or {}) do
        local search_text = NormalizeBrowserSearchTokens(
            item.name .. " " .. item.path)
        if BrowserSearchTokensMatch(search_text, query) then
            results[#results + 1] = item
        end
    end
    return results
end

function DrawFXPresetSearchGroup(label, id, items, activate,
    require_double_click)
    if #items == 0 then return end
    local folder_color = state.resolved_theme
        and state.resolved_theme.folder_text
        or state.theme.colors.folder_text
    imgui.PushStyleColor(ctx, imgui.Col_Text, folder_color)
    imgui.Text(ctx, label)
    imgui.PopStyleColor(ctx)
    for index, item in ipairs(items) do
        local clicked = imgui.Selectable(
            ctx, item.name .. "##" .. id .. "_search_"
                .. tostring(index) .. "_" .. item.path, false)
        local activated = require_double_click
            and imgui.IsItemHovered(ctx)
            and imgui.IsMouseDoubleClicked(ctx, 0)
            or not require_double_click and clicked
        if activated then
            activate(item)
        end
    end
    imgui.Separator(ctx)
end

function GetFXUsageItems(mode)
    local fx = state.fx_browser
    local cache_key = mode .. ":" .. tostring(fx.usage_generation or 0)
    fx.smart_cache = fx.smart_cache or {}
    if fx.smart_cache[cache_key] then return fx.smart_cache[cache_key] end
    local rows = {}
    for _, item in ipairs(fx.items or {}) do
        local record = fx.usage[item.ident]
        if record and (record.count or 0) > 0 then
            rows[#rows + 1] = item
        end
    end
    table.sort(rows, function(a, b)
        local ar = fx.usage[a.ident] or {}
        local br = fx.usage[b.ident] or {}
        if mode == "recent" then
            if (ar.last_used or 0) ~= (br.last_used or 0) then
                return (ar.last_used or 0) > (br.last_used or 0)
            end
            if (ar.sequence or 0) ~= (br.sequence or 0) then
                return (ar.sequence or 0) > (br.sequence or 0)
            end
        else
            if (ar.count or 0) ~= (br.count or 0) then
                return (ar.count or 0) > (br.count or 0)
            end
            if (ar.last_used or 0) ~= (br.last_used or 0) then
                return (ar.last_used or 0) > (br.last_used or 0)
            end
        end
        return a.name_lower < b.name_lower
    end)
    fx.smart_cache = {[cache_key] = rows}
    return rows
end

function DrawFXUsageRoot(mode, label)
    local fx = state.fx_browser
    local items = GetFXUsageItems(mode)
    local open = DrawBrowserFolderTreeNode(
        label .. "##fx_usage_" .. mode, FLG_SPAN_WIDTH, false)
    if open then
        if #items == 0 then
            imgui.TextDisabled(ctx, "No plug-ins recorded yet.")
        else
            local row_keys = GetFXRowKeyMap(
                "usage:" .. mode, items, "usage_" .. mode .. "_", false)
            for _, item in ipairs(items) do
                DrawFXItemRow(item,
                    row_keys[item.ident], items, nil, true, row_keys)
            end
        end
        imgui.TreePop(ctx)
    end
end

-- Keep this large optional FX section out of the main chunk's local-variable
-- budget. Lua limits locals in the top-level chunk to 200; the function's
-- internal locals remain private to its own scope.
function DrawFXLibraryRoots()
    local fx = state.fx_browser

    imgui.Spacing(ctx)
    if DrawFavoritesLibraryHeader(
        "fx_add_folder", "Create Favorites folder") then
        OpenFXFolderDialog("create_favorite", "", nil)
    end
    imgui.Separator(ctx)
    local favorites_open = DrawBrowserFolderTreeNode(
        "♥  Favorites##fx_favorites_root", FLG_SPAN_WIDTH, false)
    if fx.drag_active and IsMouseInsideLastItem() then
        fx.favorite_drop_active = true
        fx.favorite_drop_target = ""
    end
    if imgui.BeginPopupContextItem(ctx, "##fx_favorites_root_menu") then
        if imgui.MenuItem(ctx, "New Favorites Folder...") then
            OpenFXFolderDialog("create_favorite", "", nil)
        end
        imgui.EndPopup(ctx)
    end
    if favorites_open then
        local favorite_cache = GetFXFavoriteViewCache()
        local roots = favorite_cache.children[""] or {}
        for _, path in ipairs(roots) do
            DrawFavoriteFXFolder(path, path, 0, favorite_cache)
        end
        local favorite_root_items = favorite_cache.root_items
        local favorite_root_row_keys = GetFXRowKeyMap(
            "favorite:root", favorite_root_items,
            "favorite_root_", true)
        for _, item in ipairs(favorite_root_items) do
            DrawFXItemRow(
                item, favorite_root_row_keys[item.ident],
                favorite_root_items, "", true, favorite_root_row_keys)
        end
        if #roots == 0 and #favorite_root_items == 0 then
            imgui.TextDisabled(ctx,
                "No favorites yet. Click a heart or drag a plug-in here.")
        end
        imgui.TreePop(ctx)
    end

    DrawFXUsageRoot("recent", "Recent")
    DrawFXUsageRoot("used", "Most Used")

    local chain_root = r.GetResourcePath() .. "/FXChains"
    if fx.initialization_stage >= 3 and not fx.preset_init_deferred then
        fx.preset_init_deferred = true
    elseif fx.preset_init_deferred and not fx.chain_tree then
        fx.chain_tree = ScanFXChainDirectory(chain_root)
    end
    local chains_open = DrawBrowserFolderTreeNode(
        "⛓  FX Chains##fx_chains_root", FLG_SPAN_WIDTH, false)
    if chains_open then
        if fx.chain_tree then
            DrawFXChainNode(fx.chain_tree, true)
        else
            imgui.TextDisabled(ctx, "Loading FX Chains...")
        end
        imgui.TreePop(ctx)
    end

    local template_root = r.GetResourcePath() .. "/TrackTemplates"
    if fx.chain_tree and not fx.track_template_tree
        and fx.template_init_deferred then
        fx.track_template_tree = ScanTrackTemplateDirectory(template_root)
    elseif fx.chain_tree and not fx.track_template_tree then
        fx.template_init_deferred = true
    end
    local templates_open = DrawBrowserFolderTreeNode(
        "\226\150\164  Track Templates##track_templates_root",
        FLG_SPAN_WIDTH, false)
    if templates_open then
        if fx.track_template_tree then
            DrawTrackTemplateNode(fx.track_template_tree, true)
        else
            imgui.TextDisabled(ctx, "Loading Track Templates...")
        end
        imgui.TreePop(ctx)
    end

    imgui.Separator(ctx)
    imgui.Spacing(ctx)
    local browse_selected = fx.keyboard_cursor_kind == "root"
    if imgui.Selectable(
        ctx, "BROWSE PLUG-INS##fx_browse_root", browse_selected) then
        SetOnlyFXSelected(nil)
        fx.keyboard_cursor_kind = "root"
        fx.keyboard_group = nil
    end
    imgui.Separator(ctx)
end

function DrawFXFolderDialog()
    local fx = state.fx_browser
    local dialog = fx.folder_dialog
    if dialog.open then
        imgui.OpenPopup(ctx, "FX Folder##browser_styled")
        dialog.open = false
    end
    if imgui.BeginPopupModal(
        ctx, "FX Folder##browser_styled", nil,
        imgui.WindowFlags_AlwaysAutoResize) then
        local is_rename = dialog.mode:find("^rename") ~= nil
        imgui.Text(ctx, is_rename and "Rename Folder" or "Create Folder")
        imgui.Separator(ctx)
        imgui.SetNextItemWidth(ctx, 280)
        local changed, value = imgui.InputTextWithHint(
            ctx, "##fx_folder_name", "Folder name", dialog.value)
        if changed then dialog.value = value end

        local clean_name = dialog.value
            :gsub("[/\\:*?\"<>|]", "")
            :match("^%s*(.-)%s*$")
        if imgui.Button(ctx, is_rename and "Rename" or "Create")
            and clean_name ~= "" then
            if dialog.mode == "create_favorite" then
                local path = dialog.parent ~= ""
                    and (dialog.parent .. "/" .. clean_name) or clean_name
                fx.favorite_folders[path] = true
                SaveFXFavorites()
                imgui.CloseCurrentPopup(ctx)
            elseif dialog.mode == "rename_favorite" then
                if RenameFavoriteFolder(dialog.target, clean_name) then
                    imgui.CloseCurrentPopup(ctx)
                else
                    fx.status = "That Favorites folder name is already in use."
                end
            end
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Cancel") then imgui.CloseCurrentPopup(ctx) end
        imgui.EndPopup(ctx)
    end
end

function DrawRightAlignedBrowserGroupCount(count, selected, group_label)
    local label = tostring(count or 0)
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local max_x, max_y = imgui.GetItemRectMax(ctx)
    local text_w, text_h = imgui.CalcTextSize(ctx, label)
    local group_w = select(1, imgui.CalcTextSize(ctx, group_label or ""))
    if max_x - min_x < group_w + text_w + 52 then return end
    local theme = state.resolved_theme or state.theme.colors
    local text_color = theme.text or state.theme.colors.text
    local background = theme.panel_bg or state.theme.colors.panel_bg
    local hovered = imgui.IsItemHovered(ctx)
    local count_color = selected and GetSelectedTextColor()
        or (hovered and GetFolderTextColor()
            or BlendColor(text_color, background, 0.52))
    imgui.DrawList_AddText(
        imgui.GetWindowDrawList(ctx),
        math.max(min_x, max_x - text_w - 8),
        min_y + math.max(0, (max_y - min_y - text_h) * 0.5),
        count_color, label)
end

function DrawFXFolderView()
    local fx = state.fx_browser
    local groups = GetCachedFXGroups(fx.view_mode)
    for group_index, group in ipairs(groups) do
        local label = string.format(
            "%s##fx_group_%s_%d",
            group.name, fx.view_mode, group_index)
        local was_open = fx.open_group[fx.view_mode] == group.name
        imgui.SetNextItemOpen(ctx, was_open)
        local flags = FLG_SPAN_WIDTH
        local group_selected = fx.keyboard_cursor_kind == "group"
            and fx.keyboard_group == group.name
        if group_selected then
            flags = flags | imgui.TreeNodeFlags_Selected
        end
        local open = DrawBrowserFolderTreeNode(
            label, flags, group_selected)
        DrawRightAlignedBrowserGroupCount(
            #group.items, group_selected, group.name)
        if fx.keyboard_scroll_group == group.name then
            imgui.SetScrollHereY(ctx, 0.5)
            fx.keyboard_scroll_group = nil
        end
        if open ~= was_open then
            fx.open_group[fx.view_mode] = open and group.name or nil
        end
        if imgui.IsItemClicked(ctx, 0) then
            SetOnlyFXSelected(nil)
            fx.keyboard_cursor_kind = "group"
            fx.keyboard_group = group.name
        end
        if open then
            local group_row_keys = GetFXRowKeyMap(
                "group:" .. fx.view_mode .. ":" .. tostring(group_index),
                group.items,
                fx.view_mode .. "_" .. tostring(group_index) .. "_", false)
            if not fx.clipper then
                fx.clipper = imgui.CreateListClipper(ctx)
                imgui.Attach(ctx, fx.clipper)
            end
            imgui.ListClipper_Begin(fx.clipper, #group.items)
            if fx.keyboard_scroll_ident
                and imgui.ListClipper_IncludeItemByIndex then
                for index, item in ipairs(group.items) do
                    if item.ident == fx.keyboard_scroll_ident then
                        pcall(imgui.ListClipper_IncludeItemByIndex,
                            fx.clipper, index - 1)
                        break
                    end
                end
            end
            while imgui.ListClipper_Step(fx.clipper) do
                local first, last =
                    imgui.ListClipper_GetDisplayRange(fx.clipper)
                for item_index = first + 1, last do
                    local item = group.items[item_index]
                    if item then
                        DrawFXItemRow(
                            item,
                            group_row_keys[item.ident], group.items,
                            nil, true, group_row_keys)
                    end
                end
            end
            imgui.TreePop(ctx)
        end
    end
end

function DrawFXBrowser()
    local fx = state.fx_browser
    fx.initialization_stage = fx.initialization_stage or 0
    if fx.initialization_stage == 0 then
        fx.initialization_stage = 1
        fx.status = "Preparing plug-in browser..."
    elseif fx.initialization_stage == 1 then
        LoadREAPERFXMetadata()
        fx.initialization_stage = 2
        fx.status = "Loading cached plug-ins..."
    elseif fx.initialization_stage == 2 then
        if not fx.scanning and not fx.scan_complete and #fx.items == 0 then
            if not LoadFXInventoryCache() then StartFXScan() end
        end
        fx.initialization_stage = 3
    end
    if fx.initialization_stage >= 3 then UpdateFXFilter() end

    local avail_w, avail_h = imgui.GetContentRegionAvail(ctx)
    local panel_w = math.max(0, avail_w)
    local panel_h = math.max(180, avail_h)
    local panel_bg = state.resolved_theme and state.resolved_theme.panel_bg
        or state.theme.colors.panel_bg
    local border = state.resolved_theme and state.resolved_theme.border
        or state.theme.colors.border

    imgui.PushStyleColor(ctx, imgui.Col_ChildBg, panel_bg)
    imgui.PushStyleColor(ctx, imgui.Col_Border, border)
    local child_visible = imgui.BeginChild(
        ctx, "##fx_browser", panel_w, panel_h,
        FLG_CHILD_BORDER)
    if child_visible then
        imgui.SetNextItemWidth(ctx, -42)
        if imgui.SetNextItemAllowOverlap then
            imgui.SetNextItemAllowOverlap(ctx)
        end
        local changed, value = imgui.InputTextWithHint(
            ctx, "##fx_search", "Search installed plug-ins...", fx.search)
        if changed then fx.search = value end
        fx.search_active = imgui.IsItemActive(ctx)
        if DrawSearchClearOverlay("##clear_fx_search", fx.search ~= "") then
            fx.search = ""
            fx.last_search = nil
        end
        imgui.SameLine(ctx)
        if fx.scanning and imgui.BeginDisabled then imgui.BeginDisabled(ctx) end
        local refresh_clicked = DrawFXToolbarIcon(
            "refresh", fx.scanning, "Refresh installed plug-ins")
        if fx.scanning and imgui.EndDisabled then imgui.EndDisabled(ctx) end
        if refresh_clicked and not fx.scanning then StartFXScan() end

        if DrawFXToolbarIcon(
            "type_all", fx.type_filter == "all", "All plug-ins") then
            fx.type_filter = "all"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon(
            "instrument", fx.type_filter == "instrument", "Instruments") then
            fx.type_filter = "instrument"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon(
            "effect", fx.type_filter == "effect", "Audio and MIDI effects") then
            fx.type_filter = "effect"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx, "|")
        imgui.SameLine(ctx)

        if DrawFXToolbarIcon(
            "categories", fx.view_mode == "category", "Group by category") then
            fx.view_mode = "category"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon(
            "vendors", fx.view_mode == "vendor", "Group by vendor") then
            fx.view_mode = "vendor"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon(
            "all_plugins", fx.view_mode == "all", "Show all plug-ins") then
            fx.view_mode = "all"
            SaveFXBrowserPreferences()
        end
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx, "|")
        imgui.SameLine(ctx)
        DrawFXSortCombo()

        DrawFXFormatChecks()

        imgui.Separator(ctx)

        local _, remaining_h = imgui.GetContentRegionAvail(ctx)
        local footer_h = 34
        local list_visible = imgui.BeginChild(
            ctx, "##fx_list", 0, math.max(80, remaining_h - footer_h),
            FLG_CHILD_BORDER)
        if list_visible then
            fx.favorite_drop_active = false
            fx.favorite_drop_target = ""
            DrawFXLibraryRoots()
            local has_search = fx.search:match("%S") ~= nil
            if has_search then
                local query = NormalizeBrowserSearchTokens(fx.search)
                if fx.preset_search_query ~= query then
                    fx.preset_search_query = query
                    fx.chain_search_results = CollectPresetTreeMatches(
                        fx.chain_tree, query, {})
                    fx.template_search_results = CollectPresetTreeMatches(
                        fx.track_template_tree, query, {})
                end
                local chain_matches = fx.chain_search_results
                local template_matches = fx.template_search_results
                local accent = state.resolved_theme
                    and state.resolved_theme.folder_text
                    or state.theme.colors.folder_text
                if #fx.filtered_items > 0 then
                    imgui.PushStyleColor(ctx, imgui.Col_Text, accent)
                    imgui.Text(ctx, "PLUG-INS")
                    imgui.PopStyleColor(ctx)
                end
                -- Search can span every installed plug-in. Submit only the
                -- visible rows, exactly like the All Plug-ins view.
                if not fx.clipper then
                    fx.clipper = imgui.CreateListClipper(ctx)
                    imgui.Attach(ctx, fx.clipper)
                end
                local search_row_keys = GetFXRowKeyMap(
                    "search", fx.filtered_items, "search_", false)
                imgui.ListClipper_Begin(fx.clipper, #fx.filtered_items)
                while imgui.ListClipper_Step(fx.clipper) do
                    local dmin, dmax =
                        imgui.ListClipper_GetDisplayRange(fx.clipper)
                    for index = dmin + 1, dmax do
                        local item = fx.filtered_items[index]
                        if item then
                            DrawFXItemRow(
                                item, search_row_keys[item.ident],
                                fx.filtered_items, nil, nil, search_row_keys)
                        end
                    end
                end
                if #fx.filtered_items > 0 then imgui.Separator(ctx) end
                DrawFXPresetSearchGroup(
                    "FX CHAINS", "fx_chain", chain_matches,
                    AddFXChainToTrack, true)
                DrawFXPresetSearchGroup(
                    "TRACK TEMPLATES", "track_template", template_matches,
                    InsertTrackTemplate, true)
                if #fx.filtered_items == 0 and #chain_matches == 0
                    and #template_matches == 0 then
                    imgui.TextDisabled(
                        ctx, "No matching plug-ins, chains, or templates.")
                end
            elseif fx.view_mode == "all" then
                -- An attached clipper remains valid while this tab is hidden
                -- and avoids creating a short-lived resource every frame.
                if not fx.clipper then
                    fx.clipper = imgui.CreateListClipper(ctx)
                    imgui.Attach(ctx, fx.clipper)
                end
                local all_row_keys = GetFXRowKeyMap(
                    "all", fx.filtered_items, "all_", false)
                imgui.ListClipper_Begin(fx.clipper, #fx.filtered_items)
                if fx.keyboard_scroll_ident
                    and imgui.ListClipper_IncludeItemByIndex then
                    for index, item in ipairs(fx.filtered_items) do
                        if item.ident == fx.keyboard_scroll_ident then
                            pcall(imgui.ListClipper_IncludeItemByIndex,
                                fx.clipper, index - 1)
                            break
                        end
                    end
                end
                while imgui.ListClipper_Step(fx.clipper) do
                    local dmin, dmax =
                        imgui.ListClipper_GetDisplayRange(fx.clipper)
                    for i = dmin + 1, dmax do
                        local item = fx.filtered_items[i]
                        if item then
                            DrawFXItemRow(
                                item, all_row_keys[item.ident],
                                fx.filtered_items, nil, nil, all_row_keys)
                        end
                    end
                end
            else
                DrawFXFolderView()
            end
            imgui.EndChild(ctx)
        end

        local can_add = next(fx.selected_idents or {}) ~= nil
        if not can_add then imgui.BeginDisabled(ctx) end
        if DrawFXToolbarIcon(
            "add_track", false, "Add selected plug-in(s) to selected track")
            and can_add then
            AddFXItemsToTrack(
                GetSelectedFXItems(), r.GetSelectedTrack(0, 0), false)
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon(
            "add_input", false, "Add selected plug-in(s) as input FX")
            and can_add then
            AddFXItemsToTrack(
                GetSelectedFXItems(), r.GetSelectedTrack(0, 0), true)
        end
        if not can_add then imgui.EndDisabled(ctx) end
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx, fx.status)
        imgui.EndChild(ctx)
    end
    imgui.PopStyleColor(ctx, 2)
    DrawFXFolderDialog()
end

function IsFXDragMouseDown()
    -- ReaImGui may stop receiving button transitions after the pointer enters
    -- another native REAPER window. JS_Mouse_GetState remains global.
    if r.JS_Mouse_GetState then
        local ok, mouse_state = pcall(r.JS_Mouse_GetState, 1)
        if ok and type(mouse_state) == "number" then
            return (mouse_state & 1) ~= 0
        end
    end
    return imgui.IsMouseDown(ctx, 0)
end

function GetFXDragModifiers()
    -- gfx/JS mouse flags use 4 for Ctrl/Cmd and 16 for Alt/Option. Query them
    -- globally while outside ReaBrowse, with the ImGui snapshot as fallback.
    if r.JS_Mouse_GetState then
        local ok, mouse_state = pcall(r.JS_Mouse_GetState, 4 | 16)
        if ok and type(mouse_state) == "number" then
            return (mouse_state & 4) ~= 0, (mouse_state & 16) ~= 0
        end
    end
    local ctrl, _, alt = GetSelectionModifiers()
    return ctrl, alt
end

function ResolveFXDropKind(target, alt)
    if not target then return nil end
    if target.kind == "monitoring_fx" or target.kind == "input_fx"
        or target.kind == "track_fx" or target.kind == "take_fx" then
        return target.kind
    end
    if target.kind == "track" then return alt and "input_fx" or "track_fx" end
    return nil
end

function GetFXDropKindLabel(kind)
    if kind == "monitoring_fx" then return "Monitoring FX" end
    if kind == "input_fx" then return "Input FX" end
    if kind == "track_fx" then return "Track FX" end
    if kind == "take_fx" then return "Item / Take FX" end
    return "No FX target"
end

function ProcessFXDrag()
    local fx = state.fx_browser
    if not fx.drag_active or not fx.drag_item then return end
    local drag_items = fx.drag_items or {}
    if #drag_items == 0 then drag_items = {fx.drag_item} end
    local ctrl, alt = GetFXDragModifiers()
    fx.drag_input_fx = alt
    if ctrl then fx.drag_copy_favorite = true end

    local mouse_x, mouse_y
    if r.GetMousePosition then
        mouse_x, mouse_y = r.GetMousePosition()
    else
        mouse_x, mouse_y = imgui.GetMousePos(ctx)
    end
    local outside_browser =
        mouse_x < state.win_x or mouse_x > state.win_x + state.win_w
        or mouse_y < state.win_y or mouse_y > state.win_y + state.win_h
    local target = GetFXDropTarget(mouse_x, mouse_y)
    -- Explicit native FX windows can overlap ReaBrowse. Generic track regions
    -- are only eligible after the pointer actually leaves this window.
    if not outside_browser and not (target and target.explicit_chain) then
        target = nil
    end
    local drop_kind = ResolveFXDropKind(target, fx.drag_input_fx)
    local drop_as_input_fx = drop_kind == "input_fx"
        or drop_kind == "monitoring_fx"

    if imgui.BeginTooltip(ctx) then
        if fx.favorite_drop_active then
            local source_folder = fx.drag_source_folder
            local copy_drop = source_folder == nil or fx.drag_copy_favorite
            imgui.Text(ctx, (copy_drop and "Copy " or "Move ")
                .. (#drag_items > 1
                    and (tostring(#drag_items) .. " plug-ins")
                    or "plug-in"))
            imgui.TextDisabled(ctx,
                fx.favorite_drop_target ~= ""
                    and ("Folder: " .. fx.favorite_drop_target)
                    or "Favorites root")
        else
            imgui.Text(ctx, GetFXDropKindLabel(drop_kind))
            imgui.TextDisabled(ctx,
                "Drop on an audio/MIDI item, track, or FX chain")
            if not (target and target.explicit_chain) then
                imgui.TextDisabled(ctx,
                    "Alt changes a direct track drop to Input FX")
            end
        end
        imgui.TextDisabled(ctx, #drag_items > 1
            and (tostring(#drag_items) .. " selected plug-ins")
            or fx.drag_item.name)
        if not fx.favorite_drop_active and target and target.take then
            imgui.TextDisabled(ctx, "Target: "
                .. GetTakeFXDestinationName(target.take))
        elseif not fx.favorite_drop_active and target and target.track then
            local _, track_name = r.GetTrackName(target.track)
            local target_name = drop_kind == "monitoring_fx"
                and "Monitoring FX"
                or ((track_name or "Track") .. " / "
                    .. GetFXDropKindLabel(drop_kind))
            imgui.TextDisabled(ctx, "Target: " .. target_name)
        elseif not fx.favorite_drop_active and target and target.create_new then
            imgui.TextDisabled(ctx, "Target: New track / "
                .. GetFXDropKindLabel(drop_kind))
        elseif not fx.favorite_drop_active and outside_browser then
            imgui.TextDisabled(ctx,
                target and target.region
                    and ("Not an FX drop target: " .. target.region)
                or "No track under the mouse")
        end
        imgui.EndTooltip(ctx)
    end

    if not IsFXDragMouseDown() then
        if fx.favorite_drop_active then
            local source_folder = fx.drag_source_folder
            local target_folder = fx.favorite_drop_target or ""
            local copy_drop = source_folder == nil or fx.drag_copy_favorite
            ApplyFXFavoriteDrop(
                drag_items, source_folder, target_folder, copy_drop)
            fx.status = fx.favorite_drop_target ~= ""
                and ((copy_drop and "Copied " or "Moved ")
                    .. tostring(#drag_items)
                    .. " plug-in(s) in Favorites / "
                    .. fx.favorite_drop_target)
                or ("Added " .. tostring(#drag_items)
                    .. " plug-in(s) to Favorites.")
        elseif target and target.take and drop_kind == "take_fx" then
            AddFXItemsToTake(drag_items, target.take, false)
        elseif target and target.track and drop_kind then
            AddFXItemsToTrack(
                drag_items, target.track, drop_as_input_fx,
                target.explicit_chain == true, target.insert_index, target.insert_slot)
        elseif target and target.create_new and outside_browser then
            CreateTrackWithFXItems(drag_items, fx.drag_input_fx)
        elseif outside_browser then
            fx.status = "Drop cancelled: no REAPER item or track under the mouse."
        end
        fx.drag_active = false
        fx.drag_item = nil
        fx.drag_items = {}
        fx.drag_pending_item = nil
        fx.drag_pending_row_key = nil
        fx.drag_pending_ctrl = false
        fx.drag_input_fx = false
        fx.drag_copy_favorite = false
        fx.drag_ctrl_at_click = false
        fx.drag_source_folder = nil
        fx.favorite_drop_active = false
        fx.favorite_drop_target = ""
    end
end

function ProcessPendingFXCtrlClick()
    local fx = state.fx_browser
    local pending = fx.pending_ctrl_click
    if not pending then
        if not fx.drag_active and not imgui.IsMouseDown(ctx, 0) then
            fx.drag_pending_item = nil
            fx.drag_pending_row_key = nil
            fx.drag_pending_ctrl = false
        end
        return
    end
    if fx.drag_active or imgui.IsMouseDown(ctx, 0) then
        return
    end
    fx.pending_ctrl_click = nil
    if pending.item and pending.toggle then
        ToggleFXSelected(pending.item, pending.row_key)
    elseif pending.item and pending.collapse then
        SetOnlyFXSelected(pending.item, pending.row_key)
    end
    fx.drag_pending_item = nil
    fx.drag_pending_row_key = nil
    fx.drag_pending_ctrl = false
end

function HandleFXTabKeys()
    local fx = state.fx_browser
    if fx.search_active then return end
    if imgui.IsKeyPressed(ctx, imgui.Key_Space, false) then
        if state.is_playing then
            StopPreview()
            if (r.GetPlayState() & 1) ~= 0 then r.CSurf_OnStop() end
        else
            r.Main_OnCommand(40044, 0) -- Transport: Play/stop
        end
        return
    end

    local move_down = imgui.IsKeyPressed(ctx, imgui.Key_DownArrow, true)
    local move_up = imgui.IsKeyPressed(ctx, imgui.Key_UpArrow, true)
    local move_right = imgui.IsKeyPressed(ctx, imgui.Key_RightArrow, true)
    local move_left = imgui.IsKeyPressed(ctx, imgui.Key_LeftArrow, true)
    local activate = imgui.IsKeyPressed(ctx, imgui.Key_Enter, false)
    if not move_down and not move_up and not move_right
        and not move_left and not activate then
        return
    end

    local has_search = fx.search:match("%S") ~= nil
    local entries = {}
    if fx.view_mode == "all" or has_search then
        for _, item in ipairs(fx.filtered_items) do
            entries[#entries + 1] = {kind = "item", item = item}
        end
    else
        entries[#entries + 1] = {kind = "root"}
        for _, group in ipairs(GetCachedFXGroups(fx.view_mode)) do
            entries[#entries + 1] = {kind = "group", group = group}
            if fx.open_group[fx.view_mode] == group.name then
                for _, item in ipairs(group.items) do
                    entries[#entries + 1] = {
                        kind = "item", item = item, group = group}
                end
            end
        end
    end

    local current_index = nil
    for index, entry in ipairs(entries) do
        if entry.kind == "root"
            and fx.keyboard_cursor_kind == "root" then
            current_index = index
            break
        elseif entry.kind == "group"
            and fx.keyboard_cursor_kind == "group"
            and fx.keyboard_group == entry.group.name then
            current_index = index
            break
        elseif entry.kind == "item"
            and fx.keyboard_cursor_kind ~= "group"
            and entry.item.ident == fx.selected_ident then
            current_index = index
            break
        end
    end

    local function SelectEntry(entry)
        if not entry then return end
        if entry.kind == "root" then
            fx.keyboard_cursor_kind = "root"
            fx.keyboard_group = nil
            SetOnlyFXSelected(nil)
        elseif entry.kind == "group" then
            fx.keyboard_cursor_kind = "group"
            fx.keyboard_group = entry.group.name
            fx.keyboard_scroll_group = entry.group.name
            SetOnlyFXSelected(nil)
        else
            SetOnlyFXSelected(entry.item)
            fx.keyboard_group = entry.group and entry.group.name or nil
            fx.keyboard_scroll_ident = entry.item.ident
        end
    end

    if move_down then
        SelectEntry(entries[math.min(#entries, (current_index or 0) + 1)])
        return
    elseif move_up then
        SelectEntry(entries[math.max(1,
            (current_index or (#entries + 1)) - 1)])
        return
    elseif move_right then
        local entry = current_index and entries[current_index] or nil
        if entry and entry.kind == "root" then
            SelectEntry(entries[current_index + 1])
        elseif entry and entry.kind == "group" then
            if fx.open_group[fx.view_mode] ~= entry.group.name then
                fx.open_group[fx.view_mode] = entry.group.name
            elseif entries[current_index + 1]
                and entries[current_index + 1].kind == "item" then
                SelectEntry(entries[current_index + 1])
            end
        end
        return
    elseif move_left then
        local entry = current_index and entries[current_index] or nil
        if entry and entry.kind == "item" then
            local parent_group = entry.group
            if not parent_group and fx.open_group[fx.view_mode] then
                for _, group in ipairs(GetCachedFXGroups(fx.view_mode)) do
                    if group.name == fx.open_group[fx.view_mode] then
                        parent_group = group
                        break
                    end
                end
            end
            if parent_group then
                SelectEntry({kind = "group", group = parent_group})
            end
        elseif entry and entry.kind == "group"
            and fx.open_group[fx.view_mode] == entry.group.name then
            fx.open_group[fx.view_mode] = nil
        elseif entry and entry.kind == "group" then
            local groups = GetCachedFXGroups(fx.view_mode)
            local previous = nil
            for index, group in ipairs(groups) do
                if group.name == entry.group.name then
                    previous = groups[index - 1]
                    break
                end
            end
            if previous then
                SelectEntry({kind = "group", group = previous})
            else
                SelectEntry({kind = "root"})
            end
        elseif fx.selected_ident and fx.open_group[fx.view_mode] then
            for _, group in ipairs(GetCachedFXGroups(fx.view_mode)) do
                if group.name == fx.open_group[fx.view_mode] then
                    SelectEntry({kind = "group", group = group})
                    break
                end
            end
        end
        return
    elseif activate then
        local entry = current_index and entries[current_index] or nil
        if entry and entry.kind == "root" then
            SelectEntry(entries[current_index + 1])
        elseif entry and entry.kind == "group" then
            fx.open_group[fx.view_mode] =
                fx.open_group[fx.view_mode] == entry.group.name
                    and nil or entry.group.name
        elseif entry and entry.kind == "item" then
            AddFXItemsToTrack(
                GetSelectedFXItems(entry.item), r.GetSelectedTrack(0, 0), false)
        end
    end
end

-- ============================================================
-- ACTIONS BROWSER
-- ============================================================
-- Action enumeration is deliberately lazy and time-sliced. ReaBrowse runs on
-- REAPER's UI thread, so this tab performs no action-list work until opened and
-- never re-enumerates or re-filters from the normal per-frame path.
function LoadActionsBrowserState()
    local actions = state.actions_browser
    if actions.initialized then return end
    actions.initialized = true

    EachFXStateRecord(r.GetExtState(EXT_SECTION, "ActionFavoriteFolders"),
        function(record)
            local folder = DecodeFXStateField(record)
            if folder ~= "" then actions.favorite_folders[folder] = true end
        end)
    EachFXStateRecord(r.GetExtState(EXT_SECTION, "ActionFavorites"),
        function(record)
            local encoded_folder, encoded_key = record:match("^(.-),(.*)$")
            local folder, key
            if encoded_folder and encoded_key then
                folder = DecodeFXStateField(encoded_folder)
                key = DecodeFXStateField(encoded_key)
            end
            if key and key ~= "" then
                actions.favorites[key] = true
                actions.favorite_memberships[key] =
                    actions.favorite_memberships[key] or {}
                actions.favorite_memberships[key][folder and folder ~= ""
                    and folder or RB_FAVORITES_ROOT_MEMBERSHIP] = true
            end
        end)
    EachFXStateRecord(r.GetExtState(EXT_SECTION, "ActionUsage"),
        function(record)
            local count, last_used, sequence, encoded_key =
                record:match("^(%d+),(%d+),(%d+),(.*)$")
            local key = DecodeFXStateField(encoded_key)
            if key and key ~= "" then
                actions.usage[key] = {
                    count = tonumber(count) or 0,
                    last_used = tonumber(last_used) or 0,
                    sequence = tonumber(sequence) or 0,
                }
                actions.usage_generation = math.max(
                    actions.usage_generation or 0, tonumber(sequence) or 0)
            end
        end)
    local saved_view = r.GetExtState(EXT_SECTION, "ActionViewMode")
    if saved_view == "category" or saved_view == "section"
        or saved_view == "all" then
        actions.view_mode = saved_view
    end
    local saved_sort = r.GetExtState(EXT_SECTION, "ActionSortMode")
    if saved_sort == "name_az" or saved_sort == "name_za"
        or saved_sort == "section" or saved_sort == "recent"
        or saved_sort == "used" then
        actions.sort_mode = saved_sort
    end
    local saved_section = tonumber(
        r.GetExtState(EXT_SECTION, "ActionSectionFilter"))
    if saved_section then actions.section_filter = saved_section end
end

function SaveActionsBrowserPreferences()
    local actions = state.actions_browser
    r.SetExtState(EXT_SECTION, "ActionViewMode",
        tostring(actions.view_mode or "category"), true)
    r.SetExtState(EXT_SECTION, "ActionSortMode",
        tostring(actions.sort_mode or "name_az"), true)
    r.SetExtState(EXT_SECTION, "ActionSectionFilter",
        actions.section_filter == "all" and "" or
            tostring(actions.section_filter), true)
end

function GetBrowserActionCategory(name, named_command)
    local prefix = tostring(name or ""):match("^%s*([^:]+):")
    if prefix then
        prefix = prefix:match("^%s*(.-)%s*$")
        if prefix:lower() == "script" then return "Scripts" end
        if prefix:lower() == "custom" then return "Custom Actions" end
        if #prefix > 0 and #prefix <= 42 then return prefix end
    end
    local named = tostring(named_command or ""):upper()
    if named:find("^_SWS") or named:find("^_BR_") then
        return "Extensions"
    end
    return "Other"
end

function NormalizeBrowserActionSearch(value)
    return NormalizeBrowserSearchTokens(value)
end

function GetActionsInventoryCachePath()
    return GetReaBrowseDataDirectory() .. "/ReaBrowse_Actions_Inventory.tsv"
end

function PrepareBrowserActionSections()
    local sections_by_id = {}
    for _, section in ipairs(state.actions_browser.sections) do
        section.api = r.SectionFromUniqueID
            and r.SectionFromUniqueID(section.id) or nil
        sections_by_id[section.id] = section
    end
    return sections_by_id
end

function BuildBrowserActionItem(section, command_id, name, named_command)
    if not section or not command_id or not name or name == "" then return nil end
    local key = tostring(section.id) .. ":" .. tostring(command_id)
    local item = {
        key = key,
        command_id = command_id,
        command_text = named_command or tostring(command_id),
        named_command = named_command,
        name = name,
        name_lower = name:lower(),
        section_id = section.id,
        section_name = section.name,
        section = section,
    }
    item.category = GetBrowserActionCategory(item.name, item.named_command)
    return item
end

function GetBrowserActionSearchText(item)
    if item.search_text == nil then
        item.search_text = NormalizeBrowserActionSearch(
            item.name .. " " .. item.command_text .. " "
                .. item.section_name .. " " .. item.category)
    end
    return item.search_text
end

function CompareBrowserActionNames(a, b)
    if a.name_lower == b.name_lower then return a.key < b.key end
    return a.name_lower < b.name_lower
end

function SaveActionsInventoryCache()
    local actions = state.actions_browser
    if #(actions.items or {}) == 0 then return false end
    if not EnsureReaBrowseDataLayout() then return false end
    local target = GetActionsInventoryCachePath()
    local temporary = target .. ".tmp"
    local file = io.open(temporary, "w")
    if not file then return false end
    file:write("ReaBrowseActionsInventory\t2\n")
    local ordered = actions.items
    if not actions.inventory_name_sorted then
        ordered = {}
        for index, item in ipairs(actions.items) do ordered[index] = item end
        table.sort(ordered, CompareBrowserActionNames)
    end
    for _, item in ipairs(ordered) do
        file:write(table.concat({
            tostring(item.section_id),
            tostring(item.command_id),
            EncodeFXStateField(item.name),
            EncodeFXStateField(item.named_command or ""),
        }, "\t"), "\n")
    end
    file:close()
    pcall(os.remove, target)
    local ok = os.rename(temporary, target)
    if not ok then pcall(os.remove, temporary) end
    if ok then actions.cache_upgrade_pending = false end
    return ok == true
end

function LoadActionsInventoryCache()
    local actions = state.actions_browser
    local file = io.open(GetActionsInventoryCachePath(), "r")
    if not file then return false end
    local header = file:read("*l")
    local sorted_cache = header == "ReaBrowseActionsInventory\t2"
    if not sorted_cache and header ~= "ReaBrowseActionsInventory\t1" then
        file:close()
        return false
    end
    local sections_by_id = PrepareBrowserActionSections()
    local items, items_by_key = {}, {}
    for line in file:lines() do
        local section_text, command_text, encoded_name, encoded_named =
            line:match("^(.-)\t(.-)\t(.-)\t(.*)$")
        local section = sections_by_id[tonumber(section_text)]
        local command_id = tonumber(command_text)
        local name = encoded_name and DecodeFXStateField(encoded_name) or ""
        local named = encoded_named and DecodeFXStateField(encoded_named) or ""
        if named == "" then named = nil end
        local item = BuildBrowserActionItem(
            section, command_id, name, named)
        if item then
            items[#items + 1] = item
            items_by_key[item.key] = item
        end
    end
    file:close()
    if #items == 0 then return false end
    if not sorted_cache then table.sort(items, CompareBrowserActionNames) end
    actions.items = items
    actions.items_by_key = items_by_key
    actions.filtered_items = {}
    actions.filtered_group_items = {}
    actions.inventory_name_sorted = true
    actions.cache_upgrade_pending = not sorted_cache
    actions.scanning = false
    actions.scan_complete = true
    actions.cache_loaded = true
    actions.generation = (actions.generation or 0) + 1
    actions.filtered_generation = -1
    actions.view_cache = nil
    actions.view_cache_signature = nil
    actions.status = string.format("%d cached actions ready.", #items)
    return true
end

function SaveActionsFavorites()
    local actions = state.actions_browser
    local folders = {}
    for folder in pairs(actions.favorite_folders) do
        folders[#folders + 1] = folder
    end
    table.sort(folders)
    local folder_records = {}
    for _, folder in ipairs(folders) do
        folder_records[#folder_records + 1] = EncodeFXStateField(folder)
    end
    r.SetExtState(EXT_SECTION, "ActionFavoriteFolders",
        #folder_records > 0 and ("v2;" .. table.concat(folder_records, ";"))
            or "", true)

    local keys = {}
    for key in pairs(actions.favorites) do keys[#keys + 1] = key end
    table.sort(keys)
    local records = {}
    for _, key in ipairs(keys) do
        local memberships = actions.favorite_memberships[key] or {}
        local membership_folders = {}
        for folder in pairs(memberships) do
            membership_folders[#membership_folders + 1] =
                folder == RB_FAVORITES_ROOT_MEMBERSHIP and "" or folder
        end
        table.sort(membership_folders)
        if #membership_folders == 0 then membership_folders[1] = "" end
        for _, folder in ipairs(membership_folders) do
            records[#records + 1] = EncodeFXStateField(folder)
                .. "," .. EncodeFXStateField(key)
        end
    end
    r.SetExtState(EXT_SECTION, "ActionFavorites",
        #records > 0 and ("v2;" .. table.concat(records, ";")) or "", true)
    actions.favorite_generation = (actions.favorite_generation or 0) + 1
    actions.view_cache_signature = nil
end

function SaveActionsUsage(force)
    local actions = state.actions_browser
    if not actions.usage_dirty then return end
    if not force and r.time_precise() < (actions.usage_save_due or 0) then return end
    local keys = {}
    for key in pairs(actions.usage) do keys[#keys + 1] = key end
    table.sort(keys)
    local records = {}
    for _, key in ipairs(keys) do
        local usage = actions.usage[key]
        records[#records + 1] = string.format("%d,%d,%d,%s",
            usage.count or 0, usage.last_used or 0, usage.sequence or 0,
            EncodeFXStateField(key))
    end
    r.SetExtState(EXT_SECTION, "ActionUsage",
        #records > 0 and ("v2;" .. table.concat(records, ";")) or "", true)
    actions.usage_dirty = false
end

function StartActionsScan()
    local actions = state.actions_browser
    LoadActionsBrowserState()
    actions.items = {}
    actions.items_by_key = {}
    actions.filtered_items = {}
    actions.filtered_group_items = {}
    actions.inventory_name_sorted = false
    actions.scanning = true
    actions.scan_complete = false
    actions.scan_section_index = 1
    actions.scan_action_index = 0
    actions.filtered_generation = -1
    actions.view_cache = nil
    actions.view_cache_signature = nil
    actions.selected_key = nil
    actions.selected_keys = {}
    actions.selected_row_keys = {}
    actions.selected_count = 0
    actions.selection_anchor_key = nil
    PrepareBrowserActionSections()
    actions.status = "Discovering REAPER actions..."
end

function ProcessActionsScan()
    local actions = state.actions_browser
    if not actions.scanning then return end
    -- A short wall-clock budget is safer than a fixed large batch on systems
    -- with many extension actions. This runs only while the Actions tab is
    -- visible and never uses a worker or continues as a background task.
    local started = r.time_precise()
    local processed = 0
    while actions.scan_section_index <= #actions.sections
        and processed < 160 and r.time_precise() - started < 0.002 do
        local section = actions.sections[actions.scan_section_index]
        if not section.api then
            actions.scan_section_index = actions.scan_section_index + 1
            actions.scan_action_index = 0
        else
            local command_id, name = r.kbd_enumerateActions(
                section.api, actions.scan_action_index)
            if not command_id or command_id == 0 then
                actions.scan_section_index = actions.scan_section_index + 1
                actions.scan_action_index = 0
            else
                name = tostring(name or "")
                if name == "" and r.kbd_getTextFromCmd then
                    name = r.kbd_getTextFromCmd(command_id, section.api) or ""
                end
                if name ~= "" then
                    local named = r.ReverseNamedCommandLookup
                        and r.ReverseNamedCommandLookup(command_id) or nil
                    if named == "" then named = nil end
                    local named_command = named and ("_" .. named) or nil
                    local item = BuildBrowserActionItem(
                        section, command_id, name, named_command)
                    if item then
                        actions.items[#actions.items + 1] = item
                        actions.items_by_key[item.key] = item
                    end
                end
                actions.scan_action_index = actions.scan_action_index + 1
                processed = processed + 1
            end
        end
    end
    if actions.scan_section_index > #actions.sections then
        actions.scanning = false
        if #actions.items == 0 then
            actions.scan_complete = false
            if LoadActionsInventoryCache() then
                actions.status =
                    "Refresh found no actions; the previous cache was kept."
            else
                actions.status =
                    "No actions were found. The cache was not changed."
            end
            return
        end
        table.sort(actions.items, CompareBrowserActionNames)
        actions.inventory_name_sorted = true
        actions.scan_complete = true
        actions.generation = (actions.generation or 0) + 1
        actions.filtered_generation = -1
        actions.view_cache_signature = nil
        actions.cache_loaded = SaveActionsInventoryCache()
        actions.status = string.format(actions.cache_loaded
            and "%d cached actions ready."
            or "%d actions ready (cache could not be saved).", #actions.items)
    else
        actions.status = string.format(
            "Discovering REAPER actions... %d", #actions.items)
    end
end

function CompareBrowserActions(a, b, sort_mode, favorites_first)
    local actions = state.actions_browser
    if favorites_first then
        local af = actions.favorites[a.key] == true
        local bf = actions.favorites[b.key] == true
        if af ~= bf then return af end
    end
    local au = actions.usage[a.key] or {}
    local bu = actions.usage[b.key] or {}
    if sort_mode == "name_za" then
        if a.name_lower ~= b.name_lower then return a.name_lower > b.name_lower end
    elseif sort_mode == "section" then
        if a.section_name ~= b.section_name then
            return a.section_name < b.section_name
        end
    elseif sort_mode == "recent" then
        if (au.sequence or 0) ~= (bu.sequence or 0) then
            return (au.sequence or 0) > (bu.sequence or 0)
        end
    elseif sort_mode == "used" then
        if (au.count or 0) ~= (bu.count or 0) then
            return (au.count or 0) > (bu.count or 0)
        end
    end
    if a.name_lower == b.name_lower then return a.key < b.key end
    return a.name_lower < b.name_lower
end

function UpdateActionsFilter(force)
    local actions = state.actions_browser
    if actions.scanning then return end
    if not force and actions.filtered_generation == actions.generation
        and actions.last_search == actions.search
        and actions.last_section_filter == actions.section_filter
        and actions.last_sort_mode == actions.sort_mode then
        return
    end
    if not force and actions.last_search ~= nil
        and actions.last_search ~= actions.search
        and r.time_precise() < (actions.filter_due or 0) then
        return
    end
    local query = NormalizeBrowserActionSearch(actions.search)
    local base_results, favorite_results, normal_results = {}, {}, {}
    for _, item in ipairs(actions.items) do
        -- Empty-search browsing does not need the relatively expensive
        -- punctuation/token normalization for every cached action. Build it
        -- once, on demand, when the user actually searches.
        local matches = query == "" or BrowserSearchTokensMatch(
            GetBrowserActionSearchText(item), query)
        if (actions.section_filter == "all"
                or item.section_id == actions.section_filter)
            and matches then
            base_results[#base_results + 1] = item
            if actions.favorites[item.key] then
                favorite_results[#favorite_results + 1] = item
            else
                normal_results[#normal_results + 1] = item
            end
        end
    end
    local results
    if (actions.sort_mode or "name_az") == "name_az"
        and actions.inventory_name_sorted then
        -- The inventory cache is persisted in name order. Stable filtering
        -- therefore needs no O(n log n) sort on tab open; a pair of linear
        -- passes retains the existing favorites-first result behavior.
        results = favorite_results
        for _, item in ipairs(normal_results) do
            results[#results + 1] = item
        end
        actions.filtered_group_items = base_results
    else
        results = base_results
        table.sort(results, function(a, b)
            return CompareBrowserActions(
                a, b, actions.sort_mode or "name_az", true)
        end)
        actions.filtered_group_items = results
    end
    actions.filtered_items = results
    actions.filtered_generation = actions.generation
    actions.last_search = actions.search
    actions.last_section_filter = actions.section_filter
    actions.last_sort_mode = actions.sort_mode
end

function ClearActionsSearch()
    local actions = state.actions_browser
    actions.search = ""
    actions.last_search = nil
    actions.filter_due = 0
    actions.view_cache_signature = nil
    UpdateActionsFilter(true)
end

function GetActionShortcutText(item)
    if not item then return "" end
    if item.shortcut ~= nil then return item.shortcut end
    item.shortcut = ""
    if not item.section or not item.section.api
        or not r.CountActionShortcuts or not r.GetActionShortcutDesc then
        return item.shortcut
    end
    local count = r.CountActionShortcuts(item.section.api, item.command_id) or 0
    if count > 0 then
        local ok, description = r.GetActionShortcutDesc(
            item.section.api, item.command_id, 0)
        if ok then item.shortcut = description or "" end
    end
    return item.shortcut
end

function SaveActionUse(item)
    local actions = state.actions_browser
    local usage = actions.usage[item.key] or {count = 0}
    actions.usage_generation = (actions.usage_generation or 0) + 1
    usage.count = (usage.count or 0) + 1
    usage.last_used = os.time()
    usage.sequence = actions.usage_generation
    actions.usage[item.key] = usage
    actions.usage_dirty = true
    actions.usage_save_due = r.time_precise() + 0.75
    if actions.sort_mode == "recent" or actions.sort_mode == "used" then
        -- Usage-based browse ordering changes globally, so only those two
        -- sort modes need a complete regroup. Normal browsing keeps its
        -- cached category/section arrays and updates the two small roots.
        actions.view_cache_signature = nil
    elseif actions.view_cache then
        local cache = actions.view_cache
        local function AddOnce(items)
            for _, candidate in ipairs(items) do
                if candidate.key == item.key then return end
            end
            items[#items + 1] = item
        end
        AddOnce(cache.recent)
        AddOnce(cache.used)
        table.sort(cache.recent, function(a, b)
            local au = actions.usage[a.key] or {}
            local bu = actions.usage[b.key] or {}
            return (au.sequence or 0) > (bu.sequence or 0)
        end)
        table.sort(cache.used, function(a, b)
            local au = actions.usage[a.key] or {}
            local bu = actions.usage[b.key] or {}
            if (au.count or 0) == (bu.count or 0) then
                return (au.sequence or 0) > (bu.sequence or 0)
            end
            return (au.count or 0) > (bu.count or 0)
        end)
        while #cache.recent > 50 do table.remove(cache.recent) end
        while #cache.used > 50 do table.remove(cache.used) end
    end
end

function ExecuteBrowserAction(item)
    if not item then return false end
    local actions = state.actions_browser
    local command_id = item.command_id
    if item.named_command and r.NamedCommandLookup then
        local resolved = r.NamedCommandLookup(item.named_command)
        if resolved and resolved ~= 0 then command_id = resolved end
    end
    local executed = false
    if item.section_id == 0 then
        if r.Main_OnCommandEx then
            r.Main_OnCommandEx(command_id, 0, (r.EnumProjects(-1, "")))
        else
            r.Main_OnCommand(command_id, 0)
        end
        executed = true
    elseif item.section_id == 32060 or item.section_id == 32061 then
        if r.MIDIEditor_LastFocused_OnCommand then
            executed = r.MIDIEditor_LastFocused_OnCommand(
                command_id, item.section_id == 32061) == true
        else
            local editor = r.MIDIEditor_GetActive and r.MIDIEditor_GetActive()
            executed = editor and r.MIDIEditor_OnCommand
                and r.MIDIEditor_OnCommand(editor, command_id) == true or false
        end
    end
    if executed then
        SaveActionUse(item)
        actions.status = "Executed: " .. item.name
    else
        if item.section_id == 32060 or item.section_id == 32061 then
            actions.status =
                "Open/focus the matching MIDI editor, then try again."
        else
            actions.status =
                "This action section cannot be executed from ReaBrowse."
        end
    end
    return executed
end

function SetOnlyBrowserActionSelected(item, row_key)
    local actions = state.actions_browser
    actions.selected_keys = {}
    actions.selected_row_keys = {}
    actions.selected_key = item and item.key or nil
    actions.selected_count = item and 1 or 0
    actions.selection_anchor_key = item and item.key or nil
    if item then
        actions.keyboard_cursor_kind = "item"
        actions.selected_keys[item.key] = true
        actions.selected_row_keys[item.key] = row_key
    end
end

function ToggleBrowserActionSelected(item, row_key)
    if not item then return end
    local actions = state.actions_browser
    actions.keyboard_cursor_kind = "item"
    if actions.selected_keys[item.key]
        and actions.selected_row_keys[item.key] == row_key then
        actions.selected_keys[item.key] = nil
        actions.selected_row_keys[item.key] = nil
        actions.selected_count = math.max(0,
            (actions.selected_count or 0) - 1)
    else
        if not actions.selected_keys[item.key] then
            actions.selected_count = (actions.selected_count or 0) + 1
        end
        actions.selected_keys[item.key] = true
        actions.selected_row_keys[item.key] = row_key
    end
    actions.selection_anchor_key = item.key
    actions.selected_key = nil
    for key in pairs(actions.selected_keys) do
        actions.selected_key = key
        break
    end
end

function SelectBrowserActionItem(
    item, selection_order, row_key, ctrl, shift, list_id)
    local actions = state.actions_browser
    actions.keyboard_cursor_kind = "item"
    if shift and actions.selection_anchor_key and selection_order then
        local anchor_index, item_index
        for index, candidate in ipairs(selection_order) do
            if candidate.key == actions.selection_anchor_key then anchor_index = index end
            if candidate.key == item.key then item_index = index end
        end
        if anchor_index and item_index then
            if not ctrl then
                actions.selected_keys = {}
                actions.selected_row_keys = {}
                actions.selected_count = 0
            end
            for index = math.min(anchor_index, item_index),
                math.max(anchor_index, item_index) do
                local selected_item = selection_order[index]
                if not actions.selected_keys[selected_item.key] then
                    actions.selected_count =
                        (actions.selected_count or 0) + 1
                end
                actions.selected_keys[selected_item.key] = true
                actions.selected_row_keys[selected_item.key] = list_id
                    and (list_id .. "_" .. tostring(index)
                        .. "_" .. selected_item.key)
                    or (selected_item.key == item.key and row_key or nil)
            end
            actions.selected_key = item.key
            return
        end
    end
    if ctrl then
        ToggleBrowserActionSelected(item, row_key)
    else
        SetOnlyBrowserActionSelected(item, row_key)
    end
end

function GetSelectedBrowserActions(fallback_item)
    local actions = state.actions_browser
    local items = {}
    for _, item in ipairs(actions.items) do
        if actions.selected_keys[item.key] then items[#items + 1] = item end
    end
    if #items == 0 and fallback_item then items[1] = fallback_item end
    return items
end

function EnsureBrowserActionContextSelection(item, row_key)
    local actions = state.actions_browser
    if not actions.selected_keys[item.key]
        or actions.selected_row_keys[item.key] ~= row_key then
        SetOnlyBrowserActionSelected(item, row_key)
    end
end

function SetBrowserActionsFavoriteState(items, folder, enabled)
    local actions = state.actions_browser
    for _, item in ipairs(items or {}) do
        local memberships = actions.favorite_memberships[item.key] or {}
        if folder ~= nil then
            local membership_key = folder ~= ""
                and folder or RB_FAVORITES_ROOT_MEMBERSHIP
            memberships[membership_key] = enabled and true or nil
            if enabled then
                actions.favorites[item.key] = true
                actions.favorite_memberships[item.key] = memberships
            elseif next(memberships) == nil then
                -- Removing the final visible folder instance removes the
                -- favorite instead of silently moving it to Unsorted.
                actions.favorites[item.key] = nil
                actions.favorite_memberships[item.key] = nil
            else
                actions.favorite_memberships[item.key] = memberships
            end
        elseif enabled then
            actions.favorites[item.key] = true
            memberships[RB_FAVORITES_ROOT_MEMBERSHIP] = true
            actions.favorite_memberships[item.key] = memberships
        else
            actions.favorites[item.key] = nil
            actions.favorite_memberships[item.key] = nil
        end
    end
    SaveActionsFavorites()
    UpdateActionsFilter(true)
end

function ToggleBrowserActionsFavoriteMembership(items, folder)
    local actions = state.actions_browser
    local all_have = #items > 0
    for _, item in ipairs(items) do
        if folder ~= nil then
            local membership_key = folder ~= ""
                and folder or RB_FAVORITES_ROOT_MEMBERSHIP
            if not (actions.favorite_memberships[item.key]
                and actions.favorite_memberships[item.key][membership_key]) then
                all_have = false
                break
            end
        elseif not actions.favorites[item.key] then
            all_have = false
            break
        end
    end
    SetBrowserActionsFavoriteState(items, folder, not all_have)
end

function GetActionsViewCache()
    local actions = state.actions_browser
    local browse_mode = actions.view_mode == "section" and "section"
        or (actions.view_mode == "category" and "category" or "all")
    local search_surface = tostring(actions.search or ""):match("%S")
        and "search" or "browse"
    local usage_sort_generation =
        (actions.sort_mode == "recent" or actions.sort_mode == "used")
            and (actions.usage_generation or 0) or 0
    local signature = table.concat({
        tostring(actions.generation or 0),
        tostring(actions.favorite_generation or 0),
        tostring(usage_sort_generation),
        tostring(actions.section_filter),
        tostring(actions.sort_mode or "name_az"),
        browse_mode,
        search_surface,
    }, ":")
    if actions.view_cache and actions.view_cache_signature == signature then
        return actions.view_cache
    end
    local cache = {
        sections = {}, categories = {}, unsorted = {}, folders = {},
        favorite_children = {[''] = {}}, recent = {}, used = {},
        group_views = {}}
    if browse_mode == "section" then
        for _, section in ipairs(actions.sections) do
            cache.sections[section.id] = {}
        end
    end
    for folder in pairs(actions.favorite_folders) do
        cache.folders[folder] = {}
        local parent = FavoritePathParent(folder)
        cache.favorite_children[parent] =
            cache.favorite_children[parent] or {}
        cache.favorite_children[parent][
            #cache.favorite_children[parent] + 1] = folder
        cache.favorite_children[folder] =
            cache.favorite_children[folder] or {}
    end
    for _, children in pairs(cache.favorite_children) do
        table.sort(children)
    end
    -- Search draws Favorites as stable organizational/drop targets. Never
    -- derive that tree from one transient query, or clearing the query can
    -- leave a partial cached library until another unrelated invalidation.
    local view_items = search_surface == "search" and actions.items
        or actions.filtered_group_items or actions.filtered_items
    for _, item in ipairs(view_items) do
        if browse_mode == "section" then
            local section_items = cache.sections[item.section_id]
            if section_items then section_items[#section_items + 1] = item end
        elseif browse_mode == "category" then
            local category = item.category or "Other"
            cache.categories[category] = cache.categories[category] or {}
            cache.categories[category][#cache.categories[category] + 1] = item
        end
        if actions.favorites[item.key] then
            local memberships = actions.favorite_memberships[item.key] or {}
            if next(memberships) == nil then
                memberships[RB_FAVORITES_ROOT_MEMBERSHIP] = true
                actions.favorite_memberships[item.key] = memberships
            end
            if memberships[RB_FAVORITES_ROOT_MEMBERSHIP] then
                cache.unsorted[#cache.unsorted + 1] = item
            end
            for folder in pairs(memberships) do
                if folder ~= RB_FAVORITES_ROOT_MEMBERSHIP then
                    cache.folders[folder] = cache.folders[folder] or {}
                    cache.folders[folder][#cache.folders[folder] + 1] = item
                end
            end
        end
        local usage = actions.usage[item.key]
        if usage and (usage.count or 0) > 0 then
            cache.recent[#cache.recent + 1] = item
            cache.used[#cache.used + 1] = item
        end
    end
    local function SortForBrowse(items)
        table.sort(items, function(a, b)
            return CompareBrowserActions(
                a, b, actions.sort_mode or "name_az", false)
        end)
    end
    local already_name_ordered = (actions.sort_mode or "name_az") == "name_az"
        and actions.inventory_name_sorted
    if not already_name_ordered then
        if browse_mode == "section" then
            for _, items in pairs(cache.sections) do SortForBrowse(items) end
        elseif browse_mode == "category" then
            for _, items in pairs(cache.categories) do SortForBrowse(items) end
        end
        SortForBrowse(cache.unsorted)
        for _, items in pairs(cache.folders) do SortForBrowse(items) end
    end
    table.sort(cache.recent, function(a, b)
        local au = actions.usage[a.key] or {}
        local bu = actions.usage[b.key] or {}
        return (au.sequence or 0) > (bu.sequence or 0)
    end)
    while #cache.recent > 50 do table.remove(cache.recent) end
    table.sort(cache.used, function(a, b)
        local au = actions.usage[a.key] or {}
        local bu = actions.usage[b.key] or {}
        if (au.count or 0) == (bu.count or 0) then
            return (au.sequence or 0) > (bu.sequence or 0)
        end
        return (au.count or 0) > (bu.count or 0)
    end)
    while #cache.used > 50 do table.remove(cache.used) end
    actions.view_cache = cache
    actions.view_cache_signature = signature
    return cache
end

function DrawActionBrowserRow(
    item, context_folder, row_id, selection_order, list_id, grouped_view)
    local actions = state.actions_browser
    local favorite = actions.favorites[item.key] == true
    local selected = actions.selected_keys[item.key] == true
        and actions.selected_row_keys[item.key] == row_id
    local flags = imgui.TreeNodeFlags_Leaf | FLG_SPAN_WIDTH
    if selected then flags = flags | imgui.TreeNodeFlags_Selected end
    if selected then
        imgui.PushStyleColor(ctx, imgui.Col_Text, GetSelectedTextColor())
    end
    local heart_prepared_hot, heart_hover_style, heart_indent =
        PrepareFavoriteGutter(true, 0)
    local opened = imgui.TreeNode(
        ctx, item.name .. "##action_row_" .. row_id, flags)
    if actions.keyboard_scroll_key == row_id then
        imgui.SetScrollHereY(ctx, 0.5)
        actions.keyboard_scroll_key = nil
    end
    if heart_hover_style then imgui.PopStyleColor(ctx) end
    if heart_indent > 0 then imgui.Unindent(ctx, heart_indent) end
    local min_x, min_y = imgui.GetItemRectMin(ctx)
    local _, max_y = imgui.GetItemRectMax(ctx)
    local hovered = imgui.IsItemHovered(ctx)
        and not actions.suppress_mouse_hover
    if selected then imgui.PopStyleColor(ctx) end
    local mouse_x, mouse_y = imgui.GetMousePos(ctx)
    local gutter = GetFavoriteRowGutter(true)
    local heart_x = gutter.heart_x
    local heart_hovered = not actions.suppress_mouse_hover and (
        heart_prepared_hot or (
        mouse_x >= heart_x - 2 and mouse_x <= heart_x + gutter.hit_width
        and mouse_y >= min_y and mouse_y <= max_y))
    local glyph_color, glyph = GetFavoriteHeartAppearance(
        favorite, selected, hovered, false)
    imgui.DrawList_AddText(
        imgui.GetWindowDrawList(ctx), heart_x, min_y, glyph_color, glyph)
    local interaction = CaptureBrowserRowInteraction()
    if heart_hovered and imgui.IsMouseClicked(ctx, 0) then
        local target_items = selected
            and GetSelectedBrowserActions(item) or {item}
        ToggleBrowserActionsFavoriteMembership(target_items, context_folder)
    elseif interaction.clicked then
        local click_ctrl = interaction.ctrl == true
        actions.drag_pending_item = item
        actions.drag_pending_row_key = row_id
        actions.drag_pending_ctrl = click_ctrl
        if click_ctrl then
            -- Wait until mouse-up before toggling. If the gesture becomes a
            -- drag, retaining the existing selection lets Ctrl-drag copy the
            -- whole selection instead of collapsing it to one action.
            actions.pending_ctrl_click = {
                item = item, row_key = row_id, toggle = true}
        elseif selected and #GetSelectedBrowserActions(item) > 1
            and not interaction.shift then
            -- Preserve all selected actions through the drag threshold. A
            -- normal mouse-up still collapses selection to the clicked row.
            actions.pending_ctrl_click = {
                item = item, row_key = row_id, collapse = true}
        else
            actions.pending_ctrl_click = nil
            SelectBrowserActionItem(item, selection_order, row_id,
                false, interaction.shift == true, list_id)
        end
    end
    if not heart_hovered and interaction.double_clicked then
        SetOnlyBrowserActionSelected(item, row_id)
        ExecuteBrowserAction(item)
    end
    if (interaction.active
        or (actions.drag_pending_item == item
            and actions.drag_pending_row_key == row_id))
        and imgui.IsMouseDragging(ctx, 0) then
        if not actions.drag_active then
            actions.pending_ctrl_click = nil
            if not actions.selected_keys[item.key] then
                SetOnlyBrowserActionSelected(item, row_id)
            end
            actions.drag_active = true
            actions.drag_item = item
            actions.drag_items = GetSelectedBrowserActions(item)
            actions.drag_source_folder = context_folder
            actions.drag_copy_favorite = actions.drag_pending_ctrl
                or select(1, GetSelectionModifiers())
            actions.drag_pending_item = nil
            actions.drag_pending_row_key = nil
            actions.drag_pending_ctrl = false
        end
    end
    if hovered and not imgui.IsMouseDown(ctx, 0) then
        local shortcut = GetActionShortcutText(item)
        imgui.SetTooltip(ctx, item.section_name
            .. (shortcut ~= "" and (" | " .. shortcut) or "")
            .. "\nCommand ID: " .. item.command_text)
    end
    if imgui.BeginPopupContextItem(ctx, "##action_context_" .. row_id) then
        imgui.PushStyleVar(ctx, imgui.StyleVar_ItemSpacing, 7, 5)
        EnsureBrowserActionContextSelection(item, row_id)
        local selected_items = GetSelectedBrowserActions(item)
        local plural = #selected_items > 1
        if imgui.MenuItem(ctx, "Run action") then ExecuteBrowserAction(item) end
        imgui.Separator(ctx)
        local all_favorites = #selected_items > 0
        for _, selected_item in ipairs(selected_items) do
            if not actions.favorites[selected_item.key] then
                all_favorites = false
                break
            end
        end
        if imgui.MenuItem(ctx, all_favorites
            and (plural and "Remove Selected from Favorites"
                or "Remove from Favorites")
            or (plural and "Add Selected to Favorites"
                or "Add to Favorites")) then
            SetBrowserActionsFavoriteState(
                selected_items, nil, not all_favorites)
        end
        if context_folder and imgui.MenuItem(ctx, plural
            and "Remove Selected from this Favorites folder"
            or "Remove from this Favorites folder") then
            SetBrowserActionsFavoriteState(selected_items, context_folder, false)
        end
        local folders = {}
        for folder in pairs(actions.favorite_folders) do
            folders[#folders + 1] = folder
        end
        table.sort(folders)
        if #folders > 0 and imgui.BeginMenu(ctx, plural
            and "Add Selected to Favorites Folder"
            or "Add to Favorites Folder") then
            for _, folder in ipairs(folders) do
                local all_have = true
                for _, selected_item in ipairs(selected_items) do
                    if not (actions.favorite_memberships[selected_item.key]
                        and actions.favorite_memberships[selected_item.key][folder]) then
                        all_have = false
                        break
                    end
                end
                if imgui.MenuItem(ctx,
                    (all_have and "\xe2\x9c\x93 " or "") .. folder) then
                    SetBrowserActionsFavoriteState(
                        selected_items, folder, not all_have)
                end
            end
            imgui.EndMenu(ctx)
        end
        imgui.Separator(ctx)
        if not plural and imgui.MenuItem(ctx, "Copy command ID")
            and imgui.SetClipboardText then
            imgui.SetClipboardText(ctx, item.command_text)
        end
        imgui.PopStyleVar(ctx)
        imgui.EndPopup(ctx)
    end
    if opened then imgui.TreePop(ctx) end
end

function DrawClippedActionList(items, context_folder, list_id, grouped_view)
    local actions = state.actions_browser
    if not items or #items == 0 then
        imgui.TextDisabled(ctx, "No actions in this group.")
        return
    end
    if not actions.clipper then
        actions.clipper = imgui.CreateListClipper(ctx)
        imgui.Attach(ctx, actions.clipper)
    end
    imgui.ListClipper_Begin(actions.clipper, #items)
    if actions.keyboard_scroll_key
        and imgui.ListClipper_IncludeItemByIndex then
        for index, item in ipairs(items) do
            local candidate_id = list_id .. "_" .. tostring(index)
                .. "_" .. item.key
            if candidate_id == actions.keyboard_scroll_key then
                pcall(imgui.ListClipper_IncludeItemByIndex,
                    actions.clipper, index - 1)
                break
            end
        end
    end
    while imgui.ListClipper_Step(actions.clipper) do
        local first, last = imgui.ListClipper_GetDisplayRange(actions.clipper)
        for index = first + 1, last do
            local item = items[index]
            if item then
                local row_id = list_id .. "_" .. tostring(index)
                    .. "_" .. item.key
                DrawActionBrowserRow(item, context_folder, row_id,
                    items, list_id, grouped_view)
            end
        end
    end
end

function RenameBrowserActionFavoriteFolder(old_path, new_name)
    local actions = state.actions_browser
    local parent = FavoritePathParent(old_path)
    local new_path = parent ~= "" and (parent .. "/" .. new_name) or new_name
    if new_path == old_path or actions.favorite_folders[new_path] then return false end
    local replacements = {}
    for path in pairs(actions.favorite_folders) do
        if path == old_path or path:sub(1, #old_path + 1) == old_path .. "/" then
            replacements[path] = new_path .. path:sub(#old_path + 1)
        end
    end
    for old in pairs(replacements) do actions.favorite_folders[old] = nil end
    for _, replacement in pairs(replacements) do
        actions.favorite_folders[replacement] = true
    end
    for _, memberships in pairs(actions.favorite_memberships) do
        local moved = {}
        for old, replacement in pairs(replacements) do
            if memberships[old] then moved[replacement] = true end
            memberships[old] = nil
        end
        for replacement in pairs(moved) do memberships[replacement] = true end
    end
    SaveActionsFavorites()
    return true
end

function MoveBrowserActionFavoriteFolder(old_path, target_parent)
    local actions = state.actions_browser
    target_parent = target_parent or ""
    if target_parent == old_path
        or target_parent:sub(1, #old_path + 1) == old_path .. "/" then
        return false
    end
    local name = old_path:match("([^/]+)$") or old_path
    local new_path = target_parent ~= ""
        and (target_parent .. "/" .. name) or name
    if new_path == old_path or actions.favorite_folders[new_path] then
        return false
    end
    local replacements = {}
    for path in pairs(actions.favorite_folders) do
        if path == old_path or path:sub(1, #old_path + 1) == old_path .. "/" then
            replacements[path] = new_path .. path:sub(#old_path + 1)
        end
    end
    for old in pairs(replacements) do actions.favorite_folders[old] = nil end
    for _, replacement in pairs(replacements) do
        actions.favorite_folders[replacement] = true
    end
    for _, memberships in pairs(actions.favorite_memberships) do
        local moved = {}
        for old, replacement in pairs(replacements) do
            if memberships[old] then moved[replacement] = true end
            memberships[old] = nil
        end
        for replacement in pairs(moved) do memberships[replacement] = true end
    end
    SaveActionsFavorites()
    actions.status = "Moved Favorites folder."
    UpdateActionsFilter(true)
    return true
end

function DeleteBrowserActionFavoriteFolder(path)
    local actions = state.actions_browser
    local removed = {}
    for candidate in pairs(actions.favorite_folders) do
        if candidate == path
            or candidate:sub(1, #path + 1) == path .. "/" then
            removed[candidate] = true
            actions.favorite_folders[candidate] = nil
        end
    end
    for _, memberships in pairs(actions.favorite_memberships) do
        for candidate in pairs(removed) do memberships[candidate] = nil end
        -- Folder deletion is an organizational operation. Favorites whose
        -- folders were deleted remain directly at the Favorites root.
    end
    SaveActionsFavorites()
end

function PromptBrowserActionFavoriteFolder(parent, target)
    local dialog = state.actions_browser.folder_dialog
    dialog.mode = target and "rename" or "create"
    dialog.parent = parent or ""
    dialog.target = target or ""
    dialog.value = target and (target:match("([^/]+)$") or target) or ""
    dialog.open = true
end

function DrawActionsFolderDialog()
    local dialog = state.actions_browser.folder_dialog
    if dialog.open then
        imgui.OpenPopup(ctx, "Action Favorites Folder##browser_styled")
        dialog.open = false
    end
    if imgui.BeginPopupModal(ctx,
        "Action Favorites Folder##browser_styled", nil,
        imgui.WindowFlags_AlwaysAutoResize) then
        local is_rename = dialog.mode == "rename"
        imgui.Text(ctx, is_rename
            and "Rename Favorites Folder" or "Create Favorites Folder")
        imgui.Separator(ctx)
        imgui.SetNextItemWidth(ctx, 280)
        local changed, value = imgui.InputTextWithHint(
            ctx, "##action_folder_name", "Folder name", dialog.value)
        if changed then dialog.value = value end
        local clean = dialog.value:gsub("[/\\:*?\"<>|]", "")
            :match("^%s*(.-)%s*$")
        if imgui.Button(ctx, is_rename and "Rename" or "Create")
            and clean ~= "" then
            local completed = false
            if is_rename then
                completed = RenameBrowserActionFavoriteFolder(
                    dialog.target, clean)
            else
                local path = dialog.parent ~= ""
                    and (dialog.parent .. "/" .. clean) or clean
                if not state.actions_browser.favorite_folders[path] then
                    state.actions_browser.favorite_folders[path] = true
                    SaveActionsFavorites()
                    completed = true
                end
            end
            if completed then
                dialog.value = ""
                imgui.CloseCurrentPopup(ctx)
            else
                state.actions_browser.status =
                    "That Favorites folder name is already in use."
            end
        end
        imgui.SameLine(ctx)
        if imgui.Button(ctx, "Cancel") then imgui.CloseCurrentPopup(ctx) end
        imgui.EndPopup(ctx)
    end
end

function DrawBrowserActionFavoriteFolder(path, cache)
    local actions = state.actions_browser
    local label = path:match("([^/]+)$") or path
    local items = cache.folders[path] or {}
    local open = DrawBrowserFolderTreeNode(
        label .. "##actions_folder_" .. path,
        FLG_SPAN_WIDTH, false)
    if actions.drag_active and IsMouseInsideLastItem() then
        actions.favorite_drop_active = true
        actions.favorite_drop_target = path
    end
    if imgui.BeginPopupContextItem(ctx, "##actions_folder_context_" .. path) then
        if imgui.MenuItem(ctx, "Create New Subfolder...") then
            PromptBrowserActionFavoriteFolder(path, nil)
        end
        if imgui.MenuItem(ctx, "Rename Folder...") then
            PromptBrowserActionFavoriteFolder(FavoritePathParent(path), path)
        end
        local current_parent = FavoritePathParent(path)
        if current_parent ~= ""
            and imgui.MenuItem(ctx, "Move to Favorites Root") then
            MoveBrowserActionFavoriteFolder(path, "")
        end
        local move_targets = {}
        for candidate in pairs(actions.favorite_folders) do
            if candidate ~= path and candidate ~= current_parent
                and candidate:sub(1, #path + 1) ~= path .. "/" then
                move_targets[#move_targets + 1] = candidate
            end
        end
        table.sort(move_targets)
        if #move_targets > 0 and imgui.BeginMenu(ctx, "Move to Folder") then
            for _, target in ipairs(move_targets) do
                if imgui.MenuItem(ctx, target) then
                    MoveBrowserActionFavoriteFolder(path, target)
                end
            end
            imgui.EndMenu(ctx)
        end
        imgui.Separator(ctx)
        if imgui.MenuItem(ctx, "Delete folder") then
            actions.pending_delete_folder = path
        end
        imgui.EndPopup(ctx)
    end
    if open then
        local children = cache.favorite_children[path] or {}
        for _, child in ipairs(children) do
            DrawBrowserActionFavoriteFolder(child, cache)
        end
        DrawClippedActionList(items, path, "favorites_" .. path, true)
        imgui.TreePop(ctx)
    end
end

function GetActionBrowseGroups(cache)
    local actions = state.actions_browser
    cache = cache or GetActionsViewCache()
    local mode = actions.view_mode == "section" and "section" or "category"
    if cache.group_views[mode] then return cache.group_views[mode] end
    local groups = {}
    if mode == "section" then
        for _, section in ipairs(actions.sections) do
            groups[#groups + 1] = {
                name = section.name,
                id = tostring(section.id),
                items = cache.sections[section.id] or {},
            }
        end
    else
        for category, items in pairs(cache.categories) do
            groups[#groups + 1] = {
                name = category, id = category, items = items}
        end
    end
    table.sort(groups, function(a, b)
        return a.name:lower() < b.name:lower()
    end)
    cache.group_views[mode] = groups
    return groups
end

function DrawActionsLibraryRoots(suppress_browse)
    local actions = state.actions_browser
    local cache = GetActionsViewCache()
    actions.favorite_drop_active = false
    actions.favorite_drop_target = ""
    imgui.Spacing(ctx)
    if DrawFavoritesLibraryHeader(
        "actions_add_folder", "Create Favorites folder") then
        PromptBrowserActionFavoriteFolder("", nil)
    end
    imgui.Separator(ctx)
    local favorites_open = DrawBrowserFolderTreeNode(
        "\xe2\x99\xa5  Favorites##actions_favorites_root",
        FLG_SPAN_WIDTH, false)
    if actions.drag_active and IsMouseInsideLastItem() then
        actions.favorite_drop_active = true
        actions.favorite_drop_target = ""
    end
    if imgui.BeginPopupContextItem(ctx, "##actions_favorites_root_context") then
        if imgui.MenuItem(ctx, "New Favorites Folder...") then
            PromptBrowserActionFavoriteFolder("", nil)
        end
        imgui.EndPopup(ctx)
    end
    if favorites_open then
        local roots = cache.favorite_children[''] or {}
        for _, folder in ipairs(roots) do
            DrawBrowserActionFavoriteFolder(folder, cache)
        end
        if #cache.unsorted > 0 then
            DrawClippedActionList(
                cache.unsorted, "", "favorites_root", true)
        end
        if #roots == 0 and #cache.unsorted == 0 then
            imgui.TextDisabled(ctx,
                "No favorites yet. Click a heart or drag an action here.")
        end
        imgui.TreePop(ctx)
    end
    if actions.pending_delete_folder then
        local path = actions.pending_delete_folder
        actions.pending_delete_folder = nil
        DeleteBrowserActionFavoriteFolder(path)
    end

    if DrawBrowserFolderTreeNode(
        "Recent##actions_recent", FLG_SPAN_WIDTH, false) then
        DrawClippedActionList(cache.recent, nil, "recent", true)
        imgui.TreePop(ctx)
    end
    if DrawBrowserFolderTreeNode(
        "Most Used##actions_used", FLG_SPAN_WIDTH, false) then
        DrawClippedActionList(cache.used, nil, "used", true)
        imgui.TreePop(ctx)
    end

    if suppress_browse then return end

    imgui.Separator(ctx)
    imgui.Spacing(ctx)
    imgui.Text(ctx, "BROWSE ACTIONS")
    imgui.Separator(ctx)
    if actions.view_mode == "all" then
        DrawClippedActionList(actions.filtered_items, nil, "all_actions", true)
        return
    end

    local groups = GetActionBrowseGroups(cache)
    local mode = actions.view_mode == "section" and "section" or "category"
    for _, group in ipairs(groups) do
        local was_open = actions.open_group[mode] == group.id
        imgui.SetNextItemOpen(ctx, was_open)
        local flags = FLG_SPAN_WIDTH
        local group_selected = actions.keyboard_cursor_kind == "group"
            and actions.keyboard_group == group.id
        if group_selected then
            flags = flags | imgui.TreeNodeFlags_Selected
        end
        local open = DrawBrowserFolderTreeNode(
            string.format("%s##actions_group_%s_%s",
                group.name, mode, group.id), flags, group_selected)
        DrawRightAlignedBrowserGroupCount(
            #group.items, group_selected, group.name)
        if actions.keyboard_scroll_group == group.id then
            imgui.SetScrollHereY(ctx, 0.5)
            actions.keyboard_scroll_group = nil
        end
        if open ~= was_open then
            actions.open_group[mode] = open and group.id or nil
        end
        if imgui.IsItemClicked(ctx, 0) then
            SetOnlyBrowserActionSelected(nil)
            actions.keyboard_cursor_kind = "group"
            actions.keyboard_group = group.id
        end
        if open then
            DrawClippedActionList(group.items, nil,
                "group_" .. mode .. "_" .. group.id, true)
            imgui.TreePop(ctx)
        end
    end
end

function ApplyBrowserActionFavoriteDrop(
    items, source_folder, target_folder, copy_drop)
    local actions = state.actions_browser
    target_folder = target_folder or ""
    for _, item in ipairs(items or {}) do
        local memberships = actions.favorite_memberships[item.key] or {}
        actions.favorites[item.key] = true
        local target_key = target_folder ~= ""
            and target_folder or RB_FAVORITES_ROOT_MEMBERSHIP
        memberships[target_key] = true
        if not copy_drop and source_folder ~= nil
            and source_folder ~= target_folder then
            local source_key = source_folder ~= ""
                and source_folder or RB_FAVORITES_ROOT_MEMBERSHIP
            memberships[source_key] = nil
        end
        actions.favorite_memberships[item.key] = memberships
    end
    SaveActionsFavorites()
    UpdateActionsFilter(true)
end

function ProcessPendingActionsCtrlClick()
    local actions = state.actions_browser
    local pending = actions.pending_ctrl_click
    if not pending then
        if not actions.drag_active and not imgui.IsMouseDown(ctx, 0) then
            actions.drag_pending_item = nil
            actions.drag_pending_row_key = nil
            actions.drag_pending_ctrl = false
        end
        return
    end
    if actions.drag_active or imgui.IsMouseDown(ctx, 0) then return end
    actions.pending_ctrl_click = nil
    if pending.item and pending.toggle then
        ToggleBrowserActionSelected(pending.item, pending.row_key)
    elseif pending.item and pending.collapse then
        SetOnlyBrowserActionSelected(pending.item, pending.row_key)
    end
    actions.drag_pending_item = nil
    actions.drag_pending_row_key = nil
    actions.drag_pending_ctrl = false
end

function ProcessActionsFavoriteDrag()
    local actions = state.actions_browser
    if not actions.drag_active or not actions.drag_item then return end
    local drag_items = actions.drag_items or {}
    if #drag_items == 0 then drag_items = {actions.drag_item} end
    if select(1, GetSelectionModifiers()) then
        actions.drag_copy_favorite = true
    end
    local source_folder = actions.drag_source_folder
    local copy_drop = source_folder == nil or actions.drag_copy_favorite

    if imgui.BeginTooltip(ctx) then
        local target_is_root = actions.favorite_drop_active
            and actions.favorite_drop_target == ""
        local operation = source_folder == nil and "Add "
            or (copy_drop and not target_is_root and "Copy " or "Move ")
        imgui.Text(ctx, operation .. (#drag_items > 1
            and (tostring(#drag_items) .. " actions") or "action"))
        if actions.favorite_drop_active then
            imgui.TextDisabled(ctx, actions.favorite_drop_target ~= ""
                and ("Folder: " .. actions.favorite_drop_target)
                or "Favorites root")
        else
            imgui.TextDisabled(ctx,
                "Drop on a Favorites folder or Favorites root")
        end
        imgui.TextDisabled(ctx, #drag_items > 1
            and (tostring(#drag_items) .. " selected actions")
            or actions.drag_item.name)
        imgui.EndTooltip(ctx)
    end

    if not imgui.IsMouseDown(ctx, 0) then
        if actions.favorite_drop_active then
            local target_folder = actions.favorite_drop_target or ""
            ApplyBrowserActionFavoriteDrop(
                drag_items, source_folder, target_folder, copy_drop)
            local operation = source_folder == nil and "Added"
                or (copy_drop and "Copied" or "Moved")
            actions.status = target_folder ~= ""
                and string.format("%s %d action(s) in Favorites / %s.",
                    operation, #drag_items, target_folder)
                or string.format("%s %d action(s) to Favorites root.",
                    source_folder == nil and "Added" or "Moved",
                    #drag_items)
        else
            actions.status = "Favorite drag cancelled."
        end
        actions.drag_active = false
        actions.drag_item = nil
        actions.drag_items = {}
        actions.drag_pending_item = nil
        actions.drag_pending_row_key = nil
        actions.drag_pending_ctrl = false
        actions.pending_ctrl_click = nil
        actions.drag_copy_favorite = false
        actions.drag_source_folder = nil
        actions.favorite_drop_active = false
        actions.favorite_drop_target = ""
    end
end

function HandleActionsTabKeys()
    local actions = state.actions_browser
    local move_down = imgui.IsKeyPressed(ctx, imgui.Key_DownArrow, true)
    local move_up = imgui.IsKeyPressed(ctx, imgui.Key_UpArrow, true)
    local move_right = not actions.search_active
        and imgui.IsKeyPressed(ctx, imgui.Key_RightArrow, true)
    local move_left = not actions.search_active
        and imgui.IsKeyPressed(ctx, imgui.Key_LeftArrow, true)
    local activate = imgui.IsKeyPressed(ctx, imgui.Key_Enter, false)
    if not move_down and not move_up and not move_right
        and not move_left and not activate then
        return
    end
    if move_down or move_up or move_right or move_left then
        actions.suppress_mouse_hover = true
        actions.suppress_hover_mouse_x,
            actions.suppress_hover_mouse_y = imgui.GetMousePos(ctx)
    end
    if actions.last_search ~= actions.search then
        UpdateActionsFilter(true)
    end

    local has_search = actions.search:match("%S") ~= nil
    local mode = actions.view_mode == "section" and "section" or "category"
    local entries = {}
    if has_search or actions.view_mode == "all" then
        local list_id = has_search and "search" or "all_actions"
        for index, item in ipairs(actions.filtered_items) do
            entries[#entries + 1] = {
                kind = "item",
                item = item,
                row_id = list_id .. "_" .. tostring(index)
                    .. "_" .. item.key,
            }
        end
    else
        for _, group in ipairs(GetActionBrowseGroups()) do
            entries[#entries + 1] = {kind = "group", group = group}
            if actions.open_group[mode] == group.id then
                local list_id = "group_" .. mode .. "_" .. group.id
                for index, item in ipairs(group.items) do
                    entries[#entries + 1] = {
                        kind = "item",
                        item = item,
                        group = group,
                        row_id = list_id .. "_" .. tostring(index)
                            .. "_" .. item.key,
                    }
                end
            end
        end
    end
    if #entries == 0 then return end

    local current_index
    for index, entry in ipairs(entries) do
        if entry.kind == "group"
            and actions.keyboard_cursor_kind == "group"
            and actions.keyboard_group == entry.group.id then
            current_index = index
            break
        elseif entry.kind == "item"
            and actions.keyboard_cursor_kind ~= "group"
            and actions.selected_keys[entry.item.key]
            and actions.selected_row_keys[entry.item.key] == entry.row_id then
            current_index = index
            break
        end
    end

    local function SelectEntry(entry)
        if not entry then return end
        if entry.kind == "group" then
            SetOnlyBrowserActionSelected(nil)
            actions.keyboard_cursor_kind = "group"
            actions.keyboard_group = entry.group.id
            actions.keyboard_scroll_group = entry.group.id
        else
            SetOnlyBrowserActionSelected(entry.item, entry.row_id)
            actions.keyboard_group = entry.group and entry.group.id or nil
            actions.keyboard_scroll_key = entry.row_id
        end
    end

    if move_down then
        SelectEntry(entries[math.min(#entries, (current_index or 0) + 1)])
        return
    elseif move_up then
        SelectEntry(entries[math.max(1,
            (current_index or (#entries + 1)) - 1)])
        return
    elseif move_right then
        local entry = current_index and entries[current_index] or nil
        if entry and entry.kind == "group" then
            if actions.open_group[mode] ~= entry.group.id then
                actions.open_group[mode] = entry.group.id
            elseif entries[current_index + 1]
                and entries[current_index + 1].kind == "item" then
                SelectEntry(entries[current_index + 1])
            end
        end
        return
    elseif move_left then
        local entry = current_index and entries[current_index] or nil
        if entry and entry.kind == "item" and entry.group then
            SelectEntry({kind = "group", group = entry.group})
        elseif entry and entry.kind == "group"
            and actions.open_group[mode] == entry.group.id then
            actions.open_group[mode] = nil
        end
        return
    elseif activate then
        local entry = current_index and entries[current_index] or nil
        if not entry then
            SelectEntry(entries[1])
        elseif entry.kind == "group" then
            actions.open_group[mode] =
                actions.open_group[mode] == entry.group.id
                    and nil or entry.group.id
        else
            ExecuteBrowserAction(entry.item)
        end
    end
end

function DrawActionsSortCombo()
    local actions = state.actions_browser
    local labels = {
        name_az = "Name A-Z",
        name_za = "Name Z-A",
        section = "Section",
        recent = "Recently Used",
        used = "Most Used",
    }
    if DrawFXToolbarIcon("sort", actions.sort_mode ~= "name_az",
        "Sort: " .. (labels[actions.sort_mode] or "Name A-Z")) then
        imgui.OpenPopup(ctx, "##actions_sort_popup")
    end
    if imgui.BeginPopup(ctx, "##actions_sort_popup") then
        for _, mode in ipairs({
            "name_az", "name_za", "section", "recent", "used"}) do
            local prefix = actions.sort_mode == mode and "\xe2\x9c\x93 " or ""
            if imgui.MenuItem(ctx, prefix .. labels[mode]) then
                actions.sort_mode = mode
                actions.view_cache_signature = nil
                UpdateActionsFilter(true)
                SaveActionsBrowserPreferences()
            end
        end
        imgui.EndPopup(ctx)
    end
end

function DrawActionsBrowser()
    local actions = state.actions_browser
    if actions.suppress_mouse_hover then
        local mouse_x, mouse_y = imgui.GetMousePos(ctx)
        local moved = math.abs(mouse_x
            - (actions.suppress_hover_mouse_x or mouse_x)) > 1
            or math.abs(mouse_y
                - (actions.suppress_hover_mouse_y or mouse_y)) > 1
        if moved or imgui.IsMouseClicked(ctx, 0)
            or imgui.IsMouseClicked(ctx, 1) then
            actions.suppress_mouse_hover = false
        end
    end
    actions.initialization_stage = actions.initialization_stage or 0
    if actions.initialization_stage == 0 then
        actions.initialization_stage = 1
        actions.status = "Preparing Actions browser..."
    elseif actions.initialization_stage == 1 then
        LoadActionsBrowserState()
        actions.initialization_stage = 2
        actions.status = "Loading cached actions..."
    elseif actions.initialization_stage == 2 and not actions.cache_attempted then
        actions.cache_attempted = true
        if not LoadActionsInventoryCache() then
            -- First launch (or a cleared cache) discovers automatically once.
            -- Later launches load the persisted inventory; only the toolbar
            -- Refresh button deliberately triggers another enumeration.
            StartActionsScan()
        end
        actions.initialization_stage = 3
    end
    if actions.initialization_stage >= 3 then UpdateActionsFilter(false) end

    local avail_w, avail_h = imgui.GetContentRegionAvail(ctx)
    local panel_bg = state.resolved_theme and state.resolved_theme.panel_bg
        or state.theme.colors.panel_bg
    local border = state.resolved_theme and state.resolved_theme.border
        or state.theme.colors.border
    imgui.PushStyleColor(ctx, imgui.Col_ChildBg, panel_bg)
    imgui.PushStyleColor(ctx, imgui.Col_Border, border)
    local visible = imgui.BeginChild(ctx, "##actions_browser",
        math.max(1, avail_w), math.max(180, avail_h), FLG_CHILD_BORDER)
    if visible then
        local toolbar_width = select(1, imgui.GetContentRegionAvail(ctx))
        imgui.SetNextItemWidth(ctx, math.max(80, toolbar_width - 42))
        if imgui.SetNextItemAllowOverlap then
            imgui.SetNextItemAllowOverlap(ctx)
        end
        local changed, value = imgui.InputTextWithHint(
            ctx, "##actions_search", "Search REAPER actions...", actions.search)
        if changed then
            actions.search = value
            actions.filter_due = r.time_precise() + 0.12
        end
        actions.search_active = imgui.IsItemActive(ctx)
        local clear_clicked = DrawSearchClearOverlay(
            "##clear_actions_search", actions.search ~= "")
        local clear_pressed = actions.search ~= ""
            and imgui.IsKeyPressed(ctx, imgui.Key_Escape, false)
        if clear_clicked or clear_pressed then
            ClearActionsSearch()
        end
        imgui.SameLine(ctx)
        local refresh = DrawFXToolbarIcon(
            "refresh", actions.scanning, "Refresh REAPER actions")
        if refresh and not actions.scanning then StartActionsScan() end

        if DrawFXToolbarIcon("action_all",
            actions.section_filter == "all", "All action sections") then
            actions.section_filter = "all"
            actions.view_cache_signature = nil
            UpdateActionsFilter(true)
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("action_main",
            actions.section_filter == 0, "Main actions") then
            actions.section_filter = 0
            actions.view_cache_signature = nil
            UpdateActionsFilter(true)
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("action_midi",
            actions.section_filter == 32060, "MIDI Editor actions") then
            actions.section_filter = 32060
            actions.view_cache_signature = nil
            UpdateActionsFilter(true)
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("action_event_list",
            actions.section_filter == 32061, "MIDI Event List actions") then
            actions.section_filter = 32061
            actions.view_cache_signature = nil
            UpdateActionsFilter(true)
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx, "|")
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("categories",
            actions.view_mode == "category", "Group actions by category") then
            actions.view_mode = "category"
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("vendors",
            actions.view_mode == "section", "Group actions by section") then
            actions.view_mode = "section"
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        if DrawFXToolbarIcon("all_plugins",
            actions.view_mode == "all", "Show all actions") then
            actions.view_mode = "all"
            SaveActionsBrowserPreferences()
        end
        imgui.SameLine(ctx)
        imgui.TextDisabled(ctx, "|")
        imgui.SameLine(ctx)
        DrawActionsSortCombo()
        imgui.Separator(ctx)

        local _, remaining_h = imgui.GetContentRegionAvail(ctx)
        local list_visible = imgui.BeginChild(ctx, "##actions_list", 0,
            math.max(80, remaining_h - 30), FLG_CHILD_BORDER)
        if list_visible then
            if actions.suppress_mouse_hover then
                imgui.PushStyleColor(
                    ctx, imgui.Col_HeaderHovered, 0x00000000)
            end
            local has_search = actions.search:match("%S") ~= nil
            if actions.scanning then
                imgui.TextDisabled(ctx, actions.status)
            elseif has_search then
                -- Keep Favorites visible as drop targets while filtering.
                DrawActionsLibraryRoots(true)
                imgui.Separator(ctx)
                imgui.Spacing(ctx)
                imgui.Text(ctx, "SEARCH RESULTS")
                imgui.Separator(ctx)
                DrawClippedActionList(actions.filtered_items, nil, "search")
            else
                DrawActionsLibraryRoots()
            end
            if actions.suppress_mouse_hover then imgui.PopStyleColor(ctx) end
            imgui.EndChild(ctx)
        end
        local selected_count = actions.selected_count or 0
        imgui.TextDisabled(ctx, selected_count > 0
            and string.format("%d selected  |  %s", selected_count, actions.status)
            or actions.status)
        imgui.EndChild(ctx)
    end
    imgui.PopStyleColor(ctx, 2)
    DrawActionsFolderDialog()
end

function DrawMainTabs()
    local header_color = state.theme.use_custom and state.theme.colors.header_icon
        or ((state.resolved_theme and state.resolved_theme.accent)
            or 0x4A88DFFF)
    local base_text = state.theme.use_custom and state.theme.colors.text
        or ((state.resolved_theme and state.resolved_theme.text)
            or 0xD0D0D0FF)
    local header_bg = state.theme.use_custom and state.theme.colors.window_bg
        or ((state.resolved_theme and state.resolved_theme.window_bg)
            or 0x2B2B2BFF)
    local inactive_text = BlendColor(base_text, header_bg, 0.48)
    local transparent = 0x00000000
    local navigation_width = select(1, imgui.GetContentRegionAvail(ctx))
    local settings_width = 28
    local settings_right_inset = 9
    local navigation_gap = 3
    local navigation_button_width = math.max(72, math.min(96, math.floor(
        (navigation_width - settings_width - settings_right_inset
            - navigation_gap * 3) / 3)))

    local function DrawNavigationButton(parts, id, tab, tooltip)
        local active = state.active_main_tab == tab
        imgui.PushStyleColor(ctx, imgui.Col_Text,
            active and header_color or inactive_text)
        imgui.PushStyleColor(ctx, imgui.Col_Button,
            active and ((header_color & 0xFFFFFF00) | 0x16) or transparent)
        imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered,
            (header_color & 0xFFFFFF00) | (active and 0x24 or 0x12))
        imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
            (header_color & 0xFFFFFF00) | 0x30)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FrameBorderSize, 0)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FrameRounding, 5)
        imgui.PushStyleVar(ctx, imgui.StyleVar_FramePadding, 8, 6)
        if imgui.Button(ctx, "##" .. id,
            navigation_button_width, 36) then
            state.active_main_tab = tab
        end
        local min_x, min_y = imgui.GetItemRectMin(ctx)
        local max_x, max_y = imgui.GetItemRectMax(ctx)
        -- Center each glyph group from measured parts and a fixed gap. Emoji
        -- advance widths differ by font/platform; centering a space-padded
        -- label made the three otherwise equal tabs look uneven.
        if state.star_font then imgui.PushFont(ctx, state.star_font) end
        local part_gap = 10
        local part_widths = {}
        local content_width = 0
        local content_height = 0
        for index, part in ipairs(parts) do
            local part_width, part_height = imgui.CalcTextSize(ctx, part)
            part_widths[index] = part_width
            content_width = content_width + part_width
            content_height = math.max(content_height, part_height)
        end
        content_width = content_width + part_gap * math.max(0, #parts - 1)
        local text_x = min_x + (max_x - min_x - content_width) * 0.5
        local text_y = min_y + (max_y - min_y - content_height) * 0.5
        local draw = imgui.GetWindowDrawList(ctx)
        local text_color = active and header_color or inactive_text
        for index, part in ipairs(parts) do
            imgui.DrawList_AddText(draw, text_x, text_y, text_color, part)
            text_x = text_x + part_widths[index] + part_gap
        end
        if state.star_font then imgui.PopFont(ctx) end
        if active then
            imgui.DrawList_AddRectFilled(
                imgui.GetWindowDrawList(ctx), min_x + 12, max_y - 2,
                max_x - 12, max_y, header_color, 1)
        end
        imgui.PopStyleVar(ctx, 3)
        imgui.PopStyleColor(ctx, 4)
        if imgui.IsItemHovered(ctx) then imgui.SetTooltip(ctx, tooltip) end
    end

    DrawNavigationButton({"\xe2\x99\xab", "\xf0\x9f\x93\x81"}, "media_nav",
        "media", "Media Browser")
    imgui.SameLine(ctx)
    DrawNavigationButton({"FX", "\xf0\x9f\x8e\xb9"}, "fx_nav",
        "fx", "FX + Instruments")
    imgui.SameLine(ctx)
    DrawNavigationButton({"\xf0\x9f\x8e\xac", "\xf0\x9f\x93\x9c"}, "actions_nav",
        "actions", "REAPER Actions")

    imgui.SameLine(ctx)
    local settings_cursor_x = imgui.GetCursorPosX(ctx)
    local settings_remaining_w = select(1, imgui.GetContentRegionAvail(ctx))
    if settings_remaining_w > settings_width + settings_right_inset then
        imgui.SetCursorPosX(ctx,
            settings_cursor_x + settings_remaining_w - settings_width
                - settings_right_inset)
    end
    -- The cog is an icon, not a framed button. Dummy supplies layout and a
    -- generous hit target without creating an active/captured ImGui button;
    -- hover color is the only interaction decoration.
    imgui.Dummy(ctx, settings_width, 36)
    local settings_hovered = imgui.IsItemHovered(ctx)
    if settings_hovered and imgui.IsMouseClicked(ctx, 0) then
        CancelPendingMediaRowActivation()
        state.show_settings = true
    end
    local settings_min_x, settings_min_y = imgui.GetItemRectMin(ctx)
    local settings_max_x, settings_max_y = imgui.GetItemRectMax(ctx)
    local settings_color = (settings_hovered and header_color or base_text)
        & 0xFFFFFF00 | (settings_hovered and 0xB0 or 0x68)
    local settings_cx = (settings_min_x + settings_max_x) * 0.5
    local settings_cy = (settings_min_y + settings_max_y) * 0.5
    local settings_draw = imgui.GetWindowDrawList(ctx)
    imgui.DrawList_AddCircle(
        settings_draw, settings_cx, settings_cy, 5.2,
        settings_color, 0, 1.15)
    imgui.DrawList_AddCircle(
        settings_draw, settings_cx, settings_cy, 1.7,
        settings_color, 0, 1.05)
    for spoke = 0, 7 do
        local angle = spoke * math.pi / 4
        imgui.DrawList_AddLine(settings_draw,
            settings_cx + math.cos(angle) * 6.7,
            settings_cy + math.sin(angle) * 6.7,
            settings_cx + math.cos(angle) * 8.2,
            settings_cy + math.sin(angle) * 8.2,
            settings_color, 1.05)
    end
    if settings_hovered then imgui.SetTooltip(ctx, "Settings") end

    DrawSettingsPopup()
    DrawRootLibraryRemovalConfirmation()
    imgui.Separator(ctx)

    if state.active_main_tab == "fx" then
        DrawFXBrowser()
        HandleFXTabKeys()
    elseif state.active_main_tab == "actions" then
        DrawActionsBrowser()
        HandleActionsTabKeys()
    else
        DrawTopBar()
        if not state.favorites_mode then
            DrawMediaTagEditor()
        end
        -- Keep the tag bar in the same fixed position in Favorites as in the
        -- Library. Its catalog is requested against the active Favorites
        -- scope, including the unscoped Favorites home.
        DrawMediaTagBar()
        local remaining_h = select(2, imgui.GetContentRegionAvail(ctx))
        local font_height = select(2, imgui.CalcTextSize(ctx, "Ag"))
        local original_preview_height = math.max(280, font_height * 6 + 145)
        local footer_height = GetMediaPreviewFooterHeight(font_height)
        -- Normalize to the expanded footer when choosing the canvas height.
        -- Collapsing the keyboard reduces only the footer reservation.
        local expanded_footer_height = footer_height
            + (state.piano_open and 0 or (state.preview_piano_height or 54))
        local original_canvas_height = math.max(40,
            original_preview_height - expanded_footer_height - 16)
        local preview_height = footer_height + 16 + math.max(40, original_canvas_height * 2 / 3)
        local browser_height = math.max(80, remaining_h - preview_height - 4)
        DrawAccordionBrowser(browser_height)
        DrawMIDIPreview()
    end
end

function FlushCanonicalUserDataOnCleanup()
    local database = state.database
    local user_data = state.canonical_user_data
    if not database or not user_data or not database.canonical then return end
    -- Normal window closes get a short opportunity to observe the detached
    -- writer's acknowledgement and preserve ordering before a quick relaunch.
    -- The journal remains the fallback for a timeout or abnormal termination.
    local deadline = r.time_precise() + 1.0
    while r.time_precise() < deadline do
        if database.write_active then
            if database.write_pending_kind ~= "canonical_user_data" then break end
            ProcessMediaDatabase()
        elseif CanonicalUserDataQueueCount(user_data) > 0 then
            local started = StartCanonicalUserDataWrite()
            if not started then break end
        else
            break
        end
    end
end

function InitializeEULAAcceptance()
    local eula = state.eula
    local accepted_version = tonumber(
        r.GetExtState(EXT_SECTION, "eula_accepted_version")) or 0
    eula.accepted = accepted_version >= REABROWSE_EULA_VERSION
    eula.required = not eula.accepted
    eula.checkbox = false
    eula.popup_requested = false
    eula.text = nil
    eula.error = nil
    eula.notice = nil
    eula.declined = false
end

function LoadEULAText()
    local eula = state.eula
    if eula.text then return eula.text end
    local path = GetScriptDirectory():gsub("[/\\]+$", "") .. "/EULA.md"
    local file, open_error = io.open(path, "rb")
    if not file then
        eula.error = "EULA.md is missing from the ReaBrowse installation: "
            .. tostring(open_error or path)
        return nil
    end
    local text = file:read("*a") or ""
    file:close()
    if text == "" then
        eula.error = "EULA.md is empty. Reinstall ReaBrowse before continuing."
        return nil
    end
    eula.text = text
    eula.error = nil
    return text
end

function OpenEULAFile()
    local path = GetScriptDirectory():gsub("[/\\]+$", "") .. "/EULA.md"
    if not FileExists(path) then return false end
    if r.CF_ShellExecute then
        local ok, result = pcall(r.CF_ShellExecute, path)
        if ok and result then return true end
    end
    return false
end

function AcceptCurrentEULA()
    r.SetExtState(EXT_SECTION, "eula_accepted_version",
        tostring(REABROWSE_EULA_VERSION), true)
    r.SetExtState(EXT_SECTION, "eula_accepted_at",
        tostring(os.time()), true)
    local saved = tonumber(
        r.GetExtState(EXT_SECTION, "eula_accepted_version")) or 0
    if saved < REABROWSE_EULA_VERSION then
        state.eula.error =
            "REAPER could not save your acceptance. Check that REAPER's settings are writable."
        return false
    end
    state.eula.accepted = true
    state.eula.required = false
    state.eula.popup_requested = false
    state.lazy_init_frame = 0
    state.lazy_init_pending = true
    return true
end

function RenderEULADocument(markdown)
    local blocks = {}
    local current = nil
    local function Clean(value)
        local cleaned = tostring(value or "")
        cleaned = cleaned:gsub("%*%*", "")
        cleaned = cleaned:gsub("`([^`]*)`", "%1")
        cleaned = cleaned:gsub("^%s+", "")
        cleaned = cleaned:gsub("%s+$", "")
        return cleaned
    end
    local function Flush()
        if current and current.text ~= "" then
            current.text = Clean(current.text)
            blocks[#blocks + 1] = current
        end
        current = nil
    end
    local normalized = tostring(markdown or ""):gsub("\r", "")
    for line in (normalized .. "\n"):gmatch("(.-)\n") do
        local heading = line:match("^##%s+(.+)$")
        local title = line:match("^#%s+(.+)$")
        local bullet = line:match("^%-%s+(.+)$")
        if line:match("^%s*$") then
            Flush()
        elseif heading then
            Flush()
            blocks[#blocks + 1] = {kind = "heading", text = Clean(heading)}
        elseif title then
            Flush()
            blocks[#blocks + 1] = {kind = "title", text = Clean(title)}
        elseif bullet then
            Flush()
            current = {kind = "bullet", text = bullet}
        else
            local trimmed = Clean(line)
            if not current then
                current = {
                    kind = trimmed:match("^TO THE MAXIMUM EXTENT")
                        and "disclaimer" or "paragraph",
                    text = trimmed,
                }
            elseif trimmed ~= "" then
                current.text = current.text .. " " .. trimmed
            end
        end
    end
    Flush()

    local accent = state.resolved_theme and state.resolved_theme.accent
        or state.theme.colors.accent
    for _, block in ipairs(blocks) do
        if block.kind == "title" then
            -- The window already carries the document title and version.
        elseif block.kind == "heading" then
            imgui.Spacing(ctx)
            imgui.PushStyleColor(ctx, imgui.Col_Text, accent)
            imgui.TextWrapped(ctx, block.text)
            imgui.PopStyleColor(ctx)
            imgui.Separator(ctx)
        elseif block.kind == "bullet" then
            imgui.Indent(ctx, 10)
            imgui.TextWrapped(ctx, "•  " .. block.text)
            imgui.Unindent(ctx, 10)
        elseif block.kind == "disclaimer" then
            imgui.PushStyleColor(ctx, imgui.Col_Text, accent)
            imgui.TextWrapped(ctx, block.text)
            imgui.PopStyleColor(ctx)
            imgui.Spacing(ctx)
        else
            imgui.TextWrapped(ctx, block.text)
            imgui.Spacing(ctx)
        end
    end
end

function DrawEULAAcceptance()
    local eula = state.eula
    local accent = state.resolved_theme and state.resolved_theme.accent
        or state.theme.colors.accent
    imgui.PushStyleColor(ctx, imgui.Col_Text, accent)
    imgui.Text(ctx, "REABROWSE")
    imgui.PopStyleColor(ctx)
    imgui.Text(ctx, "End User License Agreement")
    imgui.SameLine(ctx)
    imgui.TextDisabled(ctx, "Version " .. tostring(REABROWSE_EULA_VERSION))
    imgui.TextWrapped(ctx,
        "Please review these terms. ReaBrowse will initialize only after you explicitly agree.")
    imgui.Separator(ctx)

    local text = LoadEULAText()
    local _, available_height = imgui.GetContentRegionAvail(ctx)
    local agreement_height = math.max(220, available_height - 155)
    local panel_bg = state.resolved_theme and state.resolved_theme.panel_bg
        or state.theme.colors.panel_bg
    local border = state.resolved_theme and state.resolved_theme.border
        or state.theme.colors.border
    imgui.PushStyleColor(ctx, imgui.Col_ChildBg, panel_bg)
    imgui.PushStyleColor(ctx, imgui.Col_Border, border)
    local text_visible = imgui.BeginChild(
        ctx, "##eula_text", 0, agreement_height, FLG_CHILD_BORDER)
    if text_visible then
        if text then
            RenderEULADocument(text)
        else
            imgui.TextWrapped(ctx, eula.error or "The agreement could not be loaded.")
        end
        imgui.EndChild(ctx)
    end
    imgui.PopStyleColor(ctx, 2)
    imgui.Spacing(ctx)

    if imgui.Button(ctx, "Open EULA file", 130, 0) then
        if not OpenEULAFile() then
            eula.notice = "Could not open the system viewer; the complete agreement is displayed above."
        else
            eula.notice = nil
        end
    end
    imgui.Spacing(ctx)
    local changed, checked = imgui.Checkbox(
        ctx, "##eula_accept", eula.checkbox)
    if changed then eula.checkbox = checked end
    imgui.SameLine(ctx)
    imgui.TextWrapped(ctx, "I have read and agree to the ReaBrowse EULA.")

    if eula.error then
        imgui.TextWrapped(ctx, eula.error)
    elseif eula.notice then
        imgui.TextWrapped(ctx, eula.notice)
    end
    imgui.TextDisabled(ctx,
        "Clicking Agree and Continue records your acceptance on this REAPER installation.")
    local footer_width = select(1, imgui.GetContentRegionAvail(ctx))
    local button_gap = 8
    local button_width = math.max(120, (footer_width - button_gap) * 0.5)
    local agree_blocked = not eula.checkbox or not text or eula.error ~= nil
    local selected_text = state.resolved_theme
        and state.resolved_theme.selected_text
        or state.theme.colors.selected_text
    imgui.PushStyleColor(ctx, imgui.Col_Text, selected_text)
    imgui.PushStyleColor(ctx, imgui.Col_Button,
        (accent & 0xFFFFFF00) | 0xC8)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonHovered, accent)
    imgui.PushStyleColor(ctx, imgui.Col_ButtonActive,
        (accent & 0xFFFFFF00) | 0xE0)
    if agree_blocked and imgui.BeginDisabled then
        imgui.BeginDisabled(ctx, true)
    end
    local agree = imgui.Button(ctx, "Agree and Continue", button_width, 0)
    if agree_blocked and imgui.EndDisabled then imgui.EndDisabled(ctx) end
    imgui.PopStyleColor(ctx, 4)
    if agree and not agree_blocked then AcceptCurrentEULA() end
    imgui.SameLine(ctx)
    if imgui.Button(ctx, "Decline and Close", button_width, 0) then
        eula.declined = true
    end
end

function Cleanup()
    if cleanup_done then return end
    cleanup_done = true
    if state.eula and state.eula.required
        and not state.eula.accepted then
        return
    end
    if SaveActionsUsage then SaveActionsUsage(true) end
    if state.actions_browser.cache_upgrade_pending
        and #state.actions_browser.items > 0 then
        SaveActionsInventoryCache()
    end
    if type(r.ReaBrowse_CancelNativeWaveform) == "function" then
        r.ReaBrowse_CancelNativeWaveform()
    end
    StopPreview()
    ReleaseLoadedAudioSource()
    if type(r.ReaBrowse_ClearPreparedNativePreviewSource) == "function" then
        r.ReaBrowse_ClearPreparedNativePreviewSource()
    end
    if state.library_scan and state.library_scan.scanning
        and state.library_scan.phase ~= "commit"
        and state.library_scan.phase ~= "finalize_db"
        and FinishCanonicalScanManifest then
        local newly_added_root = state.library_scan.newly_added_root
        FinishCanonicalScanManifest(true)
        if newly_added_root
            and RemoveConfiguredRootValue(newly_added_root) then
            SaveSettings()
        end
    end
    -- Complete an in-progress cache replacement before shutdown. The old
    -- cache remains valid until the final rename, so this prevents a completed
    -- scan from being repeated merely because the browser closed immediately.
    while state.library_cache_save
        and state.library_cache_save.active
        and state.library_cache_save.file do
        ProcessLibraryCacheSave()
    end
    if state.library_cache_save then
        state.library_cache_save.active = false
    end
    FlushCanonicalUserDataOnCleanup()
    PersistCanonicalUserDataJournal()
    CloseMediaDatabase()
end

function Loop()
    state.ui_frame_index = (state.ui_frame_index or 0) + 1
    -- Loop itself is scheduled with reaper.defer, so bridge acknowledgement
    -- polling remains asynchronous and never blocks REAPER's UI thread.
    PollReaDrumBridgeAcknowledgement()
    PublishWorkerOwnerHeartbeat()
    -- A persistent worker only removes process/SQLite startup. Consume an
    -- already-published page before ImGui builds the folder tree, otherwise
    -- the response waits until the end of this defer cycle and cannot become
    -- visible until yet another frame.
    ConsumeReadyCanonicalPageBeforeDraw()
    if state.lazy_init_pending and not state.eula.required then
        state.lazy_init_frame = (state.lazy_init_frame or 0) + 1
        if state.lazy_init_frame >= 2 then
            LazyPostWindowInit()
        end
    end
    if state.needs_refresh then
        StartLibraryScan(
            state.pending_scan_root, state.pending_scan_root_is_new)
        state.pending_scan_root = nil
        state.pending_scan_root_is_new = false
        state.needs_refresh = false
    end
    if state.media_kind == "audio" and not state.audio_peaks
        and state.audio_waveform_native_pending
        and state.audio_waveform_native_path == state.source_file
        and r.time_precise() >= state.audio_waveform_poll_at then
        local now = r.time_precise()
        local native_status
        if not state.audio_waveform_native_generation then
            local generation = r.ReaBrowse_RequestNativeWaveform(
                state.source_file)
            if generation and generation > 0 then
                state.audio_waveform_native_generation = generation
                state.audio_waveform_poll_at = now + 0.03
                native_status = 0
            else
                native_status = -1
            end
        else
            native_status = r.ReaBrowse_PollNativeWaveform(
                state.audio_waveform_native_generation)
        end
        if native_status == 1 then
            local completed_source = r.PCM_Source_CreateFromFileEx(
                state.source_file, true)
            if completed_source then
                state.audio_peaks = BuildAudioWaveform(completed_source)
                r.PCM_Source_Destroy(completed_source)
            end
            state.audio_waveform_native_generation = nil
            state.audio_waveform_native_path = nil
            state.audio_waveform_native_pending = false
            if state.audio_peaks then
                CacheAudioWaveform(state.source_file, state.audio_peaks)
                state.preview_setup_message = nil
            end
        elseif native_status and native_status < 0 then
            state.audio_waveform_native_generation = nil
            state.audio_waveform_native_path = nil
            state.audio_waveform_native_pending = false
        else
            -- Thirty-three polls/second is visually immediate while avoiding
            -- per-frame extension calls on high-refresh displays.
            state.audio_waveform_poll_at = now + 0.03
        end
    end
    local pending_restart_at = state.pending_control_transport_restart_at
    if pending_restart_at and r.time_precise() >= pending_restart_at then
        state.pending_control_transport_restart_at = nil
        StartPreview()
    end
    local transport_running = (r.GetPlayState() & 1) ~= 0
    local transport_started =
        not state.last_transport_running and transport_running
    if transport_started and state.is_playing
        and ((state.media_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().sync)
            or (state.media_kind == "midi"
                and PreviewFollowsArrangement()
                and MIDITransportModeApplies())) then
        -- A free-running preview that began while REAPER was stopped has no
        -- common phase reference. Recreate it at the arrangement phase. MIDI
        -- also switches from its exact authored endpoint to the bar-aligned
        -- arrangement cycle here.
        StartPreview()
    elseif state.last_transport_running
        and not transport_running
        and state.is_playing then
        local sync_active = PreviewFollowsArrangement()
            or PreviewControlsTransport()
        if state.media_kind == "audio" then
            local policy = GetCurrentAudioPlaybackPolicy()
            sync_active = policy.sync or policy.link_transport
        elseif state.media_kind == "midi" and state.current_file_is_one_shot
            and state.one_shot_bypass.sync then
            sync_active = false
        end
        if sync_active then StopPreview(true) end
    end
    if transport_running and state.is_playing
        and PreviewUsesArrangementClock() then
        local now = r.time_precise()
        local transport_position = (r.GetPlayPosition2
            and r.GetPlayPosition2()) or r.GetPlayPosition()
        local last_position = state.last_sync_transport_position
        local last_wall = state.last_sync_wall_time
        local discontinuity = last_position and last_wall
            and math.abs((transport_position - last_position)
                - (now - last_wall)) > 0.10
        local tempo = r.Master_GetTempo()
        local tempo_changed = state.last_sync_tempo
            and math.abs(tempo - state.last_sync_tempo) > 0.0001
        local post_start_sync = state.media_kind == "audio"
            and (state.pending_audio_phase_sync_frames or 0) > 0
        if post_start_sync then
            state.pending_audio_phase_sync_frames =
                state.pending_audio_phase_sync_frames - 1
            post_start_sync = state.pending_audio_phase_sync_frames == 0
        end
        if state.media_kind == "audio"
            and (discontinuity or tempo_changed or post_start_sync) then
            if tempo_changed and state.native_preview_kind == "audio"
                and GetCurrentAudioPlaybackPolicy().tempo_match then
                -- A unity native preview may need to become a transformed
                -- preview when the tempo map changes beneath it.
                StartPreview()
            elseif discontinuity or post_start_sync then
                ResyncAudioPreviewToArrangement()
            end
            -- Native arrangement playback is already phase-locked inside the
            -- DLL. Writing preview curpos from this GUI heuristic can interrupt
            -- the host preview when an ordinary delayed UI frame resembles a
            -- transport discontinuity.
        end
        state.last_sync_transport_position = transport_position
        state.last_sync_wall_time = now
        state.last_sync_tempo = tempo
    else
        state.last_sync_transport_position = nil
        state.last_sync_wall_time = nil
        state.last_sync_tempo = nil
        if not transport_running then
            state.pending_audio_phase_sync_frames = 0
        end
    end
    state.last_transport_running = transport_running
    if not transport_running then
        state.last_stopped_transport_position = r.GetCursorPosition()
    end

    if state.is_playing and state.media_kind == "audio" then
        local policy = GetCurrentAudioPlaybackPolicy()
        if not state.audio_preview then
            state.is_playing = false
        elseif not policy.loop
            and state.audio_preview_expected_end
            and r.time_precise() >= state.audio_preview_expected_end then
            if HasPotentiallyProvisionalPreviewLength(state.source_file) then
                -- Compressed decoders can initially report a provisional
                -- duration (commonly one second). Never stop REAPER's native
                -- preview from that estimate. Treat it only as the point to
                -- begin watching the native cursor for a stable EOF.
                local now = r.time_precise()
                local position = GetPreviewPosition()
                local previous = state.audio_preview_eof_watch_position
                local watch_time = state.audio_preview_eof_watch_time
                if previous and watch_time
                    and math.abs(position - previous) < 0.001
                    and now - watch_time >= 1.25 then
                    StopPreview()
                else
                    if not previous
                        or math.abs(position - previous) >= 0.001 then
                        state.audio_preview_eof_watch_position = position
                        state.audio_preview_eof_watch_time = now
                    end
                    state.audio_preview_expected_end = now + 0.25
                end
            else
                StopPreview()
            end
        end
    end

    EnsureFontUpToDate()
    if state.eula.required then
        imgui.SetNextWindowSize(ctx, 760, 700, imgui.Cond_Appearing)
    else
        imgui.SetNextWindowSize(ctx, 360, 700, imgui.Cond_FirstUseEver)
    end
    PushREAPERTheme()
    if state.font then imgui.PushFont(ctx, state.font) end

    local visible, open = imgui.Begin(ctx, "ReaBrowse", true, imgui.WindowFlags_NoCollapse)
    if visible then
        state.favorite_collection_drop_id = nil
        state.favorite_collection_drop_rects =
            state.favorite_collection_drop_rects or {}
        state.favorite_root_drop_hovered = false
        if state.eula.required then
            DrawEULAAcceptance()
        else
            DrawMainTabs()
        end
        -- Capture bounds now, while this is still the current ImGui window.
        -- (GetWindowPos/GetWindowSize are meaningless once End() has been called
        -- or another window/tooltip has become current -- that mismatch was why
        -- drops never registered.)
        state.win_x, state.win_y = imgui.GetWindowPos(ctx)
        state.win_w, state.win_h = imgui.GetWindowSize(ctx)
        imgui.End(ctx)
    end

    DrawFavoriteFolderDialog()
    ProcessPendingMediaCtrlClick()
    ProcessPendingFXCtrlClick()
    ProcessPendingActionsCtrlClick()
    ProcessFXDrag()
    ProcessActionsFavoriteDrag()

    if not state.drag_active and not imgui.IsMouseDown(ctx, 0) then
        state.favorite_drag_pending_path = nil
        state.favorite_drag_pending_copy = false
        state.favorite_heart_press_path = nil
    end

    if state.pending_single_node and not state.drag_active and not imgui.IsMouseDown(ctx, 0) then
        local node = state.pending_single_node
        state.pending_single_node = nil
        local row_key = state.pending_single_row_key
        state.pending_single_row_key = nil
        state.multi_selected = {[node.path] = true}
        state.selected_file_row_keys = {
            [node.path] = row_key
        }
        state.selection_anchor = node.path
        state.selection_anchor_row_key = row_key
        SetCursorToFileNode(node, false, row_key)
    end
    
    -- === DRAG AND DROP OUT LISTENER ===
    if state.drag_active then
        if state.drag_kind == "file" or state.drag_kind == "folder" then
            -- Copy versus move is decided when the mouse is released, so Ctrl
            -- can be pressed or released at any point during the drag.
            state.favorite_drag_copy =
                select(1, GetSelectionModifiers()) == true
        end
        RefreshNativeCompanionAvailability()
        local rx, ry = imgui.GetMousePos(ctx)
        local is_outside = (rx < state.win_x or rx > state.win_x + state.win_w
                          or ry < state.win_y or ry > state.win_y + state.win_h)
        local native_drag_handled = false

        -- Live drop-position marker: while hovering the arrange view, move the
        -- edit cursor (REAPER draws it as a vertical line) to the snapped
        -- position the file would land on if dropped right now. If the mouse
        -- isn't over a recognizable arrange position, preview the timeline-
        -- start fallback instead.
        local hover_window, hover_track = nil, nil
        if is_outside and state.drag_kind == "file" then
            local window, track, snapped_pos = GetArrangeHoverTarget()
            hover_window = window
            hover_track = track
            local preview_pos = window == "arrange"
                and (snapped_pos or 0)
                or state.drag_orig_cursor_pos
            if window == "arrange" then
                r.SetEditCurPos(preview_pos, false, false)
                r.UpdateArrange()
            end
            state.drag_last_track = track
            state.drag_last_pos = preview_pos
            -- Empty TCP space is a deliberate new-track destination just like
            -- empty arrange space; never replace it with the selected track.
            state.drag_hover_arrange =
                window == "arrange" or window == "tcp"
        end

        -- The mouse-down policy owns the full gesture. Internal Favorites
        -- handling stays custom; native mode hands off only outside the browser.
        if is_outside and state.drag_kind == "file"
            and state.native_drag_alt_latched then
            if not state.favorite_drop_hovered
                and state.native_drag_available then
                native_drag_handled = StartNativeExternalFileDrag(
                    state.drag_paths or GetSelectedFilePaths(state.drag_path))
                if native_drag_handled then
                    state.file_drag_handed_off = true
                    state.drag_active = false
                    r.SetEditCurPos(state.drag_orig_cursor_pos, false, false)
                    state.favorite_drag_copy = false
                    state.favorite_drag_source_collection_id = nil
                    state.favorite_drag_source_kind = nil
                    state.drag_path = nil
                    state.drag_kind = "file"
                    state.drag_last_pos = nil
                    state.drag_hover_arrange = false
                    state.native_drag_alt_latched = false
                    state.drag_paths = nil
                    state.pending_file_drag_paths = nil
                end
            end
        end

        if not native_drag_handled and state.drag_kind == "file"
            and not state.favorite_drop_hovered
            and not state.favorite_collection_drop_id
            and not state.favorite_root_drop_hovered
            and imgui.BeginTooltip(ctx) then
            if state.native_drag_alt_latched then
                imgui.Text(ctx, state.native_drag_available
                    and "Sampler/script drop armed"
                    or "Sampler/script drop unavailable")
            else
                imgui.Text(ctx, "Transformed timeline drag")
            end
            imgui.TextDisabled(ctx, GetFileName(state.drag_path))
            if state.native_drag_alt_latched then
                imgui.TextDisabled(ctx, "Drag to the destination pad")
            elseif is_outside
                and hover_window ~= "arrange" and hover_window ~= "tcp" then
                imgui.TextDisabled(ctx, "Sampler/script drop:")
                imgui.TextDisabled(ctx,
                    "Release, then start again with the opposite Alt state")
            else
                imgui.TextDisabled(ctx,
                    "Alt at mouse-down selects the opposite drag type")
            end
            if is_outside and state.drag_kind == "file" then
                if hover_track then
                    local _, tname = r.GetTrackName(hover_track)
                    imgui.TextDisabled(ctx, "→ " .. (tname or "Track"))
                elseif hover_window == "arrange"
                    or hover_window == "tcp" then
                    imgui.TextDisabled(ctx, "→ New track")
                end
            end
            imgui.EndTooltip(ctx)
        end

        if not native_drag_handled and not imgui.IsMouseDown(ctx, 0) then
            state.drag_active = false

            if not state.favorite_collection_drop_id
                and (state.drag_kind == "file"
                    or state.drag_kind == "folder"
                    or state.drag_kind == "favorite_collection") then
                local mouse_x, mouse_y = imgui.GetMousePos(ctx)
                for collection_id, rect in pairs(
                    state.favorite_collection_drop_rects or {}) do
                    if rect[5] == state.ui_frame_index
                        and mouse_x >= rect[1] and mouse_x <= rect[3]
                        and mouse_y >= rect[2] and mouse_y <= rect[4]
                        and (state.drag_kind ~= "favorite_collection"
                            or CanReparentFavoriteCollection(
                                state.favorite_drag_source_collection_id,
                                collection_id)) then
                        state.favorite_collection_drop_id = collection_id
                        break
                    end
                end
            end
            if state.drag_kind == "favorite_collection" then
                local target_id = state.favorite_collection_drop_id
                local move_to_root = state.favorite_root_drop_hovered
                    and state.favorites_mode
                if target_id then
                    ReparentFavoriteCollection(
                        state.favorite_drag_source_collection_id, target_id)
                elseif move_to_root then
                    ReparentFavoriteCollection(
                        state.favorite_drag_source_collection_id, nil)
                end
                r.SetEditCurPos(
                    state.drag_orig_cursor_pos, false, false)
            elseif state.favorite_collection_drop_id then
                local copy_to_folder = state.favorite_drag_copy
                local favorite_kind = state.drag_kind == "folder"
                    and "folder" or "file"
                local selected_paths = state.drag_kind == "folder"
                    and {state.drag_path}
                    or GetSelectedFilePaths(state.drag_path)
                ApplyFavoritePathsToCollection(
                    selected_paths, state.favorite_collection_drop_id,
                    favorite_kind, state.favorite_drag_source_kind,
                    state.favorite_drag_source_collection_id, copy_to_folder)
                r.SetEditCurPos(state.drag_orig_cursor_pos, false, false)
            elseif state.favorite_root_drop_hovered
                and state.favorites_mode
                and (state.drag_kind == "file"
                    or state.drag_kind == "folder") then
                local root_paths = state.drag_kind == "folder"
                    and {state.drag_path}
                    or GetSelectedFilePaths(state.drag_path)
                ApplyFavoritePathsToRoot(
                    root_paths,
                    state.drag_kind == "folder" and "folder" or "file",
                    state.favorite_drag_source_kind,
                    state.favorite_drag_source_collection_id,
                    state.favorite_drag_copy)
                r.SetEditCurPos(state.drag_orig_cursor_pos, false, false)
            elseif state.favorite_drop_hovered then
                if state.favorites_mode
                    and (state.drag_kind == "file"
                        or state.drag_kind == "folder") then
                    local root_paths = state.drag_kind == "folder"
                        and {state.drag_path}
                        or GetSelectedFilePaths(state.drag_path)
                    ApplyFavoritePathsToRoot(
                        root_paths,
                        state.drag_kind == "folder" and "folder" or "file",
                        state.favorite_drag_source_kind,
                        state.favorite_drag_source_collection_id,
                        state.favorite_drag_copy)
                elseif state.drag_kind == "file" then
                    SetFavoritePaths(
                        GetSelectedFilePaths(state.drag_path), true, "file")
                else
                    SetFavoritePaths(
                        {state.drag_path}, true, state.drag_kind or "folder")
                end
                r.SetEditCurPos(state.drag_orig_cursor_pos, false, false)
            elseif is_outside and state.drag_kind == "file" then
                local paths = state.drag_paths or GetSelectedFilePaths(state.drag_path)
                if state.drag_hover_arrange and not state.native_drag_alt_latched then
                    InsertFilesOnConsecutiveTracks(
                        paths,
                        state.drag_last_track,
                        state.drag_last_pos or 0,
                        false
                    )
                else
                    -- Unknown external windows and the narrow arrange/TCP
                    -- divider must never fall back to the selected track.
                    r.SetEditCurPos(
                        state.drag_orig_cursor_pos, false, false)
                end
            else
                -- Drag was cancelled (released back over the browser) --
                -- put the edit cursor back where it started.
                r.SetEditCurPos(state.drag_orig_cursor_pos, false, false)
            end
            state.favorite_drop_hovered = false
            state.favorite_collection_drop_id = nil
            state.favorite_root_drop_hovered = false
            state.favorite_drag_copy = false
            state.favorite_drag_source_collection_id = nil
            state.favorite_drag_source_kind = nil
            state.drag_path = nil
            state.drag_kind = "file"
            state.drag_last_pos = nil
            state.drag_hover_arrange = false
            state.native_drag_alt_latched = false
            state.drag_paths = nil
            state.pending_file_drag_paths = nil
        end
    end

    -- Input, navigation and preview triggering above own the front of every
    -- UI frame. Run bounded maintenance afterward so filesystem/database work
    -- cannot delay a key press that arrived for this frame.
    ProcessLibraryScan()
    ProcessLibraryCacheSave()
    ProcessMediaFilterIndexBuild()
    ProcessFolderTagFacetBuild()
    ProcessMediaDatabase()
    ProcessFXScan()
    if state.active_main_tab == "actions" then ProcessActionsScan() end
    SaveActionsUsage(false)
    ProcessInsertedItemPeakBuild()

    if state.font then imgui.PopFont(ctx) end
    PopREAPERTheme()
    FlushPendingFontSize()

    if state.eula.declined then open = false end
    if open then r.defer(Loop) else
        Cleanup()
        return
    end
end

-- ============================================================
-- INITIALIZATION
-- ============================================================
function Init()
    math.randomseed(os.time())
    r.atexit(Cleanup)
    state.last_transport_running = (r.GetPlayState() & 1) ~= 0
    state.last_stopped_transport_position = r.GetCursorPosition()
    LoadSettings()
    InitializeEULAAcceptance()
    RebuildFont()
    state.lazy_init_pending = true
    Loop()
end

function LazyPostWindowInit()
    state.lazy_init_pending = false
    EnsureReaBrowseDataLayout()
    CleanupStaleScanManifests()
    InitializeMediaDatabase()
    local database = state.database
    if database.pending_init then
        database.pending_init = false
        local existing_version, version_error = QueryDatabaseScalar(
            "PRAGMA user_version;")
        local numeric_version = tonumber(existing_version or "") or 0
        if existing_version == nil then
            database.error = tostring(version_error)
            database.status = "Could not inspect ReaBrowse database"
            database.rebuild_required = true
            return
        end
        if numeric_version ~= 0 and numeric_version ~= DATABASE_SCHEMA_VERSION then
            database.error = string.format(
                "ReaBrowse schema v%d cannot be reused by v%d. Delete the generated library database in Settings, then add/update folders to build v%d.",
                numeric_version, DATABASE_SCHEMA_VERSION,
                DATABASE_SCHEMA_VERSION)
            database.status = "Schema v5 clean rebuild required"
            database.rebuild_required = true
            return
        end
        if numeric_version == DATABASE_SCHEMA_VERSION then
            local identity, identity_error = QueryDatabaseScalar(
                "SELECT COALESCE((SELECT value FROM app_meta WHERE "
                    .. "key='database_identity'),'')||'|'||(SELECT count(*) "
                    .. "FROM sqlite_schema WHERE type='table' AND name IN("
                    .. "'app_meta','roots','folders','files','folder_files',"
                    .. "'folder_closure','file_search','user_file_data',"
                    .. "'collections','collection_items'));" )
            if identity ~= "ReaBrowseCanonical|10" then
                database.error = identity_error or
                    "Database identity or required v5 tables are missing."
                database.status = "Invalid ReaBrowse database; clean rebuild required"
                database.rebuild_required = true
                return
            end
        end
        local ok, schema_error = true, nil
        if numeric_version == 0 then
            local canonical_schema, schema_load_error = LoadReaBrowseSchemaSQL()
            if not canonical_schema then
                database.error = tostring(schema_load_error)
                database.status = "Canonical schema unavailable"
                return
            end
            ok, schema_error = WriteDatabaseBatch(
                canonical_schema .. "\nPRAGMA user_version="
                    .. tostring(DATABASE_SCHEMA_VERSION) .. ";\n"
                    .. "INSERT INTO app_meta(key,value) VALUES('database_identity','ReaBrowseCanonical') "
                    .. "ON CONFLICT(key) DO UPDATE SET value=excluded.value;\n")
        else
            -- Additive v5 maintenance: older v5 databases predate the
            -- sparse smart-view and collection paging indexes.
            ok, schema_error = WriteDatabaseBatch(
                "CREATE INDEX IF NOT EXISTS idx_collection_items_folder "
                    .. "ON collection_items(folder_id, collection_id);\n"
                    .. "CREATE INDEX IF NOT EXISTS idx_user_file_favorite "
                    .. "ON user_file_data(favorite,updated_at DESC,file_id);\n"
                    .. "CREATE INDEX IF NOT EXISTS "
                    .. "idx_collection_items_collection_added ON "
                    .. "collection_items(collection_id,added_at,file_id,folder_id);\n"
                    .. "CREATE TABLE IF NOT EXISTS key_overrides("
                    .. "path_norm TEXT PRIMARY KEY,key_pc INTEGER CHECK("
                    .. "key_pc IS NULL OR key_pc BETWEEN 0 AND 11),"
                    .. "detected_key_pc INTEGER CHECK(detected_key_pc IS NULL OR "
                    .. "detected_key_pc BETWEEN 0 AND 11),created_at INTEGER NOT NULL,"
                    .. "updated_at INTEGER NOT NULL) WITHOUT ROWID;\n")
        end
        if ok then
            local readiness, query_error = QueryDatabaseScalar(
                "SELECT COALESCE(MAX(CASE WHEN key='completed_scan_generation' "
                    .. "THEN CAST(value AS INTEGER) END),0)||'|'||"
                    .. "COALESCE(MAX(CASE WHEN key='folder_tag_counts_ready' "
                    .. "THEN value END),'0')||'|'||"
                    .. "COALESCE(MAX(CASE WHEN key='file_search_ready_v1' "
                    .. "THEN value END),'0')||'|'||"
                    .. "COALESCE(MAX(CASE WHEN key='library_file_count' "
                    .. "THEN value END),CAST((SELECT COALESCE(MAX(id),0) "
                    .. "FROM files) AS TEXT)) FROM app_meta;")
            if readiness ~= nil then
                local generation, facet_ready, search_ready, library_file_count =
                    tostring(readiness):match(
                        "^(%-?%d+)|([^|]+)|([^|]+)|([^|]*)$")
                database.backend = "sqlite"
                database.canonical = true
                database.capabilities = {
                    canonical_queries = true,
                    paged_browser = true,
                    keyset_paging = true,
                    materialized_folder_scope = true,
                    precomputed_tag_catalogs = true,
                    database_random = true,
                    background_scan_commit = true,
                }
                database.status = "Database ready"
                database.schema_version = DATABASE_SCHEMA_VERSION
                database.generation = tonumber(generation) or 0
                database.folder_tag_counts_ready = facet_ready == "1"
                database.file_search_ready = search_ready ~= "0"
                database.library_file_count = tonumber(library_file_count)
            else
                database.error = tostring(query_error)
            end
        else
            database.error = tostring(schema_error)
        end
    end
    LoadCanonicalUserDataJournal()
    ReplayRecoveredFavoritesBeforeLoad()
    LoadFavorites()
    state.database_startup_test.enabled = state.database.backend == "sqlite"
        and FileExists(GetCanonicalDatabasePath())
    if state.database_startup_test.enabled then
        QueueCanonicalUserDataSQL(
            BuildCanonicalUsageRetentionSQL(
                USAGE_RECENT_RETENTION_LIMIT,
                USAGE_MOST_USED_RETENTION_LIMIT,
                USAGE_RETENTION_PRUNE_THRESHOLD),
            "usage_retention:startup")
        LoadMediaUserTags()
        LoadClassificationOverrides()
        LoadKeyOverrides()
        -- Do not hydrate the complete historical metadata table into Lua at
        -- launch. This can be millions of rows and was the measured source
        -- of 15-second startup stalls. Metadata is queried lazily by the
        -- browser/tag paths instead.
        -- Favorites are already represented by the SQL-backed collection
        -- metadata and on-demand membership cache. Avoid hydrating direct
        -- favorite files at launch; that cost must stay independent of the
        -- size of a user's Favorites set.
        local browser = state.canonical_browser
        browser.history = {}
        browser.current_folder_id = nil
        browser.current_name = "Library"
        browser.current_path = nil
        state.selected_folder_scope = nil
        browser.offset = 0
        browser.selected_path = nil
        BuildFavoriteTree(true, true)
        RepairConfiguredRootsFromCanonicalDatabase()
        LoadCanonicalAccordionRoots()
        -- Launch only after every synchronous startup read, including the root
        -- accordion load, has finished. Starting before that final query can
        -- starve the Lua owner heartbeat long enough for a healthy new worker
        -- to terminate itself as an apparent orphan before the UI loop resumes.
        database.worker_prewarm_requested = false
        EnsureDatabaseWorkerStarted(GetCanonicalDatabasePath())
    else
        LoadMediaUserTags()
        -- SQLite is the only supported Library backend. Never make an old,
        -- incomplete cache look like a usable library after database startup
        -- fails; keep the configured root settings intact for a later retry.
        state.folder_tree = {}
        state.canonical_browser.rows = {}
        state.canonical_browser.accordion_error = database.error
            or database.status or "The ReaBrowse SQLite database is unavailable."
    end
end

Init()
